/**
 * @fileoverview View models of the watch page: the CoW button wrapper that
 * menus stamp for `buttonViewModel`, the segmented like and dislike button
 * of the video actions, and the rolling number of the view count and date.
 */
import {classes} from '../../framework/vm/classes.js';
import {IndexEach, cond} from '../../framework/vm/control.js';
import {afterRenderEffect, computed, runUntracked, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';
import {flag} from '../../framework/flags.js';
import {getText} from '../../framework/text.js';
import {AttributedString} from './attributed-string.js';
import {ButtonViewModel, LikeButtonViewModel} from './buttons.js';
import {LightShape} from './primitives.js';

/**
 * Unwraps a like or dislike button model that wraps itself.
 * @param {?Object|undefined} vm
 * @param {string} key
 * @return {?Object}
 */
function unwrapSelf(vm, key) {
  let v = vm || null;
  while (v && v[key]) v = v[key];
  return v;
}

/** The CoW wrapper around a button view model (`yt-button-view-model`). */
const ButtonViewModelWrapper = defineComponent((props) => h('ytl-yt-button-view-model', {class: 'ytlButtonViewModelWrapperHost'},
  h(ButtonViewModel, {data: props.data, overrides: props.buttonOverrides})), 'yt-button-view-model (CoW)');

defineCoW('ytl-yt-button-view-model', ButtonViewModelWrapper, {props: {data: PropKind.SIGNAL, buttonOverrides: PropKind.SIGNAL}});

/**
 * The segmented like and dislike button: two toggle buttons in one
 * smartimation container, with the like count from its entity.
 */
const SegmentedLikeDislike = defineComponent((props) => {
  const vm = () => /** @type {!Object} */ (unwrap(props.data) || {});
  const like = computed(() => unwrapSelf(vm().likeButtonViewModel, 'likeButtonViewModel'), undefined, 'segmentedLike');
  const dislike = computed(() => unwrapSelf(vm().dislikeButtonViewModel, 'dislikeButtonViewModel'), undefined, 'segmentedDislike');
  const likeCount = computed(() => {
    const entity = vm().likeCountEntity;
    return (entity && (entity.likeCountIfIndifferent || entity.expandedLikeCountIfIndifferent)) || '';
  }, undefined, 'segmentedLikeCount');
  const teasers = () => !!vm().teasersOrderEntityKey && !flag('disable_like_teasers');
  return h('ytl-segmented-like-dislike-button-view-model', {
    class: classes('ytlSegmentedLikeDislikeButtonViewModelHost', {'ytlSegmentedLikeDislikeButtonViewModelHasTeasers': teasers}),
    'data-like-count': likeCount,
  },
  h('ytl-smartimation', {class: 'ytlSmartimationHost'},
    h('div', {class: 'ytlSegmentedLikeDislikeButtonViewModelSegmentedButtonsWrapper'},
      h(LikeButtonViewModel, {data: like, kind: 'like'}),
      h(LikeButtonViewModel, {data: dislike, kind: 'dislike'})),
    h(LightShape, {variant: () => 'Tonal', disableStatic: () => true})));
}, 'segmented-like-dislike-button-view-model (CoW)');

defineCoW('ytl-segmented-like-dislike-button-view-model', SegmentedLikeDislike, {props: {data: PropKind.SIGNAL,
  buttonOverrides: PropKind.SIGNAL, isMinimized: PropKind.SIGNAL}});

/**
 * A number that rolls its digits into place: one column per character.
 */
const RollingNumber = defineComponent((props) => {
  const chars = computed(() => String(unwrap(props.numberText) || '').split(''), undefined, 'rollingChars');
  return h('ytl-animated-rolling-number', {class: 'ytlAnimatedRollingNumberHost', 'aria-label': () => unwrap(props.numberText) || ''},
    h(IndexEach, {of: chars, render: (c) => h('div', {class: () => (/\d/.test(String(c())) ? 'ytlAnimatedRollingNumberDigit' :
      'ytlAnimatedRollingNumberChar')}, () => String(c()))}));
}, 'yt-animated-rolling-number (CoW)');

defineCoW('ytl-animated-rolling-number', RollingNumber, {props: {className: PropKind.SIGNAL, numberText: PropKind.SIGNAL, numberValue: PropKind.SIGNAL, heightPx: PropKind.SIGNAL,
  fontSizeMultiplier: PropKind.SIGNAL, shouldAnimate: PropKind.SIGNAL, forceRollUp: PropKind.SIGNAL, rollFromNumberText: PropKind.SIGNAL,
  rollFromNumberValue: PropKind.SIGNAL}});

/**
 * The schema.org description of the video that the player response's
 * microformat gives (`MmF`), or null when its title, publish date or
 * thumbnail is missing.
 * @param {!Object} data
 * @return {?string}
 */
function videoObjectJson(data) {
  const title = getText(data.title).trim();
  const thumbnails = data.thumbnail && data.thumbnail.thumbnails;
  const image = thumbnails && thumbnails.length ? String(thumbnails[0].url || '').trim() : '';
  const published = String(data.publishDate || '').trim();
  if (!title || !published || !image) return null;
  return JSON.stringify({
    '@context': 'http://schema.org',
    '@type': 'VideoObject',
    'name': title,
    'description': getText(data.description),
    'thumbnailUrl': [image],
    'uploadDate': published,
    'duration': `PT${Math.floor(Number(data.lengthSeconds || 0) / 60)}M${Number(data.lengthSeconds || 0) % 60}S`,
    'embedUrl': data.embed && data.embed.iframeUrl,
    'genre': data.category,
    'interactionCount': data.viewCount,
    'author': data.ownerChannelName,
  }).replace(/</g, '\\u003C');
}

/** The structured data of the watch page's video (`player-microformat-renderer`). */
const PlayerMicroformat = defineComponent((props) => h('ytl-player-microformat-renderer', {class: 'ytlPlayerMicroformatRendererHost'},
  h('script', {type: 'application/ld+json', ref: (el) => {
    afterRenderEffect(() => {
      const json = videoObjectJson(/** @type {!Object} */ (unwrap(props.data) || {}));
      runUntracked(() => {
        if (json) el.textContent = json;
      });
    }, 'C6lE0');
  }})), 'player-microformat-renderer (CoW)');

defineCoW('ytl-player-microformat-renderer', PlayerMicroformat, {props: {data: PropKind.SIGNAL}});

/**
 * The "how this was made" section of the structured description
 * (`how-this-was-made-section-view-model`): a title, the body's header and
 * text, and an optional attribution.
 */
const HowThisWasMade = defineComponent((props) => {
  const data = () => /** @type {!Object} */ (unwrap(props.data) || {});
  return h('ytl-how-this-was-made-section-view-model', {
    class: classes('ytwHowThisWasMadeSectionViewModelHost', {
      'ytwHowThisWasMadeSectionViewModelCompact': () => data().style === 'HOW_THIS_WAS_MADE_SECTION_STYLE_COMPACT',
    }),
    tabindex: -1,
  },
  h('div', {class: classes('ytwHowThisWasMadeSectionViewModelSectionTitle', {
    'ytwHowThisWasMadeSectionViewModelSectionTitleRedesign': () => flag('web_typography_changes_sd_redesign') && !!unwrap(props.inStructuredDescription),
  })}, h(AttributedString, {text: () => data().sectionTitle})),
  h('div', {class: 'ytwHowThisWasMadeSectionViewModelBodyHeader'}, h(AttributedString, {text: () => data().bodyHeader})),
  h('div', {class: 'ytwHowThisWasMadeSectionViewModelBodyText'}, h(AttributedString, {text: () => data().bodyText})),
  cond(() => !!data().attributionText, () => h('div', {class: 'ytwHowThisWasMadeSectionViewModelAttributionText'},
    h(AttributedString, {text: () => data().attributionText}))));
}, 'how-this-was-made-section-view-model (CoW)');

defineCoW('ytl-how-this-was-made-section-view-model', HowThisWasMade, {props: {data: PropKind.SIGNAL, inStructuredDescription: PropKind.SIGNAL}});
