/**
 * @fileoverview Adaptations of iron behaviours to PolySi. The resizable
 * behaviour subscribes to `iron-resize` on the host of a controller that
 * it is told about. Per instance, behaviour methods keep running on the
 * controller; the ones that compare an event target with the element
 * compare it with the host instead.
 */
import {IronResizableBehavior} from '@polymer/iron-resizable-behavior/iron-resizable-behavior.js';
import {dom} from '@polymer/polymer/lib/legacy/polymer.dom.js';

/**
 * @param {!Object} target
 * @return {!EventTarget}
 */
function hostOf(target) {
  const host = target.hostElement;
  return host != null ? host : target;
}

/** @this {!Object} */
IronResizableBehavior._subscribeIronResize = function(target) {
  hostOf(target).addEventListener('iron-resize', this._boundOnDescendantIronResize);
};

/** @this {!Object} */
IronResizableBehavior._unsubscribeIronResize = function(target) {
  hostOf(target).removeEventListener('iron-resize', this._boundOnDescendantIronResize);
};

/**
 * Per-instance rewrites of iron behaviour methods for a PolySi controller,
 * which is not in the DOM: run from the first behaviour's `created`.
 * @param {!Object} ctrl
 */
export function adaptIronBehaviors(ctrl) {
  if (ctrl._onIronRequestResizeNotifications) {
    const original = ctrl._onIronRequestResizeNotifications.bind(ctrl);
    ctrl._onIronRequestResizeNotifications = (event) => {
      if (dom(event).rootTarget !== ctrl.hostElement) original(event);
    };
  }
  if (ctrl._ariaActiveAttributeChanged) ctrl._ariaActiveAttributeChanged = ctrl._ariaActiveAttributeChanged.bind(ctrl.hostElement);
  if (ctrl._activeChanged) {
    ctrl._activeChanged = (active) => {
      if (ctrl.toggles) setSerializedAttribute(ctrl.hostElement, active ? 'true' : 'false', ctrl.ariaActiveAttribute);
      else ctrl.hostElement.removeAttribute(ctrl.ariaActiveAttribute);
      ctrl._changedButtonState();
    };
  }
  if (ctrl._asyncClick) {
    ctrl._asyncClick = () => {
      setTimeout(() => {
        ctrl.hostElement.click();
      }, 1);
    };
  }
  if (ctrl.keyEventTarget && !(ctrl.keyEventTarget instanceof EventTarget)) ctrl.keyEventTarget = hostOf(ctrl.keyEventTarget);
  if (ctrl._disabledChanged) ctrl._disabledChanged = ctrl._disabledChanged.bind(ctrl.hostElement);
}

/**
 * Sets `name` on `el` to `value` serialized as Polymer serializes
 * attributes, or removes it for `undefined`.
 * @param {!Element} el
 * @param {*} value
 * @param {string} name
 */
function setSerializedAttribute(el, value, name) {
  let str;
  switch (typeof value) {
    case 'object':
    case 'function':
      if (value instanceof Date) str = value.toString();
      else if (value) str = JSON.stringify(value);
      break;
    case 'boolean':
      str = value ? '' : undefined;
      break;
    default:
      str = value != null ? String(value) : undefined;
  }
  if (str === undefined) el.removeAttribute(name);
  else el.setAttribute(name, str);
}
