/**
 * @fileoverview Control-flow components of the view-model runtime: `cond`,
 * `switch`, keyed and index `each`, and the renderer-type switch. They are
 * not components: they take their props as given, open no span and have
 * no frame. Each evaluation of a branch or item runs in a new owner. Their
 * region effects count as renders, so the effects they queue are flushed
 * when the outermost render ends.
 */
import {noteBreakdown} from './counters.js';
import {asRender, computed, getFrame, renderEffect, runUntracked, signal} from './effect.js';
import {h} from './jsx.js';
import {createDetachedOwner, createOwner, disposeOwner, getOwner, onCleanup, runWithOwner} from './owner.js';
import {Region, instantiate, removeNode} from './render.js';
import {flag} from '../flags.js';

/**
 * @param {*} value
 * @param {string} where
 * @return {*}
 */
function reportMissing(value, where) {
  if (value === undefined) console.warn(`${where}: branch returned no value`);
  return value;
}

/**
 * Renders a branch in a new owner under the current one (the region
 * effect) and places it in the region.
 * @param {!Region} region
 * @param {?function(): *} branch
 * @param {?string} ns
 * @param {string} where
 */
function renderBranch(region, branch, ns, where) {
  const owner = createOwner(getOwner());
  const nodes = [];
  if (branch) runWithOwner(owner, () => instantiate(reportMissing(branch(), where), ns, nodes));
  region.place(nodes);
}

/**
 * `cond` (`bcj`): one truthiness computed and one region effect.
 * @param {{when: function(): *, then: (function(): *|undefined), else: (function(): *|undefined),
 *     debugInstance: (string|undefined)}} props
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
export function Cond(props, ns, out) {
  noteBreakdown('conds', getFrame());
  const when = props.when;
  const truthy = computed(() => !!when(), undefined, 'BjQRQ');
  const region = new Region();
  renderEffect(() => {
    const show = truthy();
    runUntracked(() => asRender(() => renderBranch(region, show ? props.then || null : props.else || null, ns, 'cond')));
  }, props.debugInstance || 'RlDudd');
  region.appendTo(out);
}
Cond.isControl = true;

/**
 * @param {function(): *} when
 * @param {function(): *} then
 * @param {(function(): *)=} otherwise
 * @param {string=} debugInstance
 * @return {!Object}
 */
export function cond(when, then, otherwise, debugInstance) {
  return h(Cond, {when, then, else: otherwise, debugInstance});
}

/**
 * `switch` (`RGu`): a computed of the index of the first matching case and
 * one region effect. A case matches when it equals the value, or when it is
 * a function that returns true for it.
 * @param {{value: function(): *, cases: !Array<!Array<*>>, fallback: (function(): *|undefined)}} props
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
export function Switch(props, ns, out) {
  const cases = props.cases;
  const index = computed(() => {
    const v = props.value();
    for (let i = 0; i < cases.length; i++) {
      const match = cases[i][0];
      if (typeof match === 'function' ? match(v) : match === v) return i;
    }
    return -1;
  }, undefined, 'MSTxWb');
  const region = new Region();
  renderEffect(() => {
    const i = index();
    runUntracked(() => asRender(() => renderBranch(region, i >= 0 ? /** @type {function(): *} */ (cases[i][1]) : props.fallback || null, ns, 'switch')));
  }, 'vI1rtf');
  region.appendTo(out);
}
Switch.isControl = true;

/**
 * @param {function(): *} value
 * @param {!Array<!Array<*>>} cases
 * @param {(function(): *)=} fallback
 * @return {!Object}
 */
export function switchOn(value, cases, fallback) {
  return h(Switch, {value, cases, fallback});
}

/**
 * @typedef {{key: *, owner: !Object, nodes: !Array<!Node>, item: function(): *, setItem: ?function(*),
 *     index: ?function(): number, setIndex: ?function(number)}}
 */
let EachEntry;

/**
 * Keyed `each` (`Cs8`): one region effect and one cleanup; per item an
 * owner, an index signal unless `noIndex`, and an item signal unless the
 * key is the item itself. Items that keep their key are reused; the diff
 * skips the common head and tail, then matches keys through a multimap.
 * @param {{of: function(): ?Array<*>, key: (function(*, number): *|undefined), noIndex: (boolean|undefined),
 *     render: function(function(): *, ?function(): number): *}} props
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
export function Each(props, ns, out) {
  noteBreakdown('eachs', getFrame());
  const region = new Region();
  const byReference = !props.key;
  /** @type {!Array<!EachEntry>} */
  let entries = [];
  const makeEntry = (item, i, key) => {
    const owner = createDetachedOwner(getOwner());
    let itemGet, setItem = null, indexGet = null, setIndex = null;
    if (byReference) {
      itemGet = () => item;
    } else {
      [itemGet, setItem] = signal(item, 'N6Pkbd');
    }
    if (!props.noIndex) [indexGet, setIndex] = signal(i, 'auo2q');
    const nodes = [];
    runWithOwner(owner, () => instantiate(props.render(itemGet, indexGet), ns, nodes));
    return {key, owner, nodes, item: itemGet, setItem, index: indexGet, setIndex};
  };
  renderEffect(() => {
    const items = props.of() || [];
    runUntracked(() => asRender(() => {
      const keyOf = props.key || ((item) => item);
      const next = new Array(items.length);
      let head = 0;
      while (head < items.length && head < entries.length && entries[head].key === keyOf(items[head], head)) {
        updateEntry(entries[head], items[head], head);
        next[head] = entries[head];
        head++;
      }
      let oldTail = entries.length - 1;
      let newTail = items.length - 1;
      while (newTail >= head && oldTail >= head && entries[oldTail].key === keyOf(items[newTail], newTail)) {
        updateEntry(entries[oldTail], items[newTail], newTail);
        next[newTail] = entries[oldTail];
        oldTail--;
        newTail--;
      }
      /** @type {!Map<*, !Array<!EachEntry>>} */
      const pool = new Map();
      for (let i = head; i <= oldTail; i++) {
        const list = pool.get(entries[i].key);
        if (list) list.push(entries[i]);
        else pool.set(entries[i].key, [entries[i]]);
      }
      /** @type {!Set<!EachEntry>} */
      const reused = new Set();
      for (let i = head; i <= newTail; i++) {
        const key = keyOf(items[i], i);
        const list = pool.get(key);
        const entry = list && list.length ? list.shift() : null;
        if (entry) {
          updateEntry(entry, items[i], i);
          reused.add(entry);
          next[i] = entry;
        } else {
          next[i] = makeEntry(items[i], i, key);
        }
      }
      for (let i = head; i <= oldTail; i++) {
        const entry = entries[i];
        if (!reused.has(entry)) {
          disposeOwner(entry.owner);
          for (const n of entry.nodes) removeNode(n);
        }
      }
      entries = next;
      const nodes = [];
      for (const entry of entries) {
        for (const n of entry.nodes) nodes.push(n);
      }
      region.place(nodes);
    }));
  }, 'nsTGHd');
  region.appendTo(out);
  onCleanup(() => {
    for (const entry of entries) disposeOwner(entry.owner);
  });
}
Each.isControl = true;

/**
 * @param {!EachEntry} entry
 * @param {*} item
 * @param {number} i
 */
function updateEntry(entry, item, i) {
  if (entry.setItem && entry.item() !== item) entry.setItem(item);
  if (entry.setIndex && entry.index() !== i) entry.setIndex(i);
}

/**
 * Index `each` (`LUK`): one cleanup and one region effect; per position an
 * owner and an item signal. Positions keep their nodes; their item signals change.
 * @param {{of: function(): ?Array<*>, render: function(function(): *, number): *}} props
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
export function IndexEach(props, ns, out) {
  noteBreakdown('eachs', getFrame());
  const region = new Region();
  /** @type {!Array<{owner: !Object, nodes: !Array<!Node>, setItem: function(*), item: function(): *}>} */
  let slots = [];
  onCleanup(() => {
    for (const slot of slots) disposeOwner(slot.owner);
  });
  renderEffect(() => {
    const items = props.of() || [];
    runUntracked(() => asRender(() => {
      for (let i = 0; i < items.length; i++) {
        if (i < slots.length) {
          if (slots[i].item() !== items[i]) slots[i].setItem(items[i]);
          continue;
        }
        const owner = createDetachedOwner(getOwner());
        const [item, setItem] = signal(items[i], 'A9LfFc');
        const nodes = [];
        runWithOwner(owner, () => instantiate(props.render(item, i), ns, nodes));
        slots.push({owner, nodes, setItem, item});
      }
      for (let i = items.length; i < slots.length; i++) {
        disposeOwner(slots[i].owner);
        for (const n of slots[i].nodes) removeNode(n);
      }
      slots.length = Math.min(slots.length, items.length);
      const nodes = [];
      for (const slot of slots) {
        for (const n of slot.nodes) nodes.push(n);
      }
      region.place(nodes);
    }));
  }, 'nsTGHd');
  region.appendTo(out);
}
IndexEach.isControl = true;

/**
 * The first key of a renderer object.
 * @param {*} item
 * @return {string}
 */
export function rendererKey(item) {
  if (!item || typeof item !== 'object') return '';
  for (const key in item) return key;
  return '';
}

/**
 * The component of a renderer-type switch entry: a Wiz component as it is,
 * or, per item, a plain component that calls the render function with the
 * item's props and index thunk, named after its key.
 * @param {function(?, ?): *} entry
 * @param {string} key
 * @param {?function(): number} index
 * @return {?}
 */
function rendererComponent(entry, key, index) {
  const e = /** @type {?} */ (entry);
  if (e.isWizComponent || e.isPlainComponent) return entry;
  const item = /** @type {?} */ ((props) => entry(props, index));
  item.isPlainComponent = true;
  item.debugName = e.debugName || key;
  return item;
}

/**
 * The renderer-type switch (`_.Dv`), a plain component: a pending signal
 * and a `cond` around an `each` over the renderer objects' keys. Each object is
 * rendered by the entry mapped to its first key, as a component whose
 * `data` is a computed of the object's value. Keys without an entry render
 * `fallback`, or an empty comment.
 * @param {!Object} props
 * @return {!Object}
 */
function RendererSwitch(props) {
  const [ready] = signal(true, 'bKtO6d');
  const mapping = props.mapping;
  const extra = props.extraProps;
  const fallback = props.fallback;
  const wrapper = props.wrapper;
  const items = props.items;
  const each = h(Each, {
    of: () => items().map(rendererKey),
    render: (itemKey, index) => {
      const key = itemKey();
      const entry = mapping[key];
      const data = computed(() => {
        const v = items()[index ? index() : 0];
        return v ? v[key] : undefined;
      }, undefined, 'sErtjd');
      if (!entry) return fallback ? h(fallback, {data}) : document.createComment('');
      flag('web_enable_renderer_logger');
      const component = rendererComponent(entry, key, index);
      const itemProps = extra ? Object.assign({data}, extra) : {data};
      return wrapper ? wrapper(() => h(component, itemProps), index) : h(component, itemProps);
    },
  });
  return h(Cond, {when: ready, then: () => each, else: props.pendingFallback});
}
RendererSwitch.isPlainComponent = true;
RendererSwitch.debugName = 'J_F';

/**
 * @param {function(): ?Array<*>} items
 * @param {!Object<string, function(?, ?function(): number): *>} mapping
 * @param {(function(?): *)=} fallback
 * @param {?Object=} extraProps
 * @param {(function(function(): *, ?function(): number): *)=} wrapper Called with a
 *     thunk of the rendered item and its index.
 * @return {!Object}
 */
export function renderers(items, mapping, fallback, extraProps, wrapper) {
  return h(RendererSwitch, {items, mapping, fallback, extraProps: extraProps || undefined, wrapper});
}
