/**
 * @fileoverview The thumbnail view model (`ytl-thumbnail-view-model`, inert
 * inside lockups) and its overlays: overlay badges, the bottom overlay
 * with its progress bar, and overlay buttons. The thumbnail renders the
 * image through a `switch`, and its overlays, badges and bottom overlay
 * through three `each`es.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {cond} from '../../framework/vm/control.js';
import {afterRenderEffect, computed, onInitUntracked, runUntracked, signal, unwrap, watchAfterRender} from '../../framework/vm/effect.js';
import {RendererToken, contextLabel, rendererField, rendererOf, thumbnailSizeName, useSelector} from './hooks.js';
import {rootInjector} from '../../framework/injector.js';
import {flag} from '../../framework/flags.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {defineViewModelElement} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';
import {BadgeShape} from './badges.js';
import {Image} from './image.js';
import {ButtonViewModel} from './buttons.js';

/**
 * Unwraps `{thumbnailViewModel: {...}}` nesting.
 * @param {?Object|undefined} vm
 * @return {!Object}
 */
export function unwrapThumbnail(vm) {
  let v = vm || {};
  while (v.thumbnailViewModel) v = v.thumbnailViewModel;
  return v;
}

/**
 * @param {string|undefined} position
 * @return {string}
 */
function badgePositionClass(position) {
  switch (position) {
    case 'THUMBNAIL_OVERLAY_BADGE_POSITION_TOP_START':
      return 'ytlThumbnailOverlayBadgeViewModelTopStart';
    default:
      return 'ytlThumbnailOverlayBadgeViewModelBottomEnd';
  }
}

/**
 * Size class of an overlay badge by thumbnail size.
 * @param {string|undefined} size
 * @return {string}
 */
function badgeSizeClass(size) {
  switch (size) {
    case 'small':
      return 'ytlThumbnailOverlayBadgeViewModelSmall';
    case 'large':
      return 'ytlThumbnailOverlayBadgeViewModelLarge';
    default:
      return 'ytlThumbnailOverlayBadgeViewModelMedium';
  }
}

/**
 * Badge-shape type of a thumbnail badge style.
 * @param {string|undefined} style
 * @param {boolean} activated
 * @return {string}
 */
function thumbnailBadgeType(style, activated) {
  if (activated) return 'THUMBNAIL_OVERLAY_BADGE_STYLE_DEFAULT';
  switch (style) {
    case 'THUMBNAIL_OVERLAY_BADGE_STYLE_LIVE':
      return 'THUMBNAIL_OVERLAY_BADGE_STYLE_LIVE';
    case 'THUMBNAIL_OVERLAY_BADGE_STYLE_SPECIAL':
      return 'THUMBNAIL_OVERLAY_BADGE_STYLE_SPECIAL';
    default:
      return 'THUMBNAIL_OVERLAY_BADGE_STYLE_DEFAULT';
  }
}

/**
 * Whether an animated thumbnail badge is activated: its selector watches the
 * player, and the player plays its video in the miniplayer.
 * @param {?Object} vm
 * @param {?Object} player
 * @return {?{activated: boolean, playAnimation: boolean}}
 */
function badgeActivation(vm, player) {
  const target = vm && vm.animationActivationTargetId;
  const key = (vm && vm.animationActivationEntityKey) || '';
  if (!target || !key) return null;
  switch (vm.animationActivationEntitySelectorType) {
    case 'THUMBNAIL_BADGE_ANIMATION_ENTITY_SELECTOR_TYPE_PLAYER_STATE': {
      const activated = !!(player && player.videoId === target && player.miniplayer);
      return {activated, playAnimation: activated && player.playerState === 'PLAYER_STATE_PLAYING'};
    }
    default:
      return null;
  }
}

/**
 * The badge-shape config of a thumbnail badge, or undefined when it has
 * nothing to show.
 * @param {?Object} vm
 * @param {?{activated: boolean}} activation
 * @return {!Object|undefined}
 */
function thumbnailBadgeConfig(vm, activation) {
  if (!vm) return undefined;
  const activated = !!(activation && activation.activated);
  const icon = vm.icon && vm.icon.sources && vm.icon.sources[0] && vm.icon.sources[0].clientResource;
  if (!vm.text && !icon && !activated) return undefined;
  const label = contextLabel(vm.rendererContext);
  return {
    badgeStyle: thumbnailBadgeType(vm.badgeStyle, activated),
    text: activated && vm.animatedText ? vm.animatedText : vm.text || '',
    icon: icon ? icon.imageName : '',
    thumbnail: true,
    backgroundColor: vm.backgroundColor && vm.backgroundColor.lightTheme ? vm.backgroundColor : null,
    label: label || vm.text || '',
    animatedText: activated && vm.lottieData ? vm.animatedText || '' : '',
  };
}

/** A thumbnail badge: a badge shape when there is something to show. */
export const ThumbnailBadge = defineComponent((props) => {
  const vm = () => unwrap(props.data) || null;
  const player = useSelector((state) => state.watch);
  const activation = computed(() => badgeActivation(vm(), player()), undefined, 'thumbnailBadgeActivation');
  afterRenderEffect(() => {
    const a = activation();
    runUntracked(() => {
      if (a && a.activated && host) host.toggleAttribute('playing', a.playAnimation);
    });
  }, 'pqG3X');
  /** @type {?Element} */
  let host = null;
  const config = () => thumbnailBadgeConfig(vm(), activation());
  return h('ytl-thumbnail-badge-view-model', {
    class: classes('ytlThumbnailBadgeViewModelHost', () => unwrap(props.className) || ''),
    ref: (/** !Element */ el) => {
      host = el;
    },
  }, cond(config, () => h(BadgeShape, {data: config})));
}, 'di');

/** The overlay badges of a thumbnail. */
export const ThumbnailOverlayBadge = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  return h('ytl-thumbnail-overlay-badge-view-model', {
    class: classes('ytlThumbnailOverlayBadgeViewModelHost', () => badgePositionClass(vm().position),
        () => badgeSizeClass(unwrap(props.thumbnailSize)), {'ytlThumbnailOverlayBadgeViewModelClip': () => !!unwrap(props.isClip)}),
  }, rendererOf(() => vm().thumbnailBadges, {'thumbnailBadgeViewModel': (r) => h(ThumbnailBadge, {data: r.data,
    className: 'ytlThumbnailOverlayBadgeViewModelBadge'})}));
}, 'ytl-thumbnail-overlay-badge-view-model (CoW)');

/** The watched-progress bar. */
export const ProgressBar = defineComponent((props) => h('ytl-thumbnail-overlay-progress-bar-view-model', {
  class: 'ytlThumbnailOverlayProgressBarHost ytlThumbnailOverlayProgressBarHostMedium',
}, h('div', {class: 'ytlThumbnailOverlayProgressBarHostWatchedProgressBar'},
  h('div', {class: 'ytlThumbnailOverlayProgressBarHostWatchedProgressBarSegment', style: styles({width: () => `${props.percent()}%`})}))),
'ytl-thumbnail-overlay-progress-bar-view-model (CoW)');

/**
 * @param {string|undefined} size
 * @return {string}
 */
function bottomOverlaySizeClass(size) {
  switch (size) {
    case 'small':
      return 'ytlThumbnailBottomOverlayViewModelBadgeContainerSmall';
    case 'large':
      return 'ytlThumbnailBottomOverlayViewModelBadgeContainerLarge';
    default:
      return 'ytlThumbnailBottomOverlayViewModelBadgeContainerMedium';
  }
}

/** The bottom overlay (`U2q`): a renderer switch for the progress bar, and one each for the badge and the badges. */
export const ThumbnailBottomOverlay = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const badge = {'thumbnailBadgeViewModel': (r) => h(ThumbnailBadge, {data: r.data, className: 'ytlThumbnailBottomOverlayViewModelBadge'})};
  return h('ytl-thumbnail-bottom-overlay-view-model', {
    class: classes('ytlThumbnailBottomOverlayViewModelHost', {'ytlThumbnailBottomOverlayViewModelHostBackground': () => vm().enableGradientBackground}),
  },
  rendererOf(() => vm().progressBar, {
    'thumbnailOverlayProgressBarViewModel': (r) => h(ProgressBar, {percent: () => (r.data() || {}).startPercent || 0}),
  }),
  h('div', {class: classes('ytlThumbnailBottomOverlayViewModelBadgeContainer', () => bottomOverlaySizeClass(unwrap(props.thumbnailSize)), {
    'ytlThumbnailBottomOverlayViewModelBadgeContainerClip': props.isClip,
    'ytlThumbnailBottomOverlayViewModelBadgeContainerSmallLegacy': () => !flag('web_enable_modern_progress_bar_overlay') && unwrap(props.thumbnailSize) === 'small',
  })}, rendererOf(() => vm().badge, badge), rendererOf(() => vm().badges, badge)));
}, 'ytl-thumbnail-bottom-overlay-view-model (CoW)');

/**
 * @param {string|undefined} position
 * @return {string}
 */
function overlayButtonPositionClass(position) {
  switch (position) {
    case 'THUMBNAIL_OVERLAY_BUTTON_POSITION_TOP_END':
      return 'ytlThumbnailOverlayButtonViewModelButtonTopEndPosition';
    default:
      return 'ytlThumbnailOverlayButtonViewModelButtonBottomEndPosition';
  }
}

/** The button overrides of an overlay button with the legacy icon size. */
const LEGACY_OVERLAY_BUTTON = {iconPosition: 'icon-only-40', customColors: {backgroundColor: 'rgba(0,0,0,0.6)'}, ariaHidden: true,
  tabIndex: -1};

/** An overlay button on a thumbnail. */
export const ThumbnailOverlayButton = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const legacy = () => {
    const e = unwrap(props.lockupExperiments);
    return !!(e && e.useLegacySizedIconButton);
  };
  return h('ytl-thumbnail-overlay-button-view-model', {class: 'ytlThumbnailOverlayButtonViewModelHost'},
    h('div', {class: classes('ytlThumbnailOverlayButtonViewModelButtonContainer', () => overlayButtonPositionClass(vm().position),
        {'ytlThumbnailOverlayButtonViewModelButtonLegacyIcon': legacy})},
    rendererOf(() => vm().overlayButtons || vm().overlayButton, {
      'buttonViewModel': (r) => h(ButtonViewModel, {data: r.data, overrides: () => (legacy() ? LEGACY_OVERLAY_BUTTON : undefined)}),
    }, (node) => h('div', {class: 'ytlThumbnailOverlayButtonViewModelButton'}, node()))));
}, 'ytl-thumbnail-overlay-button-view-model (CoW)');

export const HoverOverlay = defineComponent((props) => h('ytl-thumbnail-hover-overlay-view-model', {
  class: 'ytlThumbnailHoverOverlayViewModelHost',
}), 'ytl-thumbnail-hover-overlay-view-model (CoW)');

/**
 * The aspect-ratio index of a thumbnail: 0 for 16:9, 1 for 2:3, 3 for 1:1,
 * 4 for 9:16.
 * @param {*} aspect A number, or a shelf or thumbnail aspect enum.
 * @return {number}
 */
function aspectIndexOf(aspect) {
  if (typeof aspect === 'number') return aspect;
  switch (aspect) {
    case 'GRID_SHELF_CONTENT_ASPECT_RATIO_TWO_BY_THREE':
    case 'THUMBNAIL_ASPECT_RATIO_TWO_BY_THREE':
      return 1;
    case 'RENDERING_ASPECT_SQUARE':
    case 'THUMBNAIL_ASPECT_RATIO_SQUARE':
      return 3;
    default:
      return 0;
  }
}

/**
 * The aspect-ratio class of a thumbnail.
 * @param {number} index
 * @return {string}
 */
function aspectClassOf(index) {
  switch (index) {
    case 1:
      return 'ytlThumbnailViewModelAspectRatio2By3';
    case 3:
      return 'ytlThumbnailViewModelAspectRatio1By1';
    case 4:
      return 'ytlThumbnailViewModelAspectRatio9By16';
    default:
      return 'ytlThumbnailViewModelAspectRatio16By9';
  }
}

/**
 * The size class of a thumbnail, unless rounding is off.
 * @param {string} size
 * @param {boolean} noRounding
 * @return {string|undefined}
 */
function thumbnailSizeClass(size, noRounding) {
  if (noRounding) return undefined;
  switch (size) {
    case 'large':
      return 'ytlThumbnailViewModelLarge';
    case 'small':
      return 'ytlThumbnailViewModelSmall';
    default:
      return 'ytlThumbnailViewModelMedium';
  }
}

/**
 * Width over height of an image's first source.
 * @param {?Object} image
 * @return {number}
 */
function imageAspect(image) {
  const s = image && image.sources && image.sources[0];
  return s && s.width && s.height ? s.width / s.height : 0;
}

/**
 * An ARGB colour with a new alpha, as CSS.
 * @param {number} argb
 * @param {string} alpha
 * @return {string}
 */
function withAlpha(argb, alpha) {
  return `rgba(${(argb >>> 16) & 255}, ${(argb >>> 8) & 255}, ${argb & 255}, ${alpha})`;
}

/** The animated overlay, which replaces the other overlays while a small thumbnail is hovered. */
const ANIMATED_OVERLAY = new RendererToken('animatedThumbnailOverlayViewModel');

/** The injection token of an image-load listener of thumbnails. */
export const THUMBNAIL_LOAD_LISTENER = {name: 'THUMBNAIL_LOAD_LISTENER_TOKEN'};

/**
 * The thumbnail view model (`_.zH`): the image (blurred behind for
 * cinematic thumbnails), then three renderer switches for the overlays,
 * the hover overlays and the animated overlay, and the clip pinking.
 */
export const ThumbnailViewModel = defineComponent((props) => {
  const log = [];
  const vm = () => unwrapThumbnail(unwrap(props.data));
  const size = () => thumbnailSizeName(unwrap(props.width), unwrap(props.height));
  const onLoadListener = /** @type {?function(!Element)} */ (rootInjector.resolve(THUMBNAIL_LOAD_LISTENER));
  /** @type {?Element} */
  let host = null;
  const ref = (/** !Element */ el) => {
    host = el;
    log.push('elRef.value set');
    const playback = props.playbackRef;
    if (typeof playback === 'function') playback({thumbnailElRef: el, thumbnail: vm().image, thumbnailOverlays: vm().overlays, thumbnailSize: size()});
  };
  onInitUntracked(() => {
    log.push('onInit');
    onCleanup(() => log.push('onCleanup'));
  });
  const animatedEnabled = useSelector((state) => !!state.ui.animatedThumbnailEnabled);
  const aspect = () => aspectIndexOf(unwrap(props.aspectRatio) !== undefined ? unwrap(props.aspectRatio) : unwrap(props.aspect));
  const cinematic = () => {
    const v = vm();
    const ratio = v.image ? imageAspect(v.image) : aspect();
    return v.triptych || !v.image ? false : ratio <= 1 && aspect() === 0;
  };
  const contentMode = () => (cinematic() ? 'IMAGE_CONTENT_MODE_SCALE_ASPECT_FIT' : 'IMAGE_CONTENT_MODE_SCALE_ASPECT_FILL');
  const onLoad = () => {
    if (!host) console.warn('Thumbnail elRef.value is null', log.join('\n'));
    if (onLoadListener && host) onLoadListener(host);
  };
  const [mouseOver, setMouseOver] = signal(false, 'oVjt2c');
  const [focusedIn, setFocusedIn] = signal(false, 'jpHFuc');
  const ownHover = () => unwrap(props.hovered) === undefined;
  const hovered = () => (ownHover() ? mouseOver() || focusedIn() : !!unwrap(props.hovered));
  const animatedOverlay = () => hovered() && size() !== 'large' &&
      (vm().overlays || []).some((o) => rendererField(o, ANIMATED_OVERLAY));
  const [everHovered, setEverHovered] = signal(false, 'Fmi8Me');
  watchAfterRender(hovered, (h) => {
    if (h) setEverHovered(true);
  });
  const image = () => h(Image, {data: () => vm().image, alt: '',
    contentMode: () => unwrap(props.contentMode) || contentMode(), objectPosition: props.thumbnailPosition, targetWidth: props.width, onLoad,
    imageClassificationType: props.imageClassificationType});
  return h('ytl-thumbnail-view-model', {
    class: classes('ytlThumbnailViewModelHost', () => unwrap(props.className) || '', () => aspectClassOf(aspect()),
        () => thumbnailSizeClass(size(), !!unwrap(props.disableRounding) || !!unwrap(props.isClip)),
        {'ytlThumbnailViewModelCinematic': cinematic}, {'ytlThumbnailViewModelHighlightEffect': () => {
          const e = unwrap(props.lockupExperiments);
          return !!(e && e.showHighlightEffect);
        }}),
    style: styles({'background-color': () => {
      const color = cinematic() && vm().backgroundColor ? vm().backgroundColor.lightTheme : undefined;
      return color ? withAlpha(color, '1') : undefined;
    }}),
    ref,
    'on:mouseenter': () => {
      if (ownHover()) setMouseOver(true);
    },
    'on:mouseleave': () => {
      if (!ownHover()) return;
      setMouseOver(false);
      const active = document.activeElement;
      if (!(active && host && host.contains(active) && active.matches(':focus-visible'))) setFocusedIn(false);
    },
    'on:focusin': (/** !Event */ e) => {
      if (ownHover() && /** @type {!Element} */ (e.target).matches(':focus-visible')) setFocusedIn(true);
    },
    'on:focusout': (/** !FocusEvent */ e) => {
      if (ownHover() && !(host && host.contains(/** @type {?Node} */ (e.relatedTarget)))) setFocusedIn(false);
    },
  },
  cond(cinematic, () => h('div', {class: 'ytlThumbnailViewModelBlurredImage'}, image())),
  h('div', {class: 'ytlThumbnailViewModelImage'}, cond(() => vm().triptych, () => h('div', {class: 'ytlThumbnailViewModelTriptych'}), image)),
  rendererOf(() => (animatedOverlay() ? undefined : vm().overlays), {
    'thumbnailOverlayBadgeViewModel': (r) => h(ThumbnailOverlayBadge, {data: r.data, thumbnailSize: size, isClip: props.isClip}),
    'thumbnailBottomOverlayViewModel': (r) => h(ThumbnailBottomOverlay, {data: r.data, thumbnailSize: size, isClip: props.isClip}),
    'thumbnailOverlayButtonViewModel': (r) => h(ThumbnailOverlayButton, {data: r.data, lockupExperiments: props.lockupExperiments}),
  }),
  rendererOf(() => (flag('always_render_thumbnail_overlay') || everHovered() ? vm().overlays : undefined), {
    'thumbnailHoverOverlayViewModel': (r) => h(HoverOverlay, {data: r.data, alwaysShow: hovered}),
  }),
  rendererOf(() => (hovered() && animatedEnabled() ? vm().overlays : undefined), {
    'animatedThumbnailOverlayViewModel': (r) => h('ytl-animated-thumbnail-overlay-view-model'),
  }),
  cond(() => !!unwrap(props.isClip), () => h('div', {class: 'ytlPinkingNsHost'})));
}, 'ytl-thumbnail-view-model (CoW)');

const BottomOverlayHost = defineComponent((props) => h('ytl-thumbnail-bottom-overlay-host', null,
  h(ThumbnailBottomOverlay, {data: props.data})), 'ytl-thumbnail-bottom-overlay-host (CoW)');

defineViewModelElement('ytl-thumbnail-bottom-overlay-host', BottomOverlayHost);
