/**
 * @fileoverview Hooks shared by many view-model components: prop defaults
 * (`_.KR`), store selectors (`_.R6`), entity lookups (`_.Xb`), the
 * visibility and interaction refs of ad components (`_.Ee`, `_.Fb`), ref
 * merging (`_.ty`), the renderer switch (`_.Dv`), the command link
 * (`_.gp`), the layout-token resolver (`_.F_u`, `_.Ay`) and the shared
 * resize observer (`_.io`).
 */
import {afterRenderEffect, computed, linkedState, onInit, runUntracked, signal, unwrap} from '../../framework/vm/effect.js';
import {classes} from '../../framework/vm/classes.js';
import {cond, renderers} from '../../framework/vm/control.js';
import {h} from '../../framework/vm/jsx.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {defineComponent} from '../../framework/vm/render.js';
import {linkConfig} from '../../framework/link.js';
import {rootInjector} from '../../framework/injector.js';
import {fireCommand} from '../commands.js';
import {logClick} from '../logging.js';
import {appStore, selectEntity} from '../store.js';
import {observeVisibility} from '../visibility.js';

/** A renderer key, used to read a renderer out of its wrapper object. */
export class RendererToken {
  /** @param {string} name */
  constructor(name) {
    /** @const */
    this.name = name;
  }
}

/**
 * The renderer under a token's key of a wrapper object (`_.X`).
 * @param {*} wrapper
 * @param {!RendererToken} token
 * @return {*}
 */
export function rendererField(wrapper, token) {
  if (wrapper) return wrapper[token.name];
}

export const INNERTUBE_COMMAND = new RendererToken('innertubeCommand');
export const TOOLTIP_VIEW_MODEL = new RendererToken('tooltipViewModel');
export const SAMPLED_COLOR = new RendererToken('sampledColor');
export const ACCESSIBILITY_CONTEXT = new RendererToken('accessibilityContext');
export const COMMAND_CONTEXT = new RendererToken('commandContext');
export const BUTTON_VIEW_MODEL = new RendererToken('buttonViewModel');
export const SECTION_HEADER_VIEW_MODEL = new RendererToken('sectionHeaderViewModel');
export const LOCKUP_METADATA_VIEW_MODEL = new RendererToken('lockupMetadataViewModel');
export const FEED_AD_METADATA_VIEW_MODEL = new RendererToken('feedAdMetadataViewModel');
export const AD_IMAGE_VIEW_MODEL = new RendererToken('adImageViewModel');

/**
 * The accessibility label of a renderer context.
 * @param {*} context
 * @return {string|undefined}
 */
export function contextLabel(context) {
  const a11y = /** @type {?Object} */ (rendererField(context, ACCESSIBILITY_CONTEXT));
  return a11y ? a11y.label : undefined;
}

/**
 * The tap command of a renderer context (`_.$X`).
 * @param {*} context
 * @return {*}
 */
export function contextCommandOf(context) {
  const c = /** @type {?Object} */ (rendererField(context, COMMAND_CONTEXT));
  return c ? c.onTap : undefined;
}

/**
 * A converter that turns a number thunk into a thunk of a CSS length in
 * `unit` (`jKD`; `_.Sn` for pixels). It calls the thunk twice per read.
 * @param {string} unit
 * @return {function(?function(): (number|undefined|null)): function(): (string|undefined)}
 */
export function unitThunk(unit) {
  return (fn) => () => (fn && fn() !== undefined ? String(fn()) + unit : undefined);
}

export const PX = unitThunk('px');
export const PERCENT = unitThunk('%');

const CSS_UNITS = ['rem', 'px', 'ms', '%', 's'];

/**
 * The number of a CSS length such as `16px` (`_.K8`).
 * @param {string|undefined} value
 * @return {number|undefined}
 */
export function cssNumber(value) {
  if (!value) return undefined;
  let digits = '';
  for (const unit of CSS_UNITS) {
    if (value.endsWith(unit)) {
      digits = value.slice(0, -unit.length);
      break;
    }
  }
  if (!digits) return undefined;
  const n = Number(digits);
  return isNaN(n) ? undefined : n;
}

/** The injection token of the semantic-layout resolver (`_.DSy`). */
export const LAYOUT_RESOLVER = {name: 'SEMANTIC_LAYOUT_RESOLVER_TOKEN'};

/**
 * A signal of the semantic-layout resolver from the root injector
 * (`_.F_u`). The resolver maps a design token to a CSS value. Our page
 * provides none, so readers fall back to their defaults.
 * @return {function(): (function(!Object): (string|undefined)|undefined)}
 */
export function useLayoutResolver() {
  const [resolver] = signal(/** @type {?} */ (rootInjector.resolve(LAYOUT_RESOLVER)), 'eXSuNb');
  return resolver;
}

/**
 * A computed of the CSS value of a design token thunk (`_.Ay`).
 * @param {function(): *} token
 * @return {function(): (string|undefined)}
 */
export function useLayoutToken(token) {
  const resolver = useLayoutResolver();
  return computed(() => {
    const t = token();
    if (!t) return undefined;
    const r = resolver();
    return r ? r(/** @type {!Object} */ (t)) : undefined;
  }, undefined, 'GyGPtd');
}

/** The queries of the responsive breakpoints 1 to 4. */
const BREAKPOINT_QUERIES = ['(max-width: 527.9px)', '(min-width: 528px) and (max-width: 839.9px)',
  '(min-width: 840px) and (max-width: 1023.9px)', '(min-width: 1024px)'];

/**
 * The responsive breakpoint (`_.r1`): 1 below 528 px, 2 below 840, 3 below
 * 1024, 4 from there, 0 when none matches. It creates four media query
 * lists and a signal for each, and listens to their changes from an init
 * callback. Every component that picks a typography token uses it, so a
 * lockup has one per metadata part.
 * @return {function(): number}
 */
export function useBreakpoint() {
  const lists = BREAKPOINT_QUERIES.map(q => window.matchMedia(q));
  const signals = lists.map(l => signal(l.matches, 'TmIKcb'));
  const handlers = signals.map(([, set]) => (/** !MediaQueryListEvent */ e) => set(e.matches));
  onInit(() => {
    lists.forEach((l, i) => l.addEventListener('change', handlers[i]));
    onCleanup(() => lists.forEach((l, i) => l.removeEventListener('change', handlers[i])));
  });
  return () => (signals[0][0]() ? 1 : signals[1][0]() ? 2 : signals[2][0]() ? 3 : signals[3][0]() ? 4 : 0);
}

/** The injection token of the typography resolver (`_.Y38`). */
export const TYPOGRAPHY_RESOLVER = {name: 'TYPOGRAPHY_RESOLVER_TOKEN'};

/**
 * A computed of the style a typography token stands for at the current
 * breakpoint (`_.os`). Our page provides no resolver, so it is undefined.
 * @param {function(): *} token
 * @param {function(): number} breakpoint
 * @param {!Object=} options
 * @return {function(): (!Object|undefined)}
 */
export function useTypographyToken(token, breakpoint, options) {
  const [resolver] = signal(/** @type {?} */ (rootInjector.resolve(TYPOGRAPHY_RESOLVER)), 'xGsRQ');
  return computed(() => {
    const t = token();
    if (t == null || breakpoint() === 0) return undefined;
    const r = resolver();
    return r ? r(t, breakpoint, options) : undefined;
  }, undefined, 'bsosdd');
}

/** The injection token of the colour-token resolver (`_.kWn`). */
export const COLOR_RESOLVER = {name: 'COLOR_RESOLVER_TOKEN'};

/**
 * A computed of the CSS colour a colour token stands for (`_.j6`).
 * @param {function(): *} token
 * @return {function(): (string|undefined)}
 */
export function useColorToken(token) {
  const [resolver] = signal(/** @type {?} */ (rootInjector.resolve(COLOR_RESOLVER)), 'HfDdK');
  return computed(() => {
    const t = token();
    const r = t ? resolver() : undefined;
    return r ? r(t) : undefined;
  }, undefined, 'v70E7b');
}

/**
 * The size name of a thumbnail of the given width and height (`_.VY`).
 * @param {number|undefined} width
 * @param {number|undefined=} height
 * @return {string}
 */
export function thumbnailSizeName(width, height) {
  if (!width && !height) return 'medium';
  const v = Math.max(width || 0, height || 0);
  return v >= 256 ? 'large' : v >= 96 ? 'medium' : 'small';
}

/**
 * Wraps each prop that has a default in a new thunk that falls back to it.
 * @param {!Object} props
 * @param {!Object} defaults
 * @return {!Object}
 */
export function withDefaults(props, defaults) {
  const out = Object.assign({}, props);
  for (const key in defaults) {
    const value = props[key];
    const fallback = defaults[key];
    out[key] = () => {
      const v = unwrap(value);
      return v === undefined ? fallback : v;
    };
  }
  return out;
}

/** @type {?function(): number} */
let storeVersion = null;

/**
 * The signal that counts store changes (`g9e`), created on first use and
 * bumped by one app store subscription for the page's lifetime.
 * @return {function(): number}
 */
function storeVersionSignal() {
  if (!storeVersion) {
    const [version, , update] = signal(0, 'MB1Hb');
    appStore.subscribe(() => update((n) => n + 1));
    storeVersion = version;
  }
  return storeVersion;
}

/**
 * A computed of a store selector's result (`_.zc`): it reads the store
 * version signal, so it runs again after every store change.
 * @template T
 * @param {function(?): T} selector
 * @return {function(): T}
 */
export function useSelector(selector) {
  const version = storeVersionSignal();
  return computed(() => {
    version();
    return selector(appStore.getState());
  }, undefined, 'DEXkhd');
}

/**
 * The entity of a type under a key that may change.
 * @param {string} entityType
 * @param {function(): (string|undefined)} key
 * @return {function(): *}
 */
export function useEntity(entityType, key) {
  const entities = useSelector((state) => state.entities);
  return computed(() => selectEntity(entities(), entityType, key()), undefined, 'c4');
}

/**
 * @param {*} command
 * @return {*}
 */
export function innertubeOf(command) {
  return rendererField(command, INNERTUBE_COMMAND) || command;
}

/**
 * The visibility ref of ad components: calls `onVisible(el)` the first time
 * the element nears the viewport, and `onHidden(el)` when it goes away
 * after that.
 * @param {{onVisible: function(!Element), onHidden: (function(!Element)|undefined)}} options
 * @return {function(!Element)}
 */
export function useVisibility(options) {
  return (el) => {
    let shown = false;
    const stop = observeVisibility(el, () => {
      shown = true;
      options.onVisible(el);
    });
    onCleanup(() => {
      stop();
      if (shown && options.onHidden) options.onHidden(el);
    });
  };
}

/**
 * The ref that makes an element run its interaction's tap command, through
 * a custom resolver when one is given.
 * @param {function(): ?Object} interaction
 * @param {(function(): *)=} resolver
 * @param {(function(): boolean)=} listenToTap
 * @return {function(!Element)}
 */
export function useInteraction(interaction, resolver, listenToTap) {
  return (el) => {
    const onTap = (/** !Event */ e) => {
      if (listenToTap && !listenToTap()) return;
      const i = interaction();
      const tap = i && i.onTap;
      if (!tap) return;
      const custom = resolver && resolver();
      if (typeof custom === 'function') custom(tap);
      else fireCommand(el, innertubeOf(tap));
      const command = innertubeOf(tap);
      logClick((command && command.clickTrackingParams) || '');
      e.stopPropagation();
    };
    const onKey = (/** !KeyboardEvent */ e) => {
      if (e.key === 'Enter') onTap(e);
    };
    el.addEventListener('click', onTap);
    el.addEventListener('keydown', onKey);
    onCleanup(() => {
      el.removeEventListener('click', onTap);
      el.removeEventListener('keydown', onKey);
    });
  };
}

/**
 * Runs a renderer context's visibility and tap commands (`_.u4`): an
 * after-render effect that follows the commands, adds the click listener
 * and removes it again.
 * @param {function(): *} context
 * @param {!Set<string>=} ignoreTags Tags whose clicks do not run the tap command.
 * @return {function(!Element)}
 */
export function useCommandContext(context, ignoreTags) {
  return (el) => {
    let stopVisibility = null;
    let visibleCommand;
    let hiddenCommand;
    afterRenderEffect(() => {
      const ctx = /** @type {?Object} */ (rendererField(context(), COMMAND_CONTEXT));
      const onVisible = ctx && innertubeOf(ctx.onVisible);
      const onHidden = ctx && innertubeOf(ctx.onHidden);
      const tap = ctx && innertubeOf(ctx.onTap);
      runUntracked(() => {
        if (onVisible !== visibleCommand || onHidden !== hiddenCommand) {
          if (stopVisibility) stopVisibility();
          stopVisibility = null;
          visibleCommand = onVisible;
          hiddenCommand = onHidden;
          if (onVisible || onHidden) {
            let shown = false;
            const stop = observeVisibility(el, () => {
              if (shown) return;
              shown = true;
              if (onVisible) fireCommand(el, onVisible);
            });
            stopVisibility = () => {
              stop();
              if (shown && onHidden) fireCommand(el, onHidden);
            };
          }
        }
        if (!tap) return;
        const onClick = (/** !Event */ e) => {
          for (let t = /** @type {?Element} */ (e.target); t && t !== el; t = t.parentElement) {
            if (ignoreTags && ignoreTags.has(t.tagName)) return;
          }
          fireCommand(el, tap);
        };
        el.addEventListener('click', onClick);
        onCleanup(() => el.removeEventListener('click', onClick));
      });
    }, 'UFrkkb');
    onCleanup(() => {
      if (stopVisibility) stopVisibility();
      stopVisibility = null;
    });
  };
}

/**
 * One ref that applies several refs in order.
 * @param {...*} refs Functions or `{onRender, onUnmount}` objects.
 * @return {function(!Element)}
 */
export function mergeRefs(...refs) {
  return (el) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === 'function') {
        ref(el);
      } else {
        if (ref.onRender) ref.onRender(el);
        if (ref.onUnmount) onCleanup(() => ref.onUnmount(el));
      }
    }
  };
}

/**
 * The renderer-type switch over one renderer object or a list of them
 * (`_.Dv`). Entries are components, or render functions that become
 * components named after their key; `wrapper` receives a thunk of the
 * rendered item.
 * @param {*} data
 * @param {!Object<string, function(?): *>} mapping
 * @param {(function(function(): *): *)=} wrapper
 * @return {!Object}
 */
export function rendererOf(data, mapping, wrapper) {
  return renderers(() => {
    const d = unwrap(data);
    return d ? (Array.isArray(d) ? d : [d]) : [];
  }, mapping, undefined, undefined, wrapper);
}

/** A link that runs its command on click (`_.gp`). */
export const CommandLink = defineComponent((props) => {
  const link = computed(() => linkConfig(innertubeOf(unwrap(props.command))), undefined, 'apLink');
  return h('a', {
    class: () => unwrap(props.className) || '',
    href: () => link().href,
    rel: () => link().rel,
    target: () => link().target,
    tabindex: () => (unwrap(props.tabIndex) === undefined ? undefined : String(unwrap(props.tabIndex))),
    'aria-hidden': () => (unwrap(props.ariaHidden) ? 'true' : undefined),
    'aria-label': () => unwrap(props.ariaLabel),
    style: () => unwrap(props.style) || undefined,
    'on:click': (/** !Event */ e) => {
      const command = innertubeOf(unwrap(props.command));
      if (!command) return;
      e.preventDefault();
      fireCommand(/** @type {!Element} */ (e.currentTarget), command);
    },
  }, props.children);
}, 'ap');

/**
 * The dismissal wrapper of a lockup: the replacement content after the
 * item was dismissed, else its children.
 */
export const DismissibleItem = defineComponent((props) => {
  const entity = useEntity('dismissalEntity', () => unwrap(props.contentId));
  const replacement = () => {
    const e = entity();
    return e && e.command && e.command.replacementCommand;
  };
  const undo = () => {
    const e = entity();
    return e && e.command && e.command.undoCommand;
  };
  return cond(() => replacement() || undo(), () => cond(replacement, () => h('div', {class: 'ytlDismissibleItemReplacedContent'},
    h('div', {class: classes({'ytlDismissibleItemAspectRatioContainer': () => unwrap(props.aspectRatio) !== undefined})}))),
  () => props.children);
}, 'Sb');

/** @type {?ResizeObserver} */
let resizeObserver = null;
/** @type {!Map<string, !Set<function(!Object)>>} */
const resizeCallbacks = new Map();
/** @type {!Map<string, !Object>} */
const lastResize = new Map();
let nextResizeId = 0;

/**
 * The resize-observer id of an element, assigned on first use (`qag`).
 * @param {!HTMLElement} el
 * @return {string}
 */
function resizeObserverId(el) {
  const id = el.dataset.resizeObserverId;
  if (id) return id;
  return el.dataset.resizeObserverId = String(nextResizeId++);
}

/**
 * Calls the callbacks of each element whose size changed (`Zyt`).
 * @param {!Array<!ResizeObserverEntry>} entries
 */
function onResize(entries) {
  for (const entry of entries) {
    const id = resizeObserverId(/** @type {!HTMLElement} */ (entry.target));
    const last = lastResize.get(id);
    if (last && last.contentRect.width === entry.contentRect.width && last.contentRect.height === entry.contentRect.height) continue;
    lastResize.set(id, {borderBoxSize: entry.borderBoxSize, contentBoxSize: entry.contentBoxSize, contentRect: entry.contentRect,
      devicePixelContentBoxSize: entry.devicePixelContentBoxSize});
    for (const fn of resizeCallbacks.get(id) || []) fn(entry);
  }
}

/**
 * @param {!HTMLElement} el
 * @param {function(!Object)} fn
 */
function observeResize(el, fn) {
  const id = resizeObserverId(el);
  if (!resizeCallbacks.has(id)) resizeCallbacks.set(id, new Set());
  /** @type {!Set} */ (resizeCallbacks.get(id)).add(fn);
  const last = lastResize.get(id);
  if (last) fn(Object.assign({target: el}, last));
  if (!resizeObserver) resizeObserver = new ResizeObserver(onResize);
  resizeObserver.observe(el);
}

/**
 * @param {!HTMLElement} el
 * @param {function(!Object)} fn
 */
function unobserveResize(el, fn) {
  const id = resizeObserverId(el);
  const set = resizeCallbacks.get(id);
  if (set) {
    set.delete(fn);
    if (!set.size) {
      resizeCallbacks.delete(id);
      lastResize.delete(id);
      /** @type {!ResizeObserver} */ (resizeObserver).unobserve(el);
      delete el.dataset.resizeObserverId;
    }
  }
  if (!resizeCallbacks.size && resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  }
}

/**
 * A function that runs `fn` at once, then at most once per `ms` with the
 * latest arguments (`ska`).
 * @param {function(...?)} fn
 * @param {number} ms
 * @return {function(...?)}
 */
function throttle(fn, ms) {
  let timer = 0;
  let pending = false;
  let args = [];
  const run = () => {
    timer = setTimeout(done, ms);
    const a = args;
    args = [];
    fn(...a);
  };
  const done = () => {
    timer = 0;
    if (pending) {
      pending = false;
      run();
    }
  };
  return (...a) => {
    args = a;
    if (timer) pending = true;
    else run();
  };
}

/**
 * The size of an element, from one shared resize observer (`_.io`).
 * @param {{canHaveZeroSize: (boolean|undefined), throttleMs: (number|undefined)}=} options
 * @return {!Array<?>} `[size, ref]`; `size.width()` and `size.height()` read signals.
 */
export function useResize(options) {
  const o = Object.assign({throttleMs: 0, canHaveZeroSize: true}, options);
  const [height, setHeight] = signal(0, 'resizeHeight');
  const [width, setWidth] = signal(0, 'resizeWidth');
  const size = {width, height};
  const callback = throttle((/** !Object */ entry) => {
    const h = entry.contentRect.height;
    const w = entry.contentRect.width;
    if (!(w || h || o.canHaveZeroSize)) return;
    if (width() === w && height() === h) return;
    setHeight(h);
    setWidth(w);
  }, o.throttleMs);
  const ref = (/** !Element */ el) => {
    const e = /** @type {!HTMLElement} */ (el);
    observeResize(e, callback);
    onCleanup(() => unobserveResize(e, callback));
  };
  return [size, ref];
}

/** Live setters and persisted values of updatable data (`XA`). */
const updatable = {live: new Map(), invalidators: new Map(), persistent: new Map()};

/**
 * The initial value of updatable data under `key` (`W_8`): the persisted
 * value when it was updated and its invalidators did not change, else
 * `data`.
 * @param {*} key
 * @param {*} data
 * @param {{shouldPersist: boolean}} options
 * @param {!Array<*>} deps
 * @return {*}
 */
function persistedValue(key, data, options, deps) {
  if (key == null || !options.shouldPersist) return data;
  if (updatable.persistent.get(key) === undefined) updatable.persistent.set(key, [data, deps, false]);
  const entry = updatable.persistent.get(key);
  if (!entry) return data;
  const [value, oldDeps, updated] = entry;
  if (oldDeps.length && deps.length && deps.some((d, i) => d !== oldDeps[i])) {
    updatable.persistent.delete(key);
    return data;
  }
  if (deps.length) updatable.persistent.set(key, [value, deps, updated]);
  return updated ? value : data;
}

/**
 * @param {*} key
 * @param {function(*): *} fn
 * @param {{shouldPersist: boolean}} options
 * @return {boolean}
 */
function updateUpdatable(key, fn, options) {
  const live = updatable.live.get(key);
  if (live) {
    const value = fn(live[0]());
    live[1](value);
    if (options.shouldPersist && key != null) {
      const deps = updatable.invalidators.get(key);
      updatable.persistent.set(key, [value, (deps && deps()) || [], true]);
    }
    return true;
  }
  const entry = options.shouldPersist && key != null ? updatable.persistent.get(key) : undefined;
  if (!entry) return false;
  updatable.persistent.set(key, [fn(entry[0]), entry[1], true]);
  return true;
}

/**
 * Data under a key that commands can replace while it is rendered, and
 * that can outlive the component (`Mry`).
 * @param {function(?): *} keyOf
 * @param {{shouldPersist: boolean}=} options
 * @return {{useUpdatableData: function(function(): ?, Array<function(): *>=): !Array<?>, updateData: function(*, function(*): *)}}
 */
export function updatableData(keyOf, options) {
  const opts = options || {shouldPersist: true};
  return {
    useUpdatableData(data, deps) {
      const key = computed(() => keyOf(data()), undefined, 'Gmrblb');
      const depValues = () => (deps ? deps.map((d) => d()) : []);
      const [value, setValue] = linkedState(() => persistedValue(key(), data(), opts, depValues()), 'kF');
      afterRenderEffect(() => {
        const k = key();
        if (k == null) return;
        const entry = [value, setValue];
        updatable.live.set(k, entry);
        updatable.invalidators.set(k, depValues);
        onCleanup(() => {
          if (updatable.live.get(k) === entry) {
            updatable.live.delete(k);
            updatable.invalidators.delete(k);
          }
        });
      }, 'Umac6c');
      return [value, (v) => {
        setValue(v);
        const k = key();
        if (k != null) updateUpdatable(k, () => v, opts);
      }];
    },
    updateData(key, fn) {
      updateUpdatable(key, fn, opts);
    },
  };
}
