/**
 * @fileoverview Error reporting for callbacks, as YouTube's: while the page
 * sets `window.yterr`, `wrapErrors(fn)` returns a new closure that calls `fn`
 * inside try/catch and reports what it throws.
 */
import {getConfig, getObjectByName, setConfig} from './flags.js';

/**
 * Reports an error to the error logger, or queues it in the config until
 * the logger exists.
 * @param {*} e
 */
export function reportError(e) {
  const log = /** @type {?function(*, string)} */ (getObjectByName('yt.logging.errors.log'));
  if (log) {
    log(e, 'ERROR');
  } else {
    const errors = /** @type {!Array<!Array<*>>} */ (getConfig('ERRORS', []));
    errors.push([e, 'ERROR']);
    setConfig('ERRORS', errors);
  }
  console.error('Reported error', e);
}

/**
 * @param {?Function} fn
 * @return {?Function}
 */
export function wrapErrors(fn) {
  return fn && /** @type {?} */ (window).yterr ? /** @this {*} */ function() {
    try {
      return fn.apply(this, arguments);
    } catch (e) {
      reportError(e);
    }
  } : fn;
}
