/**
 * @fileoverview The component-on-web wrapper (CoW, `_.Ho`): a custom
 * element that renders a view-model component with itself as the root
 * element, so Polymer templates can contain view-model components.
 *
 * Each declared prop gets a prototype setter. Before the first render the
 * setter stores the value; afterwards it writes the prop's signal. A host
 * that declares `data` waits for it. On first render the host converts its
 * attributes to props (camel-cased, with type coercion), creates one
 * signal per declared non-static prop, groups its child nodes by slot and
 * removes its attributes. The render runs untracked; its owner hangs off
 * the nearest ancestor host's `__owner`. Disconnecting disposes the render,
 * removes the attributes again, clears the content and resets the
 * renderer's fields on the host.
 *
 * Every hyphenated element that a component's JSX creates, other than the
 * host being rendered, is marked inert. A CoW tag marked so does nothing in
 * its callbacks and setters, and the parent component fills it as a plain
 * element.
 */
import {dashToCamel} from '../case.js';
import {vmCounters} from './counters.js';
import {runUntracked, signal} from './effect.js';
import {h} from './jsx.js';
import {runWithOwner} from './owner.js';
import {renderRoot, resetElementFields, setElementCreatedHook, setRootHost} from './render.js';

/** Prop kinds. */
export const PropKind = {SIGNAL: 1, STATIC: 2, SLOT: 3};

/** What a declared prop's getter returns. */
const UNSET = Symbol('unset');

/** @type {!WeakMap<!Element, boolean>} */
const inertHosts = new WeakMap();
/** Names that get no getter on a CoW prototype. */
const ELEMENT_NAMES = new Set(Object.getOwnPropertyNames(Element.prototype));
/** @type {?Element} */
let renderingHost = null;

/** Context providers by host element, then by tag. */
/** @type {!WeakMap<!Element, !Array<!Array<*>>>} */
const contextsByHost = new WeakMap();
/** @type {!Map<string, !Array<!Array<*>>>} */
const contextsByTag = new Map();

setElementCreatedHook((el) => {
  if (el !== renderingHost && el.localName.includes('-')) inertHosts.set(el, true);
});

/**
 * @param {!Element} host
 * @return {?Array<!Array<*>>}
 */
function lookUpContexts(host) {
  return contextsByHost.get(host) || contextsByTag.get(host.localName) || null;
}

/**
 * Coerces an attribute value: `""` and `"true"` to true, `"false"` to
 * false, numeric strings to numbers.
 * @param {string} value
 * @return {*}
 */
function coerceAttribute(value) {
  if (value === '' || value === 'true') return true;
  if (value === 'false') return false;
  return isNaN(Number(value)) ? value : Number(value);
}

function noop() {}

/**
 * @param {string} tag
 * @param {function(?, ?string, !Array<!Node>)} component A `defineComponent`
 *     component whose root element has the tag `tag`.
 * @param {{props: (!Object<string, number>|undefined), unsafeExternallySettableAttributes: (!Set<string>|undefined)}=} options
 */
export function defineCoW(tag, component, options = {}) {
  const declared = options.props || {};
  const externallySettable = options.unsafeExternallySettableAttributes || null;
  /** @type {?} */ (component).debugName = `${tag} (CoW)`;

  class CoWHost extends HTMLElement {
    constructor() {
      super();
      /** @type {!Object<string, *>} */
      this.rawProps = {};
      this.queuingData = false;
      /** @type {?Object} */
      this.owner = null;
      /** @type {function()} */
      this.dispose = noop;
      this.isWebComponentWrapper = true;
      this.isReparenting = false;
      this.hasRendered = false;
      this.isLazyComponentFn = false;
    }

    /** @return {boolean} */
    isQueuingForData() {
      return 'data' in declared && !this.rawProps['data'] && !this.getAttribute('data');
    }

    connectedCallback() {
      if (inertHosts.has(this)) return;
      if (this.isReparenting) {
        this.isReparenting = false;
        return;
      }
      this.queuingData = this.isQueuingForData();
      if (!this.owner) this.setUpOwner();
      if (this.owner && this.owner.isDisposed) this.owner = null;
      if (!this.queuingData) this.render();
    }

    disconnectedCallback() {
      if (inertHosts.has(this)) return;
      this.dispose();
      if (!this.queuingData) {
        for (const attr of Array.from(this.attributes)) {
          const name = attr.name;
          if (name === 'slot' || (name === 'hidden' && externallySettable && externallySettable.has('hidden'))) continue;
          this.removeAttribute(name);
        }
      }
      this.innerText = '';
      resetElementFields(this);
    }

    /** Walks up to the nearest element with an `__owner`, crossing shadow roots. */
    setUpOwner() {
      let el = /** @type {?} */ (this);
      while (el && !el.__owner) el = el.parentElement || (el.parentNode && el.parentNode.host);
      this.owner = el ? el.__owner : null;
    }

    setUpProps() {
      runWithOwner(this.owner, () => {
        const raw = this.rawProps;
        for (const name of Object.keys(declared)) {
          const own = this[name];
          if (own && own !== UNSET && raw[name] === undefined) {
            raw[name] = own;
            const desc = Object.getOwnPropertyDescriptor(this.constructor.prototype, name);
            if (desc) Object.defineProperty(this, name, desc);
          }
        }
        const attrs = this.attributes;
        for (const attr of Array.from(attrs)) {
          const name = dashToCamel(attr.name);
          const isClass = name === 'class' && !attrs.getNamedItem('class-name');
          if (!(name in declared) && !isClass) continue;
          const value = coerceAttribute(attr.value);
          if (name !== 'class' || raw['className']) raw[name] = value;
          else raw['className'] = value;
        }
        const setters = {};
        for (const name in declared) {
          if (declared[name] === PropKind.STATIC || declared[name] === PropKind.SLOT) continue;
          if (raw[name] instanceof Function) console.error(`${tag}: function props must be configured as STATIC, not SIGNAL.`);
          vmCounters.cowSignals++;
          const [get, set] = signal(raw[name], 'WpPQae');
          vmCounters.signals--;
          setters[name] = set;
          raw[name] = get;
        }
        this.componentProps = raw;
        this.setters = setters;
      });
      this.slotProps = this.collectSlots_();
    }

    /**
     * Groups the child nodes by their `slot` attribute. Slots other than
     * `children` are passed as thunks.
     * @return {!Object<string, *>}
     * @private
     */
    collectSlots_() {
      const slots = {};
      for (const node of Array.from(this.childNodes)) {
        const slotName = (node.getAttribute && node.getAttribute('slot')) || 'children';
        const name = dashToCamel(slotName);
        const list = slots[name];
        if (list) list.push(node);
        else if (name in declared || name === 'children') slots[name] = [node];
      }
      for (const name of Object.keys(slots)) {
        if (name === 'children') continue;
        const content = slots[name];
        slots[name] = () => content;
      }
      return slots;
    }

    render() {
      if (!this.hasRendered) {
        this.setUpProps();
        this.hasRendered = true;
      }
      for (const attr of Array.from(this.attributes)) {
        const name = attr.name;
        if (name !== 'slot' && name !== 'data-sourcecode-loc' && name !== 'hidden') this.removeAttribute(name);
      }
      let rendered = component;
      const props = Object.assign({}, this.componentProps, this.slotProps);
      const contexts = lookUpContexts(this);
      if (contexts) rendered = withContexts(rendered, contexts, tag);
      const prevRendering = renderingHost;
      const prevHost = setRootHost(this);
      renderingHost = this;
      let root;
      try {
        root = runWithOwner(this.owner, () => runUntracked(() => renderRoot(h(rendered, props), this.owner, null, true)));
      } finally {
        renderingHost = prevRendering;
        setRootHost(prevHost);
      }
      const nodes = root.nodes;
      if (nodes.length !== 1 || !(nodes[0] instanceof Element)) {
        console.error(`${tag}: wrapped Wiz components must return a single root element.`);
      } else if (nodes[0] !== this) {
        console.error(`${tag}: wrapped Wiz components must have the same host tag name as the web component.`);
      } else {
        this.dispose = root.dispose;
      }
    }

    _setPendingPropertyOrPath() {}

    notifyPath() {}

    /** @return {boolean} */
    get __isPropertyEffectsClient() {
      return false;
    }

    /** @return {undefined} */
    get __dataHasAccessor() {
      return undefined;
    }
  }

  const names = Object.keys(declared);
  if (names.includes('className')) names.push('class');
  for (const name of names) defineProp(CoWHost.prototype, name);
  customElements.define(tag, CoWHost);
}

/** @return {symbol} */
function getUnset() {
  return UNSET;
}

/**
 * Defines a declared prop's setter on a CoW prototype. Names that
 * `Element.prototype` has get no getter, so reading them gives undefined.
 * @param {!Object} proto
 * @param {string} name
 */
function defineProp(proto, name) {
  const prop = name === 'class' ? 'className' : name;
  Object.defineProperty(proto, name, {
    configurable: true,
    enumerable: true,
    get: ELEMENT_NAMES.has(name) ? undefined : getUnset,
    /** @this {?} */
    set(value) {
      if (inertHosts.has(this)) return;
      if (this.setters) {
        runUntracked(() => {
          const set = this.setters[prop];
          if (set) set(value);
        });
        return;
      }
      this.rawProps[prop] = value;
      if (this.queuingData && prop === 'data' && value != null) {
        this.queuingData = false;
        this.render();
      }
    },
  });
}

/**
 * Wraps a component in a context-provider component.
 * @param {function(?, ?string, !Array<!Node>)} component
 * @param {!Array<!Array<*>>} contexts
 * @param {string} tag
 * @return {function(?, ?string, !Array<!Node>)}
 */
function withContexts(component, contexts, tag) {
  const provider = (props) => h(component, Object.assign({contexts}, props));
  /** @type {?} */ (provider).debugName = `${tag} (Context Provider)`;
  return provider;
}

/**
 * Registers context values for a host, or for every host with a tag.
 * @param {!Element|string} hostOrTag
 * @param {!Array<!Array<*>>} contexts `[token, value]` pairs.
 */
export function provideCoWContexts(hostOrTag, contexts) {
  if (typeof hostOrTag === 'string') contextsByTag.set(hostOrTag, contexts);
  else contextsByHost.set(hostOrTag, contexts);
}

/**
 * Hosts a component that reads `data` through a CoW element with a single
 * `data` prop. Kept for elements that have not been given their own
 * declarations.
 * @param {string} tag
 * @param {function(?, ?string, !Array<!Node>)} component
 */
export function defineViewModelElement(tag, component) {
  defineCoW(tag, component, {props: {data: PropKind.SIGNAL}});
}
