/**
 * @fileoverview The path-observable store behind each property of a
 * signal-schema controller (and of repeat and if instances).
 *
 * A store holds one root value in a signal, and a tree of the sub-paths
 * that readers observe. A root write sets the value signal, which flushes
 * its readers before the write returns. Every mutation (root write,
 * sub-path write or notification) then stamps a fresh record on the tree
 * nodes from the root to the written path and on the observed subtree
 * below it, and writes the store's mutation signal, which flushes the
 * path, wildcard and splices readers. The mutation signal exists only once
 * a reader asked for it; until then mutations are not recorded.
 */
import {createComputed, createSignal, untracked} from '../signals.js';

/**
 * @typedef {{path: !Array<string>, value: *, fallbackWhenUndefined: (*|undefined)}}
 */
let Mutation;

/**
 * @typedef {{index: number, mutation: !Mutation, spliceMutationIndex: number}}
 */
let MutationData;

/**
 * A node of the observed-path tree. `data` is stamped by every mutation on
 * the way to or below the node; `selfIndex` only by mutations of the node
 * itself or an ancestor.
 * @typedef {{
 *   pathComponents: !Array<string>,
 *   data: ?MutationData,
 *   selfIndex: number,
 *   subPaths: !Object<string, ?>,
 * }}
 */
let PathNode;

/**
 * @param {!Array<string>} pathComponents
 * @return {!PathNode}
 */
function newNode(pathComponents) {
  return {pathComponents, data: null, selfIndex: 0, subPaths: Object.create(null)};
}

/**
 * @param {*} obj
 * @param {!Array<string>} path
 * @return {*}
 */
function walk(obj, path) {
  for (let i = 0; i < path.length && obj != null; i++) obj = obj[path[i]];
  return obj;
}

/**
 * @param {!PathNode} node
 * @param {number} index
 * @param {!Mutation} mutation
 * @param {number} spliceMutationIndex
 */
function stampSubtree(node, index, mutation, spliceMutationIndex) {
  node.data = {index, mutation, spliceMutationIndex};
  node.selfIndex = index;
  for (const key in node.subPaths) stampSubtree(node.subPaths[key], index, mutation, spliceMutationIndex);
}

export class PathStore {
  /**
   * @param {string} key The root property name, for change-record paths.
   * @param {*} initialValue
   */
  constructor(key, initialValue) {
    /** @const {string} */
    this.key = key;
    const [get, set] = createSignal(initialValue, undefined);
    /** @private @const {function(): *} */
    this.getValue_ = get;
    /** @private @const {function(*)} */
    this.setValue_ = set;
    /** @type {boolean} */
    this.wasDefined = initialValue !== undefined;
    /** @type {number} */
    this.mutationIndex = 0;
    /** @const {!PathNode} */
    this.observedPath = newNode([]);
    /** @type {?function(): number} */
    this.getMutationSignal = null;
    /** @type {?function(number)} */
    this.setMutationSignal = null;
  }

  /**
   * Reads the value at `path`, tracking the root value.
   * @param {!Array<string>} path Relative to the root.
   * @return {*}
   */
  getWithPath(path) {
    return walk(this.getValue_(), path);
  }

  /**
   * Reads the value at `path` without tracking.
   * @param {!Array<string>} path
   * @return {*}
   */
  peek(path) {
    return untracked(() => walk(this.getValue_(), path));
  }

  /**
   * @param {!Array<string>} path Relative to the root.
   * @param {*} value
   */
  setWithPath(path, value) {
    const last = path[path.length - 1];
    if (last === '*' || last === 'splices') return;
    if (!path.length) {
      if (value === untracked(this.getValue_)) return;
      if (value !== undefined) this.wasDefined = true;
      this.setValue_(value);
      this.recordMutation_([], {path: [], value, fallbackWhenUndefined: undefined}, 0);
      return;
    }
    const parent = this.peek(path.slice(0, -1));
    if (parent == null || typeof parent !== 'object') return;
    parent[last] = value;
    this.wasDefined = true;
    this.recordMutation_(path, {path, value, fallbackWhenUndefined: undefined}, 0);
  }

  /**
   * Notifies readers of a change at `path` that was made in place. At the
   * root, only a given value is written.
   * @param {!Array<string>} path
   * @param {{value: *}=} options
   */
  notifyPath(path, options) {
    if (!path.length) {
      if (options) this.setWithPath([], options.value);
      return;
    }
    this.recordMutation_(path, {path, value: this.peek(path), fallbackWhenUndefined: options ? options.value : undefined}, 0);
  }

  /**
   * @param {!Array<string>} path The array's path.
   * @param {!Array<!Object>} splices
   */
  notifySplices(path, splices) {
    const splicesPath = path.concat(['splices']);
    this.recordMutation_(splicesPath, {path: splicesPath, value: {indexSplices: splices}, fallbackWhenUndefined: undefined}, 0);
    const array = this.peek(path);
    if (array && array.length) {
      const lengthPath = path.concat(['length']);
      this.recordMutation_(lengthPath, {path: lengthPath, value: array.length, fallbackWhenUndefined: undefined}, this.mutationIndex);
    }
  }

  /**
   * @param {!Array<string>} path
   * @param {!Array<*>} items
   * @return {number}
   */
  push(path, items) {
    const array = /** @type {!Array<*>} */ (this.peek(path));
    const index = array.length;
    untracked(() => array.push(...items));
    if (items.length) this.notifySplices(path, [{index, addedCount: items.length, removed: [], object: array, type: 'splice'}]);
    return array.length;
  }

  /**
   * @param {!Array<string>} path
   * @param {number} start
   * @param {number} deleteCount
   * @param {!Array<*>} items
   * @return {!Array<*>}
   */
  splice(path, start, deleteCount, items) {
    const array = /** @type {!Array<*>} */ (this.peek(path));
    if (start < 0) start = Math.max(0, array.length + start);
    const removed = untracked(() => array.splice(start, deleteCount, ...items));
    if (removed.length || items.length) {
      this.notifySplices(path, [{index: start, addedCount: items.length, removed, object: array, type: 'splice'}]);
    }
    return removed;
  }

  /**
   * @param {!Array<string>} path
   * @return {*}
   */
  pop(path) {
    const array = /** @type {!Array<*>} */ (this.peek(path));
    if (!array.length) return undefined;
    return this.splice(path, array.length - 1, 1, [])[0];
  }

  /**
   * @param {!Array<string>} path
   * @param {!Array<*>} items
   * @return {number}
   */
  unshift(path, items) {
    this.splice(path, 0, 0, items);
    return /** @type {!Array<*>} */ (this.peek(path)).length;
  }

  /**
   * @param {!Array<string>} path
   * @param {!Mutation} mutation
   * @param {number} spliceMutationIndex
   * @private
   */
  recordMutation_(path, mutation, spliceMutationIndex) {
    if (!this.setMutationSignal) return;
    const index = ++this.mutationIndex;
    let node = this.observedPath;
    node.data = {index, mutation, spliceMutationIndex};
    if (!path.length) {
      stampSubtree(node, index, mutation, spliceMutationIndex);
    } else {
      for (let i = 0; i < path.length; i++) {
        node = node.subPaths[path[i]];
        if (!node) break;
        if (i === path.length - 1) stampSubtree(node, index, mutation, spliceMutationIndex);
        else node.data = {index, mutation, spliceMutationIndex};
      }
    }
    this.setMutationSignal(index);
  }

  /**
   * Returns the tree node for `path`, creating it and the mutation signal.
   * @param {!Array<string>} path
   * @return {!PathNode}
   * @private
   */
  observe_(path) {
    if (!this.setMutationSignal) {
      const [get, set] = createSignal(0, undefined);
      this.getMutationSignal = get;
      this.setMutationSignal = set;
    }
    let node = this.observedPath;
    for (let i = 0; i < path.length; i++) {
      let next = node.subPaths[path[i]];
      if (!next) {
        next = newNode(path.slice(0, i + 1));
        node.subPaths[path[i]] = next;
      }
      node = next;
    }
    return node;
  }

  /**
   * A reader that changes when `path` or an ancestor is written.
   * @param {!Array<string>} path
   * @return {function(): number}
   */
  getPathMutationSignal(path) {
    const node = this.observe_(path);
    const mutationSignal = /** @type {function(): number} */ (this.getMutationSignal);
    return createComputed(() => {
      mutationSignal();
      return node.selfIndex;
    }, undefined);
  }

  /**
   * A reader of the newest change record at or below `path`:
   * `{path, value, base}`, with string paths that start with the root key.
   * A write to an ancestor is reported at `path` itself.
   * Between records it returns a plain record of the current value, made
   * anew after each record.
   * @param {!Array<string>} path
   * @return {function(): {path: string, value: *, base: *}}
   */
  getChangeRecordSignal(path) {
    const node = this.observe_(path);
    const mutationSignal = /** @type {function(): number} */ (this.getMutationSignal);
    const observed = [this.key].concat(path).join('.');
    let lastIndex = this.mutationIndex;
    let cached = null;
    return createComputed(() => {
      mutationSignal();
      const data = node.data;
      if (data && data.index > lastIndex) {
        lastIndex = data.index;
        cached = null;
        const written = data.mutation.path;
        const tail = written[written.length - 1];
        const longer = written.length > path.length ? written : path;
        const recordValue = tail === 'splices' || tail === 'length' ? data.mutation.value :
          this.peek(longer);
        return {
          path: [this.key].concat(longer).join('.'),
          value: recordValue === undefined ? data.mutation.fallbackWhenUndefined : recordValue,
          base: this.peek(path),
        };
      }
      if (!cached) {
        const current = this.peek(path);
        cached = {path: observed, value: current, base: current};
      }
      return cached;
    }, undefined);
  }

  /**
   * A reader of the newest splices of the array at `path`; the paired
   * `length` record is ignored.
   * @param {!Array<string>} path
   * @return {function(): ?{indexSplices: !Array<!Object>}}
   */
  getSplicesSignal(path) {
    const node = this.observe_(path);
    const mutationSignal = /** @type {function(): number} */ (this.getMutationSignal);
    let lastIndex = this.mutationIndex;
    let current = null;
    return createComputed(() => {
      mutationSignal();
      const data = node.data;
      if (data && data.index > lastIndex) {
        lastIndex = data.index;
        const written = data.mutation.path;
        if (written.length === path.length + 1 && written[path.length] === 'splices') {
          current = /** @type {{indexSplices: !Array<!Object>}} */ (data.mutation.value);
        }
      }
      return current;
    }, undefined);
  }
}
