/**
 * @fileoverview View models of the comment section: the sub-thread frame
 * that draws a reply thread's lines around its content, and the ghost
 * comments that stand in for comments while they load.
 */
import {classes} from '../../framework/vm/classes.js';
import {IndexEach} from '../../framework/vm/control.js';
import {computed, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';

/** The thread line beside a sub-thread: connection, continuation and shadow. */
const SubThreadLine = defineComponent(() => h('div', {class: 'ytlSubThreadThreadline'},
  h('div', {class: 'ytlSubThreadConnection'}),
  h('div', {class: 'ytlSubThreadContinuation'}),
  h('div', {class: 'ytlSubThreadShadow'})), 'sub-thread-line');

/** A reply thread's frame; the thread's content is its child nodes. */
const SubThread = defineComponent((props) => h('ytl-sub-thread', {
  class: classes('ytlSubThreadHost', {
    'ytlSubThreadHasButton': () => !!unwrap(props.hasButton),
    'ytlSubThreadTopLevelThread': () => !!unwrap(props.topLevelThread),
    'ytlSubThreadLastThread': () => !!unwrap(props.isLastThread),
  }),
},
h(SubThreadLine, {}),
h('div', {class: 'ytlSubThreadSubThreadContent'}, props.children)), 'yt-sub-thread (CoW)');

defineCoW('ytl-sub-thread', SubThread, {props: {hasButton: PropKind.SIGNAL, topLevelThread: PropKind.SIGNAL,
  isLastThread: PropKind.SIGNAL}});

/** The number of ghost comments when the container doesn't set one. */
const DEFAULT_GHOST_COMMENTS = 3;

/** One ghost comment: an avatar circle and four text bars. */
const GhostCard = defineComponent(() => h('div', {class: 'ytlGhostCommentsGhostCard'},
  h('div', {class: 'ytlGhostCommentsAvatar'}, h('div', {class: 'ytlGhostCommentsCircle'})),
  h('div', {class: 'ytlGhostCommentsHost'},
    h('div', {class: 'ytlGhostCommentsMeta'}, h('div', {class: 'ytlGhostCommentsGhostText ytlGhostCommentsGhostFill'})),
    h('div', {class: 'ytlGhostCommentsGhostText ytlGhostCommentsGhostFill'}),
    h('div', {class: 'ytlGhostCommentsGhostText ytlGhostCommentsGhostFill'}),
    h('div', {class: 'ytlGhostCommentsGhostLikeDislike'},
      h('div', {class: 'ytlGhostCommentsGhostText ytlGhostCommentsGhostFill'}),
      h('div', {class: 'ytlGhostCommentsGhostText ytlGhostCommentsGhostFill'})))), 'ghost-card');

/** Placeholder comments, shown by a comment section's continuation item. */
const GhostComments = defineComponent((props) => {
  const cards = computed(() => {
    const n = Number(unwrap(props.numberOfComments)) || DEFAULT_GHOST_COMMENTS;
    return Array.from({length: Math.max(1, n)}, (_, i) => i);
  }, undefined, 'ghostCards');
  return h('ytl-ghost-comments', {
    class: classes('ytlGhostCommentsHost', {
      'ytlGhostCommentsEngagementPanel': () => !!unwrap(props.engagementPanel),
      'ytlGhostCommentsInitialLoad': () => !!unwrap(props.isInitialLoad),
    }),
  },
  h('div', {class: 'ytlGhostCommentsComments'}, h(IndexEach, {of: cards, render: () => h(GhostCard, {})})));
}, 'yt-ghost-comments (CoW)');

defineCoW('ytl-ghost-comments', GhostComments, {props: {data: PropKind.SIGNAL, numberOfComments: PropKind.SIGNAL,
  isInitialLoad: PropKind.SIGNAL, engagementPanel: PropKind.SIGNAL}});
