const selectCommentSharedEntity = entitySelector('commentSharedEntityPayload');
const selectCommentSurfaceEntity = entitySelector('commentSurfaceEntityPayload');
const selectToolbarState = entitySelector('engagementToolbarStateEntityPayload');
const selectToolbarSurface = entitySelector('engagementToolbarSurfaceEntityPayload');
const selectTriStateState = entitySelector('triStateButtonStateEntityPayload');

const LIKED = 'TOOLBAR_LIKE_STATE_LIKED';
const DISLIKED = 'TOOLBAR_LIKE_STATE_DISLIKED';

/** Calls a function at most once per interval, at the end of it, when fired. */
class Throttle {
  /**
   * @param {function()} fn
   * @param {number} ms
   */
  constructor(fn, ms) {
    this.fn_ = fn;
    this.ms_ = ms;
    this.timer_ = 0;
  }

  fire() {
    if (this.timer_) return;
    this.timer_ = later(() => {
      this.timer_ = 0;
      this.fn_();
    }, this.ms_);
  }
}

/** The behaviours of every renderer, without the template helpers. */
const RENDERER_BASE = RendererBehavior.slice(0, -1);

/**
 * Whether comments thread their replies.
 * @return {boolean}
 */
function threadingEnabled() {
  return flag('web_delhi_comment_threads') || flag('enable_music_web_comment_threads');
}

/**
 * The inner command of an entity command wrapper.
 * @param {?Object|undefined} command
 * @return {?Object}
 */
function innertubeCommand(command) {
  return (command && command.innertubeCommand) || null;
}

Polymer(withHandles({
  _template: threadTemplate,
  is: 'ytl-comment-thread-renderer',
  behaviors: [...RENDERER_BASE, ReduxBehavior, StoreBehavior, ActionHandlerBehavior, YtRendererStamperBehavior, TemplateHelpersBehavior],
  properties: {
    data: Object,
    useSmallAvatars: {type: Boolean, reflectToAttribute: true},
    scrollingEnabled: {type: Boolean, reflectToAttribute: true},
    isSubThread: {type: Boolean, reflectToAttribute: true},
    threadHovered: {type: Boolean, reflectToAttribute: true},
    expanded: Boolean,
    subThreadsCount: Number,
    removed: {type: Boolean, reflectToAttribute: true},
    feedbackText: Object,
    addedReplies: Array,
    commentEntity: {type: Object, selector: selectCommentEntity, selectorArgs: ['commentViewModel.commentKey']},
    commentViewModel: {type: Object, computed: '__compute__commentViewModel(data)'},
    hasSubThreading: {type: Boolean, computed: '__compute__hasSubThreading(subThreadsCount)'},
    engagementPanel: {type: Boolean, reflectToAttribute: true},
  },
  observers: ['onDataChanged(data)'],
  listeners: {
    'yt-pushed-create-comment-reply': 'onPushedCreateCommentReply',
    'yt-append-continuation-items-action-finished': 'onAppendContinuationItemsActionFinished',
    'yt-comment-sub-threads-changed': 'onSubThreadsChanged',
    'yt-comment-continuation-empty': 'onContinuationEmpty',
  },

  /** @return {?Element} */
  get commentThreadHitbox() {
    return hostDom(this.hostElement).querySelector('.thread-hitbox');
  },

  /** @return {?Element} */
  get commentElement() {
    return hostDom(this.hostElement).querySelector('#comment');
  },

  created() {
    this.useSmallAvatars = flag('small_avatars_for_comments');
    this.scrollingEnabled = true;
    this.isSubThread = false;
    this.threadHovered = false;
    this.expanded = false;
    this.subThreadsCount = 0;
    this.removed = false;
    this.addedReplies = [];
    this.actionMap = this.configureActionMap();
    this.toggleExpanded = () => {
      this.expanded = !this.expanded;
      if (!this.expanded) fireAction(/** @type {!Element} */ (this.hostElement), 'yt-scroll-to-comment-element', [this.commentElement]);
    };
  },

  /** @return {!Object<string, string>} */
  configureActionMap() {
    return threadingEnabled() ? {
      'yt-create-comment-reply-action': 'createCommentReplyAction',
      'yt-remove-comment-action': 'removeCommentAction',
      'yt-ban-author-action': 'banAuthorAction',
      'yt-hide-reported-comment-action': 'hideReportedCommentAction',
    } : {};
  },

  /** @param {?Object} action */
  createCommentReplyAction(action) {
    const create = action && action.createCommentReplyAction;
    if (!create || !create.contents) return;
    const commentId = this.commentViewModel && this.commentViewModel.commentId;
    if (commentId === create.replyToCommentId || (commentId === create.parentCommentId && !create.replyToCommentId)) {
      this.maybeAttachReply(create.contents);
    }
  },

  /** @param {!Object} reply */
  maybeAttachReply(reply) {
    const level = (this.commentEntity && this.commentEntity.properties && this.commentEntity.properties.replyLevel) || 0;
    if (level >= 3) this.fire('yt-pushed-create-comment-reply', reply);
    else this.attachReply(reply);
  },

  /** @param {!CustomEvent} e */
  onPushedCreateCommentReply(e) {
    const level = (this.commentEntity && this.commentEntity.properties && this.commentEntity.properties.replyLevel) || 0;
    if (level >= 3) return;
    this.attachReply(e.detail);
    e.stopPropagation();
  },

  /** @param {!Object} reply */
  attachReply(reply) {
    if (!this.data) return;
    if (!this.data.replies) {
      this.data = Object.assign({}, this.data, {replies: {commentRepliesRenderer: {subThreads: [reply],
        viewReplies: {buttonRenderer: {text: {simpleText: 'View replies'}, icon: {iconType: 'EXPAND'}}}}}});
      this.expanded = true;
      return;
    }
    const renderer = this.data.replies.commentRepliesRenderer;
    if (!renderer) return;
    const subThreads = (renderer.subThreads || []).slice();
    const last = subThreads.length - 1;
    const button = subThreads[last] && subThreads[last].continuationItemRenderer;
    if (button) {
      if (last === 0) this.addedReplies = [...this.addedReplies, reply];
      else subThreads.splice(last, 0, reply);
    } else {
      subThreads.push(reply);
    }
    this.data = Object.assign({}, this.data, {replies: Object.assign({}, this.data.replies,
        {commentRepliesRenderer: Object.assign({}, renderer, {subThreads})})});
  },

  onAppendContinuationItemsActionFinished() {
    if (!this.addedReplies.length) return;
    const replies = this.data && this.data.replies;
    const renderer = replies && replies.commentRepliesRenderer;
    if (!renderer) return;
    const subThreads = [...this.addedReplies, ...(renderer.subThreads || [])];
    this.addedReplies = [];
    this.data = Object.assign({}, this.data, {replies: Object.assign({}, replies,
        {commentRepliesRenderer: Object.assign({}, renderer, {subThreads})})});
  },

  /** @param {?Object} action */
  removeCommentAction(action) {
    const remove = action && action.removeCommentAction;
    const id = remove && remove.commentId;
    if (id && this.commentViewModel && this.commentViewModel.commentId === id) this.maybeRemoveComment(remove.actionResult);
  },

  /** @param {?Object} action */
  banAuthorAction(action) {
    const ban = action && action.banAuthorAction;
    const id = ban && ban.commentId;
    if (id && this.commentViewModel && this.commentViewModel.commentId === id) this.maybeRemoveComment(ban.actionResult);
  },

  /** @param {?Object} action */
  hideReportedCommentAction(action) {
    const hide = action && action.hideReportedCommentAction;
    const id = hide && hide.commentId;
    if (id && this.commentViewModel && this.commentViewModel.commentId === id) this.maybeRemoveComment(hide.actionResult);
  },

  /** @param {?Object} result */
  maybeRemoveComment(result) {
    if (!result || result.status !== 'STATUS_SUCCEEDED') return;
    this.feedbackText = result.feedbackText || {simpleText: 'Reply removed'};
    this.removed = true;
  },

  attached() {
    if (this.isSubThread) this.expanded = true;
    const hitbox = this.commentThreadHitbox;
    if (!hitbox) return;
    hitbox.addEventListener('mouseover', () => {
      this.threadHovered = true;
    });
    hitbox.addEventListener('mouseout', () => {
      this.threadHovered = false;
    });
    hitbox.addEventListener('click', () => this.maybeToggleExpanded());
  },

  /** @param {!CustomEvent} e */
  onSubThreadsChanged(e) {
    this.subThreadsCount = e.detail.subThreadsLength;
  },

  onContinuationEmpty() {
    this.subThreadsCount = 0;
    if (this.data) this.data = Object.assign({}, this.data, {replies: null});
  },

  onDataChanged() {
    const model = this.data && this.data.commentViewModel && this.data.commentViewModel.commentViewModel;
    const id = model && model.commentId;
    const sameComment = !!id && id === this.lastCommentId;
    this.lastCommentId = id;
    if (!sameComment) {
      this.removed = false;
      this.feedbackText = undefined;
      this.addedReplies = [];
    }
    const replies = this.data && this.data.replies;
    const renderer = replies && replies.commentRepliesRenderer;
    this.subThreadsCount = (renderer && renderer.subThreads && renderer.subThreads.length) || 0;
    if (renderer) {
      const teasers = renderer.teaserContents;
      const hasContents = threadingEnabled() ? !!(renderer.subThreads && renderer.subThreads.length) :
        !!(renderer.contents && renderer.contents.length);
      if (teasers && teasers.length && !hasContents) {
        const first = {commentThreadRenderer: {commentViewModel: teasers[0]}};
        const copy = Object.assign({}, renderer);
        if (threadingEnabled()) copy.subThreads = [first];
        else copy.contents = [first];
        this.data = Object.assign({}, this.data, {replies: Object.assign({}, replies, {commentRepliesRenderer: copy})});
      }
    }
    if (!sameComment) this.expanded = this.isSubThread;
  },

  maybeToggleExpanded() {
    const subThreads = this.data && this.data.replies && this.data.replies.commentRepliesRenderer &&
        this.data.replies.commentRepliesRenderer.subThreads;
    const only = subThreads && subThreads.length === 1 ? subThreads[0] : null;
    if (only && only.continuationItemRenderer && only.continuationItemRenderer.button && this.expanded) return;
    this.toggleExpanded();
  },

  /**
   * @param {?Object} data
   * @return {?Object}
   */
  __compute__commentViewModel(data) {
    const vm = data && data.commentViewModel;
    return (vm && vm.commentViewModel) || null;
  },

  /** @return {boolean} */
  __compute__hasSubThreading() {
    return threadingEnabled() && this.subThreadsCount > 0;
  },
}, ['ytRendererBehavior', 'ytdReduxBehavior', 'ytActionHandlerBehavior', 'ytRendererstamperBehavior']));
