/**
 * @fileoverview Client-side interaction logging, shaped like YouTube's
 * logging client ("GEL") and visual-element (VE) logger.
 *
 * Transport: `logEvent` wraps a payload in an event with a timestamp and
 * activity context and stores it in an in-memory store keyed by
 * authorization and tier. A batch is sent once the store holds
 * `web_logging_max_batch` events, when the debounce timer
 * (`web_gel_debounce_ms`) fires with at least `gel_min_batch_size` events,
 * or when the queue's maximum timer (`gel_queue_timeout_max_ms`) fires.
 * Sending writes the batch to an IndexedDB queue, then serializes it with a
 * copy of the InnerTube context, measures and gzips it; the request itself
 * is dropped.
 *
 * Producers in this file: the visibility logger (`visualElementShown`,
 * `visualElementHidden`, with view data from layout reads), gestures,
 * scroll events (attention logging), the view-model component path that
 * registers VE containers and screen layers, and the ads control flow
 * (`adsClientStateChange`). `telemetry.js` has the timer-driven producers.
 */
import {onCleanup} from '../framework/vm/owner.js';
import {renderEffect, setComponentLoggingHook} from '../framework/vm/render.js';
import {Priority, later, schedule, track} from './scheduler.js';
import {innertubeContext, prepareBody} from './network.js';
import {flag, flagNumber, flagValue, getConfig, getObjectByName} from '../framework/flags.js';
import {rootInjector} from '../framework/injector.js';
import {wrapErrors} from '../framework/errors.js';
import {defaultVisibilityObserver, monitorTarget, monitorVisibility, setMonitorLogger, unmonitorVisibility} from './visibility.js';

/** Event counts for tools/verify.mjs: queued events and characters per payload name. */
const counters = {queued: 0, flushes: 0, kinds: {}, batchChars: 0};
/** @type {?} */ (window)['ytlLogCounters'] = counters;

// ---------------------------------------------------------------------------
// Screens

/** @type {!Map<number, string>} */
const screenNonces = new Map();
let lastActivityMs = Date.now();

/** @return {string} */
function makeNonce() {
  return btoa(String(Math.random())).replace(/=+$/, '');
}

/**
 * The client screen nonce of a screen layer.
 * @param {*=} layer
 * @return {?string}
 */
export function currentScreen(layer) {
  return screenNonces.get(typeof layer === 'number' ? layer : 0) || null;
}

/** Starts a new client screen, as on every navigation. */
export function newScreen() {
  const csn = makeNonce();
  screenNonces.set(0, csn);
  loggerFacade();
  wrapErrors(visibilityLogger().newScreen).bind(visibilityLogger())();
  logEvent('screenCreated', {csn, pageVe: {veType: 4724}});
}

/** Records user activity for the events' `lastActivityMs`. */
function noteActivity() {
  lastActivityMs = Date.now();
}
for (const type of ['click', 'keydown', 'scroll', 'mousemove']) window.addEventListener(type, noteActivity, {capture: true, passive: true});

// ---------------------------------------------------------------------------
// Transport

const LOG_EVENT_URL = '/youtubei/v1/log_event?alt=json';

/** The payload names the transport knows, with their field numbers. */
const PAYLOAD_NUMBERS = {
  latencyActionInfo: 7, latencyActionTicked: 5, latencyActionBaselined: 6, visualElementShown: 72,
  visualElementHidden: 73, visualElementGestured: 78, visualElementStateChanged: 208, screenCreated: 156,
  visualElementAttached: 215, foregroundHeartbeat: 80, scrollEvent: 284, adsClientStateChange: 197,
  streamzIncremented: 126, sliEventBatch: 344, latencyActionSpan: 289,
};

/**
 * @typedef {{auth: (string|undefined), isJspb: boolean, cttAuthInfo: string, tier: number}}
 */
let StoreKey;

/** @param {!StoreKey} key @return {string} */
function storeKeyString(key) {
  return [key.auth, key.isJspb, key.cttAuthInfo, key.tier].join('/');
}

/** Holds events until they are sent, keyed by authorization and tier. */
class PayloadStore {
  constructor() {
    /** @type {!Object<string, !Array<!Object>>} */
    this.store = {};
    this.totalEntries = 0;
    /** @type {!Object<string, !Array<string>>} */
    this.memoizedKeySequences = {};
  }

  /**
   * @param {!StoreKey} key
   * @param {!Object} payload
   * @return {string}
   */
  storePayload(key, payload) {
    const k = storeKeyString(key);
    if (this.store[k]) {
      this.store[k].push(payload);
    } else {
      this.memoizedKeySequences = {};
      this.store[k] = [payload];
    }
    this.totalEntries++;
    if (flag('more_accurate_gel_parser')) window.dispatchEvent(new CustomEvent('TRANSPORTING_NEW_EVENT'));
    return k;
  }

  /**
   * The store keys matching `key`; undefined fields match everything.
   * @param {!StoreKey} key
   * @return {!Array<string>}
   */
  matchingKeys(key) {
    const k = storeKeyString(key);
    if (this.memoizedKeySequences[k]) return this.memoizedKeySequences[k];
    const keys = Object.keys(this.store);
    const matches = (want, have) => want === undefined || want === 'undefined' || want === have;
    const out = [];
    for (const stored of keys) {
      const parts = stored.split('/');
      if (matches(key.auth, parts[0]) && matches(String(key.isJspb), parts[1]) && matches(key.cttAuthInfo, parts[2]) &&
          matches(JSON.stringify(key.tier), parts[3])) {
        out.push(stored);
      }
    }
    this.memoizedKeySequences[k] = out;
    return out;
  }

  /**
   * Removes and returns up to `sizeLimit` events, trying keys in order.
   * @param {!Array<!StoreKey>} keys
   * @param {number} sizeLimit
   * @return {!Array<!Object>}
   */
  smartExtractMatchingEntries(keys, sizeLimit) {
    const out = [];
    for (const key of keys) {
      for (const k of this.matchingKeys(key)) {
        const list = this.store[k];
        if (!list || out.length >= sizeLimit) continue;
        const room = sizeLimit - out.length;
        if (list.length <= room) {
          out.push(...list);
          delete this.store[k];
        } else {
          out.push(...list.splice(0, room));
        }
      }
    }
    this.totalEntries -= out.length;
    return out;
  }

  /**
   * @param {!StoreKey} key
   * @return {number}
   */
  getSequenceCount(key) {
    let n = 0;
    for (const k of this.matchingKeys(key)) n += (this.store[k] && this.store[k].length) || 0;
    return n;
  }
}

/** Per-queue timer state. */
class QueueState {
  constructor() {
    this.queueTimer = 0;
    this.queueMaxTimer = 0;
    this.lastDebounceQueueFromLogTimeMs = 0;
  }
}

const store = new PayloadStore();
/** @type {!Map<number, !QueueState>} */
const queues = new Map();
/** @type {!Object<string, boolean>} */
const pendingAuthKeys = {};
let maxBatchJob = 0;
let batchId = 0;
/** @type {?IDBDatabase} */
let db = null;
let sentBytes = 0;

/**
 * @param {number} tier
 * @return {!QueueState}
 */
function queueFor(tier) {
  let q = queues.get(tier);
  if (!q) queues.set(tier, q = new QueueState());
  return q;
}

/**
 * Opens the IndexedDB log queue. Called once at startup.
 * @return {!Promise<void>}
 */
export function openLogQueue() {
  return new Promise((resolve) => {
    const req = indexedDB.open('ytl-logs', 2);
    req.onupgradeneeded = () => {
      if (req.result.objectStoreNames.contains('batches')) req.result.deleteObjectStore('batches');
      req.result.createObjectStore('batches', {keyPath: 'id', autoIncrement: true});
    };
    req.onsuccess = () => {
      db = req.result;
      const tx = db.transaction('batches', 'readwrite');
      tx.objectStore('batches').clear();
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve();
    };
    req.onerror = () => resolve();
  });
}

/**
 * @typedef {{
 *   timestamp: (number|undefined),
 *   sequenceGroup: (string|undefined),
 *   endOfSequence: (boolean|undefined),
 *   sendIsolatedPayload: (boolean|undefined),
 *   cttAuthInfo: (?Object|undefined),
 *   automatedLogEventSource: (number|undefined),
 * }}
 */
let LogOptions;

/** @type {!Object<string, number>} */
const sequenceIndexes = {};

/**
 * Logs one event: `{eventTimeMs, [name]: payload, context}`.
 * @param {string} name
 * @param {!Object} payload
 * @param {!LogOptions=} options
 */
export function logEvent(name, payload, options = {}) {
  if (getConfig('ytLoggingEventsDefaultDisabled', false)) return;
  const event = {};
  const t = Math.round(options.timestamp || performance.timeOrigin + performance.now());
  event.eventTimeMs = t < Number.MAX_SAFE_INTEGER ? t : 0;
  event[name] = payload;
  event.context = {lastActivityMs: String(options.timestamp || !isFinite(lastActivityMs) ? -1 : Date.now() - lastActivityMs)};
  if (options.sequenceGroup && !flag('web_gel_sequence_info_killswitch')) {
    const group = options.sequenceGroup;
    sequenceIndexes[group] = group in sequenceIndexes ? sequenceIndexes[group] + 1 : 0;
    event.context.sequence = {index: sequenceIndexes[group], groupKey: group};
    if (options.endOfSequence) delete sequenceIndexes[group];
  }
  if (flag('web_tag_automated_log_events')) event.context.automatedLogEventSource = options.automatedLogEventSource;
  countEvent(name, payload);
  if (options.sendIsolatedPayload) sendIsolated(event);
  else storeEvent(event);
}

/**
 * @param {string} name
 * @param {!Object} payload
 */
function countEvent(name, payload) {
  counters.queued++;
  const k = counters.kinds[name] || (counters.kinds[name] = {count: 0, chars: 0});
  k.count++;
  k.chars += JSON.stringify(payload).length;
}

/**
 * The payload name of an event: its first key the transport knows.
 * @param {!Object} event
 * @return {string}
 */
function payloadNameOf(event) {
  for (const k of Object.keys(event)) if (PAYLOAD_NUMBERS[k]) return k;
  return '';
}

/**
 * The global config service. Creating it publishes the page's hot config
 * group at `yt.gcf.config.hotConfigGroup`.
 */
class GlobalConfigService {
  constructor() {
    const w = /** @type {?} */ (window);
    const yt = w.yt || (w.yt = {});
    const gcf = yt.gcf || (yt.gcf = {});
    const config = gcf.config || (gcf.config = {});
    config.hotConfigGroup = getConfig('RAW_HOT_CONFIG_GROUP') || null;
  }
}
/** @type {?} */ (GlobalConfigService)['ɵprov'] = {providedIn: 'root', factory: () => new GlobalConfigService()};

/** @return {?Object} */
function hotConfigGroup() {
  const group = getObjectByName('yt.gcf.config.hotConfigGroup');
  return /** @type {?Object} */ (group != null ? group : getConfig('RAW_HOT_CONFIG_GROUP'));
}

/**
 * The payload policy of a payload name in the hot config, looked up per
 * event.
 * @param {string} name
 * @return {?{payloadNumber: number, enabled: (boolean|undefined), tier: (string|undefined)}|undefined}
 */
function payloadPolicyOf(name) {
  if (!flag('enable_web_tiered_gel')) return undefined;
  const number = PAYLOAD_NUMBERS[name || ''];
  let policies;
  if (rootInjector.resolve(GlobalConfigService) != null) {
    const group = /** @type {?} */ (hotConfigGroup());
    const logging = group == null ? undefined : group.loggingHotConfig;
    const events = logging == null ? undefined : logging.eventLoggingConfig;
    policies = events == null ? undefined : events.payloadPolicies;
  }
  if (policies) {
    for (let i = 0; i < policies.length; i++) if (policies[i].payloadNumber === number) return policies[i];
  }
  return undefined;
}

/**
 * @param {string|undefined} tier
 * @return {number}
 */
function tierNumber(tier) {
  switch (tier) {
    case 'DELAYED_EVENT_TIER_UNSPECIFIED': return 0;
    case 'DELAYED_EVENT_TIER_DEFAULT': return 100;
    case 'DELAYED_EVENT_TIER_DISPATCH_TO_EMPTY': return 200;
    case 'DELAYED_EVENT_TIER_FAST': return 300;
    case 'DELAYED_EVENT_TIER_IMMEDIATE': return 400;
    default: return 200;
  }
}

/**
 * Collects payloads for tests when payload scraping is on.
 * @param {!Object} event
 */
function scrapeForTest(event) {
  const w = /** @type {?} */ (window);
  if (!(w.yt && w.yt.logging && w.yt.logging.transport && w.yt.logging.transport.enableScrapingForTest)) {
    if (flagValue('il_payload_scraping') !== 'enable_il_payload_scraping') return;
  }
  (w.ytlScrapedPayloads || (w.ytlScrapedPayloads = [])).push(event);
}

/**
 * A transport timer. YouTube's is a delayed scheduler job when
 * `transport_use_scheduler` is on; ours is always a plain timer, which the
 * benchmark does not wait for.
 * @param {function()} fn
 * @param {number} ms
 * @return {number}
 */
function transportTimer(fn, ms) {
  const viaScheduler = flag('transport_use_scheduler') !== false;
  const avoidNavigation = viaScheduler && (flag('logging_avoid_blocking_during_navigation') || flag('lr_logging_avoid_blocking_during_navigation'));
  return setTimeout(avoidNavigation ? () => schedule(fn, Priority.IDLE) : fn, ms);
}

/** @param {number} id */
function clearTransportTimer(id) {
  flag('transport_use_scheduler');
  clearTimeout(id);
}

/** @param {!Object} event */
function storeEvent(event) {
  scrapeForTest(event);
  const name = payloadNameOf(event);
  const policy = payloadPolicyOf(name);
  let tier = 200;
  if (policy) {
    if (policy.enabled === false && !flag('web_payload_policy_disabled_killswitch')) return;
    tier = tierNumber(policy.tier);
    if (tier === 400) {
      sendIsolated(event);
      return;
    }
  }
  const auth = '';
  pendingAuthKeys[auth] = true;
  const key = {auth: undefined, isJspb: false, cttAuthInfo: auth, tier};
  store.storePayload(key, event);
  scheduleFlush(key, name === 'gelDebuggingEvent');
}

/**
 * @param {!StoreKey} key
 * @param {boolean} debugging
 */
function scheduleFlush(key, debugging) {
  const max = flagNumber('tvhtml5_logging_max_batch_ads_fork') || flagNumber('tvhtml5_logging_max_batch') ||
      flagNumber('web_logging_max_batch') || 100;
  const now = performance.now();
  const q = queueFor(key.tier);
  const count = store.getSequenceCount(key);
  if (count >= 1000) {
    flushQueue(key.tier);
  } else if (count >= max) {
    if (!maxBatchJob) {
      maxBatchJob = schedule(() => {
        maxBatchJob = 0;
        flushQueue(key.tier);
      }, Priority.IDLE);
    }
  } else if (now - q.lastDebounceQueueFromLogTimeMs >= 10) {
    debounceQueue(key.tier);
    q.lastDebounceQueueFromLogTimeMs = now;
  }
}

const INITIAL_BATCH_TIMEOUT_MS = flagNumber('initial_gel_batch_timeout', 2000);
const QUEUE_TIMEOUT_MAX_MS = flagNumber('gel_queue_timeout_max_ms', 60000);
const MIN_BATCH_SIZE = flagNumber('gel_min_batch_size', 5);

/** @param {number} tier */
function debounceQueue(tier) {
  const q = queueFor(tier);
  if (flag('web_gel_timeout_cap') && !q.queueMaxTimer) {
    q.queueMaxTimer = transportTimer(() => flushQueue(tier), tier === 300 ? 5000 : QUEUE_TIMEOUT_MAX_MS);
  }
  clearTransportTimer(q.queueTimer);
  let ms = /** @type {number} */ (getConfig('LOGGING_BATCH_TIMEOUT', flagNumber('web_gel_debounce_ms', 10000)));
  if (flag('shorten_initial_gel_batch_timeout') && !batchId) ms = INITIAL_BATCH_TIMEOUT_MS;
  q.queueTimer = transportTimer(() => {
    if (flagNumber('gel_min_batch_size') > 0) {
      if (store.getSequenceCount({auth: undefined, isJspb: false, cttAuthInfo: undefined, tier}) >= MIN_BATCH_SIZE) flushQueue(tier);
    } else {
      flushQueue(tier);
    }
  }, ms);
}

/**
 * Sends everything queued for `tier` (300 and 200 together when tiers are
 * on), one batch per authorization key.
 * @param {number} tier
 * @param {boolean=} writeThenSend
 */
function flushQueue(tier, writeThenSend = true) {
  const q = queueFor(tier);
  clearTransportTimer(q.queueTimer);
  clearTransportTimer(q.queueMaxTimer);
  q.queueTimer = 0;
  q.queueMaxTimer = 0;
  if (flag('enable_web_tiered_gel') && flag('web_vss_routing_check_all_tier_policies')) {
    queueFor(300);
    queueFor(200);
  }
  const batches = new Map();
  for (const auth of Object.keys(pendingAuthKeys)) {
    const keys = flag('enable_web_tiered_gel') ?
        [{auth: undefined, isJspb: false, cttAuthInfo: auth, tier}, {auth: undefined, isJspb: false, cttAuthInfo: auth, tier: undefined}] :
        [{auth: undefined, isJspb: false, cttAuthInfo: auth, tier: undefined}];
    const events = store.smartExtractMatchingEntries(/** @type {!Array<!StoreKey>} */ (keys), 1000);
    if (events.length) batches.set(auth, events);
    if ((flag('web_fp_via_jspb_and_json') && writeThenSend) || !flag('web_fp_via_jspb_and_json')) delete pendingAuthKeys[auth];
  }
  for (const [auth, events] of batches) sendBatch(auth, events, {writeThenSend: true});
}

/**
 * The batch counter of the serialized client event id.
 * @return {number}
 */
function nextBatchCounter() {
  let n = Number(getConfig('BATCH_CLIENT_COUNTER', 0)) || 0;
  if (!n) n = Math.floor(Math.random() * 65535 / 2);
  n++;
  if (n > 65535) n = 1;
  const cfg = /** @type {?} */ (window).yt && /** @type {?} */ (window).yt.config_;
  if (cfg) cfg['BATCH_CLIENT_COUNTER'] = n;
  return n;
}

/**
 * @param {string} auth
 * @param {!Array<!Object>} events
 * @param {{writeThenSend: boolean}} options
 */
function sendBatch(auth, events, options) {
  counters.flushes++;
  const request = {context: innertubeContext()};
  if (!Array.isArray(events) && !flag('throw_err_when_logevent_malformed_killswitch')) return;
  request.events = events;
  if (!flag('use_request_time_ms_header')) request.requestTimeMs = String(Math.round(performance.timeOrigin + performance.now()));
  if (flag('unsplit_gel_payloads_in_logs')) request.unsplitGelPayloadsInLogs = true;
  const eventId = /** @type {?string} */ (getConfig('EVENT_ID'));
  if (auth !== 'visitorOnlyApprovedKey' && eventId) {
    request.serializedClientEventId = {serializedEventId: eventId, clientCounter: String(nextBatchCounter())};
  }
  if (flag('always_send_and_write')) options.writeThenSend = false;
  const batch = {id: ++batchId, request, compress: flag('compress_gel') || flag('compress_gel_lr'), dbId: undefined};
  if (flag('use_request_time_ms_header')) batch.requestTimeHeader = JSON.stringify(Math.round(performance.timeOrigin + performance.now()));
  if (!db || !options.writeThenSend || !flag('networkless_logging')) {
    send(batch);
    return;
  }
  const record = {url: LOG_EVENT_URL, options: {method: 'POST', postParams: request, postBodyFormat: '', compress: batch.compress},
    timestamp: Date.now(), status: 'NEW', sendCount: 0};
  const tx = db.transaction('batches', 'readwrite');
  const put = tx.objectStore('batches').add(record);
  track(new Promise((resolve) => {
    tx.oncomplete = () => {
      record.id = put.result;
      batch.dbId = /** @type {number} */ (put.result);
      send(batch);
      resolve(null);
    };
    tx.onerror = () => {
      send(batch);
      resolve(null);
    };
  }));
}

/** @param {!Object} event */
function sendIsolated(event) {
  sendBatch('', [event], {writeThenSend: false});
}

/** @param {{id: number, request: !Object, compress: boolean, dbId: (number|undefined)}} batch */
function send(batch) {
  const body = JSON.stringify(batch.request);
  counters.batchChars += body.length;
  const prepared = batch.compress ? prepareBody(body) : {body};
  sentBytes += typeof prepared.body === 'string' ? prepared.body.length : prepared.body.byteLength;
  if (db && batch.dbId) {
    const tx = db.transaction('batches', 'readwrite');
    tx.objectStore('batches').delete(batch.dbId);
  }
  if (flag('start_client_gcf')) schedule(() => readGlobalConfig(batch.request), Priority.IDLE);
}

/**
 * Reads the global config group of a logging response (the response is
 * empty here, so this finds nothing).
 * @param {!Object} request
 */
function readGlobalConfig(request) {
  const rc = /** @type {?} */ (request).responseContext;
  const group = rc && rc.globalConfigGroup;
  if (group && group.hotHashData) console.info('hot config', group.hotHashData.length);
}

/** @return {number} */
export function loggedBytes() {
  return sentBytes;
}

// ---------------------------------------------------------------------------
// Visual elements

/** A visual element: server-provided (tracking params) or client-side. */
export class VisualElement {
  /** @param {!Object} veData */
  constructor(veData) {
    /** @const {!Object} */
    this.veData = veData;
  }

  /** @return {!Object} */
  getAsJson() {
    const out = {};
    if (this.veData.trackingParams !== undefined) {
      out.trackingParams = this.veData.trackingParams;
    } else {
      out.veType = this.veData.veType;
      if (this.veData.veCounter !== undefined) out.veCounter = this.veData.veCounter;
      if (this.veData.elementIndex !== undefined) out.elementIndex = this.veData.elementIndex;
    }
    if (this.veData.dataElement !== undefined) out.dataElement = this.veData.dataElement.getAsJson();
    if (this.veData.youtubeData !== undefined) out.youtubeData = this.veData.youtubeData;
    if (this.veData.isCounterfactual) out.isCounterfactual = true;
    return out;
  }

  /** @return {boolean} */
  isClientVe() {
    return !this.veData.trackingParams && !!this.veData.veType;
  }
}

let veCounter = 1;

/**
 * @param {string} trackingParams
 * @return {!VisualElement}
 */
export function veFromTrackingParams(trackingParams) {
  return new VisualElement({trackingParams});
}

/**
 * Creates the VE of a server-side tracking params string and attaches it to
 * the screen (`graftServerVe`).
 * @param {string} trackingParams
 * @param {string=} csn
 * @return {!VisualElement}
 */
export function graftServerVe(trackingParams, csn) {
  const ve = veFromTrackingParams(trackingParams);
  noteVeAttach(ve, csn || currentScreen());
  return ve;
}

/**
 * Logs a change of a server VE's state, such as its position in a grid.
 * @param {string} csn
 * @param {string} trackingParams
 * @param {!Object} clientData
 */
export function logVisualElementStateChanged(csn, trackingParams, clientData) {
  logEvent('visualElementStateChanged', {csn, ve: veFromTrackingParams(trackingParams).getAsJson(), clientData});
}

/**
 * A client VE from a `clientVeSpec`.
 * @param {!Object} spec
 * @return {!VisualElement}
 */
export function clientVe(spec) {
  return new VisualElement({veType: spec.uiType, veCounter: veCounter++, elementIndex: spec.elementIndex,
    youtubeData: spec.clientYoutubeData});
}

/**
 * The tracking params of renderer or view-model data.
 * @param {*} data
 * @return {string|undefined}
 */
export function trackingParamsOf(data) {
  const d = /** @type {?} */ (data);
  if (d && d.rendererContext) {
    const lc = d.rendererContext.loggingContext;
    if (lc && lc.loggingDirectives && lc.loggingDirectives.trackingParams) return lc.loggingDirectives.trackingParams;
  }
  if (d && d.loggingDirectives && d.loggingDirectives.trackingParams) return d.loggingDirectives.trackingParams;
  return d == null ? undefined : d.trackingParams;
}

/**
 * The parent of `node` for VE purposes: its parent element, the host of its
 * shadow root, or window.
 * @param {*} node
 * @return {*}
 */
function veParentOf(node) {
  if (node === window) return null;
  const parent = node.parentElement;
  if (parent) return parent;
  if (typeof ShadowRoot !== 'undefined' && node.getRootNode) {
    const root = node.getRootNode();
    if (root instanceof ShadowRoot) return root.host;
  }
  return window;
}

/**
 * @param {*} el
 * @return {string|undefined}
 */
function elementTrackingParams(el) {
  const data = el.data;
  if (flag('il_use_view_model_logging_context') && data && data.context && data.context.loggingContext &&
      data.context.loggingContext.loggingDirectives && data.context.loggingContext.loggingDirectives.trackingParams) {
    return data.context.loggingContext.loggingDirectives.trackingParams;
  }
  if (data && data.rendererContext && data.rendererContext.loggingContext &&
      data.rendererContext.loggingContext.loggingDirectives && data.rendererContext.loggingContext.loggingDirectives.trackingParams) {
    return data.rendererContext.loggingContext.loggingDirectives.trackingParams;
  }
  if (data && data.loggingDirectives && data.loggingDirectives.trackingParams) return data.loggingDirectives.trackingParams;
  if (el.veContainer && el.veContainer.trackingParams) return el.veContainer.trackingParams;
  return data == null ? undefined : data.trackingParams;
}

/**
 * The VE of an element, if it has one.
 * @param {*} el
 * @return {?VisualElement|undefined}
 */
function elementVe(el) {
  if (el.visualElement) return el.visualElement;
  const tp = elementTrackingParams(el);
  if (tp) return veFromTrackingParams(tp);
  return undefined;
}

/**
 * @param {*} el
 * @return {?VisualElement|undefined}
 */
function nearestVe(el) {
  if (!(el instanceof HTMLElement)) return undefined;
  let ve;
  for (let n = el; n && n !== window && !(ve = elementVe(n)); n = veParentOf(n)) {}
  return ve;
}

// ---------------------------------------------------------------------------
// Renderer and VE-container registry, screen layers

/** The data of a registered element, under this key in its entry. */
export const RENDERER_DATA = Symbol('rendererData');

/** @type {!WeakMap<!Element, !Object>} */
const rendererEntries = new WeakMap();

/**
 * @param {*} el
 * @return {?Object|undefined}
 */
export function rendererEntry(el) {
  return rendererEntries.get(el);
}

/**
 * @param {!Element} el
 * @param {!Object} entry
 */
export function setRendererEntry(el, entry) {
  rendererEntries.set(el, entry);
}

/** @param {!Element} el */
export function deleteRendererEntry(el) {
  rendererEntries.delete(el);
}

/** A node in the tree of screen layers that renderers log into. */
export class ScreenLayerNode {
  /** @param {number=} layer */
  constructor(layer) {
    /** @type {number|undefined} */
    this.layer = layer;
    /** @type {?ScreenLayerNode|undefined} */
    this.parent = undefined;
  }

  /** @param {!ScreenLayerNode} parent */
  setParent(parent) {
    this.parent = parent;
  }
}

/**
 * The layer of a node: its own, else its parent's, else 0 (cached).
 * @param {!ScreenLayerNode} node
 * @return {number}
 */
export function layerOf(node) {
  if (node.layer !== undefined) return node.layer;
  if (node.parent) return layerOf(node.parent);
  return node.layer = 0;
}

/**
 * The nearest element above `el` that is registered as a renderer,
 * crossing shadow roots.
 * @param {!Node} el
 * @return {?Element}
 */
export function nearestRendererAbove(el) {
  for (let n = el.parentNode; n;) {
    if (n instanceof Element) {
      const entry = rendererEntries.get(n);
      const target = monitorTarget(n);
      if ((entry && entry.isRenderer) || target.isRenderer_) return n;
    }
    if (n.parentNode) n = n.parentNode;
    else if (flag('web_fix_shadow_root_undefined') && typeof ShadowRoot === 'undefined') n = null;
    else n = n instanceof ShadowRoot ? n.host : null;
  }
  return null;
}

/**
 * Gives `el` a layer node and a `getScreenLayer` that reads it.
 * @param {!Element} el
 * @param {!ScreenLayerNode} node
 */
function attachLayerNode(el, node) {
  const entry = rendererEntries.get(el) || {layerNode: node};
  entry.layerNode = node;
  rendererEntries.set(el, entry);
  /** @type {?} */ (el).getScreenLayer = () => layerOf(entry.layerNode);
}

/**
 * Links `el`'s layer node into the tree of renderers above it, until a
 * node that already has a parent.
 * @param {!Element} el
 * @return {!ScreenLayerNode}
 */
function linkLayerNodes(el) {
  const own = rendererEntries.get(el);
  const node = own && own.layerNode ? own.layerNode : new ScreenLayerNode();
  attachLayerNode(el, node);
  let child = node;
  for (let n = /** @type {?Element} */ (el); n;) {
    n = nearestRendererAbove(n);
    const entry = n ? rendererEntries.get(n) : undefined;
    if (!n || !entry) break;
    child.setParent(entry.layerNode);
    attachLayerNode(n, entry.layerNode);
    if (entry.layerNode.parent) break;
    child = entry.layerNode;
  }
  return node;
}

// ---------------------------------------------------------------------------
// The visibility logger

/**
 * @param {*} el
 * @return {*}
 */
function loggableData(el) {
  let data = el.data || (el.props ? el.props.data : undefined);
  if (!data || el.isWebComponentWrapper) {
    const entry = rendererEntries.get(el);
    data = entry ? entry[RENDERER_DATA] : undefined;
  }
  return data;
}

/**
 * The visibility types of an element's logging directives: 1 shown once,
 * 2 hidden once, 4 shown every time, 8 hidden every time.
 * @param {*} el
 * @return {number}
 */
function visibilityTypes(el) {
  const d = loggableData(el);
  return Math.floor(Number(d && d.loggingDirectives && d.loggingDirectives.visibility && d.loggingDirectives.visibility.types || '')) || 1;
}

/**
 * @param {*} el
 * @return {boolean}
 */
function hasLoggingDirectives(el) {
  const d = loggableData(el);
  return !(d == null || !d.loggingDirectives);
}

/** Whether attention logging (scroll events, view data) is installed. */
let attentionLogging = false;

/**
 * Reports VEs as shown and hidden, deduplicated per screen.
 */
class VisibilityLogger {
  constructor() {
    /** @const {!Set<*>} */
    this.shownElements = new Set();
    /** @const {!Set<*>} */
    this.hiddenElements = new Set();
    /** @const {!Map<*, boolean>} */
    this.visibleState = new Map();
    /** @type {?string} */
    this.csn = null;
  }

  newScreen() {
    this.clear();
    this.csn = currentScreen();
  }

  clear() {
    this.shownElements.clear();
    this.hiddenElements.clear();
    this.visibleState.clear();
    this.csn = null;
  }

  /**
   * @param {*} el
   * @return {string}
   */
  getTrackingParams(el) {
    const d = loggableData(el);
    if (flag('il_use_view_model_logging_context') && d && d.context && d.context.loggingContext && d.context.loggingContext.loggingDirectives) {
      return d.context.loggingContext.loggingDirectives.trackingParams || '';
    }
    if (d && d.rendererContext && d.rendererContext.loggingContext && d.rendererContext.loggingContext.loggingDirectives) {
      return d.rendererContext.loggingContext.loggingDirectives.trackingParams || '';
    }
    if (d && d.loggingDirectives) return d.loggingDirectives.trackingParams || '';
    if (el.veContainer && el.veContainer.trackingParams) return el.veContainer.trackingParams;
    return (d && d.trackingParams) || '';
  }

  /**
   * @param {*} el
   * @param {number} gesture
   * @return {boolean}
   */
  elementShouldLogGesture(el, gesture) {
    const d = loggableData(el);
    return !!((Math.floor(Number(d && d.loggingDirectives && d.loggingDirectives.gestures && d.loggingDirectives.gestures.types || '')) || 0) & gesture);
  }

  /**
   * @param {*} el
   * @return {?VisualElement}
   */
  getNearestParentVe(el) {
    const tp = this.getTrackingParams(el);
    if (el.visualElement) return el.visualElement;
    if (tp) return veFromTrackingParams(tp);
    if (flag('wiz_next_client_ve_parent_fix')) {
      const p = veParentOf(el);
      return p && p !== window ? this.getNearestParentVe(p) : null;
    }
    return el.parentElement ? this.getNearestParentVe(el.parentElement) : null;
  }

  /**
   * The csn to log into, or null when the logger is behind the screen.
   * @param {*} el
   * @param {*} layer
   * @return {?string}
   * @private
   */
  screenFor_(el, layer) {
    const csn = currentScreen(layer);
    if (this.csn === null || csn === this.csn || layer) return csn;
    console.warn('VisibilityLogger called before newScreen', el.localName, this.csn, csn);
    return null;
  }

  /**
   * @param {*} el
   * @return {!Object}
   * @private
   */
  viewData_(el) {
    let target = el;
    if (target && typeof target.getBoundingClientRect !== 'function' && target.hostElement) target = target.hostElement;
    if (!target || typeof target.getBoundingClientRect !== 'function') {
      return {originXPoints: 0, originYPoints: 0, widthPoints: 0, heightPoints: 0, position: 'POSITION_UNSPECIFIED'};
    }
    const rect = target.getBoundingClientRect();
    let position = 'POSITION_UNSPECIFIED';
    const style = window.getComputedStyle ? window.getComputedStyle(target) : null;
    if (style && style.position === 'fixed') {
      position = 'POSITION_FIXED';
    } else {
      for (let n = veParentOf(target); n && n !== window;) {
        if (typeof n.getBoundingClientRect !== 'function') {
          if (n.hostElement) {
            n = n.hostElement;
            continue;
          }
          break;
        }
        const s = window.getComputedStyle ? window.getComputedStyle(n) : null;
        if (s && s.position === 'fixed') {
          position = 'POSITION_FIXED';
          break;
        }
        if (elementVe(n)) break;
        n = veParentOf(n);
      }
    }
    return {originXPoints: Math.round(rect.left), originYPoints: Math.round(rect.top), widthPoints: Math.round(rect.width),
      heightPoints: Math.round(rect.height), position};
  }

  /**
   * @param {*} el
   * @param {*} unused
   * @param {*} layer
   * @param {number=} source
   */
  reportShown(el, unused, layer, source) {
    const tp = this.getTrackingParams(el);
    const key = el.visualElement ? el.visualElement : tp;
    const wasShown = key ? this.shownElements.has(key) : false;
    const visible = key ? this.visibleState.get(key) : false;
    if (key && wasShown && visible) return;
    if (key) {
      this.shownElements.add(key);
      this.visibleState.set(key, true);
    }
    if (el.impressionLog && !wasShown) el.impressionLog();
    if (!tp && !el.visualElement) return;
    const csn = this.screenFor_(el, layer);
    if (!csn) return;
    const directives = hasLoggingDirectives(el);
    const types = visibilityTypes(el);
    if (!types && !directives) return;
    const ve = el.visualElement ? el.visualElement : veFromTrackingParams(tp);
    if (!el.interactionLoggingClientData) el.interactionLoggingClientData = {};
    const clientData = el.interactionLoggingClientData;
    if (attentionLogging) clientData.viewData = this.viewData_(el);
    if (directives || wasShown) {
      if (types & 4) {
        if (!visible) logVeEvent('visualElementShown', csn, ve, 4, clientData);
      } else if (types & 1 && !wasShown) {
        logVeEvent('visualElementShown', csn, ve, 1, clientData, source);
      }
    } else {
      logVeEvent('visualElementShown', csn, ve, 1, clientData, source);
    }
  }

  /**
   * @param {*} el
   * @param {*} unused
   * @param {*} layer
   * @param {number=} source
   * @return {boolean}
   */
  reportHidden(el, unused, layer, source) {
    const tp = this.getTrackingParams(el);
    const key = el.visualElement ? el.visualElement : tp;
    const wasHidden = this.hiddenElements.has(key);
    const visible = this.visibleState.get(key);
    this.hiddenElements.add(key);
    this.visibleState.set(key, false);
    if (visible === false) return true;
    if (!tp && !el.visualElement) return false;
    const csn = this.screenFor_(el, layer);
    if (!csn || (!visibilityTypes(el) && hasLoggingDirectives(el))) return false;
    const ve = el.visualElement ? el.visualElement : veFromTrackingParams(tp);
    const types = visibilityTypes(el);
    if (types & 8) logVeEvent('visualElementHidden', csn, ve, 8, undefined, source);
    else if (types & 2 && !wasHidden) logVeEvent('visualElementHidden', csn, ve, 2, undefined, source);
    return true;
  }
}

/**
 * @param {string} name
 * @param {string} csn
 * @param {!VisualElement} ve
 * @param {number} eventType
 * @param {?Object=} clientData
 * @param {number=} source
 */
function logVeEvent(name, csn, ve, eventType, clientData, source) {
  if (name === 'visualElementShown') noteVeAttach(ve, csn);
  const payload = {csn, ve: ve.getAsJson(), eventType};
  if (clientData) payload.clientData = clientData;
  const options = {automatedLogEventSource: source};
  if (flag('log_sequence_info_on_gel_web')) options.sequenceGroup = csn;
  logEvent(name, payload, options);
}

/** @type {!Map<string, boolean>} */
const shownVeKeys = new Map();

/**
 * Notes a VE as shown, for client VEs that attach only when shown.
 * @param {!VisualElement} ve
 * @param {string} csn
 */
function noteVeAttach(ve, csn) {
  if (!flag('no_client_ve_attach_unless_shown')) return;
  const json = ve.getAsJson();
  shownVeKeys.set(`${json.veType}${json.veCounter}${csn}`, true);
}

/** @type {?VisibilityLogger} */
let logger = null;

/** @return {!VisibilityLogger} */
export function visibilityLogger() {
  if (!logger) logger = new VisibilityLogger();
  return logger;
}

/**
 * The public face of the visibility logger, as YouTube's: every call wraps
 * the logger's method with `wrapErrors` and binds it to the logger.
 */
class LoggerFacade {
  clear() {
    wrapErrors(visibilityLogger().clear).bind(visibilityLogger())();
  }

  /**
   * @param {*} el
   * @param {*=} unused
   * @param {*=} layer
   * @param {number=} source
   */
  reportShown(el, unused, layer, source) {
    wrapErrors(visibilityLogger().reportShown).bind(visibilityLogger())(el, unused, layer, source);
  }

  /**
   * @param {*} el
   * @param {*=} unused
   * @param {*=} layer
   * @param {number=} source
   * @return {*}
   */
  reportHidden(el, unused, layer, source) {
    return wrapErrors(visibilityLogger().reportHidden).bind(visibilityLogger())(el, unused, layer, source);
  }
}

/** @type {?LoggerFacade} */
let facade = null;

/** @return {!LoggerFacade} */
export function loggerFacade() {
  if (!facade) facade = new LoggerFacade();
  return facade;
}

/**
 * @param {!LoggerFacade} f
 * @param {*} el
 * @return {string}
 */
export function facadeTrackingParams(f, el) {
  return /** @type {string} */ (wrapErrors(visibilityLogger().getTrackingParams).bind(visibilityLogger())(el));
}

/**
 * @param {!LoggerFacade} f
 * @param {*} el
 * @return {?VisualElement}
 */
function facadeNearestParentVe(f, el) {
  return /** @type {?VisualElement} */ (wrapErrors(visibilityLogger().getNearestParentVe).bind(visibilityLogger())(el));
}

/**
 * @param {*} el
 * @param {number} gesture
 * @return {boolean}
 */
export function shouldLogGesture(el, gesture) {
  return !!wrapErrors(visibilityLogger().elementShouldLogGesture).bind(visibilityLogger())(el, gesture);
}

setMonitorLogger({
  reportShown: (el, u, layer, source) => loggerFacade().reportShown(el, u, layer, source),
  reportHidden: (el, u, layer, source) => loggerFacade().reportHidden(el, u, layer, source),
  currentScreen,
  trackingParamsOf,
  graftClientVe: (spec) => clientVe(spec),
});

// ---------------------------------------------------------------------------
// Gestures and scroll events

/**
 * Logs a gesture on a VE.
 * @param {string} csn
 * @param {!VisualElement} ve
 * @param {string=} gestureType
 * @param {?Object=} clientData
 */
export function logGesture(csn, ve, gestureType, clientData) {
  noteVeAttach(ve, csn);
  const payload = {csn, ve: ve.getAsJson(), gestureType: gestureType || 'INTERACTION_LOGGING_GESTURE_TYPE_GENERIC_CLICK'};
  if (clientData) payload.clientData = clientData;
  const options = {};
  if (flag('log_sequence_info_on_gel_web')) options.sequenceGroup = csn;
  logEvent('visualElementGestured', payload, options);
}

/** @param {string} trackingParams */
export function logClick(trackingParams) {
  const csn = currentScreen();
  if (trackingParams && csn) logGesture(csn, veFromTrackingParams(trackingParams));
}

/** @type {!WeakMap<!EventTarget, {fire: function()}>} */
const scrollThrottles = new WeakMap();
/** @type {!WeakMap<!EventTarget, {scrollTop: number, scrollLeft: number}>} */
const scrollPositions = new WeakMap();

/**
 * A throttle: runs `fn` at once, then at most once per `ms`, with a
 * trailing run for calls made in between.
 * @param {function()} fn
 * @param {number} ms
 * @return {{fire: function()}}
 */
function throttle(fn, ms) {
  let timer = 0;
  let pending = false;
  const onTimer = () => {
    timer = 0;
    if (pending) {
      pending = false;
      timer = setTimeout(onTimer, ms);
      fn();
    }
  };
  return {
    fire() {
      if (timer) {
        pending = true;
        return;
      }
      timer = setTimeout(onTimer, ms);
      fn();
    },
  };
}

/** @param {!Event} e */
function onScrollCapture(e) {
  const target = e.target;
  if (!(target instanceof HTMLElement || target instanceof Document)) return;
  const ms = flagNumber('web_attention_logging_scroll_throttle', 500);
  let t = scrollThrottles.get(target);
  if (!t) {
    t = throttle(() => {
      const pos = target instanceof Document ? {top: window.scrollY, left: window.scrollX} :
          {top: target.scrollTop, left: target.scrollLeft};
      const last = scrollPositions.get(target);
      if (!last) {
        scrollPositions.set(target, {scrollTop: pos.top, scrollLeft: pos.left});
        return;
      }
      const dy = pos.top - last.scrollTop;
      const dx = pos.left - last.scrollLeft;
      if (dy === 0 && dx === 0) return;
      const ve = nearestVe(target);
      scrollPositions.set(target, {scrollTop: pos.top, scrollLeft: pos.left});
      const csn = currentScreen();
      if (!csn) return;
      const vertical = Math.abs(dy) >= Math.abs(dx);
      const payload = {clientScreenNonce: csn};
      if (ve) payload.ve = ve.getAsJson();
      if (vertical && dy !== 0) {
        payload.orientation = 'SCROLL_ORIENTATION_VERTICAL';
        payload.startContentOffsetPoints = Math.round(last.scrollTop);
        payload.netDisplacementPoints = Math.round(dy);
        logEvent('scrollEvent', payload);
      } else if (!vertical && dx !== 0) {
        payload.orientation = 'SCROLL_ORIENTATION_HORIZONTAL';
        payload.startContentOffsetPoints = Math.round(last.scrollLeft);
        payload.netDisplacementPoints = Math.round(dx);
        logEvent('scrollEvent', payload);
      }
    }, ms);
    scrollThrottles.set(target, t);
  }
  t.fire();
}

/** Installs attention logging: scroll events and view data in "shown" events. */
export function installAttentionLogging() {
  if (attentionLogging || !flag('web_attention_logging_enabled')) return;
  if (!document.documentElement || typeof document.documentElement.getBoundingClientRect !== 'function') return;
  window.addEventListener('scroll', onScrollCapture, {capture: true, passive: true});
  attentionLogging = true;
}

// ---------------------------------------------------------------------------
// View-model components

/**
 * Whether `data` is loggable as a VE.
 * @param {!Element} el
 * @param {*} data
 * @return {boolean}
 */
function isLoggable(el, data) {
  const d = /** @type {?} */ (data);
  return !!((d && d.trackingParams) || (d && d.loggingDirectives) || (d && d.rendererContext && d.rendererContext.loggingContext) ||
      el.getAttribute('client-ve-type'));
}

/**
 * Registers a view model's root element as a VE container on a screen
 * layer node.
 * @param {!Element} el
 * @param {*} data
 */
function registerContainer(el, data) {
  const attr = el.getAttribute('layer');
  const layer = attr ? Number(attr) : undefined;
  const existing = rendererEntries.get(el);
  const entry = existing != null ? existing : {layerNode: new ScreenLayerNode(layer)};
  if (layer !== undefined) entry.layerNode.layer = layer;
  entry.isRenderer = true;
  entry[RENDERER_DATA] = data;
  rendererEntries.set(el, entry);
  attachLayerNode(el, entry.layerNode);
  const tp = trackingParamsOf(data);
  const e = /** @type {?} */ (el);
  if (tp) {
    if (e.veContainer == null) e.veContainer = {};
    e.veContainer.trackingParams = tp;
  } else if (e.veContainer) {
    delete e.veContainer.trackingParams;
  }
}

/**
 * Whether the monitor should skip a view model: when it shows the same
 * data as the renderer above it.
 * @param {!Element} el
 * @param {*} data
 * @return {boolean}
 */
function skipComponentLogging(el, data) {
  if (getConfig('INNERTUBE_CLIENT_NAME') !== 'WEB' || !data) return false;
  const parent = nearestRendererAbove(el);
  if (!parent) return false;
  const entry = rendererEntries.get(parent);
  const parentData = entry && entry[RENDERER_DATA] != null ? entry[RENDERER_DATA] : monitorTarget(parent).data;
  if (!parentData) return false;
  const tp = trackingParamsOf(data);
  return !!tp && tp === trackingParamsOf(parentData);
}

/**
 * Logs a registered view model: resolves its layer and VE, then registers
 * it with the visibility monitor.
 * @param {!Element} el
 * @param {*} data
 */
function attachComponentVe(el, data) {
  let layer;
  const attr = el.getAttribute('layer');
  if (attr) {
    layer = Number(attr);
    const entry = rendererEntries.get(el);
    if (entry) {
      entry.layerNode.layer = layer;
      attachLayerNode(el, entry.layerNode);
    } else {
      attachLayerNode(el, new ScreenLayerNode(layer));
    }
    const parent = nearestRendererAbove(el);
    const pe = parent ? rendererEntries.get(parent) : undefined;
    const own = rendererEntries.get(el);
    if (pe && own) own.layerNode.setParent(pe.layerNode);
  } else {
    const entry = rendererEntries.get(el);
    layer = entry && entry.layerNode.parent ? layerOf(entry.layerNode) : layerOf(linkLayerNodes(el));
  }
  if (layer == null) layer = 0;
  const clientVeType = Number(el.getAttribute('client-ve-type'));
  let changed = false;
  registerContainer(el, data);
  const d = /** @type {?} */ (data);
  let directives;
  if (flag('wiz_next_client_ve_parent_fix')) {
    const lc = d && d.rendererContext && d.rendererContext.loggingContext;
    directives = (lc && lc.loggingDirectives) || (d && d.loggingDirectives);
  } else {
    directives = d && d.loggingDirectives;
  }
  const tp = trackingParamsOf(data);
  const spec = directives && directives.clientVeSpec;
  const trackingKey = tp != null ? tp : spec ? `${spec.uiType != null ? spec.uiType : ''}:${spec.elementIndex != null ? spec.elementIndex : ''}` :
      clientVeType ? `clientVe:${clientVeType}` : '';
  const entry = rendererEntries.get(el);
  const e = /** @type {?} */ (el);
  if (entry && entry.loggedTrackingKey !== trackingKey) {
    if (entry.loggedTrackingKey !== undefined && e.visualElement) e.visualElement = undefined;
    entry.loggedTrackingKey = trackingKey;
    changed = true;
  }
  if (entry) entry.clientVeType = clientVeType;
  if (changed && directives && directives.clientVeSpec) {
    facadeNearestParentVe(loggerFacade(), el);
    if (flag('enable_client_ve_spec')) e.visualElement = clientVe(directives.clientVeSpec);
  }
  if (!e.visualElement && clientVeType && changed) {
    e.veType = clientVeType;
    e.visualElement = clientVe({uiType: clientVeType});
  }
  if (changed) {
    monitorVisibility(el, {data, observer: defaultVisibilityObserver(), layer, showOption: {calledOnce: false, state: 'visible'},
      hideOption: {calledOnce: false, state: 'hidden'},
      skipLogging: () => skipComponentLogging(el, data)});
  }
}

let componentLogCount = 0;

/**
 * Registers a view model's data for logging, then queues its VE attachment.
 * @param {!Element} el
 * @param {*} data
 */
function trackComponent(el, data) {
  componentLogCount++;
  if (isLoggable(el, data)) {
    registerContainer(el, data);
    queueComponentVe(el, data);
  }
  markDebugVe(el, data);
}

/**
 * Debug attributes for a view model's VE, when the debug flags ask for them.
 * @param {!Element} el
 * @param {*} data
 */
function markDebugVe(el, data) {
  const debugData = flag('debug_web_ve_data');
  const debugVes = flag('enable_debug_ves');
  if (!debugData && !debugVes) return;
  const tp = trackingParamsOf(data);
  if (debugData && tp) /** @type {!HTMLElement} */ (el).dataset.ve = tp.slice(0, 8);
}

/**
 * Queues the VE attachment of a registered view model.
 * @param {!Element} el
 * @param {*} data
 */
function queueComponentVe(el, data) {
  schedule(() => {
    later(() => {
      if (isLoggable(el, data) && el.ownerDocument.documentElement === document.documentElement) attachComponentVe(el, data);
    }, 0);
  }, Priority.DEFERRED);
}

/**
 * The logging hook of data-driven view-model components with one root
 * element: one render effect that reads `data` and tracks the element, and
 * one cleanup that unregisters it.
 * @param {!Element} el
 * @param {!Object} props
 */
function logComponent(el, props) {
  if (flag('cow_logging_in_component_wrapper')) return;
  const clientVeType = el.getAttribute('client-ve-type');
  if (!((props.data && !props.disableReactiveLogging) || clientVeType)) return;
  renderEffect(() => {
    const data = typeof props.data === 'function' ? props.data() : props.data;
    trackComponent(el, data);
  }, 'vg');
  onCleanup(() => {
    rendererEntries.delete(el);
    unmonitorVisibility(el, defaultVisibilityObserver());
  });
}
setComponentLoggingHook(logComponent);

// ---------------------------------------------------------------------------
// Ads control flow

const CONTROL_FLOW_LAYERS = new Map([
  ['unspecified', 'CONTROL_FLOW_MANAGER_LAYER_UNSPECIFIED'],
  ['core', 'CONTROL_FLOW_MANAGER_LAYER_CORE'],
  ['adapter', 'CONTROL_FLOW_MANAGER_LAYER_ADAPTER'],
  ['surface', 'CONTROL_FLOW_MANAGER_LAYER_SURFACE'],
  ['external', 'CONTROL_FLOW_MANAGER_LAYER_EXTERNAL'],
]);

/**
 * @typedef {{
 *   slotId: string, slotType: string, slotPhysicalPosition: number, managerLayer: string,
 *   slotEntryTrigger: ?Object, slotFulfillmentTriggers: !Array<!Object>,
 *   slotExpirationTriggers: !Array<!Object>, adSlotLoggingData: ?Object,
 * }}
 */
let AdSlot;

/**
 * @typedef {{layoutId: string, layoutType: string, managerLayer: string, adLayoutLoggingData: ?Object}}
 */
let AdLayout;

/** @type {!WeakMap<!Object, !AdSlot>} */
const slotCache = new WeakMap();
/** @type {!WeakMap<!Object, !AdLayout>} */
const layoutCache = new WeakMap();

/**
 * The control-flow slot of `adSlotMetadata`, or null when it is malformed.
 * @param {?Object} meta
 * @return {?AdSlot}
 */
function toSlot(meta) {
  if (!meta || typeof meta.slotId !== 'string' || typeof meta.slotType !== 'string') {
    console.warn('Malformed ad slot metadata');
    return null;
  }
  let slot = slotCache.get(meta);
  if (!slot) {
    slot = {
      slotId: meta.slotId,
      slotType: meta.slotType,
      slotPhysicalPosition: meta.slotPhysicalPosition != null ? meta.slotPhysicalPosition : 1,
      managerLayer: 'surface',
      slotEntryTrigger: {triggerType: 'TRIGGER_TYPE_SLOT_ID_ENTERED', triggeringSlotId: meta.slotId},
      slotFulfillmentTriggers: [{triggerType: 'TRIGGER_TYPE_ON_NEW_PLAYBACK_AFTER_CONTENT_VIDEO_ID'}],
      slotExpirationTriggers: [{triggerType: 'TRIGGER_TYPE_SLOT_ID_EXITED', triggeringSlotId: meta.slotId}],
      adSlotLoggingData: meta.adSlotLoggingData || null,
    };
    slotCache.set(meta, slot);
  }
  return slot;
}

/**
 * @param {?Object} meta
 * @return {?AdLayout}
 */
function toLayout(meta) {
  if (!meta || typeof meta.layoutId !== 'string' || typeof meta.layoutType !== 'string') {
    console.warn('Malformed ad layout metadata');
    return null;
  }
  let layout = layoutCache.get(meta);
  if (!layout) {
    layout = {layoutId: meta.layoutId, layoutType: meta.layoutType, managerLayer: 'surface',
      adLayoutLoggingData: meta.adLayoutLoggingData || null};
    layoutCache.set(meta, layout);
  }
  return layout;
}

/**
 * @param {?Object} trigger
 * @param {string=} category
 * @return {!Object}
 */
function triggerData(trigger, category) {
  const out = {type: trigger ? trigger.triggerType : undefined};
  if (category != null) out.category = category;
  if (trigger && trigger.triggeringSlotId != null) {
    out.triggerSourceData = out.triggerSourceData || {};
    out.triggerSourceData.associatedSlotId = trigger.triggeringSlotId;
  }
  if (trigger && trigger.triggeringLayoutId != null) {
    out.triggerSourceData = out.triggerSourceData || {};
    out.triggerSourceData.associatedLayoutId = trigger.triggeringLayoutId;
  }
  return out;
}

/**
 * @param {boolean} debug
 * @param {!AdSlot} slot
 * @return {!Object}
 */
function slotData(debug, slot) {
  const out = {type: slot.slotType, controlFlowManagerLayer: CONTROL_FLOW_LAYERS.get(slot.managerLayer) || 'CONTROL_FLOW_MANAGER_LAYER_UNSPECIFIED'};
  if (slot.slotEntryTrigger) out.entryTriggerType = slot.slotEntryTrigger.triggerType;
  if (slot.slotPhysicalPosition !== 1) out.slotPhysicalPosition = slot.slotPhysicalPosition;
  if (debug) {
    out.debugData = {slotId: slot.slotId};
    if (slot.slotEntryTrigger) out.debugData.slotEntryTriggerData = triggerData(slot.slotEntryTrigger);
    out.debugData.fulfillmentTriggerData = [];
    for (const t of slot.slotFulfillmentTriggers) out.debugData.fulfillmentTriggerData.push(triggerData(t));
    out.debugData.expirationTriggerData = [];
    for (const t of slot.slotExpirationTriggers) out.debugData.expirationTriggerData.push(triggerData(t));
  }
  return out;
}

/** The ads control-flow event logger. */
class AdEventLogger {
  constructor() {
    this.eventCount = 0;
    this.alwaysIncludeDebugData = false;
  }
}

const adLogger = new AdEventLogger();
/** @type {!Map<string, string>} Slot lifecycle stage by slot id. */
const slotStages = new Map();
/** @type {!Set<string>} */
const scheduledSlots = new Set();
/** @type {!Set<string>} */
const scheduledLayouts = new Set();

/**
 * @typedef {{
 *   opportunityType: (string|undefined),
 *   slots: (!Array<!AdSlot>|undefined),
 *   slot: (?AdSlot|undefined),
 *   layout: (?AdLayout|undefined),
 *   errorInfo: (?Object|undefined),
 * }}
 */
let AdEventData;

/**
 * Logs one ads control-flow state change (`adsClientStateChange`). This is
 * the hook for ad surfaces: view-model ad lockups call it for their own
 * layout events (for example `ADS_CLIENT_EVENT_TYPE_LAYOUT_EXITED_USER_CANCELLED`
 * with the layout's `adSlotMetadata` and `adLayoutMetadata`).
 * @param {string} eventType An `ADS_CLIENT_EVENT_TYPE_*` name.
 * @param {{slotMetadata: (?Object|undefined), layoutMetadata: (?Object|undefined), opportunityType: (string|undefined)}=} data
 */
export function logAdsClientStateChange(eventType, data = {}) {
  logAdEventData(eventType, {
    opportunityType: data.opportunityType,
    slot: data.slotMetadata ? toSlot(data.slotMetadata) : undefined,
    layout: data.layoutMetadata ? toLayout(data.layoutMetadata) : undefined,
  });
}

/**
 * @param {string} eventType
 * @param {!AdEventData} data
 */
function logAdEventData(eventType, data) {
  if (flag('h5_enable_pacf_debug_logs')) console.log(`[PACF]: ${eventType}`, 'slot:', data.slot, 'layout:', data.layout);
  try {
    if (eventType === 'ADS_CLIENT_EVENT_TYPE_UNSPECIFIED') return;
    const debug = adLogger.alwaysIncludeDebugData;
    const event = {eventType, eventOrder: ++adLogger.eventCount};
    const clientData = {};
    if (data.slot) clientData.slotData = slotData(debug, data.slot);
    if (data.layout) {
      const layoutData = {type: data.layout.layoutType,
        controlFlowManagerLayer: CONTROL_FLOW_LAYERS.get(data.layout.managerLayer) || 'CONTROL_FLOW_MANAGER_LAYER_UNSPECIFIED'};
      if (debug) layoutData.debugData = {layoutId: data.layout.layoutId};
      clientData.layoutData = layoutData;
    }
    if (data.opportunityType) {
      const opportunity = {opportunityType: data.opportunityType};
      if (debug && data.slots) opportunity.associatedSlotIds = data.slots.map((s) => s.slotId);
      clientData.opportunityData = opportunity;
    }
    event.adClientData = clientData;
    if (data.slot && data.slot.adSlotLoggingData) event.serializedSlotAdServingData = data.slot.adSlotLoggingData.serializedSlotAdServingDataEntry;
    if (data.layout && data.layout.adLayoutLoggingData) event.serializedAdServingData = data.layout.adLayoutLoggingData.serializedAdServingDataEntry;
    if (data.errorInfo) event.errorInfo = data.errorInfo;
    logEvent('adsClientStateChange', {adsClientEvent: event});
  } catch (e) {
    if (flag('html5_log_pacf_logging_errors')) console.warn('exception during pacf logging', e);
  }
}

/**
 * Handles an `adsControlFlowOpportunityReceivedCommand`: logs the
 * opportunity, each slot and layout it carries, and the processed
 * opportunity.
 * @param {?Object} command
 */
export function adsOpportunityReceived(command) {
  if (!command) return;
  const type = command.opportunityType;
  if (type !== undefined) logAdEventData('ADS_CLIENT_EVENT_TYPE_OPPORTUNITY_RECEIVED', {opportunityType: type});
  else console.warn('onOpportunityReceivedExternallyManaged: no opportunity type');
  const slots = [];
  for (const item of command.adSlotAndLayoutMetadata || []) {
    const slot = item.adSlotMetadata ? toSlot(item.adSlotMetadata) : null;
    if (!slot) continue;
    slots.push(slot);
    logAdEventData('ADS_CLIENT_EVENT_TYPE_SLOT_RECEIVED', {slot});
    for (const layoutMeta of item.adLayoutMetadata || []) {
      const layout = toLayout(layoutMeta);
      if (layout && slot.managerLayer !== 'core') logAdEventData('ADS_CLIENT_EVENT_TYPE_LAYOUT_RECEIVED', {slot, layout});
    }
  }
  if (type !== undefined) logAdEventData('ADS_CLIENT_EVENT_TYPE_OPPORTUNITY_PROCESSED', {opportunityType: type, slots});
}

/**
 * An ad slot was rendered: logs it as scheduled and entered.
 * @param {?Object} slotMetadata
 */
export function adSlotEntered(slotMetadata) {
  const slot = toSlot(slotMetadata);
  if (!slot) return;
  const dedupe = flag('web_dedup_ads_lifecycle_scheduled_events');
  if (!dedupe || !scheduledSlots.has(slot.slotId)) {
    if (dedupe) scheduledSlots.add(slot.slotId);
    logAdEventData('ADS_CLIENT_EVENT_TYPE_SLOT_SCHEDULED', {slot});
    const stage = slotStages.get(slot.slotId);
    if (stage && stage !== 'not_scheduled') console.warn('Unexpected slot stage', stage, 'onSlotScheduled');
    slotStages.set(slot.slotId, 'scheduled');
  }
  logAdEventData('ADS_CLIENT_EVENT_TYPE_SLOT_ENTERED', {slot});
  slotStages.set(slot.slotId, 'entered');
}

/**
 * An ad slot was removed: logs it as exited and unscheduled.
 * @param {?Object} slotMetadata
 */
export function adSlotExited(slotMetadata) {
  const slot = toSlot(slotMetadata);
  if (!slot) return;
  logAdEventData('ADS_CLIENT_EVENT_TYPE_SLOT_EXITED', {slot});
  logAdEventData('ADS_CLIENT_EVENT_TYPE_SLOT_UNSCHEDULED', {slot});
  slotStages.delete(slot.slotId);
  scheduledSlots.delete(slot.slotId);
}

/**
 * An ad layout was rendered in its slot: logs it as scheduled and entered.
 * @param {?Object} slotMetadata
 * @param {?Object} layoutMetadata
 */
export function adLayoutEntered(slotMetadata, layoutMetadata) {
  const slot = toSlot(slotMetadata);
  const layout = toLayout(layoutMetadata);
  if (!slot || !layout) return;
  const dedupe = flag('web_dedup_ads_lifecycle_scheduled_events');
  if (!dedupe || !scheduledLayouts.has(layout.layoutId)) {
    if (dedupe) scheduledLayouts.add(layout.layoutId);
    logAdEventData('ADS_CLIENT_EVENT_TYPE_LAYOUT_SCHEDULED', {slot, layout});
  }
  logAdEventData('ADS_CLIENT_EVENT_TYPE_LAYOUT_ENTERED', {slot, layout});
  slotStages.set(slot.slotId, 'rendering');
}

/**
 * An ad layout was removed: logs it as exited normally.
 * @param {?Object} slotMetadata
 * @param {?Object} layoutMetadata
 */
export function adLayoutExited(slotMetadata, layoutMetadata) {
  const slot = toSlot(slotMetadata);
  const layout = toLayout(layoutMetadata);
  if (!slot || !layout) return;
  logAdEventData('ADS_CLIENT_EVENT_TYPE_LAYOUT_EXITED_NORMALLY', {slot, layout});
  scheduledLayouts.delete(layout.layoutId);
}

/** Ad pings (first-visible and active-view commands); they are not GEL events. */
let adPings = 0;

/**
 * Records an ad ping. Kept for callers that report ad pings; YouTube sends
 * these as pings, not as logging events.
 * @param {string} kind
 * @param {?Object} command
 */
export function logAdEvent(kind, command) {
  adPings++;
}
