/**
 * @fileoverview PolySi legacy controllers.
 *
 * A PolySi element is a thin custom-element host plus a controller. A
 * legacy controller is a real Polymer legacy element instance: its class
 * is made by Polymer's `mixinBehaviors` on top of `ControllerBase` instead
 * of `HTMLElement`, so Polymer's property effects, template stamping and
 * binding, observers and legacy API all run on it unchanged. Two mixins
 * adapt it to living outside the DOM:
 * - `HostDomMixin` attaches the stamped template to a ShadyDOM shadow root
 *   on the host, and styles the host;
 * - `HostEffectsMixin` makes notify events, reflected attributes, event
 *   listeners, `fire` and host attributes target the host.
 *
 * The controller has no DOM API of its own. Element code reaches the DOM
 * through `this.hostElement`.
 */
import {mixinBehaviors} from '@polymer/polymer/lib/legacy/class.js';
import {LegacyElementMixin} from '@polymer/polymer/lib/legacy/legacy-element-mixin.js';
import {sanitizeDOMValue} from '@polymer/polymer/lib/utils/settings.js';
import {get as getPath, root as rootOfPath} from '@polymer/polymer/lib/utils/path.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {camelToDash} from '../case.js';
import {InitBehavior, InjectBehavior, TemplateHelpersBehavior} from './base-behaviors.js';
import {logPropertyAccess} from './logging.js';

/** @type {?HTMLElement} */
let constructingHost = null;

/**
 * Sets the host that the next controller constructor attaches to.
 * @param {?HTMLElement} host
 */
export function setConstructingHost(host) {
  constructingHost = host;
}

/**
 * The base class of every controller, in place of HTMLElement.
 */
export class ControllerBase {
  constructor() {
    /** @type {!HTMLElement} */
    this.hostElement = /** @type {!HTMLElement} */ (constructingHost);
  }

  /**
   * Polymer asks for `dir` and `disable-upgrade` only; any other attribute
   * belongs to the host.
   * @param {string} name
   * @return {boolean}
   */
  hasAttribute(name) {
    if (name === 'dir') return false;
    if (name === 'disable-upgrade') {
      const host = this.hostElement;
      return host ? host.hasAttribute('disable-upgrade') : false;
    }
    throw new Error(`hasAttribute(${name}) on a controller`);
  }

  /**
   * The host's attribute callback. Ignores unchanged values and the
   * controller's own reflections.
   * @param {string} name
   * @param {?string} oldValue
   * @param {?string} newValue
   */
  attributeChangedCallbackWrapper(name, oldValue, newValue) {
    const self = /** @type {?} */ (this);
    if (name === 'disable-upgrade' && self.__isUpgradeDisabled && newValue === null) {
      self._initializeProperties();
      self.__isUpgradeDisabled = false;
      const host = this.hostElement != null ? this.hostElement : self;
      if (host.isConnected) self.connectedCallback();
    } else if (oldValue !== newValue && !self.__isReflecting) {
      self.attributeChangedCallback(name, oldValue, newValue);
    }
  }

  /**
   * New closures, per call, for the Polymer methods that hosts forward
   * besides the element's own. `_setPendingProperty` records a declarative
   * external write.
   * @return {!Array<!Array<?>>} [name, function] pairs.
   */
  getExtraMethodsToForward() {
    const self = /** @type {?} */ (this);
    const out = [];
    for (const name of EXTRA_METHODS) {
      let fn;
      if (name === '_setPendingProperty') {
        const tag = this.hostElement.tagName.toLowerCase();
        fn = (prop, value, shouldNotify) => {
          logPropertyAccess(tag, prop, 'PROPERTY_ACCESS_SET_EXTERNAL_DECLARATIVE');
          return self._setPendingProperty(prop, value, shouldNotify);
        };
      } else {
        fn = (...args) => self[name].apply(self, args);
      }
      out.push([name, fn]);
    }
    return out;
  }
}

/** Polymer methods that every legacy host forwards, besides the element's own. */
export const EXTRA_METHODS = ['_enableProperties', '_flushProperties', '_setPendingProperty', '_setPendingPropertyOrPath', 'set', 'get'];

/**
 * @param {*} x
 * @return {*} The host of a controller, or `x` itself.
 */
function hostOf(x) {
  const host = x && x.hostElement;
  return host != null ? host : x;
}

/**
 * Serializes a property value for an attribute, as Polymer does.
 * @param {*} value
 * @return {string|undefined}
 */
function serializeForAttribute(value) {
  switch (typeof value) {
    case 'object':
    case 'function':
      if (value instanceof Date) return value.toString();
      if (value) {
        try {
          return JSON.stringify(value);
        } catch (e) {
          return undefined;
        }
      }
      return undefined;
    case 'boolean':
      return value ? '' : undefined;
    default:
      return value != null ? String(value) : undefined;
  }
}

/**
 * The notify effect of legacy controllers: fires `<prop>-changed` on the
 * host, without bubbling.
 * @param {!Object} inst
 * @param {string} property
 * @param {!Object} props
 * @param {!Object} oldProps
 * @param {!Object} info
 * @param {boolean} hasPaths
 */
function notifyOnHost(inst, property, props, oldProps, info, hasPaths) {
  const rootProperty = hasPaths ? rootOfPath(property) : property;
  const path = rootProperty !== property ? property : null;
  let value = path ? getPath(inst, path) : inst.__data[property];
  if (path && value === undefined) value = props[property];
  const detail = {value, queueProperty: true, path: path != null ? path : undefined};
  const event = new CustomEvent(`${camelToDash(rootProperty)}-changed`, {bubbles: false, composed: false, detail});
  inst.hostElement.dispatchEvent(event);
}

/**
 * The reflect effect of legacy controllers: writes the attribute on the
 * host.
 * @param {!Object} inst
 * @param {string} property
 */
function reflectOnHost(inst, property) {
  inst.__isReflecting = true;
  const attr = camelToDash(property);
  let value = inst.__data[property];
  if (sanitizeDOMValue) value = sanitizeDOMValue(value, attr, 'attribute', inst.hostElement);
  const str = serializeForAttribute(value);
  if (str === undefined) inst.hostElement.removeAttribute(attr);
  else inst.hostElement.setAttribute(attr, str);
  inst.__isReflecting = false;
}

/**
 * @param {function(new:Object)} base
 * @return {function(new:Object)}
 */
function HostDomMixin(base) {
  /** @suppress {checkTypes,missingProperties,missingOverride} */
  class HostDom extends base {
    /**
     * Attaches the stamped template to a ShadyDOM shadow root on the host.
     * @param {?DocumentFragment} dom
     * @return {?Node}
     * @override
     */
    _attachDom(dom) {
      if (!dom) return null;
      const host = wrap(this.hostElement);
      host.attachShadow({mode: 'open', shadyUpgradeFragment: dom});
      host.shadowRoot.appendChild(dom);
      return host.shadowRoot;
    }

    /** @override */
    _readyClients() {
      super._readyClients();
      this.root = this;
    }

    /** @override */
    connectedCallback() {
      if (window.ShadyCSS && this._template) window.ShadyCSS.styleElement(this.hostElement);
      super.connectedCallback();
    }
  }
  return HostDom;
}

/**
 * @param {function(new:Object)} base
 * @return {function(new:Object)}
 */
function HostEffectsMixin(base) {
  /** @suppress {checkTypes,missingProperties,missingOverride} */
  class HostEffects extends base {
    /** @override */
    created() {
      const notify = this.__notifyEffects;
      if (notify) {
        for (const list of Object.values(notify)) {
          for (const fx of list) fx.fn = notifyOnHost;
        }
      }
      const reflect = this.__reflectEffects;
      if (reflect) {
        for (const list of Object.values(reflect)) {
          for (const fx of list) fx.fn = reflectOnHost;
        }
      }
      super.created();
    }

    /**
     * @param {!EventTarget} node
     * @param {string} eventName
     * @param {function(!Event)} handler
     * @override
     */
    _addEventListenerToNode(node, eventName, handler) {
      super._addEventListenerToNode(/** @type {!EventTarget} */ (hostOf(node)), eventName, handler);
    }

    /**
     * @param {!EventTarget} node
     * @param {string} eventName
     * @param {function(!Event)} handler
     * @override
     */
    _removeEventListenerFromNode(node, eventName, handler) {
      super._removeEventListenerFromNode(/** @type {!EventTarget} */ (hostOf(node)), eventName, handler);
    }

    /**
     * Drops pending notifications of properties without a notify effect.
     * @param {!Object} currentProps
     * @param {?Object} changedProps
     * @param {?Object} oldProps
     * @override
     */
    _propertiesChanged(currentProps, changedProps, oldProps) {
      const toNotify = this.__dataToNotify;
      const notify = this.__notifyEffects;
      if (toNotify && notify) {
        for (const path of Object.keys(toNotify)) {
          if (!notify[rootOfPath(path)]) delete toNotify[path];
        }
      } else {
        this.__dataToNotify = null;
      }
      super._propertiesChanged(currentProps, changedProps, oldProps);
    }

    /**
     * Polymer's `fire`, dispatched on the host.
     * @param {string} type
     * @param {*=} detail
     * @param {{bubbles: (boolean|undefined), cancelable: (boolean|undefined), composed: (boolean|undefined), node: (!EventTarget|undefined)}=} options
     * @return {!Event}
     * @override
     */
    fire(type, detail = {}, options) {
      const node = /** @type {!EventTarget} */ (hostOf(options && options.node != null ? options.node : this));
      const init = options || {bubbles: true, cancelable: false, composed: true};
      if (detail != null) init.detail = detail;
      const event = new CustomEvent(type, /** @type {!CustomEventInit} */ (init));
      node.dispatchEvent(event);
      return event;
    }

    /**
     * @param {string} name
     * @param {*} value
     * @override
     */
    _ensureAttribute(name, value) {
      const host = this.hostElement;
      if (host.hasAttribute(name)) return;
      const str = serializeForAttribute(value);
      if (str === undefined) host.removeAttribute(name);
      else host.setAttribute(name, str);
    }

    /**
     * @param {?Node} node
     * @return {boolean}
     * @override
     */
    isLightDescendant(node) {
      const host = this.hostElement;
      return host !== node && wrap(host).contains(node) && wrap(host).getRootNode() === wrap(node).getRootNode();
    }
  }
  return HostEffects;
}

/** The base class of the legacy controller classes. */
const LegacyControllerBase = HostEffectsMixin(HostDomMixin(LegacyElementMixin(ControllerBase)));

/**
 * @param {!Array<*>} behaviors
 * @param {!Array<!Object>=} out
 * @return {!Array<!Object>}
 */
function flattenBehaviors(behaviors, out = []) {
  for (const b of behaviors) {
    if (!b) continue;
    if (Array.isArray(b)) flattenBehaviors(b, out);
    else if (out.indexOf(b) < 0) out.push(/** @type {!Object} */ (b));
  }
  return out;
}

/**
 * The merged property declarations of the behaviors and the info object.
 * @param {!Array<!Object>} behaviors
 * @param {!Object} info
 * @return {{properties: !Object<string, !Object>}}
 */
function mergeSchema(behaviors, info) {
  const properties = {};
  for (const source of [...behaviors, info]) {
    const props = source.properties;
    if (!props) continue;
    for (const name in props) {
      const decl = props[name];
      properties[name] = Object.assign({}, properties[name], typeof decl === 'function' ? {type: decl} : decl);
    }
  }
  return {properties};
}

/** Info keys that the controller class doesn't take from the info object. */
const SKIPPED_INFO_KEYS = new Set(['behaviors']);

/**
 * The info object as the last behavior: everything except its `behaviors`.
 * @param {!Object} info
 * @return {!Object}
 */
function infoAsBehavior(info) {
  const out = {};
  for (const key of Object.getOwnPropertyNames(info)) {
    if (SKIPPED_INFO_KEYS.has(key)) continue;
    Object.defineProperty(out, key, /** @type {!ObjectPropertyDescriptor} */ (Object.getOwnPropertyDescriptor(info, key)));
  }
  return out;
}

/**
 * Creates the legacy controller class for a PolySi element.
 * @param {!Object} info The object passed to Polymer().
 * @param {!Array<string>|undefined} registeredAllowedProps The registration
 *     option listing the properties that other code may set on the host.
 * @return {function(new:Object)}
 */
export function createControllerClass(info, registeredAllowedProps) {
  const behaviors = flattenBehaviors([InitBehavior, InjectBehavior, info.behaviors || [], TemplateHelpersBehavior]);
  /** @const {function(new:Object)} */
  const Generated = mixinBehaviors([...behaviors, infoAsBehavior(info)], LegacyControllerBase);

  // An own field of every controller, forwarded at `ready`; `undefined`
  // without registration options.
  const allowed = (registeredAllowedProps || []).concat(info.allowedPropsFromBehaviors || []);
  const allowedProps = allowed.length > 0 ? allowed : undefined;

  /** @suppress {checkTypes,missingProperties,missingOverride} */
  class PolySiController extends Generated {
    constructor() {
      super();
      this.root = this;
      this._overrideLegacyUndefined = true;
      this.allowedProps = allowedProps;
    }
  }
  PolySiController.prototype.is = info.is;
  PolySiController.prototype.localName = info.is;

  PolySiController.psSchema = mergeSchema(behaviors, info);
  PolySiController.psBehaviors = behaviors;
  PolySiController.psInfo = info;
  return PolySiController;
}
