/**
 * @fileoverview Element registration. App elements call this module's
 * `Polymer(info)` instead of Polymer's. Tags listed in the build's PolySi
 * configuration become PolySi elements; the others are defined by Polymer.
 */
import {Polymer as polymerFn} from '../polymer-namespace.js';
import '../resin.js';
import {POLYSI_SIGNAL_TAGS, POLYSI_TAGS} from '../../../gen/polysi-config.js';
import {hostDom} from '../host-dom.js';
import {definePolySiElement} from './host.js';
import {installLifecyclePatches} from './lifecycle.js';
import './repeat.js';

const polysiTags = new Set(POLYSI_TAGS);
const signalTags = new Set(POLYSI_SIGNAL_TAGS);
installLifecyclePatches();

/** @typedef {{mode: (number|undefined), allowedProps: (!Array<string>|undefined)}} */
let RegistrationOptions;

/** @type {!Map<string, !RegistrationOptions>} */
const registrationOptions = new Map();

/**
 * Mode 2 registrations on YouTube list the properties other code may set;
 * we have not ported the lists, so mode 2 elements get this one.
 */
const MODE_2_ALLOWED_PROPS = ['data'];

/**
 * Sets the registration options of a tag, for its `Polymer()` call. `mode`
 * is the registration mode of a legacy PolySi element (default 2).
 * @param {string} tag
 * @param {!RegistrationOptions} options
 */
export function setRegistrationOptions(tag, options) {
  registrationOptions.set(tag, options);
}

/**
 * Adds a getter per name that returns the element, as YouTube's classes
 * have for each behaviour they declare (`ytRendererBehavior` and similar).
 * @param {!Object} info
 * @param {!Array<string>} names
 * @return {!Object} `info`.
 */
export function withHandles(info, names) {
  for (const name of names) {
    if (!Object.getOwnPropertyDescriptor(info, name)) {
      Object.defineProperty(info, name, {configurable: true, enumerable: true, get() {
        return this;
      }});
    }
  }
  return info;
}

/**
 * Adds a getter per entry that returns the element of the given id in the
 * template, as the `@query` members of YouTube's classes do.
 * @param {!Object} info
 * @param {!Object<string, string>} queries Member name to element id.
 * @return {!Object} `info`.
 */
export function withQueries(info, queries) {
  for (const name of Object.keys(queries)) {
    const id = queries[name];
    if (!Object.getOwnPropertyDescriptor(info, name)) {
      Object.defineProperty(info, name, {configurable: true, enumerable: true, get() {
        return this.$[id];
      }});
    }
  }
  return info;
}

/**
 * Adds a getter per entry that returns the first element that matches the
 * selector in the element's content, as `@query` members with a selector do.
 * @param {!Object} info
 * @param {!Object<string, string>} selectors Member name to selector.
 * @return {!Object} `info`.
 */
export function withSelectors(info, selectors) {
  for (const name of Object.keys(selectors)) {
    const selector = selectors[name];
    if (!Object.getOwnPropertyDescriptor(info, name)) {
      Object.defineProperty(info, name, {configurable: true, enumerable: true, get() {
        return hostDom(this.hostElement).querySelector(selector);
      }});
    }
  }
  return info;
}

/**
 * Members that a tag has on YouTube and that its element here does not
 * carry itself.
 * @typedef {{
 *   behaviors: (!Array<*>|undefined),
 *   properties: (!Object<string, !Object>|undefined),
 *   observers: (!Array<string>|undefined),
 *   listeners: (!Object<string, string>|undefined),
 *   fields: (!Object<string, *>|undefined),
 *   methods: (!Array<string>|undefined),
 *   handles: (!Array<string>|undefined),
 *   stamps: (!Object<string, string>|undefined),
 * }}
 */
export let Members;

/** @const {!Map<string, !Members>} */
const memberTable = new Map();

/**
 * Registers members per tag; `Polymer()` adds them to the element's info:
 * behaviours, declared properties and observers the info lacks, controller
 * fields (set in `created()`, or in `initFields_()` on signal-schema
 * elements), methods the info lacks (as no-ops) and behaviour handles.
 * @param {!Object<string, !Members>} table
 */
export function registerMembers(table) {
  for (const tag of Object.keys(table)) memberTable.set(tag, table[tag]);
}

/**
 * @param {!Object} info
 * @param {boolean} signal
 * @return {!Object}
 */
function applyMembers(info, signal) {
  const members = memberTable.get(info.is);
  if (!members) return info;
  const copy = Object.create(Object.getPrototypeOf(info), Object.getOwnPropertyDescriptors(info));
  if (members.behaviors) copy.behaviors = (info.behaviors || []).concat(members.behaviors);
  copy.properties = Object.assign({}, members.properties, info.properties);
  copy.observers = (info.observers || []).concat((members.observers || []).filter(o => (info.observers || []).indexOf(o) < 0));
  if (members.listeners) copy.listeners = Object.assign({}, members.listeners, info.listeners);
  for (const name of members.methods || []) {
    if (!Object.getOwnPropertyDescriptor(copy, name)) copy[name] = function() {};
  }
  if (members.handles) withHandles(copy, members.handles);
  if (members.stamps) {
    const original = info.configureRendererStamper;
    const stamps = members.stamps;
    copy.configureRendererStamper = function() {
      const config = {};
      for (const path of Object.keys(stamps)) config[path] = {id: stamps[path], mapping: {}};
      return Object.assign(config, original ? original.apply(this, arguments) : null);
    };
  }
  const fields = members.fields;
  if (fields) {
    const hook = signal ? 'initFields_' : 'created';
    const original = info[hook];
    copy[hook] = function() {
      if (original) original.apply(this, arguments);
      for (const name of Object.keys(fields)) {
        if (!(name in this)) this[name] = typeof fields[name] === 'function' ? fields[name]() : fields[name];
      }
    };
  }
  return copy;
}

/**
 * @param {!Object} info
 * @return {function(new:Object)}
 */
export function Polymer(info) {
  const signal = signalTags.has(info.is);
  info = applyMembers(info, signal);
  info = applyDeclarationHooks(info, signal);
  const options = registrationOptions.get(info.is);
  if (polysiTags.has(info.is)) {
    if (!options) return definePolySiElement(info, signal, 2, MODE_2_ALLOWED_PROPS);
    const mode = options.mode !== undefined ? options.mode : 2;
    return definePolySiElement(info, signal, mode, options.allowedProps || (mode === 2 ? MODE_2_ALLOWED_PROPS : undefined));
  }
  return polymerFn(/** @type {?} */ (info));
}

/**
 * @param {!Array<*>} behaviors
 * @param {!Array<!Object>=} out
 * @return {!Array<!Object>}
 */
function flattenBehaviors(behaviors, out = []) {
  for (const b of behaviors) {
    if (Array.isArray(b)) flattenBehaviors(b, out);
    else if (b && out.indexOf(b) < 0) out.push(/** @type {!Object} */ (b));
  }
  return out;
}

/**
 * Lets behaviours add declarations before the element class is created:
 * each behaviour's `registerDeclarations_(info, behaviors, signal)` may add
 * observers and replace property declarations. Runs on a copy of `info`.
 * @param {!Object} info
 * @param {boolean} signal Whether the element is signal-schema.
 * @return {!Object}
 */
function applyDeclarationHooks(info, signal) {
  const behaviors = flattenBehaviors(info.behaviors || []);
  const hooks = behaviors.filter(b => typeof b.registerDeclarations_ === 'function');
  if (!hooks.length) return info;
  const copy = Object.create(Object.getPrototypeOf(info), Object.getOwnPropertyDescriptors(info));
  copy.observers = (info.observers || []).slice();
  copy.properties = Object.assign({}, info.properties);
  for (const b of hooks) b.registerDeclarations_(copy, behaviors, signal);
  return copy;
}

/**
 * @param {string} tag
 * @return {boolean}
 */
export function isPolySiTag(tag) {
  return polysiTags.has(tag);
}

/**
 * The DOM element behind `self`: a PolySi controller's host, or `self` for
 * stock elements and plain nodes.
 * @param {*} self
 * @return {!Element}
 */
export function elementOf(self) {
  const host = self.hostElement;
  return host != null ? host : self;
}
