/**
 * Applies custom properties to an element through the ShadyCSS shim
 * (kevlar's `cn`), which also restyles the shadow hosts below it.
 * @param {!Element} el
 * @param {!Object<string, string>} props
 */
export function styleSubtree(el, props) {
  const shady = /** @type {?} */ (window).ShadyCSS;
  if (shady && shady.styleSubtree) shady.styleSubtree(el, props);
  else for (const name of Object.keys(props)) /** @type {!HTMLElement} */ (el).style.setProperty(name, props[name]);
}

/** The grid-state column classes (`Cth`): 6 down to 1 columns of 2 × 107 px. */
const GRID_STATES = [6, 5, 4, 3, 2, 1].map(columns => ({columns, query: columns === 1 ? 0 : columns * 2 * 107 - 4 + 32,
  className: `grid-${columns}-columns`}));
const GUIDE_WIDTH = 240;

/**
 * The grid state for the current window (`_.BBM`): the widest column count
 * whose minimum width fits the body minus the guide.
 * @return {{columns: number, query: number, className: string}}
 */
function currentGridState() {
  const usable = document.body.clientWidth - GUIDE_WIDTH;
  for (const state of GRID_STATES) if (usable > state.query) return state;
  return GRID_STATES[GRID_STATES.length - 1];
}

/**
 * A colour of an on-focus effect as a CSS colour.
 * @param {number} color An ARGB integer.
 * @return {string}
 */
function cssColor(color) {
  const c = color & 0xFFFFFF;
  return `rgb(${(c & 0xFF0000) >> 16}, ${(c & 0xFF00) >> 8}, ${c & 0xFF})`;
}

/** The page subtypes that have no grid (`LEh`). */
const GRID_DISABLED_SUBTYPES = ['WEB_PAGE_TYPE_SETTINGS', 'red', 'playlist', 'labs', 'handle', 'ypc-offers', 'show', 'ypc-checkout'];

/**
 * The grid-state behaviour (kevlar's `ytdGridStateAwareBehavior`): a
 * `grid` class and a `grid-N-columns` class on the element, updated after
 * each render and on `ytd-update-grid-state-action`.
 * @polymerBehavior
 */
const GridStateAwareBehaviorImpl = {
  properties: {
    gridStateAwareSizingElementSelector: String,
    disableGridStateAware: {type: Boolean, reflectToAttribute: true},
  },

  created() {
    this.disableGridStateAware = false;
    this.gridStateActionMap = {'ytd-update-grid-state-action': 'handleUpdateGridStateAction'};
    this.currentGridClass = '';
  },

  attached() {
    this.registerActionMap(this.gridStateActionMap);
    afterNextRender(this, this.handleUpdateGridStateAction);
    if (!this.disableGridStateAware) this.gridStateAwareGetElement().classList.add('grid');
  },

  detached() {
    this.unregisterActionMap(this.gridStateActionMap);
  },

  /** @return {?Element} */
  gridStateAwareGetElement() {
    return this.gridStateAwareSizingElementSelector ? hostDom(this.hostElement).querySelector(this.gridStateAwareSizingElementSelector) : this.hostElement;
  },

  handleUpdateGridStateAction() {
    let className;
    if (this.disableGridStateAware) {
      className = 'grid-disabled';
    } else {
      const subtype = this.get('pageSubtype');
      className = subtype && (GRID_DISABLED_SUBTYPES.includes(subtype) || (subtype === 'you' && flag('web_you_tab_layout_alignment'))) ?
        'grid-disabled' : currentGridState().className;
    }
    const el = this.gridStateAwareGetElement();
    if (!el || className === this.currentGridClass) return;
    if (className) el.classList.add(className);
    if (this.currentGridClass) el.classList.remove(this.currentGridClass);
    this.currentGridClass = className;
  },
};

/** @polymerBehavior */
const GridStateAwareBehavior = [GridStateAwareBehaviorImpl, ActionHandlerBehavior];

/** @type {!WeakMap<!Object, !Object>} */
const scrollDebouncers = new WeakMap();

/** @type {!WeakMap<!Object, function()>} */
const scrollListeners = new WeakMap();

/**
 * @param {!Object} self
 * @return {function()}
 */
function boundScroll(self) {
  let listener = scrollListeners.get(self);
  if (!listener) scrollListeners.set(self, listener = () => self.onScroll());
  return listener;
}

/**
 * The behaviour of the tabbed page header (kevlar's `ytdTabbedHeaderBehavior`):
 * the tabs and the selected one, and the panel mode that follows the scroll.
 * @polymerBehavior
 */
const TabbedHeaderBehaviorImpl = {
  properties: {
    tabs: Array,
    selected: Object,
    active: Boolean,
    disableHeaderFluidWidth: {type: Boolean, reflectToAttribute: true},
  },
  observers: ['activeChanged(active)', 'guideVisibleChanged(guidePersistentAndVisible)', 'tabsChanged(tabs)'],

  activeChanged() {
    if (this.active) {
      const header = hostDom(this.hostElement).querySelector('#header');
      if (header) header.dispatchEvent(new CustomEvent('iron-resize', {bubbles: true, composed: true}));
      window.addEventListener('scroll', boundScroll(this));
    } else {
      window.removeEventListener('scroll', boundScroll(this));
      this.fire('yt-request-panel-mode-change', {mode: 'seamed'});
    }
  },

  guideVisibleChanged() {
    const header = hostDom(this.hostElement).querySelector('#header');
    if (header) header.dispatchEvent(new CustomEvent('iron-resize', {bubbles: true, composed: true}));
  },

  onScroll() {
    scrollDebouncers.set(this, Debouncer.debounce(scrollDebouncers.get(this), timeOut.after(10), () => {
      const header = hostDom(this.hostElement).querySelector('#header');
      if (!header || !header.polymerController) return;
      const mode = header.polymerController.getScrollState().progress === 1 ? 'standard' : 'seamed';
      this.fire('yt-request-panel-mode-change', {mode});
    }));
  },

  tabsChanged() {
    if (!this.tabs) return;
    let selected = null;
    for (let i = 0; i < this.tabs.length; i++) {
      const tab = this.tabs[i].tabRenderer;
      if (tab && tab.selected) {
        selected = i;
        break;
      }
    }
    this.selected = selected;
  },

  /** @param {!CustomEvent} e */
  onTabsActivate(e) {
    this.fire('yt-navigate', {endpoint: this.tabs[e.detail.selected].tabRenderer.endpoint});
  },
};

/** @polymerBehavior */
const TabbedHeaderBehavior = [...RendererBehavior, ...GuideStateAwareBehavior, TabbedHeaderBehaviorImpl];

