/** @type {?number} */
let scrollbarWidth = null;

/**
 * The width of a scroll bar, from a probe element (memoized).
 * @return {number}
 */
function getScrollbarWidth() {
  if (scrollbarWidth === null) {
    const probe = document.createElement('div');
    probe.style.cssText = 'overflow:auto;position:absolute;top:0;width:100px;height:100px';
    document.body.appendChild(probe);
    scrollbarWidth = probe.offsetWidth - probe.clientWidth;
    probe.remove();
  }
  return scrollbarWidth;
}

/** @type {?{width: number, height: number}} */
let cachedWindowSize = null;

/**
 * The size of the document element's client area, cached unless forced.
 * @param {boolean=} force
 * @return {{width: number, height: number}}
 */
function getWindowSize(force) {
  if (force || !cachedWindowSize) {
    const root = document.documentElement;
    cachedWindowSize = {width: root.clientWidth, height: root.clientHeight};
  }
  return cachedWindowSize;
}

/**
 * The sidebar's width for a window, as a share of the window that grows when
 * the player leaves room for it, bounded by the flags.
 * @param {{width: number, height: number}} win
 * @param {number} ratio The video's height to width ratio.
 * @return {number}
 */
function calculateSidebarWidth(win, ratio) {
  const margin = flagNumber('kevlar_watch_page_horizontal_margin', 16);
  const available = win.width - getScrollbarWidth();
  if (available < flagNumber('kevlar_watch_two_column_width_threshold', TWO_COLUMN_THRESHOLD) ||
      !flag('web_watch_use_sidebar_width_percentage', false)) {
    return flagNumber('kevlar_watch_secondary_width', 402);
  }
  const share = available * flagNumber('kevlar_watch_sidebar_width_percentage', 0.25);
  const nonPlayerHeight = MASTHEAD_HEIGHT + flagNumber('kevlar_watch_page_columns_top_padding', 12) + flagNumber('kevlar_watch_flexy_metadata_height', 48);
  let width = share + Math.max(0, available - (share + 3 * margin + (win.height - nonPlayerHeight) / ratio));
  width = Math.min(Math.max(flagNumber('kevlar_watch_sidebar_min_width', 320), width), flagNumber('kevlar_watch_secondary_max_width', 600));
  if (flag('web_watch_use_secondary_max_width_percent', false)) width = Math.min(width, available * flagNumber('web_watch_secondary_max_width_percent', 0.275));
  return width;
}

/**
 * The player size for a window in the default two-column layout.
 * @param {{width: number, height: number}} win
 * @param {number} ratio
 * @return {{width: number, height: number}}
 */
function calculateNormalPlayerSize(win, ratio) {
  const margin = flagNumber('kevlar_watch_page_horizontal_margin', 16);
  const threshold = flagNumber('kevlar_watch_two_column_width_threshold', TWO_COLUMN_THRESHOLD);
  const nonPlayerHeight = MASTHEAD_HEIGHT + flagNumber('kevlar_watch_page_columns_top_padding', 12) + flagNumber('kevlar_watch_flexy_metadata_height', 48);
  let width = Math.max(win.width, 426 + 2 * margin);
  width = win.width >= threshold ? width - (2 * margin + flagNumber('kevlar_watch_secondary_width', 402) + margin) : width - 2 * margin;
  width = Math.min(width, flagNumber('kevlar_watch_max_player_width', 1280));
  let height = Math.min(width * ratio, win.height - nonPlayerHeight);
  let minHeight = 240;
  if (ratio >= 0.5624) {
    if (win.height < 630 && win.width >= 657 || win.height >= 630 && win.width >= threshold && win.width < LARGE_WINDOW_MIN_WIDTH) minHeight = 360;
    else if (win.height >= 630 && win.width >= LARGE_WINDOW_MIN_WIDTH) minHeight = 480;
  }
  height = Math.max(height, minHeight);
  if (ratio < 1) width = height / ratio;
  else if (win.width >= threshold) width = calculateNormalPlayerSize({width: win.width, height: win.height}, 0.5625).width;
  return {width: Math.round(width), height: Math.round(height)};
}

Polymer({
  is: 'iron-ytl-media-query',
  properties: {
    query: {type: String, observer: 'queryChanged_'},
    queryMatches: {type: Boolean, value: false, notify: true},
  },

  attached() {
    this.queryChanged_(this.query);
  },

  detached() {
    this.removeListener_();
  },

  /** @param {string} query */
  queryChanged_(query) {
    this.removeListener_();
    if (!query || !this.isAttached) return;
    this.mql_ = window.matchMedia(query);
    this.boundChanged_ = this.boundChanged_ || (() => this.queryMatches = !!(this.mql_ && this.mql_.matches));
    this.mql_.addListener(this.boundChanged_);
    this.boundChanged_();
  },

  /** @private */
  removeListener_() {
    if (this.mql_ && this.boundChanged_) this.mql_.removeListener(this.boundChanged_);
    this.mql_ = null;
  },
});

/**
 * The state of the "are you still there" prompt: its pending jobs and flags.
 * A page dispose job resets it (kevlar's `cO9`).
 */
class YouThereManager {
  constructor() {
    this.showWarningJob_ = 0;
    this.showBlockingWarningJob_ = 0;
    this.pausePlaybackJob_ = 0;
    /** @type {?Object} */
    this.youThereData_ = null;
    this.inYouThereFlow_ = false;
    this.isUserPredictedAbsent_ = false;
  }

  reset() {
    cancel(this.showWarningJob_);
    cancel(this.showBlockingWarningJob_);
    cancel(this.pausePlaybackJob_);
    this.showWarningJob_ = this.showBlockingWarningJob_ = this.pausePlaybackJob_ = 0;
    this.youThereData_ = null;
    this.inYouThereFlow_ = false;
    this.isUserPredictedAbsent_ = false;
  }
}

