/**
 * @fileoverview The infocards section of the structured description (the
 * creator's links and the video's info cards) and the elements its cards
 * stamp, from kevlar's classes and templates. Not ported: the lockups of
 * playlists, videos and channels that a compact infocard can hold besides a
 * media lockup (the data has only media lockups).
 */
import {Polymer, withHandles} from '../../framework/polysi/register.js';
import {flag} from '../../framework/flags.js';
import {registerRenderer} from '../../framework/registry.js';
import {RendererBehavior} from '../renderer-behavior.js';
import {YtRendererStamperBehavior} from '../renderer-stamper.js';
import {HorizontalListBehavior} from '../horizontal-list.js';
import {TaskEmitterBehavior} from '../container-behaviors.js';
import {template as infocardsTemplate} from '../../../gen/templates/ytl-video-description-infocards-section-renderer.js';
import {template as compactInfocardTemplate} from '../../../gen/templates/ytl-compact-infocard-renderer.js';
import {template as mediaLockupTemplate} from '../../../gen/templates/ytl-media-lockup-renderer.js';

/** How long the resizing of the section has to settle before the list resets. */
const RESIZE_DELAY_MS = 200;

Polymer(withHandles({
  _template: infocardsTemplate,
  is: 'ytl-video-description-infocards-section-renderer',
  behaviors: [RendererBehavior, YtRendererStamperBehavior, ...HorizontalListBehavior, TaskEmitterBehavior],
  properties: {
    data: Object,
    engagementPanel: {type: Boolean, reflectToAttribute: true},
    sdRedesign: {type: Object, reflectToAttribute: true},
    enableRightArrowHidden: Object,
    hideRightArrow: {type: Object, computed: '__compute__hideRightArrow(enableRightArrowHidden,atEnd)'},
    creatorCustomUrlButtons: {type: Object, computed: '__compute__creatorCustomUrlButtons(data)'},
    showCreatorCustomUrlButtons: {type: Boolean, reflectToAttribute: true},
    channelAvatarSize: Number,
  },

  created() {
    this.sdRedesign = flag('web_typography_changes_sd_redesign');
    this.enableRightArrowHidden = flag('channel_details_shelf_resize_observer') && !!window.ResizeObserver;
    this.showCreatorCustomUrlButtons = true;
    this.channelAvatarSize = 36;
  },

  attached() {
    if (!this.enableRightArrowHidden) return;
    this.resizeTimer_ = 0;
    this.resizeObserver = new ResizeObserver(() => {
      if (this.resizeTimer_) return;
      this.resizeTimer_ = setTimeout(() => {
        this.resizeTimer_ = 0;
        this.reset();
      }, RESIZE_DELAY_MS);
    });
    this.resizeObserver.observe(this.hostElement);
  },

  detached() {
    if (!this.enableRightArrowHidden) return;
    if (this.resizeObserver) this.resizeObserver.disconnect();
    clearTimeout(this.resizeTimer_);
    this.resizeTimer_ = 0;
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.infocards': {id: 'infocards-section', mapping: {'compactInfocardRenderer': 'ytl-compact-infocard-renderer'}},
      'creatorCustomUrlButtons': {id: 'items', mapping: {'buttonRenderer': 'ytl-button-renderer', 'buttonViewModel': 'ytl-yt-button-view-model'}},
    };
  },

  /** @return {string} */
  getItemsPath() {
    return 'data.creatorCustomUrlButtons';
  },

  /**
   * @param {boolean} enabled
   * @param {boolean} atEnd
   * @return {boolean}
   */
  __compute__hideRightArrow(enabled, atEnd) {
    return !!enabled && atEnd;
  },

  /**
   * The creator's videos, about and custom link buttons, in this order.
   * @param {?Object} data
   * @return {?Array<!Object>}
   */
  __compute__creatorCustomUrlButtons(data) {
    if (!data) return undefined;
    const buttons = [];
    if (data.creatorVideosButton) buttons.push(data.creatorVideosButton);
    if (data.creatorAboutButton) buttons.push(data.creatorAboutButton);
    for (const button of data.creatorCustomUrlButtons || []) buttons.push(button);
    return buttons;
  },
}, ['ytRendererBehavior', 'ytRendererstamperBehavior', 'ytdHorizontalListBehavior']));
registerRenderer('videoDescriptionInfocardsSectionRenderer', 'ytl-video-description-infocards-section-renderer');

Polymer(withHandles({
  _template: compactInfocardTemplate,
  is: 'ytl-compact-infocard-renderer',
  behaviors: [RendererBehavior, YtRendererStamperBehavior],
  properties: {data: Object},

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.content': {id: 'content', mapping: {'mediaLockupRenderer': {component: 'ytl-media-lockup-renderer', params: {'isCompact': true}}}},
    };
  },
}, ['ytRendererBehavior', 'componentBehavior', 'ytRendererstamperBehavior']));
registerRenderer('compactInfocardRenderer', 'ytl-compact-infocard-renderer');

Polymer(withHandles({
  _template: mediaLockupTemplate,
  is: 'ytl-media-lockup-renderer',
  behaviors: [RendererBehavior],
  properties: {
    data: Object,
    isCompact: {type: Object, reflectToAttribute: true},
    thumbnailWidth: {type: Number, computed: '__compute__thumbnailWidth(isCompact)'},
    openNewWindow: {type: Boolean, computed: '__compute__openNewWindow(data)'},
  },

  initFields_() {
    this.isCompact = false;
  },

  /**
   * @param {boolean} compact
   * @return {number}
   */
  __compute__thumbnailWidth(compact) {
    return compact ? 112 : 80;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__openNewWindow(data) {
    const endpoint = data && data.endpoint;
    const target = endpoint && endpoint.urlEndpoint && endpoint.urlEndpoint.target;
    return target === 'TARGET_NEW_WINDOW';
  },
}, ['ytRendererBehavior', 'componentBehavior']));
registerRenderer('mediaLockupRenderer', 'ytl-media-lockup-renderer');
