/**
 * @fileoverview Tracing spans around component renders and connected
 * callbacks. The tracing config is read once at load, as YouTube's is; with
 * `web_tracing_all_components` off, a span only runs the callback.
 */
import {flag} from './flags.js';

/** @type {!Array<{name: string, start: number, end: number}>} */
const spans = [];
const traceAllComponents = flag('web_tracing_all_components');

/**
 * Runs `fn` inside a span named `name`.
 * @template T
 * @param {string} name
 * @param {function(): T} fn
 * @return {T}
 */
export function traceSpan(name, fn) {
  if (!traceAllComponents) return fn();
  const start = performance.now();
  try {
    return fn();
  } finally {
    spans.push({name, start, end: performance.now()});
    if (spans.length > 500) spans.splice(0, 250);
  }
}

/**
 * Runs `fn`, and reports errors instead of letting them escape.
 * @param {string} context
 * @param {function()} fn
 */
export function guarded(context, fn) {
  try {
    fn();
  } catch (e) {
    console.error(`${context} failed`, e);
  }
}
