/**
 * @fileoverview `ps-dom-repeat` and `ps-dom-if`, the template helpers of
 * signal-schema templates. The template parser wraps the `<template>` of a
 * `dom-repeat` or `dom-if` in these elements, and the stamper hands them
 * the parsed template, the parent's signal proxy, the event host and the
 * parent's enabled signal.
 *
 * Both keep their input in a store and render from an effect on the
 * parent's proxy, debounced on a microtask; every render fires
 * `dom-change`. An instance has its own signal proxy over a small model;
 * other keys resolve to forwarding stores, which re-notify the parent's
 * newest change record unless the instance's updates are disabled.
 * `ps-dom-if` hides its instance when the condition turns false (unless it
 * restamps), and disables the instance's updates until it is shown again.
 * `ps-dom-repeat` reuses instances by position.
 */
import {Debouncer, enqueueDebouncer} from '@polymer/polymer/lib/utils/debounce.js';
import {microTask} from '@polymer/polymer/lib/utils/async.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {createSignal, untracked} from '../signals.js';
import {SignalProxy, toPath} from './proxy.js';
import {PathStore} from './store.js';
import {stampTemplate} from './template.js';

let styleInjected = false;

function injectStyle() {
  if (styleInjected) return;
  styleInjected = true;
  const style = document.createElement('style');
  style.textContent = 'ps-dom-if,ps-dom-repeat{display:none;}';
  document.head.appendChild(style);
}

/**
 * Hides or shows stamped nodes as Polymer's `dom-if` does, with the state
 * kept per node.
 * @param {boolean} hide
 * @param {!Array<!Node>} nodes
 */
function showHideNodes(hide, nodes) {
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    const api = node.showHideApi || (node.showHideApi = {});
    if (node.nodeType === Node.TEXT_NODE) {
      if (hide) {
        api.polymerTextContent = node.textContent;
        node.textContent = '';
      } else if (api.polymerTextContent !== undefined) {
        node.textContent = api.polymerTextContent;
      }
    } else if (node.localName === 'slot') {
      if (hide) {
        const comment = document.createComment('hidden-slot');
        api.replacement = comment;
        /** @type {!Node} */ (node.parentNode).replaceChild(comment, node);
        nodes[i] = comment;
        comment.showHideApi = {original: node};
      }
    } else if (node.nodeType === Node.COMMENT_NODE && api.original && !hide) {
      /** @type {!Node} */ (node.parentNode).replaceChild(api.original, node);
      nodes[i] = api.original;
    } else if (node instanceof HTMLElement) {
      if (hide) {
        api.polymerDisplay = node.style.display;
        node.style.display = 'none';
      } else {
        node.style.display = api.polymerDisplay || '';
      }
    }
    if (typeof node.showHideChildren === 'function') node.showHideChildren(hide);
  }
}

/**
 * @typedef {{
 *   proxy: !SignalProxy,
 *   model: !Object,
 *   children: !Array<!Node>,
 *   root: !DocumentFragment,
 *   disabled: function(): boolean,
 *   setDisabled: function(boolean),
 * }}
 */
let Instance;

/** The shared empty item list for non-array `items`. */
const EMPTY_ITEMS = [];

/** Common parts of the two helpers. */
class TemplateHelper extends HTMLElement {
  constructor() {
    super();
    /** @type {?Object} */
    this.templateInfo = null;
    /** @type {?SignalProxy} */
    this.parentSignalProxy = null;
    /** @type {?Object} */
    this.eventListenerHost = null;
    /** @type {?function(): boolean} */
    this.stampingEnabled = null;
    /** @type {?Debouncer} */
    this.renderDebouncer_ = null;
    /** @type {?{destroy: function()}} */
    this.renderEffect_ = null;
  }

  /** Schedules a render in a microtask. */
  debounceRender_() {
    this.renderDebouncer_ = Debouncer.debounce(this.renderDebouncer_, microTask, () => this.renderImpl());
    enqueueDebouncer(this.renderDebouncer_);
  }

  /** Renders now if a render is pending. */
  render() {
    if (this.renderDebouncer_) this.renderDebouncer_.flush();
  }

  renderImpl() {}

  /**
   * Creates an instance with its own proxy over `model`.
   * @param {!Object} model
   * @param {function(string): ?string=} alias Maps a key to another key of
   *     the model.
   * @return {!Instance}
   */
  createInstance_(model, alias) {
    const parent = /** @type {!SignalProxy} */ (this.parentSignalProxy);
    const [disabled, setDisabled] = createSignal(false, undefined);
    const proxy = new SignalProxy(model, (key, self) => {
      const target = alias ? alias(key) : null;
      if (target) return self.resolve(target);
      if (Object.prototype.hasOwnProperty.call(model, key)) return null;
      const store = new PathStore(key, undefined);
      const source = parent.resolve(key);
      const reader = source.getChangeRecordSignal([]);
      self.effect(() => {
        const record = reader();
        if (disabled()) return;
        untracked(() => store.notifyPath(toPath(record.path).slice(1), {value: record.value}));
      }, key);
      return store;
    }, parent);
    const methodHost = parent.methodHost || parent.model;
    proxy.methodHost = methodHost;
    proxy.isInstance = true;
    const parentEnabled = this.stampingEnabled;
    const {dom} = proxy.runUntracked(() => stampTemplate(/** @type {!Object} */ (this.templateInfo), {
      proxy,
      methodHost,
      eventHost: /** @type {!Object} */ (this.eventListenerHost),
      getModel: () => model,
      enabled: parentEnabled || undefined,
    }));
    return {proxy, model, children: Array.from(dom.childNodes), root: dom, disabled, setDisabled};
  }

  /**
   * Moves an instance's nodes back into its fragment and disposes it.
   * @param {!Instance} instance
   */
  removeInstance_(instance) {
    for (const node of instance.children) {
      const parent = wrap(node).parentNode;
      if (parent && parent !== instance.root) wrap(parent).removeChild(node);
      instance.root.appendChild(node);
    }
    instance.proxy.dispose();
  }

  fireDomChange_() {
    this.dispatchEvent(new CustomEvent('dom-change', {bubbles: true, composed: true}));
  }
}

class PsDomIf extends TemplateHelper {
  constructor() {
    super();
    /** @type {?Instance} */
    this.instance = null;
    /** @private @const {!PathStore} */
    this.condition_ = new PathStore('if', false);
  }

  /** @return {boolean} */
  get if() {
    return /** @type {boolean} */ (this.condition_.peek([]));
  }

  /** @param {*} value */
  set if(value) {
    if (!value && this.instance) this.instance.setDisabled(true);
    this.condition_.setWithPath([], !!value);
  }

  connectedCallback() {
    injectStyle();
    const parent = this.parentSignalProxy;
    if (!parent) {
      console.error('ps-dom-if without a parent signal proxy');
      return;
    }
    if (this.renderEffect_) return;
    this.renderEffect_ = parent.effect(() => {
      this.condition_.getWithPath([]);
      untracked(() => this.debounceRender_());
    }, 'ps-dom-if');
  }

  disconnectedCallback() {
    const parent = this.parentNode;
    if (this.instance && (!parent || !parent.isConnected)) {
      this.removeInstance_(this.instance);
      this.instance = null;
    }
    if (this.renderEffect_) {
      this.renderEffect_.destroy();
      this.renderEffect_ = null;
    }
  }

  /** @override */
  renderImpl() {
    const show = /** @type {boolean} */ (this.condition_.peek([]));
    const parent = wrap(this).parentNode;
    if (show) {
      if (!this.instance) {
        if (!parent || !this.templateInfo) return;
        const parentProxy = /** @type {!SignalProxy} */ (this.parentSignalProxy);
        this.instance = this.createInstance_(parentProxy.isInstance ? Object.assign({}, parentProxy.model) : {});
        wrap(parent).insertBefore(this.instance.root, this);
      } else {
        const last = this.instance.children[this.instance.children.length - 1];
        if (parent && last && wrap(last).nextSibling !== this) {
          for (const node of this.instance.children) wrap(parent).insertBefore(node, this);
        }
      }
    } else if (this.hasAttribute('restamp') && this.instance) {
      this.removeInstance_(this.instance);
      this.instance = null;
    }
    if (this.instance) {
      showHideNodes(!show, this.instance.children);
      if (show) this.instance.setDisabled(false);
    }
    this.fireDomChange_();
  }

  /** @param {boolean} hide */
  showHideChildren(hide) {
    if (this.instance) showHideNodes(hide || !this.condition_.peek([]), this.instance.children);
  }
}

class PsDomRepeat extends TemplateHelper {
  constructor() {
    super();
    /** @type {!Array<!Instance>} */
    this.instances = [];
    /** @private @const {!PathStore} */
    this.items_ = new PathStore('items', EMPTY_ITEMS);
  }

  /** @return {!Array<*>} */
  get items() {
    return /** @type {!Array<*>} */ (this.items_.peek([]));
  }

  /** @param {*} value */
  set items(value) {
    this.items_.setWithPath([], Array.isArray(value) ? value : EMPTY_ITEMS);
  }

  /**
   * @param {string} name
   * @return {boolean}
   */
  canNotifyPath(name) {
    return name === 'items';
  }

  /**
   * @param {string} path
   * @param {*=} value
   */
  notifyPath(path, value) {
    const parts = toPath(path);
    if (parts[0] !== 'items') return;
    this.items_.notifyPath(parts.slice(1), arguments.length > 1 ? {value} : undefined);
  }

  /** @return {string} */
  get as_() {
    return this.getAttribute('as') || 'item';
  }

  /** @return {string} */
  get indexAs_() {
    return this.getAttribute('index-as') || 'index';
  }

  /** @return {string} */
  get itemsIndexAs_() {
    return this.getAttribute('items-index-as') || 'itemsIndex';
  }

  connectedCallback() {
    injectStyle();
    const parent = this.parentSignalProxy;
    if (!parent) {
      console.error('ps-dom-repeat without a parent signal proxy');
      return;
    }
    if (!this.renderEffect_) {
      const reader = this.items_.getChangeRecordSignal([]);
      this.renderEffect_ = parent.effect(() => {
        const record = reader();
        untracked(() => {
          const parts = toPath(record.path);
          if (parts.length === 1 || parts[1] === 'splices' || parts[1] === 'length') {
            this.debounceRender_();
          } else {
            const instance = this.instances[Number(parts[1])];
            if (instance) instance.proxy.notifyPath([this.as_].concat(parts.slice(2)), {value: record.value});
          }
        });
      }, 'ps-dom-repeat');
    } else if (this.instances.length) {
      const parentNode = wrap(/** @type {!Node} */ (wrap(this).parentNode));
      for (const instance of this.instances) {
        for (const node of instance.children) parentNode.insertBefore(node, this);
      }
    }
  }

  disconnectedCallback() {
    if (this.parentNode && this.parentNode.isConnected) return;
    for (const instance of this.instances) this.removeInstance_(instance);
    this.instances = [];
    if (this.renderEffect_) {
      this.renderEffect_.destroy();
      this.renderEffect_ = null;
    }
  }

  /** @override */
  renderImpl() {
    const parent = wrap(this).parentNode;
    if (!parent || !this.templateInfo) return;
    const items = this.items;
    const as = this.as_;
    const indexAs = this.indexAs_;
    const itemsIndexAs = this.itemsIndexAs_;
    const reused = Math.min(items.length, this.instances.length);
    for (let i = 0; i < reused; i++) {
      const proxy = this.instances[i].proxy;
      proxy.setWithPath([as], items[i]);
      proxy.setWithPath([indexAs], i);
    }
    const parentProxy = /** @type {!SignalProxy} */ (this.parentSignalProxy);
    const parentModel = parentProxy.isInstance ? parentProxy.model : null;
    for (let i = reused; i < items.length; i++) {
      const model = Object.assign({}, parentModel, {[as]: items[i], [indexAs]: i});
      const instance = this.createInstance_(model, key => (key === itemsIndexAs ? indexAs : null));
      this.instances.push(instance);
      const next = this.instances[i + 1];
      wrap(parent).insertBefore(instance.root, next ? next.children[0] : this);
    }
    while (this.instances.length > items.length) {
      this.removeInstance_(/** @type {!Instance} */ (this.instances.pop()));
    }
    this.fireDomChange_();
  }

  /** @param {boolean} hide */
  showHideChildren(hide) {
    for (const instance of this.instances) showHideNodes(hide, instance.children);
  }

  /**
   * @param {!Node} el
   * @return {*}
   */
  itemForElement(el) {
    const instance = this.instanceForElement_(el);
    return instance ? instance.model[this.as_] : undefined;
  }

  /**
   * @param {!Node} el
   * @return {number|undefined}
   */
  indexForElement(el) {
    const instance = this.instanceForElement_(el);
    return instance ? this.instances.indexOf(instance) : undefined;
  }

  /**
   * @param {!Node} el
   * @return {?Instance}
   * @private
   */
  instanceForElement_(el) {
    for (const instance of this.instances) {
      for (const node of instance.children) {
        if (node === el || node.contains(el)) return instance;
      }
    }
    return null;
  }
}

customElements.define('ps-dom-if', PsDomIf);
customElements.define('ps-dom-repeat', PsDomRepeat);
