/**
 * @fileoverview The app's job scheduler. Jobs have a priority. Each
 * animation frame runs all IMMEDIATE and HIGH jobs, then RENDER and DEFERRED
 * jobs until the frame budget is used up; a single job may overrun it. IDLE
 * jobs run in idle callbacks. The benchmark steps wait for `whenIdle()`.
 */

import {microTask} from '@polymer/polymer/lib/utils/async.js';

/** @enum {number} */
export const Priority = {
  IMMEDIATE: 0,
  HIGH: 1,
  RENDER: 2,
  DEFERRED: 3,
  IDLE: 4,
};

/** 16.7 ms frame minus 3 ms for the browser's own work. */
const FRAME_BUDGET_MS = 13.7;
const IDLE_TIMEOUT_MS = 3000;

/**
 * @typedef {{fn: function(), id: number}}
 */
let Job;

/** @type {!Array<!Array<!Job>>} */
const queues = [[], [], [], [], []];
let nextId = 1;
let frameRequested = false;
let idleRequested = false;
/** @type {!Set<number>} */
const cancelled = new Set();
/** @type {!Array<function()>} */
let idleWaiters = [];
let pendingTimers = 0;

/**
 * @param {function()} fn
 * @param {!Priority=} priority
 * @return {number} A job id for `cancel()`.
 */
export function schedule(fn, priority = Priority.RENDER) {
  const job = {fn, id: nextId++};
  queues[priority].push(job);
  if (priority !== Priority.IDLE) requestFrame();
  else if (!hasFrameJobs()) requestIdle();
  return job.id;
}

/** @param {number} id */
export function cancel(id) {
  if (id) cancelled.add(id);
}

function requestFrame() {
  if (frameRequested) return;
  frameRequested = true;
  requestAnimationFrame(runFrame);
}

function requestIdle() {
  if (idleRequested) return;
  idleRequested = true;
  requestIdleCallback(runIdle, {timeout: IDLE_TIMEOUT_MS});
}

/**
 * @param {number} priority
 * @return {?Job}
 */
function take(priority) {
  const q = queues[priority];
  while (q.length) {
    const job = /** @type {!Job} */ (q.shift());
    if (cancelled.has(job.id)) {
      cancelled.delete(job.id);
      continue;
    }
    return job;
  }
  return null;
}

/** @param {number} frameStart */
function runFrame(frameStart) {
  frameRequested = false;
  let job;
  while ((job = take(Priority.IMMEDIATE) || take(Priority.HIGH))) job.fn();
  const deadline = frameStart + FRAME_BUDGET_MS;
  for (let p = Priority.RENDER; p <= Priority.DEFERRED; p++) {
    while (performance.now() < deadline && (job = take(p))) {
      job.fn();
      // A newly queued urgent job preempts the remaining work.
      while ((job = take(Priority.IMMEDIATE) || take(Priority.HIGH))) job.fn();
    }
  }
  if (hasFrameJobs()) requestFrame();
  else if (queues[Priority.IDLE].length) requestIdle();
  checkIdle();
}

/** @param {!IdleDeadline} deadline */
function runIdle(deadline) {
  idleRequested = false;
  // Idle work waits until the frame queues are empty; runFrame requests
  // another idle callback when they are.
  if (hasFrameJobs()) return;
  let job;
  do {
    job = take(Priority.IDLE);
    if (job) job.fn();
  } while (job && (deadline.didTimeout || deadline.timeRemaining() > 1));
  if (queues[Priority.IDLE].length) requestIdle();
  checkIdle();
}

/** @return {boolean} */
function hasFrameJobs() {
  for (let p = 0; p < Priority.IDLE; p++) if (queues[p].length) return true;
  return false;
}

/**
 * Like Polymer's afterNextRender: runs `fn` after the next frame has been
 * rendered.
 * @param {*} context
 * @param {function(...?)} fn
 * @param {!Array<*>=} args
 */
export function afterNextRender(context, fn, args) {
  pendingTimers++;
  requestAnimationFrame(() => {
    setTimeout(() => {
      pendingTimers--;
      fn.apply(context, args || []);
      checkIdle();
    }, 0);
  });
}

/**
 * Runs `fn` in a microtask, batched with other callbacks (Polymer's
 * `microTask`, which YouTube's deferred callbacks use).
 * @param {function()} fn
 * @return {number}
 */
export function soon(fn) {
  return microTask.run(fn);
}

/**
 * Runs `fn` after `ms`, tracked so that `whenIdle()` waits for it.
 * @param {function()} fn
 * @param {number} ms
 * @return {number}
 */
export function later(fn, ms) {
  pendingTimers++;
  return setTimeout(() => {
    pendingTimers--;
    fn();
    checkIdle();
  }, ms);
}

/**
 * Tracks an asynchronous operation (a simulated fetch, an IndexedDB
 * transaction) so that `whenIdle()` waits for it.
 * @template T
 * @param {!Promise<T>} promise
 * @return {!Promise<T>}
 */
export function track(promise) {
  pendingTimers++;
  const done = () => {
    pendingTimers--;
    Promise.resolve().then(checkIdle);
  };
  promise.then(done, done);
  return promise;
}

/** @return {boolean} */
function isIdle() {
  return !hasFrameJobs() && !queues[Priority.IDLE].length && pendingTimers === 0;
}

function checkIdle() {
  if (!idleWaiters.length || !isIdle()) return;
  const waiters = idleWaiters;
  idleWaiters = [];
  for (const w of waiters) w();
}

/**
 * Resolves once no jobs, idle work or tracked async operations are pending.
 * @return {!Promise<void>}
 */
export function whenIdle() {
  return new Promise(resolve => {
    idleWaiters.push(resolve);
    // Let microtasks (Polymer's batched property effects) settle first.
    setTimeout(checkIdle, 0);
  });
}
