/**
 * @fileoverview Core Polymer elements used by every renderer: formatted
 * strings, icons, images, tooltips, interaction ripples, icon buttons and
 * the spinner.
 */
import {Polymer, setRegistrationOptions} from '../../framework/polysi/register.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {HostDom, hostDom, styleSubtree} from '../../framework/host-dom.js';
import {ICON_RENAMES, IconManager, iconManager, iconTypeToName, isResolvableIcon, resolveIconShape, setIconScheduling, splitIconName} from '../../framework/icons.js';
import {flag, getConfig} from '../../framework/flags.js';
import {rootInjector} from '../../framework/injector.js';
import {createSignal, defineInjectable, registerInjectable} from '../../framework/signals.js';
import {HostElementBehavior, TemplateHelpersBehavior} from '../../framework/polysi/base-behaviors.js';
import {h} from '../../framework/vm/jsx.js';
import {renderEffect, render} from '../../framework/vm/render.js';
import {writeSignal} from '../../framework/vm/effect.js';
import {ActionHandlerBehavior} from '../item-behaviors.js';
import {IronA11yKeysBehavior} from '../../../vendor/polymer/iron-a11y-keys-behavior/iron-a11y-keys-behavior.js';
import {ComponentBehavior, RendererCoreBehavior, VisibilityObserverBehavior, VisualElementBehavior} from '../renderer-behavior.js';
import {linkConfig} from '../../framework/link.js';
import {getText} from '../../framework/text.js';
import {Priority, afterNextRender, schedule, track} from '../scheduler.js';
import {fireCommand} from '../commands.js';
import {observeVisibility} from '../visibility.js';
import {argbToCss, pickSource} from '../vm/primitives.js';
import {template as imgShadowTemplate} from '../../../gen/templates/ytl-img-shadow.js';
import '../../../vendor/polymer/paper-tooltip/paper-tooltip.js';
import {template as interactionTemplate} from '../../../gen/templates/ytl-interaction.js';
import {template as iconButtonTemplate} from '../../../gen/templates/ytl-icon-button.js';
import {template as spinnerTemplate} from '../../../gen/templates/tp-ytl-paper-spinner.js';
import {template as spinnerLiteTemplate} from '../../../gen/templates/tp-ytl-paper-spinner-lite.js';
import {template as iconTemplate} from '../../../gen/templates/ytl-icon.js';
import {template as formattedStringTemplate} from '../../../gen/templates/ytl-formatted-string.js';

/**
 * Replaces the content of the host `el` with `nodes`.
 * @param {!Element} el
 * @param {!Array<!Node>} nodes
 */
function replaceChildren(el, nodes) {
  const content = hostDom(el);
  let c;
  while ((c = content.lastChild)) content.removeChild(c);
  for (const n of nodes) content.appendChild(n);
}

/**
 * Pasting into plain-text-only content inserts text only.
 * @polymerBehavior
 */
const PlaintextBehavior = {
  properties: {
    plaintextOnly: {type: Boolean, value: false},
  },

  attached() {
    if (!this.plaintextOnly) return;
    this.boundOnPaste_ = this.boundOnPaste_ || this.onPaste_.bind(this);
    this.hostElement.addEventListener('paste', this.boundOnPaste_);
  },

  detached() {
    if (this.boundOnPaste_) this.hostElement.removeEventListener('paste', this.boundOnPaste_);
  },

  /** @param {!ClipboardEvent} e */
  onPaste_(e) {
    e.preventDefault();
    const text = e.clipboardData ? e.clipboardData.getData('text/plain') : '';
    document.execCommand('insertText', false, text);
  },
};

/** The style classes a run's node can have. */
const RUN_STYLE_CLASSES = ['bold', 'deemphasize', 'italic', 'strikethrough', 'bracket', 'error-underline'];

// Registered in mode 0, as YouTube's yt-formatted-string is.
setRegistrationOptions('ytl-formatted-string', {mode: 0});
Polymer({
  _template: formattedStringTemplate,
  is: 'ytl-formatted-string',
  behaviors: [IronA11yKeysBehavior, PlaintextBehavior, ComponentBehavior, VisibilityObserverBehavior, VisualElementBehavior,
    RendererCoreBehavior],
  properties: {
    text: Object,
    noEndpoints: Boolean,
    noStyles: Boolean,
    ignoreShadyDom: Boolean,
    hasEmoji: Boolean,
    disableAttributedString: Boolean,
    isOverlay: Boolean,
    linkInheritColor: Boolean,
    noPreWrap: Boolean,
    userInput: Boolean,
    enableContentEditable: Boolean,
    respectHtmlDir: Boolean,
    respectLangDir: Boolean,
    isDarkTheme: {type: Boolean, reflectToAttribute: true},
    forceDefaultStyle: {type: Boolean, reflectToAttribute: true},
    ellipsisTruncate: {type: Boolean, reflectToAttribute: true},
    isEmpty: {type: Boolean, reflectToAttribute: true},
    splitLines: {type: Boolean, value: false, reflectToAttribute: true},
    emojiSize: {type: Number, value: 16},
    target: String,
    overrideAriaLabel: String,
    ellipsisTruncateStyling: {type: Boolean, reflectToAttribute: true,
      computed: 'computeEllipsisTruncateStyling(ellipsisTruncate, useYtAttributedString)'},
    ariaLabel: {type: String, reflectToAttribute: true, computed: 'computeAriaLabel_(text.accessibility.accessibilityData.label)'},
    hasLinkOnly_: {type: Boolean, reflectToAttribute: true, computed: 'computeHasLinkOnly_(text.runs)'},
    useMixedDirectionFormattedStrings: {type: Boolean, computed: '__compute__useMixedDirectionFormattedStrings(plaintextOnly)'},
    useYtAttributedString: {type: Boolean, computed: 'computeUseAttributedString(text)'},
  },
  observers: [
    'textChanged(text)',
    'ellipsisTruncateChanged_(ellipsisTruncate)',
    'overrideAriaLabelChanged_(overrideAriaLabel)',
    'enableContentEditableChanged_(enableContentEditable)',
  ],

  /** @return {!Object} */
  get ytPlaintextBehavior() {
    return this;
  },

  /** @return {!Object} */
  get ytComponentBehavior() {
    return this;
  },

  /** @return {!Object} */
  get ytRendererBehavior() {
    return this;
  },

  created() {
    this.ignoreShadyDom = false;
    this.hasChange_ = false;
    this.hasSetTitle_ = false;
    this.useIOObserverForVisibilityLogging_ = flag('kevlar_use_vimio_behavior') && getConfig('CLIENT_NAME', 'WEB') === 'WEB';
    this.ytFormattedStringObserverHandlerKeys_ = undefined;
    this.useIOObserverForVisibilityLogging_ = flag('kevlar_use_vimio_behavior') && getConfig('CLIENT_NAME', 'WEB') === 'WEB';
    this.isEmpty = true;
  },

  ready() {
    const host = this.hostElement;
    if (getConfig('HTML_DIR', 'ltr') === 'rtl') {
      if (this.useMixedDirectionFormattedStrings) host.dir = 'rtl';
      else if (!this.respectHtmlDir) host.dir = 'auto';
    } else if (this.respectLangDir) {
      host.dir = 'auto';
      host.style.textAlign = 'left';
    }
    this.enableContentEditableChanged_();
  },

  attached() {
    if (this.hasChange_) this.textChanged_(this.text);
  },

  detached() {
    this.unobserveIOObservers_();
  },

  /** Removes the content from the end, up to a `STYLE` element. */
  clearContents_() {
    const root = this.getRoot();
    for (let child = root.lastChild; child && /** @type {?} */ (child).tagName !== 'STYLE'; child = root.lastChild) {
      try {
        root.removeChild(child);
      } catch (e) {
        break;
      }
    }
  },

  unobserveIOObservers_() {
    const observer = this.visibilityObserver;
    const keys = this.ytFormattedStringObserverHandlerKeys_;
    if (!this.useIOObserverForVisibilityLogging_ || !observer || !keys) return;
    for (const key of keys) observer.unobserveByKey(key);
    keys.length = 0;
  },

  textChanged() {
    this.textChanged_(this.text);
  },

  /**
   * Writes `text` into the shady root: a simple string as `textContent`,
   * runs through `updateText_`. Deferred until the first `attached`.
   * @param {*} text
   */
  textChanged_(text) {
    if (this.isAttached === undefined) {
      this.hasChange_ = true;
      return;
    }
    this.hasChange_ = false;
    const t = /** @type {?} */ (text);
    this.isEmpty = !t || (!t.runs && !t.simpleText);
    if (flag('web_replace_formatted_with_attributed_string')) {
      if (this.useYtAttributedString) {
        this.resetForAttributedString();
        return;
      }
      this.resetForFormattedString();
    }
    this.unobserveIOObservers_();
    const host = this.hostElement;
    for (let child = host.firstChild; child && child.nodeName === 'FONT';) {
      const font = child;
      child = child.nextSibling;
      host.removeChild(font);
    }
    const root = this.getRoot();
    if (this.isEmpty) {
      this.clearContents_();
      return;
    }
    this.ellipsisTruncateChanged_();
    let simple = t.simpleText;
    if (!simple && t.runs && t.runs.length === 1 && this.isSimpleString_(t.runs[0])) simple = t.runs[0].text;
    if (simple !== undefined && !this.respectHtmlDir && this.useMixedDirectionFormattedStrings &&
        getConfig('HTML_DIR', 'ltr') === 'rtl') {
      host.dir = 'auto';
    }
    if (simple !== undefined) {
      try {
        root.textContent = simple;
      } catch (e) {}
      if (!root.textContent) this.isEmpty = true;
    } else {
      if (this.ellipsisTruncate) host.classList.add('complex-string');
      else host.classList.remove('complex-string');
      if (t.runs) this.updateText_(t.runs);
      if (!root.textContent && !this.hasEmoji) this.isEmpty = true;
    }
  },

  /**
   * @param {!Object} run
   * @return {boolean}
   */
  isSimpleString_(run) {
    return (this.noEndpoints || !run.navigationEndpoint) && !run.emoji &&
        (this.noStyles || !(run.bold || run.deemphasize || run.italics || run.strikethrough || run.errorUnderline ||
          run.bracket || run.textColor)) && !run.loggingDirectives;
  },

  /**
   * Updates the leading nodes that fit the runs in place, removes the
   * rest, and appends nodes for the remaining runs.
   * @param {!Array<!Object>} runs
   */
  updateText_(runs) {
    const count = runs.length;
    const root = this.getRoot();
    let node = root.firstChild;
    while (node && node.nodeName === 'STYLE') node = node.nextSibling;
    let i = 0;
    while (i < count && node) {
      const run = runs[i];
      const text = flag('remove_cr_char') && run.text ? run.text.replace('\r', '') : run.text;
      if (this.isSimpleString_(run) && !this.useMixedDirectionFormattedStrings) {
        if (node.nodeName !== '#text') break;
        if (node.textContent != text) node.textContent = text;
        i++;
        node = node.nextSibling;
        continue;
      }
      if (run.emoji) break;
      if (!this.noEndpoints && run.navigationEndpoint) {
        if (node.nodeName !== 'A') break;
        this.setDataOnAnchor_(/** @type {!Element} */ (node), run.navigationEndpoint);
      } else if (node.nodeName !== 'SPAN') {
        break;
      }
      this.setNodeStyle_(run, /** @type {!Element} */ (node));
      this.setUpVisibilityLogging_(run, /** @type {!Element} */ (node));
      if (node.textContent != text) node.textContent = text;
      i++;
      node = node.nextSibling;
    }
    if (node) {
      const keep = i ? node.previousSibling : null;
      for (let last = root.lastChild; last && last != keep; last = root.lastChild) {
        try {
          root.removeChild(last);
        } catch (e) {
          break;
        }
      }
    }
    if (i !== count) this.addTextNodes_(runs, i);
  },

  /**
   * Appends nodes for `runs` from `start` on, as one fragment.
   * @param {!Array<!Object>} runs
   * @param {number} start
   */
  addTextNodes_(runs, start) {
    const fragment = document.createDocumentFragment();
    for (let i = start; i < runs.length; i++) {
      const run = runs[i];
      const text = flag('remove_cr_char') && run.text ? run.text.replace('\r', '') : run.text;
      if (this.isSimpleString_(run) && !this.useMixedDirectionFormattedStrings) {
        fragment.appendChild(document.createTextNode(text));
        continue;
      }
      const emoji = run.emoji;
      if (emoji) {
        if (emoji.image) {
          const img = document.createElement('img');
          if (!emoji.isCustomEmoji) img.classList.add('small-emoji');
          img.classList.add('emoji');
          if (emoji.isCustomEmoji) img.dataset.emojiId = emoji.emojiId;
          const source = pickSource(emoji.image.thumbnails || [], this.emojiSize);
          img.src = source ? source.url : '';
          const label = /** @type {?} */ (this).get('image.accessibility.accessibilityData.label', emoji);
          if (label) img.alt = label;
          else if (emoji.shortcuts && emoji.shortcuts.length > 0) img.alt = emoji.shortcuts[0];
          else if (emoji.emojiId) img.alt = emoji.emojiId;
          fragment.appendChild(img);
          this.hasEmoji = true;
        }
        continue;
      }
      let node;
      if (!this.noEndpoints && run.navigationEndpoint) {
        node = document.createElement('a');
        node.classList.add('ytl-simple-endpoint');
        node.setAttribute('spellcheck', 'false');
        this.setDataOnAnchor_(node, run.navigationEndpoint);
      } else {
        node = document.createElement('span');
      }
      this.setNodeStyle_(run, node);
      this.setUpVisibilityLogging_(run, node);
      node.appendChild(document.createTextNode(text));
      fragment.appendChild(node);
    }
    this.getRoot().appendChild(fragment);
  },

  /**
   * @param {!Object} run
   * @param {!Element} node
   */
  setNodeStyle_(run, node) {
    const host = this.hostElement;
    if (!this.useMixedDirectionFormattedStrings || this.respectHtmlDir ||
        (flag('disable_child_node_auto_formatted_strings') && host.dir === 'auto')) {
      node.removeAttribute('dir');
    } else {
      node.setAttribute('dir', 'auto');
    }
    node.classList.remove(...RUN_STYLE_CLASSES);
    /** @type {!HTMLElement} */ (node).style.color = '';
    let styleTarget = null;
    if (!this.noStyles) {
      if (run.bold) {
        node.classList.add('bold');
        styleTarget = 'bold';
      }
      if (run.deemphasize) {
        node.classList.add('deemphasize');
        styleTarget = 'deemphasize';
      }
      if (run.italics) node.classList.add('italic');
      if (run.strikethrough) node.classList.add('strikethrough');
      if (run.errorUnderline) {
        node.classList.add('error-underline');
        this.isDarkTheme = document.documentElement.hasAttribute('dark');
      }
      if (run.bracket) node.classList.add('bracket');
      if (run.textColor) /** @type {!HTMLElement} */ (node).style.color = argbToCss(run.textColor);
    }
    if (styleTarget !== node.getAttribute('style-target')) {
      if (styleTarget) node.setAttribute('style-target', styleTarget);
      else node.removeAttribute('style-target');
    }
  },

  /**
   * @param {!Object} run
   * @param {!Element} node
   */
  setUpVisibilityLogging_(run, node) {
    this.setNodeTrackingParams_(run, node);
    const data = /** @type {?} */ (node).data;
    const observer = this.visibilityObserver;
    if (!data || !data.trackingParams || !this.useIOObserverForVisibilityLogging_ || !observer) return;
    const shown = observer.observe(node, (n) => {
      const logger = this.getVisibilityLogger();
      if (logger && logger.reportShown) logger.reportShown(n);
    }, this.visibilityOptionVisible_);
    const hidden = observer.observe(node, (n) => {
      const logger = this.getVisibilityLogger();
      if (logger && logger.reportHidden) logger.reportHidden(n);
    }, this.visibilityOptionHidden_);
    if (!this.ytFormattedStringObserverHandlerKeys_) this.ytFormattedStringObserverHandlerKeys_ = [];
    this.ytFormattedStringObserverHandlerKeys_.push(shown, hidden);
  },

  /**
   * Gives the run's node a `data` object that holds the run's tracking
   * params.
   * @param {!Object} run
   * @param {!Element} node
   */
  setNodeTrackingParams_(run, node) {
    const n = /** @type {?} */ (node);
    if (!n.data) n.data = {};
    const trackingParams = run.loggingDirectives ? run.loggingDirectives.trackingParams : null;
    if (trackingParams || n.data.trackingParams) n.data.trackingParams = trackingParams;
  },

  /**
   * @param {!Element} node
   * @param {!Object} endpoint
   */
  setDataOnAnchor_(node, endpoint) {
    if (endpoint.commandMetadata && endpoint.commandMetadata.webCommandMetadata &&
        endpoint.commandMetadata.webCommandMetadata.sendPost) {
      node.setAttribute('href', '#');
      /** @type {?} */ (node).onclick = (/** !Event */ e) => {
        e.preventDefault();
        this.resolveCommand(endpoint);
      };
      return;
    }
    const link = linkConfig(endpoint);
    if (link.href) node.setAttribute('href', link.href);
    if (link.rel) node.setAttribute('rel', link.rel);
    if (link.target) node.setAttribute('target', link.target);
    if (!node.psClick_) {
      node.psClick_ = true;
      node.addEventListener('click', (e) => {
        e.preventDefault();
        fireCommand(/** @type {!Element} */ (e.currentTarget), endpoint);
      });
    }
  },

  ellipsisTruncateChanged_() {
    const host = this.hostElement;
    if (this.ellipsisTruncate && !(host.title && !this.hasSetTitle_)) {
      host.title = this.getRawText();
      this.hasSetTitle_ = true;
    } else if (this.hasSetTitle_) {
      host.removeAttribute('title');
      this.hasSetTitle_ = false;
    }
  },

  overrideAriaLabelChanged_() {
    const root = this.getRoot();
    if (this.enableContentEditable && root) root.setAttribute('aria-label', /** @type {string} */ (this.overrideAriaLabel));
  },

  enableContentEditableChanged_() {
    const options = this.buildScopeDomOptions();
    if (this.enableContentEditable) {
      this.hostElement.removeAttribute('dir');
      const content = hostDom(this.hostElement, options);
      const last = content.lastChild;
      if (!last || (last instanceof HTMLElement && last.id !== 'contenteditable-root')) {
        const div = document.createElement('div');
        div.id = 'contenteditable-root';
        div.setAttribute('contenteditable', 'true');
        div.setAttribute('dir', 'auto');
        div.onfocus = () => {
          this.hostElement.dispatchEvent(new FocusEvent('focus', {bubbles: false}));
        };
        content.appendChild(div);
        if (this.overrideAriaLabel) div.setAttribute('aria-label', this.overrideAriaLabel);
      }
    } else {
      const first = wrap(this.hostElement).firstChild;
      if (first instanceof HTMLElement && first.id === 'contenteditable-root') hostDom(this.hostElement, options).removeChild(first);
    }
  },

  /**
   * @param {?string} label
   * @return {?string}
   */
  computeAriaLabel_(label) {
    return label;
  },

  /**
   * @param {?Array<!Object>} runs
   * @return {boolean}
   */
  computeHasLinkOnly_(runs) {
    return !!runs && runs.length === 1 && !!runs[0].navigationEndpoint && !this.noEndpoints;
  },

  /**
   * @param {boolean} plaintextOnly
   * @return {boolean}
   */
  __compute__useMixedDirectionFormattedStrings(plaintextOnly) {
    return !plaintextOnly && flag('enable_mixed_direction_formatted_strings');
  },

  /**
   * @param {boolean} ellipsisTruncate
   * @param {boolean} useYtAttributedString
   * @return {boolean}
   */
  computeEllipsisTruncateStyling(ellipsisTruncate, useYtAttributedString) {
    return !!ellipsisTruncate && !useYtAttributedString;
  },

  /**
   * @param {*} text
   * @return {boolean}
   */
  computeUseAttributedString(text) {
    return flag('web_replace_formatted_with_attributed_string') && !!text && /** @type {?} */ (text).content !== undefined &&
        !this.disableAttributedString && !this.enableContentEditable;
  },

  resetForAttributedString() {
    const root = this.getRoot();
    if (!root.querySelector('ytl-attributed-string') && this.ytAttributedStringElementRef) {
      this.clearContents_();
      root.appendChild(this.ytAttributedStringElementRef);
    }
  },

  resetForFormattedString() {
    const root = this.getRoot();
    const attributed = root.querySelector('ytl-attributed-string');
    if (attributed) this.ytAttributedStringElementRef = root.removeChild(attributed);
  },

  /**
   * A new wrapper for the content: the shady root, or the contenteditable
   * element when editing is on.
   * @return {!HostDom}
   */
  getRoot() {
    const options = this.buildScopeDomOptions();
    if (!this.enableContentEditable) return hostDom(this.hostElement, options);
    return hostDom(/** @type {!Element} */ (hostDom(this.hostElement, options).querySelector('[contenteditable]')));
  },

  fixContenteditableScope() {
    const scope = (node) => {
      if (!node) return;
      if (node.nodeType === Node.ELEMENT_NODE && node.classList) {
        node.classList.add('style-scope');
        node.classList.add('ytl-formatted-string');
      }
      if (node.childNodes) node.childNodes.forEach(scope);
    };
    scope(this.getRoot());
  },

  /** @return {string} */
  getRawText() {
    return getText(/** @type {?} */ (this.text));
  },

  /** @return {string|undefined} */
  getFirstRunText() {
    const text = /** @type {?} */ (this.text);
    if (text && text.runs && text.runs[0]) return text.runs[0].text;
    return undefined;
  },

  /** @param {string} value */
  setFirstRunText(value) {
    const text = /** @type {?} */ (this.text);
    if (!text || !text.runs || !text.runs[0]) return;
    text.runs[0].text = value;
    this.textChanged_(text);
  },

  /** @return {{ignoreOwnerDocument: boolean}|undefined} */
  buildScopeDomOptions() {
    if (this.ignoreShadyDom) return {ignoreOwnerDocument: true};
    return undefined;
  },

  /**
   * The content nodes with tracking params.
   * @return {!Array<!Node>}
   */
  getNodesForVisibilityLogging_() {
    return Array.from(this.getRoot().childNodes).filter((n) => {
      const data = /** @type {?} */ (n).data;
      return !!data && !!data.trackingParams;
    });
  },

  /** @return {!Array<!Node>} */
  getNodes() {
    return this.getNodesForVisibilityLogging_();
  },

  onShow() {
    if (this.useIOObserverForVisibilityLogging_) return;
    const logger = this.getVisibilityLogger();
    if (logger && logger.reportShown) this.getNodesForVisibilityLogging_().forEach((n) => logger.reportShown(n));
  },

  onHide() {
    if (this.useIOObserverForVisibilityLogging_) return;
    const logger = this.getVisibilityLogger();
    if (logger && logger.reportHidden) this.getNodesForVisibilityLogging_().forEach((n) => logger.reportHidden(n));
  },
});

setIconScheduling({idleJob: (fn) => { schedule(fn, Priority.IDLE); }, track});

const forcedColors = window.matchMedia('(forced-colors: active)').matches;

/**
 * The animation of a like icon, when icons come from the icon manager.
 * @param {?string|undefined} icon
 * @return {?Object|undefined}
 */
function likeAnimation(icon) {
  if (!icon) return undefined;
  switch (icon) {
    case 'yt-icons:like':
    case 'LIKE':
    case 'LIKE_SELECTED':
      if (flag('kevlar_use_wil_icons')) return {type: 'LIKE', totalFrames: 120};
  }
  return undefined;
}

/**
 * Whether an animated like icon sits in a like button or in the player's
 * quick actions, for a signed-in user.
 * @param {!Element} container
 * @param {?string|undefined} icon
 * @return {boolean}
 */
function inAnimatedLikeButton(container, icon) {
  if (!container.closest) return false;
  const animated = !!likeAnimation(icon);
  return getConfig('ID_TOKEN') && animated ?
      !!container.closest('ytl-segmented-like-dislike-button-view-model') || !!container.closest('ytl-player-quick-action-buttons') : false;
}

/**
 * Whether the icon in `container` is drawn as an animation instead of an
 * icon shape: a like icon in a like button, or the bell of a notification
 * toggle, for a signed-in user.
 * @param {?Element|undefined} container
 * @param {?string|undefined} icon
 * @return {boolean}
 */
function usesAnimatedIcon(container, icon) {
  if (!container || forcedColors) return false;
  if (inAnimatedLikeButton(container, icon)) return true;
  if (!container.closest) return false;
  const signedOut = !getConfig('ID_TOKEN');
  const toggle = container.closest('ytl-subscription-notification-toggle-button-renderer-next');
  if (signedOut || !toggle) return false;
  const data = /** @type {?} */ (toggle).data;
  return (data == null ? undefined : data.targetId) === 'notification-bell' && icon !== 'EXPAND_MORE';
}

/**
 * The style scope of an element: the name after `style-scope` in its
 * classes.
 * @param {*} el
 * @return {?string}
 */
function styleScopeOf(el) {
  if (!(el instanceof Element)) return null;
  const classes = el.classList ? Array.from(el.classList) : undefined;
  if (!classes) return null;
  const i = classes.indexOf('style-scope');
  return i > -1 && i + 1 < classes.length ? classes[i + 1] : null;
}

/**
 * @param {!Element} el
 * @return {?Element}
 */
function parentOf(el) {
  const e = /** @type {?} */ (el);
  const p = e.parentElement != null ? e.parentElement : e.__shady_native_parentElement;
  return p != null ? p : e.__shady_parentElement != null ? e.__shady_parentElement : null;
}

/**
 * @param {!Element} el
 * @return {*}
 */
function shadowRootOf(el) {
  const e = /** @type {?} */ (el);
  if (e.root != null) return e.root;
  if (e.shadowRoot != null) return e.shadowRoot;
  if (e.__shady_native_shadowRoot != null) return e.__shady_native_shadowRoot;
  return e.__shady_shadowRoot != null ? e.__shady_shadowRoot : e;
}

/**
 * The root of the template `el` was stamped from: found by walking up to
 * the element named by its style scope. Without a scope, the root node.
 * @param {?Element} el
 * @return {*}
 */
function scopeRoot(el) {
  if (!el) return null;
  const scope = styleScopeOf(el);
  if (!scope) return Node.prototype.getRootNode ? el.getRootNode() : undefined;
  const tag = scope.toUpperCase();
  let n = parentOf(el);
  while (n && n.tagName !== tag) n = parentOf(n);
  return n ? shadowRootOf(n) : null;
}

/** The icon manager, provided through the root injector as YouTube's `ICON_MANAGER_TOKEN` is. */
class IconManagerToken {}
registerInjectable(IconManagerToken,
    defineInjectable({token: IconManagerToken, providedIn: 'root', factory: () => iconManager()}));

/**
 * Resolves the icon manager in a later microtask, as kevlar's generator
 * does.
 * @return {!Promise<!IconManager>}
 */
async function resolveIconManager() {
  try {
    return /** @type {!IconManager} */ (rootInjector.resolve(IconManagerToken));
  } catch (e) {
    return iconManager();
  }
}

/**
 * The icon shape view: a container that the icon manager renders the
 * current shape into, now or once the icon has been fetched.
 * @param {{data: function(): ?Object, options: function(): ?Object}} props
 * @return {!Element}
 */
function IconShapeView(props) {
  const span = document.createElement('span');
  span.className = 'ytl-icon-shape ytlIconShapeHost';
  const state = {value: null, cancelled: false};
  renderEffect(() => {
    const shape = props.data();
    const options = props.options();
    if (!shape) return;
    const fn = iconManager().renderer(/** @type {?} */ (shape));
    const apply = (render, token) => {
      if (state.value !== token || state.cancelled) return;
      while (span.firstChild) span.removeChild(span.firstChild);
      span.classList.add('ytlSpecIconShapeHost');
      render(span, options);
    };
    if (typeof fn === 'function') {
      state.value = null;
      apply(fn, null);
    } else {
      state.value = fn;
      fn.then((render) => apply(render, fn));
    }
  });
  return span;
}

// A stock Polymer element, as YouTube's yt-icon is. Its template has only
// styles; the shape is inserted by script.
Polymer({
  _template: iconTemplate,
  is: 'ytl-icon',
  behaviors: [HostElementBehavior, ActionHandlerBehavior, TemplateHelpersBehavior],
  properties: {
    icon: String,
    active: {type: Boolean, value: false},
    defaultToFilled: {type: Boolean, value: false},
    isAnimatedIcon: {type: Boolean, value: false},
    size: {type: Number, value: 24},
    targetContainer: {type: String, value: ''},
    animatedIconElement: Object,
    isDarkTheme: Boolean,
    ariaHidden: {type: String, reflectToAttribute: true},
    ariaLabel: {type: String, reflectToAttribute: true},
    role: {type: String, reflectToAttribute: true},
    tabindex: {type: String, reflectToAttribute: true},
    title: {type: String, reflectToAttribute: true},
    style: String,
    iconFilter: String,
    gradientColor: String,
  },
  observers: [
    'updateIconSize(size)',
    'handlePropertyChange(icon, active, defaultToFilled, size, targetContainer, isAttached, isDarkTheme, gradientColor, iconFilter)',
  ],

  created() {
    this.isDarkTheme = document.documentElement.hasAttribute('dark');
    this.iconName = '';
    this.iconsetName = 'yt-icons';
    this.iconset = null;
    this.missingIconSet = false;
    this.iconType = '';
    const [shapeData, setShapeData] = createSignal(/** @type {?Object} */ (null), undefined);
    this.iconShapeDataSignal = {get: shapeData, set: setShapeData};
    const [options, setOptions] = createSignal(/** @type {?Object} */ (null), undefined);
    this.renderingOptionsSignal = {get: options, set: setOptions};
    this.wizHasRendered = false;
    this.actionMap = {'yt-dark-mode-toggled-action': 'onDarkModeToggled'};
  },

  /** @param {number} size */
  updateIconSize(size) {
    if (flag('web_yt_icon_update_styles_killswitch') || size === 24) return;
    styleSubtree(this.hostElement, {width: `${size}px`, height: `${size}px`});
  },

  /** @param {string} target */
  toggleContainerClass(target) {
    this.hostElement.classList.toggle('ytl-icon-container-target', !!target);
  },

  async handlePropertyChange() {
    if ((!this.icon && !this.iconName) || !this.isAttached) return;
    const icon = this.icon;
    const size = this.size;
    const defaultToFilled = this.defaultToFilled;
    const active = this.active;
    const target = this.targetContainer;
    this.toggleContainerClass(target);
    if (flag('kevlar_use_wil_icons') && icon) {
      const parts = splitIconName(icon);
      this.iconType = parts.length ? parts[1] : null;
    }
    if (!icon) {
      this.iconsetName = '';
      this.iconName = '';
      await this.renderIcon(target, icon);
      return;
    }
    const full = !flag('default_to_innertube_icon') || icon.indexOf(':') > 0 ? icon : iconTypeToName(icon);
    const parts = splitIconName(full);
    this.iconsetName = parts[0];
    this.iconName = parts[1];
    if (flag('kevlar_use_wil_icons')) {
      await resolveIconManager();
      this.iconShapeData = resolveIconShape(this.iconType, this.active, this.defaultToFilled, this.size, this.iconsetName);
    }
    if (!this.shouldRenderIconShape(target)) await this.determineIconSet(full, active, defaultToFilled, size);
    await this.renderIcon(target, icon);
  },

  /**
   * @param {string} icon
   * @param {boolean} active
   * @param {boolean} defaultToFilled
   * @param {number} size
   */
  async determineIconSet(icon, active, defaultToFilled, size) {
    if (flag('kevlar_system_icons') || getConfig('INNERTUBE_CLIENT_NAME') === 'WEB_REMIX' || getConfig('INNERTUBE_CLIENT_NAME') === 'WEB_CREATOR') {
      await this.switchToYtSysIconset(icon);
    }
  },

  /** @param {string} icon */
  async switchToYtSysIconset(icon) {
    if (!icon || (this.iconsetName !== 'yt-icons' && this.iconsetName !== 'yt-sys-icons')) return;
    let name = splitIconName(icon)[1];
    if (!isResolvableIcon(name)) {
      const lower = name.toLowerCase();
      name = ICON_RENAMES.get(lower) || lower;
    }
    if (flag('enable_polymer_icons_replace_underscores_dash') && name.includes('_filled')) name = name.replace(/_filled/g, '-filled');
    this.iconName = name;
    this.iconsetName = 'yt-sys-icons';
  },

  /**
   * @param {string} target
   * @return {boolean}
   */
  shouldRenderIconShape(target) {
    if (!flag('kevlar_use_wil_icons') || !this.iconType || !this.iconShapeData || this.isAnimatedIcon) return false;
    return !usesAnimatedIcon(this.getContainer(target), this.icon);
  },

  /**
   * @param {string} target
   * @return {?Element}
   */
  getContainer(target) {
    const root = scopeRoot(/** @type {?Element} */ (this.hostElement));
    const host = root == null ? undefined : /** @type {?} */ (root).host;
    const inController = !!host && !!host.polymerController;
    if (!target || inController) return target ? this.getTargetContainer(target, host) : this.hostElement;
    return null;
  },

  /**
   * @param {string} target
   * @param {!Element} host
   * @return {?Element}
   */
  getTargetContainer(target, host) {
    const el = hostDom(host).querySelector(`#${target}`);
    if (!el) console.error('ytl-icon container missing', host.localName, target);
    return el;
  },

  /**
   * @param {string} target
   * @param {?string} icon
   */
  async renderIcon(target, icon) {
    if (icon && this.icon !== icon) return;
    const container = this.getContainer(target);
    const animated = usesAnimatedIcon(container, this.icon);
    if (this.shouldRenderIconShape(target) && this.iconType) {
      this.applyIconShape(animated, container);
      return;
    }
    this.removeIconShape();
  },

  /**
   * @param {boolean} animated
   * @param {?Element} container
   */
  applyIconShape(animated, container) {
    const options = {iconWidth: '100%', iconHeight: '100%', iconFilter: this.iconFilter, iconColor: this.gradientColor};
    writeSignal(this.iconShapeDataSignal.set, this.iconShapeData);
    writeSignal(this.renderingOptionsSignal.set, options);
    if (this.wizHasRendered) return;
    this.wizHasRendered = true;
    const fragment = document.createDocumentFragment();
    render(h(IconShapeView, {data: this.iconShapeDataSignal.get, options: this.renderingOptionsSignal.get}), fragment);
    while (fragment.firstChild) hostDom(this).appendChild(fragment.firstChild);
  },

  removeIconShape() {
    if (flag('kevlar_use_wil_icons')) writeSignal(this.iconShapeDataSignal.set, undefined);
  },

  onDarkModeToggled() {
    this.isDarkTheme = document.documentElement.hasAttribute('dark');
  },
});

Polymer({
  _template: imgShadowTemplate,
  is: 'ytl-img-shadow',
  properties: {
    thumbnail: {type: Object, observer: 'thumbnailChanged_'},
    width: {type: Number, value: 0},
    alt: {type: String, value: ''},
    loaded: {type: Boolean, value: false, reflectToAttribute: true},
  },
  hostAttributes: {'class': 'no-transition'},

  ready() {
    this.$['img'].addEventListener('load', () => this.onLoad_());
  },

  attached() {
    this.hostElement.classList.add('empty');
    if (this.stopObserving_) return;
    this.stopObserving_ = observeVisibility(this.hostElement, () => {
      this.visible_ = true;
      this.stopObserving_ = null;
      this.thumbnailChanged_(this.thumbnail);
    });
  },

  detached() {
    if (this.stopObserving_) this.stopObserving_();
    this.stopObserving_ = null;
  },

  /** @param {?Object} thumbnail */
  thumbnailChanged_(thumbnail) {
    if (!this.visible_) return;
    const thumbs = (thumbnail && thumbnail.thumbnails) || [];
    const src = pickSource(thumbs, this.width || 48);
    const img = /** @type {!HTMLImageElement} */ (this.$['img']);
    if (!src) {
      img.removeAttribute('src');
      this.hostElement.classList.add('empty');
      return;
    }
    if (img.getAttribute('src') !== src.url) {
      this.loaded = false;
      img.src = src.url;
    }
  },

  onLoad_() {
    this.loaded = true;
    this.hostElement.classList.remove('empty');
  },
});

Polymer({
  _template: interactionTemplate,
  is: 'ytl-interaction',
  hostAttributes: {'aria-hidden': 'true'},
  properties: {
    disabled: {type: Boolean, value: false, reflectToAttribute: true},
  },

  triggerDown() {
    if (!this.disabled) this.hostElement.setAttribute('pressed', '');
  },

  triggerUp() {
    this.hostElement.removeAttribute('pressed');
  },

  attached() {
    const parent = wrap(this).parentNode;
    const target = parent && parent.nodeType === Node.DOCUMENT_FRAGMENT_NODE ? /** @type {?} */ (parent).host : parent;
    if (!target || target === this.target_) return;
    this.target_ = target;
    this.down_ = () => this.hostElement.setAttribute('pressed', '');
    this.up_ = () => this.hostElement.removeAttribute('pressed');
    target.addEventListener('pointerdown', this.down_, {passive: true});
    target.addEventListener('pointerup', this.up_, {passive: true});
    target.addEventListener('pointerleave', this.up_, {passive: true});
  },

  detached() {
    const t = this.target_;
    if (!t) return;
    t.removeEventListener('pointerdown', this.down_);
    t.removeEventListener('pointerup', this.up_);
    t.removeEventListener('pointerleave', this.up_);
    this.target_ = null;
  },
});

