/**
 * @fileoverview The chip shape (CoW `ytl-chip-shape`) of the filter chips.
 */
import {classes} from '../../framework/vm/classes.js';
import {cond} from '../../framework/vm/control.js';
import {computed} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';
import {Icon, TouchFeedbackShape} from './primitives.js';

/**
 * @param {string|undefined} style
 * @return {string}
 */
function chipStyleClass(style) {
  switch (style) {
    case 'CHIP_STYLE_OVERLAY':
      return 'ytlChipShapeOverlay';
    case 'CHIP_STYLE_TRANSPARENT':
      return 'ytlChipShapeTransparent';
    default:
      return '';
  }
}

/** The chip shape. */
export const ChipShape = defineComponent((props) => {
  const d = () => props.data() || {};
  const selected = computed(() => !!d().selected, undefined, 'chipSelected');
  return h('ytl-chip-shape', {class: classes('ytlChipShapeHost', () => chipStyleClass(d().chipStyle)), role: () => 'presentation'},
    h('button', {
      class: 'ytlChipShapeButtonReset',
      role: () => 'tab',
      'aria-selected': () => String(selected()),
      'aria-label': () => d().accessibilityLabel || undefined,
    },
    h('div', {
      class: classes('ytlChipShapeChip', {'ytlChipShapeActive': selected, 'ytlChipShapeInactive': () => !selected()},
          {'ytlChipShapeOnlyTextPadding': () => !d().leadingIcon && !d().trailingIcon}),
    },
    cond(() => !!d().leadingIcon, () => h('div', {class: 'ytlChipShapeIconContainer'}, h(Icon, {icon: () => d().leadingIcon, size: 18}))),
    cond(() => !!d().avatar, () => h('div', {class: 'ytlChipShapeAvatar'})),
    h('div', null, () => d().text || ''),
    cond(() => !!d().trailingIcon, () => h('div', {class: 'ytlChipShapeIconContainer'}, h(Icon, {icon: () => d().trailingIcon, size: 18}))),
    cond(() => !!d().badgeCount, () => h('span', {class: 'ytlChipShapeBadge'}, () => String(d().badgeCount))),
    h(TouchFeedbackShape, {response: 'normal'}),
    cond(() => !!d().dismissible, () => h('div', {class: 'ytlChipShapeDismiss'})))));
}, 'chip-shape');

defineCoW('ytl-chip-shape', ChipShape, {props: {data: PropKind.SIGNAL, className: PropKind.SIGNAL}});
