/**
 * @fileoverview Upward action bus: components fire bubbling `yt-action`
 * events and the app element handles them.
 */

/**
 * @param {!Element} source
 * @param {string} actionName
 * @param {!Array<*>=} args
 */
export function fireAction(source, actionName, args = []) {
  source.dispatchEvent(new CustomEvent('yt-action', {
    bubbles: true,
    cancelable: false,
    composed: true,
    detail: {actionName, args},
  }));
}
