/**
 * @fileoverview Simulated InnerTube network. Responses are pre-generated
 * JSON strings, loaded before the benchmark starts. A request builds the
 * same request objects a real client would (body, size check, optional
 * gzip, `Request`), then resolves with the response text in a later task;
 * the caller parses it.
 */
import {gzip} from 'pako';
import {track} from './scheduler.js';
import {flagNumber, getConfig} from '../framework/flags.js';

/** @type {!Map<string, !Array<string>>} */
const responses = new Map();
/** @type {!Map<string, number>} */
const cursors = new Map();

const MAX_BODY_SIZE_TO_COMPRESS = flagNumber('max_body_size_to_compress', 500000);
const MIN_BODY_SIZE_TO_COMPRESS = flagNumber('min_body_size_to_compress', 500);

/**
 * @param {*} value
 * @return {*}
 */
function deepClone(value) {
  if (Array.isArray(value)) return value.map(deepClone);
  if (value && typeof value === 'object') {
    const out = {};
    for (const k of Object.keys(value)) out[k] = deepClone(value[k]);
    return out;
  }
  return value;
}

/**
 * The client context of an InnerTube request: a fresh copy of the page
 * config's context, with the current URL and click tracking filled in.
 * @param {string=} clickTrackingParams
 * @return {!Object}
 */
export function innertubeContext(clickTrackingParams) {
  const context = /** @type {!Object} */ (deepClone(getConfig('INNERTUBE_CONTEXT', {client: {}})));
  const client = context['client'] || {};
  client['originalUrl'] = location.href;
  client['screenWidthPoints'] = window.innerWidth;
  client['screenHeightPoints'] = window.innerHeight;
  if (client['mainAppWebInfo']) client['mainAppWebInfo']['graftUrl'] = location.href;
  if (clickTrackingParams && context['clickTracking']) context['clickTracking']['clickTrackingParams'] = clickTrackingParams;
  return context;
}

/**
 * Registers the response texts served for `kind`, in order.
 * @param {string} kind
 * @param {!Array<string>} texts
 */
export function addResponses(kind, texts) {
  responses.set(kind, texts);
  cursors.set(kind, 0);
}

/**
 * Loads `<base>/<name>.json` for every entry of `manifest` (kind → names).
 * @param {string} base
 * @param {!Object<string, !Array<string>>} manifest
 * @return {!Promise<void>}
 */
export async function loadResponses(base, manifest) {
  for (const kind of Object.keys(manifest)) {
    const texts = [];
    for (const name of manifest[kind]) {
      const res = await fetch(`${base}/${name}.json`);
      texts.push(await res.text());
    }
    addResponses(kind, texts);
  }
}

/**
 * The UTF-8 size of a request body, measured the way the logging and
 * InnerTube clients do it.
 * @param {string} body
 * @return {number}
 */
export function byteLength(body) {
  return new Blob(body.split('')).size;
}

/**
 * Prepares a POST body: measures it and gzips it when it is in range.
 * @param {string} body
 * @return {{body: (string|!Uint8Array), encoding: ?string}}
 */
export function prepareBody(body) {
  const size = byteLength(body);
  if (size >= MIN_BODY_SIZE_TO_COMPRESS && size <= MAX_BODY_SIZE_TO_COMPRESS) {
    return {body: gzip(body, {level: 6}), encoding: 'gzip'};
  }
  return {body, encoding: null};
}

/**
 * @param {string} kind Response kind, e.g. "search-append".
 * @param {string} apiPath
 * @param {!Object} payload The request payload (context, continuation...).
 * @return {!Promise<string>} The response text.
 */
export function innertubeFetch(kind, apiPath, payload) {
  const {body, encoding} = prepareBody(JSON.stringify(payload));
  const headers = {'Content-Type': 'application/json', 'X-Ytl-Client-Name': '1', 'X-Ytl-Client-Version': '1.0.0'};
  if (encoding) headers['Content-Encoding'] = encoding;
  const request = new Request(`https://www.example.invalid${apiPath}?prettyPrint=false`, {
    method: 'POST',
    headers,
    body: /** @type {?} */ (body),
    credentials: 'include',
  });
  const list = responses.get(kind) || [];
  const i = cursors.get(kind) || 0;
  cursors.set(kind, i + 1);
  const text = list.length ? list[i % list.length] : '{}';
  return track(new Promise(resolve => setTimeout(() => resolve(request.method === 'POST' ? text : ''), 0)));
}

/** Rewinds every response list, for a fresh benchmark iteration. */
export function resetResponses() {
  for (const kind of cursors.keys()) cursors.set(kind, 0);
}
