const PALETTE_VARS = ['section1Color', 'section2Color', 'section3Color', 'section4Color', 'primaryTitleColor',
  'secondaryTitleColor', 'iconActivatedColor', 'iconInactiveColor', 'iconDisabledColor'];

Polymer({
  _template: expandableTemplate,
  is: 'ytl-expandable-metadata-renderer',
  behaviors: [RendererBehavior],
  observers: ['dataChanged(data)'],
  properties: {
    header: Object,
    expanded: {type: Boolean, value: false, reflectToAttribute: true},
    collapsedThumbnail_: Object,
  },

  /** @param {?Object} data */
  dataChanged(data) {
    if (!data) return;
    this.header = data.header || {};
    this.collapsedThumbnail_ = this.header.collapsedThumbnail || null;
    this.hostElement.toggleAttribute('show-prominent-label', !!this.header.showLeadingCollapsedLabel);
    this.hostElement.toggleAttribute('use-custom-colors', !!data.useCustomColors);
    this.applyColors_(data.colorData);
    const content = data.expandedContent || {};
    const host = this.$['content'];
    if (this.summaryView_) {
      this.summaryView_.dispose();
      this.summaryView_ = null;
    }
    for (let c = wrap(host).lastChild; c; c = wrap(host).lastChild) wrap(host).removeChild(c);
    if (content.videoSummaryContentViewModel) {
      this.hostElement.toggleAttribute('has-video-summary', true);
      this.summaryView_ = render(h(VideoSummaryContent, {data: content.videoSummaryContentViewModel}), host);
    } else {
      this.hostElement.toggleAttribute('has-video-summary', false);
      stampRenderers(host, [content]);
    }
  },

  /** @param {?Object|undefined} colors */
  applyColors_(colors) {
    if (!colors) return;
    const palette = colors.lightColorPalette || {};
    for (const name of PALETTE_VARS) {
      const v = palette[name];
      if (typeof v === 'number') this.hostElement.style.setProperty(`--ytl-expandable-${name.replace(/[A-Z0-9]/g, c => '-' + c.toLowerCase())}`, argbToCss(v));
    }
    const sat = colors.saturatedColorPalettes && colors.saturatedColorPalettes.lightThemePalette;
    if (sat) {
      for (const key in sat) {
        if (typeof sat[key] === 'number') this.hostElement.style.setProperty(`--ytl-spec-${key}`, argbToCss(sat[key]));
      }
    }
  },

  /**
   * @param {?Object|undefined} icon
   * @return {string}
   */
  iconName_(icon) {
    return (icon && icon.iconType) || '';
  },

  /** @param {!Event} e */
  onHeaderTap_(e) {
    e.stopPropagation();
    this.expanded = !this.expanded;
  },
});
