Polymer({
  _template: cardListTemplate,
  is: 'ytl-horizontal-card-list-renderer',
  behaviors: [RendererBehavior, IronResizableBehavior],
  observers: ['dataChanged(data)'],
  listeners: {'iron-resize': 'onIronResize_'},

  /** @param {?Object} data */
  dataChanged(data) {
    this.cards_ = (data && data.cards) || [];
    this.shownCount_ = 0;
    if (this.isAttached) this.updateListStyles_();
  },

  onIronResize_() {
    this.updateListStyles_();
  },

  /**
   * Stamps the first 7 cards, or the cards that fit in the scroller plus one
   * if that is more, as YouTube does; the rest are stamped when the list is
   * scrolled.
   * @param {number} perRow
   */
  stampVisibleCards_(perRow) {
    if (!this.cards_) return;
    const want = Math.min(this.cards_.length, Math.max(7, perRow + 1));
    if (want <= this.shownCount_) return;
    this.shownCount_ = want;
    stampRenderers(this.$['items'], this.cards_.slice(0, want));
  },

  /** Sizes the cards to the scroller width, through a CSS variable. */
  updateListStyles_() {
    const scroller = this.$['scroller'];
    const width = scroller.clientWidth;
    const perRow = Math.max(1, Math.floor(width / 186));
    this.stampVisibleCards_(perRow);
    const item = width ? Math.floor((width - 8 * (perRow - 1)) / perRow) : 186;
    if (item !== this.itemWidth_) {
      this.itemWidth_ = item;
      this.hostElement.style.setProperty('--ytl-card-width', `${item}px`);
      this.notifyResize();
    }
    this.hostElement.toggleAttribute('overflowing', scroller.scrollWidth > width);
  },
});
