/**
 * @fileoverview JSX-style node descriptors for the view-model renderer
 * (`_.G`). `h()` only builds descriptors; `render.js` turns them into DOM.
 * Element types are tag names. Component types are functions made by
 * `defineComponent`; control-flow types (`Cond`, `Switch`, `Each`) are
 * functions marked `isControl`.
 */
import {vmCounters} from './counters.js';

/**
 * @typedef {string|number|boolean|null|undefined|!VNode|!Array<*>|function(): *}
 */
export let Child;

export class VNode {
  /**
   * @param {string|function(!Object, ?string, !Array<!Node>)} type
   * @param {?Object} props
   * @param {!Array<*>} children
   */
  constructor(type, props, children) {
    /** @const */
    this.type = type;
    /** @const {!Object} */
    this.props = props || EMPTY;
    /** @const {!Array<*>} */
    this.children = children;
  }
}

const EMPTY = Object.freeze({});

/**
 * @param {string|function(?): *} type
 * @param {?Object=} props
 * @param {...*} children
 * @return {!VNode}
 */
export function h(type, props, ...children) {
  vmCounters.jsx++;
  return new VNode(/** @type {?} */ (type), props || null, children);
}

/** Groups children without a wrapper element. */
export const Fragment = '#fragment';

/**
 * @param {*} v
 * @return {boolean}
 */
export function isVNode(v) {
  return v instanceof VNode;
}
