/**
 * @fileoverview Visibility observation, shaped like YouTube's:
 * - `observeVisibility`: one shared IntersectionObserver for lazy images and
 *   ad pings. Callbacks run once, when the element first comes within the
 *   preload margin of the viewport.
 * - `VisibilityObserver`: the renderers' observer. It keeps a `Map` from
 *   each element to a `Map` of handlers keyed by option objects ("visible",
 *   "hidden", "prescan"); `observe` returns a key for `unobserveByKey`.
 * - `monitorVisibility`: the shared visibility monitor that renderers and
 *   view models register with. It reports "shown" and "hidden" to the
 *   visibility logger and calls the element's own callback.
 */
import {flag} from '../framework/flags.js';

/** @type {?IntersectionObserver} */
let observer = null;
/** @type {!WeakMap<!Element, !Array<function()>>} */
const callbacks = new WeakMap();

/** @param {!Array<!IntersectionObserverEntry>} entries */
function onIntersect(entries) {
  for (const entry of entries) {
    if (!entry.isIntersecting) continue;
    const el = entry.target;
    const list = callbacks.get(el);
    if (!list) continue;
    callbacks.delete(el);
    /** @type {!IntersectionObserver} */ (observer).unobserve(el);
    for (const fn of list) fn();
  }
}

/**
 * @param {!Element} el
 * @param {function()} fn
 * @return {function()} Stops observing.
 */
export function observeVisibility(el, fn) {
  if (!observer) observer = new IntersectionObserver(onIntersect, {rootMargin: '600px 0px', threshold: 0});
  let list = callbacks.get(el);
  if (!list) {
    list = [];
    callbacks.set(el, list);
    observer.observe(el);
  }
  list.push(fn);
  return () => {
    const l = callbacks.get(el);
    if (!l) return;
    const i = l.indexOf(fn);
    if (i >= 0) l.splice(i, 1);
    if (!l.length) {
      callbacks.delete(el);
      /** @type {!IntersectionObserver} */ (observer).unobserve(el);
    }
  };
}

/**
 * @typedef {{calledOnce: boolean, state: string}}
 */
export let VisibilityOption;

/**
 * @typedef {{element: !Element, option: !VisibilityOption}}
 */
export let ObserverKey;

/** The renderers' visibility observer. */
export class VisibilityObserver {
  /**
   * @param {?Element=} viewroot
   * @param {number=} defaultPrescanHeight
   */
  constructor(viewroot, defaultPrescanHeight = 0) {
    /** @const {?Element|undefined} */
    this.viewroot = viewroot;
    /** @const {number} */
    this.defaultPrescanHeight = defaultPrescanHeight;
    this.isConnected = true;
    this.pauseObservingUntilReconnect = false;
    /** @const {!IntersectionObserver} */
    this.observer = new IntersectionObserver(this.handleObserveEvent.bind(this),
        viewroot ? {root: viewroot, rootMargin: '-0.1px'} : {rootMargin: '-0.1px'});
    /** @const {!Map<number, !IntersectionObserver>} */
    this.prescanObservers = new Map();
    /** @const {!Map<!Element, !Map<!VisibilityOption, function(!Element, string)>>} */
    this.handlers = new Map();
  }

  dispose() {
    this.disconnect();
    this.handlers.clear();
  }

  /** @param {boolean=} pause */
  disconnect(pause = false) {
    this.isConnected = false;
    this.pauseObservingUntilReconnect = pause;
    this.observer.disconnect();
    for (const o of this.prescanObservers.values()) o.disconnect();
  }

  reconnect() {
    if (this.isConnected) return;
    this.isConnected = true;
    this.pauseObservingUntilReconnect = false;
    for (const [el, options] of this.handlers) {
      let prescan = false;
      for (const option of options.keys()) {
        if (option && option.state === 'prescan') {
          prescan = true;
          break;
        }
      }
      if (prescan) this.prescanObserverFor_(el).observe(el);
      this.observer.observe(el);
    }
  }

  /** @param {!Array<!IntersectionObserverEntry>} entries */
  handleObserveEvent(entries) {
    for (const entry of entries) {
      const options = this.handlers.get(entry.target);
      if (!options) continue;
      const visible = entry.isIntersecting;
      for (const [option, handler] of options) {
        if (!option || !((option.state === 'visible' && visible) || (option.state === 'hidden' && !visible))) continue;
        handler(entry.target, option.state);
        if (option.calledOnce) this.unobserveByKey({element: entry.target, option});
      }
    }
  }

  /** @param {!Array<!IntersectionObserverEntry>} entries */
  handlePrescanEvent(entries) {
    for (const entry of entries) {
      const options = this.handlers.get(entry.target);
      if (!options || !entry.isIntersecting) continue;
      for (const [option, handler] of options) {
        if (!option || option.state !== 'prescan') continue;
        handler(entry.target, option.state);
        if (option.calledOnce) this.unobserveByKey({element: entry.target, option});
      }
    }
  }

  /**
   * @param {!Element} el
   * @param {function(!Element, string)} handler
   * @param {!VisibilityOption} option
   * @return {!ObserverKey}
   */
  observe(el, handler, option) {
    const existing = this.handlers.get(el);
    if (existing && existing.has(option)) return {element: el, option};
    const key = {element: el, option};
    if (!this.handlers.has(el)) this.handlers.set(el, new Map());
    const options = this.handlers.get(el);
    if (options && !options.has(option)) options.set(option, handler);
    if (!this.pauseObservingUntilReconnect) {
      if (option.state === 'prescan') this.prescanObserverFor_(el).observe(el);
      this.observer.observe(el);
    }
    return key;
  }

  /** @param {!ObserverKey} key */
  unobserveByKey(key) {
    const options = this.handlers.get(key.element);
    if (!options || !options.has(key.option)) return;
    options.delete(key.option);
    if (key.option.state === 'prescan') {
      const height = this.prescanHeightOf_(key.element);
      const prescan = this.prescanObservers.get(height);
      if (prescan) prescan.unobserve(key.element);
    }
    if (!options.size) {
      this.handlers.delete(key.element);
      this.observer.unobserve(key.element);
    }
  }

  /**
   * @param {!Element} el
   * @return {number}
   * @private
   */
  prescanHeightOf_(el) {
    const target = /** @type {?} */ (el).polymerController || el;
    return Number(target.prescanHeight) || this.defaultPrescanHeight;
  }

  /**
   * @param {!Element} el
   * @return {!IntersectionObserver}
   * @private
   */
  prescanObserverFor_(el) {
    const height = this.prescanHeightOf_(el);
    let prescan = this.prescanObservers.get(height);
    if (!prescan) {
      prescan = new IntersectionObserver(this.handlePrescanEvent.bind(this),
          this.viewroot ? {root: this.viewroot, rootMargin: `${height}px`} : {rootMargin: `${height}px`});
      this.prescanObservers.set(height, prescan);
    }
    return prescan;
  }
}

/**
 * A new visibility observer for a visibility root.
 * @param {?Element=} viewroot
 * @return {!VisibilityObserver}
 */
export function createVisibilityObserver(viewroot) {
  return new VisibilityObserver(viewroot, 400);
}

/** @type {?VisibilityObserver} */
let defaultObserver = null;

/**
 * The observer used when no ancestor provides one.
 * @return {!VisibilityObserver}
 */
export function defaultVisibilityObserver() {
  if (!defaultObserver) defaultObserver = createVisibilityObserver();
  return defaultObserver;
}

/**
 * @typedef {{
 *   data: *,
 *   observer: ?VisibilityObserver,
 *   visibilityCallback: (function(boolean)|undefined),
 *   prescanCallback: (function()|undefined),
 *   layer: *,
 *   showOption: ?VisibilityOption,
 *   hideOption: ?VisibilityOption,
 *   prescanOption: (?VisibilityOption|undefined),
 *   skipLogging: (function(): boolean|undefined),
 * }}
 */
export let MonitorConfig;

/**
 * The object that carries an element's monitor state: its controller, or
 * the element itself.
 * @param {!Element} el
 * @return {?}
 */
export function monitorTarget(el) {
  const c = /** @type {?} */ (el).polymerController;
  return c != null ? c : el;
}

/**
 * @typedef {{
 *   reportShown: function(*, *, *, number),
 *   reportHidden: function(*, *, *, number),
 *   currentScreen: function(*=): ?string,
 *   trackingParamsOf: function(*): (string|undefined),
 *   graftClientVe: function(!Object): ?Object,
 * }}
 */
let MonitorLogger;

/** @type {?MonitorLogger} */
let logger = null;

/**
 * Sets the visibility logger the monitor reports to.
 * @param {!MonitorLogger} l
 */
export function setMonitorLogger(l) {
  logger = l;
}

/**
 * Removes every observation the monitor holds for `el`.
 * @param {!Element} el
 * @param {?VisibilityObserver} obs
 */
export function unmonitorVisibility(el, obs) {
  const target = monitorTarget(el);
  for (const key of target.visibilityMonitorKeys || []) if (obs) obs.unobserveByKey(key);
  target.visibilityMonitorKeys = undefined;
  target.trackedParams = undefined;
}

/**
 * Whether `data` can be logged as a visual element, creating a client VE
 * from its logging directives where they ask for one.
 * @param {!Element} el
 * @param {*} data
 * @return {boolean}
 */
function prepareVisualElement(el, data) {
  const target = monitorTarget(el);
  if (target.visualElement && !data) return true;
  if (!data) return false;
  const d = /** @type {!Object} */ (data);
  let clientVe = false;
  if (flag('enable_client_ve_spec_logging')) {
    clientVe = !!(d.loggingDirectives && d.loggingDirectives.clientVeSpec && d.loggingDirectives.clientVeSpec.uiType);
  }
  const tp = /** @type {!MonitorLogger} */ (logger).trackingParamsOf(data);
  if (!tp && !clientVe) return false;
  if (flag('mweb_component_visibility_logging')) {
    if (!target.veContainer) target.veContainer = {};
    target.veContainer.trackingParams = tp;
  }
  if (target.trackedParams && target.trackedParams === tp) return false;
  if (flag('enable_client_ve_spec_logging') && !target.visualElement && clientVe) {
    target.visualElement = /** @type {!MonitorLogger} */ (logger).graftClientVe(d.loggingDirectives.clientVeSpec);
  }
  return true;
}

/**
 * @param {!Element} el
 * @param {!MonitorConfig} config
 */
function observeWithConfig(el, config) {
  const obs = config.observer;
  if (!obs) {
    if (flag('web_skip_missing_vimio_observer')) {
      const d = /** @type {?} */ (config.data);
      console.warn('VisibilityObserver is not defined.', el.localName, monitorTarget(el).trackedParams,
          d == null ? undefined : d.trackingParams);
    }
    return;
  }
  const layer = config.layer;
  const callback = config.visibilityCallback || (() => {});
  const prescan = config.prescanCallback;
  const target = monitorTarget(el);
  const keys = [];
  if (config.showOption) {
    keys.push(obs.observe(el, () => {
      if (!(config.skipLogging && config.skipLogging())) /** @type {!MonitorLogger} */ (logger).reportShown(target, undefined, layer, 7);
      callback(true);
    }, config.showOption));
  }
  if (config.hideOption) {
    keys.push(obs.observe(el, () => {
      /** @type {!MonitorLogger} */ (logger).reportHidden(target, undefined, layer, 7);
      callback(false);
    }, config.hideOption));
  }
  if (config.prescanOption && prescan) keys.push(obs.observe(el, () => prescan(), config.prescanOption));
  target.visibilityMonitorKeys = (target.visibilityMonitorKeys != null ? target.visibilityMonitorKeys : []).concat(keys);
}

/**
 * Registers `el` with the shared visibility monitor. Observations are kept
 * while the element's tracking params stay the same.
 * @param {!Element} el
 * @param {!MonitorConfig} config
 */
export function monitorVisibility(el, config) {
  if (!logger || !logger.currentScreen()) return;
  if (flag('kevlar_vimio_use_shared_monitor')) prepareVisualElement(el, config.data);
  else if (!prepareVisualElement(el, config.data)) return;
  const data = config.data;
  const tp = logger.trackingParamsOf(data);
  const target = monitorTarget(el);
  const keys = target.visibilityMonitorKeys;
  if (tp && target.trackedParams === tp && keys && keys.length) return;
  if (flag('enable_client_ve_spec_logging')) {
    unmonitorVisibility(el, config.observer);
  } else if (target.trackedParams && target.trackedParams !== tp) {
    unmonitorVisibility(el, config.observer);
  }
  if (data && !(target.data && target.data === data)) target.data = data;
  observeWithConfig(el, config);
  target.trackedParams = tp;
}
