/**
 * @fileoverview The watch page's theater manager. It listens for the
 * player's `SIZE_CLICKED` event and runs the toggle in one update callback.
 */
import {flag, flagNumber} from '../framework/flags.js';
import {fireAction} from '../framework/actions.js';
import {appStore} from './store.js';

export class TheaterManager {
  /**
   * @param {!Element} watch The watch page element.
   * @param {!Element} player The page's player element.
   */
  constructor(watch, player) {
    /** @private @const {?} */
    this.watch_ = watch;
    /** @private @const {?} */
    this.player_ = player;
    this.player_.addPlayerListener('SIZE_CLICKED', (enabled) => this.toggle(!!enabled));
  }

  /**
   * @param {boolean} enabled
   * @param {boolean=} writeCookie
   */
  toggle(enabled, writeCookie = true) {
    if (enabled && flag('disable_theater_mode', false)) return;
    this.update_(enabled, writeCookie);
  }

  /**
   * @param {boolean} enabled
   * @param {boolean} writeCookie
   * @private
   */
  update_(enabled, writeCookie) {
    appStore.dispatch({type: 'SET_IS_THEATER_MODE', payload: {isTheaterMode: enabled}});
    if (!flag('theater_mode_scroll_to_top_killswitch', false)) window.scrollTo(0, 0);
    this.player_.setSizeStyle(!flag('disable_theater_mode', false), enabled);
    if (writeCookie) writeSessionCookie('wide', enabled ? '1' : '0', flagNumber('theater_mode_cookie_max_age_seconds', -1));
    fireAction(this.watch_, 'yt-close-popup-action', ['yt-tooltip-renderer']);
    this.watch_.fire('yt-set-theater-mode-enabled', {enabled});
    window.dispatchEvent(new CustomEvent('ytl-theater-mode-applied'));
  }
}

/**
 * @param {string} name
 * @param {string} value
 * @param {number} maxAge Seconds; negative for a session cookie.
 */
function writeSessionCookie(name, value, maxAge) {
  document.cookie = `${name}=${encodeURIComponent(value)}${maxAge >= 0 ? `; max-age=${maxAge}` : ''}; path=/`;
}
