/**
 * @fileoverview Resolves InnerTube commands and endpoints into URLs and
 * command kinds.
 */

const ENDPOINT_KINDS = ['watchEndpoint', 'browseEndpoint', 'searchEndpoint', 'reelWatchEndpoint', 'urlEndpoint',
  'continuationCommand', 'signInEndpoint', 'watchPlaylistEndpoint', 'commandExecutorCommand', 'openPopupAction',
  'showReloadUiCommand', 'signalServiceEndpoint', 'playlistEditEndpoint', 'shareEntityServiceEndpoint'];

/**
 * @param {?Object|undefined} endpoint
 * @return {?string}
 */
export function endpointKind(endpoint) {
  if (!endpoint) return null;
  for (const kind of ENDPOINT_KINDS) if (endpoint[kind]) return kind;
  return null;
}

/**
 * @param {?Object|undefined} endpoint
 * @return {string}
 */
export function endpointUrl(endpoint) {
  if (!endpoint) return '';
  const meta = endpoint.commandMetadata && endpoint.commandMetadata.webCommandMetadata;
  if (meta && typeof meta.url === 'string') return meta.url;
  if (endpoint.watchEndpoint) return `/watch?v=${endpoint.watchEndpoint.videoId}`;
  if (endpoint.browseEndpoint) return endpoint.browseEndpoint.canonicalBaseUrl || `/channel/${endpoint.browseEndpoint.browseId}`;
  if (endpoint.searchEndpoint) return `/results?search_query=${encodeURIComponent(endpoint.searchEndpoint.query || '')}`;
  if (endpoint.urlEndpoint) return endpoint.urlEndpoint.url || '';
  return '';
}

/**
 * @param {?Object|undefined} endpoint
 * @return {string}
 */
export function webPageType(endpoint) {
  const meta = endpoint && endpoint.commandMetadata && endpoint.commandMetadata.webCommandMetadata;
  return (meta && meta.webPageType) || 'WEB_PAGE_TYPE_UNKNOWN';
}

/**
 * Unwraps the command shapes used by view models:
 * `{innertubeCommand}`, `{commandExecutorCommand: {commands}}`, or a plain
 * endpoint.
 * @param {?Object|undefined} command
 * @return {!Array<!Object>}
 */
export function flattenCommand(command) {
  if (!command) return [];
  if (command.innertubeCommand) return flattenCommand(command.innertubeCommand);
  if (command.commandExecutorCommand) {
    const out = [];
    for (const c of command.commandExecutorCommand.commands || []) out.push(...flattenCommand(c));
    return out;
  }
  return [command];
}

/**
 * The tracking params of a renderer or endpoint, in any of the places
 * InnerTube puts them.
 * @param {?Object|undefined} data
 * @return {string}
 */
export function trackingParamsOf(data) {
  if (!data) return '';
  if (typeof data.trackingParams === 'string') return data.trackingParams;
  if (data.loggingDirectives && typeof data.loggingDirectives.trackingParams === 'string') return data.loggingDirectives.trackingParams;
  if (typeof data.clickTrackingParams === 'string') return data.clickTrackingParams;
  return '';
}
