/**
 * @fileoverview The app shell: masthead with the searchbox, guide, page
 * navigation progress bar, popup container and app drawer.
 */
import {Polymer} from '../../framework/polysi/register.js';
import {IronResizableBehavior} from '@polymer/iron-resizable-behavior/iron-resizable-behavior.js';
import {h} from '../../framework/vm/jsx.js';
import {render} from '../../framework/vm/render.js';
import {dashToCamel} from '../../framework/case.js';
import {afterNextRender} from '../scheduler.js';
import {Searchbox} from '../vm/searchbox.js';
import {template as mastheadTemplate} from '../../../gen/templates/ytl-masthead.js';
import {template as logoTemplate} from '../../../gen/templates/ytl-topbar-logo-renderer.js';
import {template as guideTemplate} from '../../../gen/templates/ytl-guide-renderer.js';
import {template as guideSectionTemplate} from '../../../gen/templates/ytl-guide-section-renderer.js';
import {template as guideEntryTemplate} from '../../../gen/templates/ytl-guide-entry-renderer.js';
import {template as progressTemplate} from '../../../gen/templates/ytl-page-navigation-progress.js';
import '../../../vendor/polymer/paper-item/paper-item.js';

Polymer({
  _template: mastheadTemplate,
  is: 'ytl-masthead',
  behaviors: [IronResizableBehavior],
  properties: {
    voiceButton_: {type: Object, value: () => ({icon: {iconType: 'MICROPHONE_ON'}, accessibilityData: {accessibilityData: {label: 'Search with your voice'}}, tooltip: 'Search with your voice'})},
    createButton_: {type: Object, value: () => ({icon: {iconType: 'VIDEO_CALL'}, text: {simpleText: 'Create'}, style: 'STYLE_DEFAULT'})},
    signInButton_: {type: Object, value: () => ({icon: {iconType: 'AVATAR_LOGGED_OUT'}, text: {simpleText: 'Sign in'}, style: 'STYLE_SUGGESTIVE'})},
    narrow: {type: Boolean, value: false, reflectToAttribute: true},
  },
  listeners: {'iron-resize': 'onIronResize_'},

  ready() {
    this.searchbox_ = render(h(Searchbox, {}), this.$['searchbox-host']);
  },

  onIronResize_() {
    this.narrow = this.hostElement.offsetWidth < 656;
  },

  onGuideTap_() {
    this.fire('yt-action', {actionName: 'yt-guide-toggle', args: []});
  },
});

Polymer({
  _template: logoTemplate,
  is: 'ytl-topbar-logo-renderer',
  properties: {
    countryCode: {type: String, value: ''},
  },

  /** @param {!Event} e */
  onTap_(e) {
    e.preventDefault();
  },
});

Polymer({
  _template: guideTemplate,
  is: 'ytl-guide-renderer',
  properties: {data: Object},
});

Polymer({
  _template: guideSectionTemplate,
  is: 'ytl-guide-section-renderer',
  properties: {data: Object},

  /**
   * @param {string} title
   * @return {!Object}
   */
  titleText_(title) {
    return {simpleText: title || ''};
  },
});

Polymer({
  _template: guideEntryTemplate,
  is: 'ytl-guide-entry-renderer',
  properties: {data: Object},

  /**
   * @param {string} title
   * @return {!Object}
   */
  titleText_(title) {
    return {simpleText: title || ''};
  },
});

Polymer({
  is: 'tp-ytl-app-drawer',
  behaviors: [IronResizableBehavior],
  properties: {
    opened: {type: Boolean, value: true, reflectToAttribute: true},
  },
});

Polymer({
  is: 'ytl-mini-guide-renderer',
});

Polymer({
  is: 'ytl-popup-container',

  /** @param {!Object} popup */
  openPopup(popup) {
    this.lastPopup_ = popup;
  },

  /**
   * Closes the open popup if its type is one of `types`.
   * @param {!Array<string>} types
   */
  closePopups(types) {
    const popup = this.lastPopup_;
    if (!popup) return;
    const type = Object.keys(popup).find(k => k.endsWith('Renderer') || k.endsWith('ViewModel'));
    if (type && types.some(t => dashToCamel(t) === type)) this.lastPopup_ = null;
  },
});

Polymer({
  _template: progressTemplate,
  is: 'ytl-page-navigation-progress',
  properties: {
    progress: {type: Number, value: 0},
    active: {type: Boolean, value: false, reflectToAttribute: true},
  },

  /**
   * @param {number} progress
   * @return {string}
   */
  barStyle_(progress) {
    return `transform: scaleX(${progress / 100})`;
  },

  start() {
    this.active = true;
    this.progress = 10;
    afterNextRender(this, () => {
      if (this.active) this.progress = 60;
    });
  },

  finish() {
    this.progress = 100;
    afterNextRender(this, () => {
      this.active = false;
      this.progress = 0;
    });
  },
});

/**
 * Synthetic guide sections for the drawer.
 * @return {!Object}
 */
export function makeGuideData() {
  const icons = ['HOME', 'SHORTS', 'SUBSCRIPTIONS', 'HISTORY', 'PLAYLISTS', 'WATCH_LATER', 'LIKED', 'TRENDING', 'MUSIC', 'GAMING', 'NEWS', 'SPORTS', 'LEARNING', 'PODCASTS'];
  const names = ['Home', 'Shorts', 'Subscriptions', 'History', 'Playlists', 'Watch later', 'Liked', 'Trending', 'Music', 'Gaming', 'News', 'Sports', 'Learning', 'Podcasts'];
  const entry = (i) => ({title: names[i], icon: icons[i], active: i === 0, count: ''});
  return {
    sections: [
      {title: '', items: [0, 1, 2].map(entry)},
      {title: 'You', items: [3, 4, 5, 6].map(entry)},
      {title: 'Explore', items: [7, 8, 9, 10, 11, 12, 13].map(entry)},
      {title: 'More', items: []},
    ],
    footerLinks: ['About', 'Press', 'Copyright', 'Contact us', 'Creators', 'Advertise', 'Developers', 'Terms', 'Privacy', 'Policy & Safety'],
    copyright: '© 2026 Example',
  };
}
