/**
 * @fileoverview The behaviours every renderer element shares, shaped like
 * YouTube's: component helpers (text, hrefs, icons, commands), the
 * visibility observer and visual-element logging, and the renderer tree
 * (parent lookup, screen layers, target ids). `RendererBehavior` is the
 * list of them, with the setup, injection and template-helper behaviours
 * that every element has.
 */
import {getText} from '../framework/text.js';
import {endpointKind, endpointUrl} from '../framework/endpoints.js';
import {iconTypeToName, resolvedIconName} from '../framework/icons.js';
import {flag, getConfig} from '../framework/flags.js';
import {InitBehavior, InjectBehavior, TemplateHelpersBehavior} from '../framework/polysi/base-behaviors.js';
import {fireCommand} from './commands.js';
import {RENDERER_DATA, ScreenLayerNode, clientVe, currentScreen, deleteRendererEntry, layerOf, logGesture, rendererEntry, setRendererEntry, trackingParamsOf as logTrackingParamsOf, facadeTrackingParams, loggerFacade, shouldLogGesture, veFromTrackingParams} from './logging.js';
import {wrapErrors} from '../framework/errors.js';
import {Priority, cancel, schedule, soon} from './scheduler.js';
import {registerTarget, unregisterTarget} from './targets.js';
import {createVisibilityObserver, defaultVisibilityObserver, monitorVisibility, unmonitorVisibility} from './visibility.js';

/** A URL that passed the sanitizer. */
class SafeUrl {
  /** @param {string} value */
  constructor(value) {
    /** @private @const {string} */
    this.privateDoNotAccessOrElseSafeUrlWrappedValue_ = value;
  }

  /** @override */
  toString() {
    return this.privateDoNotAccessOrElseSafeUrlWrappedValue_;
  }
}

const SAFE_URL_PATTERN = /^(?:(?:https?|mailto|ftp):|[^:/?#]*(?:[/?#]|$))/i;

/**
 * @param {string} url
 * @return {!SafeUrl}
 */
function sanitizeUrl(url) {
  return new SafeUrl(SAFE_URL_PATTERN.test(url) ? url : 'about:invalid#zClosurez');
}

/** @polymerBehavior */
export const ComponentBehavior = {
  /**
   * @param {*} text
   * @return {string}
   */
  getSimpleString(text) {
    return getText(/** @type {?} */ (text));
  },

  /**
   * @param {?Object|undefined} command
   * @param {*=} options
   * @param {boolean=} fromUser
   * @return {boolean}
   */
  resolveCommand(command, options, fromUser) {
    return fireCommand(/** @type {!Element} */ (this.hostElement), command);
  },

  /**
   * The sanitized href of an endpoint, or null.
   * @param {?Object|undefined} endpoint
   * @param {boolean=} optional
   * @return {?string}
   */
  computeHref_(endpoint, optional) {
    if (!endpoint || endpointKind(endpoint) === 'commandExecutorCommand') return null;
    const url = endpointUrl(endpoint);
    const href = url ? (flag('enable_polymer_resin') ? sanitizeUrl(url).toString() : url) : null;
    if (href == null && !optional) console.warn('No href for endpoint', endpointKind(endpoint));
    return href;
  },

  /**
   * @param {?Object|undefined} endpoint
   * @return {?string}
   */
  computeOptionalHref_(endpoint) {
    return this.computeHref_(endpoint, true);
  },

  /**
   * @param {?Object|undefined} endpoint
   * @return {?string}
   */
  computeNofollow_(endpoint) {
    return endpoint && endpoint.urlEndpoint && endpoint.urlEndpoint.nofollow ? 'nofollow' : null;
  },

  /**
   * @param {*} icon
   * @return {string}
   */
  computeIcon_(icon) {
    if (!icon) return '';
    if (icon.iconType) return iconTypeToName(String(icon.iconType));
    return typeof icon !== 'string' || flag('polymer_yticon_killswitch') ? '' : resolvedIconName(icon);
  },
};

/**
 * @param {?string} option
 * @param {string} state
 * @return {?{calledOnce: boolean, state: string}}
 */
function visibilityOption(option, state) {
  return option ? {calledOnce: option === 'observe_once', state} : null;
}

/**
 * The nearest node from `node` upwards (by `parentNode`, not crossing
 * shadow roots) for which `test` is true.
 * @param {?Node|undefined} node
 * @param {function(!Node): boolean} test
 * @return {?Node}
 */
function closestNode(node, test) {
  for (let n = node; n; n = n.parentNode) if (test(n)) return n;
  return null;
}

/**
 * The observer that `self` registers with: the cached one, else the nearest
 * ancestor's observer for children, else the default. The walk starts at
 * `self.parentNode`, which controllers do not have.
 * @param {!Object} self
 * @return {!Object}
 */
function resolveVisibilityObserver(self) {
  if (self.localVisibilityObserver_) return self.localVisibilityObserver_;
  const found = closestNode(self.parentNode, (n) => {
    const target = /** @type {?} */ (n).polymerController != null ? /** @type {?} */ (n).polymerController : n;
    return !!target.getVisibilityObserverForChild && !!target.getVisibilityObserverForChild();
  });
  if (found) {
    const target = /** @type {?} */ (found).polymerController != null ? /** @type {?} */ (found).polymerController : found;
    self.localVisibilityObserver_ = target.getVisibilityObserverForChild();
  } else {
    self.localVisibilityObserver_ = defaultVisibilityObserver();
  }
  return self.localVisibilityObserver_;
}

/**
 * Registers renderers with the shared visibility monitor.
 * @polymerBehavior
 */
export const VisibilityObserverBehavior = {
  isVisibilityRoot: false,

  properties: {
    observeVisibleOption: {type: String, value: null},
    observeHiddenOption: {type: String, value: null},
    observePrescanOption: {type: String, value: null},
    viewroot: Object,
    visibilityMonitorKeys: {type: Array, value: undefined},
    visibilityObserver: Object,
  },

  created() {
    this.visibilityObserverForChild_ = null;
    this.localVisibilityObserver_ = null;
    this.visibilityOptionVisible_ = visibilityOption(this.observeVisibleOption, 'visible');
    this.visibilityOptionHidden_ = visibilityOption(this.observeHiddenOption, 'hidden');
    this.visibilityOptionPrescan_ = visibilityOption(this.observePrescanOption, 'prescan');
  },

  attached() {
    if (this.isVisibilityRoot) this.visibilityObserverForChild_ = createVisibilityObserver(this.viewroot);
    soon(this.initVisibilityObserver_.bind(this));
  },

  detached() {
    this.unobserve_();
    this.visibilityObserverForChild_ = null;
    this.localVisibilityObserver_ = null;
  },

  initVisibilityObserver_() {
    if (this.hostElement && this.hostElement.isConnected && resolveVisibilityObserver(this)) this.configureVisibilityObserver_();
  },

  configureVisibilityObserver_() {
    this.unobserve_();
    const observer = resolveVisibilityObserver(this);
    if (flag('kevlar_vimio_use_shared_monitor')) {
      monitorVisibility(this.hostElement, {
        data: this.data || null,
        observer,
        visibilityCallback: this.visibilityCallback.bind(this),
        prescanCallback: this.onPrescanVisible.bind(this),
        layer: this.getScreenLayer && this.getScreenLayer(),
        showOption: this.visibilityOptionVisible_,
        hideOption: this.visibilityOptionHidden_,
        prescanOption: this.visibilityOptionPrescan_,
        skipLogging: this.shouldSkipLogging.bind(this),
      });
      return;
    }
    const keys = [];
    if (this.visibilityOptionVisible_) keys.push(observer.observe(this.hostElement, () => this.onVisible(), this.visibilityOptionVisible_));
    if (this.visibilityOptionHidden_) keys.push(observer.observe(this.hostElement, () => this.onHidden(), this.visibilityOptionHidden_));
    if (this.visibilityOptionPrescan_) keys.push(observer.observe(this.hostElement, () => this.onPrescanVisible(), this.visibilityOptionPrescan_));
    this.visibilityMonitorKeys = keys;
  },

  unobserve_() {
    unmonitorVisibility(this.hostElement, resolveVisibilityObserver(this));
  },

  markDirtyVisibilityObserver() {
    if (this.localVisibilityObserver_) this.configureVisibilityObserver_();
  },

  /** @return {?Object} */
  getVisibilityObserverForChild() {
    return this.visibilityObserverForChild_ ? this.visibilityObserverForChild_ : this.localVisibilityObserver_;
  },

  /** @param {boolean} visible */
  visibilityCallback(visible) {
    if (visible) this.onVisible();
    else this.onHidden();
  },

  onVisible() {},

  onHidden() {},

  onPrescanVisible() {},

  shouldSkipLogging() {},
};
if (!flag('kevlar_use_vimio_behavior')) {
  delete VisibilityObserverBehavior.attached;
  delete VisibilityObserverBehavior.detached;
}

/**
 * Visual-element logging on top of the visibility observer.
 * @polymerBehavior
 */
export const VisualElementBehavior = {
  properties: {
    observeVisibleOption: {type: String, value: 'observe_multiple'},
    observeHiddenOption: {type: String, value: 'observe_multiple'},
    visualElement: Object,
  },

  onVisible() {
    if (flag('kevlar_use_vimio_behavior') && this.onShow) this.onShow();
    if (!flag('kevlar_vimio_use_shared_monitor') && !this.shouldSkipLogging()) {
      const layer = this.getScreenLayer && this.getScreenLayer();
      const logger = this.getVisibilityLogger();
      if (logger) logger.reportShown(this, undefined, layer);
    }
  },

  onHidden() {
    if (flag('kevlar_use_vimio_behavior') && this.onHide) this.onHide();
    if (!flag('kevlar_vimio_use_shared_monitor')) {
      const layer = this.getScreenLayer && this.getScreenLayer();
      const logger = this.getVisibilityLogger();
      if (logger) logger.reportHidden(this, undefined, layer);
    }
  },

  /** @return {*} */
  getVisibilityLogger() {
    return flag('kevlar_use_vimio_behavior') ? loggerFacade() : null;
  },

  /**
   * Whether the monitor should skip logging this renderer: when it shows the
   * same data as its parent renderer.
   * @return {boolean}
   */
  shouldSkipLogging() {
    if (getConfig('INNERTUBE_CLIENT_NAME') !== 'WEB' || !this.data) return false;
    const parent = this.getParentRenderer && this.getParentRenderer();
    if (!parent) return false;
    const entry = rendererEntry(parent);
    const parentController = parent.polymerController != null ? parent.polymerController : parent;
    const parentData = entry && entry[RENDERER_DATA] != null ? entry[RENDERER_DATA] : parentController.data;
    if (!parentData) return false;
    const tp = logTrackingParamsOf(this.data);
    return !!tp && tp === logTrackingParamsOf(parentData);
  },
};

/** Hover trackers by element. */
/** @type {!Map<!Element, {cancel: function()}>} */
const hoverTrackers = new Map();

/**
 * Stops tracking hovers on `el`.
 * @param {!Element} el
 */
function untrackHover(el) {
  const t = hoverTrackers.get(el);
  if (!t) return;
  t.cancel();
  hoverTrackers.delete(el);
}

/**
 * Logs hovers of at least 500 ms on renderers whose logging directives ask
 * for hover gestures, then waits for the next hover.
 * @param {!Element} el
 */
function trackHover(el) {
  loggerFacade();
  if (!shouldLogGesture(el, 4)) return;
  untrackHover(el);
  let start = 0;
  const onLeave = () => {
    el.removeEventListener('mouseleave', onLeave);
    const ms = Math.round(performance.now() - start);
    if (ms >= 500 && ms < 600000) {
      const target = /** @type {?} */ (el);
      const csn = currentScreen(target.getScreenLayer ? target.getScreenLayer() : undefined) || '';
      const ve = target.visualElement ? target.visualElement : veFromTrackingParams(facadeTrackingParams(loggerFacade(), el));
      logGesture(csn, ve, 'INTERACTION_LOGGING_GESTURE_TYPE_HOVER', {hoverData: {durationHoveredMs: ms}});
    }
    trackHover(el);
  };
  const onEnter = /** @type {function()} */ (wrapErrors(() => {
    start = performance.now();
    el.addEventListener('mouseleave', onLeave);
  }));
  el.addEventListener('mouseenter', onEnter, {once: true});
  hoverTrackers.set(el, {cancel: () => {
    el.removeEventListener('mouseenter', onEnter);
    el.removeEventListener('mouseleave', onLeave);
  }});
}

/**
 * The renderer tree: parent lookup, screen layers, target ids.
 * @polymerBehavior
 */
export const RendererCoreBehavior = {
  childCache_: null,
  parentComponent: null,
  wasVisible: false,
  wasPrescan: false,
  lastHandledScroll_: 0,
  isRenderer_: true,
  screenLayer: null,
  veFromLoggingDirective_: false,
  useVimio_: flag('kevlar_use_vimio_behavior'),

  properties: {
    data: Object,
  },

  observers: [
    'ytRendererBehaviorDataObserver_(data)',
    'ytRendererBehaviorTargetIdObserver_(data.targetId)',
  ],

  created() {
    if (!this.useVimio_) this.childCache_ = new Set();
  },

  attached() {
    const host = this.hostElement;
    const parent = this.getParentRenderer();
    if (parent) {
      const target = parent.polymerController != null ? parent.polymerController : parent;
      if (target.registerRenderer != null) target.registerRenderer(host);
    }
    if (!this.useVimio_ && this.monitorScroll) {
      const scroller = this.monitorScrollElement != null ? this.monitorScrollElement : host;
      if (scroller) scroller.addEventListener('scroll', this.boundOnScroll_ || (this.boundOnScroll_ = this.onScroll.bind(this)));
    }
    schedule(() => trackHover(host), Priority.DEFERRED);
    const layerNode = new ScreenLayerNode(this.screenLayer || undefined);
    const parentEntry = parent ? rendererEntry(parent) : null;
    if (parentEntry && parentEntry.layerNode) layerNode.setParent(parentEntry.layerNode);
    const entry = {};
    entry.isRenderer = true;
    entry.layerNode = layerNode;
    entry[RENDERER_DATA] = this.data;
    setRendererEntry(host, entry);
  },

  detached() {
    const host = this.hostElement;
    if (this.monitorScroll && this.boundOnScroll_) {
      const scroller = this.monitorScrollElement != null ? this.monitorScrollElement : host;
      if (scroller) scroller.removeEventListener('scroll', this.boundOnScroll_);
    }
    if (this.parentComponent) {
      if (this.parentComponent.childCache_) this.parentComponent.childCache_.delete(host);
      this.parentComponent = null;
    }
    if (!this.useVimio_) this.markDirty();
    untrackHover(host);
    unregisterTarget(host);
    deleteRendererEntry(host);
  },

  /** @param {!Element} child */
  registerRenderer(child) {
    const target = child.polymerController != null ? child.polymerController : child;
    target.parentComponent = this.hostElement;
    if (!this.useVimio_) {
      this.childCache_.add(child);
      this.markDirty();
    }
  },

  /** @param {!Element} child */
  unregisterRenderer_(child) {
    if (this.useVimio_) return;
    this.childCache_.delete(child);
    this.markDirty();
  },

  /**
   * The nearest renderer above this one, across shadow roots.
   * @return {?Element}
   */
  getParentRenderer() {
    let n = this.hostElement.parentNode;
    for (; n; n = n.parentNode || /** @type {?} */ (n).host) {
      const entry = rendererEntry(n);
      if (entry && entry.isRenderer) break;
      const target = /** @type {?} */ (n).polymerController != null ? /** @type {?} */ (n).polymerController : n;
      if (target.isRenderer_) break;
    }
    return /** @type {?Element} */ (n);
  },

  onScroll() {
    const now = Date.now();
    if (now - this.lastHandledScroll_ < 50) return;
    this.lastHandledScroll_ = now;
    this.markDirty();
  },

  markDirty() {
    if (flag('kevlar_use_vimio_behavior')) this.markDirtyVisibilityObserver();
    else refreshVisibility(this.hostElement);
  },

  /** @return {*} */
  getScreenLayer() {
    if (this.screenLayer) return this.screenLayer;
    const parent = this.getParentRenderer();
    const entry = parent ? rendererEntry(parent) : null;
    if (entry && entry.layerNode) return layerOf(entry.layerNode);
    return undefined;
  },

  invalidate() {
    this.markDirty();
    this.wasPrescan = this.wasVisible = false;
  },

  /** @return {!Array<!Element>} */
  getNodes() {
    return this.childCache_ ? [...this.childCache_] : [];
  },

  impressionLog() {
    const data = this.data;
    if (data && data.impressionEndpoints) {
      for (let i = 0; i < data.impressionEndpoints.length; i++) this.sendImpression(data.impressionEndpoints[i]);
    } else if (data && data.impressionEndpoint) {
      this.sendImpression(data.impressionEndpoint);
    }
  },

  /** @param {!Object} endpoint */
  sendImpression(endpoint) {
    if (endpoint.clickTrackingParams) delete endpoint.clickTrackingParams;
    fireCommand(/** @type {!Element} */ (this.hostElement), endpoint);
  },

  /** @param {?Element=} el */
  logExplicitClick(el) {
    const csn = currentScreen(this.getScreenLayer());
    if (!csn || !el) return;
    const target = el.polymerController != null ? el.polymerController : el;
    let ve = target.visualElement;
    const tp = target.trackingParams || target.clickTrackingParams;
    if (!ve && tp) ve = veFromTrackingParams(tp);
    if (ve) logGesture(csn, ve);
  },

  ytRendererBehaviorDataObserver_() {
    const host = this.hostElement;
    const entry = rendererEntry(host);
    if (entry) entry[RENDERER_DATA] = this.data;
    const data = this.data;
    if (!data) return;
    this.wasVisible = false;
    if (flag('kevlar_use_vimio_behavior')) this.markDirtyVisibilityObserver();
    if (getConfig('ADD_SCRAPER_ATTRIBUTES') && data.trackingParams) host.dataset.ved = data.trackingParams;
    if (flag('debug_web_ve_data') && data.trackingParams) host.dataset.ve = data.trackingParams.slice(0, 8);
    if (this.veFromLoggingDirective_) {
      this.dataElement = this.clientYouTubeData = this.veType = this.visualElement = undefined;
      this.veFromLoggingDirective_ = false;
    }
    const directives = data.loggingDirectives;
    if (!this.visualElement && directives && directives.clientVeSpec && directives.clientVeSpec.uiType) {
      this.veType = directives.clientVeSpec.uiType;
      this.clientYouTubeData = directives.clientVeSpec.clientYoutubeData;
      if (flag('debug_web_ve_data')) host.dataset.ve = String(this.veType);
      if (directives.trackingParams) this.dataElement = veFromTrackingParams(directives.trackingParams);
      this.visualElement = clientVe(directives.clientVeSpec) || undefined;
      this.veFromLoggingDirective_ = true;
    }
  },

  ytRendererBehaviorTargetIdObserver_() {
    if (this.data && this.data.targetId) registerTarget(this.data.targetId, this.hostElement);
    else unregisterTarget(this.hostElement);
  },
};

let refreshJob = 0;

/**
 * Asks the old visibility system to recheck, once per frame.
 * @param {!Element} el
 */
function refreshVisibility(el) {
  if (refreshJob) cancel(refreshJob);
  refreshJob = schedule(() => {
    el.dispatchEvent(new CustomEvent('yt-visibility-refresh', {bubbles: true, composed: true}));
    refreshJob = 0;
  }, Priority.RENDER);
}

/**
 * The behaviours of every renderer element.
 * @polymerBehavior
 */
export const RendererBehavior = [InitBehavior, InjectBehavior, ComponentBehavior, VisibilityObserverBehavior,
  VisualElementBehavior, RendererCoreBehavior, TemplateHelpersBehavior];
