/**
 * NZ content-rating type of a badge (`h14`).
 * @param {string|undefined} kind
 * @return {string}
 */
export function nzRatingTypeOf(kind) {
  switch (kind) {
    case 'NZ_RATING_G':
      return 'g';
    case 'NZ_RATING_PG':
      return 'pg';
    case 'NZ_RATING_M':
      return 'm';
    default:
      return '';
  }
}

/**
 * Whether a badge sits on an overlay, from the renderer's context.
 * @param {string|undefined} context
 * @return {boolean}
 */
export function badgeIsOverlay(context) {
  switch (context) {
    case 'THUMBNAIL':
    case 'PLAYER':
      return true;
    case 'INLINE':
    case 'METADATA':
    default:
      return false;
  }
}

/**
 * Whether an ad badge includes the dot.
 * @param {string|undefined} style
 * @return {boolean}
 */
export function adsIncludeDot(style) {
  switch (style) {
    case 'BADGE_STYLE_TYPE_AD':
      return true;
    default:
      return false;
  }
}

