/**
 * Thumbnail aspect-ratio class.
 * @param {string|undefined} aspect
 * @return {string}
 */
export function thumbnailAspectClass(aspect) {
  switch (aspect) {
    case 'GRID_SHELF_CONTENT_ASPECT_RATIO_TWO_BY_THREE':
    case 'THUMBNAIL_ASPECT_RATIO_TWO_BY_THREE':
      return 'ytlThumbnailViewModelAspectRatio2By3';
    case 'RENDERING_ASPECT_SQUARE':
    case 'THUMBNAIL_ASPECT_RATIO_SQUARE':
      return 'ytlThumbnailViewModelAspectRatio1By1';
    default:
      return 'ytlThumbnailViewModelAspectRatio16By9';
  }
}

/**
 * Image content-mode class.
 * @param {string|undefined} mode
 * @return {string}
 */
export function contentModeClass(mode) {
  switch (mode) {
    case 'fit':
    case 'IMAGE_CONTENT_MODE_SCALE_ASPECT_FIT':
      return 'ytlCoreImageContentModeScaleAspectFit';
    case 'fill-width':
      return 'ytlCoreImageContentModeScaleToFill';
    case 'center':
      return 'ytlCoreImageContentModeCenter';
    default:
      return 'ytlCoreImageContentModeScaleAspectFill';
  }
}

/**
 * Avatar size in pixels.
 * @param {string|undefined} size
 * @return {number}
 */
export function avatarSizeOf(size) {
  switch (size) {
    case 'AVATAR_SIZE_XXS':
      return 16;
    case 'AVATAR_SIZE_XS':
    case 'AD_AVATAR_SIZE_XS':
      return 24;
    case 'AVATAR_SIZE_S':
      return 32;
    case 'AVATAR_SIZE_L':
      return 48;
    default:
      return 36;
  }
}

/**
 * Reads a set of experiment flags into an object, as components do once
 * per render.
 * @param {!Array<string>} names
 * @return {!Object<string, boolean>}
 */
export function readFlags(names) {
  const out = {};
  for (const name of names) out[name] = flag(name);
  return out;
}

