/**
 * @fileoverview The masthead searchbox: a view-model component with the
 * query in a signal, a clear button, and suggestions-style attachments.
 * Submitting fires `yt-navigate` with a search endpoint, then clears the
 * attachments in a microtask.
 */
import {h} from '../../framework/vm/jsx.js';
import {Cond} from '../../framework/vm/control.js';
import {createSignal} from '../../framework/signals.js';
import {Icon, TouchFeedbackShape} from './primitives.js';

/** @return {*} */
export function Searchbox() {
  const [query, setQuery] = createSignal('', undefined);
  const [attachments, setAttachments] = createSignal(/** @type {!Array<string>} */ ([]), undefined);
  const [focused, setFocused] = createSignal(false, undefined);
  /** @type {?HTMLInputElement} */
  let input = null;

  const clearAttachments = async () => {
    await Promise.resolve();
    setAttachments([]);
    // YouTube refocuses the input here. Disabled because in Speedometer's
    // iframe, Firefox's FormAutofill then observes every DOM insertion.
    // if (input) input.focus();
  };

  const submit = (/** !Event */ e) => {
    e.preventDefault();
    const q = input ? input.value : query();
    if (!q) return;
    setQuery(q);
    const form = /** @type {!Element} */ (e.currentTarget);
    form.dispatchEvent(new CustomEvent('yt-navigate', {
      bubbles: true,
      composed: true,
      detail: {endpoint: {
        commandMetadata: {webCommandMetadata: {url: `/results?search_query=${encodeURIComponent(q)}`, webPageType: 'WEB_PAGE_TYPE_SEARCH', rootVe: 4724}},
        searchEndpoint: {query: q},
      }},
    }));
    clearAttachments();
  };

  return h('ytl-searchbox', {class: () => `ytlSearchboxComponentHost ${focused() ? 'ytlSearchboxComponentHostFocused' : ''}`},
    h('form', {class: 'ytlSearchboxComponentSearchForm', action: '/results', role: 'search', 'on:submit': submit},
      h('div', {class: 'ytlSearchboxComponentInputBox'},
        h(Cond, {
          when: () => attachments().length > 0,
          then: () => h('div', {class: 'ytlSearchboxComponentAttachments'}, () => attachments().map(a => h('span', {class: 'ytlSearchboxComponentAttachment'}, a))),
        }),
        h('input', {
          class: 'ytlSearchboxComponentInput',
          name: 'search_query',
          type: 'text',
          autocomplete: 'off',
          autocapitalize: 'none',
          spellcheck: 'false',
          placeholder: 'Search',
          role: 'combobox',
          'aria-haspopup': 'false',
          ref: (/** !Element */ el) => { input = /** @type {!HTMLInputElement} */ (el); },
          'on:input': (/** !Event */ e) => setQuery(/** @type {!HTMLInputElement} */ (e.target).value),
          'on:focus': () => setFocused(true),
          'on:blur': () => setFocused(false),
        }),
        h(Cond, {
          when: () => query().length > 0,
          then: () => h('div', {class: 'ytlSearchboxComponentClearButtonContainer'},
            h('button', {
              class: 'ytlSearchboxComponentClearButton',
              type: 'button',
              'aria-label': 'Clear search query',
              'on:click': () => {
                setQuery('');
                if (input) {
                  input.value = '';
                  input.focus();
                }
              },
            }, h(Icon, {icon: 'CLOSE', size: 24}), h(TouchFeedbackShape, {}))),
        })),
      h('button', {class: 'ytlSearchboxComponentSearchButton', type: 'submit', 'aria-label': 'Search', title: 'Search'},
        h(Icon, {icon: 'SEARCH', size: 24}), h(TouchFeedbackShape, {}))));
}
