/**
 * @fileoverview The attributed string (`_.H8`) and its CoW host
 * (`ytl-attributed-string`). The options are a computed with a deep
 * equality check, the text a normalising computed, and the outer component
 * a `cond` on the text. The span's parts are rendered by an after-render
 * effect: in a microtask it clears the span, disposes the previous parts
 * render and renders the parts as a new root. The parts come from the
 * string's runs: style, command, decoration, attachment and paragraph
 * runs become part descriptors, which are sorted, nested by range
 * containment and filled with the plain-text gaps.
 */
import {cond} from '../../framework/vm/control.js';
import {afterRenderEffect, computed, runUntracked, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent, renderRoot} from '../../framework/vm/render.js';
import {flag} from '../../framework/flags.js';
import {linkConfig} from '../../framework/link.js';
import {fireCommand} from '../commands.js';
import {baselineOffsetClass, fontWeightOf, headingTagOf, textAlignmentClass} from './enums.js';
import {themeColor} from './primitives.js';

/**
 * @param {*} a
 * @param {*} b
 * @return {boolean}
 */
function deepEqual(a, b) {
  if (a === b) return true;
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const ka = Object.keys(a);
  const kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) {
    if (!deepEqual(a[k], b[k])) return false;
  }
  return true;
}

/**
 * A computed of `fn` with the attributed-string equality (`_.IPY`).
 * @param {function(): *} fn
 * @param {string} name
 * @return {function(): *}
 */
function equalComputed(fn, name) {
  return computed(fn, flag('web_attributed_string_deep_equal_bugfix') ? deepEqual : undefined, name);
}

/**
 * The options thunk (`e58`).
 * @param {!Object} props
 * @return {function(): !Object}
 */
function optionsOf(props) {
  return () => ({
    ariaLabel: unwrap(props.ariaLabel),
    className: unwrap(props.className),
    ellipsisTruncate: unwrap(props.ellipsisTruncate),
    isOverlay: unwrap(props.isOverlay),
    linkInheritColor: unwrap(props.linkInheritColor),
    noEndpoints: unwrap(props.noEndpoints),
    noStyleRuns: unwrap(props.noStyleRuns),
    noLinkColor: unwrap(props.noLinkColor),
    noPreWrap: unwrap(props.noPreWrap),
    noWrap: unwrap(props.noWrap),
    skipOnClick: unwrap(props.skipOnClick),
    userInput: unwrap(props.userInput),
    headerRuns: unwrap(props.headerRuns),
    isHeadline: unwrap(props.isHeadline),
  });
}

/**
 * @param {*} text
 * @return {?Object}
 */
function normalizeText(text) {
  if (typeof text === 'string') text = {content: text};
  else if (text && typeof text === 'object' && /** @type {!Object} */ (text).content === undefined) {
    const t = /** @type {!Object} */ (text);
    if (t.simpleText !== undefined) text = {content: t.simpleText};
    else if (t.runs) text = {content: t.runs.map((r) => r.text || '').join('')};
  }
  if (!text || typeof text !== 'object') return null;
  const t = /** @type {!Object} */ (text);
  if (!t.content && !(t.attachmentRuns && t.attachmentRuns.length)) return null;
  return t;
}

/**
 * @typedef {{start: number, end: number, tag: string, attrs: !Object, children: !Array<*>}}
 */
let Part;

/**
 * @param {!Object} run
 * @param {!Object} options
 * @return {!Part}
 */
function stylePart(run, options) {
  const start = run.startIndex || 0;
  const cls = [];
  if (run.italic) cls.push('ytlAttributedStringItalic');
  if (run.strikethrough) cls.push(strikeClass(run.strikethrough));
  if (run.underline) cls.push(underlineClass(run.underline));
  const baseline = baselineOffsetClass(run.baselineOffset);
  if (baseline) cls.push(baseline);
  if (options.linkInheritColor) cls.push('ytlAttributedStringLinkInheritColor');
  const style = {};
  const weight = fontWeightOf(run.weightLabel);
  if (weight) style['font-weight'] = weight;
  const color = runColor(run);
  if (color) style['color'] = color;
  return {start, end: start + (run.length || 0), tag: 'span', attrs: {class: cls.join(' ') || undefined, style}, children: []};
}

/**
 * @param {*} kind
 * @return {string}
 */
function strikeClass(kind) {
  return kind === 'LINE_STYLE_DOUBLE' ? 'ytlAttributedStringDoubleStrikethrough' : 'ytlAttributedStringStrikethrough';
}

/**
 * @param {*} kind
 * @return {string}
 */
function underlineClass(kind) {
  return kind === 'UNDERLINE_STYLE_DOTTED' ? 'ytlAttributedStringDottedUnderline' : 'ytlAttributedStringUnderline';
}

/**
 * The colour of a style run (`SiY`), from its theme colour map or its raw
 * colour.
 * @param {!Object} run
 * @return {string|undefined}
 */
function runColor(run) {
  const ext = run.styleRunExtensions && run.styleRunExtensions.styleRunColorMapExtension;
  if (ext && ext.colorMap) {
    let token = null;
    for (const entry of ext.colorMap) {
      if (entry.key === 'USER_INTERFACE_THEME_DARK') token = Object.assign({}, token, {darkTheme: entry.value});
      else token = Object.assign({}, token, {lightTheme: entry.value});
    }
    return themeColor(token, null);
  }
  return run.fontColor != null ? themeColor(null, run.fontColor) : undefined;
}

/**
 * A command run (`dad`): a link with its class list, label, link config and
 * click and long-press handlers.
 * @param {!Object} run
 * @param {!Object} options
 * @return {!Part}
 */
function commandPart(run, options) {
  const start = run.startIndex || 0;
  const command = (run.onTap && (run.onTap.innertubeCommand || run.onTap)) || null;
  const link = linkConfig(command);
  const cls = ['ytlAttributedStringLink'];
  if (options.linkInheritColor) cls.push('ytlAttributedStringLinkInheritColor');
  else cls.push('ytlAttributedStringLinkCallToActionColor');
  const onClick = (/** !Event */ e) => {
    e.preventDefault();
    fireCommand(/** @type {!Element} */ (e.currentTarget), command);
  };
  const onLongPress = (/** !Event */ e) => {
    if (run.onLongPress) fireCommand(/** @type {!Element} */ (e.currentTarget), run.onLongPress.innertubeCommand || run.onLongPress);
  };
  return {start, end: start + (run.length || 0), tag: 'a', attrs: {
    class: cls.join(' '),
    href: link.href,
    rel: link.rel,
    target: link.target,
    tabindex: '0',
    'aria-label': (run.accessibilityLabel) || undefined,
    'on:click': onClick,
    'on:contextmenu': onLongPress,
  }, children: []};
}

/**
 * @param {!Object} run
 * @return {!Part}
 */
function decorationPart(run) {
  const start = run.startIndex || 0;
  const style = {};
  const highlight = run.textDecorator && run.textDecorator.highlightTextDecorator;
  if (highlight) {
    if (highlight.backgroundColor != null) style['background-color'] = themeColor(null, highlight.backgroundColor);
    if (highlight.backgroundCornerRadius) style['border-radius'] = `${highlight.backgroundCornerRadius}px`;
    if (highlight.bottomPadding) style['padding-bottom'] = `${highlight.bottomPadding}px`;
    if (highlight.topPadding) style['padding-top'] = `${highlight.topPadding}px`;
    if (highlight.startPadding) style['padding-left'] = `${highlight.startPadding}px`;
    if (highlight.endPadding) style['padding-right'] = `${highlight.endPadding}px`;
  }
  return {start, end: start + (run.length || 0), tag: 'span', attrs: {class: 'ytlAttributedStringHighlight', style}, children: []};
}

/**
 * An attachment run: an image with margin, size and alignment classes.
 * @param {!Object} run
 * @return {!Part}
 */
function attachmentPart(run) {
  const start = run.startIndex || 0;
  const el = run.element || {};
  const props = el.properties || {};
  const size = props.layoutProperties || {};
  const height = size.height && size.height.value;
  const width = size.width && size.width.value;
  const sources = (el.type && el.type.imageType && el.type.imageType.image && el.type.imageType.image.sources) || [];
  const cls = ['ytlAttributedStringImage'];
  if (run.alignment === 'ALIGNMENT_VERTICAL_CENTER') cls.push('ytlAttributedStringImageAlignCenter');
  if (size.margin) cls.push('ytlAttributedStringImageMargin');
  return {start, end: start + (run.length || 0), tag: 'img', attrs: {
    class: cls.join(' '), alt: '', src: sources[0] && sources[0].url, height: height ? `${height}` : undefined,
    width: width ? `${width}` : undefined,
  }, children: []};
}

/**
 * @param {!Object} run
 * @return {!Part}
 */
function paragraphPart(run) {
  const start = run.startIndex || 0;
  const list = run.style && run.style.listStyle;
  const header = run.style && run.style.headerStyle;
  const tag = list ? 'li' : header ? headingTagOf(header.size) : 'span';
  return {start, end: start + (run.length || 0), tag, attrs: {class: list ? 'ytlAttributedStringListItem' : undefined}, children: []};
}

/**
 * Orders parts by start, longer ones first (`v6j`).
 * @param {!Part} a
 * @param {!Part} b
 * @return {number}
 */
function byRange(a, b) {
  return a.start - b.start || (b.end - b.start) - (a.end - a.start);
}

/**
 * Nests sorted parts into `parent` by range containment (`USY`).
 * @param {!Array<!Part>} parts
 * @param {!Part} parent
 * @param {number} from
 * @return {number} The index of the first part not contained in `parent`.
 */
function nest(parts, parent, from) {
  let i = from;
  while (i < parts.length && parts[i].start < parent.end && parts[i].end <= parent.end) {
    const part = parts[i];
    parent.children.push(part);
    i = nest(parts, part, i + 1);
  }
  return i;
}

/**
 * Fills the plain-text gaps of `part` (`cCj`).
 * @param {!Part} part
 * @param {string} content
 */
function fill(part, content) {
  const children = part.children;
  let pos = part.start;
  for (let i = 0; i < children.length; i++) {
    const child = /** @type {!Part} */ (children[i]);
    if (child.start > pos) {
      children.splice(i, 0, content.slice(pos, child.start));
      i++;
    }
    fill(child, content);
    pos = Math.max(pos, child.end);
  }
  if (pos < part.end) children.push(content.slice(pos, part.end));
}

/**
 * The part tree of an attributed string (`V`).
 * @param {!Object} text
 * @param {!Object} options
 * @return {!Part}
 */
function buildParts(text, options) {
  const content = String(text.content || '');
  const parts = [];
  for (const run of text.paragraphStyleRuns || []) parts.push(paragraphPart(run));
  if (!options.noStyleRuns) {
    for (const run of text.styleRuns || []) parts.push(stylePart(run, options));
  }
  if (!options.noEndpoints) {
    for (const run of text.commandRuns || []) parts.push(commandPart(run, options));
  }
  for (const run of text.decorationRuns || []) parts.push(decorationPart(run));
  for (const run of text.attachmentRuns || []) parts.push(attachmentPart(run));
  parts.sort(byRange);
  const root = {start: 0, end: content.length, tag: '', attrs: {}, children: []};
  nest(parts, root, 0);
  fill(root, content);
  return root;
}

/**
 * The nodes of a part's children (`$S8`/`JCY`).
 * @param {!Array<*>} children
 * @return {!Array<*>}
 */
function renderParts(children) {
  return children.map((child) => {
    if (typeof child === 'string') return child;
    const part = /** @type {!Part} */ (child);
    return h(part.tag, part.attrs, part.tag === 'img' ? null : renderParts(part.children));
  });
}

/**
 * The class list of the span.
 * @param {!Object} t The text.
 * @param {!Object} o The options.
 * @return {string}
 */
function spanClass(t, o) {
  const list = ['ytlAttributedStringHost'];
  if (o.className) list.push(o.className);
  if (o.ellipsisTruncate) list.push('ytlAttributedStringEllipsisTruncate');
  else if (o.noWrap) list.push('ytlAttributedStringWhiteSpaceNoWrap');
  else if (!o.noPreWrap) list.push('ytlAttributedStringWhiteSpacePreWrap');
  if (o.linkInheritColor) list.push('ytlAttributedStringLinkInheritColor');
  if (t.alignment) list.push(textAlignmentClass(t.alignment));
  if (t.lineBreakMode) list.push('ytlAttributedStringWordWrapping');
  return list.join(' ');
}

/**
 * Whether the span carries its label (`W6d`): when a label is given, or
 * when the text has no command or paragraph runs.
 * @param {!Object} t
 * @param {*} label
 * @return {boolean}
 */
function labelsSpan(t, label) {
  return !!label || !((t.commandRuns && t.commandRuns.length) || (t.paragraphStyleRuns && t.paragraphStyleRuns.length));
}

/**
 * The rendered span with its parts; the `cond` branch of the attributed
 * string.
 * @param {function(): *} options
 * @param {function(): *} text
 * @param {*} style
 * @return {!Object}
 */
function attributedSpan(options, text, style) {
  /** @type {?Element} */
  let span = null;
  /** @type {?{dispose: function()}} */
  let parts = null;
  /** @type {*} */
  let previous = null;
  afterRenderEffect(() => {
    const t = text();
    const o = options();
    runUntracked(() => {
      if (deepEqual(t, previous)) return;
      previous = t;
      queueMicrotask(() => {
        if (!span) return;
        span.innerText = '';
        if (parts) parts.dispose();
        parts = t ? renderRoot(renderParts(buildParts(/** @type {!Object} */ (t), /** @type {!Object} */ (o)).children), null, span) : null;
      });
    });
  }, 'KgZVkd');
  return h('span', {
    class: () => (text() ? spanClass(/** @type {!Object} */ (text()), /** @type {!Object} */ (options())) : undefined),
    style,
    dir: () => (/** @type {!Object} */ (options()).userInput ? 'auto' : undefined),
    'aria-label': () => (labelsSpan(/** @type {!Object} */ (text()), /** @type {!Object} */ (options()).ariaLabel) ? /** @type {!Object} */ (options()).ariaLabel : undefined),
    role: () => (labelsSpan(/** @type {!Object} */ (text()), /** @type {!Object} */ (options()).ariaLabel) ? 'text' : undefined),
    ref: {
      onRender: (/** !Element */ el) => {
        span = el;
      },
      onUnmount: () => {
        if (parts) parts.dispose();
        parts = null;
        span = null;
      },
    },
  });
}

/**
 * The attributed string (`_.H8`). Its text is the `text` prop.
 */
export const AttributedString = defineComponent((props) => {
  const options = equalComputed(optionsOf(props), 'tAhC7e');
  const text = equalComputed(() => normalizeText(unwrap(props.text)), 'Oe9wNd');
  return cond(() => !!text(), () => attributedSpan(options, text, props.style));
}, 'H8');

const AttributedStringHost = defineComponent((props) => h('ytl-attributed-string', {
  'aria-label': props.ariaLabel, hidden: props.hidden, id: props.id, class: props.className, style: props.style,
}, h(AttributedString, {
  text: props.data, ariaHidden: props.ariaHidden, ariaLabel: props.ariaLabel, ellipsisTruncate: props.ellipsisTruncate,
  isOverlay: props.isOverlay, linkInheritColor: props.linkInheritColor, noStyleRuns: props.noStyleRuns,
  noLinkColor: props.noLinkColor, noPreWrap: props.noPreWrap, noWrap: props.noWrap, userInput: props.userInput,
  noEndpoints: props.noEndpoints, headerRuns: props.headerRuns, isHeadline: props.isHeadline,
})), 'ytl-attributed-string (CoW)');

defineCoW('ytl-attributed-string', AttributedStringHost, {props: {
  ariaHidden: PropKind.SIGNAL, ariaLabel: PropKind.SIGNAL, ellipsisTruncate: PropKind.SIGNAL, isOverlay: PropKind.SIGNAL,
  linkInheritColor: PropKind.SIGNAL, noEndpoints: PropKind.SIGNAL, noStyleRuns: PropKind.SIGNAL,
  noLinkColor: PropKind.SIGNAL, noPreWrap: PropKind.SIGNAL, noWrap: PropKind.SIGNAL, skipOnClick: PropKind.SIGNAL,
  userInput: PropKind.SIGNAL, headerRuns: PropKind.SIGNAL, isHeadline: PropKind.SIGNAL, data: PropKind.SIGNAL,
  id: PropKind.SIGNAL, className: PropKind.SIGNAL, hidden: PropKind.SIGNAL, style: PropKind.SIGNAL,
  slot: PropKind.STATIC,
}});
