/**
 * @fileoverview Experiment flags and client config. The page sets the config
 * in an inline script (`ytlcfg.set`) before the app loads; it holds one
 * large flags dictionary of about 1,070 entries in which false flags are
 * absent. Every read looks up `EXPERIMENT_FLAGS` in the config with an `in`
 * check, passing a fresh empty object as the default, then reads the flag by
 * name.
 */

/** @type {!Object<string, *>} */
const config = (() => {
  const w = /** @type {?} */ (window);
  return (w['yt'] && w['yt']['config_']) || (w['ytlcfg'] && w['ytlcfg']['data_']) || {};
})();

/**
 * @param {string} name
 * @param {*=} fallback
 * @return {*}
 */
export function getConfig(name, fallback) {
  return name in config ? config[name] : fallback;
}

/**
 * @param {string} name
 * @param {*=} fallback
 * @return {*}
 */
export function flagValue(name, fallback) {
  const v = /** @type {!Object<string, *>} */ (getConfig('EXPERIMENT_FLAGS', {}))[name];
  return v !== undefined ? v : fallback;
}

/**
 * A boolean flag. The string "false" counts as false.
 * @param {string} name
 * @param {boolean=} fallback
 * @return {boolean}
 */
export function flag(name, fallback) {
  const v = flagValue(name, fallback);
  return typeof v === 'string' && v === 'false' ? false : !!v;
}

/**
 * A numeric flag.
 * @param {string} name
 * @param {number=} fallback
 * @return {number}
 */
export function flagNumber(name, fallback = 0) {
  const v = Number(flagValue(name, fallback));
  return isNaN(v) ? fallback : v;
}

/**
 * Sets a config value.
 * @param {string} name
 * @param {*} value
 */
export function setConfig(name, value) {
  config[name] = value;
}

/**
 * The value at a dotted path below `window`, or null.
 * @param {string} path
 * @return {*}
 */
export function getObjectByName(path) {
  let o = /** @type {?} */ (window);
  for (const part of path.split('.')) {
    o = o[part];
    if (o == null) return null;
  }
  return o;
}
