import {NOT_FOUND, setCurrentInjector} from './signals.js';

/** A small root injector for the DI primitives' `retrieve` protocol. */
export class RootInjector {
  constructor() {
    /** @private @const {!Map<*, *>} */
    this.instances_ = new Map();
  }

  /**
   * @param {*} token
   * @param {*=} options
   * @return {*}
   */
  retrieve(token, options) {
    if (this.instances_.has(token)) return this.instances_.get(token);
    const prov = token['ɵprov'];
    if (!prov || prov.providedIn !== 'root') return NOT_FOUND;
    const value = prov.factory();
    this.instances_.set(token, value);
    return value;
  }

  /**
   * Registers `value` for `token`.
   * @param {*} token
   * @param {*} value
   */
  provide(token, value) {
    this.instances_.set(token, value);
  }

  /**
   * The value for `token`, or undefined.
   * @param {*} token
   * @return {*}
   */
  resolve(token) {
    const value = this.retrieve(token);
    return value === NOT_FOUND ? undefined : value;
  }

  /**
   * Runs `fn` with this injector as the current injector.
   * @template T
   * @param {function(): T} fn
   * @return {T}
   */
  runInContext(fn) {
    const prev = setCurrentInjector(this);
    try {
      return fn();
    } finally {
      setCurrentInjector(prev);
    }
  }
}

export const rootInjector = new RootInjector();
