/**
 * @fileoverview Entity store updates from `frameworkUpdates` mutations (comments, like status,
 * subscription state, ...). A response's mutations go to the app store as one
 * batch action; elements select the entities they show by type and key.
 */
import {appStore} from './store.js';

/**
 * @param {!Array<!Object>} mutations
 * @return {number} The number of applied mutations.
 */
export function applyEntityMutations(mutations) {
  let n = 0;
  const updates = [];
  for (const m of mutations) {
    const key = m.entityKey;
    if (typeof key !== 'string') continue;
    if (m.payload) {
      const entityType = Object.keys(m.payload)[0];
      if (entityType) {
        updates.push({entityType, key, value: m.type === 'ENTITY_MUTATION_TYPE_DELETE' ? undefined : m.payload[entityType]});
      }
    }
    n++;
  }
  if (updates.length) appStore.dispatch({type: 'ENTITY_BATCH_UPDATE', payload: updates});
  return n;
}
