/**
 * Calls `fn` at most once per `ms`, at the end of the interval.
 * @param {function()} fn
 * @param {number} ms
 * @return {function()}
 */
function throttle(fn, ms) {
  let timer = 0;
  return () => {
    if (timer) return;
    timer = later(() => {
      timer = 0;
      fn();
    }, ms);
  };
}

/**
 * @param {!Object} self An item section controller.
 * @return {!Array<!Element>}
 */
function queryLockups(self) {
  return Array.from(self.hostElement.querySelectorAll('#contents ytl-lockup-view-model, #contents ytl-suspense-view-model'));
}

/** The scroll listener of each sticky item section. */
const stickyScrollListeners = new WeakMap();

/**
 * @param {!Object} self An item section controller.
 * @return {function()}
 */
function stickyScrollListener(self) {
  let listener = stickyScrollListeners.get(self);
  if (!listener) {
    listener = () => self.updateHeaderState();
    stickyScrollListeners.set(self, listener);
  }
  return listener;
}

