/** Animates the scroll position of an element to a target. */
class ScrollAnimation {
  /** @param {!Element} element */
  constructor(element) {
    /** @const */
    this.element_ = element;
    this.frame_ = 0;
  }

  /**
   * @param {number} from
   * @param {number} to
   * @param {number} duration
   */
  start(from, to, duration) {
    cancelAnimationFrame(this.frame_);
    const begin = performance.now();
    const step = now => {
      const t = Math.min(1, (now - begin) / duration);
      this.element_.scrollTop = from + (to - from) * t;
      this.frame_ = t < 1 ? requestAnimationFrame(step) : 0;
    };
    this.frame_ = requestAnimationFrame(step);
  }
}

