/**
 * @fileoverview The metadata of a lockup (`yt-lockup-metadata-view-model`,
 * `_.J5B`) as its own component, with the parts it renders: the avatar
 * slot, the title, the content metadata with its rows, text parts and
 * delimiters, the attribution, the action bar and the menu button. Also the
 * decorated avatar with its avatar shape, and the badge view model that
 * rows use. YouTube's tree is about 120 effects per lockup for the metadata
 * alone: each renderer switch, `cond`, token hook and element with
 * function-valued props costs what it costs there.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {IndexEach, Switch, cond} from '../../framework/vm/control.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {unwrap} from '../../framework/vm/effect.js';
import {defineComponent} from '../../framework/vm/render.js';
import {rootInjector} from '../../framework/injector.js';
import {flag} from '../../framework/flags.js';
import {fireCommand} from '../commands.js';
import {AvatarStack, AvatarViewModel, DecoratedAvatar} from './avatars.js';
import {BadgeShape, NzRatingBadge} from './badges.js';
import {ButtonViewModel} from './buttons.js';
import {AttributedString} from './attributed-string.js';
import {COMMAND_CONTEXT, CommandLink, contextCommandOf, contextLabel, innertubeOf, rendererField, rendererOf, useBreakpoint, useColorToken,
  useCommandContext, useLayoutToken, useTypographyToken, withDefaults} from './hooks.js';
import {Image} from './image.js';
import {DarkTheme, IconByName} from './primitives.js';

/**
 * The tag-keyed class of a delimiter or text part by line count.
 * @param {number|undefined} lines
 * @return {string|undefined}
 */
function maxLinesClass(lines) {
  switch (lines) {
    case undefined:
      return undefined;
    case 0:
      return 'ytlContentMetadataViewModelMetadataTextMaxLines0';
    case 1:
      return 'ytlContentMetadataViewModelMetadataTextMaxLines1';
    case 2:
      return 'ytlContentMetadataViewModelMetadataTextMaxLines2';
    case 3:
      return 'ytlContentMetadataViewModelMetadataTextMaxLines3';
    default:
      return 'ytlContentMetadataViewModelMetadataTextMaxLines4';
  }
}

/** The delimiter after a part or row (`ec`): a `cond` and a span. */
const Delimiter = defineComponent((props) => cond(() => !(props.hideDelimiter && props.hideDelimiter()) && props.max() - 1 > props.index(), () => h('span', {
  class: classes('ytlContentMetadataViewModelDelimiter', {'ytlContentMetadataViewModelDelimiterStandalone': props.isStandalone}),
  'aria-hidden': true,
}, props.delimiter)), 'ec');

/** The text of a metadata part (`m6E`). */
const PartText = defineComponent((props) => {
  const part = /** @type {function(): !Object} */ (props.metadataPart);
  const breakpoint = useBreakpoint();
  const margin = useLayoutToken(() => part().textMarginEndToken);
  const rtl = document.documentElement.dir === 'rtl';
  const color = useColorToken(() => part().colorToken);
  return h(AttributedString, {
    style: styles(useTypographyToken(() => part().typographyToken, breakpoint, {forceSmallLayout: props.forceSmallLayout}),
        rtl ? {'margin-left': margin} : {'margin-right': margin}, {color}),
    text: () => part().text,
    ariaLabel: () => part().accessibilityLabel,
    linkInheritColor: true,
    className: classes(() => {
      const lines = props.maxLines();
      return lines === 1 ? 'ytlContentMetadataViewModelMetadataText' : maxLinesClass(lines);
    }, {'ytlContentMetadataViewModelMetadataTextLastPart': props.isLastPart}),
    userInput: true,
  });
}, 'fc');

/** A part's text, inside a tooltip span when it has one (`gZK`). */
const PartTextWithTooltip = defineComponent((props) => cond(() => (props.metadataPart() || {}).tooltip,
    () => h('span', {title: () => props.metadataPart().tooltip, role: 'tooltip'}, h(PartText, props)),
    () => h(PartText, props)), 'gc');

/**
 * The badge view model's badge-shape type by style (`R1y`).
 * @param {string|undefined} style
 * @return {string}
 */
function badgeStyleType(style) {
  switch (style) {
    case 'BADGE_COMMERCE':
    case 'BADGE_MEMBERS_ONLY':
      return 'BADGE_COMMERCE';
    case 'BADGE_MEDIA':
      return 'BADGE_STYLE_TYPE_MEDIA';
    case 'BADGE_LIVE_NOW':
      return 'BADGE_STYLE_TYPE_LIVE_NOW';
    case 'BADGE_PREMIUM':
      return 'BADGE_STYLE_TYPE_PREMIUM';
    case 'BADGE_PROMOTED':
      return 'BADGE_STYLE_TYPE_AD';
    default:
      return 'BADGE_STYLE_TYPE_SIMPLE';
  }
}

const RATING_STYLE = /^BADGE_(NZ|BR)_RATING_/;

/** The badge view model (`yvq`): a switch over the rating badges and the badge shape. */
export const BadgeViewModel = defineComponent((props) => {
  const config = () => {
    const r = props.data();
    if (!r) return undefined;
    return {
      badgeStyle: badgeStyleType(r.badgeStyle),
      text: r.badgeText,
      icon: r.iconName,
      isOverlay: r.badgeStyle === 'BADGE_OVERLAY',
      modern: (props.modern && props.modern()) || flag('web_modern_badge_view_model'),
      label: r.accessibilityLabel || contextLabel(r.rendererContext),
      numBadgesInRow: props.numBadgesInRow && props.numBadgesInRow(),
      tooltip: undefined,
    };
  };
  return h('ytl-badge-view-model', {class: classes('ytlBadgeViewModelHost', props.class)},
    h(Switch, {
      value: () => 0,
      cases: [[() => !!config() && RATING_STYLE.test(props.data().badgeStyle), () => h(NzRatingBadge, {rating: () => props.data().badgeStyle.replace(RATING_STYLE, '')})],
        [() => !!config(), () => h(BadgeShape, {data: config})]],
    }));
}, 'ytl-badge-view-model (CoW)');

defineCoW('ytl-badge-view-model', BadgeViewModel, {props: {data: PropKind.SIGNAL, workaroundShortsIsThumbnailBadge: PropKind.SIGNAL,
  modern: PropKind.SIGNAL, numBadgesInRow: PropKind.SIGNAL, clipTextOverflow: PropKind.SIGNAL, inheritTypography: PropKind.SIGNAL,
  class: PropKind.SIGNAL}});

/** One part of a metadata row (`G6O`): avatar stack or badge, leading icon, text, trailing icon. */
const MetadataPart = defineComponent((props) => {
  const part = /** @type {function(): !Object} */ (props.metadataPart);
  const leadingColor = () => useColorToken(() => (part().leadingIcon || {}).colorToken);
  const leadingMargin = useLayoutToken(() => (part().leadingIcon || {}).marginEndToken);
  const iconMargin = useLayoutToken(() => (part().icon || {}).marginEndToken);
  const maxLines = () => {
    if (props.rowHasMaxLines && props.rowHasMaxLines()) return 0;
    const lines = part().maxLines;
    return lines != null ? lines : 1;
  };
  return [
    rendererOf(() => part().avatarStack, {
      'avatarStackViewModel': (r) => h(AvatarStack, {data: r.data, isOverlay: props.isOverlay, useMediumText: props.useMediumText,
        hideAvatar: props.hideAvatar, className: 'ytlContentMetadataViewModelAvatarStack'}),
      'badgeViewModel': (r) => h(BadgeViewModel, {data: r.data}),
    }),
    cond(() => part().leadingIcon, () => {
      const color = leadingColor();
      return h(IconByName, {
        className: 'ytlContentMetadataViewModelLeadingIcon',
        icon: () => part().leadingIcon.name,
        size: () => part().leadingIcon.width,
        ariaLabel: () => part().leadingIcon.accessibilityLabel,
        style: styles({color, 'margin-inline-end': leadingMargin}),
      });
    }),
    cond(() => part().text, () => h(PartTextWithTooltip, {
      metadataPart: part, maxLines, isLastPart: props.isLastPart, forceSmallLayout: props.forceSmallLayout,
    })),
    cond(() => part().icon, () => cond(() => part().icon.ytIcon, () => h(Image, {
      data: () => part().icon.ytIcon,
      imageClassName: 'ytlContentMetadataViewModelIcon',
      alt: () => part().icon.accessibilityLabel || '',
      style: styles({'margin-inline-end': iconMargin}),
    }), () => cond(() => part().icon.name, () => h(IconByName, {
      className: 'ytlContentMetadataViewModelIcon',
      icon: () => part().icon.name,
      size: () => part().icon.width,
      ariaLabel: () => part().icon.accessibilityLabel,
      style: styles({'margin-inline-end': iconMargin}),
    })))),
  ];
}, 'hc');

/** One row of content metadata (`H1z`): its badges and its parts between delimiters. */
const MetadataRow = defineComponent((props) => {
  const row = /** @type {function(): !Object} */ (props.metadataRow);
  const extension = () => {
    const e = props.extensions && props.extensions();
    return e ? e.lockupMetadata : undefined;
  };
  const isByline = () => row().contentType === 'METADATA_ROW_CONTENT_TYPE_BYLINE';
  const hideAvatar = () => !!(extension() && extension().byline && extension().byline.hideAvatar) && isByline();
  const maxLines = () => {
    if (!props.isInline()) {
      const lines = row().maxLines != null ? row().maxLines : 0;
      return lines > 0 ? lines : undefined;
    }
    return undefined;
  };
  const hasMaxLines = () => maxLines() !== undefined;
  const parts = () => row().metadataParts || [];
  const hover = (e) => {
    const command = innertubeOf(((rendererField(row().rendererContext, COMMAND_CONTEXT) || {})).onHoverStart);
    if (command) fireCommand(/** @type {!Element} */ (e.currentTarget), command);
  };
  const hoverable = () => !!innertubeOf(((rendererField(row().rendererContext, COMMAND_CONTEXT) || {})).onHoverStart);
  const onKey = (/** !KeyboardEvent */ e) => {
    if ((e.key === 'Enter' || e.key === ' ') && /** @type {!Element} */ (e.target).tagName !== 'A' && /** @type {!Element} */ (e.target).tagName !== 'BUTTON') hover(e);
  };
  return h('div', {
    class: classes('ytlContentMetadataViewModelMetadataRow', () => maxLinesClass(maxLines()), {
      'ytlContentMetadataViewModelMetadataRowMetadataRowInline': props.isInline,
      'ytlContentMetadataViewModelMetadataRowMetadataRowPadding': () => !!(extension() && extension().byline && extension().byline.addPadding) && isByline(),
      'ytlContentMetadataViewModelMetadataRowMetadataRowWrap': () => {
        if (hasMaxLines()) return false;
        if (extension() && row().badges && !row().metadataParts) return true;
        const list = row().metadataParts;
        return flag('wrap_content_metadata_to_second_line') && !!list && list.length > 1 && (row().contentType === undefined || isByline());
      },
      'ytlContentMetadataViewModelMetadataRowMetadataRowMaxLines': hasMaxLines,
    }),
    'aria-label': () => row().a11yLabel,
    role: () => (hoverable() ? 'button' : 'group'),
    tabindex: () => (hoverable() ? 0 : undefined),
    'aria-haspopup': () => (hoverable() ? 'dialog' : undefined),
    'on:mouseenter': hover,
    'on:mouseleave': (/** !Event */ e) => {
      const command = innertubeOf((rendererField(row().rendererContext, COMMAND_CONTEXT) || {}).onHoverEnd);
      if (command) fireCommand(/** @type {!Element} */ (e.currentTarget), command);
    },
    'on:keydown': onKey,
  },
  rendererOf(() => row().badges, {
    'badgeViewModel': (r) => h('div', {class: 'ytlContentMetadataViewModelBadge'},
        h(BadgeViewModel, {data: r.data, numBadgesInRow: () => (row().badges || []).length})),
  }),
  h(IndexEach, {of: parts, render: (part, i) => [
    h(MetadataPart, {
      metadataPart: part, isOverlay: props.isOverlay, useMediumText: props.useMediumText, hideAvatar,
      isLastPart: () => i === parts().length - 1, rowHasMaxLines: hasMaxLines, forceSmallLayout: props.forceSmallLayout,
    }),
    h(Delimiter, {delimiter: props.delimiter, max: () => parts().length, index: () => i, isStandalone: false,
      hideDelimiter: () => part().hideDelimiter}),
  ]}),
  cond(() => row().isSpacerRow && !props.isInline(), () => h('div', {class: 'ytlContentMetadataViewModelSpacer'})));
}, 'ic');

/** The content metadata (`d6K`): the rows of a lockup's metadata, with the interaction of their context. */
export const ContentMetadata = defineComponent((rawProps) => {
  const props = withDefaults(rawProps, {layout: 0, isOverlay: false, forceSmallLayout: false});
  const data = /** @type {function(): !Object} */ (props.data);
  const inline = () => props.layout() === 0;
  const rows = () => (data().metadataRows || []).filter((row) => {
    const lockup = props.extensions && props.extensions() ? props.extensions().lockupMetadata : undefined;
    const hideDescription = !!(lockup && lockup.description && lockup.description.hideDescription) && row.contentType === 'METADATA_ROW_CONTENT_TYPE_DESCRIPTION';
    const hideSpacer = !!(lockup && lockup.spacer && lockup.spacer.hideSpacer) && row.contentType === 'METADATA_ROW_CONTENT_TYPE_SPACER';
    return !(hideSpacer || hideDescription);
  });
  return h('ytl-content-metadata-view-model', {
    class: classes(props.className, 'ytlContentMetadataViewModelHost', {
      'ytlContentMetadataViewModelInline': inline,
      'ytlContentMetadataViewModelTappable': () => !!contextCommandOf(data().rendererContext),
      'ytlContentMetadataViewModelMediumText': props.useMediumText,
      'ytlContentMetadataViewModelCenter': () => props.layout() === 2,
    }),
    ref: useCommandContext(() => data().rendererContext),
  }, h(IndexEach, {of: rows, render: (row, i) => [
    h(MetadataRow, {
      metadataRow: row, isInline: inline, delimiter: () => data().delimiter, isOverlay: props.isOverlay,
      useMediumText: props.useMediumText, extensions: props.extensions, forceSmallLayout: props.forceSmallLayout,
    }),
    cond(() => inline() && !row().isSpacerRow, () => h(Delimiter, {delimiter: () => data().delimiter, max: () => rows().length, index: () => i,
      isStandalone: true})),
  ]}));
}, 'dc');

/** The avatar of a lockup's metadata (`Wh`): a renderer switch with a wrapper div. */
const AvatarSlot = defineComponent((props) => {
  const lockupStyle = () => (props.lockupStyle && props.lockupStyle()) || {};
  const overrides = () => (lockupStyle().miniAvatarInByline ? {size: 'tiny'} : undefined);
  return rendererOf(() => props.data().image, {
    'avatarStackViewModel': (r) => h(AvatarStack, {data: r.data, overrides: () => ({layoutType: 'AVATAR_STACK_LAYOUT_CLUSTER'})}),
    'avatarViewModel': (r) => h(AvatarViewModel, {data: r.data, avatarOverrides: overrides}),
    'decoratedAvatarViewModel': (r) => h(DecoratedAvatar, {data: r.data, avatarOverrides: overrides}),
  }, (render) => h('div', {class: 'ytlLockupMetadataViewModelAvatar'}, render()));
}, 'Wh');

/**
 * The colour of a lockup's text under the focus effect, else the colour of its token.
 * @param {?Object|undefined} style
 * @param {boolean} hovered
 * @param {boolean} dark
 * @param {string|undefined} fallback
 * @param {string} field
 * @return {string|undefined}
 */
function textColor(style, hovered, dark, fallback, field) {
  const effect = style && style.onFocusEffect && style.onFocusEffect[field];
  if (!(effect && hovered)) return fallback;
  const argb = dark ? effect.darkTheme : effect.lightTheme;
  return argb ? `#${(argb >>> 0).toString(16).padStart(8, '0')}` : undefined;
}

/** The title (`qpF`): a heading with the lockup's command link and the title text. */
const Title = defineComponent((props) => {
  const dark = /** @type {!DarkTheme} */ (rootInjector.resolve(DarkTheme));
  const color = useColorToken(() => props.data().titleColorToken);
  const typography = useTypographyToken(() => props.data().titleTypographyToken, () => 1);
  return h('h3', {
    class: 'ytlLockupMetadataViewModelHeadingReset',
    title: () => (props.data().title || {}).content,
    'aria-label': () => (props.data().title || {}).content,
  }, cond(() => props.data().title, () => h(CommandLink, {
    command: () => props.lockupCommand && props.lockupCommand(),
    className: 'ytlLockupMetadataViewModelTitle',
    style: styles({color: () => textColor(props.lockupStyle && props.lockupStyle(), !!(props.hovered && props.hovered()), dark.isDark(), color(), 'textPrimaryColor')}, typography),
    ariaLabel: () => props.lockupAccessibilityLabel && props.lockupAccessibilityLabel(),
  }, h(AttributedString, {text: () => props.data().title, userInput: true}))));
}, 'Xh');

/** The metadata line (`Yh`): the content metadata under a renderer switch. */
const MetadataLine = defineComponent((props) => {
  const dark = /** @type {!DarkTheme} */ (rootInjector.resolve(DarkTheme));
  const color = useColorToken(() => props.data().metadataColorToken);
  const typography = useTypographyToken(() => props.data().metadataTypographyToken, () => 1);
  const lockupStyle = () => (props.lockupStyle && props.lockupStyle()) || {};
  return h('div', {
    class: 'ytlLockupMetadataViewModelMetadata',
    style: styles({color: () => textColor(props.lockupStyle && props.lockupStyle(), !!(props.hovered && props.hovered()), dark.isDark(), color(), 'textSecondaryColor')}, typography),
  }, rendererOf(() => props.data().metadata, {
    'contentMetadataViewModel': (r) => h(ContentMetadata, {
      data: r.data,
      layout: () => (props.layout && props.layout() != null ? props.layout() : 1),
      useMediumText: () => lockupStyle().typographyBump || lockupStyle().useRichGridLegacyTypography,
      extensions: () => ({lockupMetadata: {
        byline: {hideAvatar: lockupStyle().arrangement === 0, addPadding: lockupStyle().arrangement === 1},
        description: {hideDescription: !!lockupStyle().compactMetadata},
        spacer: {hideSpacer: !!lockupStyle().compactMetadata},
      }}),
    }),
  }));
}, 'Yh');

/** The attribution line (`attributionViewModel`). */
export const AttributionViewModel = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  return h('ytl-attribution-view-model', {class: classes('ytlAttributionViewModelHost ytlAttributionViewModelMediumText',
    () => unwrap(props.className) || '')}, ' ',
  h('span', {class: 'ytlAttributionViewModelAttributionText'}, ' ',
    h('span', null, h(AttributedString, {text: () => vm().text, noWrap: true, linkInheritColor: true}))),
  cond(() => !!vm().suffix, () => h('span', {class: 'ytlAttributionViewModelSuffix'}, h(AttributedString, {text: () => vm().suffix}))), ' ');
}, 'attribution-view-model');

/** The attribution (`Zh`): a renderer switch over the attribution view model. */
const Attribution = defineComponent((props) => rendererOf(() => props.data().attribution, {
  'attributionViewModel': (r) => h('div', {class: 'ytlLockupMetadataViewModelAttribution'}, h(AttributionViewModel, {data: r.data})),
}), 'Zh');

/** The action bar (`$h`): a `cond` and a renderer switch over the bar's button. */
const ActionBar = defineComponent((props) => cond(() => props.data().actionBar, () => h('div', {class: 'ytlLockupMetadataViewModelActionBar'},
    rendererOf(() => props.data().actionBar, {
      'buttonViewModel': (r) => h(ButtonViewModel, {data: r.data, buttonOverrides: () => {
        const s = props.lockupStyle && props.lockupStyle();
        return s && s.isOverlay ? {style: 'overlay'} : undefined;
      }}),
    }, (render) => h('div', {class: 'ytlLockupMetadataViewModelActionButton'}, render())))), '$h');

/** The menu button (`ai`). */
const MenuButton = defineComponent((props) => {
  const lockupStyle = () => (props.lockupStyle && props.lockupStyle()) || {};
  return h('div', {
    class: classes({
      'ytlLockupMetadataViewModelMenuButton': () => !lockupStyle().enableUniversalEnvelope,
      'ytlLockupMetadataViewModelEnvelopeMenuButton': () => lockupStyle().enableUniversalEnvelope,
      'ytlLockupMetadataViewModelVisible': () => (props.hovered && props.hovered()) || lockupStyle().miniOverflowInByline,
      'ytlLockupMetadataViewModelBottomRight': () => lockupStyle().moveLockupOverflowMenuToBottomRight,
      'ytlLockupMetadataViewModelShowMenuButtonOnHover': () => lockupStyle().showMenuButtonOnHover,
    }),
  }, rendererOf(() => props.data().menuButton, {
    'buttonViewModel': (r) => h(ButtonViewModel, {data: r.data, buttonOverrides: () => {
      const s = lockupStyle();
      if (s.isOverlay || s.miniOverflowInByline) return Object.assign({}, s.isOverlay ? {style: 'overlay'} : {}, s.miniOverflowInByline ? {size: 'XS'} : {});
      return undefined;
    }}),
  }));
}, 'ai');

/**
 * The class of the metadata host by lockup arrangement.
 * @param {?Object|undefined} style
 * @return {string}
 */
function arrangementClass(style) {
  if (style && style.isOverlay) return 'ytlLockupMetadataViewModelOverlay';
  return style && style.arrangement === 1 ? 'ytlLockupMetadataViewModelHorizontal' : 'ytlLockupMetadataViewModelVertical';
}

/**
 * @param {?Object|undefined} style
 * @return {string|undefined}
 */
function titleLinesClass(style) {
  switch (style && style.titleMaxLines) {
    case 1:
      return 'ytlLockupMetadataViewModelTitleMaxLines1';
    case 3:
      return 'ytlLockupMetadataViewModelTitleMaxLines3';
    default:
      return undefined;
  }
}

/**
 * @param {?Object|undefined} style
 * @return {string}
 */
function sizeClass(style) {
  if (style && style.isTiny) return 'ytlLockupMetadataViewModelTiny';
  switch (style && style.sizing) {
    case 'MINI':
    case 'EXTRA_COMPACT':
    case 'COMPACT':
      return 'ytlLockupMetadataViewModelCompact';
    default:
      return 'ytlLockupMetadataViewModelStandard';
  }
}

/** The lockup metadata (`J5B`). */
export const LockupMetadata = defineComponent((props) => {
  const style = () => (props.lockupStyle && props.lockupStyle()) || undefined;
  const flagOf = (name) => () => !!(style() && style()[name]);
  const miniAvatar = flagOf('miniAvatarInByline');
  const miniOverflow = flagOf('miniOverflowInByline');
  const own = Object.assign({}, props);
  return h('ytl-lockup-metadata-view-model', {
    class: classes('ytlLockupMetadataViewModelHost', () => arrangementClass(style()), () => titleLinesClass(style()), () => sizeClass(style()), {
      'ytlLockupMetadataViewModelOverlay': flagOf('isOverlay'),
      'ytlLockupMetadataViewModelThumbnailOverlay': () => !!(style() && style().metadataOnThumbnail) && flag('enable_ai_search_web_m1_features'),
      'ytlLockupMetadataViewModelCard': flagOf('isCard'),
      'ytlLockupMetadataViewModelCentered': flagOf('isCentered'),
      'ytlLockupMetadataViewModelTypographyBump': flagOf('typographyBump'),
      'ytlLockupMetadataViewModelLegacyTypography': flagOf('useLegacyTypography'),
      'ytlLockupMetadataViewModelRichGridLegacyTypography': flagOf('useRichGridLegacyTypography'),
      'ytlLockupMetadataViewModelCenteredColumn': flagOf('isCenteredMetadata'),
      'ytlLockupMetadataViewModelMoveLockupOverflowMenuToBottomRight': flagOf('moveLockupOverflowMenuToBottomRight'),
      'ytlLockupMetadataViewModelHasMenuButton': () => props.data().menuButton,
      'ytlLockupMetadataViewModelMwebHomeTuningExp': () => (style() && style().singleLineTitle) || miniAvatar() || miniOverflow() ||
          (style() && style().reducedTypography),
      'ytlLockupMetadataViewModelHasMiniOverflowByline': miniOverflow,
      'ytlLockupMetadataViewModelHasMiniAvatarByline': miniAvatar,
      'ytlLockupMetadataViewModelReducedTypography': flagOf('reducedTypography'),
    }),
  }, h(Switch, {
    value: () => 0,
    cases: [
      [flagOf('enableUniversalEnvelope'), () => h('div', {class: 'ytlLockupMetadataViewModelEnvelope'},
        h(Title, own),
        h('div', {class: 'ytlLockupMetadataViewModelEnvelopeMetadata'}, h(AvatarSlot, own),
          h('div', {class: 'ytlLockupMetadataViewModelTextContainer ytlLockupMetadataViewModelEnvelopeTextContainer'}, h(MetadataLine, own)),
          h(ActionBar, own), h(MenuButton, own)))],
      [() => miniAvatar() || miniOverflow(), () => [
        cond(() => !miniAvatar(), () => h(AvatarSlot, own)),
        h('div', {class: 'ytlLockupMetadataViewModelTextContainer'}, h(Title, own),
          h('div', {class: 'ytlLockupMetadataViewModelBylineRow'}, cond(miniAvatar, () => h(AvatarSlot, own)), h(MetadataLine, own),
            cond(miniOverflow, () => h(MenuButton, own))), h(Attribution, own)),
        cond(() => !miniOverflow(), () => h(MenuButton, own))]],
    ],
    fallback: () => [h(AvatarSlot, own),
      h('div', {class: 'ytlLockupMetadataViewModelTextContainer'}, h(Title, own), h(MetadataLine, own), h(Attribution, own)),
      h(MenuButton, own)],
  }));
}, 'ytl-lockup-metadata-view-model (CoW)');

defineCoW('ytl-lockup-metadata-view-model', LockupMetadata, {props: {data: PropKind.SIGNAL, lockupStyle: PropKind.SIGNAL,
  lockupCommand: PropKind.SIGNAL, lockupAccessibilityLabel: PropKind.SIGNAL, hovered: PropKind.SIGNAL, layout: PropKind.SIGNAL}});
