/**
 * @fileoverview The JSX renderer of the view-model runtime. It instantiates
 * node descriptors into DOM with native DOM calls, so view-model content
 * gets no ShadyDOM scoping. Each element applies its static props through
 * the sanitizer contracts and collects its function-valued props into one
 * element effect that re-reads all of them. Function children are
 * reactive regions. Empty regions and false branches leave an empty text
 * node as a placeholder.
 */
import {traceSpan} from '../trace.js';
import {noteBreakdown, vmCounters} from './counters.js';
import {afterRenderEffect, asRender, getFrame, renderEffect, runReporting, runUntracked, setFrame} from './effect.js';
import {Fragment, VNode} from './jsx.js';
import {createOwner, createPolySiOwner, disposeOwner, getOwner, onCleanup, runWithOwner} from './owner.js';
import {flag} from '../flags.js';
import {sanitizeAttribute} from './sanitize.js';

export {renderEffect, afterRenderEffect};

const SVG_NS = 'http://www.w3.org/2000/svg';
const XLINK_NS = 'http://www.w3.org/1999/xlink';
const XML_NS = 'http://www.w3.org/XML/1998/namespace';

/** Marks elements created by the JSX renderer. */
export const WIZ_ELEMENT = Symbol('Pc');
const DEBUG_NAME = Symbol('debugName');
const STYLE_KEYS = Symbol('styleKeys');
const STYLE_DISPOSERS = Symbol('styleDisposers');

/** `enableAttributeSanitization` of the runtime toggles. */
const SANITIZE_ATTRIBUTES = true;

/** Attributes that are present or absent. */
const BOOLEAN_ATTRIBUTES = new Set(['allowfullscreen', 'async', 'autofocus', 'autoplay', 'checked', 'controls', 'default',
  'defer', 'disabled', 'formnovalidate', 'hidden', 'inert', 'ismap', 'itemscope', 'loop', 'multiple', 'muted',
  'nomodule', 'novalidate', 'open', 'playsinline', 'readonly', 'required', 'reversed', 'selected']);

/** Attributes whose boolean values are written as `"true"` or `"false"`. */
const ENUMERATED_BOOLEANS = new Set(['aria-atomic', 'aria-busy', 'aria-checked', 'aria-disabled', 'aria-expanded',
  'aria-hidden', 'aria-modal', 'aria-multiline', 'aria-multiselectable', 'aria-pressed', 'aria-readonly',
  'aria-required', 'aria-selected', 'contenteditable', 'draggable', 'spellcheck']);

/** Keys that are assigned as properties. */
const PROPERTY_KEYS = new Set(['value', 'checked', 'indeterminate', 'muted', 'textContent', 'innerText']);

/** @type {?Element} The CoW host whose component is rendering. */
let rootHost = null;

/** @type {function(!Element)} */
let elementCreatedHook = (el) => {};

/** @type {function(!Element, !Object)} */
let componentLoggingHook = (el, props) => {};

/**
 * Makes the next JSX element with `host`'s tag reuse `host`.
 * @param {?Element} host
 * @return {?Element} The previous host.
 */
export function setRootHost(host) {
  const prev = rootHost;
  rootHost = host;
  return prev;
}

/**
 * Called for every element the renderer creates, after its props and
 * children (`AL8`).
 * @param {function(!Element)} fn
 */
export function setElementCreatedHook(fn) {
  elementCreatedHook = fn;
}

/**
 * Called after a component whose props have `data` rendered one element.
 * @param {function(!Element, !Object)} fn
 */
export function setComponentLoggingHook(fn) {
  componentLoggingHook = fn;
}

/** @param {!Node} node */
export function removeNode(node) {
  const parent = node.parentNode;
  if (parent) parent.removeChild(node);
}

/**
 * Instantiates a child into DOM nodes, appended to `out`.
 * @param {*} child
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
export function instantiate(child, ns, out) {
  if (child == null || child === false || child === true) return;
  if (typeof child === 'string' || typeof child === 'number') {
    out.push(document.createTextNode(String(child)));
  } else if (Array.isArray(child)) {
    for (let i = 0; i < child.length; i++) instantiate(child[i], ns, out);
  } else if (typeof child === 'function') {
    createRegion(/** @type {function(): *} */ (child), ns, out);
  } else if (child instanceof VNode) {
    const type = child.type;
    if (typeof type === 'function') {
      if (type.isControl) /** @type {?} */ (type)(child.props, ns, out);
      else callComponent(child, ns, out);
    } else if (type === Fragment) {
      instantiate(child.children, ns, out);
    } else {
      out.push(createElement(child, ns));
    }
  } else if (child instanceof Node) {
    out.push(child);
  }
}

/**
 * Calls a component with a component-stack frame, then the logging hook
 * when it rendered one element and its props have a truthy `data` (`pAy`).
 * Functions marked `isPlainComponent` are called without the component
 * wrapper (`_.YF`): no span and no prop thunks.
 * @param {!VNode} vnode
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
function callComponent(vnode, ns, out) {
  const type = /** @type {?} */ (vnode.type);
  const props = vnode.children.length ? Object.assign({}, vnode.props, {children: vnode.children}) : vnode.props;
  const prevFrame = setFrame({name: type.debugName || 'component', isReactive: false, parent: getFrame()});
  try {
    const start = out.length;
    if (type.isPlainComponent) {
      instantiate(type(props), ns, out);
    } else {
      const component = type.isWizComponent ? type : type.wizComponent || (type.wizComponent = defineComponent(type, type.name));
      component(props, ns, out);
    }
    const el = out.length - start === 1 ? out[start] : null;
    if (el instanceof HTMLElement && !flag('cow_logging_in_component_wrapper') &&
        ((props.data && !props.disableReactiveLogging) || el.getAttribute('client-ve-type'))) {
      componentLoggingHook(el, props);
    }
  } finally {
    setFrame(prevFrame);
  }
}

/**
 * Turns each value prop into a thunk, as the component boundary does.
 * @param {!Object} props
 * @return {!Object}
 */
function thunkProps(props) {
  const out = {};
  for (const key in props) {
    const value = props[key];
    out[key] = typeof value === 'function' || key === 'children' || key === 'ref' || value === undefined ? value : () => value;
  }
  return out;
}

/**
 * Wraps a component body (`_.YF`). Each call opens a sampled tracing span,
 * passes every value prop as a thunk, renders the returned nodes and names
 * the root element.
 * @param {function(!Object): *} body
 * @param {string} debugName
 * @return {function(!Object, ?string, !Array<!Node>)}
 */
export function defineComponent(body, debugName) {
  const component = (props, ns, out) => traceSpan('ytComponent', () => {
    vmCounters.renders++;
    noteBreakdown(component.debugName.endsWith('(CoW)') ? 'instances' : 'renders', getFrame());
    const start = out.length;
    instantiate(body(thunkProps(props)), ns, out);
    if (out.length > start) setDebugName(out[start], debugName);
  });
  component.debugName = debugName;
  component.isWizComponent = true;
  return component;
}

/**
 * @param {!Node} node
 * @param {string} debugName
 */
function setDebugName(node, debugName) {
  if (node.nodeType !== Node.ELEMENT_NODE) return;
  const el = /** @type {!Element} */ (node);
  el[DEBUG_NAME] = debugName || `${el.tagName.toLowerCase()}.${String(el.getAttribute('class') || '').split(' ').join('.')}`;
}

/**
 * Creates an element: the CoW host being rendered when the tag matches,
 * else a new element. Then props, the element effect, children and ref.
 * @param {!VNode} vnode
 * @param {?string} ns
 * @return {!Element}
 */
function createElement(vnode, ns) {
  const tag = /** @type {string} */ (vnode.type);
  const childNs = tag === 'svg' ? SVG_NS : ns;
  let el;
  if (rootHost && rootHost.localName === tag) {
    el = rootHost;
    rootHost = null;
  } else {
    el = childNs ? document.createElementNS(childNs, tag) : document.createElement(tag);
  }
  el[WIZ_ELEMENT] = true;
  vmCounters.elements++;
  const props = vnode.props;
  let ref = null;
  for (const key in props) {
    if (key === 'ref') ref = props[key];
    else applyProp(el, key, props[key]);
  }
  if (el._signalProps) createElementEffect(el, props);
  if (vnode.children.length) {
    const nodes = [];
    instantiate(vnode.children, tag === 'foreignObject' ? null : childNs, nodes);
    for (let i = 0; i < nodes.length; i++) el.appendChild(nodes[i]);
  }
  if (ref) applyRef(el, ref);
  elementCreatedHook(el);
  return el;
}

/**
 * @param {!Element} el
 * @param {*} ref A function called with the element, or `{onRender, onUnmount}`.
 */
function applyRef(el, ref) {
  if (typeof ref === 'function') {
    ref(el);
    return;
  }
  if (ref.onRender) ref.onRender(el);
  if (ref.onUnmount) onCleanup(() => ref.onUnmount(el));
}

/**
 * Applies one prop (`nMF`). The keys of function values are collected as
 * signal props of the element effect, which calls this again with their
 * values.
 * @param {!Element} el
 * @param {string} key
 * @param {*} value
 */
export function applyProp(el, key, value) {
  if (key.charCodeAt(0) === 111 /* o */ && key.charCodeAt(2) === 58 /* : */ && key.charCodeAt(1) === 110 /* n */) {
    addHandler(el, key.slice(3), /** @type {function(!Event)} */ (value));
  } else if (typeof value === 'function') {
    if (!el._signalProps) {
      el._signalProps = [];
      el._signalValues = [];
    }
    el._signalProps.push(key);
  } else if (typeof value === 'boolean' && BOOLEAN_ATTRIBUTES.has(key)) {
    if (value) el.setAttribute(key, '');
    else el.removeAttribute(key);
  } else if (typeof value === 'boolean' && ENUMERATED_BOOLEANS.has(key)) {
    el.setAttribute(key, value ? 'true' : 'false');
  } else if (key.startsWith('data-') && typeof value === 'string') {
    el.setAttribute(key, sanitizeDataValue(value));
  } else if (key === 'style' && value && typeof value === 'object') {
    applyStyleObject(/** @type {!HTMLElement} */ (el), /** @type {!Object} */ (value));
  } else if (key.startsWith('prop:')) {
    el[key.slice(5)] = value;
  } else if (PROPERTY_KEYS.has(key)) {
    el[key] = value;
  } else {
    const v = SANITIZE_ATTRIBUTES ? sanitizeAttribute(el.localName, key, value) : value;
    setAttributeValue(el, key, v);
  }
}

/**
 * @param {string} value
 * @return {string}
 */
function sanitizeDataValue(value) {
  return value.indexOf('javascript:') === 0 ? '' : value;
}

/**
 * @param {!Element} el
 * @param {string} key
 * @param {*} value
 */
function setAttributeValue(el, key, value) {
  const ns = key.startsWith('xlink:') ? XLINK_NS : key.startsWith('xml:') ? XML_NS : null;
  if (value == null || value === false) {
    if (ns) el.removeAttributeNS(ns, key.slice(key.indexOf(':') + 1));
    else el.removeAttribute(key);
  } else if (ns) {
    el.setAttributeNS(ns, key, value === true ? '' : String(value));
  } else {
    el.setAttribute(key, value === true ? '' : String(value));
  }
}

/**
 * Wraps an event handler (`yxY`): it does nothing once the target is
 * disconnected or the owner disposed, runs untracked, and reports errors
 * with the component stack.
 * @param {function(!Event)} handler
 * @return {function(!Event)}
 */
export function wrapHandler(handler) {
  const owner = getOwner();
  const frame = getFrame();
  return (e) => {
    const target = /** @type {?Node} */ (e.currentTarget);
    if ((target && !target.isConnected) || (owner && owner.isDisposed)) return;
    runReporting(() => runUntracked(() => handler(e)), frame, 'handler');
  };
}

/**
 * @param {!Element} el
 * @param {string} type
 * @param {function(!Event)} handler
 */
function addHandler(el, type, handler) {
  const wrapped = wrapHandler(handler);
  const prop = 'on' + type;
  if (Object.prototype.hasOwnProperty.call(el, prop)) {
    el[prop] = wrapped;
    return;
  }
  el.addEventListener(type, wrapped);
  onCleanup(() => el.removeEventListener(type, wrapped));
}

/**
 * The element effect (`mly`): one per element with signal props, in the
 * current owner. It calls every signal prop and applies the ones whose
 * value differs from the last one. The last values start empty, so a prop
 * whose first value is `undefined` is not applied.
 * @param {!Element} el
 * @param {!Object} props
 */
function createElementEffect(el, props) {
  renderEffect(() => {
    const keys = el._signalProps;
    const values = el._signalValues;
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      const v = props[key]();
      if (values[i] !== v) {
        values[i] = v;
        applyProp(el, key, v);
      }
    }
  }, 'e3YVbb');
}

/**
 * A style object (`Qxx`): static keys are set at once; each function-valued
 * key gets its own owner and effect. The per-key disposers live in a map on
 * the element, which `_disposeEffects` clears.
 * @param {!HTMLElement} el
 * @param {!Object} styles
 */
function applyStyleObject(el, styles) {
  const hasOwner = !!getOwner();
  /** @type {?Map<string, !Object>} */
  let disposers = el[STYLE_DISPOSERS] || null;
  const prevKeys = /** @type {?Set<string>} */ (el[STYLE_KEYS]);
  if (prevKeys) {
    for (const k of prevKeys) {
      if (k in styles) continue;
      clearStyleKey(disposers, k);
      el.style.removeProperty(k);
    }
  }
  /** @type {!Set<string>} */
  const keys = new Set();
  for (const k in styles) {
    if (!Object.prototype.hasOwnProperty.call(styles, k)) continue;
    keys.add(k);
    const v = styles[k];
    if (typeof v === 'function' && hasOwner) {
      if (!disposers) {
        const map = disposers = new Map();
        el[STYLE_DISPOSERS] = map;
        addElementDisposer(el, () => {
          for (const owner of map.values()) disposeOwner(owner);
          map.clear();
        });
      }
      clearStyleKey(disposers, k);
      const owner = createOwner(getOwner());
      runWithOwner(owner, () => renderEffect(() => setStyle(el, k, v()), 'QDzHJe'));
      disposers.set(k, owner);
    } else {
      clearStyleKey(disposers, k);
      setStyle(el, k, v);
    }
  }
  el[STYLE_KEYS] = keys;
}

/**
 * @param {?Map<string, !Object>} disposers
 * @param {string} key
 */
function clearStyleKey(disposers, key) {
  const owner = disposers && disposers.get(key);
  if (!owner) return;
  disposeOwner(owner);
  disposers.delete(key);
}

/**
 * Chains a disposer onto the element's `_disposeEffects` (`DWj`).
 * @param {!Element} el
 * @param {function()} fn
 */
function addElementDisposer(el, fn) {
  const prev = el._disposeEffects;
  el._disposeEffects = prev ? () => {
    prev();
    fn();
  } : fn;
}

/**
 * @param {!HTMLElement} el
 * @param {string} key
 * @param {*} value
 */
function setStyle(el, key, value) {
  if (value == null || value === false || value === '') el.style.removeProperty(key);
  else el.style.setProperty(key, String(value));
}

/**
 * The nodes of a region in the DOM. An empty region holds one empty text
 * node. The region's effect places its first nodes when it is created;
 * `appendTo` then adds them to the output.
 */
export class Region {
  constructor() {
    /** @type {!Array<!Node>} */
    this.nodes = [];
  }

  /** @param {!Array<!Node>} out */
  appendTo(out) {
    if (!this.nodes.length) this.nodes = [document.createTextNode('')];
    for (let i = 0; i < this.nodes.length; i++) out.push(this.nodes[i]);
  }

  /**
   * Replaces the region's nodes with `next` (`zmK`/`Axu`): reused nodes stay,
   * new ones are inserted before the first old node, the rest removed.
   * @param {!Array<!Node>} next
   */
  place(next) {
    const old = this.nodes;
    if (!old.length) {
      this.nodes = next.length ? next : [document.createTextNode('')];
      return;
    }
    if (!next.length) {
      if (old.length === 1 && old[0].nodeType === Node.TEXT_NODE && !/** @type {!Text} */ (old[0]).data) return;
      next = [document.createTextNode('')];
    }
    const parent = old[0].parentNode;
    if (!parent) {
      this.nodes = next;
      return;
    }
    if (old.length === 1 && next.length === 1) {
      if (old[0] !== next[0]) parent.replaceChild(next[0], old[0]);
      this.nodes = next;
      return;
    }
    /** @type {!Map<!Node, number>} */
    const kept = new Map();
    for (let i = 0; i < next.length; i++) kept.set(next[i], i);
    let ref = old[old.length - 1].nextSibling;
    for (let i = next.length - 1; i >= 0; i--) {
      const n = next[i];
      if (n.parentNode !== parent || n.nextSibling !== ref) parent.insertBefore(n, ref);
      ref = n;
    }
    for (let i = 0; i < old.length; i++) {
      if (!kept.has(old[i]) && old[i].parentNode === parent) parent.removeChild(old[i]);
    }
    this.nodes = next;
  }
}

/**
 * A reactive region for a function child (`HOK`). A string or number
 * result updates the region's text node in place.
 * @param {function(): *} fn
 * @param {?string} ns
 * @param {!Array<!Node>} out
 */
function createRegion(fn, ns, out) {
  const region = new Region();
  renderEffect(() => {
    const value = fn();
    runUntracked(() => {
      const current = region.nodes;
      if ((typeof value === 'string' || typeof value === 'number') && current.length === 1 &&
          current[0].nodeType === Node.TEXT_NODE) {
        /** @type {!Text} */ (current[0]).data = String(value);
        return;
      }
      const nodes = [];
      instantiate(value, ns, nodes);
      region.place(nodes);
    });
  }, 'qmF2ne');
  region.appendTo(out);
}

/**
 * A render root (`vwx`): instantiates `child` in a new owner attached to
 * `parentOwner`, appends the nodes to `parent` when given, and returns the
 * nodes and a disposer. The outermost render flushes the effects queued
 * during it. With `rootCleanup`, a root without a parent owner gets a no-op
 * cleanup (`zGe`).
 * @param {*} child
 * @param {?Object} parentOwner
 * @param {?Node=} parent
 * @param {boolean=} rootCleanup
 * @return {{nodes: !Array<!Node>, owner: !Object, dispose: function()}}
 */
export function renderRoot(child, parentOwner, parent = null, rootCleanup = false) {
  const owner = createOwner(parentOwner);
  const nodes = [];
  runWithOwner(owner, () => {
    if (rootCleanup && !parentOwner) onCleanup(noop);
    runReporting(() => asRender(() => {
      instantiate(child, null, nodes);
      if (parent) {
        for (let i = 0; i < nodes.length; i++) parent.appendChild(nodes[i]);
      }
    }), getFrame(), 'render');
  });
  return {nodes, owner, dispose: () => disposeOwner(owner)};
}

function noop() {}

/**
 * Renders `child` into `parent` natively under a new root owner. The caller
 * removes the nodes after disposing.
 * @param {*} child
 * @param {!Node} parent
 * @param {?Object=} parentOwner
 * @return {{nodes: !Array<!Node>, owner: !Object, dispose: function()}}
 */
export function render(child, parent, parentOwner = null) {
  return renderRoot(child, parentOwner, parent);
}

/**
 * Renders a PolySi host's own component (the `p` component, `mpW`) in a
 * render root that is not linked to the current owner. The component runs
 * `setUp` (the controller creation) and registers the disconnect hook as a
 * cleanup; the host is not a JSX element, so it gets no props and no
 * element effect. The root owner becomes the host's `__owner`. Afterwards
 * the host's element fields are reset (`Oi4`).
 * @param {!HTMLElement} host
 * @param {function()} setUp
 */
export function renderPolySiHost(host, setUp) {
  vmCounters.polysiRenders++;
  const owner = createPolySiOwner();
  const hadOwner = !!getOwner();
  const prevFrame = setFrame({name: host.localName, isReactive: false, parent: null});
  try {
    runWithOwner(owner, () => {
      if (!hadOwner) onCleanup(noop);
      asRender(() => traceSpan('ytComponent', () => {
        setUp();
        onCleanup(() => {
          if (!host.lifecycleIsConnected) return;
          host.lifecycleIsConnected = false;
          const ctrl = /** @type {?} */ (host).polymerController;
          if (ctrl && ctrl.disconnectedCallback) ctrl.disconnectedCallback();
        });
        host.__owner = owner;
      }));
    });
  } finally {
    setFrame(prevFrame);
  }
  resetElementFields(host);
}

/**
 * Resets the fields the renderer keeps on an element (`Oi4`).
 * @param {!Element} el
 */
export function resetElementFields(el) {
  Object.assign(el, {_disposeEffects: undefined, _signalProps: undefined, _signalValues: undefined});
}
