/**
 * @fileoverview The timer-driven and per-request logging producers, shaped
 * like YouTube's:
 * - service-level indicators (SLIs): start and end records per network
 *   request and navigation, merged by dimensions and sent as one
 *   `sliEventBatch` every 30 s or after 100 records;
 * - streamz counters: per-metric cells, sent as `streamzIncremented`
 *   events (one per metric) every 30 s or after 100 increments;
 * - latency actions (CSI): `latencyActionInfo` events, at most 5 per key
 *   and action;
 * - the foreground heartbeat: one `foregroundHeartbeat` at startup and one
 *   every 30 s while the page is visible.
 * Timers here are not tracked by the scheduler: the benchmark does not wait
 * for them.
 */
import {flag, flagNumber, getConfig} from '../framework/flags.js';
import {currentScreen, logEvent} from './logging.js';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'.split('');

/**
 * A random id of `n` characters.
 * @param {number} n
 * @return {string}
 */
function randomId(n) {
  const out = [];
  for (let i = 0; i < n; i++) out[i] = ALPHABET[0 | Math.random() * ALPHABET.length];
  return out.join('');
}

/** A repeating timer that can be started and stopped. */
class IntervalTimer {
  /**
   * @param {number} ms
   * @param {function()} fn
   */
  constructor(ms, fn) {
    this.ms = ms;
    this.fn = fn;
    this.enabled = false;
    this.id = 0;
  }

  start() {
    this.enabled = true;
    this.id = setInterval(this.fn, this.ms);
  }

  stop() {
    this.enabled = false;
    clearInterval(this.id);
  }
}

// ---------------------------------------------------------------------------
// SLIs

/**
 * The sorted `[path, value]` pairs of a dimensions object.
 * @param {!Object} dims
 * @param {string=} prefix
 * @return {!Array<!Array<*>>}
 */
function flattenDimensions(dims, prefix = '') {
  const out = [];
  for (const k in dims) {
    if (!dims.hasOwnProperty(k)) continue;
    const path = prefix !== '' ? `${prefix}.${k}` : k;
    if (typeof dims[k] === 'object') out.push(...flattenDimensions(dims[k], path));
    else out.push([path, dims[k]]);
  }
  out.sort();
  return out;
}

/** SLI events by dimensions key. */
class SliRegister {
  constructor() {
    /** @const {!Map<string, !Object>} */
    this.events = new Map();
  }

  /** @return {!Array<!Object>} */
  values() {
    const out = [];
    for (const e of this.events.values()) out.push(e);
    return out;
  }

  clear() {
    this.events.clear();
  }
}

/** Collects SLI records and sends them in batches. */
class SliLogger {
  constructor() {
    this.loggedEventRegister = new SliRegister();
    this.unloggedEventRegister = new SliRegister();
    this.eventsCount = 0;
    this.flushTimer = new IntervalTimer(30000, () => this.flush());
  }

  /** @param {{dimensions: !Object, records: !Array<!Object>}} event */
  add(event) {
    event.dimensions = event.dimensions || {};
    event.dimensions.csn = currentScreen() || '';
    const key = flattenDimensions(event.dimensions).join(';');
    const reg = this.loggedEventRegister;
    if (reg.events.has(key)) reg.events.get(key).records.push(...event.records);
    else reg.events.set(key, event);
    if (!this.flushTimer.enabled) this.flushTimer.start();
    this.eventsCount++;
    if (this.eventsCount >= 100) this.flush();
  }

  flush() {
    if (!this.eventsCount) return;
    const batch = {loggedEvents: this.loggedEventRegister.values(), unloggedEvents: this.unloggedEventRegister.values()};
    if (flag('export_player_version_to_ytconfig')) {
      const version = /** @type {?string} */ (getConfig('PLAYER_CLIENT_VERSION'));
      let v = '';
      if (version) {
        v = version.split('-')[0].replace(/\./g, '');
        if (isNaN(Number(v))) v = '0';
      }
      batch.dimensions = {playerClientVersion: v, playerCanaryState: 'CLIENT_CANARY_STATE_UNKNOWN'};
    }
    if (flag('enable_client_sli_logging')) logEvent('sliEventBatch', batch);
    this.loggedEventRegister.clear();
    this.unloggedEventRegister.clear();
    this.eventsCount = 0;
    if (this.flushTimer.enabled) this.flushTimer.stop();
  }
}

/** @type {?SliLogger} */
let sliLogger = null;

/** @return {!SliLogger} */
function slis() {
  if (!sliLogger) sliLogger = new SliLogger();
  return sliLogger;
}

/** One service-level indicator; at most one is ongoing per name and id. */
class Sli {
  /**
   * @param {string} name
   * @param {string} sliId
   * @param {number} timeoutMs
   * @param {string} statusOnTimeout
   */
  constructor(name, sliId, timeoutMs, statusOnTimeout) {
    this.name = name;
    this.sliId = sliId;
    this.timeoutMs = timeoutMs;
    this.statusOnTimeout = statusOnTimeout;
    this.logSliId = '';
    this.timeoutHandle = -1;
    this.ongoing = false;
    this.dimensions = {};
  }

  /** @param {!Object=} dimensions */
  start(dimensions = {}) {
    if (this.ongoing) return;
    this.ongoing = true;
    this.dimensions = dimensions;
    this.logSliId = randomId(8);
    slis().add({dimensions: this.dimensions, records: [{name: this.name, state: 'SLI_STATE_START', sliId: this.logSliId}]});
    if (this.timeoutMs > 0) this.timeoutHandle = setTimeout(() => this.end(this.statusOnTimeout), this.timeoutMs);
  }

  /** @param {string} status */
  end(status) {
    if (!this.ongoing) return;
    if (this.timeoutMs > 0) clearTimeout(this.timeoutHandle);
    this.ongoing = false;
    sliRegistry.delete(`${this.name}_${this.sliId}`);
    slis().add({dimensions: this.dimensions, records: [{name: this.name, status: `SLI_STATUS_${status}`, state: 'SLI_STATE_END', sliId: this.logSliId}]});
  }
}

/** @type {!Map<string, !Sli>} */
const sliRegistry = new Map();

/**
 * @param {string} name
 * @param {string} id
 * @param {number} timeoutMs
 * @param {string} statusOnTimeout
 * @return {!Sli}
 */
function sli(name, id, timeoutMs, statusOnTimeout) {
  const key = `${name}_${id}`;
  let s = sliRegistry.get(key);
  if (!s) sliRegistry.set(key, s = new Sli(name, id, timeoutMs, statusOnTimeout));
  return s;
}

/**
 * The main-app dimensions of a request.
 * @param {string} pageType
 * @param {string} requestType
 * @return {!Object}
 */
function mainAppDimensions(pageType, requestType) {
  return {mainAppWeb: {pageType: `MAIN_APP_WEB_PAGE_TYPE_${pageType.toUpperCase()}`,
    requestType: `MAIN_APP_WEB_REQUEST_TYPE_${requestType.toUpperCase()}`, isShellLoad: !!getConfig('IS_SHELL_LOAD', false)}};
}

/**
 * Starts the network-request SLI.
 * @param {string} pageType
 * @param {string} requestType
 */
export function networkRequestStarted(pageType, requestType) {
  sli('SLI_NAME_YOUTUBE_WEB_NETWORK_REQUEST', 'NETWORK_REQUEST', 120000, 'TIMEOUT').start(mainAppDimensions(pageType, requestType));
}

/** @param {boolean} ok */
export function networkRequestFinished(ok) {
  sli('SLI_NAME_YOUTUBE_WEB_NETWORK_REQUEST', 'NETWORK_REQUEST', 120000, 'TIMEOUT').end(ok ? 'SUCCESS' : 'FAILURE');
}

/** @param {string} pageType */
export function navigationStarted(pageType) {
  sli('SLI_NAME_YOUTUBE_WEB_WARM_PAGE_NAVIGATION', 'WARM_PAGE_NAVIGATION', 120000, 'TIMEOUT').start(mainAppDimensions(pageType, 'browse'));
}

export function navigationFinished() {
  sli('SLI_NAME_YOUTUBE_WEB_WARM_PAGE_NAVIGATION', 'WARM_PAGE_NAVIGATION', 120000, 'TIMEOUT').end('SUCCESS');
}

// ---------------------------------------------------------------------------
// Streamz

/** A counter metric with one cell per field combination. */
class CounterMetric {
  /**
   * @param {string} name
   * @param {!Array<{name: string, type: string}>} fields
   */
  constructor(name, fields) {
    this.metricName = name;
    this.fields = fields;
    /** @const {!Map<string, number>} */
    this.cellMap = new Map();
  }

  /**
   * @param {number} by
   * @param {...*} values
   */
  incrementBy(by, ...values) {
    const key = values.join(',');
    this.cellMap.set(key, (this.cellMap.get(key) || 0) + by);
  }

  clear() {
    this.cellMap.clear();
  }
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/**
 * Base64 of a byte array.
 * @param {!Array<number>} bytes
 * @return {string}
 */
function base64(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
    out += B64[n >> 18 & 63] + B64[n >> 12 & 63] + (i + 1 < bytes.length ? B64[n >> 6 & 63] : '=') + (i + 2 < bytes.length ? B64[n & 63] : '=');
  }
  return out;
}

/**
 * @param {!Array<number>} out
 * @param {number} field
 * @param {string} s
 */
function writeString(out, field, s) {
  out.push(field << 3 | 2, s.length & 127);
  for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 255);
}

/**
 * Serializes a metric's increments as a binary message.
 * @param {!CounterMetric} metric
 * @return {!Array<number>}
 */
function serializeIncrements(metric) {
  const out = [];
  writeString(out, 1, metric.metricName);
  for (const f of metric.fields) writeString(out, 3, f.name);
  for (const [key, value] of metric.cellMap) {
    const cell = [];
    for (const v of key.split(',')) writeString(cell, 1, v);
    cell.push(2 << 3, value & 127);
    out.push(4 << 3 | 2, cell.length & 127, ...cell);
  }
  writeString(out, 2, 'youtube_web');
  return out;
}

/** The streamz registry: metrics, flushed every 30 s or after 100 increments. */
class Streamz {
  constructor() {
    this.invocationCount = 0;
    this.invocationLimit = flagNumber('client_streamz_web_flush_count', -1) !== -1 ? flagNumber('client_streamz_web_flush_count') : 100;
    /** @const {!Map<string, !CounterMetric>} */
    this.metricMap = new Map();
    this.flushTimer = new IntervalTimer(30000, () => this.snapshotAndFlush());
  }

  /**
   * @param {string} name
   * @param {...{name: string, type: string}} fields
   */
  addNewCounter(name, ...fields) {
    if (!this.metricMap.has(name)) this.metricMap.set(name, new CounterMetric(name, fields));
  }

  /**
   * @param {string} name
   * @param {...*} values
   */
  incrementCounter(name, ...values) {
    const m = this.metricMap.get(name);
    if (!m) return;
    m.incrementBy(1, ...values);
    if (!this.flushTimer.enabled) this.flushTimer.start();
    this.invocationCount++;
    if (this.invocationCount >= this.invocationLimit) this.snapshotAndFlush();
  }

  snapshotAndFlush() {
    const metrics = [...this.metricMap.values()].filter((m) => m.cellMap.size);
    if (metrics.length && flag('enable_client_streamz_web')) {
      for (const m of metrics) logEvent('streamzIncremented', {serializedIncrementBatch: base64(serializeIncrements(m))});
    }
    for (const m of metrics) m.clear();
    this.invocationCount = 0;
    if (this.flushTimer.enabled) this.flushTimer.stop();
  }
}

/** @type {?Streamz} */
let streamz = null;

/** @return {!Streamz} */
export function streamzService() {
  if (!streamz) {
    streamz = new Streamz();
    streamz.addNewCounter('/client_streamz/youtube/web/response_signature', {name: 'check_status', type: 'string'});
    streamz.addNewCounter('/client_streamz/youtube/web/e_sig_log', {name: 'sig', type: 'string'}, {name: 'de', type: 'bool'});
    streamz.addNewCounter('/client_streamz/youtube/web/debug/browser_cookie_setting',
        {name: 'cookie_enabled', type: 'bool'}, {name: 'cookie_3p_enabled', type: 'bool'}, {name: 'browser', type: 'string'});
  }
  return streamz;
}

/**
 * Counts an InnerTube response by its signature check.
 * @param {string} status
 */
export function countResponse(status) {
  const s = streamzService();
  s.incrementCounter('/client_streamz/youtube/web/response_signature', status);
  s.incrementCounter('/client_streamz/youtube/web/e_sig_log', 'search', true);
}

// ---------------------------------------------------------------------------
// Latency actions

/** @type {!Object<string, {count: number, time: number}>} */
const usageStats = {};
let usageCleanup = 0;

/**
 * Whether `key` was logged more than 5 times recently.
 * @param {string} key
 * @return {boolean}
 */
function overLimit(key) {
  const s = usageStats[key] = usageStats[key] || {count: 0, time: 0};
  s.count++;
  s.time = performance.now();
  if (!usageCleanup) {
    usageCleanup = setTimeout(() => {
      const now = performance.now();
      for (const k in usageStats) if (usageStats[k] && now - usageStats[k].time > 60000) delete usageStats[k];
      usageCleanup = 0;
    }, 5000);
  }
  return s.count > 5;
}

/** @type {!Map<string, string>} */
const actionNonces = new Map();

/**
 * The client action nonce of an action, made on first use.
 * @param {string} action
 * @return {string}
 */
function actionNonce(action) {
  let n = actionNonces.get(action);
  if (!n) actionNonces.set(action, n = randomId(16));
  return n;
}

/**
 * Logs latency-action info.
 * @param {!Object} info
 * @param {string=} action
 */
export function latencyInfo(info, action = '') {
  if (flag('web_csi_action_sampling_enabled') && getConfig('CSI_ACTION_DISABLED', false)) return;
  const nonce = actionNonce(action);
  if (overLimit(`info_${Object.keys(info).join('')}_${nonce}`)) return;
  const payload = Object.assign({}, info);
  payload.clientActionNonce = nonce;
  logEvent('latencyActionInfo', payload);
}

const LATENCY_ACTIONS = {results: 'LATENCY_ACTION_RESULTS', browse: 'LATENCY_ACTION_BROWSE', watch: 'LATENCY_ACTION_WATCH'};

/**
 * Starts a latency action for a navigation: a new action nonce, then the
 * action type and the screen it starts on.
 * @param {string} action
 */
export function startLatencyAction(action) {
  actionNonces.set('', randomId(16));
  const info = {actionType: LATENCY_ACTIONS[action] || 'LATENCY_ACTION_UNKNOWN'};
  const csn = currentScreen();
  if (csn && csn !== 'UNDEFINED_CSN') info.clientScreenNonce = csn;
  latencyInfo(info);
}

/** A warm navigation's load type. */
export function markWarmLoad() {
  latencyInfo({loadType: 'warm'});
}

/** The screen a navigation created. */
export function markScreenCreated() {
  const csn = currentScreen();
  if (csn) latencyInfo({clientScreenNonce: csn});
}

// ---------------------------------------------------------------------------
// Foreground heartbeat

const documentNonce = randomId(16);
let heartbeatIndex = 0;
let lastHeartbeat = 0;
let lastTrigger = '';
const pageStart = Date.now();

/** @param {string} trigger */
function heartbeat(trigger) {
  if (trigger === 'FOREGROUND_HEARTBEAT_TRIGGER_ON_BACKGROUND' || trigger === 'FOREGROUND_HEARTBEAT_TRIGGER_ON_FOREGROUND') {
    if (lastTrigger === trigger) return;
    lastTrigger = trigger;
  }
  if (trigger === 'FOREGROUND_HEARTBEAT_TRIGGER_ON_INTERVAL' && document.visibilityState !== 'visible') return;
  const delta = lastHeartbeat ? Math.round(performance.now() - lastHeartbeat) : -1;
  logEvent('foregroundHeartbeat', {firstActivityMs: String(heartbeatIndex ? -1 : Math.max(Date.now() - pageStart, 0)),
    clientDocumentNonce: documentNonce, index: String(heartbeatIndex), lastEventDeltaMs: String(delta), trigger});
  heartbeatIndex++;
  lastHeartbeat = performance.now();
}

/** Starts the heartbeat: one event now, then one every 30 s. */
export function startHeartbeat() {
  heartbeat('FOREGROUND_HEARTBEAT_TRIGGER_ON_FOREGROUND');
  setInterval(() => heartbeat('FOREGROUND_HEARTBEAT_TRIGGER_ON_INTERVAL'), 30000);
  if (flag('log_heartbeat_with_lifecycles')) {
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden' && !flag('log_heartbeat_on_blur')) heartbeat('FOREGROUND_HEARTBEAT_TRIGGER_ON_BACKGROUND');
      else if (document.visibilityState === 'visible') heartbeat('FOREGROUND_HEARTBEAT_TRIGGER_ON_FOREGROUND');
    });
  }
}
