/**
 * @fileoverview Anchor configuration for a command: `href`, `rel` and
 * `target`. Links to other origins and endpoints marked `nofollow` get
 * `rel="nofollow"`. The origin check splits URLs with the Closure Library's
 * URI regexp, two to four times per link, as YouTube's does.
 */
import uriUtils from 'goog:goog.uri.utils';
import {endpointUrl, flattenCommand} from './endpoints.js';

const NOFOLLOW_KINDS = ['urlEndpoint', 'browseEndpoint', 'watchEndpoint', 'searchEndpoint'];

/**
 * @param {string} url
 * @return {?string}
 */
function hostOf(url) {
  return uriUtils.getDomain(url);
}

/**
 * @param {string} url
 * @return {?number}
 */
function portOf(url) {
  return Number(uriUtils.split(url)[uriUtils.ComponentIndex.PORT] || null) || null;
}

/**
 * Whether `url` has the page's origin. Relative URLs do.
 * @param {string} url
 * @return {boolean}
 */
export function isSameOrigin(url) {
  const here = window.location.href;
  const scheme = uriUtils.split(url)[uriUtils.ComponentIndex.SCHEME] || null;
  const host = hostOf(url);
  if (scheme && host) return uriUtils.haveSameDomain(url, here);
  if (host) return hostOf(here) === host && portOf(here) === portOf(url);
  return true;
}

/**
 * @param {?Object|undefined} command
 * @param {string=} defaultTarget
 * @return {{href: (string|undefined), rel: (string|undefined), target: (string|undefined)}}
 */
export function linkConfig(command, defaultTarget) {
  const config = {href: undefined, rel: undefined, target: undefined};
  if (!command) return config;
  const endpoint = flattenCommand(command)[0];
  const href = endpointUrl(endpoint);
  if (!href) return config;
  config.href = href;
  let nofollow = !isSameOrigin(href);
  for (const kind of NOFOLLOW_KINDS) {
    const e = endpoint[kind];
    if (e && e.nofollow) nofollow = true;
  }
  if (nofollow) config.rel = 'nofollow';
  const url = endpoint.urlEndpoint;
  config.target = url && url.target === 'TARGET_NEW_WINDOW' ? '_blank' : (defaultTarget === undefined ? '' : defaultTarget);
  return config;
}
