/**
 * @fileoverview The search results page: page element, two-column layout,
 * header with the chip bar, and the filter chips.
 */
import {Polymer} from '../../framework/polysi/register.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {hostDom} from '../../framework/host-dom.js';
import {IronResizableBehavior} from '@polymer/iron-resizable-behavior/iron-resizable-behavior.js';
import {registerRenderer} from '../../framework/registry.js';
import {stampRenderers} from '../../framework/stamper.js';
import {getAccessibilityLabel, getText} from '../../framework/text.js';
import {ComponentBehavior, RendererBehavior, RendererCoreBehavior, VisibilityObserverBehavior, VisualElementBehavior} from '../renderer-behavior.js';
import {YtRendererStamperBehavior} from '../renderer-stamper.js';
import {ActionHandlerBehavior} from '../item-behaviors.js';
import {ContinuationHandlerBehavior, GuideStateAwareBehavior} from '../container-behaviors.js';
import {Priority, cancel, schedule} from '../scheduler.js';
import {flag, flagValue} from '../../framework/flags.js';
import {innertubeContext, innertubeFetch} from '../network.js';
import {handleResponse} from '../response.js';
import {logClick} from '../logging.js';
import {template as searchTemplate} from '../../../gen/templates/ytl-search.js';
import {template as twoColumnTemplate} from '../../../gen/templates/ytl-two-column-search-results-renderer.js';
import {template as headerTemplate} from '../../../gen/templates/ytl-search-header-renderer.js';
import {template as secondaryTemplate} from '../../../gen/templates/ytl-secondary-search-container-renderer.js';
import {template as chipCloudTemplate} from '../../../gen/templates/ytl-chip-cloud-renderer.js';
import {template as chipTemplate} from '../../../gen/templates/ytl-chip-cloud-chip-renderer.js';

Polymer({
  _template: searchTemplate,
  is: 'ytl-search',
  properties: {
    data: Object,
    header_: Object,
    results_: Object,
    active: {type: Boolean, value: false, reflectToAttribute: true},
  },

  /**
   * Called by the page manager with the fetched page data.
   * @param {{response: !Object, url: string}} pageData
   */
  onYtPageDataFetched(pageData) {
    this.updatePageData(pageData);
  },

  /** @param {{response: !Object, url: string}} pageData */
  updatePageData(pageData) {
    this.pageData_ = pageData;
    this.performDataUpdate(() => this.loadPage_(pageData.response));
  },

  /** @param {function()} update */
  performDataUpdate(update) {
    this.fire('yt-page-data-will-update', {page: 'search'});
    update();
    this.fire('yt-page-data-updated', {page: 'search'});
  },

  /** @param {!Object} response */
  loadPage_(response) {
    this.data = response;
    const contents = response.contents || {};
    this.header_ = response.header ? response.header.searchHeaderRenderer || null : null;
    this.results_ = contents.twoColumnSearchResultsRenderer || null;
  },

  /** @param {!Array<!Object>} items */
  reloadResults(items) {
    const first = items[0] || {};
    if (first.twoColumnSearchResultsRenderer) {
      this.results_ = first.twoColumnSearchResultsRenderer;
    } else if (first.searchHeaderRenderer) {
      this.header_ = first.searchHeaderRenderer;
    }
  },
});

/** The narrowest window that shows the secondary search column. */
const SECONDARY_COLUMN_MIN_WIDTH = 1090;
const MASTHEAD_HEIGHT = 56;

Polymer({
  _template: twoColumnTemplate,
  is: 'ytl-two-column-search-results-renderer',
  behaviors: [YtRendererStamperBehavior, ComponentBehavior, VisibilityObserverBehavior, VisualElementBehavior, RendererCoreBehavior,
    GuideStateAwareBehavior, IronResizableBehavior],
  properties: {
    data: Object,
    active: Boolean,
    useBiggerThumbs: {type: Boolean, reflectToAttribute: true, value() {
      return flag('enable_desktop_search_bigger_thumbs');
    }},
    biggerThumbsStyle: {type: String, reflectToAttribute: true, value() {
      return String(flagValue('desktop_search_bigger_thumbs_style', ''));
    }},
    renderSecondarySearchContainer: Object,
    showSecondaryColumn: {type: Boolean, computed: 'computeShowSecondaryColumn(renderSecondarySearchContainer,data)'},
    isSearchFrictionPage: {type: Boolean, reflectToAttribute: true, computed: 'computeIsSearchFrictionPage(data)'},
    isSearch: Object,
    pageSubtype: {type: String, reflectToAttribute: true},
    visibleHeight: Object,
    contentAriaRole: {type: String, computed: '__compute__contentAriaRole(pageSubtype)'},
    contentAriaLabel: {type: String, computed: '__compute__contentAriaLabel(pageSubtype)'},
    contentAriaLive: {type: String, computed: '__compute__contentAriaLive(pageSubtype)'},
  },
  observers: [
    'activeChanged(active)',
    'persistentGuideChanged(guidePersistentAndVisible)',
    'dataChanged(data)',
  ],
  listeners: {
    'yt-retrieve-location': 'onYtRetrieveLocation_',
    'iron-resize': 'onIronResize',
  },

  initFields_() {
    this.renderSecondarySearchContainer = false;
    this.isSearch = false;
    this.visibleHeight = this.computeVisibleHeight();
  },

  created() {
    this.boundStampIfFits = () => this.scheduleSecondaryStamp_();
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.primaryContents': {id: 'primary', mapping: {
        'sectionListRenderer': {component: 'ytl-section-list-renderer', properties: {'isSearch': 'isSearch',
          'containerHeight': 'visibleHeight', 'ariaRole': 'contentAriaRole', 'ariaLabel': 'contentAriaLabel', 'ariaLive': 'contentAriaLive'}},
      }},
      'data.continuations': {id: 'continuations', mapping: {'pageContinuationData': 'ytl-page-continuation'}},
    };
  },

  /** @return {boolean} */
  get isAiSearch() {
    return this.pageSubtype === 'ai-search';
  },

  /** @return {string|undefined} */
  __compute__contentAriaRole() {
    return this.isAiSearch ? 'log' : undefined;
  },

  /** @return {string|undefined} */
  __compute__contentAriaLabel() {
    return this.isAiSearch ? 'Search results' : undefined;
  },

  /** @return {string|undefined} */
  __compute__contentAriaLive() {
    return this.isAiSearch ? 'polite' : undefined;
  },

  /** @return {number} */
  computeVisibleHeight() {
    return window.innerHeight - MASTHEAD_HEIGHT;
  },

  /**
   * @param {boolean} render
   * @param {?Object} data
   * @return {boolean}
   */
  computeShowSecondaryColumn(render, data) {
    return !!(data && data.secondaryContents && render);
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  computeIsSearchFrictionPage(data) {
    const list = data && data.primaryContents && data.primaryContents.sectionListRenderer;
    const first = list && list.contents && list.contents[0];
    const items = (first && first.itemSectionRenderer && first.itemSectionRenderer.contents) || [];
    for (const item of items) {
      if (item.searchFrictionViewModel) return true;
    }
    return false;
  },

  /** @param {boolean} active */
  activeChanged(active) {
    if (active && !this.renderSecondarySearchContainer) {
      window.addEventListener('resize', this.boundStampIfFits);
      this.scheduleSecondaryStamp_();
    } else if (!active) {
      window.removeEventListener('resize', this.boundStampIfFits);
    }
  },

  /** @param {boolean} visible */
  persistentGuideChanged(visible) {
    this.scheduleSecondaryStamp_();
  },

  /** @param {?Object} data */
  dataChanged(data) {
    this.scheduleSecondaryStamp_();
  },

  /** @private */
  scheduleSecondaryStamp_() {
    if (this.secondaryStampJob) cancel(this.secondaryStampJob);
    this.secondaryStampJob = schedule(() => {
      this.secondaryStampJob = 0;
      this.stampSecondarySearchContainerIfFits();
    }, Priority.DEFERRED);
  },

  stampSecondarySearchContainerIfFits() {
    if (window.innerWidth < SECONDARY_COLUMN_MIN_WIDTH) return;
    this.renderSecondarySearchContainer = true;
    window.removeEventListener('resize', this.boundStampIfFits);
  },

  onIronResize() {
    this.visibleHeight = window.innerHeight - MASTHEAD_HEIGHT;
  },

  /** @param {!CustomEvent} e */
  onYtRetrieveLocation_(e) {
    if (e.detail) e.detail.location = `${location.pathname}${location.search}&pbj=1`;
  },
});
registerRenderer('twoColumnSearchResultsRenderer', 'ytl-two-column-search-results-renderer');

Polymer({
  _template: secondaryTemplate,
  is: 'ytl-secondary-search-container-renderer',
  behaviors: [YtRendererStamperBehavior, VisibilityObserverBehavior, VisualElementBehavior, RendererCoreBehavior, ComponentBehavior,
    ActionHandlerBehavior, ContinuationHandlerBehavior],
  properties: {
    data: Object,
    isSearch: {type: Boolean, value: false},
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.contents': {id: 'contents', mapping: {
        'universalWatchCardRenderer': {component: 'ytl-universal-watch-card-renderer', properties: {'isSearch': 'isSearch'}},
        'overviewAnswerViewModel': 'ytl-overview-answer-view-model',
        'overviewMessageViewModel': 'ytl-overview-message-view-model',
      }},
    };
  },

  /** @return {!Object<string, string>} */
  configureContinuationPathMap() {
    return {'yt-reload-continuation-items-command-body': 'contents'};
  },
});

Polymer({
  _template: headerTemplate,
  is: 'ytl-search-header-renderer',
  behaviors: [ComponentBehavior, VisibilityObserverBehavior, VisualElementBehavior, RendererCoreBehavior, YtRendererStamperBehavior],
  properties: {
    data: Object,
    hasChipBar: {type: Object, reflectToAttribute: true, computed: 'computeHasChipBar(data)'},
    hasBackButton: {type: Object, reflectToAttribute: true, computed: 'computeHasBackButton(data)'},
  },
  observers: ['dataChanged(data)'],

  initFields_() {
    this.hasChipBar = false;
    this.hasBackButton = false;
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.backButton': {id: 'back-button', mapping: {'buttonViewModel': 'ytl-scroll-button-view-model'}},
      'data.chipBar': {id: 'chip-bar', mapping: {'chipCloudRenderer': 'ytl-chip-cloud-renderer',
        'feedFilterChipBarRenderer': 'ytl-feed-filter-chip-bar-renderer'}},
      'data.searchFilterButton': {id: 'filter-button', mapping: {'buttonRenderer': 'ytl-button-renderer'}},
      'data.aboutTheseResultsButton': {id: 'about-these-results', mapping: {'buttonRenderer': 'ytl-button-renderer'}},
    };
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  computeHasChipBar(data) {
    return !!(data && data.chipBar);
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  computeHasBackButton(data) {
    return !!(data && data.backButton);
  },

  /** @param {?Object} data */
  dataChanged(data) {
    if (!data || !data.tagManagerId || this.tagManagerStarted) return;
    this.tagManagerStarted = true;
    this.fire('yt-start-tag-manager', {id: data.tagManagerId});
  },
});
registerRenderer('searchHeaderRenderer', 'ytl-search-header-renderer');

Polymer({
  _template: chipCloudTemplate,
  is: 'ytl-chip-cloud-renderer',
  behaviors: [RendererBehavior, IronResizableBehavior],
  observers: ['dataChanged(data)'],
  properties: {
    selected_: Number,
    showLeft_: {type: Boolean, value: false},
    showRight_: {type: Boolean, value: false},
  },
  listeners: {'iron-resize': 'updateArrows_', 'ytl-chip-selected': 'onChipSelected_'},

  /** @param {?Object} data */
  dataChanged(data) {
    const chips = (data && data.chips) || [];
    stampRenderers(this.$['chips'], chips);
    this.selected_ = Math.max(0, chips.findIndex(c => c.chipCloudChipRenderer && c.chipCloudChipRenderer.isSelected));
    this.updateArrows_();
  },

  updateArrows_() {
    const scroller = this.$['scroll-container'];
    const overflow = scroller.scrollWidth - scroller.offsetWidth;
    this.showLeft_ = scroller.scrollLeft > 0;
    this.showRight_ = overflow - scroller.scrollLeft > 1;
  },

  /** @param {!CustomEvent} e */
  onChipSelected_(e) {
    const chips = [...wrap(this.$['chips']).children];
    this.selected_ = chips.indexOf(/** @type {!Element} */ (e.detail.chip));
    for (const chip of chips) /** @type {?} */ (chip).selected = chip === e.detail.chip;
  },

  scrollLeft_() {
    this.$['scroll-container'].scrollLeft -= this.$['scroll-container'].offsetWidth / 2;
    this.updateArrows_();
  },

  scrollRight_() {
    this.$['scroll-container'].scrollLeft += this.$['scroll-container'].offsetWidth / 2;
    this.updateArrows_();
  },
});
registerRenderer('chipCloudRenderer', 'ytl-chip-cloud-renderer');

Polymer({
  is: 'iron-ytl-selector',
  properties: {
    selected: {type: Number, observer: 'selectedChanged_'},
  },

  /** @param {number} index */
  selectedChanged_(index) {
    const children = wrap(this).children;
    for (let i = 0; i < children.length; i++) children[i].classList.toggle('iron-selected', i === index);
  },
});

Polymer({
  _template: chipTemplate,
  is: 'ytl-chip-cloud-chip-renderer',
  behaviors: [RendererBehavior],
  observers: ['dataChanged(data)'],
  properties: {
    selected: {type: Boolean, value: false, reflectToAttribute: true},
    chipShapeData: {type: Object, computed: '__compute__chipShapeData(data, selected)'},
  },
  listeners: {click: 'onTap_'},
  hostAttributes: {'chip-style': 'STYLE_HOME_FILTER'},

  /** @param {?Object} data */
  dataChanged(data) {
    this.selected = !!(data && data.isSelected);
  },

  /**
   * The chip-shape config.
   * @param {?Object} data
   * @param {boolean} selected
   * @return {!Object}
   */
  __compute__chipShapeData(data, selected) {
    return {
      text: data ? getText(data.text) : '',
      selected: !!selected,
      chipStyle: data && data.style ? data.style.styleType : '',
      accessibilityLabel: data ? getAccessibilityLabel(data.accessibilityData) : '',
    };
  },

  /** @return {!Promise<void>} */
  async onTap_() {
    if (!this.data || this.selected) return;
    logClick(this.data.trackingParams || '');
    this.fire('ytl-chip-selected', {chip: this.hostElement});
    const endpoint = this.data.navigationEndpoint || {};
    const token = endpoint.continuationCommand ? endpoint.continuationCommand.token : getText(this.data.text);
    const text = await innertubeFetch('search-reload', '/youtubei/v1/search', {
      context: innertubeContext(this.data.trackingParams),
      continuation: token,
    });
    handleResponse(text, this.hostElement, 'search-reload');
  },
});
registerRenderer('chipCloudChipRenderer', 'ytl-chip-cloud-chip-renderer');
