/**
 * @fileoverview Maps InnerTube renderer keys (`videoRenderer`,
 * `gridShelfViewModel`, ...) to the custom elements that render them.
 */

/** @type {!Map<string, string>} */
const tags = new Map();

/**
 * @param {string} rendererKey
 * @param {string} tag
 */
export function registerRenderer(rendererKey, tag) {
  tags.set(rendererKey, tag);
}

/**
 * The first key of `item` that has a registered element, or null.
 * @param {?Object|undefined} item
 * @return {?string}
 */
export function rendererKeyOf(item) {
  if (!item) return null;
  for (const key in item) {
    if (tags.has(key)) return key;
  }
  return null;
}

/**
 * @param {string} rendererKey
 * @return {?string}
 */
export function tagFor(rendererKey) {
  return tags.get(rendererKey) || null;
}
