/**
 * @fileoverview Avatars: the avatar shape (`yt-avatar-shape`, `_.ZiT`), the
 * avatar view model (`_.F1E`), the decorated avatar (`_.ln`) and the avatar
 * stack (`_.Nw`), with the size helpers they share. The avatar shape has a
 * host with decoration and size wrappers, the image, and the live badge,
 * dot, overlay and badge-icon parts. The stack lays its avatars out in a
 * row or, for the cluster layout, on a square.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {cond} from '../../framework/vm/control.js';
import {afterRenderEffect, computed, runUntracked, signal, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {defineComponent} from '../../framework/vm/render.js';
import {AttributedString} from './attributed-string.js';
import {contextCommandOf, contextLabel, rendererOf, useCommandContext} from './hooks.js';
import {Image} from './image.js';
import {IconByName} from './primitives.js';
import {HoverOverlay} from './thumbnails.js';

/**
 * The avatar-shape size class.
 * @param {string} size
 * @param {boolean} button
 * @return {string}
 */
export function avatarShapeSizeClass(size, button) {
  const prefix = button ? 'ytlSpecAvatarShapeButton' : 'ytlSpecAvatarShapeSize';
  switch (size) {
    case 'tiny':
      return `${prefix}Tiny`;
    case 'extra-small':
      return `${prefix}ExtraSmall`;
    case 'small':
      return `${prefix}Small`;
    case 'large':
      return `${prefix}Large`;
    case 'extra-large':
      return `${prefix}ExtraLarge`;
    case '48':
      return `${prefix}48`;
    default:
      return `${prefix}Medium`;
  }
}

/**
 * The inner size class of an avatar shape.
 * @param {string} size
 * @return {string}
 */
export function avatarSizeClass(size) {
  switch (size) {
    case 'tiny':
      return 'ytlSpecAvatarShapeAvatarSizeTiny';
    case 'extra-small':
      return 'ytlSpecAvatarShapeAvatarSizeExtraSmall';
    case 'small':
      return 'ytlSpecAvatarShapeAvatarSizeSmall';
    case 'large':
      return 'ytlSpecAvatarShapeAvatarSizeLarge';
    default:
      return 'ytlSpecAvatarShapeAvatarSizeMedium';
  }
}

/**
 * Pixel width of an avatar size.
 * @param {string} size
 * @return {number}
 */
export function avatarPixels(size) {
  switch (size) {
    case 'tiny':
      return 16;
    case 'extra-small':
      return 24;
    case 'small':
      return 32;
    case '48':
      return 48;
    case 'large':
      return 56;
    case 'extra-large':
      return 72;
    default:
      return 40;
  }
}

/**
 * The size name of an avatar view model's size enum (`HW8`).
 * @param {string|undefined} size
 * @return {string}
 */
export function avatarViewModelSize(size) {
  switch (size) {
    case 'AVATAR_SIZE_XXS':
      return 'tiny';
    case 'AVATAR_SIZE_XS':
      return 'extra-small';
    case 'AVATAR_SIZE_S':
      return 'small';
    case 'AVATAR_SIZE_L':
      return 'large';
    case 'AVATAR_SIZE_XL':
      return 'extra-large';
    case 'AVATAR_SIZE_XXL':
      return 'extra-extra-large';
    case 'AVATAR_SIZE_XXXL':
      return 'giant';
    case 'AVATAR_SIZE_RESPONSIVE':
      return 'responsive';
    case 'AVATAR_SIZE_40':
      return '40';
    case 'AVATAR_SIZE_48':
      return '48';
    default:
      return 'medium';
  }
}

/**
 * The width in pixels of an avatar size enum (`dze`).
 * @param {string|undefined} size
 * @return {number}
 */
function avatarEnumPixels(size) {
  switch (size) {
    case 'AVATAR_SIZE_XXS':
      return 16;
    case 'AVATAR_SIZE_XS':
      return 24;
    case 'AVATAR_SIZE_S':
      return 32;
    case 'AVATAR_SIZE_M':
      return 36;
    case 'AVATAR_SIZE_40':
      return 40;
    case 'AVATAR_SIZE_48':
      return 48;
    case 'AVATAR_SIZE_L':
      return 56;
    case 'AVATAR_SIZE_XL':
      return 72;
    case 'AVATAR_SIZE_XXL':
      return 120;
    case 'AVATAR_SIZE_XXXL':
      return 160;
    default:
      return 0;
  }
}

/** The ref that listens for a keyboard or pointer tap while the element is tappable (`_.NKT`). */
function useTapListeners(tappable, listeners) {
  return (el) => {
    afterRenderEffect(() => {
      if (!tappable()) return;
      runUntracked(() => {
        for (const type in listeners) el.addEventListener(type, listeners[type]);
        onCleanup(() => {
          for (const type in listeners) el.removeEventListener(type, listeners[type]);
        });
      });
    }, 'bXZGfe');
  };
}

/** The decorations that give the avatar ring, border and live classes. */
function avatarDecorations(config) {
  return config.decorations || [];
}

/** The avatar shape (`ZiT`, `yt-avatar-shape`): host, decoration and size wrappers, the image and the optional badges. */
const AvatarShape = defineComponent((props) => {
  const config = /** @type {function(): !Object} */ (props.data);
  const [badgeFits, setBadgeFits] = signal(true, 'Vwwafb');
  const tappable = () => !!config().onTap;
  afterRenderEffect(() => {
    const c = config();
    requestAnimationFrame(() => setBadgeFits(!c.badgeText));
  }, 'PVZmVe');
  const has = (n) => avatarDecorations(config()).includes(n);
  const imageClasses = () => ({'ytlSpecAvatarShapeImage': true, 'ytlSpecAvatarShapeAdsApp': config().type === 1,
    'ytlSpecAvatarShapeInscribedSquare': config().type === 2});
  const sized = () => ['medium', '48', 'large', 'extra-large', 'extra-extra-large', 'giant'].includes(config().size);
  return h('ytl-avatar-shape', null,
    h('div', {
      ref: useTapListeners(tappable, {
        keydown: (/** !KeyboardEvent */ e) => {
          if (e.key === 'Enter') /** @type {!HTMLElement} */ (e.currentTarget).click();
        },
        click: (/** !Event */ e) => {
          const tap = config().onTap;
          if (tap) tap(e);
        },
      }),
      class: classes('ytlSpecAvatarShapeHost', 'ytlSpecAvatarShapeButton', () => avatarShapeSizeClass(config().size, false), {
        'ytlSpecAvatarShapeTappable': tappable,
      }, () => config().avatarButtonCustomClassName),
      'aria-label': () => (tappable() ? config().accessibilityText : ''),
      role: () => (tappable() ? 'button' : undefined),
      tabindex: () => (tappable() ? 0 : undefined),
    },
    h('div', {
      class: classes({
        'ytlSpecAvatarShapeLiveRing': () => has(0) && sized(),
        'ytlSpecAvatarShapeBackgroundBorder': () => has(3) && config().size !== 'tiny' && config().size !== 'extra-small',
        'ytlSpecAvatarShapeBackgroundBorderThin': () => has(3) && (config().size === 'tiny' || config().size === 'extra-small'),
        'ytlSpecAvatarShapeOnSelectBorder': () => has(4),
        'ytlSpecAvatarShapeWhiteBorder': () => has(5),
        'ytlSpecAvatarShapeIsOverlay': () => !!props.isOverlay && !!props.isOverlay(),
      }),
      style: () => (config().clusterLayoutConfig ? '' : undefined),
    },
    h('div', {class: classes(() => avatarSizeClass(config().size), {'ytlSpecAvatarShapeNoMargin': () => has(3),
      'ytlSpecAvatarShapeSquare': () => config().type === 2})},
    h(Image, {
      data: props.image,
      alt: () => (!tappable() && config().accessibilityText ? config().accessibilityText : ''),
      targetWidth: () => avatarPixels(config().size),
      targetHeight: () => avatarPixels(config().size),
      imageClassName: () => Object.keys(imageClasses()).filter((k) => imageClasses()[k]).join(' '),
      imageClassificationType: 'IMAGE_CLASSIFICATION_TYPE_AVATAR',
    }),
    cond(() => has(0) && sized(), () => h('div', {class: 'ytlSpecAvatarShapeLiveBadge'},
      cond(() => config().badgeText, () => h('div', {class: 'ytlSpecAvatarShapeLiveBadgeText'}, () => config().badgeText)),
      cond(badgeFits, () => h('div', {class: 'ytlSpecAvatarShapeLiveBadgeIcon'}, h(IconByName, {icon: () => props.iconType ? props.iconType() : 'LIVE',
        size: () => (config().size === 'extra-large' ? 16 : 13)}))))),
    cond(() => has(1) || (has(0) && !sized()), () => h('div', {class: classes({'ytlSpecAvatarShapeLiveDot': () => has(0), 'ytlSpecAvatarShapeNewContent': () => has(1)})})),
    cond(() => !!props.overlays, () => h('div', {class: classes('ytlSpecAvatarShapeImageOverlays', {'ytlSpecAvatarShapeImage': true,
      'ytlSpecAvatarShapeAdsApp': () => config().type === 1, 'ytlSpecAvatarShapeInscribedSquare': () => config().type === 2})},
    props.overlays && props.overlays())),
    cond(() => config().badgeIcon, () => h('div', {
      class: classes('ytlSpecAvatarShapeBadgeIconContainer', () => avatarShapeSizeClass(config().size, false).replace('Size', 'BadgeIconContainer')),
      style: styles({'background-color': () => config().badgeIconBorderColor}),
    }, h(IconByName, {icon: () => config().badgeIcon, className: 'ytlSpecAvatarShapeBadgeIcon', style: styles({color: () => config().badgeIconColor})})))))));
}, 'QD');

/** The overlays of a decorated avatar (`i1F`): a renderer switch. */
const AvatarOverlays = defineComponent((props) => rendererOf(() => (props.data() || {}).overlays, {
  'thumbnailHoverOverlayViewModel': (r) => h(HoverOverlay, {data: r.data}),
}), 'bc');

/** The decorated avatar (`ln`, `yt-decorated-avatar-view-model`). */
export const DecoratedAvatar = defineComponent((props) => {
  const vm = () => /** @type {!Object} */ (unwrap(props.data) || {});
  const avatar = () => (vm().avatar && vm().avatar.avatarViewModel) || undefined;
  const config = computed(() => {
    const d = vm();
    const a = avatar();
    const overrides = props.avatarOverrides ? props.avatarOverrides() : undefined;
    if (!a) return Object.assign({size: 'medium'}, overrides);
    const decorations = [];
    if (d.liveData) decorations.push(0);
    return Object.assign({
      size: avatarViewModelSize(a.avatarImageSize),
      decorations,
      badgeText: d.liveData ? d.liveData.liveBadgeText : undefined,
      accessibilityText: contextLabel(d.rendererContext) || d.a11yLabel,
      badgeIcon: d.iconBadgeData ? d.iconBadgeData.iconName : undefined,
      badgeIconColor: undefined,
      badgeIconBorderColor: undefined,
    }, overrides);
  }, undefined, 'H8tk9d');
  return h('ytl-decorated-avatar-view-model', {class: classes('ytlDecoratedAvatarViewModelHost', props.className)},
    cond(() => avatar() && avatar().image, () => h(AvatarShape, {
      data: config, image: () => avatar().image, iconType: 'RADAR_LIVE', overlays: () => h(AvatarOverlays, {data: avatar}),
    })));
}, 'ytl-decorated-avatar-view-model (CoW)');

defineCoW('ytl-decorated-avatar-view-model', DecoratedAvatar, {props: {data: PropKind.SIGNAL, className: PropKind.SIGNAL,
  avatarOverrides: PropKind.SIGNAL, avatarExperiments: PropKind.SIGNAL}});


/**
 * The avatar config of an avatar view model (`sSI`).
 * @param {!Object} o
 * @return {!Object}
 */
function avatarConfig(o) {
  return Object.assign({}, {
    size: avatarViewModelSize(o.data.avatarImageSize),
    type: o.data.avatarBorderStyle === 'AVATAR_BORDER_STYLE_SQUARE' ? 2 : 0,
    onTap: o.onTap,
    decorations: o.decorations || [],
    badgeText: o.badgeText,
    accessibilityText: o.accessibilityText,
    avatarButtonCustomClassName: o.avatarButtonCustomClassName,
    clusterLayoutConfig: o.clusterLayoutConfig,
  }, o.overrides);
}

/** The avatar view model (`F1E`): the avatar shape over its image, with the overlays. */
export const AvatarViewModel = defineComponent((props) => {
  const vm = /** @type {function(): !Object} */ (props.data);
  return h('ytl-avatar-view-model', null, cond(() => vm().image, () => h(AvatarShape, {
    data: () => avatarConfig({
      data: vm(), onTap: undefined, decorations: props.decorations && props.decorations(), badgeText: undefined,
      accessibilityText: vm().accessibilityText, avatarButtonCustomClassName: props.avatarButtonCustomClassName && props.avatarButtonCustomClassName(),
      clusterLayoutConfig: props.clusterLayoutConfig && props.clusterLayoutConfig(), overrides: props.avatarOverrides && props.avatarOverrides(),
    }),
    image: () => vm().image,
    iconType: 'RADAR_LIVE',
    overlays: () => h(AvatarOverlays, {data: vm}),
    isOverlay: props.isOverlay,
  })));
}, 'cc');

/**
 * The size of an avatar in a cluster (`_.nMI`).
 * @param {string} clusterSize
 * @param {number} count
 * @return {number}
 */
function clusterAvatarSize(clusterSize, count) {
  switch (clusterSize) {
    case 'small':
      return count === 2 ? 22 : 18;
    case '40':
      return count === 2 ? 24 : 22;
    default:
      return count === 2 ? 24 : 20;
  }
}

/**
 * The layout of an avatar stack (`gMt`): its avatars, sizes, styles and classes.
 * @param {!Object} stack
 * @return {!Object}
 */
function stackLayout(stack) {
  const first = stack.avatars && stack.avatars.length > 0 ? (stack.avatars[0].avatarViewModel || {}).avatarImageSize : 'AVATAR_SIZE_UNKNOWN';
  const px = avatarEnumPixels(first) || 0;
  if (stack.layoutType === 'AVATAR_STACK_LAYOUT_CLUSTER') {
    const cluster = stack.avatarClusterSize != null ? stack.avatarClusterSize : 'AVATAR_SIZE_M';
    const total = avatarEnumPixels(cluster);
    const count = Math.min((stack.avatars || []).length, 4);
    const clusterName = avatarViewModelSize(cluster);
    const rtl = document.documentElement.dir === 'rtl' || document.body.getAttribute('dir') === 'rtl';
    return {
      avatars: (stack.avatars || []).slice(0, 4),
      avatarSizeInPx: px,
      avatarStackStyle: {width: `${total}px`, height: `${total}px`, position: 'relative'},
      avatarStyle: (i) => {
        const size = clusterAvatarSize(clusterName, count);
        let shift;
        if (count === 3 && i === 2) shift = (rtl ? -1 : 1) * ((total - size) / 2);
        return {
          position: 'absolute',
          top: (count === 2 && i === 1) || (count === 3 && i === 2) || (count === 4 && i >= 2) ? '0' : undefined,
          bottom: (count === 2 && i === 0) || (count > 2 && i < 2) ? '0' : undefined,
          left: (count === 2 && i === 1) || (count > 2 && (i === 1 || i === 3)) ? '0' : undefined,
          right: (count <= 3 && i === 0) || (count === 4 && (i === 0 || i === 2)) ? '0' : undefined,
          transform: shift ? `translateX(${shift}px)` : undefined,
          width: `${size}px`,
          height: `${size}px`,
        };
      },
      avatarStackClass: undefined,
      avatarClass: undefined,
      clusterLayoutConfig: (i) => ({clusterSize: avatarViewModelSize(stack.avatarClusterSize), numAvatarsInCluster: count, avatarIndex: i}),
      avatarButtonCustomClassName: undefined,
    };
  }
  return {
    avatars: (stack.avatars || []).slice(),
    avatarSizeInPx: px,
    avatarStackClass: 'ytlAvatarStackViewModelAvatars',
    avatarClass: avatarStackSizeClass(first),
    avatarStyle: () => ({}),
    avatarStackStyle: {},
    clusterLayoutConfig: undefined,
    avatarButtonCustomClassName: 'ytlAvatarStackViewModelAvatarButton',
  };
}

/**
 * @param {string|undefined} size
 * @return {string}
 */
function avatarStackSizeClass(size) {
  switch (size) {
    case 'AVATAR_SIZE_XS':
      return 'ytlAvatarStackViewModelAvatarSizeExtraSmall';
    case 'AVATAR_SIZE_S':
      return 'ytlAvatarStackViewModelAvatarSizeSmall';
    case 'AVATAR_SIZE_M':
      return 'ytlAvatarStackViewModelAvatarSizeMedium';
    case 'AVATAR_SIZE_48':
      return 'ytlAvatarStackViewModelAvatarSize48';
    case 'AVATAR_SIZE_L':
      return 'ytlAvatarStackViewModelAvatarSizeLarge';
    case 'AVATAR_SIZE_XL':
      return 'ytlAvatarStackViewModelAvatarSizeExtraLarge';
    case 'AVATAR_SIZE_XXL':
      return 'ytlAvatarStackViewModelAvatarSizeExtraExtraLarge';
    case 'AVATAR_SIZE_XXXL':
      return 'ytlAvatarStackViewModelAvatarSizeGiant';
    default:
      return '';
  }
}

/**
 * A style attribute from an object of properties; unset values are left out.
 * @param {?Object|undefined} style
 * @return {string|undefined}
 */
function styleText(style) {
  let out = '';
  for (const key in style) {
    if (style[key] != null && style[key] !== '') out += `${out ? '; ' : ''}${key}: ${style[key]}`;
  }
  return out || undefined;
}

/** The avatar stack (`Nw`, `yt-avatar-stack-view-model`). */
export const AvatarStack = defineComponent((props) => {
  const vm = () => Object.assign({}, props.data(), props.overrides && props.overrides());
  const tappable = () => !!contextCommandOf(vm().rendererContext);
  const firstSize = () => {
    const avatars = vm().avatars;
    const a = avatars && avatars[0] ? avatars[0].avatarViewModel : undefined;
    return a && a.avatarImageSize != null ? a.avatarImageSize : 'AVATAR_SIZE_UNKNOWN';
  };
  const layout = () => stackLayout(vm());
  const decorations = () => {
    if (vm().layoutType === 'AVATAR_STACK_LAYOUT_CLUSTER') return undefined;
    if (props.decorations && props.decorations()) return props.decorations();
    const v = vm();
    let n = 0;
    if (v.avatars) n += v.avatars.length;
    if (v.decoratedText) n += 1;
    return n > 1 ? [3] : [];
  };
  const thin = () => firstSize() === 'AVATAR_SIZE_XXS' || firstSize() === 'AVATAR_SIZE_XS';
  const avatarSlot = (render) => (r, index) => h('div', {
    style: () => styleText(layout().avatarStyle ? layout().avatarStyle(index ? index() : 0) : undefined),
    class: () => layout().avatarClass,
  }, render(r, index));
  return h('ytl-avatar-stack-view-model', {
    ref: useCommandContext(() => vm().rendererContext),
    class: classes('ytlAvatarStackViewModelHost', props.className, {
      'ytlAvatarStackViewModelTappable': tappable,
      'ytlAvatarStackViewModelIsOverlay': props.isOverlay,
      'ytlAvatarStackViewModelMediumText': props.useMediumText,
    }),
    tabindex: () => (tappable() ? 0 : undefined),
    role: () => (tappable() ? 'button' : undefined),
    'aria-label': () => contextLabel(vm().rendererContext) || '',
    'on:keydown': (/** !KeyboardEvent */ e) => {
      if ((e.key === 'Enter' || e.key === ' ') && /** @type {!Element} */ (e.currentTarget) === e.target) {
        e.preventDefault();
        /** @type {!HTMLElement} */ (e.currentTarget).click();
      }
    },
  },
  cond(() => vm().avatars && !(props.hideAvatar && props.hideAvatar()), () => h('div', {class: 'ytlAvatarStackViewModelAvatars'},
    cond(() => vm().decoratedText, () => h('div', {
      class: classes('ytlAvatarStackViewModelTextContainer', {
        'ytlAvatarStackViewModelTextContainerThinBorder': thin,
        'ytlAvatarStackViewModelTextContainerThinBorderOverlay': () => !!props.isOverlay && props.isOverlay() && thin(),
      }),
      style: styles({width: () => `${layout().avatarSizeInPx}px`, height: () => `${layout().avatarSizeInPx}px`}),
    }, h(AttributedString, {text: () => vm().decoratedText, className: 'ytlAvatarStackViewModelAvatarDecoratedText'}))),
    h('div', {style: () => styleText(layout().avatarStackStyle), class: () => layout().avatarStackClass},
      rendererOf(() => layout().avatars.reverse(), {
        'avatarViewModel': avatarSlot((r, index) => h(AvatarViewModel, {
          data: r.data, decorations, avatarButtonCustomClassName: () => layout().avatarButtonCustomClassName, isOverlay: props.isOverlay,
          clusterLayoutConfig: () => (layout().clusterLayoutConfig ? layout().clusterLayoutConfig(index ? index() : 0) : undefined),
        })),
        'decoratedAvatarViewModel': avatarSlot((r) => h(DecoratedAvatar, {data: r.data})),
      })))),
  cond(() => vm().text, () => h(AttributedString, {text: () => vm().text, className: 'ytlAvatarStackViewModelAvatarStackText', linkInheritColor: true})));
}, 'ytl-avatar-stack-view-model (CoW)');

defineCoW('ytl-avatar-stack-view-model', AvatarStack, {props: {data: PropKind.SIGNAL, overrides: PropKind.SIGNAL, className: PropKind.SIGNAL,
  isOverlay: PropKind.SIGNAL, useMediumText: PropKind.SIGNAL, hideAvatar: PropKind.SIGNAL, decorations: PropKind.SIGNAL}});
