/**
 * @fileoverview Number and time formatting for metadata lines.
 */

const compact = new Intl.NumberFormat('en-US', {notation: 'compact', maximumFractionDigits: 1});
const full = new Intl.NumberFormat('en-US');
const relative = new Intl.RelativeTimeFormat('en-US', {numeric: 'auto'});

/**
 * @param {number} n
 * @return {string}
 */
export function formatCompactCount(n) {
  return compact.format(n);
}

/**
 * @param {number} n
 * @return {string}
 */
export function formatCount(n) {
  return full.format(n);
}

/**
 * Parses "1,234", "1.2K" or "3M views" into a number.
 * @param {string} text
 * @return {number}
 */
export function parseCount(text) {
  const m = /([\d.,]+)\s*([KMB])?/i.exec(text);
  if (!m) return 0;
  const base = parseFloat(m[1].replace(/,/g, ''));
  const mult = m[2] ? {k: 1e3, m: 1e6, b: 1e9}[m[2].toLowerCase()] : 1;
  return Math.round(base * mult);
}

const UNITS = [['year', 31536000], ['month', 2592000], ['week', 604800], ['day', 86400], ['hour', 3600], ['minute', 60]];

/**
 * @param {number} epochSeconds
 * @return {string}
 */
export function relativeTime(epochSeconds) {
  const delta = epochSeconds - Date.now() / 1000;
  for (const [unit, secs] of UNITS) {
    if (Math.abs(delta) >= secs) return relative.format(Math.round(delta / /** @type {number} */ (secs)), /** @type {string} */ (unit));
  }
  return relative.format(Math.round(delta), 'second');
}

/**
 * "12:34" or "1:02:03" to seconds.
 * @param {string} text
 * @return {number}
 */
export function parseDuration(text) {
  let total = 0;
  for (const part of text.split(':')) total = total * 60 + (parseInt(part, 10) || 0);
  return total;
}
