/**
 * @fileoverview The AI video summary shown in expandable metadata: text
 * paragraphs plus like and dislike feedback buttons.
 */
import {unwrap} from '../../framework/vm/effect.js';
import {h} from '../../framework/vm/jsx.js';
import {LikeButtonViewModel} from './buttons.js';
import {AttributedString} from './attributed-string.js';
import {defineComponent} from '../../framework/vm/render.js';

/**
 * @param {?Object|undefined} vm
 * @return {?Object}
 */
function unwrapLike(vm) {
  let v = vm || null;
  while (v && v.likeButtonViewModel) v = v.likeButtonViewModel;
  while (v && v.dislikeButtonViewModel) v = v.dislikeButtonViewModel;
  return v;
}

/** The video summary content. */
export const VideoSummaryContent = defineComponent((props) => {
  const vm = unwrap(props.data);
  return h('ytl-video-summary-content-view-model', {class: 'videoSummaryContentViewModelHost videoSummaryContentViewModelHostIsSearch'},
    h('div', {class: 'videoSummaryContentViewModelParagraphContainer'},
      (vm.paragraphs || []).map(p => h('p', {class: 'videoSummaryContentViewModelParagraph'},
        h(AttributedString, {text: (p.videoSummaryParagraphViewModel || p).text})))),
    h('div', {class: 'videoSummaryContentViewModelBottomButtonsContainer'},
      h('div', {class: 'videoSummaryContentViewModelLikeButton'},
        h(LikeButtonViewModel, {data: unwrapLike(vm.likeButtonViewModel), kind: 'like'})),
      h(LikeButtonViewModel, {data: unwrapLike(vm.dislikeButtonViewModel), kind: 'dislike'})));
}, 'video-summary-content-view-model');
