/**
 * @fileoverview Small view-model shapes shared by many components: the
 * icon, the touch-feedback shape, the rim-light shape, the tooltip hook,
 * theme-token colours and the avatar shape.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {cond} from '../../framework/vm/control.js';
import {afterRenderEffect, computed, linkedSignal, runUntracked, signal, unwrap} from '../../framework/vm/effect.js';
import {h} from '../../framework/vm/jsx.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {defineComponent} from '../../framework/vm/render.js';
import {createIconShape} from '../../framework/icons.js';
import {rootInjector} from '../../framework/injector.js';
import {defineInjectable, registerInjectable} from '../../framework/signals.js';
import {avatarSizeOf} from './enums.js';

/**
 * @param {number} argb
 * @return {string}
 */
export function argbToCss(argb) {
  const a = ((argb >>> 24) & 255) / 255;
  const r = (argb >>> 16) & 255, g = (argb >>> 8) & 255, b = argb & 255;
  return `rgba(${r}, ${g}, ${b}, ${a.toFixed(3)})`;
}

/** The dark-theme state, provided through the root injector. */
export class DarkTheme {
  /** @return {boolean} */
  isDark() {
    return document.documentElement.hasAttribute('dark');
  }
}
registerInjectable(DarkTheme, defineInjectable({token: DarkTheme, providedIn: 'root', factory: () => new DarkTheme()}));

/** Whether the user navigates with the keyboard, provided through the root injector. */
export class KeyboardTracker {
  constructor() {
    /** @private {boolean} */
    this.inUse_ = false;
    document.addEventListener('keydown', () => {
      this.inUse_ = true;
    }, true);
    document.addEventListener('mousedown', () => {
      this.inUse_ = false;
    }, true);
  }

  /** @return {boolean} */
  isKeyBoardInUse() {
    return this.inUse_;
  }
}
registerInjectable(KeyboardTracker, defineInjectable({token: KeyboardTracker, providedIn: 'root', factory: () => new KeyboardTracker()}));

/** @return {boolean} */
export function keyboardInUse() {
  const tracker = /** @type {?KeyboardTracker} */ (rootInjector.resolve(KeyboardTracker));
  return !!tracker && tracker.isKeyBoardInUse();
}

/**
 * Resolves a theme-token colour (`R_x`): the dark or light value of the
 * token, else the raw colour, as CSS.
 * @param {?Object|undefined} token `{lightTheme, darkTheme}` ARGB values.
 * @param {?number|undefined} raw
 * @return {string|undefined}
 */
export function themeColor(token, raw) {
  const theme = /** @type {!DarkTheme} */ (rootInjector.resolve(DarkTheme));
  const value = token ? (theme.isDark() ? token.darkTheme : token.lightTheme) : raw;
  return value == null ? undefined : argbToCss(value);
}

/**
 * The smallest source at least `width` wide, or the largest one.
 * @param {!Array<{url: string, width: number, height: number}>} sources
 * @param {number} width
 * @return {?{url: string, width: number, height: number}}
 */
export function pickSource(sources, width) {
  let best = null;
  for (const s of sources) {
    if (s.width >= width && (!best || best.width < width || s.width < best.width)) best = s;
    else if (!best || (best.width < width && s.width > best.width)) best = s;
  }
  return best;
}

/**
 * @param {?Object} a
 * @param {?Object} b
 * @return {boolean}
 */
function sameIconConfig(a, b) {
  return !!a && !!b && a.name === b.name && a.size === b.size && a.filled === b.filled && a.color === b.color &&
      a.animated === b.animated;
}

/**
 * The icon (`_.Mm`): a wrapper span whose shape an after-render effect
 * resolves from a computed icon config.
 */
export const Icon = defineComponent((props) => {
  const config = computed(() => ({
    name: unwrap(props.icon) || '',
    size: unwrap(props.size) || 24,
    filled: !!unwrap(props.filled),
    color: unwrap(props.color) || '',
    animated: !!unwrap(props.animated),
  }), sameIconConfig, 'Mm');
  /** @type {?Element} */
  let wrapper = null;
  afterRenderEffect(() => {
    const c = config();
    runUntracked(() => {
      if (!wrapper) return;
      const shape = createIconShape(c.name, c.size);
      if (wrapper.firstChild) wrapper.replaceChild(shape, wrapper.firstChild);
      else wrapper.appendChild(shape);
    });
  }, 'v878Je');
  const size = unwrap(props.size) || 24;
  const label = unwrap(props.label);
  return h('span', {
    class: classes('ytlIconWrapperHost', props.className),
    role: label ? 'img' : undefined,
    'aria-label': label || undefined,
    'aria-hidden': label ? undefined : unwrap(props.ariaHidden),
    style: props.style ? () => `width: ${size}px; height: ${size}px;${props.style() ? ` ${props.style()}` : ''}` : {width: `${size}px`, height: `${size}px`},
    ref: (/** !Element */ el) => {
      wrapper = el;
    },
  });
}, 'Icon');

const ICON_NAME = /^YTICON_(fill|outline)_([a-zA-Z0-9_]+)_s([0-9]+)$/i;

/**
 * The icon with the lookup of a sized icon name (`_.Cr`): a computed of the
 * name's parts, a `cond` on the icon and the icon itself.
 */
export const IconByName = defineComponent((props) => {
  const lookup = computed(() => {
    const name = props.icon && props.icon();
    const m = name && ICON_NAME.exec(name);
    return m ? {iconName: m[2].toUpperCase(), iconSize: Number(m[3]), iconActive: m[1].toLowerCase() === 'fill'} : undefined;
  }, undefined, 'M0i5vf');
  const name = () => (lookup() ? lookup().iconName : props.icon());
  const size = () => {
    const s = props.size && props.size();
    return s != null ? s : lookup() ? lookup().iconSize : undefined;
  };
  return cond(props.icon, () => h(Icon, {
    icon: name,
    size: () => size() || 24,
    filled: () => (props.active && props.active() != null ? props.active() : lookup() ? lookup().iconActive : false),
    className: props.className,
    ariaHidden: props.ariaHidden,
    label: props.ariaLabel,
    style: props.style,
  }));
}, 'q');

/**
 * @param {string|undefined} response
 * @return {string}
 */
function touchResponseClass(response) {
  switch (response) {
    case 'invert':
      return 'ytlTouchFeedbackShapeTouchResponseInverse';
    case 'none':
      return '';
    default:
      return 'ytlTouchFeedbackShapeTouchResponse';
  }
}

/**
 * The thumbnail-size class of a touch-feedback model.
 * @param {?Object} model
 * @return {string}
 */
function feedbackSizeClass(model) {
  switch (model && model.thumbnailSize) {
    case 'small':
      return 'ytlTouchFeedbackShapeThumbnailSizeSmall';
    case 'medium':
      return 'ytlTouchFeedbackShapeThumbnailSizeMedium';
    case 'large':
      return 'ytlTouchFeedbackShapeThumbnailSizeLarge';
    default:
      return '';
  }
}

/**
 * Adds a listener for the current owner's lifetime.
 * @param {!EventTarget} target
 * @param {string} type
 * @param {function(!Event)} fn
 */
export function listen(target, type, fn) {
  target.addEventListener(type, fn);
  onCleanup(() => target.removeEventListener(type, fn));
}

/**
 * The touch-feedback shape (`_.VFS`): three classed elements and three
 * after-render effects for press, release and leave.
 */
export const TouchFeedbackShape = defineComponent((props) => {
  const [down, setDown] = signal(false, 'qLIsKb');
  /** @type {?Element} */
  let host = null;
  afterRenderEffect(() => {
    const target = host && host.parentElement;
    if (target) listen(target, 'pointerdown', () => setDown(true));
  }, 'press');
  afterRenderEffect(() => {
    if (down()) runUntracked(() => listen(document, 'pointerup', () => setDown(false)));
  }, 'release');
  afterRenderEffect(() => {
    const target = host && host.parentElement;
    if (down() && target) runUntracked(() => listen(target, 'pointerleave', () => setDown(false)));
  }, 'leave');
  const model = () => unwrap(props.model) || null;
  return h('ytl-touch-feedback-shape', {
    class: classes('ytlTouchFeedbackShapeHost', () => touchResponseClass(unwrap(props.response)), () => feedbackSizeClass(model()), {
      'ytlTouchFeedbackShapeTriggerEvents': () => !!(model() && model().triggerEvents),
      'ytlTouchFeedbackShapeHovered': () => !!unwrap(props.hovered),
      'ytlTouchFeedbackShapeDown': down,
    }),
    style: styles({
      '--ytl-touch-feedback-margin': () => (model() && model().margin !== undefined ? `${model().margin}px` : undefined),
      '--ytl-touch-feedback-top-extend': () => (model() && model().customTopExtend !== undefined ? `${model().customTopExtend}px` : undefined),
    }),
    'aria-hidden': 'true',
    ref: (/** !Element */ el) => {
      host = el;
    },
  },
  '',
  h('div', {class: classes('ytlTouchFeedbackShapeStroke', {'ytlTouchFeedbackShapeStrokeDown': down})}),
  h('div', {class: classes('ytlTouchFeedbackShapeFill', {'ytlTouchFeedbackShapeFillDown': down})}));
}, 'TouchFeedbackShape');

/**
 * The rim-light shape (`_.ZED`): one hover signal, two after-render
 * effects, CSS custom properties from thunks and four `cond`s.
 */
export const LightShape = defineComponent((props) => {
  const [hovered, setHovered] = signal(false, 'kGyvJb');
  /** @type {?Element} */
  let host = null;
  afterRenderEffect(() => {
    const target = host && host.parentElement;
    if (target) listen(target, 'pointerenter', () => setHovered(true));
  }, 'TNbAqd');
  afterRenderEffect(() => {
    const target = host && host.parentElement;
    if (hovered() && target) runUntracked(() => listen(target, 'pointerleave', () => setHovered(false)));
  }, 'kQ0Ibe');
  const variant = () => unwrap(props.variant) || 'Outline';
  return h('ytl-light-shape', {
    class: classes('ytlLightShapeHost', () => `ytlLightShapeStaticRimLight${variant()}`, 'ytlLightShapeStaticRimLight'),
    'aria-hidden': 'true',
    style: styles({'--ytl-light-angle': () => (variant() === 'Tonal' ? '120deg' : '135deg'), '--ytl-light-opacity': () => (hovered() ? '1' : '0.6')}),
    ref: (/** !Element */ el) => {
      host = el;
    },
  },
  cond(() => unwrap(props.animated), () => h('div', {class: 'ytlLightShapeAnimatedLight'})),
  cond(hovered, () => h('div', {class: 'ytlLightShapeHoverLight'})),
  cond(() => !unwrap(props.disableStatic), () => cond(() => unwrap(props.gradient), () => h('div', {class: 'ytlLightShapeGradient'}))));
}, 'LightShape');

/** @type {?HTMLElement} */
let tooltipElement = null;
/** @type {!WeakMap<!Element, function(): string>} */
const tooltipTargets = new WeakMap();

/**
 * @param {!Element} target
 * @param {string} text
 * @param {string} placement
 */
function showTooltip(target, text, placement) {
  if (!text) return;
  if (!tooltipElement) {
    tooltipElement = /** @type {!HTMLElement} */ (document.createElement('div'));
    tooltipElement.className = 'ytlTooltipHost';
    tooltipElement.setAttribute('role', 'tooltip');
    document.body.appendChild(tooltipElement);
  }
  const rect = target.getBoundingClientRect();
  tooltipElement.textContent = text;
  tooltipElement.style.left = `${rect.left}px`;
  tooltipElement.style.top = `${placement === 'top' ? rect.top - 32 : rect.bottom + 8}px`;
  tooltipElement.hidden = false;
}

function hideTooltip() {
  if (tooltipElement) tooltipElement.hidden = true;
}

/**
 * The tooltip hook (`_.hy`): a linked signal of the text and a ref that,
 * on render, adds one computed, one after-render effect and five listeners
 * with one cleanup.
 * @param {*} text A string or thunk.
 * @param {*=} placement
 * @return {{onRender: function(!Element)}}
 */
export function useTooltip(text, placement) {
  const tooltipText = linkedSignal(() => unwrap(text) || '', 'tooltipText');
  return {
    onRender: (el) => {
      const hasTooltip = computed(() => !!tooltipText(), undefined, 'hasTooltip');
      afterRenderEffect(() => {
        const has = hasTooltip();
        runUntracked(() => {
          if (has) tooltipTargets.set(el, tooltipText);
          else tooltipTargets.delete(el);
        });
      }, 'WlsgZc');
      const where = () => unwrap(placement) || 'bottom';
      const show = () => showTooltip(el, tooltipText(), where());
      el.addEventListener('mouseenter', show);
      el.addEventListener('focus', show);
      el.addEventListener('mouseleave', hideTooltip);
      el.addEventListener('blur', hideTooltip);
      el.addEventListener('click', hideTooltip);
      onCleanup(() => {
        el.removeEventListener('mouseenter', show);
        el.removeEventListener('focus', show);
        el.removeEventListener('mouseleave', hideTooltip);
        el.removeEventListener('blur', hideTooltip);
        el.removeEventListener('click', hideTooltip);
      });
    },
  };
}

/**
 * The avatar shape: a sized image in a circle.
 */
export const AvatarShape = defineComponent((props) => {
  const avatar = () => unwrap(props.data) || {};
  const px = () => avatarSizeOf(unwrap(props.size) || avatar().avatarImageSize);
  const src = () => {
    const s = pickSource((avatar().image && avatar().image.sources) || [], px());
    return s ? s.url : undefined;
  };
  return h('ytl-avatar-shape', {class: classes('ytlAvatarShapeHost', () => `ytlAvatarShapeSize${px()}`)},
    h('div', {class: 'ytlAvatarShapeAvatar'},
      h('img', {class: 'ytlCoreImageHost ytlCoreImageFillParentWidth ytlCoreImageFillParentHeight ytlAvatarShapeImage',
        alt: '', src, width: px})));
}, 'AvatarShape');
