/** @type {!WeakMap<!Object, !Object<string, function()>>} */
const boundListeners = new WeakMap();

/**
 * The listener that calls the method `name` of `self`, one per instance and
 * method, so that it can be removed again.
 * @param {!Object} self
 * @param {string} name
 * @return {function()}
 */
function bound(self, name) {
  let table = boundListeners.get(self);
  if (!table) boundListeners.set(self, table = {});
  return table[name] || (table[name] = () => self[name]());
}

/**
 * Scrolls its target down on its own while `autoScrollEnabled`, a frame at
 * a time at `scrollRate` lines per second, and stops on click and hover.
 * @polymerBehavior
 */
const AutoScrollBehavior = {
  properties: {
    scrollRate: {type: Object},
    scrollTarget: {type: Object},
    autoScrollEnabled: {type: Boolean},
  },
  observers: ['autoScrollEnabledChanged(autoScrollEnabled)'],

  initFields_() {
    this._noAccessors = true;
    this.scrollRate = 3;
    this.autoScrollAnimationStart = 0;
    this.autoScrollPaused = false;
    this.autoScrollRafId = 0;
  },

  created() {
    this.boundAutoScrollHandler = (/** number */ time) => this.autoScroll(time);
  },

  detached() {
    const host = this.hostElement;
    host.removeEventListener('mouseout', bound(this, 'startAutoScroll'));
    host.removeEventListener('click', bound(this, 'endAutoScroll'));
    host.removeEventListener('mouseover', bound(this, 'endAutoScroll'));
    this.endAutoScroll();
  },

  autoScrollEnabledChanged() {
    const host = this.hostElement;
    if (this.autoScrollEnabled) {
      host.addEventListener('mouseout', bound(this, 'startAutoScroll'));
      host.addEventListener('click', bound(this, 'endAutoScroll'));
      host.addEventListener('mouseover', bound(this, 'endAutoScroll'));
      this.startAutoScroll();
    } else {
      host.removeEventListener('mouseout', bound(this, 'startAutoScroll'));
      host.removeEventListener('click', bound(this, 'endAutoScroll'));
      host.removeEventListener('mouseover', bound(this, 'endAutoScroll'));
      this.endAutoScroll();
    }
  },

  /** @param {number} time */
  autoScroll(time) {
    if (!this.autoScrollAnimationStart) this.autoScrollAnimationStart = time;
    if (this.autoScrollPaused || !this.scrollTarget || this.hasScrolledToBottom(this.scrollTarget)) return;
    const interval = 1000 / this.scrollRate;
    const elapsed = time - this.autoScrollAnimationStart;
    if (elapsed > interval) {
      this.scrollTarget.scrollTop += Math.ceil(elapsed / interval);
      this.autoScrollAnimationStart = 0;
    }
    this.startAutoScroll();
  },

  /**
   * @param {!Element} target
   * @return {boolean}
   */
  hasScrolledToBottom(target) {
    return target.scrollHeight - target.scrollTop === target.clientHeight;
  },

  startAutoScroll() {
    this.autoScrollPaused = false;
    this.autoScrollRafId = window.requestAnimationFrame(this.boundAutoScrollHandler);
  },

  endAutoScroll() {
    this.autoScrollPaused = true;
    window.cancelAnimationFrame(this.autoScrollRafId);
  },
};

