/**
 * An input that opens and closes on click: `showInput` follows the clicks
 * on the host and on the window (kevlar's `ytdExpandableInputBehavior`).
 * @polymerBehavior
 */
const ExpandableInputBehavior = {
  properties: {
    showInput: {type: Boolean, reflectToAttribute: true},
  },
  observers: ['showInputChanged(showInput)'],
  listeners: {'click': 'stopPropagation_', 'keydown': 'stopPropagation_'},

  initFields_() {
    this.showInput = false;
  },

  detached() {
    if (this.showInput) window.removeEventListener('click', boundOutsideClick(this));
  },

  /** @param {!Event} e */
  stopPropagation_(e) {
    if (this.showInput) e.stopPropagation();
  },

  /** @param {!Event} e */
  closeOnOutsideClick_(e) {
    if (!this.closeOnOutsideClickCondition(e)) return;
    this.showInput = false;
    window.removeEventListener('click', boundOutsideClick(this));
    this.closeOnOutsideClickHandler();
  },

  /** @return {boolean} */
  closeOnOutsideClickCondition() {
    return true;
  },

  closeOnOutsideClickHandler() {},

  openOnClick_() {
    this.showInput = true;
    window.addEventListener('click', boundOutsideClick(this));
    this.openOnClickHandler();
  },

  openOnClickHandler() {},

  showInputChanged() {},

  /** @param {boolean} value */
  setShowInput(value) {
    this.showInput = value;
  },
};

/** @type {!WeakMap<!Object, function(!Event)>} */
const outsideClickListeners = new WeakMap();

/**
 * The window click listener of an expandable input, one per instance.
 * @param {!Object} self
 * @return {function(!Event)}
 */
function boundOutsideClick(self) {
  let listener = outsideClickListeners.get(self);
  if (!listener) outsideClickListeners.set(self, listener = e => self.closeOnOutsideClick_(e));
  return listener;
}

/** The search tab of a channel: an icon that opens a search field. */
Polymer(withQueries(withHandles({
  _template: expandableTabTemplate,
  is: 'ytl-expandable-tab-renderer',
  behaviors: [ExpandableInputBehavior, RendererBehavior],
  properties: {
    data: Object,
    searchIcon: String,
  },
  observers: ['onDataChanged(data)'],

  initFields_() {
    this.searchIcon = flag('enable_web_delhi_icons') ? 'search' : 'yt-icons:search';
    this.onYtNavigate = undefined;
  },

  ready() {
    hostDom(this.hostElement).querySelector('#form').addEventListener('submit', (/** !Event */ e) => this.onSubmit(e));
  },

  onDataChanged() {
    if (this.data && this.data.selected) this.ytdExpandableInputBehavior.setShowInput(true);
  },

  /** @param {!KeyboardEvent} e */
  onIconButtonKeydown(e) {
    if (e.keyCode === 13) this.iconButton.click();
  },

  closeOnOutsideClickHandler() {
    this.set('data.expandedText', '');
  },

  openOnClickHandler() {
    this.input.focus();
  },

  /**
   * @param {!Event} e
   * @return {boolean}
   */
  onSubmit(e) {
    e.preventDefault();
    return false;
  },

  /** @param {!KeyboardEvent} e */
  submitOnEnterKeyUp(e) {
    if (e.keyCode !== 13 || !(this.data && this.data.expandedText)) return;
    const endpoint = /** @type {!Object} */ (JSON.parse(JSON.stringify(this.data.endpoint)));
    const meta = endpoint.commandMetadata && endpoint.commandMetadata.webCommandMetadata;
    if (meta && meta.url) {
      const url = new URL(meta.url, location.href);
      url.searchParams.set('query', this.data.expandedText);
      meta.url = url.pathname + url.search;
      if (endpoint.browseEndpoint) endpoint.browseEndpoint.query = this.data.expandedText;
      this.fire('yt-navigate', {endpoint, tempData: {disableCache: true}});
    } else {
      reportError(new Error('Trying to navigate to an endpoint without url'));
    }
  },

  /** @param {!CustomEvent} e */
  updateDataExpandedTextFromBinding(e) {
    this.set('data.expandedText', e.detail.value);
  },
}, ['ytRendererBehavior', 'ytdExpandableInputBehavior']), {input: 'input', iconButton: 'icon-button'}));
