/**
 * @fileoverview The horizontal list behaviour of shelves and link rows that
 * scroll sideways (kevlar's `YtdHorizontalListBehavior`): the lazy list of
 * the items, an offset applied to `#items` as a transform, arrows that move
 * it by whole items and hide at either end, wheel and drag scrolling for
 * search shelves, an observer of the items that are fully visible, and the
 * state of the guide. The element's template has `#scroll-container`,
 * `#items` and `#scroll-outer-container`, and arrows bound to `prevClick_`
 * and `nextClick_` that read `atStart` and `atEnd`.
 */
import {FlattenedNodesObserver} from '@polymer/polymer/lib/utils/flattened-nodes-observer.js';
import {flush} from '@polymer/polymer/lib/utils/flush.js';
import {IronResizableBehavior} from '@polymer/iron-resizable-behavior/iron-resizable-behavior.js';
import {flag, getConfig, setConfig} from '../framework/flags.js';
import {hostDom} from '../framework/host-dom.js';
import {reportError} from '../framework/errors.js';
import {afterNextRender} from './scheduler.js';
import {LazyListBehavior, itemsPathOfElement} from './lazy-list.js';
import {GuideStateAwareBehavior} from './container-behaviors.js';
import {RendererBehavior} from './renderer-behavior.js';

/**
 * @param {!Object} self
 * @return {!HTMLElement}
 */
function itemsElement(self) {
  return /** @type {!HTMLElement} */ (hostDom(self.hostElement).querySelector('#items'));
}

/**
 * @param {!Object} self
 * @return {!HTMLElement}
 */
function scrollContainer(self) {
  return /** @type {!HTMLElement} */ (hostDom(self.hostElement).querySelector('#scroll-container'));
}

/** @polymerBehavior */
const HorizontalListScrollBehavior = {
  properties: {
    data: Object,
    atStart: {type: Boolean, reflectToAttribute: true},
    atEnd: {type: Boolean, reflectToAttribute: true},
    startIndex: Object,
    endIndex: Object,
    initialCount: {type: Number, value: 6},
    scrollCount: Object,
    initialStartIndex: Object,
    disableScrollEventListener: Object,
    supportComponentResize: Object,
    boundPrevClick: {type: Function, value() {
      return () => this.prevClick_();
    }},
    boundNextClick: {type: Function, value() {
      return () => this.nextClick_();
    }},
    useFloorScrolling: Object,
    isSearch: Object,
    dragging: Object,
    dragMouseStart: Object,
    dragOffsetStart: Object,
    disableWheelScroll: Object,
    centerListItems: Object,
  },
  observers: ['onIronResize_(guideOpened)', 'observeShownItems_(shownItems)'],
  listeners: {'iron-resize': 'onIronResize_', 'transitionend': 'onItemsTransitionEnd_', 'focusin': 'onChildElementFocus_'},

  created() {
    this.atStart = true;
    this.atEnd = true;
    this.startIndex = 0;
    this.endIndex = 0;
    this.scrollCount = 0;
    this.initialStartIndex = 0;
    this.disableScrollEventListener = false;
    this.useFloorScrolling = false;
    this.isSearch = false;
    this.dragging = false;
    this.dragMouseStart = 0;
    this.dragOffsetStart = 0;
    this.disableWheelScroll = false;
    this.centerListItems = false;
    this.offset = 0;
    this.minComponentWidth = 0;
    this.marginWidthRight = 0;
    this.marginWidthLeft = 0;
    this.setButtonsStateRequested = false;
    this.itemsVisibilityObserver = null;
    this.fullyVisibleItemsIndices = [];
    this.onWheelScroll = (/** !WheelEvent */ e) => {
      if (!this.isWheelScrollEnabled()) return;
      const delta = e.shiftKey ? (Math.abs(e.deltaY) > Math.abs(e.deltaX) ? e.deltaY : e.deltaX) : e.deltaX;
      if (delta === 0) return;
      e.preventDefault();
      this.fillRemainingListItems();
      this.offset += delta;
      this.ensureWithinScrollBounds();
      this.reposition_();
    };
    this.onPointerDown = (/** !PointerEvent */ e) => {
      if (!this.isClickDragScrollEnabled()) return;
      this.dragMouseStart = e.clientX;
      this.dragOffsetStart = this.offset;
      this.dragging = true;
    };
    this.onPointerMove = (/** !PointerEvent */ e) => {
      if (!this.isClickDragScrollEnabled() || !this.dragging) return;
      this.fillRemainingListItems();
      this.offset = this.dragOffsetStart - (e.clientX - this.dragMouseStart);
      this.ensureWithinScrollBounds();
      this.reposition_();
    };
    this.onPointerUp = () => {
      if (this.isClickDragScrollEnabled()) this.dragging = false;
    };
    this.cachedViewportWidth = getConfig('initialInnerWidth') || window.innerWidth;
    this['JSC$18343_cachedViewportHeight'] = getConfig('initialInnerHeight') || window.innerHeight;
    if (getConfig('REMAINING_DOVA_DEFERRED_CHUNKS', -1) === -1) setConfig('REMAINING_DOVA_DEFERRED_CHUNKS', 6);
  },

  attached() {
    this.disableScrollEventListener || this.addScrollEventListeners();
    this.setUpItemsVisibilityObserver();
  },

  detached() {
    this.disableScrollEventListener || this.removeScrollEventListeners();
    this.tearDownItemsVisibilityObserver();
  },

  /** @return {number} */
  getFullyVisibleItemsWidthPixels() {
    const items = itemsElement(this).children;
    let width = 0;
    for (const index of this.fullyVisibleItemsIndices) width += items[index].clientWidth;
    return width;
  },

  /** @return {boolean} */
  isWheelScrollEnabled() {
    return !!this.isSearch && !this.disableWheelScroll;
  },

  /** @return {boolean} */
  isClickDragScrollEnabled() {
    return !!this.isSearch;
  },

  setUpItemsVisibilityObserver() {
    const container = scrollContainer(this);
    if (!container) return;
    if (!this.itemsVisibilityObserver) {
      const margin = window.getComputedStyle(container).marginRight;
      this.itemsVisibilityObserver = new IntersectionObserver(entries => this.onVisibilityChange(entries),
          {root: container, rootMargin: margin, threshold: 0.98});
    }
    const items = hostDom(this.hostElement).querySelector('#items');
    if (items) this.itemsObserver = new FlattenedNodesObserver(items, info => this.onItemsChanged(info));
  },

  /** @param {{addedNodes: !Array<!Node>, removedNodes: !Array<!Node>}} info */
  onItemsChanged(info) {
    if (!this.useItemsFullVisibility()) return;
    for (const node of Array.from(info.addedNodes)) {
      if (node.nodeType === Node.ELEMENT_NODE && this.itemsVisibilityObserver) this.itemsVisibilityObserver.observe(/** @type {!Element} */ (node));
    }
    for (const node of Array.from(info.removedNodes)) {
      if (node.nodeType === Node.ELEMENT_NODE && this.itemsVisibilityObserver) this.itemsVisibilityObserver.unobserve(/** @type {!Element} */ (node));
    }
  },

  /** @param {!Array<!IntersectionObserverEntry>} entries */
  onVisibilityChange(entries) {
    const visible = new Set(this.fullyVisibleItemsIndices);
    for (const entry of entries) {
      const parent = entry.target.parentElement;
      if (!parent) {
        reportError(new Error(`Parent element not found: ${entry.target.nodeName}`));
        continue;
      }
      const index = Array.from(parent.children).indexOf(entry.target);
      if (entry.isIntersecting) visible.add(index);
      else if (visible.has(index)) visible.delete(index);
    }
    this.fullyVisibleItemsIndices = Array.from(visible).sort((a, b) => a - b);
    if (visible.size === 0) {
      reportError(new Error('No visible entries in horizontal list'));
    } else {
      this.startIndex = this.fullyVisibleItemsIndices[0];
      this.endIndex = this.fullyVisibleItemsIndices[this.fullyVisibleItemsIndices.length - 1];
    }
  },

  tearDownItemsVisibilityObserver() {
    if (this.itemsVisibilityObserver) this.itemsVisibilityObserver.disconnect();
    this.itemsVisibilityObserver = null;
    if (this.itemsObserver) this.itemsObserver.disconnect();
  },

  /** @return {boolean} */
  useItemsFullVisibility() {
    return this.data ? this.areListItemsHavingEqualHeight(this.data) : false;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  areListItemsHavingEqualHeight(data) {
    return !!data && !!data.itemSizeConstraint && data.itemSizeConstraint === 'LIST_ITEM_SIZE_CONSTRAINT_EQUAL_HEIGHT';
  },

  addScrollEventListeners() {
    const container = scrollContainer(this);
    container.style.touchAction = 'pan-y';
    container.addEventListener('wheel', this.onWheelScroll);
    container.addEventListener('pointerdown', this.onPointerDown);
    container.addEventListener('pointermove', this.onPointerMove);
    window.addEventListener('pointerup', this.onPointerUp);
  },

  removeScrollEventListeners() {
    const container = scrollContainer(this);
    container.removeEventListener('wheel', this.onWheelScroll);
    container.removeEventListener('pointerdown', this.onPointerDown);
    container.removeEventListener('pointermove', this.onPointerMove);
    window.removeEventListener('pointerup', this.onPointerUp);
  },

  /** Scrolls back to the start and updates the arrows. */
  reset() {
    this.scrollCount = this.offset = 0;
    this.reposition_();
    this.marginWidthLeft = this.marginWidthRight = this.minComponentWidth = 0;
    if (this.initialStartIndex > 0) afterNextRender(this, () => this.setStartIndex(this.initialStartIndex));
  },

  /** Applies the offset to the items. */
  reposition_() {
    const sign = getConfig('HTML_DIR') === 'rtl' ? '' : '-';
    const items = hostDom(this.hostElement).querySelector('#items');
    if (items) /** @type {!HTMLElement} */ (items).style.transform = `translateX(${sign}${this.offset}px)`;
    this.requestButtonsStateUpdate_();
  },

  /** Updates the arrows after the next render, once per request. */
  requestButtonsStateUpdate_() {
    if (this.setButtonsStateRequested) return;
    this.setButtonsStateRequested = true;
    afterNextRender(this, () => this.setButtonsState_());
  },

  /** Hides the arrow of an end that the list has reached. */
  setButtonsState_() {
    this.setButtonsStateRequested = false;
    const first = itemsElement(this).firstElementChild;
    if (!first) return;
    if (!this.minComponentWidth) this.minComponentWidth = this.getMinComponentWidth(first);
    const width = scrollContainer(this).clientWidth;
    const scrollWidth = itemsElement(this).scrollWidth;
    const items = this.get(itemsPathOfElement(this), this);
    if (items) {
      const visibleCount = Math.round(width / this.minComponentWidth) || 1;
      if (this.fullyVisibleItemsIndices.length === 0) {
        this.startIndex = Math.round(this.offset / this.minComponentWidth);
        this.endIndex = Math.min(this.startIndex + visibleCount, items.length) - 1;
      }
    }
    if (this.canShowMore) {
      if (scrollWidth + this.minComponentWidth >= this.offset + width) this.atEnd = false;
    } else {
      this.atEnd = this.offset + width >= scrollWidth - 20;
    }
    this.atStart = this.offset <= 20;
  },

  /** @param {number} index */
  setStartIndex(index) {
    if (!this.minComponentWidth) {
      const first = itemsElement(this).firstElementChild;
      if (!first) return;
      this.minComponentWidth = this.getMinComponentWidth(first);
    }
    this.fillRemainingListItems();
    this.offset = this.minComponentWidth * index;
    this.ensureWithinScrollBounds();
    this.reposition_();
  },

  /** Scrolls forward by the whole items that fit in the container, showing every item first. */
  nextClick_() {
    this.fillRemainingListItems();
    flush();
    const width = scrollContainer(this).clientWidth;
    if (!this.minComponentWidth) this.minComponentWidth = this.getMinComponentWidth(itemsElement(this).firstElementChild);
    const count = this.useFloorScrolling ? Math.floor(width / this.minComponentWidth) || 1 : Math.round(width / this.minComponentWidth) || 1;
    if (this.centerListItems && this.scrollCount === 0) this.centerListItem();
    this.offset += this.useItemsFullVisibility() ? this.getFullyVisibleItemsWidthPixels() : count * this.minComponentWidth;
    this.ensureWithinScrollBounds();
    this.reposition_();
    this.scrollCount++;
  },

  /** Scrolls back by the whole items that fit in the container. */
  prevClick_() {
    const width = scrollContainer(this).clientWidth;
    const count = this.useFloorScrolling ? Math.floor(width / this.minComponentWidth) || 1 : Math.round(width / this.minComponentWidth) || 1;
    if (this.resizeSupportEnabled) {
      this.scrollCount--;
      this.offset = this.useItemsFullVisibility() ? this.getFullyVisibleItemsWidthPixels() : this.minComponentWidth * this.scrollCount - 1;
    } else {
      this.offset -= this.useItemsFullVisibility() ? this.getFullyVisibleItemsWidthPixels() : count * this.minComponentWidth;
    }
    if (this.centerListItems) this.centerListItem();
    this.ensureWithinScrollBounds();
    this.reposition_();
  },

  onIronResize_() {
    if (this.resizeSupportEnabled) afterNextRender(this, () => this.checkComponentWidthResize());
    if (!flag('web_horizontal_list_resize_fill_ks')) afterNextRender(this, () => this.maybeLoadToFillContainer());
    this.requestButtonsStateUpdate_();
  },

  /** @param {!Event} e */
  onItemsTransitionEnd_(e) {
    if (e.composedPath()[0] === itemsElement(this)) this.markDirty();
  },

  /** @param {!Event} e */
  onChildElementFocus_(e) {
    const target = /** @type {?HTMLElement} */ (/** @type {!Element} */ (e.target).closest('#items > *'));
    const container = scrollContainer(this);
    if (!target || !container.contains(target)) return;
    if (flag('web_horizontal_list_behavior_focus_killswitch')) {
      if (target.offsetLeft < this.offset) {
        this.offset = Math.abs(target.offsetLeft) < target.clientWidth ? 0 : target.offsetLeft;
      } else if (target.offsetLeft + target.clientWidth > this.offset + container.clientWidth) {
        this.fillRemainingListItems();
        flush();
        this.offset = target.offsetLeft + target.clientWidth - container.clientWidth;
      } else {
        return;
      }
    } else {
      const items = itemsElement(this);
      const rtl = getConfig('HTML_DIR') === 'rtl';
      const start = rtl ? items.clientWidth - target.offsetLeft : target.offsetLeft;
      const end = rtl ? items.clientWidth - (target.offsetLeft + target.clientWidth) : target.offsetLeft + target.clientWidth;
      const beforeView = rtl ? start > this.offset + container.clientWidth : start < this.offset;
      const afterView = rtl ? end < this.offset : end > this.offset + container.clientWidth;
      const scrollBack = rtl ? beforeView : afterView;
      if (rtl ? afterView : beforeView) {
        const edge = rtl ? end : start;
        this.offset = Math.abs(edge) < target.clientWidth ? 0 : edge;
      } else if (scrollBack) {
        this.fillRemainingListItems();
        flush();
        this.offset = (rtl ? start : end) - container.clientWidth;
      } else {
        return;
      }
    }
    this.ensureWithinScrollBounds();
    this.reposition_();
  },

  observeShownItems_() {
    this.reset();
  },

  maybeLoadToFillContainer() {
    const outer = hostDom(this.hostElement).querySelector('#scroll-outer-container');
    const outerWidth = outer && outer.clientWidth;
    const itemsWidth = itemsElement(this) && itemsElement(this).clientWidth;
    if (outerWidth && itemsWidth && itemsWidth < outerWidth) this.fillRemainingListItems();
  },

  checkComponentWidthResize() {
    const first = itemsElement(this).firstElementChild;
    if (!first) return;
    const width = this.getMinComponentWidth(first);
    if (!this.centerListItems && width === this.minComponentWidth) return;
    this.minComponentWidth = width;
    this.offset = width * this.scrollCount;
    if (this.centerListItems) this.centerListItem();
    this.ensureWithinScrollBounds();
    this.reposition_();
  },

  /**
   * The width of an item with its right margin.
   * @param {!Element} item
   * @return {number}
   */
  getMinComponentWidth(item) {
    const marginRight = Math.floor(Number(window.getComputedStyle(item).marginRight.replace('px', '')));
    const marginLeft = Math.floor(Number(window.getComputedStyle(item).marginLeft.replace('px', '')));
    if (this.centerListItems && !this.marginWidthRight) {
      this.marginWidthRight = marginRight;
      this.marginWidthLeft = marginLeft;
    }
    return this.resizeSupportEnabled ? item.getBoundingClientRect().width + marginRight : /** @type {!HTMLElement} */ (item).offsetWidth + marginRight;
  },

  ensureWithinScrollBounds() {
    const width = scrollContainer(this).clientWidth;
    const itemsWidth = itemsElement(this).clientWidth;
    if (this.offset < 0) this.offset = 0;
    else if (this.offset + width >= itemsWidth) this.offset = itemsWidth - width;
  },

  centerListItem() {
    this.offset -= (scrollContainer(this).clientWidth + this.marginWidthRight - this.minComponentWidth) / 2 - this.marginWidthLeft;
  },

  /**
   * How many items of a list render at once: the first lists get as many as
   * fit the window's first rows, the others none (kevlar's stateful getter,
   * which the lazy list reads and assigns `-1` to; the setter ignores it).
   * @return {number}
   */
  get nonDeferredItemCount() {
    let rows = /** @type {number} */ (getConfig('NON_DEFERRED_HORIZONTAL_LIST_ROW_COUNT', -1));
    if (rows === -1) {
      const height = this['JSC$18343_cachedViewportHeight'];
      rows = height > 1320 ? 5 : height > 1020 ? 4 : height > 730 ? 3 : height > 430 ? 2 : 1;
    } else if (rows === 0) {
      return 0;
    }
    setConfig('NON_DEFERRED_HORIZONTAL_LIST_ROW_COUNT', rows - 1);
    let count = /** @type {number} */ (getConfig('NON_DEFERRED_HORIZONTAL_LIST_ITEM_COUNT', -1));
    if (count > -1) return count;
    const width = this.cachedViewportWidth;
    count = width > 1600 ? 6 : width > 1400 ? 5 : width > 1300 ? 4 : width > 1090 ? 5 : width > 870 ? 4 : width > 660 ? 3 : 2;
    setConfig('NON_DEFERRED_HORIZONTAL_LIST_ITEM_COUNT', count);
    return count;
  },

  /** @param {number} value */
  set nonDeferredItemCount(value) {},

  /** @return {boolean} */
  get resizeSupportEnabled() {
    return !flag('kevlar_disable_component_resizing_support') && !!this.supportComponentResize;
  },
};

/** @const {!Array<!Object>} */
export const HorizontalListBehavior = [IronResizableBehavior, ...RendererBehavior, LazyListBehavior, ...GuideStateAwareBehavior,
  HorizontalListScrollBehavior];
