/**
 * @fileoverview The PolySi lifecycle bridge. PolySi hosts have no native
 * lifecycle callbacks. Instead, the DOM insertion and removal methods of
 * `Node`, `Element`, `Document`, `DocumentFragment`, `ShadowRoot` and
 * ShadyDOM's `Wrapper` are patched: after a node is inserted into a
 * connected parent, every element in its subtree is visited, and PolySi
 * hosts that are not connected yet get their controller's
 * `connectedCallback` called. Removal and moves do the same for
 * `disconnectedCallback`. The attribute methods forward changes of
 * observed attributes to the controller.
 *
 * With `ShadyDOM.noPatch`, ShadyDOM performs its physical DOM operations
 * through its own saved copies of the native methods. Those copies are
 * replaced by the patched methods, so insertions made through
 * `ShadyDOM.wrap` run the lifecycle too.
 */
import {runUntracked} from '../vm/effect.js';
import {traceSpan} from '../trace.js';

/**
 * @param {!Element} el
 * @return {boolean}
 */
function isRepeat(el) {
  return el.tagName === 'PS-DOM-REPEAT' || el.tagName === 'DOM-REPEAT';
}

/**
 * @param {!Node} node
 * @return {!Array<!Element>}
 */
function subtreeElements(node) {
  let qsa = null;
  if (node instanceof Element) qsa = Element.prototype.querySelectorAll;
  else if (node instanceof DocumentFragment) qsa = DocumentFragment.prototype.querySelectorAll;
  return qsa ? Array.from(qsa.call(node, '*')) : [];
}

/**
 * The PolySi hosts in and under `node` whose connected state is
 * `connected`, including the instances of repeats.
 * @param {!Node} node
 * @param {boolean} connected
 * @return {!Array<!Element>}
 */
function lifecycleTargets(node, connected) {
  const list = subtreeElements(node);
  if (node instanceof Element) list.unshift(node);
  for (const repeat of list.filter(isRepeat)) {
    for (const inst of repeat.__instances || []) {
      if (!inst.root) continue;
      for (const child of Array.from(inst.root.children)) list.push(...lifecycleTargets(child, connected));
    }
  }
  return list.filter(el => el.usePatchedLifecycles && el.lifecycleIsConnected === connected);
}

/**
 * Calls `connectedCallback` on the hosts in and under `node`.
 * @param {!Node} node
 */
function connectTree(node) {
  runUntracked(() => {
    for (const el of lifecycleTargets(node, false)) {
      el.lifecycleIsConnected = true;
      try {
        const target = el.polymerController != null ? el.polymerController : el;
        if (target.connectedCallback) traceSpan('polymerComponent', target.connectedCallback.bind(target));
      } catch (e) {
        console.error(e);
      }
    }
  });
}

/**
 * Calls `disconnectedCallback` on the hosts in and under `node`.
 * @param {!Node} node
 */
function disconnectTree(node) {
  runUntracked(() => {
    for (const el of lifecycleTargets(node, true)) {
      el.lifecycleIsConnected = false;
      try {
        const target = el.polymerController != null ? el.polymerController : el;
        if (target.disconnectedCallback) target.disconnectedCallback();
      } catch (e) {
        console.error(e);
      }
    }
  });
}

/**
 * Splits the arguments of `append`-like methods into the nodes that end up
 * inserted and the connected elements that move.
 * @param {!Array<*>} args
 * @return {!Array<!Array<*>>}
 */
function splitInserted(args) {
  const inserted = [];
  const moved = [];
  for (const a of args) {
    if (a instanceof DocumentFragment) {
      inserted.push(...Array.from(a.children));
    } else {
      inserted.push(a);
      if (a instanceof Element && a.isConnected) moved.push(a);
    }
  }
  return [inserted, moved];
}

/**
 * Wraps an `append`-like method.
 * @param {!Function} native
 * @return {!Function}
 */
function wrapInsertion(native) {
  return function(...args) {
    const [inserted, moved] = splitInserted(args);
    native.apply(this, args);
    for (const el of moved) disconnectTree(el);
    if (this.isConnected) {
      for (const n of inserted) {
        if (n instanceof Element) connectTree(n);
      }
    }
  };
}

/**
 * The element behind a ShadyDOM wrapper, or `x` itself.
 * @param {*} x
 * @return {!Element}
 */
function unwrap(x) {
  const Wrapper = window.ShadyDOM && window.ShadyDOM.Wrapper;
  return Wrapper && x instanceof Wrapper ? x.node : x;
}

/**
 * @param {!Element} el
 * @param {string} name
 * @param {?string} oldValue
 * @param {?string} newValue
 */
function forwardAttributeChange(el, name, oldValue, newValue) {
  const ctrl = el.polymerController;
  if (!ctrl || !ctrl.observedAttributes || !ctrl.observedAttributes.includes(name)) return;
  if (ctrl.attributeChangedCallbackWrapper) ctrl.attributeChangedCallbackWrapper(name, oldValue, newValue);
  else if (ctrl.attributeChangedCallback) ctrl.attributeChangedCallback(name, oldValue, newValue, null);
}

/** @param {!Function} proto */
function patchChildMethods(proto) {
  const p = proto.prototype;
  const nativeInsertBefore = p.insertBefore;
  const isNodeLevel = proto === Node;
  p.insertBefore = function(child, ref) {
    if (child instanceof DocumentFragment) {
      const children = Array.from(child.children);
      const result = nativeInsertBefore.call(this, child, ref);
      if (this.isConnected && isNodeLevel) {
        for (const c of children) connectTree(c);
      }
      return result;
    }
    const wasConnected = child instanceof Element && child.isConnected;
    const result = nativeInsertBefore.call(this, child, ref);
    if (wasConnected) disconnectTree(child);
    if (this.isConnected) connectTree(child);
    return result;
  };
  const nativeAppendChild = p.appendChild;
  p.appendChild = function(child) {
    if (child instanceof DocumentFragment) {
      const children = Array.from(child.children);
      const result = nativeAppendChild.call(this, child);
      if (this.isConnected) {
        for (const c of children) connectTree(c);
      }
      return result;
    }
    const wasConnected = child instanceof Element && child.isConnected;
    const result = nativeAppendChild.call(this, child);
    if (wasConnected) disconnectTree(child);
    if (this.isConnected) connectTree(child);
    return result;
  };
  const nativeRemoveChild = p.removeChild;
  p.removeChild = function(child) {
    const wasConnected = child instanceof Element && child.isConnected;
    const result = nativeRemoveChild.call(this, child);
    if (wasConnected && isNodeLevel) disconnectTree(child);
    return result;
  };
  const nativeReplaceChild = p.replaceChild;
  p.replaceChild = function(child, old) {
    if (child instanceof DocumentFragment) {
      const children = Array.from(child.children);
      const result = nativeReplaceChild.call(this, child, old);
      if (this.isConnected) {
        disconnectTree(old);
        for (const c of children) connectTree(c);
      }
      return result;
    }
    const wasConnected = child instanceof Element && child.isConnected;
    const parentConnected = this.isConnected;
    const result = nativeReplaceChild.call(this, child, old);
    if (parentConnected) disconnectTree(old);
    if (wasConnected) disconnectTree(child);
    if (parentConnected) connectTree(child);
    return result;
  };
}

/** @param {!Function} proto */
function patchElementMethods(proto) {
  const p = proto.prototype;
  p.before = wrapInsertion(p.before);
  p.after = wrapInsertion(p.after);
  const nativeReplaceWith = p.replaceWith;
  p.replaceWith = function(...args) {
    const [inserted, moved] = splitInserted(args);
    const wasConnected = this.isConnected;
    nativeReplaceWith.apply(this, args);
    for (const el of moved) disconnectTree(el);
    if (wasConnected) {
      disconnectTree(this);
      for (const n of inserted) {
        if (n instanceof Element) connectTree(n);
      }
    }
  };
  const nativeRemove = p.remove;
  p.remove = function() {
    const wasConnected = this.isConnected;
    nativeRemove.call(this);
    if (wasConnected) disconnectTree(this);
  };
  const nativeInsertAdjacentElement = p.insertAdjacentElement;
  p.insertAdjacentElement = function(where, el) {
    const wasConnected = el.isConnected;
    const result = nativeInsertAdjacentElement.call(this, where, el);
    if (wasConnected) disconnectTree(el);
    if (result.isConnected) connectTree(result);
    return result;
  };
  const nativeSetAttribute = p.setAttribute;
  p.setAttribute = function(name, value) {
    const el = unwrap(this);
    if (!el.usePatchedLifecycles) return nativeSetAttribute.call(this, name, value);
    const old = this.getAttribute(name);
    nativeSetAttribute.call(this, name, value);
    forwardAttributeChange(el, name, old, this.getAttribute(name));
  };
  const nativeRemoveAttribute = p.removeAttribute;
  p.removeAttribute = function(name) {
    const el = unwrap(this);
    if (!el.usePatchedLifecycles) return nativeRemoveAttribute.call(this, name);
    const old = this.getAttribute(name);
    nativeRemoveAttribute.call(this, name);
    if (old !== null) forwardAttributeChange(el, name, old, null);
  };
  const nativeToggleAttribute = p.toggleAttribute;
  p.toggleAttribute = function(name, force) {
    const el = unwrap(this);
    if (!el.usePatchedLifecycles) return nativeToggleAttribute.call(this, name, force);
    const old = this.getAttribute(name);
    const had = old !== null;
    const result = nativeToggleAttribute.call(this, name, force);
    if (result !== had) forwardAttributeChange(el, name, old, result ? '' : null);
    return result;
  };
}

/** Child-list methods whose ShadyDOM native copies are replaced. */
const SHADY_NATIVE_METHODS = ['appendChild', 'insertBefore', 'removeChild', 'replaceChild'];

let installed = false;

/** Installs the patched DOM methods. */
export function installLifecyclePatches() {
  if (installed) return;
  installed = true;
  const shady = window.ShadyDOM;
  const Wrapper = shady && shady.Wrapper;
  const childTypes = [Node];
  if (Wrapper) childTypes.push(Wrapper);
  for (const type of childTypes) patchChildMethods(type);
  const elementTypes = [Element];
  if (Wrapper) elementTypes.push(Wrapper);
  for (const type of elementTypes) patchElementMethods(type);
  const parentTypes = [Document, DocumentFragment, Element, ShadowRoot];
  if (Wrapper) parentTypes.push(Wrapper);
  for (const type of parentTypes) {
    type.prototype.prepend = wrapInsertion(type.prototype.prepend);
    type.prototype.append = wrapInsertion(type.prototype.append);
  }
  if (shady && shady.noPatch === true) {
    const proto = Node.prototype;
    for (const name of SHADY_NATIVE_METHODS) {
      const desc = Object.getOwnPropertyDescriptor(proto, name);
      if (desc) Object.defineProperty(proto, `__shady_native_${name}`, desc);
    }
  }
  if (document.readyState === 'complete') {
    connectTree(document.body);
  } else {
    document.addEventListener('readystatechange', () => {
      if (document.readyState === 'complete') connectTree(document.body);
    });
  }
  const innerText = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'innerText');
  if (innerText && innerText.get && innerText.set) {
    Object.defineProperty(HTMLElement.prototype, 'innerText', {
      enumerable: innerText.enumerable,
      configurable: true,
      get: innerText.get,
      set(value) {
        if (!value) disconnectTree(this);
        innerText.set.call(this, value);
      },
    });
  }
}
