/**
 * @fileoverview Response handling: parses InnerTube responses, runs the
 * response processors (generators that yield commands), and resolves
 * commands into `yt-action` events or navigations.
 */
import {fireAction} from '../framework/actions.js';
import {endpointKind, flattenCommand} from '../framework/endpoints.js';
import {applyEntityMutations} from './entities.js';
import {countResponse} from './telemetry.js';
import {adsOpportunityReceived} from './logging.js';

/** Maps command keys to the actions the app element handles. */
const COMMAND_ACTIONS = {
  'appendContinuationItemsAction': 'yt-append-continuation-items-action',
  'reloadContinuationItemsCommand': 'yt-reload-continuation-items-command',
  'showReloadUiCommand': 'yt-show-reload-ui-command',
  'signalServiceEndpoint': 'yt-signal-action',
  'playlistEditEndpoint': 'yt-playlist-edit-action',
  'shareEntityServiceEndpoint': 'yt-share-action',
  'openPopupAction': 'yt-open-popup-action',
  'continuationCommand': 'yt-continuation-command',
  'feedbackEndpoint': 'yt-feedback-action',
};

const NAVIGATIONS = new Set(['watchEndpoint', 'browseEndpoint', 'searchEndpoint', 'reelWatchEndpoint', 'watchPlaylistEndpoint', 'urlEndpoint']);

/**
 * @typedef {{
 *   response: !Object,
 *   source: !Element,
 *   kind: string,
 *   commands: !Array<!Object>,
 *   stats: {commands: number, mutations: number},
 * }}
 */
export let ResponseContext;

/**
 * @param {!ResponseContext} ctx
 * @return {!Iterator<!Object>}
 */
function* responseContextProcessor(ctx) {
  const rc = ctx.response.responseContext;
  if (!rc) return;
  for (const param of (rc.serviceTrackingParams || [])) {
    for (const p of (param.params || [])) {
      if (p.key === 'logged_in' && p.value === '1') yield {signalServiceEndpoint: {signal: 'CLIENT_SIGNAL', loggedIn: true}};
    }
  }
}

/**
 * @param {!ResponseContext} ctx
 * @return {!Iterator<!Object>}
 */
function* frameworkUpdatesProcessor(ctx) {
  const fu = ctx.response.frameworkUpdates;
  const mutations = fu && fu.entityBatchUpdate && fu.entityBatchUpdate.mutations;
  if (!mutations) return;
  ctx.stats.mutations += applyEntityMutations(mutations);
  yield* [];
}

/**
 * @param {!ResponseContext} ctx
 * @return {!Iterator<!Object>}
 */
function* receivedCommandsProcessor(ctx) {
  const r = ctx.response;
  for (const list of [r.onResponseReceivedCommands, r.onResponseReceivedActions, r.onResponseReceivedEndpoints]) {
    if (!list) continue;
    for (const command of list) yield command;
  }
}

const PROCESSORS = [responseContextProcessor, frameworkUpdatesProcessor, receivedCommandsProcessor];

/**
 * Parses `text` and runs the response processors. Returns the parsed
 * response; commands are resolved against `source`.
 * @param {string} text
 * @param {!Element} source
 * @param {string} kind
 * @return {!Object}
 */
export function handleResponse(text, source, kind) {
  return processResponse(/** @type {!Object} */ (JSON.parse(text)), source, kind);
}

/**
 * Parses a get_watch response, an array of a player part and a watch-next
 * part, and runs the response processors over each part.
 * @param {string} text
 * @param {!Element} source
 * @return {{playerResponse: ?Object, response: !Object}}
 */
export function handleWatchResponse(text, source) {
  const parts = /** @type {!Array<!Object>} */ (JSON.parse(text));
  let playerResponse = null;
  let response = {};
  for (const part of parts) {
    if (part.playerResponse) playerResponse = processResponse(part.playerResponse, source, 'watch-player');
    else if (part.watchNextResponse) response = processResponse(part.watchNextResponse, source, 'watch');
  }
  return {playerResponse, response};
}

/**
 * Runs the response processors over a parsed response. Commands are
 * resolved against `source`.
 * @param {!Object} response
 * @param {!Element} source
 * @param {string} kind
 * @return {!Object}
 */
function processResponse(response, source, kind) {
  countResponse(response.responseContext ? 'ok' : 'missing');
  /** @type {!ResponseContext} */
  const ctx = {response, source, kind, commands: [], stats: {commands: 0, mutations: 0}};
  for (const processor of PROCESSORS) {
    for (const command of processor(ctx)) ctx.commands.push(command);
  }
  for (const command of ctx.commands) {
    resolveCommand(source, command);
    ctx.stats.commands++;
  }
  return response;
}

/**
 * Resolves one command: fires the matching action, or a navigation.
 * @param {!Element} source
 * @param {?Object|undefined} command
 * @return {boolean} Whether anything handled it.
 */
export function resolveCommand(source, command) {
  let handled = false;
  for (const c of flattenCommand(command)) {
    const kind = endpointKind(c);
    if (kind && NAVIGATIONS.has(kind)) {
      source.dispatchEvent(new CustomEvent('yt-navigate', {bubbles: true, composed: true, detail: {endpoint: c}}));
      handled = true;
      continue;
    }
    for (const key in c) {
      if (key === 'adsControlFlowOpportunityReceivedCommand') {
        adsOpportunityReceived(c[key]);
        handled = true;
        continue;
      }
      const action = COMMAND_ACTIONS[key];
      if (!action) continue;
      fireAction(source, action, [c[key], c]);
      handled = true;
    }
  }
  return handled;
}
