/**
 * @fileoverview Helpers for InnerTube text objects: `{simpleText}` or
 * `{runs: [{text, bold, italics, navigationEndpoint}]}`, plus accessibility
 * wrappers.
 */

/**
 * @typedef {{
 *   text: string,
 *   bold: (boolean|undefined),
 *   italics: (boolean|undefined),
 *   strikethrough: (boolean|undefined),
 *   navigationEndpoint: (!Object|undefined),
 * }}
 */
export let TextRun;

/**
 * @typedef {{simpleText: (string|undefined), runs: (!Array<!TextRun>|undefined), accessibility: (!Object|undefined)}}
 */
export let FormattedText;

/**
 * @param {?FormattedText|undefined} text
 * @return {string}
 */
export function getText(text) {
  if (!text) return '';
  if (text.simpleText != null) return text.simpleText;
  const runs = text.runs;
  if (!runs) return '';
  let out = '';
  for (const run of runs) out += run.text;
  return out;
}

/**
 * @param {?FormattedText|undefined} text
 * @return {!Array<!TextRun>}
 */
export function getRuns(text) {
  if (!text) return [];
  if (text.runs) return text.runs;
  if (text.simpleText != null) return [{text: text.simpleText}];
  return [];
}

/**
 * @param {?Object|undefined} holder An object with `accessibility` or
 *     `accessibilityData`.
 * @return {string}
 */
export function getAccessibilityLabel(holder) {
  if (!holder) return '';
  const acc = holder.accessibility || holder;
  const data = acc.accessibilityData || acc;
  return typeof data.label === 'string' ? data.label : '';
}

/**
 * @param {?FormattedText|undefined} text
 * @return {boolean}
 */
export function isEmptyText(text) {
  return getText(text).trim() === '';
}

/**
 * @param {?FormattedText|undefined} text
 * @return {boolean}
 */
export function hasLinks(text) {
  const runs = text && text.runs;
  if (!runs) return false;
  for (const run of runs) if (run.navigationEndpoint) return true;
  return false;
}

/**
 * Splits an "attributed string" (`{content, styleRuns, commandRuns}`) into
 * ranges with their style and command.
 * @param {?Object|undefined} attributed
 * @return {!Array<{text: string, style: ?Object, command: ?Object}>}
 */
export function attributedRanges(attributed) {
  if (!attributed || typeof attributed.content !== 'string') return [];
  const content = /** @type {string} */ (attributed.content);
  const styleRuns = attributed.styleRuns || [];
  const commandRuns = attributed.commandRuns || [];
  if (!styleRuns.length && !commandRuns.length) return [{text: content, style: null, command: null}];
  const cuts = new Set([0, content.length]);
  for (const r of styleRuns) {
    cuts.add(r.startIndex || 0);
    cuts.add((r.startIndex || 0) + (r.length || 0));
  }
  for (const r of commandRuns) {
    cuts.add(r.startIndex || 0);
    cuts.add((r.startIndex || 0) + (r.length || 0));
  }
  const points = [...cuts].filter(p => p >= 0 && p <= content.length).sort((a, b) => a - b);
  const out = [];
  for (let i = 0; i + 1 < points.length; i++) {
    const start = points[i], end = points[i + 1];
    if (start === end) continue;
    const style = styleRuns.find(r => (r.startIndex || 0) <= start && start < (r.startIndex || 0) + (r.length || 0)) || null;
    const command = commandRuns.find(r => (r.startIndex || 0) <= start && start < (r.startIndex || 0) + (r.length || 0)) || null;
    out.push({text: content.slice(start, end), style, command});
  }
  return out;
}
