import {flattenCommand} from '../../framework/endpoints.js';
import {flag, flagNumber} from '../../framework/flags.js';
import {rootInjector} from '../../framework/injector.js';
import {linkConfig} from '../../framework/link.js';
import {registerRenderer} from '../../framework/registry.js';
