/**
 * Runs the first-visible command of an ad component's interaction.
 * @param {?Object|undefined} interaction
 */
function runFirstVisible(interaction) {
  for (const cmd of flattenCommand(interaction && interaction.onFirstVisible)) logAdEvent('first-visible', cmd);
}

/**
 * Starts active-view measurement for a layout.
 * @param {!Element} el
 * @param {?Object|undefined} view
 */
function startActiveView(el, view) {
  if (!view) return;
  for (const cmd of flattenCommand(view.viewableCommand)) logAdEvent('viewable', cmd);
  logAdEvent('identifier', {id: view.identifier, tag: el.localName});
}

/**
 * Ends active-view measurement for a layout.
 * @param {?Object|undefined} view
 */
function stopActiveView(view) {
  if (!view) return;
  for (const cmd of flattenCommand(view.endOfSessionCommand)) logAdEvent('end-of-session', cmd);
}

/**
 * The visibility ref of an ad component: its first-visible command.
 * @param {function(): !Object} vm
 * @return {function(!Element)}
 */
function adVisibility(vm) {
  return useVisibility({onVisible: () => runFirstVisible(vm().interaction)});
}

/**
 * The visibility ref of an ad layout: the first-visible command, then
 * active-view measurement while the layout is shown.
 * @param {function(): !Object} vm
 * @return {function(!Element)}
 */
function layoutVisibility(vm) {
  return useVisibility({
    onVisible: (el) => {
      runFirstVisible(vm().interaction);
      const data = vm().adLayoutData;
      startActiveView(el, data && data.activeViewData);
    },
    onHidden: () => {
      const data = vm().adLayoutData;
      if (flag('stop_av_measurement_on_detach')) stopActiveView(data && data.activeViewData);
    },
  });
}

/**
 * @param {!Object} vm
 * @return {boolean}
 */
function isClickable(vm) {
  return !!(vm.interaction && vm.interaction.onTap);
}


/**
 * Ad avatar size (`Gj8`).
 * @param {string|undefined} size
 * @return {string}
 */
function adAvatarSize(size) {
  switch (size) {
    case 'AD_AVATAR_SIZE_XXS':
      return 'tiny';
    case 'AD_AVATAR_SIZE_XS':
      return 'extra-small';
    case 'AD_AVATAR_SIZE_S':
      return 'small';
    case 'AD_AVATAR_SIZE_M':
      return 'medium';
    case 'AD_AVATAR_SIZE_MPLUS':
      return '48';
    case 'AD_AVATAR_SIZE_L':
      return 'large';
    case 'AD_AVATAR_SIZE_XL':
      return 'extra-large';
    default:
      return 'medium';
  }
}

/**
 * @param {string|undefined} style
 * @return {number} 1 for rounded corners, 0 for a circle.
 */
function adAvatarType(style) {
  switch (style) {
    case 'AD_AVATAR_STYLE_ROUNDED_CORNER':
      return 1;
    default:
      return 0;
  }
}

/** The avatar shape of an ad avatar. */
const AdAvatarShape = defineComponent((props) => {
  const config = () => unwrap(props.data) || {};
  const size = () => config().size || 'medium';
  const tappable = () => typeof config().onTap === 'function';
  return h('ytl-avatar-shape', null,
    h('div', {
      class: classes('ytlSpecAvatarShapeHost', () => (tappable() ? 'ytlSpecAvatarShapeButton' : ''),
          () => avatarShapeSizeClass(size(), tappable()), {
            'ytlSpecAvatarShapeTappable': tappable,
            'ytlSpecAvatarShapeRoundedCorner': () => config().type === 1,
          }),
      role: () => (tappable() ? 'button' : undefined),
      tabindex: () => (tappable() ? '0' : undefined),
      'aria-label': () => config().accessibilityText,
      'on:click': (/** !Event */ e) => {
        const tap = config().onTap;
        if (typeof tap === 'function') tap(e);
      },
    },
    h('div', null,
      h('div', {class: () => avatarSizeClass(size())},
        h(Image, {data: () => ({sources: (unwrap(props.image) || {}).sources || []}), targetWidth: () => avatarPixels(size()),
          imageClassName: 'ytlSpecAvatarShapeImage', fillParentWidth: true, fillParentHeight: true, contentMode: 'fill', alt: ''}),
        cond(() => !!config().liveData, () => h('div', {class: 'ytlSpecAvatarShapeLiveBadge'})),
        cond(() => !!config().hasRing, () => h('div', {class: 'ytlSpecAvatarShapeRing'})),
        cond(() => !!config().overlay, () => h('div', {class: 'ytlSpecAvatarShapeOverlay'})),
        cond(() => !!config().badge, () => h('div', {class: 'ytlSpecAvatarShapeBadge'}))))));
}, 'njB');

/** The ad avatar (`ad-avatar-view-model`). */
export const AdAvatar = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const tap = () => (isClickable(vm()) ? (/** !Event */ e) => {
    const custom = unwrap(props.customCommandResolver);
    const command = vm().interaction.onTap;
    if (typeof custom === 'function') custom(command);
    else fireCommand(/** @type {!Element} */ (e.currentTarget), innertubeOf(command));
  } : undefined);
  const config = () => {
    const v = vm();
    return {size: adAvatarSize(v.size), type: adAvatarType(v.style), onTap: tap(), accessibilityText: contextLabel(v.rendererContext)};
  };
  return h('ytl-ad-avatar-view-model', {
    class: () => (isClickable(vm()) ? 'ytlAdAvatarViewModelHostIsClickableAdComponent' : 'ytlAdAvatarViewModelHost'),
    ref: adVisibility(vm),
  }, cond(() => vm().image, () => h(AdAvatarShape, {data: config, image: () => vm().image})));
}, 'FA');

