/** The feed-ad metadata (`feed-ad-metadata-view-model`). */
export const FeedAdMetadata = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const [tapped, setTapped] = signal(false, 'cEhXFe');
  return h('ytl-feed-ad-metadata-view-model', {
    class: () => (isClickable(vm()) ? 'ytlFeedAdMetadataViewModelHostIsClickableAdComponent' : 'ytlFeedAdMetadataViewModelHost'),
    ref: mergeRefs(adVisibility(vm), useInteraction(() => vm().interaction, undefined, () => unwrap(props.listenToTapEvent) !== false)),
    'on:touchend': (/** !Event */ e) => {
      if (unwrap(props.setTouchEndHandler) && !tapped()) {
        /** @type {!HTMLElement} */ (e.currentTarget).click();
        setTapped(true);
        setTimeout(() => setTapped(false), 100);
      }
      e.stopPropagation();
    },
  }, h(Switch, {
    value: () => vm().style,
    cases: [
      ['FEED_AD_METADATA_STYLE_COMPACT', () => h(CompactAdMetadata, {data: vm, typographyBump: props.typographyBump})],
      ['FEED_AD_METADATA_STYLE_STANDARD', () => h(StandardAdMetadata, {data: vm, noBottomMargin: props.noBottomMargin,
        useVideoLockupTopPadding: props.useVideoLockupTopPadding, typographyBump: props.typographyBump})],
    ],
  }));
}, 'OA');

/**
 * Ad button style to button-shape type and style (`WsS`).
 * @param {string|undefined} style
 * @return {{type: string, style: string}}
 */
function adButtonStyle(style) {
  switch (style) {
    case 'AD_BUTTON_STYLE_FILLED':
      return {type: 'filled', style: 'call-to-action'};
    case 'AD_BUTTON_STYLE_MONO_FILLED':
      return {type: 'filled', style: 'mono'};
    case 'AD_BUTTON_STYLE_MONO_TONAL':
      return {type: 'tonal', style: 'mono'};
    case 'AD_BUTTON_STYLE_MONO_OUTLINE':
      return {type: 'outline', style: 'mono'};
    case 'AD_BUTTON_STYLE_OVERLAY_TEXT':
      return {type: 'text', style: 'overlay'};
    case 'AD_BUTTON_STYLE_OVERLAY_TONAL':
      return {type: 'tonal', style: 'overlay'};
    case 'AD_BUTTON_STYLE_BRAND':
      return {type: 'filled', style: 'brand'};
    case 'AD_BUTTON_STYLE_TRANSPARENT':
      return {type: 'text', style: 'mono'};
    default:
      return {type: 'tonal', style: 'mono'};
  }
}

/**
 * @param {string|undefined} size
 * @return {string}
 */
function adButtonSize(size) {
  switch (size) {
    case 'AD_BUTTON_SIZE_SMALL':
      return 'S';
    case 'AD_BUTTON_SIZE_LARGE':
      return 'L';
    case 'AD_BUTTON_SIZE_EXTRA_SMALL':
      return 'XS';
    default:
      return 'M';
  }
}

/**
 * The button-shape config of an ad button.
 * @param {!Object} vm
 * @param {*} resolver
 * @return {!Object}
 */
function adButtonConfig(vm, resolver) {
  const command = vm.interaction && vm.interaction.onTap;
  const link = linkConfig(innertubeOf(command));
  const s = adButtonStyle(vm.style);
  const position = vm.iconImage ? (vm.label && vm.label.content ? (vm.iconLeading ? 'leading' : 'trailing') : 'icon-only') : undefined;
  return {
    type: s.type,
    style: s.style,
    size: adButtonSize(vm.size),
    iconPosition: position,
    formattedButtonText: vm.label ? {content: vm.label.content, noWrap: true} : null,
    accessibilityLabel: (vm.interaction && vm.interaction.accessibility && vm.interaction.accessibility.label) || '',
    aTagConfig: link.href ? link : null,
    isFullWidth: !!vm.isFullWidth,
    onTap: (/** !Event */ e) => {
      if (!command) return;
      e.preventDefault();
      if (typeof resolver === 'function') resolver(command);
      else fireCommand(/** @type {!Element} */ (e.currentTarget), innertubeOf(command));
    },
  };
}

/** An ad button (CoW `ad-button-view-model`). */
export const AdButton = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const [focused, setFocused] = signal(false, 'Oh9Nof');
  const animated = () => !!(vm().onImpressionBehaviors && vm().onImpressionBehaviors.length);
  const entityKey = () => vm().adButtonAnimationStateEntityKey || '';
  const entity = useEntity('booleanEntity', entityKey);
  const played = () => !!(entity() && entity().value);
  const [shown, setShown] = linkedState(() => played() || vm().visibility !== 'VISIBILITY_GONE', 'adButtonShown');
  const [visible, setVisible] = linkedState(() => played() || vm().visibility === 'VISIBILITY_VISIBLE', 'adButtonVisible');
  const [destination, setDestination] = linkedState(() => (played() ? vm().destinationStyle : undefined), 'adButtonDestination');
  const config = () => {
    const c = adButtonConfig(Object.assign({}, vm(), destination() ? {style: destination()} : {}), unwrap(props.customCommandResolver));
    c.focused = focused();
    return c;
  };
  const resolver = useLayoutResolver();
  const iconSize = () => buttonIconSize(config(), !!vm().iconImage, resolver);
  /** @type {!Array<number>} */
  const jobs = [];
  afterRenderEffect(() => {
    const behaviors = vm().onImpressionBehaviors;
    runUntracked(() => {
      for (const b of behaviors || []) {
        const delay = b.triggerCondition && b.triggerCondition.delayedSeconds;
        if (!delay) continue;
        jobs.push(schedule(() => {
          const change = b.visibilityBehavior && b.visibilityBehavior.newVisibility;
          if (change === 'VISIBILITY_VISIBLE') {
            setShown(true);
            setVisible(true);
          } else if (change === 'VISIBILITY_INVISIBLE') {
            setShown(true);
            setVisible(false);
          } else if (change === 'VISIBILITY_GONE') {
            setShown(false);
            setVisible(false);
          } else if (b.adButtonAnimationBehavior && vm().destinationStyle) {
            setDestination(vm().destinationStyle);
          }
        }));
      }
    });
  }, 'adButtonBehaviors');
  onCleanup(() => {
    for (const id of jobs) cancel(id);
    jobs.length = 0;
  });
  return h('ytl-ad-button-view-model', {
    'on:focusin': (/** !Event */ e) => {
      setFocused(keyboardInUse());
      e.stopPropagation();
    },
    'on:focusout': (/** !Event */ e) => {
      setFocused(false);
      e.stopPropagation();
    },
    class: classes('ytlAdButtonViewModelHost', () => (animated() ? 'ytlAdButtonViewModelHostHasAnimation' : ''),
        () => (animated() ? (shown() ? 'ytlAdButtonViewModelFullHeight' : 'ytlAdButtonViewModelNoHeight') : ''),
        () => (animated() ? (visible() ? 'ytlAdButtonViewModelShow' : 'ytlAdButtonViewModelHide') : ''),
        () => (!animated() || shown() ? unwrap(props.delayedClassName) || '' : ''), {
          'ytlAdButtonViewModelHostCompactWidth': () => !!unwrap(props.isCompactWidth) && !vm().isFullWidth,
          'ytlAdButtonViewModelHostContentWidth': () => !!unwrap(props.isContentWidth),
        }, () => unwrap(props.className) || ''),
    ref: adVisibility(vm),
    style: styles({'transition-duration': '0.3s'}),
  }, cond(config, () => h(ButtonShape, {data: config, icon: () => cond(() => vm().iconImage, () => h(Image, {data: () => vm().iconImage,
    alt: '', targetWidth: iconSize, targetHeight: iconSize, preserveWidth: true, preserveHeight: true}))})));
}, 'ad-button-view-model (CoW)');

