/**
 * @fileoverview Templates of signal-schema controllers.
 *
 * `parseTemplate` runs once per template. It rewrites
 * `<template is="dom-if|dom-repeat">` into `<ps-dom-if|ps-dom-repeat>`
 * wrappers around a plain `<template>`, parses nested templates
 * separately, turns `[[...]]` attributes and text into bindings, and
 * records a node-info entry for every node with bindings, events, an id or
 * a nested template, and for their ancestors.
 *
 * `stampTemplate` clones the parsed content, finds the nodes, records ids,
 * hands nested templates to their helpers, adds event listeners, and
 * creates one effect per binding. As in YouTube's stamper, each node-info
 * entry also creates effects for the bindings of its ancestors' entries.
 */
import {addListener, gestures} from '@polymer/polymer/lib/utils/gestures.js';
import {sanitizeDOMValue} from '@polymer/polymer/lib/utils/settings.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {dashToCamel} from '../case.js';
import {parseArg} from './schema.js';
import {logPropertyAccess} from './logging.js';
import {toPath} from './proxy.js';

/**
 * @typedef {{
 *   type: string,
 *   value: string,
 *   path: string,
 *   negate: boolean,
 *   coerce: (boolean|undefined),
 *   methodName: string,
 *   args: !Array<!Object>,
 * }}
 */
let BindingPart;

/**
 * @typedef {{kind: string, target: string, parts: !Array<!BindingPart>}}
 */
let Binding;

/**
 * @typedef {{
 *   index: number,
 *   parentInfo: ?Object,
 *   parentIndex: number,
 *   bindings: !Array<!Binding>,
 *   events: !Array<{name: string, value: string}>,
 *   id: string,
 *   templateInfo: ?Object,
 * }}
 */
let NodeInfo;

/**
 * @typedef {{content: !DocumentFragment, nodeInfoList: !Array<!NodeInfo>, hasInsertionPoint: boolean}}
 */
export let TemplateInfo;

const HELPER_ATTRIBUTES = {
  'dom-if': new Set(['class', 'hidden', 'id', 'on-dom-change', 'if', 'notify-dom-change', 'restamp', 'data-sourcecode-loc']),
  'dom-repeat': new Set(['class', 'hidden', 'id', 'on-dom-change', 'if', 'notify-dom-change', 'restamp', 'data-sourcecode-loc',
    'as', 'index-as', 'initial-count', 'items', 'items-index-as', 'target-framerate', 'strip-whitespace']),
};

/** Returned by a binding evaluation that should not be applied. */
const SKIP = {};

/**
 * Parses the binding parts of `text`, or returns null without bindings.
 * @param {string} text
 * @return {?Array<!BindingPart>}
 */
function parseBindingParts(text) {
  if (text.includes('{{')) throw new Error(`Two-way bindings are not supported: ${text}`);
  if (!text.includes('[[')) return null;
  const parts = [];
  const re = /\[\[([\s\S]*?)\]\]/g;
  let last = 0;
  let m;
  while ((m = re.exec(text))) {
    if (m.index > last) parts.push(literalPart(text.slice(last, m.index)));
    let expr = m[1].trim();
    let bangs = 0;
    while (expr[bangs] === '!') bangs++;
    if (bangs) expr = expr.slice(bangs).trim();
    const negate = bangs % 2 === 1;
    const coerce = bangs > 0 && !negate;
    const call = /^([\w$]+)\s*\(([\s\S]*)\)$/.exec(expr);
    if (call) {
      const args = call[2].trim() ? splitArgs(call[2]).map(parseArg) : [];
      parts.push({type: 'method', value: '', path: '', negate, coerce, methodName: call[1], args});
    } else {
      parts.push({type: 'path', value: '', path: expr, negate, coerce, methodName: '', args: []});
    }
    last = re.lastIndex;
  }
  if (last < text.length) parts.push(literalPart(text.slice(last)));
  return parts;
}

/**
 * @param {string} value
 * @return {!BindingPart}
 */
function literalPart(value) {
  return {type: 'literal', value, path: '', negate: false, methodName: '', args: []};
}

/**
 * @param {string} body
 * @return {!Array<string>}
 */
function splitArgs(body) {
  const out = [];
  let quote = '';
  let start = 0;
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = '';
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === ',') {
      out.push(body.slice(start, i));
      start = i + 1;
    }
  }
  out.push(body.slice(start));
  return out;
}

/**
 * Replaces `<template is="dom-if|dom-repeat">` by a helper element that
 * wraps a plain template.
 * @param {!Element} template
 * @return {!Element} The helper.
 */
function wrapHelper(template) {
  const is = /** @type {string} */ (template.getAttribute('is'));
  const helper = document.createElement(`ps-${is}`);
  const allowed = HELPER_ATTRIBUTES[is];
  for (const attr of Array.from(template.attributes)) {
    if (attr.name === 'is') {
      template.removeAttribute('is');
    } else if (allowed.has(attr.name.replace(/\$$/, ''))) {
      helper.setAttribute(attr.name, attr.value);
      template.removeAttribute(attr.name);
    }
  }
  /** @type {!Node} */ (template.parentNode).insertBefore(helper, template);
  helper.appendChild(template);
  return helper;
}

/**
 * Parses the bindings, events and id of one node.
 * @param {!Node} node
 * @return {{bindings: !Array<!Binding>, events: !Array<{name: string, value: string}>, id: string}}
 */
function parseNode(node) {
  const bindings = [];
  const events = [];
  let id = '';
  if (node.nodeType === Node.TEXT_NODE) {
    const parts = parseBindingParts(/** @type {!Text} */ (node).data);
    if (parts) {
      const literal = parts.filter(p => p.type === 'literal').map(p => p.value).join('');
      /** @type {!Text} */ (node).data = literal || ' ';
      bindings.push({kind: 'text', target: 'textContent', parts});
    }
    return {bindings, events, id};
  }
  const el = /** @type {!Element} */ (node);
  for (const attr of Array.from(el.attributes)) {
    const name = attr.name;
    if (name.startsWith('on-')) {
      events.push({name: name.slice(3), value: attr.value});
      el.removeAttribute(name);
      continue;
    }
    if (name === 'id') id = attr.value;
    const parts = parseBindingParts(attr.value);
    if (!parts) continue;
    el.removeAttribute(name);
    const isAttribute = name.endsWith('$');
    const target = isAttribute ? name.slice(0, -1) : dashToCamel(name);
    if (isAttribute && target === 'class' && el.hasAttribute('class')) {
      parts.push(literalPart(` ${el.getAttribute('class')}`));
    }
    if (isAttribute) {
      const literal = parts.filter(p => p.type === 'literal').map(p => p.value).join('').trim();
      if (literal) el.setAttribute(target, literal);
      if (target === 'disable-upgrade') el.setAttribute(target, '');
    }
    bindings.push({kind: isAttribute ? 'attribute' : 'property', target, parts});
  }
  return {bindings, events, id};
}

/**
 * Parses a template's content once.
 * @param {!HTMLTemplateElement} template
 * @return {!TemplateInfo}
 */
export function parseTemplate(template) {
  const content = /** @type {!DocumentFragment} */ (template.content.cloneNode(true));
  const nodeInfoList = [];
  const info = {content, nodeInfoList, hasInsertionPoint: false};
  const stripWhitespace = template.hasAttribute('strip-whitespace');
  /**
   * @param {!Node} parent
   * @param {?NodeInfo} parentInfo
   * @param {!Array<!NodeInfo>} pending Ancestor infos not yet in the list.
   */
  const visit = (parent, parentInfo, pending) => {
    parent.normalize();
    for (let i = 0; i < parent.childNodes.length; i++) {
      let node = parent.childNodes[i];
      if (node.nodeType === Node.TEXT_NODE && stripWhitespace && !/** @type {!Text} */ (node).data.trim()) {
        parent.removeChild(node);
        i--;
        continue;
      }
      if (node.nodeType !== Node.ELEMENT_NODE && node.nodeType !== Node.TEXT_NODE) continue;
      if (node.localName === 'template' && /** @type {!Element} */ (node).hasAttribute('is')) node = wrapHelper(/** @type {!Element} */ (node));
      if (node.localName === 'slot') info.hasInsertionPoint = true;
      const parsed = parseNode(node);
      const nodeInfo = {index: -1, parentInfo, parentIndex: i, bindings: parsed.bindings, events: parsed.events, id: parsed.id, templateInfo: null};
      const own = parsed.bindings.length || parsed.events.length || parsed.id;
      const chain = pending.concat([nodeInfo]);
      if (own) {
        for (const p of chain) {
          if (p.index < 0) {
            p.index = nodeInfoList.length;
            nodeInfoList.push(p);
          }
        }
      }
      if (node.localName === 'template') {
        const nested = /** @type {!HTMLTemplateElement} */ (node);
        nodeInfo.templateInfo = parseTemplate(nested);
        while (nested.content.firstChild) nested.content.removeChild(nested.content.firstChild);
        for (const p of chain) {
          if (p.index < 0) {
            p.index = nodeInfoList.length;
            nodeInfoList.push(p);
          }
        }
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        visit(node, nodeInfo, own ? [] : chain);
      }
    }
  };
  visit(content, null, []);
  return info;
}

/**
 * @typedef {{
 *   proxy: !Object,
 *   methodHost: !Object,
 *   eventHost: !Object,
 *   getModel: (?function(): ?Object|undefined),
 *   enabled: (?function(): boolean|undefined),
 * }}
 */
let StampContext;

/**
 * Stamps a parsed template.
 * @param {!TemplateInfo} info
 * @param {!StampContext} ctx
 * @return {{dom: !DocumentFragment, nodes: !Array<!Node>, nodesById: !Object<string, !Element>}}
 */
export function stampTemplate(info, ctx) {
  const dom = /** @type {!DocumentFragment} */ (document.importNode(info.content, true));
  /** @type {?} */ (dom).__noInsertionPoint = !info.hasInsertionPoint;
  const list = info.nodeInfoList;
  const nodes = new Array(list.length);
  const nodesById = {};
  for (let i = 0; i < list.length; i++) {
    const ni = list[i];
    const parent = ni.parentInfo ? nodes[ni.parentInfo.index] : dom;
    const node = parent.childNodes[ni.parentIndex];
    nodes[i] = node;
    if (ni.id) nodesById[ni.id] = node;
    if (ni.templateInfo) {
      const helper = /** @type {?} */ (node.parentNode);
      helper.templateInfo = ni.templateInfo;
      helper.parentSignalProxy = ctx.proxy;
      helper.eventListenerHost = ctx.eventHost;
      helper.stampingEnabled = ctx.enabled || null;
    }
    for (const event of ni.events) addTemplateListener(node, event.name, event.value, ctx);
  }
  for (let i = 0; i < list.length; i++) {
    for (let p = list[i]; p; p = p.parentInfo) {
      for (const binding of p.bindings) createBindingEffect(nodes[p.index], binding, ctx);
    }
  }
  return {dom, nodes, nodesById};
}

/**
 * @param {!Node} node
 * @param {string} name
 * @param {string} handler
 * @param {!StampContext} ctx
 */
function addTemplateListener(node, name, handler, ctx) {
  const host = ctx.eventHost;
  const getModel = ctx.getModel;
  const listener = (e) => {
    const model = getModel ? getModel() : null;
    if (model) /** @type {?} */ (e).model = model;
    const fn = host[handler];
    if (typeof fn === 'function') fn.call(host, e, e.detail);
  };
  if (gestures[name]) addListener(node, name, listener);
  else node.addEventListener(name, listener);
}

/**
 * A getter of a path's value, cached per proxy and path: a root path reads
 * the value signal, a sub-path the path's mutation signal.
 * @param {!Object} proxy
 * @param {string} path
 * @return {function(): {value: *, defined: boolean}}
 */
function pathGetter(proxy, path) {
  const cache = proxy.pathGetters_ || (proxy.pathGetters_ = new Map());
  let getter = cache.get(path);
  if (getter) return getter;
  const parts = toPath(path);
  const store = proxy.resolve(parts[0]);
  const rest = parts.slice(1);
  if (!rest.length) {
    getter = () => {
      const value = store.getWithPath([]);
      return {value, defined: value !== undefined || store.wasDefined};
    };
  } else {
    const reader = store.getPathMutationSignal(rest);
    getter = () => {
      reader();
      const value = store.peek(rest);
      return {value, defined: value !== undefined || store.wasDefined};
    };
  }
  cache.set(path, getter);
  return getter;
}

/**
 * @param {!BindingPart} part
 * @param {!StampContext} ctx
 * @return {{value: *, defined: boolean}}
 */
function evaluatePart(part, ctx) {
  if (part.type === 'literal') return {value: part.value, defined: true};
  let result;
  if (part.type === 'path') {
    result = pathGetter(ctx.proxy, part.path)();
  } else {
    const values = [];
    let anyDefined = !part.args.length;
    for (const arg of part.args) {
      if (arg.type === 'literal') {
        values.push(arg.value);
        anyDefined = true;
        continue;
      }
      const r = pathGetter(ctx.proxy, arg.path)();
      values.push(r.value);
      if (r.defined) anyDefined = true;
    }
    if (!anyDefined) return {value: undefined, defined: false};
    const fn = pathGetter(ctx.proxy, part.methodName)().value;
    result = {value: typeof fn === 'function' ? fn.apply(ctx.methodHost, values) : undefined, defined: true};
  }
  if (part.negate) return {value: !result.value, defined: result.defined};
  if (part.coerce) return {value: !!result.value, defined: result.defined};
  return result;
}

/**
 * @param {!Binding} binding
 * @param {!StampContext} ctx
 * @return {*} The value, or SKIP.
 */
function evaluateBinding(binding, ctx) {
  const parts = binding.parts;
  if (parts.length === 1) {
    const r = evaluatePart(parts[0], ctx);
    return r.value === undefined && !r.defined ? SKIP : r.value;
  }
  let out = '';
  for (const part of parts) {
    const r = evaluatePart(part, ctx);
    out += r.value == null ? '' : r.value;
  }
  return out;
}

/**
 * Serializes a value for an attribute.
 * @param {*} value
 * @return {string|undefined}
 */
function attributeValue(value) {
  if (value === undefined || value === null || value === false) return undefined;
  if (value === true) return '';
  if (typeof value === 'object') {
    try {
      return JSON.stringify(value);
    } catch (e) {
      return undefined;
    }
  }
  return String(value);
}

/**
 * @param {!Node} node
 * @param {!Binding} binding
 * @param {*} value
 */
function applyBinding(node, binding, value) {
  if (value === SKIP) return;
  const target = binding.target;
  if (value === undefined && (target === 'textContent' || (target === 'value' && (node.localName === 'input' || node.localName === 'textarea')))) value = '';
  if (sanitizeDOMValue) value = sanitizeDOMValue(value, target, binding.kind, node);
  if (binding.kind === 'text') {
    node.textContent = value == null ? '' : String(value);
    return;
  }
  if (binding.kind === 'attribute') {
    const el = target === 'class' || target === 'name' || target === 'slot' ? wrap(/** @type {!Element} */ (node)) : node;
    const str = attributeValue(value);
    if (str === undefined) el.removeAttribute(target);
    else el.setAttribute(target, str);
    return;
  }
  if (value !== node[target] || typeof value === 'object') {
    const status = node.loggingStatus;
    if (status) {
      status.isDeclarativeExternal = true;
      logPropertyAccess(node.localName, target, 'PROPERTY_ACCESS_SET_EXTERNAL_DECLARATIVE');
    }
    node[target] = value;
    if (status) status.isDeclarativeExternal = false;
  }
}

/**
 * Whether a binding target forwards path notifications: a signal-schema
 * controller's mutable property, or a declared property of a Polymer
 * controller.
 * @param {!Node} node
 * @param {string} target
 * @return {?Object} The controller to notify.
 */
function notifyTarget(node, target) {
  const ctrl = node.polymerController;
  if (!ctrl) return null;
  if (ctrl.canNotifyPath) return ctrl.canNotifyPath(target) ? ctrl : null;
  const props = ctrl.constructor && ctrl.constructor.properties;
  return props && props[target] ? ctrl : null;
}

/**
 * @param {!Node} node
 * @param {!Binding} binding
 * @param {!StampContext} ctx
 */
function createBindingEffect(node, binding, ctx) {
  const enabled = ctx.enabled;
  const parts = binding.parts;
  const single = parts.length === 1 && parts[0].type === 'path' && !parts[0].negate && !parts[0].coerce && binding.kind === 'property';
  const forward = single ? notifyTarget(node, binding.target) : null;
  if (forward) {
    const sourcePath = toPath(parts[0].path);
    const store = ctx.proxy.resolve(sourcePath[0]);
    const reader = store.getChangeRecordSignal(sourcePath.slice(1));
    let first = true;
    ctx.proxy.effect(() => {
      if (enabled && !enabled()) return;
      const record = reader();
      ctx.proxy.runUntracked(() => {
        if (first) {
          first = false;
          const value = store.peek(sourcePath.slice(1));
          if (value !== undefined || store.wasDefined) applyBinding(node, binding, value);
          return;
        }
        const tail = record.path.split('.').slice(sourcePath.length);
        forward.notifyPath([binding.target].concat(tail).join('.'), record.value);
      });
    }, binding.target);
    return;
  }
  ctx.proxy.effect(() => {
    if (enabled && !enabled()) return;
    const value = evaluateBinding(binding, ctx);
    ctx.proxy.runUntracked(() => applyBinding(node, binding, value));
  }, binding.target);
}
