/**
 * @fileoverview Installs polymer-resin as Polymer's `sanitizeDOMValue`, as
 * YouTube does when its bundle loads, so that every attribute, property and
 * text binding is vetted against the HTML contract tables. The safe-types
 * bridge accepts any object as a string, any string as a style, and URLs
 * that match a safe-URL pattern; other safe types fall back to the
 * innocuous replacement.
 */
import sanitizer from 'goog:security.polymer_resin.sanitizer';
import {sanitizeDOMValue, setSanitizeDOMValue} from '@polymer/polymer/lib/utils/settings.js';

const SAFE_URL = /^(?:(?:https?|mailto|ftp):|[^:/?#]*(?:[/?#]|$))/i;

/**
 * @param {*} value
 * @param {string} type
 * @param {*} fallback
 * @return {*}
 */
function safeTypesBridge(value, type, fallback) {
  switch (type) {
    case 'STRING':
      return String(value);
    case 'STYLE':
      return typeof value === 'string' ? value : fallback;
    case 'URL': {
      const s = String(value);
      return SAFE_URL.test(s) ? s : fallback;
    }
    default:
      return fallback;
  }
}

/**
 * @param {boolean} isViolation
 * @param {string} format
 */
function reportHandler(isViolation, format) {
  if (isViolation) console.warn('resin: ' + format);
}

if (sanitizeDOMValue !== undefined) throw new Error('sanitizeDOMValue is already set');
setSanitizeDOMValue(sanitizer.makeSanitizeDomFunction(
    {'reportHandler': reportHandler, 'safeTypesBridge': safeTypesBridge, 'allowedIdentifierPrefixes': ['']},
    undefined));
