/**
 * @fileoverview Property-access logging for PolySi elements, used to find
 * code that still depends on the Polymer API. Every forwarded access asks
 * whether logging is on for the element's tag; it is off unless the
 * experiment flags enable it, so normally the check costs two flag reads.
 */
import {flag, flagNumber} from '../flags.js';

/** Names that are never recorded. */
const IGNORED = new Set(['allowedProps', '_definePropertyAccessor', '_setPendingProperty', '_setUnmanagedPropertyToNode']);

/** @type {!Map<string, number>} */
const counts = new Map();

/** @type {number} */
let startTime = 0;

/**
 * @param {string} s
 * @return {number}
 */
function hashTag(s) {
  let h = 0;
  for (let i = 0; i < s.length; ++i) h = (31 * h + s.charCodeAt(i)) >>> 0;
  return h;
}

/**
 * @param {string} tag
 * @return {boolean}
 */
export function isAccessLoggingEnabled(tag) {
  if (flag('polymer_property_access_logging_debug')) return true;
  if (!flag('polymer_enable_property_access_logging')) return false;
  startTime = startTime || Date.now();
  return (hashTag(tag) + startTime) % 100 < flagNumber('polymer_property_access_logging_percent', 0);
}

/**
 * @param {string} name
 * @return {boolean}
 */
export function isIgnoredName(name) {
  return IGNORED.has(name);
}

/**
 * Wraps a controller method so that calls from inside the element are
 * recorded too. Used only when logging is on for the element's tag.
 * @param {!Object} ctrl
 * @param {string} name
 */
export function instrumentMethod(ctrl, name) {
  const fn = ctrl[name];
  if (typeof fn !== 'function') return;
  const tag = String(ctrl.is);
  ctrl[name] = function(...args) {
    if (!ctrl.hostElement.loggingStatus.currentExternalCall) logPropertyAccess(tag, name, 'PROPERTY_ACCESS_CALL_INTERNAL');
    return fn.apply(this, args);
  };
}

/**
 * Records reads and writes of a controller field from inside the element.
 * Used only when logging is on for the element's tag.
 * @param {!Object} ctrl
 * @param {string} name
 */
export function instrumentField(ctrl, name) {
  let value = ctrl[name];
  const tag = String(ctrl.is);
  Object.defineProperty(ctrl, name, {
    configurable: true,
    get() {
      if (!ctrl.hostElement.loggingStatus.isExternalGet) logPropertyAccess(tag, name, 'PROPERTY_ACCESS_GET_INTERNAL');
      return value;
    },
    set(v) {
      if (ctrl.hostElement.loggingStatus.currentExternalSet !== name) logPropertyAccess(tag, name, 'PROPERTY_ACCESS_SET_INTERNAL');
      value = v;
    },
  });
}

/**
 * @param {string} tag
 * @param {string} name
 * @param {string} kind
 */
export function logPropertyAccess(tag, name, kind) {
  if (!isAccessLoggingEnabled(tag) || IGNORED.has(name)) return;
  const key = `${kind}:${tag}.${name.replace(/^JSC\$\d+_/, '').replace(/\.\d+(\.|$)/g, (m, end) => '.#' + end)}`;
  counts.set(key, (counts.get(key) || 0) + 1);
}

/** @return {!Map<string, number>} */
export function getAccessCounts() {
  return counts;
}
