/**
 * @fileoverview The app store: a small Redux-like store with an entity
 * table. Elements with the redux behaviour subscribe while attached and
 * recompute their selector properties on every change.
 */

/**
 * @typedef {{
 *   entities: !Object<string, !Object<string, *>>,
 *   ui: {pageType: string, isGridView: boolean, chipBarIsSticky: boolean, richGridItemsPerRow: (number|undefined),
 *     richGridSlimItemsPerRow: (number|undefined), richGridContainerWidth: (number|undefined), richGridStyle: (string|undefined),
 *     currentPageType: (string|undefined), currentPageSubType: (string|undefined), isTheaterMode: boolean},
 *   watch: ?{isGrid: boolean, secondaryColumns: number},
 *   continuationCommand: ?Object,
 * }}
 */
let AppState;

class AppStore {
  constructor() {
    /** @private {!AppState} */
    this.state_ = {entities: {}, ui: {pageType: 'search', isGridView: false, chipBarIsSticky: false, isTheaterMode: false}, watch: null,
      continuationCommand: null};
    /** @private @const {!Set<function()>} */
    this.listeners_ = new Set();
  }

  /** @return {!AppState} */
  getState() {
    return this.state_;
  }

  /**
   * @param {{type: string, payload: *}} action
   * @return {{type: string, payload: *}}
   */
  dispatch(action) {
    this.state_ = reduce(this.state_, action);
    for (const listener of Array.from(this.listeners_)) listener();
    return action;
  }

  /**
   * @param {function()} listener
   * @return {function()} Unsubscribes.
   */
  subscribe(listener) {
    this.listeners_.add(listener);
    return () => this.listeners_.delete(listener);
  }
}

/** The page types of the page elements. */
const PAGE_TYPES = {'ytl-search': 'search', 'ytl-watch-flexy': 'watch', 'ytl-browse': 'browse'};

/**
 * @param {!AppState} state
 * @param {{type: string, payload: *}} action
 * @return {!AppState}
 */
function reduce(state, action) {
  switch (action.type) {
    case 'ENTITY_UPDATE': {
      const {entityType, key, value} = /** @type {{entityType: string, key: string, value: *}} */ (action.payload);
      const table = Object.assign({}, state.entities[entityType], {[key]: value});
      return Object.assign({}, state, {entities: Object.assign({}, state.entities, {[entityType]: table})});
    }
    case 'ENTITY_BATCH_UPDATE': {
      const entities = Object.assign({}, state.entities);
      const copied = {};
      for (const {entityType, key, value} of /** @type {!Array<{entityType: string, key: string, value: *}>} */ (action.payload)) {
        if (!copied[entityType]) copied[entityType] = entities[entityType] = Object.assign({}, entities[entityType]);
        if (value === undefined) delete entities[entityType][key];
        else entities[entityType][key] = value;
      }
      return Object.assign({}, state, {entities});
    }
    case 'SET_CONTINUATION_COMMAND':
      return Object.assign({}, state, {continuationCommand: /** @type {?Object} */ (action.payload)});
    case 'SET_RICH_GRID_ITEMS_PER_ROW':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {richGridItemsPerRow: /** @type {number} */ (action.payload)})});
    case 'SET_RICH_GRID_SLIM_ITEMS_PER_ROW':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {richGridSlimItemsPerRow: /** @type {number} */ (action.payload)})});
    case 'SET_RICH_GRID_CONTAINER_WIDTH':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {richGridContainerWidth: /** @type {number} */ (action.payload)})});
    case 'SET_RICH_GRID_STYLE':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {richGridStyle: /** @type {string} */ (action.payload)})});
    case 'SET_SHARED_CURRENT_PAGE_TYPE': {
      const tag = /** @type {string} */ (action.payload);
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {currentPageType: tag, pageType: PAGE_TYPES[tag] || state.ui.pageType})});
    }
    case 'SET_SHARED_CURRENT_PAGE_SUB_TYPE':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {currentPageSubType: /** @type {string} */ (action.payload)})});
    case 'SET_IS_THEATER_MODE':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui,
        {isTheaterMode: !!/** @type {{isTheaterMode: boolean}} */ (action.payload).isTheaterMode})});
    case 'SET_WATCH_GRID':
      return Object.assign({}, state, {watch: /** @type {{isGrid: boolean, secondaryColumns: number}} */ (action.payload)});
    case 'SET_CHIP_BAR_STICKY':
      return Object.assign({}, state, {ui: Object.assign({}, state.ui, {chipBarIsSticky: !!action.payload})});
    default:
      return state;
  }
}

export const appStore = new AppStore();

/**
 * Selects one entity.
 * @param {!Object<string, !Object<string, *>>} entities
 * @param {string} entityType
 * @param {?string|undefined} key
 * @return {*}
 */
export function selectEntity(entities, entityType, key) {
  const table = entities[entityType];
  return key && table ? table[key] : undefined;
}

/**
 * @param {string} entityType
 * @return {function(!AppState, ?string=): *} A selector of the entity of that
 *     type under a key.
 */
export function entitySelector(entityType) {
  return (state, key) => selectEntity(state.entities, entityType, key);
}

/**
 * Whether lists show a grid: the watch page's choice, else the UI state.
 * @param {!AppState} state
 * @return {boolean}
 */
export function selectIsGridViewEnabled(state) {
  if (state.watch) return state.watch.isGrid;
  return state.ui.isGridView;
}

/**
 * @param {!AppState} state
 * @return {number}
 */
export function selectSecondaryGridColumns(state) {
  return state.watch ? state.watch.secondaryColumns : 2;
}

/**
 * @param {!AppState} state
 * @return {boolean}
 */
export function selectIsShortsPage(state) {
  return state.ui.pageType === 'shorts';
}

/**
 * @param {!AppState} state
 * @return {boolean}
 */
export function selectIsWatchPage(state) {
  return state.ui.pageType === 'watch';
}
