/**
 * @fileoverview Command dispatch: components fire InnerTube commands as
 * bubbling `yt-action` events with action name "yt-command"; the app
 * element resolves them (navigation, continuation, popups, service calls).
 */
import {fireAction} from '../framework/actions.js';

/**
 * @param {!Element} source
 * @param {?Object|undefined} command
 * @return {boolean} Whether a command was fired.
 */
export function fireCommand(source, command) {
  if (!command) return false;
  fireAction(source, 'yt-command', [command]);
  return true;
}
