/**
 * @fileoverview Debug counters of the view-model runtime, read by
 * `tools/verify.mjs` through `window.ytlVmCounters`. Each is one increment
 * at a creation site.
 */

export const vmCounters = {
  /** Render effects created by view-model code. */
  effects: 0,
  /** After-render effects created by view-model code. */
  afterEffects: 0,
  /** Effects created by PolySi signal stores and templates. */
  polysiEffects: 0,
  computeds: 0,
  /** Signals created by view-model code, without the CoW prop signals. */
  signals: 0,
  /** Linked signals, which YouTube's counters do not count as signals. */
  linked: 0,
  /** One per declared prop of each rendered CoW host. */
  cowSignals: 0,
  owners: 0,
  /** Root owners of PolySi signal proxies and host renders. */
  polysiOwners: 0,
  cleanups: 0,
  /** View-model component renders. */
  renders: 0,
  /** Render roots of PolySi hosts. */
  polysiRenders: 0,
  /** JSX nodes. */
  jsx: 0,
  /** Elements created by the JSX renderer. */
  elements: 0,
};

window['ytlVmCounters'] = vmCounters;

/**
 * Per-component breakdown, filled only when the page sets
 * `window.ytlVmBreakdown = {}` before the app loads. Work is attributed to
 * the nearest CoW component on the component stack, as in the
 * specification's per-instance tables.
 * @type {?Object<string, !Object<string, number>>}
 */
const breakdown = window['ytlVmBreakdown'] || null;

/**
 * @param {string} kind
 * @param {?{name: string, parent: ?Object}} frame
 * @param {string=} debugName For computeds and signals: counted per name
 *     under `#computeds:name` and `#signals:name`.
 */
export function noteBreakdown(kind, frame, debugName) {
  if (!breakdown) return;
  let key = kind.charCodeAt(0) === 35 /* # */ ? '#effects by name' : '-';
  for (let f = frame; f; f = /** @type {?} */ (f.parent)) {
    if (f.name.endsWith('(CoW)')) {
      key = f.name;
      break;
    }
    key = f.name;
  }
  const entry = breakdown[key] || (breakdown[key] = {});
  entry[kind] = (entry[kind] || 0) + 1;
  if (debugName) {
    const named = `#${kind}:${debugName}`;
    entry[named] = (entry[named] || 0) + 1;
  }
}
