/**
 * @fileoverview Polymer setup that matches YouTube's copy of Polymer:
 *
 * - `window.Polymer` becomes a function that forwards to `_polymerFn`, with
 *   the page's settings object copied onto it (the Polymer 2 style boot code
 *   that kevlar.js contains), plus a `Polymer.*` namespace (`version`,
 *   `Element`, `html`, ...). Stock Polymer 3 has neither; this is a minimal
 *   equivalent written for the workload.
 * - LegacyDataMixin is loaded, as in kevlar.js, so every legacy element
 *   class gets its `_marshalArgs` override and wrapped effect functions.
 */
import {version} from '@polymer/polymer/lib/mixins/element-mixin.js';
import {PolymerElement} from '@polymer/polymer/polymer-element.js';
import {Polymer as polymerFn} from '@polymer/polymer/lib/legacy/polymer-fn.js';
import {Class} from '@polymer/polymer/lib/legacy/class.js';
import {dom} from '@polymer/polymer/lib/legacy/polymer.dom.js';
import {html} from '@polymer/polymer/lib/utils/html-tag.js';
import {flush} from '@polymer/polymer/lib/utils/flush.js';
import {Base} from '@polymer/polymer/polymer-legacy.js';
import '@polymer/polymer/lib/legacy/legacy-data-mixin.js';

const userSettings = window.Polymer;
const ns = /** @type {!Object} */ (window.Polymer = function(info) {
  return window.Polymer._polymerFn(info);
});
if (userSettings) Object.assign(ns, userSettings);
ns._polymerFn = polymerFn;
ns.version = version;
ns.Element = PolymerElement;
ns.Class = Class;
ns.Base = Base;
ns.dom = dom;
ns.html = html;
ns.flush = flush;

export {polymerFn as Polymer};
