/**
 * @fileoverview View models of the channel page: the page header (CoW
 * `ytl-page-header-renderer` around `ytl-page-header-view-model`) with its
 * avatar, title, metadata, description preview, attribution and actions;
 * the image banner; the tab group and tab shapes with the measured slider;
 * the shorts lockup host that horizontal lists stamp; and the chip bar of
 * the rich grid. Specification: `yt-fingerprint/channel-code-2026-10-08.md`,
 * sections 3.2 to 3.6.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {IndexEach, cond} from '../../framework/vm/control.js';
import {afterRenderEffect, computed, signal, unwrap} from '../../framework/vm/effect.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';
import {flag, getConfig} from '../../framework/flags.js';
import {registerRenderer} from '../../framework/registry.js';
import {fireCommand} from '../commands.js';
import {logClick} from '../logging.js';
import {Priority, cancel, schedule} from '../scheduler.js';
import {AttributedString} from './attributed-string.js';
import {ChipShape} from './chips.js';
import {ButtonViewModel} from './buttons.js';
import {DecoratedAvatar} from './avatars.js';
import {AttributionViewModel, ContentMetadata} from './lockup-metadata.js';
import {ShortsLockup, innertube} from './lockups.js';
import {pickSource} from './primitives.js';
import {contextLabel, rendererOf, useBreakpoint, withDefaults} from './hooks.js';

/**
 * The number of filled header fields (`lTs`), which picks the avatar size.
 * @param {!Object} vm
 * @return {number}
 */
function filledFieldCount(vm) {
  let n = 0;
  for (const key of ['title', 'metadata', 'actions', 'description', 'attribution']) if (vm[key]) n++;
  return n + (vm.additionalAttributions ? vm.additionalAttributions.length : 0);
}

/**
 * @param {number} level
 * @param {number} fields
 * @param {boolean} compact
 * @return {string}
 */
function avatarSizeFor(level, fields, compact) {
  if (compact || level === 1) return 'AVATAR_SIZE_XL';
  if (level === 2 || (level === 4 && fields < 4)) return 'AVATAR_SIZE_XXL';
  return 'AVATAR_SIZE_XXXL';
}

/** The title (`dynamicTextViewModel`). */
const DynamicText = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const maxLines = () => (flag('enable_dynamic_text_max_lines', true) ? vm().maxLines || 2 : undefined);
  return h('ytl-dynamic-text-view-model', {class: classes('ytlDynamicTextViewModelHost', () => unwrap(props.className) || '')},
    h('h1', {class: 'ytlDynamicTextViewModelH1', 'aria-label': () => contextLabel(vm().rendererContext),
      style: styles({'-webkit-line-clamp': () => (maxLines() ? String(maxLines()) : undefined)})},
    h(AttributedString, {text: () => vm().text, linkInheritColor: true})));
}, 'dynamic-text-view-model');

/**
 * Truncated text with a visible copy and a hidden measuring copy, and the
 * "more" button. The visible copy is clamped to `maxLines`; the button
 * shows when the hidden copy is taller than the clamp.
 */
const TruncatedText = defineComponent((props) => {
  const [overflowing, setOverflowing] = signal(false, 'truncatedOverflow');
  let hidden = null;
  let visible = null;
  afterRenderEffect(() => {
    unwrap(props.text);
    if (!hidden || !visible) return;
    setOverflowing(hidden.scrollHeight > visible.clientHeight + 1);
  }, 'truncatedMeasure');
  const content = (hiddenCopy) => h('truncated-text-content', {
    class: classes('ytlTruncatedTextTruncatedTextContent', {'ytlTruncatedTextHiddenTextContent': hiddenCopy}),
    'aria-hidden': hiddenCopy ? 'true' : undefined,
    style: styles({'-webkit-line-clamp': () => (hiddenCopy ? undefined : String(unwrap(props.maxLines) || 1))}),
    ref: (/** !Element */ el) => {
      if (hiddenCopy) hidden = el;
      else visible = el;
    },
  },
  h(AttributedString, {text: props.text}),
  h('button', {class: 'ytlTruncatedTextInlineButton', disabled: 'true', 'aria-disabled': 'true'},
    h(AttributedString, {text: props.truncationText})));
  return h('truncated-text', {class: 'ytlTruncatedTextHost ytlTruncatedTextMediumText'},
    content(false), content(true),
    h('button', {class: 'ytlTruncatedTextAbsoluteButton', hidden: () => !overflowing(), 'aria-label': props.ariaLabel,
      'on:click': (/** !Event */ e) => {
        e.stopPropagation();
        if (props.onExpand) props.onExpand();
      }},
    h(AttributedString, {text: props.truncationText})));
}, 'truncated-text');

/** The description preview (`descriptionPreviewViewModel`). */
const DescriptionPreview = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const command = () => {
    const c = vm().rendererContext && vm().rendererContext.commandContext;
    return c && c.onTap ? innertube(c.onTap) : null;
  };
  return h('ytl-description-preview-view-model', {
    class: classes('ytlDescriptionPreviewViewModelHost', () => unwrap(props.className) || '',
        {'ytlDescriptionPreviewViewModelClickable': () => !!command()}),
    'on:click': (/** !Event */ e) => fireCommand(/** @type {!Element} */ (e.currentTarget), command()),
  }, h(TruncatedText, {text: () => vm().description, truncationText: () => vm().truncationText,
    maxLines: () => unwrap(props.maxLinesOverride) || vm().maxLines, ariaLabel: () => contextLabel(vm().rendererContext)}));
}, 'description-preview-view-model');

/** The header's action buttons (`flexibleActionsViewModel`). */
const FlexibleActions = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const actions = () => {
    const out = [];
    for (const row of vm().actionsRows || []) for (const a of row.actions || []) out.push(a);
    return out;
  };
  return h('ytl-flexible-actions-view-model', {
    class: classes('ytlFlexibleActionsViewModelHost', () => unwrap(props.className) || '',
        {'ytlFlexibleActionsViewModelInline': () => unwrap(props.layout) !== 1,
          'ytlFlexibleActionsViewModelJustifyContentStart': () => vm().justifyContent !== 'FLEXIBLE_ACTIONS_JUSTIFY_CONTENT_CENTER'}),
    style: styles({'min-height': () => (vm().minimumRowHeight ? `${vm().minimumRowHeight}px` : undefined)}),
  }, h(IndexEach, {of: actions, render: (action) => h('div', {class: 'ytlFlexibleActionsViewModelAction'},
    rendererOf(action, {'buttonViewModel': (r) => h(ButtonViewModel, {data: r.data})}))}));
}, 'flexible-actions-view-model');

/** The image banner (CoW `ytl-image-banner-view-model`). */
const ImageBanner = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const src = () => {
    const s = pickSource((vm().image && vm().image.sources) || [], 1060);
    return s ? s.url : undefined;
  };
  return h('ytl-image-banner-view-model', {class: classes('ytlImageBannerViewModelHost',
    {'ytlImageBannerViewModelInset': () => vm().style === 'IMAGE_BANNER_STYLE_INSET'}, 'ytlImageBannerViewModelPositionAbsolute')}, ' ',
  h('img', {class: 'ytlCoreImageHost ytlCoreImageFillParentHeight ytlCoreImageFillParentWidth ytlCoreImageContentModeScaleAspectFill',
    alt: '', src}), ' ');
}, 'ytl-image-banner-view-model (CoW)');

defineCoW('ytl-image-banner-view-model', ImageBanner, {props: {data: PropKind.SIGNAL}});

/** The page header view model, default layout (`CrN`). */
const PageHeaderViewModel = defineComponent((rawProps) => {
  const props = withDefaults(rawProps, {noPadding: false, displayAsSidebar: false, displayAsPanel: false});
  const vm = () => /** @type {!Object} */ (unwrap(props.data)) || {};
  const responsive = useBreakpoint();
  const level = computed(() => (props.displayAsSidebar() || props.displayAsPanel() ? 1 : responsive()), undefined, 'pageHeaderLevelOf');
  const wide = () => level() >= 3;
  const compact = () => vm().layoutPreset === 'PAGE_HEADER_LAYOUT_PRESET_COMPACT';
  const avatar = computed(() => {
    const image = vm().image && vm().image.decoratedAvatarViewModel;
    if (!image) return null;
    const size = avatarSizeFor(level(), filledFieldCount(vm()), compact());
    const avatarVm = Object.assign({}, image.avatar && image.avatar.avatarViewModel, {avatarImageSize: size});
    return Object.assign({}, image, {avatar: {avatarViewModel: avatarVm}});
  }, undefined, 'pageHeaderAvatar');
  const title = () => vm().title && vm().title.dynamicTextViewModel;
  const metadata = () => vm().metadata && vm().metadata.contentMetadataViewModel;
  const description = () => vm().description && vm().description.descriptionPreviewViewModel;
  const attribution = () => vm().attribution && vm().attribution.attributionViewModel;
  const actions = () => vm().actions && vm().actions.flexibleActionsViewModel;
  const trailing = () => [
    cond(() => !!attribution(), () => h(AttributionViewModel, {data: attribution, className: 'ytlPageHeaderViewModelAttribution'})),
    cond(() => !!actions(), () => h(FlexibleActions, {data: actions, layout: () => (level() <= 2 ? 1 : 0),
      className: 'ytlPageHeaderViewModelFlexibleActions ytlPageHeaderViewModelFlexibleActionsMarginTop ytlPageHeaderViewModelFlexibleActionsMarginBottom'})),
  ];
  return h('ytl-page-header-view-model', {class: classes('ytlPageHeaderViewModelHost', {
    'ytlPageHeaderViewModelNoPadding': props.noPadding,
    'ytlPageHeaderViewModelDisplayAsSidebar': props.displayAsSidebar,
    'ytlPageHeaderViewModelLayoutPresetCompact': compact,
  })}, ' ',
  h('div', {class: 'ytlPageHeaderViewModelContent'}, ' ',
    h('div', {class: 'ytlPageHeaderViewModelHeadline'},
      cond(() => !!avatar(), () => h('div', {class: 'ytlPageHeaderViewModelHeadlineImage'}, h(DecoratedAvatar, {data: avatar}))), ' ',
      h('div', {class: 'ytlPageHeaderViewModelHeadlineInfo'}, ' ',
        cond(() => !!title(), () => h(DynamicText, {data: title,
          className: () => `ytlPageHeaderViewModelTitle ${wide() ? 'ytlPageHeaderViewModelTitleLarge' : 'ytlPageHeaderViewModelTitleMedium'}`})),
        cond(() => !!metadata(), () => h(ContentMetadata, {data: metadata, layout: () => (level() === 1 ? 1 : 0),
          className: 'ytlPageHeaderViewModelContentMetadata ytlContentMetadataViewModelMediumText'})),
        cond(() => wide() && !!description(), () => h(DescriptionPreview, {data: description, className: 'ytlPageHeaderViewModelDescription',
          maxLinesOverride: () => (level() === 1 || vm().disableMaxLinesConstraint ? undefined : 1)})),
        cond(wide, () => trailing()))),
    cond(() => !wide(), () => h('div', {class: 'ytlPageHeaderViewModelHeadlineInfo'},
      cond(() => !!description(), () => h(DescriptionPreview, {data: description, className: 'ytlPageHeaderViewModelDescription'})),
      trailing())),
    cond(() => !!vm().bottomMetadataFlexibleContainer, () => h('div', {class: 'ytlPageHeaderViewModelBottomMetadata'}))));
}, 'page-header-view-model');

/** The page header renderer (CoW): picks its data and renders the view model. */
const PageHeaderRenderer = defineComponent((rawProps) => {
  const props = withDefaults(rawProps, {noPadding: false, displayAsSidebar: false, pageSubtype: undefined});
  const content = () => {
    const d = /** @type {!Object} */ (props.data()) || {};
    return props.displayAsSidebar() && d.sidebarContent ? d.sidebarContent : d.content;
  };
  return h('ytl-page-header-renderer', {class: classes('ytlPageHeaderRendererHost', () => props.className() || '')},
    rendererOf(content, {'pageHeaderViewModel': (r) => h(PageHeaderViewModel, {data: r.data, noPadding: props.noPadding,
      displayAsSidebar: props.displayAsSidebar, pageSubtype: props.pageSubtype})}));
}, 'ytl-page-header-renderer (CoW)');

defineCoW('ytl-page-header-renderer', PageHeaderRenderer, {props: {
  data: PropKind.SIGNAL, noPadding: PropKind.SIGNAL, enableBanner: PropKind.SIGNAL, cinematicContainerTopbarOffset: PropKind.SIGNAL,
  allowCinematicContainerOverflow: PropKind.SIGNAL, displayAsSidebar: PropKind.SIGNAL, pageSubtype: PropKind.SIGNAL,
  className: PropKind.SIGNAL,
}});

/** The gap between tabs that the slider offset adds per tab. */
const TAB_GAP = 24;

/**
 * Whether two paths are on the same channel (`e89`): the first segment is
 * equal and starts with `@`, or is a channel prefix with an equal id.
 * @param {string} a
 * @param {string} b
 * @return {boolean}
 */
function sameChannelPath(a, b) {
  const pa = a.split('/').filter(Boolean);
  const pb = b.split('/').filter(Boolean);
  if (!pa.length || pa[0] !== pb[0]) return false;
  if (pa[0].startsWith('@')) return true;
  return ['channel', 'c', 'user'].includes(pa[0]) && pa[1] === pb[1];
}

/**
 * The app path of the current page: a channel's path is in the `c` query
 * parameter (see the app's navigation).
 * @return {string}
 */
function currentAppPath() {
  return new URLSearchParams(location.search).get('c') || location.pathname;
}

/** One tab (`yt-tab-shape`); an expandable tab renders its own element instead of the label and bar. */
const TabShape = defineComponent((props) => {
  const shape = () => unwrap(props.shape) || {};
  const custom = shape().customTabRenderable;
  const click = (/** !Event */ e) => {
    const s = shape();
    if (!s.disabled && s.aTagConfig && s.aTagConfig.onclick) s.aTagConfig.onclick(e);
    e.stopPropagation();
  };
  return h('ytl-tab-shape', {
    class: classes('ytlTabShapeHost', {'ytlTabShapeLastTab': props.isLastTab, 'ytlTabShapeHostDisabled': () => !!shape().disabled,
      'ytlTabShapeHostClickable': !custom}),
    role: custom ? undefined : 'tab',
    'aria-selected': () => String(!!shape().selected),
    'aria-disabled': () => (shape().disabled ? 'true' : undefined),
    tabindex: custom ? undefined : '0',
    'tab-identifier': () => shape().identifier,
    'tab-title': () => shape().title,
    'on:click': click,
    'on:keydown': (/** !KeyboardEvent */ e) => {
      if (flag('web_tab_shape_keydown_killswitch')) return;
      if (e.key !== 'Enter' && e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
      e.preventDefault();
      /** @type {!HTMLElement} */ (e.currentTarget).click();
    },
  },
  custom ? custom() : [
    h('div', {class: classes('ytlTabShapeTab', {'ytlTabShapeTabSelected': () => !!shape().selected})},
      cond(() => !!shape().icon, () => h('div', {class: 'ytlTabShapeTabIcon'})), ' ', () => shape().title || ''),
    h('div', {class: classes('ytlTabShapeTabBar', {'ytlTabShapeTabBarSelected': () => !!shape().selected})})]);
}, 'tab-shape');

/** The tab group (CoW `ytl-tab-group-shape`) with the moving underline. */
const TabGroupShape = defineComponent((props) => {
  const shape = () => /** @type {!Object} */ (props.shape()) || {};
  const tabs = () => shape().tabs || [];
  const [width, setWidth] = signal(48, 'tabSliderWidth');
  const [offset, setOffset] = signal(0, 'tabSliderOffset');
  const [transition, setTransition] = signal(false, 'tabSliderTransition');
  const previousPath = currentAppPath();
  let host = null;
  let job = 0;
  afterRenderEffect(() => {
    const list = tabs();
    const selected = list.findIndex(t => t.selected);
    if (job) cancel(job);
    job = schedule(() => {
      job = 0;
      if (!host || selected < 0) return;
      const shapes = host.querySelectorAll('ytl-tab-shape');
      let x = 0;
      for (let i = 0; i < selected && i < shapes.length; i++) x += Math.round(shapes[i].getBoundingClientRect().width) + TAB_GAP;
      const target = shapes[selected];
      if (!target) return;
      setWidth(Math.round(target.getBoundingClientRect().width));
      setOffset(getConfig('HTML_DIR', 'ltr') === 'rtl' ? -x : x);
      if (sameChannelPath(currentAppPath(), previousPath)) /** @type {!HTMLElement} */ (target).focus({preventScroll: true});
      if (!transition()) schedule(() => setTransition(true), Priority.DEFERRED);
    }, Priority.DEFERRED);
  }, 'tabSliderMeasure');
  onCleanup(() => {
    if (job) cancel(job);
  });
  return h('ytl-tab-group-shape', {
    class: classes('ytlTabGroupShapeHost', {'ytlTabGroupShapeOverflowHidden': () => !!shape().isOverflowHidden}),
    ref: (/** !Element */ el) => host = el,
  },
  h('div', {class: 'ytlTabGroupShapeTabs', role: 'tablist'},
    h(IndexEach, {of: tabs, render: (tab, i) => h(TabShape, {shape: tab, isLastTab: () => i === tabs().length - 1})})),
  h('div', {class: classes('ytlTabGroupShapeSlider', {'ytlTabGroupShapeSliderTransition': transition}),
    style: () => `width:${width()}px; transform:translateX(${offset()}px)`}));
}, 'ytl-tab-group-shape (CoW)');

defineCoW('ytl-tab-group-shape', TabGroupShape, {props: {shape: PropKind.SIGNAL}});

/**
 * The tab shapes of a tab list (`lIN`, `ynu`): each tab's click runs its
 * endpoint as a navigation.
 * @param {?Array<!Object>|undefined} tabs
 * @param {function(!Object): !Object=} customTabRenderable Renders an
 *     expandable tab.
 * @return {!Array<!Object>}
 */
export function tabShapesOf(tabs, customTabRenderable) {
  const out = [];
  for (const t of tabs || []) {
    if (t.expandableTabRenderer && customTabRenderable) {
      const expandable = t.expandableTabRenderer;
      out.push({customTabRenderable: () => customTabRenderable(expandable)});
      continue;
    }
    const tab = t.tabRenderer;
    if (!tab) {
      out.push({});
      continue;
    }
    const endpoint = tab.endpoint;
    out.push({
      identifier: tab.tabIdentifier,
      title: tab.title,
      selected: !!tab.selected,
      disabled: !!tab.unselectable,
      icon: tab.icon,
      aTagConfig: {
        href: endpoint && endpoint.commandMetadata ? endpoint.commandMetadata.webCommandMetadata.url : undefined,
        forceNewState: true,
        onclick: (/** !Event */ e) => {
          const me = /** @type {!MouseEvent} */ (e);
          if (me.button || me.ctrlKey || me.metaKey || me.shiftKey || me.altKey) return;
          if (endpoint && endpoint.clickTrackingParams) logClick(endpoint.clickTrackingParams);
          fireCommand(/** @type {!Element} */ (e.currentTarget), endpoint);
        },
      },
    });
  }
  return out;
}

defineCoW('ytl-shorts-lockup-view-model-v2', ShortsLockup, {props: {
  data: PropKind.SIGNAL, inlineMetadata: PropKind.SIGNAL, aspectRatio: PropKind.SIGNAL, scrimStyle: PropKind.SIGNAL,
  className: PropKind.SIGNAL, useDefaultStyle: PropKind.SIGNAL,
}});
registerRenderer('shortsLockupViewModel', 'ytl-shorts-lockup-view-model-v2');

/** One chip of the chip bar (`chipViewModel`). */
const ChipViewModel = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  return h('ytl-chip-view-model', {class: 'ytlChipViewModelHost', 'on:click': (/** !Event */ e) => {
    const command = vm().tapCommand ? innertube(vm().tapCommand) : null;
    if (vm().loggingDirectives) logClick(vm().loggingDirectives.trackingParams);
    fireCommand(/** @type {!Element} */ (e.currentTarget), command);
  }}, h(ChipShape, {data: () => ({text: vm().text, selected: vm().selected, accessibilityLabel: vm().accessibilityLabel})}));
}, 'chip-view-model');

/** The chip bar (CoW `ytl-chip-bar-view-model`). */
const ChipBar = defineComponent((props) => {
  const chips = () => ((/** @type {!Object} */ (props.data()) || {}).chips || []);
  return h('ytl-chip-bar-view-model', {class: classes('ytlChipBarViewModelHost', () => props.className() || '')},
    h('div', {class: 'ytlChipBarViewModelChipBarScrollContainer', role: 'tablist'},
      h(IndexEach, {of: chips, render: (chip) => h('div', {class: 'ytlChipBarViewModelChipWrapper'},
        rendererOf(chip, {'chipViewModel': (r) => h(ChipViewModel, {data: r.data})}))})));
}, 'ytl-chip-bar-view-model (CoW)');

defineCoW('ytl-chip-bar-view-model', ChipBar, {props: {data: PropKind.SIGNAL, className: PropKind.SIGNAL}});
registerRenderer('chipBarViewModel', 'ytl-chip-bar-view-model');
