import '@polymer/polymer/polymer-legacy.js';

import {Polymer} from '@polymer/polymer/lib/legacy/polymer-fn.js';
import {dom} from '@polymer/polymer/lib/legacy/polymer.dom.js';
import {html} from '@polymer/polymer/lib/utils/html-tag.js';

import {AppLayoutBehavior} from '../app-layout-behavior/app-layout-behavior.js';
import {template as ytlTemplate} from '../../../../gen/templates/tp-ytl-app-header-layout.js';

/**
tp-ytl-app-header-layout is a wrapper element that positions an tp-ytl-app-header and other
content. This element uses the document scroll by default, but it can also
define its own scrolling region.

Using the document scroll:

```html
<tp-ytl-app-header-layout>
  <tp-ytl-app-header slot="header" fixed condenses effects="waterfall">
    <tp-ytl-app-toolbar>
      <div main-title>App name</div>
    </app-toolbar>
  </app-header>
  <div>
    main content
  </div>
</app-header-layout>
```

Using an own scrolling region:

```html
<tp-ytl-app-header-layout has-scrolling-region style="width: 300px; height: 400px;">
  <tp-ytl-app-header slot="header" fixed condenses effects="waterfall">
    <tp-ytl-app-toolbar>
      <div main-title>App name</div>
    </app-toolbar>
  </app-header>
  <div>
    main content
  </div>
</app-header-layout>
```

Add the `fullbleed` attribute to tp-ytl-app-header-layout to make it fit the size of
its container:

```html
<tp-ytl-app-header-layout fullbleed>
 ...
</app-header-layout>
```

@element tp-ytl-app-header-layout
@demo tp-ytl-app-header-layout/demo/simple.html Simple Demo
@demo tp-ytl-app-header-layout/demo/scrolling-region.html Scrolling Region
@demo tp-ytl-app-header-layout/demo/music.html Music Demo
@demo tp-ytl-app-header-layout/demo/footer.html Footer Demo
*/
Polymer({
  /** @override */
  _template: ytlTemplate(),

  is: 'tp-ytl-app-header-layout',
  behaviors: [AppLayoutBehavior],

  properties: {
    hasScrollingRegion: {type: Boolean, value: false, reflectToAttribute: true},
    rafId: {type: Number, value: -1},
    useRaf: {type: Boolean, value: true},
    useResizeObserver: {type: Boolean, value: true},
  },

  observers: ['resetLayout(isAttached, hasScrollingRegion)'],

  get header() {
    return dom(this.$.headerSlot).getDistributedNodes()[0];
  },

  _updateLayoutStates: function() {
    if (this.useRaf) {
      cancelAnimationFrame(this.rafId);
      this.rafId = requestAnimationFrame(this.performUpdate.bind(this));
    } else {
      this.performUpdate();
    }
  },

  attached: function() {
    if (!window.ResizeObserver || !this.useResizeObserver) return;
    this._resizeObserver = new ResizeObserver(entries => {
      let changed = false;
      for (const entry of entries) {
        const height = entry.borderBoxSize && entry.borderBoxSize.length > 0 ? entry.borderBoxSize[0].blockSize : entry.contentRect.height;
        if (height !== this._lastObservedHeight) {
          this._lastObservedHeight = height;
          changed = true;
        }
      }
      if (changed) {
        const header = this.header || this._observedHeader;
        if (header && typeof header.resetLayout === 'function') header.resetLayout();
      }
      this._updateLayoutStates();
    });
  },

  detached: function() {
    if (!this._resizeObserver) return;
    this._resizeObserver.disconnect();
    this._lastObservedHeight = this._observedHeader = this._resizeObserver = null;
  },

  performUpdate: function() {
    const header = this.header;
    if (!this.isAttached || !header) return;
    if (this.useResizeObserver && this._resizeObserver && this._observedHeader !== header) {
      this._resizeObserver.disconnect();
      this._resizeObserver.observe(header);
      this._observedHeader = header;
      this._lastObservedHeight = null;
    }
    this.$.wrapper.classList.remove('initializing');
    header.scrollTarget = this.hasScrollingRegion ? this.$.contentContainer : this.ownerDocument.documentElement;
    if (this.hasScrollingRegion) {
      if (header.style.left !== '') header.style.left = '';
      if (header.style.right !== '') header.style.right = '';
    } else {
      const rect = this.getBoundingClientRect();
      const left = rect.left + 'px';
      const right = document.documentElement.clientWidth - rect.right + 'px';
      if (header.style.left !== left) header.style.left = left;
      if (header.style.right !== right) header.style.right = right;
    }
    const containerStyle = this.$.contentContainer.style;
    const observed = this._lastObservedHeight;
    const headerHeight = observed !== undefined && observed !== null ? observed : header.offsetHeight;
    if (header.fixed && !header.condenses && this.hasScrollingRegion) {
      const margin = headerHeight + 'px';
      if (containerStyle.marginTop !== margin) containerStyle.marginTop = margin;
      if (containerStyle.paddingTop !== '') containerStyle.paddingTop = '';
    } else {
      const padding = headerHeight + 'px';
      if (containerStyle.paddingTop !== padding) containerStyle.paddingTop = padding;
      if (containerStyle.marginTop !== '') containerStyle.marginTop = '';
    }
  }
});
