/**
 * @fileoverview The image (`_.gA`) and its CoW host (`ytl-image`). The host
 * wraps each prop with a default in a new thunk (`_.KR`), keeps a cleanup
 * that revokes object URLs, and renders a `cond` on `data`. The image reads
 * about 27 optional props into a config (`TzK`) that picks image or icon,
 * class list and style; a `switch` renders the `img` (`mz4`), whose
 * after-render effect picks the source and loads it lazily.
 */
import {classes} from '../../framework/vm/classes.js';
import {Switch, cond} from '../../framework/vm/control.js';
import {afterRenderEffect, runUntracked, signal, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {defineComponent} from '../../framework/vm/render.js';
import {observeVisibility} from '../visibility.js';
import {contentModeClass} from './enums.js';
import {Icon, pickSource} from './primitives.js';

/** The image props with defaults (`_.KR`). */
const IMAGE_DEFAULTS = {
  alt: '', width: 0, height: 0, objectFit: '', loading: 'lazy', placeholder: false, fillParentWidth: true,
  fillParentHeight: true, notifyOnLoaded: false, notifyOnUnloaded: false, draggable: false, disabled: false, ariaHidden: false,
};

/**
 * @param {!Object} props
 * @return {!Object}
 */
function withDefaults(props) {
  const out = Object.assign({}, props);
  for (const key of Object.keys(IMAGE_DEFAULTS)) {
    const value = props[key];
    const fallback = IMAGE_DEFAULTS[key];
    out[key] = () => {
      const v = unwrap(value);
      return v === undefined || v === null ? fallback : v;
    };
  }
  return out;
}

/** Object URLs created for images; revoked when their owner goes. */
const objectUrls = new Set();

/**
 * The image config (`kZh` and `TzK`).
 * @param {!Object} props
 * @return {!Object}
 */
function imageConfig(props) {
  const data = unwrap(props.data) || {};
  const sources = data.thumbnails || data.sources || [];
  const icon = unwrap(props.iconName) || (sources[0] && sources[0].clientResource && sources[0].clientResource.imageName) || '';
  const fit = unwrap(props.objectFit);
  const config = {
    kind: icon && !(sources[0] && sources[0].url) ? 'icon' : 'image',
    sources,
    icon,
    alt: typeof unwrap(props.alt) === 'string' ? unwrap(props.alt) : '',
    width: unwrap(props.width),
    height: unwrap(props.height),
    loading: unwrap(props.loading),
    placeholder: unwrap(props.placeholder),
    draggable: unwrap(props.draggable),
    disabled: unwrap(props.disabled),
    ariaHidden: unwrap(props.ariaHidden),
    notifyOnLoaded: unwrap(props.notifyOnLoaded),
    notifyOnUnloaded: unwrap(props.notifyOnUnloaded),
    fillParentWidth: unwrap(props.fillParentWidth),
    fillParentHeight: unwrap(props.fillParentHeight),
    className: unwrap(props.imageClassName) || '',
    contentMode: contentModeClass(fit === 'contain' ? 'fit' : unwrap(props.contentMode)),
    backgroundColor: unwrap(props.backgroundColor) || '',
    borderRadius: unwrap(props.borderRadius) || 0,
    targetWidth: unwrap(props.targetWidth) || unwrap(props.width) || 0,
    ftlEligible: !!unwrap(props.ftlEligible),
    preload: !!unwrap(props.preload),
    sizes: unwrap(props.sizes) || '',
    srcset: !!unwrap(props.useSrcset),
    gradient: unwrap(props.gradient) || null,
    tint: unwrap(props.tint) || '',
    onLoad: props.onLoad || null,
  };
  config.classList = imageClassList(config);
  return config;
}

/**
 * @param {!Object} c
 * @return {string}
 */
function imageClassList(c) {
  let cls = 'ytlCoreImageHost';
  if (c.fillParentHeight) cls += ' ytlCoreImageFillParentHeight';
  if (c.fillParentWidth) cls += ' ytlCoreImageFillParentWidth';
  cls += ' ' + c.contentMode;
  if (c.className) cls += ' ' + c.className;
  return cls;
}

/**
 * The responsive source choice (`_.EG8`): the smallest source at least as
 * wide as the target width times the device pixel ratio.
 * @param {!Array<!Object>} sources
 * @param {number} width
 * @return {string}
 */
function chooseSource(sources, width) {
  const s = pickSource(/** @type {?} */ (sources), Math.round((width || 360) * (window.devicePixelRatio || 1)));
  return s ? s.url : '';
}

/** The `img` element (`mz4`). */
const ImageElement = defineComponent((props) => {
  const config = /** @type {function(): !Object} */ (props.config);
  const loaded = props.loaded;
  const setLoaded = props.setLoaded;
  /** @type {?HTMLImageElement} */
  let img = null;
  afterRenderEffect(() => {
    const c = config();
    runUntracked(() => {
      if (!img) return;
      const el = img;
      const src = chooseSource(c.sources, c.targetWidth);
      if (!src || el.getAttribute('src') === src) return;
      if (c.loading === 'eager' || c.preload) {
        el.src = src;
        return;
      }
      onCleanup(observeVisibility(el, () => {
        el.src = src;
      }));
    });
  }, 'RfEgBc');
  const onLoad = (/** !Event */ e) => {
    setLoaded(true);
    const c = config();
    if (typeof c.onLoad === 'function') c.onLoad(e);
    if (c.notifyOnLoaded) {
      const host = /** @type {!Element} */ (e.currentTarget).parentElement;
      if (host) host.dispatchEvent(new CustomEvent('image-loaded', {bubbles: true, composed: true}));
    }
  };
  const onError = () => setLoaded(false);
  return h('img', {
    class: () => (loaded() ? `${config().classList} ytlCoreImageLoaded` : config().classList),
    alt: () => config().alt,
    'aria-hidden': () => (config().ariaHidden ? 'true' : undefined),
    'data-disabled': () => (config().disabled ? 'true' : undefined),
    style: () => (config().backgroundColor ? `background-color: ${config().backgroundColor}` : loaded() ? 'background-color: transparent' : undefined),
    width: () => (config().fillParentWidth ? undefined : config().width || undefined),
    height: () => (config().fillParentHeight ? undefined : config().height || undefined),
    draggable: () => (config().draggable ? 'true' : undefined),
    'on:load': onLoad,
    'on:error': onError,
    ref: (/** !Element */ el) => {
      img = /** @type {!HTMLImageElement} */ (el);
    },
  });
}, 'mz4');

/** The image content: image or icon (`kZh`). */
const ImageContent = defineComponent((props) => {
  const config = () => imageConfig(props);
  return h(Switch, {
    value: () => config().kind,
    cases: [
      ['image', () => h(ImageElement, {data: props.data, config, loaded: props.loaded, setLoaded: props.setLoaded})],
      ['icon', () => h(Icon, {icon: () => config().icon, size: () => config().targetWidth || 24})],
    ],
  });
}, 'kZh');

/** The image (`_.gA`): a loaded signal, the gradient and the content. */
export const Image = defineComponent((props) => {
  const [loaded, setLoaded] = signal(false, 'MuHszf');
  const content = Object.assign({}, props, {loaded, setLoaded});
  return [
    cond(() => !!unwrap(props.gradient), () => h('div', {class: 'ytlCoreImageGradient'})),
    h(ImageContent, content),
  ];
}, 'gA');

/** The image CoW host. */
const ImageHost = defineComponent((rawProps) => {
  const props = withDefaults(rawProps);
  onCleanup(() => {
    for (const url of objectUrls) URL.revokeObjectURL(url);
    objectUrls.clear();
  });
  return h('ytl-image', {class: props.className, ref: (/** !Element */ el) => {}},
    cond(() => !!props.data(), () => h(Image, props)));
}, 'ytl-image (CoW)');

defineCoW('ytl-image', ImageHost, {props: {
  data: PropKind.SIGNAL, className: PropKind.SIGNAL, alt: PropKind.SIGNAL, width: PropKind.SIGNAL, height: PropKind.SIGNAL,
  objectFit: PropKind.SIGNAL, ftlEligible: PropKind.SIGNAL, notifyOnLoaded: PropKind.SIGNAL, notifyOnUnloaded: PropKind.SIGNAL,
  loading: PropKind.SIGNAL, placeholder: PropKind.SIGNAL, draggable: PropKind.SIGNAL, disabled: PropKind.SIGNAL,
  ariaHidden: PropKind.SIGNAL, iconName: PropKind.SIGNAL, targetWidth: PropKind.SIGNAL, imageClassName: PropKind.SIGNAL,
}});
