/**
 * @fileoverview The registry of renderers by their data's target id
 * (`"search-feed"`, `"search-page"`, ...), kept by the renderer behaviour.
 */

/** @type {!Map<string, !Element>} */
const targets = new Map();
/** @type {!WeakMap<!Element, string>} */
const idsByElement = new WeakMap();

/**
 * @param {string} id
 * @param {!Element} el
 */
export function registerTarget(id, el) {
  const old = idsByElement.get(el);
  if (old !== undefined && old !== id && targets.get(old) === el) targets.delete(old);
  targets.set(id, el);
  idsByElement.set(el, id);
}

/**
 * Removes `el` from the registry, whatever its id.
 * @param {!Element} el
 */
export function unregisterTarget(el) {
  const id = idsByElement.get(el);
  if (id === undefined) return;
  idsByElement.delete(el);
  if (targets.get(id) === el) targets.delete(id);
}
