/**
 * @fileoverview Badges: the badge shape (`_.Hly`, CoW `ytl-badge-shape`),
 * the metadata badge (`LDv`) and the badge-supported renderer (`CH9`, CoW
 * `ytl-badge-supported-renderer-impl`), which renders a badge list through
 * the renderer-type switch.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {cond, renderers} from '../../framework/vm/control.js';
import {computed, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';
import {flag} from '../../framework/flags.js';
import {getAccessibilityLabel} from '../../framework/text.js';
import {fireCommand} from '../commands.js';
import {BADGE_FLAGS, adsIncludeDot, badgeIsOverlay, badgeTypeClass, metadataBadgeStyle, nzRatingTypeOf, readFlags} from './enums.js';
import {Icon, themeColor, useTooltip} from './primitives.js';

/**
 * Resolves a badge icon: the filled style at 12 px, else the outline style
 * at 24 px.
 * @param {string} name
 * @return {{name: string, size: number}|null}
 */
function resolveBadgeIcon(name) {
  if (!name) return null;
  const filled = name.endsWith('_FILLED') ? name : `${name}_FILLED`;
  if (filled.length < 40) return {name, size: 12};
  return {name, size: 24};
}

/**
 * The badge shape. `data` holds `text`, `label`, `badgeStyle`, `icon`,
 * `thumbnail`, `tooltip` and the font and overlay flags.
 */
export const BadgeShape = defineComponent((props) => {
  const experiments = readFlags(BADGE_FLAGS);
  const d = () => unwrap(props.data) || {};
  const style = () => d().badgeStyle;
  const icon = computed(() => resolveBadgeIcon(d().icon || ''), undefined, 'badgeIcon');
  const tooltip = useTooltip(() => d().tooltip || '');
  return h('ytl-badge-shape', {
    class: classes('ytlBadgeShapeHost', () => badgeTypeClass(style()), {
      'ytlBadgeShapeThumbnailBadge': () => !!d().thumbnail,
      'ytlBadgeShapeOverlay': () => !!d().isOverlay,
      'ytlBadgeShapeAdsIncludeDot': () => !!d().adsIncludeDot,
      'ytlBadgeShapeModern': () => !!d().modern || flag('web_modern_badge_shape'),
      'ytlBadgeShapeTypography': () => true,
      'ytlBadgeShapeMediumFont': () => !!d().mediumFont,
      'ytlBadgeShapeLargeFont': () => !!d().largeFont,
      'ytlBadgeShapeIconOnly': () => !!d().icon && !d().text,
      'ytlBadgeShapeWrap': () => !!d().wrap,
      'ytlBadgeShapeRounded': () => !!d().rounded || experiments['web_badge_shape_rounded'],
      'ytlBadgeShapeAnimated': () => !!d().animatedText,
      'ytlBadgeShapeThumbnailBadgeRedesign': () => flag('enable_lockup_redesign') && !!d().thumbnail,
    }),
    style: styles({'background-color': () => themeColor(d().backgroundColor || null, null)}),
    role: () => (d().text || d().label ? 'img' : undefined),
    'aria-label': () => d().label || d().text || undefined,
    ref: tooltip,
  },
  cond(() => !!d().animatedText, () => h('div', {class: 'ytlBadgeShapeAnimatedText'}, () => d().animatedText)),
  cond(() => !!icon(), () => h('div', {class: 'ytlBadgeShapeIcon'}, h(Icon, {icon: () => icon().name, size: () => icon().size}))),
  h('div', {class: classes('ytlBadgeShapeText', {'ytlBadgeShapeTextHidden': () => !d().text}), 'aria-hidden': 'true'},
    () => d().text || ''));
}, 'Hly');

defineCoW('ytl-badge-shape', BadgeShape, {props: {data: PropKind.SIGNAL}});

/**
 * The badge config of a `metadataBadgeRenderer` (`QN8`).
 * @param {!Object} badge
 * @param {!Object} context
 * @return {!Object}
 */
function metadataBadgeConfig(badge, context) {
  const style = metadataBadgeStyle(badge.style);
  return {
    badgeStyle: style,
    nzRating: nzRatingTypeOf(badge.nzRating),
    text: badge.label || '',
    label: getAccessibilityLabel(badge) || badge.label || badge.tooltip || '',
    isOverlay: badgeIsOverlay(context.surface),
    icon: badge.icon ? badge.icon.iconType : (badge.ytIcon || ''),
    modern: flag('web_modern_badge_shape'),
    numBadgesInRow: context.numBadgesInRow || 0,
    adsIncludeDot: adsIncludeDot(badge.style) && !context.noDotAdBadge,
    tooltip: badge.tooltip || '',
    mediumFont: !!context.mediumFontAdBadge,
    largeFont: !!context.largeFontAdBadge,
    wrap: !!context.wrapBadges,
  };
}

/** The NZ content-rating badge. */
export const NzRatingBadge = defineComponent((props) => h('div', {
  class: classes('ytlNzRatingBadge', () => `ytlNzRatingBadge${String(props.rating()).toUpperCase()}`),
}), 'NzRatingBadge');

/** A metadata badge (`LDv`). */
const MetadataBadge = defineComponent((props) => {
  const config = computed(() => metadataBadgeConfig(unwrap(props.data) || {}, unwrap(props.context) || {}), undefined, 'QN8');
  const onClick = (/** !Event */ e) => {
    const badge = unwrap(props.data) || {};
    if (badge.onTapCommand) fireCommand(/** @type {!Element} */ (e.currentTarget), badge.onTapCommand);
    e.stopPropagation();
  };
  return h('ytl-metadata-badge-renderer', {class: 'ytlMetadataBadgeRendererHost', 'on:click': onClick},
    cond(() => !!config().nzRating, () => h(NzRatingBadge, {rating: () => config().nzRating}),
      () => h(BadgeShape, {data: config})));
}, 'LDv');

/**
 * The verified or strikethrough class of a badge's wrapper.
 * @param {string|undefined} style
 * @return {string}
 */
function wrapperStyleClass(style) {
  switch (style) {
    case 'BADGE_STYLE_TYPE_VERIFIED':
    case 'BADGE_STYLE_TYPE_VERIFIED_ARTIST':
      return 'ytlBadgeSupportedRendererBadgeShapeStyleTypeVerifiedArtist';
    case 'BADGE_STYLE_TYPE_SIMPLE_STRIKETHROUGH':
      return 'ytlBadgeSupportedRendererBadgeShapeStyleTypeStrikethrough';
    default:
      return '';
  }
}

/** One badge of the badge-supported renderer: its wrapper and the metadata badge. */
const BadgeItem = defineComponent((props) => h('div', {
  class: classes('badge-shape', 'ytlBadgeSupportedRendererBadgeShape', () => wrapperStyleClass((unwrap(props.data) || {}).style)),
}, h(MetadataBadge, {data: props.data, context: props.context})), 'BadgeItem');

/** Badge kinds this renderer does not render. */
const UnknownBadge = defineComponent((props) => null, 'Fne');

/** The badge-supported renderer (`CH9`). */
const BadgeSupportedRenderer = defineComponent((props) => {
  const context = () => ({
    largeFontAdBadge: props.largeFontAdBadge(), mediumFontAdBadge: props.mediumFontAdBadge(), noDotAdBadge: props.noDotAdBadge(),
    numBadgesInRow: props.numBadgesInRow(), wrapBadges: props.wrapBadges(), surface: 'METADATA',
  });
  return h('ytl-badge-supported-renderer-impl', {
    class: classes('ytlBadgeSupportedRendererHost', {'ytlBadgeSupportedRendererWrap': props.wrapBadges}),
  }, renderers(() => props.data() || [], {'metadataBadgeRenderer': BadgeItem}, UnknownBadge, {context}));
}, 'CH9');

defineCoW('ytl-badge-supported-renderer-impl', BadgeSupportedRenderer, {props: {
  data: PropKind.SIGNAL, largeFontAdBadge: PropKind.SIGNAL, mediumFontAdBadge: PropKind.SIGNAL, noDotAdBadge: PropKind.SIGNAL,
  numBadgesInRow: PropKind.SIGNAL, wrapBadges: PropKind.SIGNAL,
}});
