/**
 * @fileoverview The attribute sanitizer of the JSX renderer. Each static
 * attribute value is looked up in the Closure HTML contract tables that
 * polymer-resin also uses (per tag, then global, with contingent
 * attributes), and the contract type picks a handler. URLs must look safe;
 * HTML and resource URLs must be typed values, which plain strings never
 * are, so they become the innocuous value.
 */
import contracts from 'goog:security.html.contracts';

const INNOCUOUS = 'about:invalid#zClosurez';
const SAFE_URL = /^(?:(?:https?|mailto|ftp):|[^:/?#]*(?:[/?#]|$))/i;

/**
 * @param {string} name
 * @param {*} value
 * @return {string}
 */
function innocuous(name, value) {
  return INNOCUOUS;
}

/**
 * @param {string} name
 * @param {*} value
 * @return {string}
 */
function safeUrl(name, value) {
  const s = String(value);
  return SAFE_URL.test(s) ? s : INNOCUOUS;
}

/**
 * @param {string} name
 * @param {*} value
 * @return {string}
 */
function safeStyle(name, value) {
  return String(value);
}

/** Contract type to handler; types without one keep the value. */
const HANDLERS = {1: null, 2: innocuous, 3: safeUrl, 4: innocuous, 5: safeStyle, 7: null, 8: null, 10: null};

/**
 * @param {string} name
 * @return {?string}
 */
function contingentValueUnavailable(name) {
  throw new Error(`attribute contract depends on ${name}`);
}

/**
 * @param {string} tag
 * @param {string} name
 * @param {*} value
 * @return {*}
 */
export function sanitizeAttribute(tag, name, value) {
  if (value === null || value === undefined) return value;
  const attr = name.toLowerCase();
  const type = contracts.typeOfAttribute(tag.toLowerCase(), attr, contingentValueUnavailable);
  if (type === null) return value;
  const handler = HANDLERS[type];
  return handler ? handler(attr, value) : value;
}
