/**
 * @fileoverview Ad slot renderers: the slot, the in-feed layout (which
 * renders one of the ad layout view models) and promoted-video results.
 * Also the channel result renderer.
 */
import {Polymer} from '../../framework/polysi/register.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {registerRenderer} from '../../framework/registry.js';
import {stampRenderers} from '../../framework/stamper.js';
import {RendererBehavior} from '../renderer-behavior.js';
import {adLayoutEntered, adLayoutExited, adSlotEntered, adSlotExited} from '../logging.js';
import {AD_LAYOUT_TAGS} from '../vm/ads.js';
import {template as slotTemplate} from '../../../gen/templates/ytl-ad-slot-renderer.js';
import {template as layoutTemplate} from '../../../gen/templates/ytl-in-feed-ad-layout-renderer.js';
import {template as pyvTemplate} from '../../../gen/templates/ytl-search-pyv-renderer.js';
import {template as channelTemplate} from '../../../gen/templates/ytl-channel-renderer.js';

Polymer({
  _template: slotTemplate,
  is: 'ytl-ad-slot-renderer',
  behaviors: [RendererBehavior],
  observers: ['onAdSlotMetadataChanged(data.adSlotMetadata)', 'dataChanged(data)'],

  attached() {
    if (!this.adSlotMetadata) return;
    if (this.adSlotMetadata === (this.data && this.data.adSlotMetadata)) adSlotEntered(this.adSlotMetadata);
    else console.error('Ad slot metadata does not match the data');
  },

  detached() {
    if (this.adSlotMetadata) adSlotExited(this.adSlotMetadata);
  },

  onAdSlotMetadataChanged() {
    const meta = this.data && this.data.adSlotMetadata;
    if (!meta) return;
    if (this.isAttached && this.adSlotMetadata !== meta) {
      if (this.adSlotMetadata !== undefined) adSlotExited(this.adSlotMetadata);
      adSlotEntered(meta);
    }
    this.adSlotMetadata = meta;
  },

  /** @param {?Object} data */
  dataChanged(data) {
    const layout = data && data.fulfillmentContent && data.fulfillmentContent.fulfilledLayout;
    stampRenderers(this.$['fulfilled'], layout ? [layout] : []);
    const meta = data && data.adSlotMetadata;
    this.hostElement.setAttribute('slot-type', meta ? meta.slotType || '' : '');
  },
});
registerRenderer('adSlotRenderer', 'ytl-ad-slot-renderer');

const LAYOUT_CLASSES = {
  'LAYOUT_TYPE_DISPLAY_COMPACT_LANDSCAPE_NO_BUTTON': 'compact-landscape',
  'LAYOUT_TYPE_VIDEO_DISPLAY_COMPACT_BUTTON_GROUP': 'video-display',
  'LAYOUT_TYPE_TEXT_IMAGE_NO_BUTTON': 'text-image',
};

Polymer({
  _template: layoutTemplate,
  is: 'ytl-in-feed-ad-layout-renderer',
  behaviors: [RendererBehavior],
  observers: ['dataChanged(data)', 'onAdMetadataChanged_(data.adLayoutMetadata)'],

  /** @return {boolean} */
  storedMetadataIsCurrent_() {
    return !!this.storedAdSlotMetadata_ && !!this.storedAdLayoutMetadata_ && this.storedAdSlotMetadata_ === this.slotMetadata_() &&
        this.storedAdLayoutMetadata_ === (this.data && this.data.adLayoutMetadata);
  },

  attached() {
    if (this.storedMetadataIsCurrent_()) adLayoutEntered(this.storedAdSlotMetadata_, this.storedAdLayoutMetadata_);
  },

  detached() {
    if (this.storedMetadataIsCurrent_()) adLayoutExited(this.storedAdSlotMetadata_, this.storedAdLayoutMetadata_);
  },

  onAdMetadataChanged_() {
    const slot = this.slotMetadata_();
    const layout = this.data && this.data.adLayoutMetadata;
    if (!slot || !layout || this.storedAdLayoutMetadata_ === layout) return;
    if (this.isAttached) {
      if (this.storedAdLayoutMetadata_ && this.storedAdSlotMetadata_) adLayoutExited(this.storedAdSlotMetadata_, this.storedAdLayoutMetadata_);
      adLayoutEntered(slot, layout);
    }
    this.storedAdLayoutMetadata_ = layout;
    this.storedAdSlotMetadata_ = slot;
  },

  /**
   * The slot metadata of the ad slot this layout fills.
   * @return {?Object}
   */
  slotMetadata_() {
    const parent = this.parentComponent;
    const c = parent ? (parent.polymerController != null ? parent.polymerController : parent) : null;
    return (c && c.data && c.data.adSlotMetadata) || null;
  },

  /**
   * @param {string} type
   * @return {string}
   */
  layoutClass_(type) {
    return `${LAYOUT_CLASSES[type] || 'unknown'} style-scope ytl-in-feed-ad-layout-renderer`;
  },

  /** @param {?Object} data */
  dataChanged(data) {
    const content = (data && data.renderingContent) || {};
    stampRenderers(this.$['ad-layout'], [content]);
  },
});
registerRenderer('inFeedAdLayoutRenderer', 'ytl-in-feed-ad-layout-renderer');

Polymer({
  _template: pyvTemplate,
  is: 'ytl-search-pyv-renderer',
  behaviors: [RendererBehavior],
  observers: ['dataChanged(data)'],

  /** @param {?Object} data */
  dataChanged(data) {
    stampRenderers(this.$['contents'], (data && data.ads) || []);
  },
});
registerRenderer('searchPyvRenderer', 'ytl-search-pyv-renderer');

Polymer({
  _template: channelTemplate,
  is: 'ytl-channel-renderer',
  behaviors: [RendererBehavior],

  /** @param {!Event} e */
  onTap_(e) {
    e.preventDefault();
    this.resolveCommand(this.data && this.data.navigationEndpoint);
  },
});
registerRenderer('channelRenderer', 'ytl-channel-renderer');
for (const key of Object.keys(AD_LAYOUT_TAGS)) registerRenderer(key, AD_LAYOUT_TAGS[key]);
