/**
 * @fileoverview Class-list and style builders of view-model components
 * (`_.sn`, `_.TP`). Parts are strings, thunks, or objects whose values are
 * thunks or booleans. When every part is a string the result is joined
 * once; otherwise the result is a thunk that walks the parts on every
 * evaluation, so the element effect re-evaluates each part.
 */

/**
 * @param {!Array<*>} parts
 * @return {boolean}
 */
function allStatic(parts) {
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i];
    if (p && typeof p !== 'string') return false;
  }
  return true;
}

/**
 * @param {...*} parts
 * @return {string|function(): string}
 */
export function classes(...parts) {
  if (allStatic(parts)) {
    let out = '';
    for (const p of parts) {
      if (p) out += out ? ' ' + p : p;
    }
    return out;
  }
  return () => {
    let out = '';
    for (const p of parts) {
      if (!p) continue;
      if (typeof p === 'string') {
        out += out ? ' ' + p : p;
      } else if (typeof p === 'function') {
        const v = p();
        if (v) out += out ? ' ' + v : v;
      } else {
        for (const name in p) {
          if (!Object.prototype.hasOwnProperty.call(p, name)) continue;
          const on = p[name];
          if (typeof on === 'function' ? on() : on) out += out ? ' ' + name : name;
        }
      }
    }
    return out;
  };
}

/**
 * Builds a style attribute from objects of `key: value` pairs, whose values
 * may be thunks, and from thunks that return such objects; empty values are
 * left out.
 * @param {...*} parts
 * @return {string|undefined|function(): (string|undefined)}
 */
export function styles(...parts) {
  const build = () => {
    let out = '';
    for (const part of parts) {
      const p = typeof part === 'function' ? part() : part;
      if (!p) continue;
      for (const key in p) {
        if (!Object.prototype.hasOwnProperty.call(p, key)) continue;
        const raw = p[key];
        const v = typeof raw === 'function' ? raw() : raw;
        if (v != null && v !== '') out += `; ${key}: ${v}`;
      }
    }
    return out ? out.slice(2) : undefined;
  };
  for (const p of parts) {
    if (!p) continue;
    if (typeof p === 'function') return build;
    for (const key in p) {
      if (typeof p[key] === 'function') return build;
    }
  }
  return build();
}
