/**
 * @fileoverview The behaviours that every PolySi element gets, as kevlar's
 * registration adds them: setup on creation (iron behaviour adaptations,
 * then injection), dependency injection, and template helpers.
 */
import {rootInjector} from '../injector.js';
import {adaptIronBehaviors} from './iron.js';

/**
 * Setup that every element runs when it is created: the iron behaviour
 * adaptations of PolySi controllers, then injection.
 * @polymerBehavior
 */
export const InitBehavior = {
  created() {
    if (this.hostElement !== this) adaptIronBehaviors(this);
    this.initializeInjection();
  },
};

/**
 * @param {*} behavior
 * @param {!Array<!Object>} out
 */
function collectInjectMaps(behavior, out) {
  if (Array.isArray(behavior)) {
    for (const b of behavior) collectInjectMaps(b, out);
  } else if (behavior && behavior.inject) {
    out.push(behavior.inject);
  }
}

/** @polymerBehavior */
export const InjectBehavior = {
  /** Registers `provide`d values and resolves `inject` maps into fields. */
  initializeInjection() {
    const provide = this.provide;
    if (provide) {
      for (const token of Object.keys(provide)) rootInjector.provide(token, provide[token]);
    }
    const maps = [];
    collectInjectMaps(this.behaviors || this.constructor.psBehaviors || [], maps);
    if (this.inject) maps.push(this.inject);
    const seen = new Set();
    for (const map of maps) {
      for (const key of Object.keys(map)) {
        if (seen.has(key)) continue;
        seen.add(key);
        this[key] = rootInjector.resolve(map[key]);
      }
    }
  },
};

/** @polymerBehavior */
export const TemplateHelpersBehavior = {
  created() {},

  /**
   * @param {*} a
   * @param {*} b
   * @return {boolean}
   */
  equals(a, b) {
    return a === b;
  },

  /**
   * @param {*} value
   * @return {boolean}
   */
  isEmpty(value) {
    return !value || (Array.isArray(value) && value.length === 0);
  },

  /**
   * @param {*} value
   * @return {boolean}
   */
  isDefined(value) {
    return value !== undefined;
  },

  /**
   * @param {string} name
   * @return {!Function}
   */
  bindCb(name) {
    return this[name].bind(this);
  },
};


/**
 * Lets stock Polymer elements stand where code expects a PolySi host: the
 * element is its own host and controller.
 * @polymerBehavior
 */
export const HostElementBehavior = {
  /** @return {!Object} */
  get hostElement() {
    return this;
  },

  /** @param {*} value */
  set hostElement(value) {},

  /** @return {!Object} */
  get polymerController() {
    return this;
  },

  /** @param {*} value */
  set polymerController(value) {},
};
