/**
 * @fileoverview Signal-schema controllers: PolySi controllers that are not
 * Polymer instances. The element's property and observer declarations
 * become reactive schemas once per type; behaviours may add more in
 * `beforeRegister` through `addReactiveSchema`. Every property is a path
 * store on the controller's signal proxy, the template is parsed by
 * `template.js` and stamped with one effect per binding, and observers,
 * computed properties, notify events and reflected attributes are effects
 * (`schema.js`).
 *
 * Lifecycle: the constructor registers the type and parses the template
 * once, adds the host listeners and calls `created()`, which creates the
 * property stores, applies defaults, creates the computed effects and runs
 * the `created` hooks. The first connection runs `ready()`: stamping, the
 * ShadyDOM shadow root, the observer, notify and reflect effects, and the
 * `ready` hooks.
 */
import {addListener, gestures} from '@polymer/polymer/lib/utils/gestures.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {camelToDash, dashToCamel} from '../case.js';
import {runUntracked} from '../vm/effect.js';
import {InitBehavior, InjectBehavior, TemplateHelpersBehavior} from './base-behaviors.js';
import {adaptIronBehaviors} from './iron.js';
import {SignalProxy, toPath} from './proxy.js';
import {createComputed, createNotify, createObserver, createReflect, parseMethod} from './schema.js';
import {parseTemplate, stampTemplate} from './template.js';

/**
 * @typedef {{
 *   type: string,
 *   propertyKey: string,
 *   value: *,
 *   attributeType: *,
 *   readOnly: boolean,
 *   method: ?Object,
 *   selector: ?Function,
 *   selectorArgs: ?Array<string>,
 * }}
 */
let ReactiveSchema;

/**
 * Lifecycle hooks, called per behaviour and then for the element.
 * `initFields_` stands for a class constructor body: it sets instance
 * fields after the property stores exist and before defaults and computed
 * properties. Behaviours without one run their `constructor`, which for a
 * plain object is `Object`, as YouTube's plain behaviours do.
 */
const HOOKS = ['initFields_', 'created', 'attached', 'detached', 'ready', 'beforeRegister', 'registered', 'attributeChanged'];

/** Declaration keys that are not copied onto the controller prototype. */
const NOT_COPIED = new Set(HOOKS.concat(['properties', 'observers', 'behaviors', 'listeners', 'hostAttributes', 'is', '_template', 'keyBindings']));

/**
 * Flattens nested behaviour lists. A behaviour listed more than once keeps
 * its last position, and the ones in `skip` are left out.
 * @param {!Array<*>} behaviors
 * @param {!Set<!Object>} skip
 * @return {!Array<!Object>}
 */
function flattenBehaviors(behaviors, skip) {
  const out = [];
  const seen = new Set(skip);
  const walk = list => {
    for (let i = list.length - 1; i >= 0; i--) {
      const b = list[i];
      if (Array.isArray(b)) walk(b);
      else if (b && !seen.has(b)) {
        seen.add(b);
        out.unshift(/** @type {!Object} */ (b));
      }
    }
  };
  walk(behaviors);
  return out;
}

/**
 * Merges the declarations of the behaviours and the element and turns them
 * into reactive schemas. A later declaration of a property replaces an
 * earlier one completely; the property keeps its first position.
 * @param {!Array<!Object>} sources
 * @return {{schemas: !Array<!ReactiveSchema>, properties: !Object<string, !Object>}}
 */
function buildSchemas(sources) {
  const properties = {};
  let observers = [];
  for (const source of sources) {
    const props = source.properties;
    if (props) {
      for (const name of Object.keys(props)) {
        const decl = props[name];
        properties[name] = typeof decl === 'function' ? {type: decl} : Object.assign({}, decl);
      }
    }
    if (source.observers) observers = observers.concat(source.observers);
  }
  const schemas = [];
  const make = (type, key, extra) => Object.assign({type, propertyKey: key, value: undefined, attributeType: null, readOnly: false,
    method: null, selector: null, selectorArgs: null}, extra);
  for (const name of Object.keys(properties)) {
    const decl = properties[name];
    if (decl.computed) {
      schemas.push(make('computeWithMethod', name, {method: parseMethod(decl.computed), value: decl.value}));
    } else if (decl.selector) {
      schemas.push(make('redux', name, {selector: decl.selector, selectorArgs: decl.selectorArgs || []}));
    } else {
      schemas.push(make('signal', name, {value: decl.value, attributeType: decl.type || String, readOnly: !!decl.readOnly}));
    }
    if (decl.reflectToAttribute) schemas.push(make('reflect', name, {}));
    if (decl.observer) schemas.push(make('observe', name, {method: {methodName: decl.observer, args: [{type: 'path', path: name, value: undefined}]}}));
    if (decl.notify) schemas.push(make('notify', name, {}));
  }
  for (const expr of observers) schemas.push(make('observe', '', {method: parseMethod(expr)}));
  return {schemas, properties};
}

/**
 * @param {?string} value
 * @param {*} type
 * @return {*}
 */
function deserialize(value, type) {
  switch (type) {
    case Boolean:
      return value !== null;
    case Number:
      return value === null ? null : Number(value);
    case Object:
    case Array:
      if (value === null) return null;
      try {
        return JSON.parse(value);
      } catch (e) {
        return value;
      }
    case Date:
      return value === null ? null : new Date(isNaN(Number(value)) ? value : Number(value));
    default:
      return value;
  }
}

/**
 * @param {*} value
 * @return {string|undefined}
 */
function serialize(value) {
  if (value == null || value === false) return undefined;
  if (value === true) return '';
  return typeof value === 'object' ? JSON.stringify(value) : String(value);
}

/**
 * @typedef {{
 *   sources: !Array<!Object>,
 *   info: !Object,
 *   reactiveSchemas: !Array<!ReactiveSchema>,
 *   registered: boolean,
 *   templateParsed: boolean,
 *   templateInfo: ?Object,
 *   listeners: !Array<!Array<string>>,
 *   hostAttributes: !Object<string, *>,
 *   hooks: !Object<string, !Array<!Function>>,
 *   constructors: !Array<!Function>,
 * }}
 */
let ControllerParams;

/**
 * A class constructor that runs `init`. YouTube's class constructors also
 * call an empty base class constructor; Closure removes that call here.
 * @param {?Function|undefined} init
 * @return {!Function}
 */
function classConstructor(init) {
  return /** @this {*} */ function() {
    if (init) init.call(this);
  };
}

/** The base class of signal-schema controllers. */
export class SignalController {
  /**
   * @param {!HTMLElement} host
   * @param {!ControllerParams} params
   */
  constructor(host, params) {
    /** @const {!Object} */
    this.polySiInfo = params.info;
    /** @const {!ControllerParams} */
    this.polySiParams = params;
    /** @const {!Object} */
    this.polySiContext = {};
    /** @type {boolean} */
    this.didCallReady = false;
    /** @type {boolean} */
    this.isPolySiElementConnected = false;
    /** @const {!Set<string>} */
    this.mutablePropNames = new Set();
    /** @type {boolean} */
    this.reflecting = false;
    /** @type {*} */
    this.allowedProps = params.info.allowedProps;
    /** @type {boolean} */
    this.isAttached = false;
    /** @const {!HTMLElement} */
    this.hostElement = host;
    /** @type {*} */
    this.json = undefined;
    /** @type {boolean} */
    // Kevlar's constructor reads `params.legacyOptimizations`, which no
    // registration sets, so `disable-upgrade` never disables a schema host.
    this.upgradeDisabled = false;
    /** @const {!SignalProxy} */
    this.signalProxy = new SignalProxy(this, null);
    this.signalProxy.methodHost = this;
    /** @const {!Object<string, boolean>} */
    this.__dataHasAccessor = {};
    for (const schema of params.reactiveSchemas) {
      if (schema.type === 'signal') this.__dataHasAccessor[schema.propertyKey] = true;
    }
    /** @type {?Object} */
    this.$ = null;
    if (!this.upgradeDisabled) this.initialize_();
  }

  /** @private */
  initialize_() {
    const params = this.polySiParams;
    if (!params.registered) {
      params.registered = true;
      this.registerType_();
    }
    if (!params.templateParsed) {
      params.templateParsed = true;
      const source = params.info._template;
      const template = typeof source === 'function' ? source() : source;
      if (template) {
        if (window.ShadyCSS) window.ShadyCSS.prepareTemplate(template, this.is);
        params.templateInfo = parseTemplate(template);
      }
    }
    this.addHostListeners_();
    const status = this.hostElement.loggingStatus;
    if (status) status.isInitializing = true;
    runUntracked(() => this.created());
    if (status) status.isInitializing = false;
  }

  /**
   * Runs the `beforeRegister` hooks with `addReactiveSchema` live, then the
   * `registered` hooks. Once per type.
   * @private
   */
  registerType_() {
    const params = this.polySiParams;
    const proto = Object.getPrototypeOf(this);
    proto.addReactiveSchema = schema => params.reactiveSchemas.push(schema);
    try {
      for (const hook of params.hooks['beforeRegister']) hook.call(proto);
    } finally {
      proto.addReactiveSchema = () => {};
    }
    for (const hook of params.hooks['registered']) hook.call(proto);
  }

  /** @private */
  addHostListeners_() {
    const host = this.hostElement;
    for (const [event, method] of this.polySiParams.listeners) {
      const handler = e => {
        const fn = this[method];
        if (typeof fn === 'function') fn.call(this, e, e.detail);
      };
      if (gestures[event]) addListener(host, event, handler);
      else host.addEventListener(event, handler);
    }
  }

  /**
   * @param {string} name
   * @param {...*} args
   * @private
   */
  runHooks_(name, ...args) {
    for (const hook of this.polySiParams.hooks[name]) hook.apply(this, args);
  }

  /**
   * Injection, the property stores, the instance fields, defaults and
   * computed effects, iron adaptations, then the `created` hooks.
   */
  created() {
    const params = this.polySiParams;
    /** @type {?} */ (this).provide = params.info.provide;
    this.initializeInjection();
    const proxy = this.signalProxy;
    const schemas = params.reactiveSchemas;
    for (const schema of schemas) {
      if (schema.type !== 'signal') continue;
      this.mutablePropNames.add(schema.propertyKey);
      proxy.resolve(schema.propertyKey);
    }
    for (const ctor of params.constructors) ctor.apply(this);
    for (const schema of schemas) {
      if (schema.type !== 'signal' || schema.value === undefined) continue;
      const value = schema.value;
      this[schema.propertyKey] = typeof value === 'function' ? value.call(this) : value;
    }
    for (const schema of schemas) {
      if (schema.type === 'computeWithMethod') {
        createComputed(proxy, this, schema.propertyKey, /** @type {!Object} */ (schema.method), schema.value);
      } else if (schema.type === 'redux') {
        const selector = /** @type {!Function} */ (schema.selector);
        const args = [{type: 'path', path: 'reduxPropertiesRecomputeTrigger', value: undefined}]
            .concat((schema.selectorArgs || []).map(path => ({type: 'path', path, value: undefined})));
        const name = `__redux__${schema.propertyKey}`;
        Object.defineProperty(this, name, {value: (trigger, ...rest) => selector(this.getState ? this.getState() : {}, ...rest)});
        createComputed(proxy, this, schema.propertyKey, {methodName: name, args}, undefined);
      }
    }
    adaptIronBehaviors(this);
    this.runHooks_('created');
  }

  /** Stamps the template and creates the remaining effects. */
  ready() {
    if (this.beforeReady) this.beforeReady();
    const params = this.polySiParams;
    const proxy = this.signalProxy;
    if (params.templateInfo) {
      const {dom, nodesById} = stampTemplate(params.templateInfo, {proxy, methodHost: this, eventHost: this, getModel: null, enabled: null});
      const host = wrap(this.hostElement);
      host.attachShadow({mode: 'open', shadyUpgradeFragment: dom});
      host.shadowRoot.appendChild(dom);
      this.root = host.shadowRoot;
      this.$ = nodesById;
    }
    for (const schema of params.reactiveSchemas) {
      if (schema.type === 'observe') createObserver(proxy, this, /** @type {!Object} */ (schema.method));
      else if (schema.type === 'notify') createNotify(proxy, this.hostElement, schema.propertyKey);
      else if (schema.type === 'reflect') createReflect(proxy, this, schema.propertyKey);
    }
    const host = this.hostElement;
    for (const name of Object.keys(params.hostAttributes)) {
      if (host.hasAttribute(name)) continue;
      const str = serialize(params.hostAttributes[name]);
      if (str !== undefined) host.setAttribute(name, str);
    }
    this.runHooks_('ready');
  }

  connectedCallback() {
    if (this.upgradeDisabled) return;
    this.isPolySiElementConnected = true;
    if (!this.didCallReady) {
      this.didCallReady = true;
      runUntracked(() => this.ready());
    }
    this.isAttached = true;
    this.runHooks_('attached');
  }

  disconnectedCallback() {
    if (this.upgradeDisabled) return;
    this.isPolySiElementConnected = false;
    this.isAttached = false;
    this.runHooks_('detached');
  }

  /**
   * @param {string} name
   * @param {?string} oldValue
   * @param {?string} value
   */
  attributeChangedCallbackWrapper(name, oldValue, value) {
    this.attributeChangedCallback(name, oldValue, value);
  }

  /**
   * @param {string} name
   * @param {?string} oldValue
   * @param {?string} value
   */
  attributeChangedCallback(name, oldValue, value) {
    if (name === 'disable-upgrade') {
      if (value === null && this.upgradeDisabled) {
        this.upgradeDisabled = false;
        this.initialize_();
        if (this.hostElement.isConnected) this.connectedCallback();
      }
      return;
    }
    if (this.reflecting) return;
    const camel = dashToCamel(name);
    const type = this.constructor.typesForSignals[camel];
    if (type === undefined) return;
    this[camel] = deserialize(value, type);
    this.runHooks_('attributeChanged', name, oldValue, value);
  }

  /**
   * @param {string|!Array<string|number>} path
   * @param {*} value
   * @param {*=} root
   */
  set(path, value, root) {
    if (root !== undefined) throw new Error('set() with a root object');
    const parts = toPath(path);
    if (parts.length === 1 && parts[0] === 'hidden') {
      this.hostElement.hidden = !!value;
      return;
    }
    this.signalProxy.setWithPath(parts, value);
  }

  /**
   * @param {string|!Array<string|number>} path
   * @param {*=} root Read the path on this object instead of the stores.
   * @return {*}
   */
  get(path, root) {
    const parts = toPath(path);
    if (root !== undefined) {
      let value = root;
      for (const part of parts) {
        if (value == null) return undefined;
        value = value[part];
      }
      return value;
    }
    if (parts.length === 1 && parts[0] === 'hidden') return this.hostElement.hidden;
    return this.signalProxy.getWithPath(parts);
  }

  /**
   * @param {string|!Array<string|number>} path
   * @param {*=} value
   */
  notifyPath(path, value) {
    this.signalProxy.notifyPath(toPath(path), arguments.length === 2 ? {value} : undefined);
  }

  /**
   * @param {string} path
   * @param {...*} items
   * @return {number}
   */
  push(path, ...items) {
    const parts = toPath(path);
    return this.signalProxy.resolve(parts[0]).push(parts.slice(1), items);
  }

  /**
   * @param {string} path
   * @param {number} start
   * @param {number=} deleteCount
   * @param {...*} items
   * @return {!Array<*>}
   */
  splice(path, start, deleteCount, ...items) {
    const parts = toPath(path);
    const store = this.signalProxy.resolve(parts[0]);
    const array = /** @type {!Array<*>} */ (store.peek(parts.slice(1)));
    const count = deleteCount === undefined ? array.length - start : deleteCount;
    return store.splice(parts.slice(1), start, count, items);
  }

  /**
   * @param {string} path
   * @return {*}
   */
  pop(path) {
    const parts = toPath(path);
    return this.signalProxy.resolve(parts[0]).pop(parts.slice(1));
  }

  /**
   * @param {string} path
   * @param {...*} items
   * @return {number}
   */
  unshift(path, ...items) {
    const parts = toPath(path);
    return this.signalProxy.resolve(parts[0]).unshift(parts.slice(1), items);
  }

  /**
   * @param {string} path
   * @param {!Array<!Object>} splices
   */
  notifySplices(path, splices) {
    const parts = toPath(path);
    this.signalProxy.resolve(parts[0]).notifySplices(parts.slice(1), splices);
  }

  /**
   * @param {string} name
   * @return {boolean}
   */
  canNotifyPath(name) {
    return this.mutablePropNames.has(name);
  }

  /**
   * @param {string} name
   * @param {*} value
   * @return {boolean}
   */
  _setPendingProperty(name, value) {
    this.set(name, value);
    return false;
  }

  /**
   * @param {string} path
   * @param {*} value
   */
  _setPendingPropertyOrPath(path, value) {
    this.notifyPath(path, value);
  }

  /** @return {boolean} */
  get __isPropertyEffectsClient() {
    return true;
  }

  _enableProperties() {}

  _addPropertyEffect() {}

  _stampTemplate() {
    throw new Error('_stampTemplate on a signal-schema controller');
  }

  /** @param {!Object} props */
  setProperties(props) {
    for (const key of Object.keys(props)) this[key] = props[key];
  }

  /** @return {!Object} */
  get properties() {
    return {};
  }

  /** @return {!Array<string>} */
  get observers() {
    return [];
  }

  /**
   * @param {string} type
   * @param {*=} detail
   * @param {{bubbles: (boolean|undefined), cancelable: (boolean|undefined), composed: (boolean|undefined), node: (?EventTarget|undefined)}=} options
   * @return {!Event}
   */
  fire(type, detail, options) {
    const opts = options || {};
    const event = new CustomEvent(type, {
      bubbles: opts.bubbles !== false,
      cancelable: !!opts.cancelable,
      composed: opts.composed !== false,
      detail: detail == null ? {} : detail,
    });
    const node = opts.node != null ? opts.node : this.hostElement;
    const target = node.hostElement != null ? node.hostElement : node;
    target.dispatchEvent(event);
    return event;
  }

  linkPaths() {}

  unlinkPaths() {}

  /**
   * @param {string} name
   * @return {boolean}
   */
  hasAttribute(name) {
    if (name === 'dir') return false;
    if (name === 'disable-upgrade') return this.hostElement.hasAttribute('disable-upgrade');
    throw new Error(`hasAttribute(${name}) on a controller`);
  }
}

/**
 * Creates the controller class of a signal-schema element.
 * @param {!Object} info The object passed to Polymer().
 * @return {function(new:SignalController, !HTMLElement)}
 */
export function createSignalControllerClass(info) {
  const behaviors = flattenBehaviors(info.behaviors || [], new Set([InitBehavior, InjectBehavior, TemplateHelpersBehavior]))
      .concat([InjectBehavior, TemplateHelpersBehavior]);
  const sources = behaviors.concat([info]);
  const {schemas, properties} = buildSchemas(sources);
  const hooks = {};
  for (const name of HOOKS) hooks[name] = sources.map(s => s[name]).filter(fn => typeof fn === 'function');
  const listeners = [];
  const hostAttributes = {};
  for (const source of sources) {
    if (source.listeners) {
      for (const event of Object.keys(source.listeners)) listeners.push([event, source.listeners[event]]);
    }
    if (source.hostAttributes) Object.assign(hostAttributes, source.hostAttributes);
  }
  const constructors = behaviors.map(b => typeof b.initFields_ === 'function' ? classConstructor(b.initFields_) : b.constructor)
      .concat([classConstructor(info.initFields_)]);
  /** @type {!ControllerParams} */
  const params = {sources, info, reactiveSchemas: schemas, registered: false, templateParsed: false, templateInfo: null,
    listeners, hostAttributes, hooks, constructors};

  class SignalSchemaController extends SignalController {
    /** @param {!HTMLElement} host */
    constructor(host) {
      super(host, params);
    }
  }
  const proto = SignalSchemaController.prototype;
  for (const source of sources) {
    for (const name of Object.getOwnPropertyNames(source)) {
      if (NOT_COPIED.has(name)) continue;
      Object.defineProperty(proto, name, /** @type {!ObjectPropertyDescriptor} */ (Object.getOwnPropertyDescriptor(source, name)));
    }
  }
  proto.useSignals = true;
  if (!('behaviors' in proto)) proto.behaviors = behaviors;
  proto.is = info.is;
  proto.localName = info.is;
  const typesForSignals = {};
  const observed = ['disable-upgrade'];
  for (const schema of schemas) {
    if (schema.type !== 'signal') continue;
    typesForSignals[schema.propertyKey] = schema.attributeType;
    observed.push(camelToDash(schema.propertyKey));
  }
  SignalSchemaController.typesForSignals = typesForSignals;
  SignalSchemaController.observedAttributes = observed;
  SignalSchemaController.psSchema = {properties};
  SignalSchemaController.psBehaviors = behaviors;
  SignalSchemaController.psInfo = info;
  SignalSchemaController.psKind = 'signal';
  return SignalSchemaController;
}
