/**
 * @fileoverview Entry point: defines all elements, loads the simulated
 * network responses, opens the logging queue, then creates the app and
 * exposes the hooks the benchmark steps use as `window.ytlWorkload`.
 */
import './elements/members.js';
import './elements/core.js';
import './elements/buttons.js';
import './elements/thumbnail.js';
import './elements/video.js';
import './elements/lists.js';
import './elements/ads.js';
import './elements/search.js';
import './elements/shell.js';
import './elements/app.js';
import './elements/watch.js';
import './elements/shopping.js';
import './elements/infocards.js';
import './elements/comments.js';
import './elements/browse.js';
import './elements/browse-siblings.js';
import './vm/attributed-string.js';
import './vm/badges.js';
import './vm/image.js';
import './vm/button-shape.js';
import './vm/chips.js';
import './vm/thumbnails.js';
import './vm/lockups.js';
import './vm/ads.js';
import './vm/watch.js';
import './vm/comments.js';
import './vm/channel.js';
import {loadResponses, resetResponses} from './network.js';
import {installAttentionLogging, openLogQueue} from './logging.js';
import {startHeartbeat} from './telemetry.js';
import {whenIdle} from './scheduler.js';

/** Response files in dist/data, by kind, in the order steps request them. */
const MANIFEST = {
  'search-init': ['search-init'],
  'search-append': ['search-append-1', 'search-append-2'],
  'search-reload': ['search-reload'],
  'watch': ['watch-1', 'watch-2', 'watch-1'],
  'comments-reload': ['comments-reload'],
  'comments-append': ['comments-append-1', 'comments-append-2'],
  'related-append': ['related-append'],
  'browse': ['channel-home', 'channel-videos'],
  'grid-append': ['grid-append-1', 'grid-append-2'],
  'player': ['channel-player'],
};

/**
 * Resolves on the next `name` event on window, or, with `targetIds`, once a
 * `name` event has come for each of them (by `detail.targetId`).
 * @param {string} name
 * @param {?Array<string>=} targetIds
 * @return {!Promise<?Event>}
 */
function nextEvent(name, targetIds) {
  if (!targetIds) return new Promise(resolve => window.addEventListener(name, resolve, {once: true}));
  const pending = new Set(targetIds);
  return new Promise(resolve => {
    const listener = (e) => {
      pending.delete(e.detail && e.detail.targetId);
      if (pending.size) return;
      window.removeEventListener(name, listener);
      resolve(null);
    };
    window.addEventListener(name, listener);
  });
}

async function boot() {
  installAttentionLogging();
  startHeartbeat();
  const base = document.documentElement.getAttribute('data-ytl-data') || 'data';
  await Promise.all([loadResponses(base, MANIFEST), openLogQueue()]);
  const app = document.createElement('ytl-app');
  app.id = 'app';
  document.body.appendChild(app);
  await whenIdle();
  window['ytlWorkload'] = {whenIdle, nextEvent, resetResponses, app};
  window.dispatchEvent(new CustomEvent('ytl-ready'));
}

boot();
