/**
 * @fileoverview The renderer stamper behaviour of renderers that stamp
 * InnerTube sub-renderers into containers of their template. An element
 * describes its containers in `configureRendererStamper()`: a map from a
 * data path to `{id, mapping, initialRenderPriority, attributes,
 * properties, events}`, or behaviours in `stampDom`. Each entry becomes a
 * wildcard observer on its path, served by a per-instance bound function:
 * declared before a legacy element is defined (`registerDeclarations_`),
 * or added as a reactive schema in `beforeRegister` on signal-schema
 * elements. A root
 * change re-stamps the container (reusing children whose `is` is the tag,
 * so never view-model hosts), a
 * splice inserts new children, and any other change is forwarded to the
 * child as a path notification. New children are inserted as one
 * fragment and get their data afterwards. A container with an
 * `initialRenderPriority` renders its first change in a scheduler job;
 * later changes render at once.
 */
import {dom} from '@polymer/polymer/lib/legacy/polymer.dom.js';
import {hostDom, styleSubtree} from '../framework/host-dom.js';
import {getConfig} from '../framework/flags.js';
import {Priority, cancel, schedule} from './scheduler.js';

/**
 * A mapping value is a tag name, or `{component, properties, params}`:
 * properties are data paths and params are constant values, which only
 * children of that renderer key get.
 * With `enablePropertyObservers`, the parent also watches each property it
 * passes and writes the new value to the live children of that component.
 * @typedef {{
 *   id: string,
 *   mapping: !Object<string, (string|{component: string, properties: (!Object<string, string>|undefined), params: (!Object<string, *>|undefined), enablePropertyObservers: (boolean|undefined)})>,
 *   initialRenderPriority: (number|undefined),
 *   attributes: (!Object<string, string>|undefined),
 *   properties: (!Object<string, string>|undefined),
 *   events: (boolean|undefined),
 * }}
 */
let StampConfig;

/**
 * @param {string} id
 * @return {string}
 */
function observerName(id) {
  return `stamp${id.replace('-', '_')}_`;
}

/**
 * @param {{configId: string, component: string, propName: string}} binding
 * @return {string}
 */
function propertyObserverName(binding) {
  return `stamperUpdate_${binding.configId}_${binding.component}_${binding.propName}_`;
}

/**
 * The properties that mapping entries with `enablePropertyObservers` pass
 * from the parent: the container id, the component, the property and the
 * parent's property it comes from.
 * @param {!Object<string, !StampConfig>} stampDom
 * @return {!Array<{configId: string, component: string, propName: string, parentPropName: string}>}
 */
function propertyBindingsOf(stampDom) {
  const bindings = [];
  for (const path of Object.keys(stampDom)) {
    const config = stampDom[path];
    for (const key of Object.keys(config.mapping)) {
      const mapped = config.mapping[key];
      if (typeof mapped === 'string' || !mapped.enablePropertyObservers || !mapped.properties) continue;
      for (const propName of Object.keys(mapped.properties)) {
        bindings.push({configId: config.id, component: mapped.component, propName, parentPropName: mapped.properties[propName]});
      }
    }
  }
  return bindings;
}

/**
 * The first key of the entry's mapping that `item` has with a truthy
 * value. Items without one are not stamped.
 * @param {!StampConfig} config
 * @param {?Object} item
 * @return {?string}
 */
function itemKey(config, item) {
  const mapping = config.mapping;
  for (const key in mapping) {
    if (mapping.hasOwnProperty(key) && item[key]) return key;
  }
  return null;
}

/**
 * Whether a container reuses components: its own setting, else the page's
 * `REUSE_COMPONENTS`.
 * @param {!StampConfig} config
 * @return {boolean}
 */
function reusesComponents(config) {
  return config.reuseComponents === undefined ? !!getConfig('REUSE_COMPONENTS', false) : !!config.reuseComponents;
}

/** The element pool: removed custom elements by tag, kept up to `ELEMENT_POOL_DEFAULT_CAP` per tag. */
const elementPool = new Map();

/**
 * @param {string} tag
 * @return {?Element}
 */
function takeFromPool(tag) {
  const list = elementPool.get(tag);
  return (list && list.pop()) || null;
}

/**
 * @param {!Element} el
 * @return {boolean} Whether a view-model host is inside `el`. Such hosts
 *     dispose their renderings when they leave the document and render
 *     again from scratch when they come back, so the element is no use to
 *     the pool.
 */
function containsViewModelHost(el) {
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_ELEMENT);
  for (let n = walker.nextNode(); n; n = walker.nextNode()) if (/** @type {?} */ (n).isWebComponentWrapper) return true;
  return false;
}

/** @param {!Element} el */
function offerToPool(el) {
  const tag = /** @type {?} */ (el).is;
  if (!tag || containsViewModelHost(el)) return;
  let list = elementPool.get(tag);
  if (!list) elementPool.set(tag, list = []);
  if (list.length < Number(getConfig('ELEMENT_POOL_DEFAULT_CAP', 0))) list.push(el);
}

/** The jobs that remove hidden children, by child. */
const detachJobs = new WeakMap();

/**
 * Removes a child that was inserted before it replaced it, or that a
 * deferred detach hid, offering it to the pool; cancels its pending job.
 * @param {!Object} parent The container's Polymer DOM API.
 * @param {!Element} child
 * @param {boolean} reuse
 */
function removeChild(parent, child, reuse) {
  if (dom(child).parentNode === parent.node) {
    parent.removeChild(child);
    if (reuse) offerToPool(child);
  }
  const job = detachJobs.get(child);
  if (job) {
    detachJobs.delete(child);
    cancel(job);
  }
  child.hidden = false;
}

/**
 * Detaches children: hides them and removes them in a scheduler job when
 * `DEFERRED_DETACH` is on, else removes them at once.
 * @param {!Object} parent The container's Polymer DOM API.
 * @param {!Array<!Element>} children
 * @param {boolean} reuse
 */
function detach(parent, children, reuse) {
  if (getConfig('DEFERRED_DETACH', false)) {
    for (const child of children) {
      child.hidden = true;
      detachJobs.set(child, schedule(() => removeChild(parent, child, reuse), Priority.IMMEDIATE));
    }
  } else {
    for (let i = children.length - 1; i >= 0; i--) removeChild(parent, children[i], reuse);
  }
}

/** The success-ratio SLI that every stamper reports to: counters per outcome. */
const STAMPER_SLI = {success: 0, failure: 0};

/** @polymerBehavior */
export const YtRendererStamperBehavior = {
  /**
   * Merges the stamp configuration of the element and its behaviours, and
   * adds one wildcard observer per configured path to a legacy element's
   * declarations.
   * @param {!Object} info
   * @param {!Array<!Object>} behaviors
   * @param {boolean} signal
   */
  registerDeclarations_(info, behaviors, signal) {
    const config = info.configureRendererStamper ? info.configureRendererStamper() : null;
    const merged = {};
    for (const b of behaviors) Object.assign(merged, b.stampDom);
    info.stampDom = Object.assign(merged, info.stampDom, config);
    if (signal) return;
    for (const path of Object.keys(info.stampDom)) {
      info.observers.push(`${observerName(info.stampDom[path].id)}(${path}.*)`);
    }
    for (const binding of propertyBindingsOf(info.stampDom)) info.observers.push(`${propertyObserverName(binding)}(${binding.parentPropName})`);
  },

  beforeRegister() {
    this.stampDom = this.stampDom || {};
    if (this.useSignals) this.addStampDomObservers_();
  },

  created() {
    this.deferredBindingTasks_ = [];
    this.renderJobsMap_ = Object.create(null);
    this.hasDataPath_ = Object.create(null);
    this.addStampDomObserverFns_();
    this.telemetry_ = {create: 0, reuse: 0, error: 0};
    this.resetTelemetry_();
    this.successRatioSliParams_ = {sli: STAMPER_SLI, sliDimensions: () => ({})};
    this.componentsWithPropertyObservers_ = {};
  },

  /**
   * The mapping entries that ask for observers on a property of the parent:
   * the container id, the component, the property and the parent's path.
   * @return {!Array<{configId: string, component: string, propName: string, parentPropName: string}>}
   */
  getPropertyBindingsWithObservers_() {
    return propertyBindingsOf(/** @type {!Object<string, !StampConfig>} */ (this.stampDom));
  },

  /** Adds one wildcard observer per configured path to a signal-schema element. */
  addStampDomObservers_() {
    for (const path of Object.keys(this.stampDom)) {
      this.addReactiveSchema({type: 'observe', propertyKey: '', method: {methodName: observerName(this.stampDom[path].id),
        args: [{type: 'wildcard', path, value: undefined}]}});
    }
    for (const binding of this.getPropertyBindingsWithObservers_()) {
      this.addReactiveSchema({type: 'observe', propertyKey: '', method: {methodName: propertyObserverName(binding),
        args: [{type: 'path', path: binding.parentPropName, value: undefined}]}});
    }
  },

  /**
   * @param {!Node} node
   * @return {?}
   */
  polymerDom(node) {
    return dom(node);
  },

  addStampDomObserverFns_() {
    const config = /** @type {!Object<string, !StampConfig>} */ (this.stampDom);
    for (const path of Object.keys(config)) {
      const id = config[path].id;
      this[observerName(id)] = this.rendererStamperObserver_.bind(this, path, id);
      this.hasDataPath_[path] = false;
    }
    for (const binding of this.getPropertyBindingsWithObservers_()) {
      this[propertyObserverName(binding)] = (/** * */ value) => {
        const container = this.getStampContainer_(binding.configId);
        if (!container) return;
        for (const child of this.polymerDom(container).children) {
          if (child.localName !== binding.component) continue;
          const target = child.polymerController != null ? child.polymerController : child;
          target[binding.propName] = value;
        }
      };
    }
  },

  resetTelemetry_() {
    this.telemetry_.create = 0;
    this.telemetry_.reuse = 0;
    this.telemetry_.error = 0;
  },

  /**
   * @param {string} path
   * @param {string} id
   * @param {{path: string, value: *}} record
   */
  rendererStamperObserver_(path, id, record) {
    if (record.path === path) {
      if (record.value === undefined && !this.hasDataPath_[path]) return;
      this.hasDataPath_[path] = true;
    }
    this.rendererStamperApplyChangeRecord_(path, id, record);
  },

  /**
   * @param {string} path
   * @param {string} id
   * @param {{path: string, value: *}} record
   */
  rendererStamperApplyChangeRecord_(path, id, record) {
    const config = /** @type {!StampConfig} */ (this.stampDom[path]);
    let task;
    if (record.path === path) {
      const value = record.value;
      const items = value == null ? [] : Array.isArray(value) ? value : [value];
      task = () => this.stampDomArray_(items, id, config);
    } else if (record.path === `${path}.splices`) {
      const splices = /** @type {{indexSplices: !Array<!Object>}} */ (record.value).indexSplices;
      task = () => this.stampDomArraySplices_(this.get(path) || [], splices, id, config);
    } else {
      task = () => this.forwardRendererStamperChanges_(path, id, record);
    }
    if (config.initialRenderPriority !== undefined) {
      const pending = this.renderJobsMap_[id];
      if (pending === undefined) {
        this.renderJobsMap_[id] = schedule(() => {
          this.renderJobsMap_[id] = 0;
          task();
        }, Priority.DEFERRED);
        return;
      }
      if (pending) {
        if (record.path !== path) {
          schedule(task, Priority.DEFERRED);
          return;
        }
        cancel(pending);
        this.renderJobsMap_[id] = 0;
      }
    }
    task();
  },

  /**
   * Forwards a change below a stamped item to its element.
   * @param {string} path
   * @param {string} id
   * @param {{path: string, value: *}} record
   */
  forwardRendererStamperChanges_(path, id, record) {
    const rest = record.path.slice(path.length + 1).split('.');
    const container = this.getStampContainer_(id);
    if (!container) return;
    const children = this.polymerDom(container).children;
    const value = this.get(path);
    let child;
    if (Array.isArray(value)) {
      child = children[Number(rest.shift())];
      rest.shift();
    } else {
      child = children[0];
      rest.shift();
    }
    if (!child || !rest.length) return;
    const target = child.polymerController != null ? child.polymerController : child;
    if (target.notifyPath) target.notifyPath(`data.${rest.join('.')}`, record.value);
  },

  /**
   * Re-renders a container, keeping the children that are of the right tag
   * for the item at their position. Where the tag differs, the new element
   * is inserted before the old one and the old one is removed. Children
   * beyond the items are detached (deferred, with the page's setting).
   * @param {!Array<!Object>} items
   * @param {string} id
   * @param {!StampConfig} config
   */
  stampDomArray_(items, id, config) {
    const container = this.getStampContainer_(id);
    if (!container) return;
    const parent = this.polymerDom(container);
    const reuse = reusesComponents(config);
    const stable = config.stamperStableList === undefined ? !!getConfig('STAMPER_STABLE_LIST', false) : !!config.stamperStableList;
    let failures = 0;
    let stamped = 0;
    let i = 0;
    let index = 0;
    const live = Array.from(parent.children).filter(c => !detachJobs.has(c));
    if (stable) {
      while (index < live.length && i < items.length) {
        let child = live[index];
        const key = itemKey(config, items[i]);
        if (!key) {
          failures++;
          i++;
          continue;
        }
        stamped++;
        const tag = this.getComponentName_(config, key);
        if (/** @type {?} */ (child).is !== tag) {
          const created = this.createComponent_(tag, reuse);
          const next = this.polymerDom(child).nextElementSibling;
          if (next) parent.insertBefore(created, next);
          else parent.appendChild(created);
          removeChild(parent, child, reuse);
          child = created;
        } else {
          this.telemetry_.reuse++;
        }
        this.deferRenderStamperBinding_(child, config, items[i][key], key);
        index++;
        i++;
      }
    }
    detach(parent, live.slice(index), reuse);
    if (i < items.length) {
      const fragment = document.createDocumentFragment();
      for (; i < items.length; i++) {
        const key = itemKey(config, items[i]);
        if (!key) {
          failures++;
          continue;
        }
        stamped++;
        const created = this.createComponent_(this.getComponentName_(config, key), reuse);
        this.deferRenderStamperBinding_(created, config, items[i][key], key);
        fragment.appendChild(created);
      }
      parent.appendChild(fragment);
    }
    this.flushRenderStamperComponentBindings_();
    if (this.markDirty) this.markDirty();
    if (config.events) this.fire('yt-rendererstamper-finished', {container}, {bubbles: false});
    this.updateSuccessRatioSli_(failures === 0 && stamped > 0);
  },

  /**
   * Applies splices to a container: removed children are removed, and
   * added items take the removed children of their tag (when the
   * container reuses components) or get new elements.
   * @param {!Array<!Object>} items
   * @param {!Array<!Object>} splices
   * @param {string} id
   * @param {!StampConfig} config
   */
  stampDomArraySplices_(items, splices, id, config) {
    const container = this.getStampContainer_(id);
    if (!container) return;
    const parent = this.polymerDom(container);
    const reuse = reusesComponents(config);
    let failures = 0;
    let stamped = 0;
    for (const splice of splices) {
      const index = /** @type {number} */ (splice.index);
      const added = /** @type {number} */ (splice.addedCount);
      const removed = /** @type {!Array<*>} */ (splice.removed);
      const children = Array.from(parent.children).filter(c => !detachJobs.has(c));
      let at = children[index] || null;
      let reusing = reuse;
      const fragment = document.createDocumentFragment();
      let r = removed.length;
      let a = 0;
      for (; a < added; a++) {
        const item = items[index + a];
        const key = itemKey(config, item);
        if (!key) {
          failures++;
          continue;
        }
        stamped++;
        const tag = this.getComponentName_(config, key);
        let el;
        if (reusing && r > 0 && at && /** @type {?} */ (at).is === tag && !detachJobs.has(at)) {
          el = at;
          r--;
          this.telemetry_.reuse++;
          at = children[children.indexOf(at) + 1] || null;
        } else if (reusing && r > 0 && at && !detachJobs.has(at)) {
          el = this.createComponent_(tag, reuse);
          const next = children[children.indexOf(at) + 1] || null;
          parent.insertBefore(el, this.polymerDom(at).nextElementSibling);
          removeChild(parent, at, reuse);
          r--;
          at = next;
        } else {
          reusing = false;
          el = this.createComponent_(tag, reuse);
          fragment.appendChild(el);
        }
        this.deferRenderStamperBinding_(el, config, item[key], key);
      }
      for (; r > 0 && at; r--) {
        const next = children[children.indexOf(at) + 1] || null;
        removeChild(parent, at, reuse);
        at = next;
      }
      parent.insertBefore(fragment, at);
    }
    this.flushRenderStamperComponentBindings_();
    if (this.markDirty) this.markDirty();
    if (config.events) this.fire('yt-rendererstamper-finished', {container}, {bubbles: false});
    this.updateSuccessRatioSli_(failures === 0 && stamped > 0);
  },

  /**
   * @param {string} id
   * @return {?Element}
   */
  getStampContainer_(id) {
    const byId = this.$ && this.$[id];
    if (byId) return byId;
    return hostDom(this.hostElement).querySelector(`#${id}`);
  },

  /**
   * @param {!StampConfig} config
   * @param {string} key
   * @return {string}
   */
  getComponentName_(config, key) {
    const mapped = config.mapping[key];
    return typeof mapped === 'string' ? mapped : mapped.component;
  },

  /**
   * Creates the element for a tag: a pooled one when the container reuses
   * components, with its styles cleared (a restyle of its subtree) unless it
   * is a view-model host.
   * @param {string} tag
   * @param {boolean=} reuse
   * @return {!Element}
   */
  createComponent_(tag, reuse) {
    try {
      let el = reuse ? takeFromPool(tag) : null;
      if (!el) el = document.createElement(tag);
      if (reuse && !/** @type {?} */ (el).isWebComponentWrapper) styleSubtree(el);
      this.telemetry_.create++;
      return el;
    } catch (e) {
      this.telemetry_.error++;
      return document.createElement('span');
    }
  },

  /**
   * @param {!Element} component
   * @param {!StampConfig} config
   * @param {*} data
   * @param {string=} key
   */
  deferRenderStamperBinding_(component, config, data, key) {
    this.deferredBindingTasks_.push({component, config, data, key});
  },

  flushRenderStamperComponentBindings_() {
    const tasks = this.deferredBindingTasks_;
    this.deferredBindingTasks_ = [];
    for (const {component, config, data, key} of tasks) {
      const status = component.loggingStatus;
      if (status) status.isRendererStamper = true;
      if (config.attributes) {
        for (const name of Object.keys(config.attributes)) {
          const value = config.attributes[name];
          if (value == null) component.removeAttribute(name);
          else component.setAttribute(name, value);
        }
      }
      const target = component.polymerController != null ? component.polymerController : component;
      if (config.properties) {
        for (const name of Object.keys(config.properties)) target[name] = this.get(config.properties[name]);
      }
      const mapped = key && config.mapping ? config.mapping[key] : null;
      if (mapped && typeof mapped !== 'string') {
        for (const name in mapped.params) target[name] = mapped.params[name];
        for (const name in mapped.properties) target[name] = this.get(mapped.properties[name]);
      }
      /** @type {?} */ (component).data = data;
      if (status) status.isRendererStamper = false;
    }
  },

  /** @param {boolean} ok */
  updateSuccessRatioSli_(ok) {
    const params = this.successRatioSliParams_;
    if (!params) return;
    if (ok) params.sli.success++;
    else params.sli.failure++;
  },
};
