/**
 * @fileoverview Reactive schemas of signal-schema controllers: observers,
 * computed properties, notify events and reflected attributes, each one
 * effect on the controller's signal proxy.
 *
 * Observer arguments are literals, root paths (the value signal), sub-paths
 * (writes to the path or an ancestor), wildcards (the newest change record)
 * or splices. An observer runs its method once any argument's root has been
 * defined, and then on every run; a single path argument also gets the
 * previous value.
 */
import {camelToDash} from '../case.js';
import {toPath} from './proxy.js';

/**
 * @typedef {{type: string, path: string, value: *}}
 */
export let SchemaArg;

/**
 * @typedef {{methodName: string, args: !Array<!SchemaArg>}}
 */
export let SchemaMethod;

/**
 * Parses one argument of an observer or computed expression.
 * @param {string} text
 * @return {!SchemaArg}
 */
export function parseArg(text) {
  const arg = text.trim();
  const first = arg[0];
  if (first === '"' || first === "'") return {type: 'literal', path: '', value: arg.slice(1, -1).replace(/\\(.)/g, '$1')};
  if (first === '-' || (first >= '0' && first <= '9')) return {type: 'literal', path: '', value: Number(arg)};
  if (arg.endsWith('.*')) return {type: 'wildcard', path: arg.slice(0, -2), value: undefined};
  if (arg.endsWith('.splices')) return {type: 'splices', path: arg.slice(0, -8), value: undefined};
  return {type: 'path', path: arg, value: undefined};
}

/**
 * Parses `method(arg, ...)`.
 * @param {string} expression
 * @return {!SchemaMethod}
 */
export function parseMethod(expression) {
  const m = /^\s*([\w$]+)\s*\(([\s\S]*)\)\s*$/.exec(expression);
  if (!m) throw new Error(`Invalid method expression: ${expression}`);
  const args = [];
  let depth = 0;
  let quote = '';
  let start = 0;
  const body = m[2];
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = '';
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === '(') {
      depth++;
    } else if (c === ')') {
      depth--;
    } else if (c === ',' && !depth) {
      args.push(parseArg(body.slice(start, i)));
      start = i + 1;
    }
  }
  if (body.trim()) args.push(parseArg(body.slice(start)));
  return {methodName: m[1], args};
}

/**
 * A getter for one argument: `{value, defined}`.
 * @param {!Object} proxy
 * @param {!SchemaArg} arg
 * @return {function(): {value: *, defined: boolean}}
 */
export function argumentGetter(proxy, arg) {
  if (arg.type === 'literal') {
    const result = {value: arg.value, defined: true};
    return () => result;
  }
  const parts = toPath(arg.path);
  const store = proxy.resolve(parts[0]);
  const rest = parts.slice(1);
  if (arg.type === 'wildcard') {
    const reader = store.getChangeRecordSignal(rest);
    return () => ({value: reader(), defined: store.wasDefined});
  }
  if (arg.type === 'splices') {
    const reader = store.getSplicesSignal(rest);
    return () => ({value: reader(), defined: store.wasDefined});
  }
  if (!rest.length) {
    return () => {
      const value = store.getWithPath([]);
      return {value, defined: store.wasDefined || value !== undefined};
    };
  }
  const reader = store.getPathMutationSignal(rest);
  return () => {
    reader();
    return {value: store.peek(rest), defined: store.wasDefined};
  };
}

/**
 * Creates an observer: one effect that reads every argument and calls the
 * method untracked.
 * @param {!Object} proxy The controller's signal proxy.
 * @param {!Object} target The object whose method is called.
 * @param {!SchemaMethod} method
 * @param {function(!Array<*>)=} onResult Receives the method's result.
 * @return {{run: function(), destroy: function()}}
 */
export function createObserver(proxy, target, method, onResult) {
  const getters = method.args.map(arg => argumentGetter(proxy, arg));
  const single = method.args.length === 1 && method.args[0].type === 'path';
  let called = method.args.length === 0;
  let first = true;
  let previous;
  return proxy.effect(() => {
    const values = [];
    for (const get of getters) {
      const {value, defined} = get();
      values.push(value);
      if (defined) called = true;
    }
    if (single) {
      values.push(first ? values[0] : previous);
      previous = values[0];
      first = false;
    }
    if (!called) return;
    proxy.runUntracked(() => {
      const fn = target[method.methodName];
      if (typeof fn !== 'function') return;
      const result = fn.apply(target, single ? values : values.slice(0, method.args.length));
      if (onResult) onResult(result);
    });
  }, method.methodName);
}

/**
 * A computed property: a store seeded with the declared value, written by
 * an observer of the method's arguments.
 * @param {!Object} proxy
 * @param {!Object} target
 * @param {string} key
 * @param {!SchemaMethod} method
 * @param {*} value
 */
export function createComputed(proxy, target, key, method, value) {
  const store = proxy.resolve(key);
  if (value !== undefined) store.setWithPath([], value);
  const call = {methodName: method.methodName, args: method.args};
  createObserver(proxy, target, call, result => store.setWithPath([], result));
}

/**
 * Fires `<key>-changed` on the host for every change of `key`, once the
 * value is defined.
 * @param {!Object} proxy
 * @param {!Element} host
 * @param {string} key
 */
export function createNotify(proxy, host, key) {
  const store = proxy.resolve(key);
  const reader = store.getChangeRecordSignal([]);
  const eventName = `${camelToDash(key)}-changed`;
  proxy.effect(() => {
    const record = reader();
    if (!store.wasDefined) return;
    proxy.runUntracked(() => {
      const detail = {value: record.value, queueProperty: true};
      if (record.path !== key) detail.path = record.path;
      host.dispatchEvent(new CustomEvent(eventName, {detail, bubbles: false, composed: false}));
    });
  }, eventName);
}

/**
 * Serializes a value for a reflected attribute: objects become `""`.
 * @param {*} value
 * @return {string|undefined}
 */
function reflectedValue(value) {
  if (value == null || value === false) return undefined;
  if (value === true || typeof value === 'object' || typeof value === 'function') return '';
  return String(value);
}

/**
 * Reflects `key` to the host attribute.
 * @param {!Object} proxy
 * @param {!Object} ctrl
 * @param {string} key
 */
export function createReflect(proxy, ctrl, key) {
  const store = proxy.resolve(key);
  const attr = camelToDash(key);
  proxy.effect(() => {
    const value = store.getWithPath([]);
    proxy.runUntracked(() => {
      const host = ctrl.hostElement;
      const str = reflectedValue(value);
      ctrl.reflecting = true;
      try {
        if (str === undefined) host.removeAttribute(attr);
        else host.setAttribute(attr, str);
      } finally {
        ctrl.reflecting = false;
      }
    });
  }, attr);
}
