/**
 * @fileoverview Behaviours of renderer containers, shaped like YouTube's:
 * the task emitter, next-continuation requests, the continuation handler
 * that splices continuation items into the data, boolean template helpers,
 * prescan visibility, and guide-state awareness.
 */
import {camelToDash} from '../framework/case.js';
import {flag} from '../framework/flags.js';
import {rootInjector} from '../framework/injector.js';
import {ActionHandlerBehavior} from './item-behaviors.js';
import {innertubeFetch} from './network.js';
import {Priority, cancel, schedule} from './scheduler.js';

/** Containers whose lazy lists render through the task manager. */
const TASK_MANAGER_TAGS = new Set(['ytl-section-list-renderer', 'ytl-horizontal-list-renderer', 'ytl-item-section-renderer',
  'ytl-watch-next-secondary-results-renderer', 'ytl-video-primary-info-renderer']);

/** The default task manager, which runs jobs on the app's scheduler. */
const defaultTaskManager = {
  /**
   * @param {function()} fn
   * @param {number=} delay
   * @return {number}
   */
  addJob(fn, delay) {
    return schedule(fn, Priority.RENDER);
  },

  /**
   * @param {function()} fn
   * @param {number=} delay
   * @return {number}
   */
  addLowPriorityJob(fn, delay) {
    return schedule(fn, Priority.IDLE);
  },

  /** @param {number} id */
  cancelJob(id) {
    cancel(id);
  },
};

/** The default network manager of continuation requests. */
export const defaultNetworkManager = {
  /**
   * @param {string} path
   * @return {!Promise<{response: !Object}>}
   */
  fetchData(path) {
    return innertubeFetch('next-continuation', path, {}).then(text => ({response: JSON.parse(text)}));
  },

  /**
   * @param {string} path
   * @param {!Object} payload
   * @return {!Promise<{response: !Object}>}
   */
  postData(path, payload) {
    return innertubeFetch('next-continuation', path, payload).then(text => ({response: JSON.parse(text)}));
  },
};

/** @polymerBehavior */
export const TaskEmitterBehavior = {
  created() {
    this.cachedProviderNode_ = null;
  },

  detached() {
    this.cachedProviderNode_ = null;
  },

  /** @return {!Object} */
  getTaskManager() {
    const context = this.getContext_();
    return context ? context.getTaskManager() : defaultTaskManager;
  },

  /**
   * The context of the nearest provider, if elements that use the task
   * manager have one.
   * @return {?Object|undefined}
   */
  getContext_() {
    if (!this.shouldUseTaskManager()) return undefined;
    if (!this.cachedProviderNode_) {
      const event = this.fire('yt-get-context-provider', {});
      if (event.detail && event.detail.contextProvider) this.cachedProviderNode_ = event.detail.contextProvider;
      else if (this.hostElement.parentElement) this.cachedProviderNode_ = this;
    }
    const provider = this.cachedProviderNode_;
    return provider && provider.getProvidedContext && provider.getProvidedContext() ? provider.getProvidedContext() : undefined;
  },

  /** @return {boolean} */
  shouldUseTaskManager() {
    return TASK_MANAGER_TAGS.has(this.hostElement.localName);
  },

  /** @return {?Object|undefined} */
  getNetworkManager() {
    const context = this.getContext_();
    return context ? context.getNetworkManager() : undefined;
  },
};

/** The `yt-navigate-start` listener of each element that waits for a continuation. */
const navigateListeners = new WeakMap();

/**
 * @param {!Object} self
 * @return {function()}
 */
function navigateListener(self) {
  let listener = navigateListeners.get(self);
  if (!listener) {
    listener = () => self.onYtNavigateStart_();
    navigateListeners.set(self, listener);
  }
  return listener;
}

/** @polymerBehavior */
export const NextContinuationBehavior = {
  listeners: {
    'yt-load-next-continuation': 'onLoadNextContinuation_',
  },

  nextContinuation: undefined,
  pendingContinuationRequest_: undefined,
  listeningForNavigate_: false,

  created() {},

  detached() {
    this.stopListeningForNavigate_();
  },

  /** @return {boolean} */
  canUseContextualNetworkManager_() {
    return this.shouldUseTaskManager() && !!this.getNetworkManager();
  },

  startListeningForNavigate_() {
    if (this.canUseContextualNetworkManager_() || this.listeningForNavigate_) return;
    document.addEventListener('yt-navigate-start', navigateListener(this));
    this.listeningForNavigate_ = true;
  },

  stopListeningForNavigate_() {
    if (this.canUseContextualNetworkManager_()) return;
    document.removeEventListener('yt-navigate-start', navigateListener(this));
    this.listeningForNavigate_ = false;
  },

  /**
   * @param {!CustomEvent} e
   * @param {function(string): string} urlFn
   */
  onLoadNextContinuation_(e, urlFn) {
    e.stopPropagation();
    if (this.nextContinuation.requestPath) {
      this.makeNextContinuationRequest_(this.nextContinuation.requestPath, urlFn, {});
    } else {
      this.fire('yt-retrieve-location', {locationRetrieved: path => this.makeNextContinuationRequest_(path, urlFn, {})});
    }
  },

  /**
   * @param {string} path
   * @param {function(string): string} urlFn
   * @param {!Object} payload
   */
  makeNextContinuationRequest_(path, urlFn, payload) {
    const url = urlFn(path);
    const manager = (this.canUseContextualNetworkManager_() ? this.getNetworkManager() : undefined) || defaultNetworkManager;
    const request = this.nextContinuation.usePost ? manager.postData(url, payload) : manager.fetchData(url);
    request.then(result => this.updateNextContinuationData_(url, result));
    this.pendingContinuationRequest_ = request;
    this.startListeningForNavigate_();
  },

  /**
   * @param {string} url
   * @param {?{response: ?Object}} result
   */
  updateNextContinuationData_(url, result) {
    this.pendingContinuationRequest_ = undefined;
    if (!result) return;
    const config = this.nextContinuation || {};
    const contents = result.response && result.response.continuationContents && result.response.continuationContents[config.continuationType];
    if (!contents) {
      this.set(config.continuationsArray || 'data.continuations', []);
      return;
    }
    const header = contents[config.responseHeaderKey || 'header'];
    if (header) this.set(config.header || 'data.header', header);
    const path = config.contentsArray || 'data.contents';
    const items = this.getContents_(contents, config.responseContentsKey || 'contents') || [];
    if (this.pathExists_(path)) this.push(path, ...items);
    else this.set(path, items);
    this.fire('yt-next-continuation-data-updated', {continuationData: result, page: this, contentsArray: path});
    this.set(config.continuationsArray || 'data.continuations', contents[config.responseContinuationsKey || 'continuations'] || []);
  },

  /**
   * @param {!Object} contents
   * @param {string} key
   * @return {*}
   */
  getContents_(contents, key) {
    let value = contents;
    for (const part of key.split('.')) value = value == null ? undefined : value[part];
    return value;
  },

  /**
   * @param {string} path
   * @return {boolean}
   */
  pathExists_(path) {
    let value = /** @type {?} */ (this);
    for (const part of path.split('.')) {
      value = value[part];
      if (value === undefined) return false;
    }
    return true;
  },

  onYtNavigateStart_() {
    this.pendingContinuationRequest_ = undefined;
    this.stopListeningForNavigate_();
  },
};

const ACTION_SUFFIXES = ['action', 'command', 'endpoint'];

/**
 * The action name of a command: its first key that ends in "Action",
 * "Command" or "Endpoint", as `yt-` plus the key in dash case.
 * @param {!Object} command
 * @return {?string}
 */
export function commandActionName(command) {
  let key = null;
  for (const suffix of ACTION_SUFFIXES) {
    key = Object.keys(command).find(k => k.toLowerCase().endsWith(suffix)) || null;
    if (key) break;
  }
  if (!key) return null;
  let name = `yt-${camelToDash(key)}`;
  const signal = command.signalAction;
  if (signal && signal.signal) name += `-${signal.signal.toLowerCase().replace(/_/g, '-')}`;
  return name;
}

/**
 * Splices continuation items into the data at the paths of
 * `continuationPathMap`, for commands whose `targetId` is the data's.
 * @polymerBehavior
 */
export const ContinuationHandlerBehavior = {
  properties: {
    data: Object,
    continuationIsReloading: {type: Boolean, value: false, reflectToAttribute: true},
    reloadUiContent: Object,
  },

  observers: ['observeData(data)'],

  initFields_() {
    this.continuationActionMap = {
      'yt-append-continuation-items-action': 'handleAppendContinuationItemsAction',
      'yt-reload-continuation-items-command': 'handleReloadContinuationItemsCommand',
      'yt-restore-cached-continuable-data-command': 'handleRestoreCachedContinuableDataCommand',
      'yt-show-reload-ui-command': 'handleShowReloadUiCommand',
    };
  },

  /** @return {!Object<string, string>} */
  configureContinuationPathMap() {
    return {};
  },

  beforeRegister() {
    this.continuationPathMap = this.configureContinuationPathMap();
  },

  attached() {
    this.registerActionMap(this.continuationActionMap);
  },

  detached() {
    this.unregisterActionMap(this.continuationActionMap);
  },

  observeData() {
    if (!this.data) return;
    this.continuationIsReloading = false;
    this.reloadUiContent = undefined;
  },

  /** @param {function(!Object): boolean} matcher */
  setReloadContinuationItemsCommandMatcher(matcher) {
    this.reloadContinuationItemsCommandMatcher = matcher;
  },

  /**
   * Replaces the first continuation item of the list with the command's
   * items, or appends them if the list has none.
   * @param {!Object} command
   */
  handleAppendContinuationItemsAction(command) {
    const action = command.appendContinuationItemsAction;
    if (!this.data || !this.data.targetId || !action || !this.continuationPathMap || action.targetId !== this.data.targetId) return;
    const name = commandActionName(command);
    const path = name && this.continuationPathMap[name];
    if (!path) return;
    const list = /** @type {?Array<!Object>} */ (this.get(path, this.data));
    if (!list) return;
    let index = 0;
    while (index < list.length && !list[index].continuationItemRenderer) index++;
    const fullPath = `data.${path}`;
    const items = action.continuationItems;
    if (!items) this.splice(fullPath, index, 1);
    else if (index === list.length) this.push(fullPath, ...items);
    else this.splice(fullPath, index, 1, ...items);
    if (flag('web_enable_voting_animation') || flag('enable_music_web_cairo_voting_animation')) {
      this.fire('yt-append-continuation-items-action-finished');
    }
    this.fire('yt-next-continuation-data-updated', null, {bubbles: false});
  },

  /** @param {!Object} command */
  handleReloadContinuationItemsCommand(command) {
    const reload = command.reloadContinuationItemsCommand;
    if (!this.data || !reload || !this.data.targetId || !this.continuationPathMap || reload.targetId !== this.data.targetId) return;
    const slot = reload.slot ? reload.slot.replace('RELOAD_CONTINUATION_SLOT_', '') : undefined;
    const key = `${commandActionName(command)}-${slot && slot.toLowerCase()}`;
    const path = this.continuationPathMap[key];
    if (!path || !slot) return;
    if (this.reloadContinuationItemsCommandMatcher && !this.reloadContinuationItemsCommandMatcher(reload)) return;
    const items = reload.continuationItems;
    if (reload.replaceWithFirstItem) this.set(`data.${path}`, items && items.length ? items[0] : {});
    else this.set(`data.${path}`, items || []);
    this.markLoadingAsDone();
  },

  /** @param {!Object} command */
  handleRestoreCachedContinuableDataCommand(command) {
    const restore = command.restoreCachedContinuableDataCommand;
    if (this.data && this.data.targetId && restore && restore.targetId === this.data.targetId) this.markLoadingAsDone();
  },

  markLoadingAsDone() {
    this.continuationIsReloading = false;
    this.reloadUiContent = undefined;
    this.fire('yt-reload-continuation-finish', null, {bubbles: false});
  },

  /** @param {!Object} command */
  handleShowReloadUiCommand(command) {
    const show = command.showReloadUiCommand;
    if (!this.data || !this.data.targetId || !show || !show.targetId || show.targetId !== this.data.targetId) return;
    this.continuationIsReloading = true;
    if (show.content) this.reloadUiContent = show.content;
  },
};

/** @polymerBehavior */
export const BooleanLogicBehavior = {
  created() {},

  /**
   * @param {*} condition
   * @param {*} value
   * @param {*} otherwise
   * @return {*}
   */
  bindIf(condition, value, otherwise) {
    return condition ? value : otherwise;
  },

  /**
   * @param {*} value
   * @param {*} fallback
   * @return {*}
   */
  bindIfDefined(value, fallback) {
    return value !== undefined ? value : fallback;
  },

  /**
   * @param {*} value
   * @return {string}
   */
  booleanString(value) {
    return (!!value).toString();
  },

  /**
   * @param {...*} values
   * @return {boolean}
   */
  equals(...values) {
    for (let i = 1; i < values.length; i++) if (values[0] != values[i]) return false;
    return true;
  },

  /**
   * @param {number} a
   * @param {number} b
   * @return {boolean}
   */
  isGreaterThan(a, b) {
    return a > b;
  },

  /**
   * @param {number} a
   * @param {number} b
   * @return {boolean}
   */
  isLessThan(a, b) {
    return a < b;
  },

  /**
   * @param {...*} values
   * @return {boolean}
   */
  logicalAND(...values) {
    return values.every(Boolean);
  },

  /**
   * @param {...*} values
   * @return {boolean}
   */
  logicalOR(...values) {
    return values.some(Boolean);
  },

  /**
   * @param {*} value
   * @return {boolean}
   */
  toBool(value) {
    return !!value;
  },
};

/**
 * Prescan visibility: renderers override `onShow`.
 * @polymerBehavior
 */
export const VisibilityBehavior = {
  properties: {
    disablePrescanVisibility: Boolean,
    prescanHeight: {type: Number, reflectToAttribute: true},
  },

  onShow() {},
};

/** Window widths at which the guide is persistent, or the mini guide shows. */
const PERSISTENT_GUIDE_MIN_WIDTH = 1312;
const MINI_GUIDE_MIN_WIDTH = 792;

/** The guide state that guide-aware components read through injection. */
export class GuideService {
  constructor() {
    /** @type {?Object} */
    this.activeEndpoint = null;
  }

  /** @return {boolean} */
  getGuidePersistentAndVisible() {
    return window.innerWidth >= PERSISTENT_GUIDE_MIN_WIDTH;
  }

  /** @return {boolean} */
  getMiniGuideVisible() {
    return !this.getGuidePersistentAndVisible() && window.innerWidth >= MINI_GUIDE_MIN_WIDTH;
  }

  /** @return {boolean} */
  getGuideOpened() {
    return this.getGuidePersistentAndVisible();
  }

  /** @return {?Object} */
  getActiveEndpoint() {
    return this.activeEndpoint;
  }
}
/** @type {?} */ (GuideService)['ɵprov'] = {providedIn: 'root', factory: () => new GuideService()};

/**
 * Mirrors the guide state into four properties, from the guide service on
 * attach and from the guide actions after (kevlar's
 * `YtdGuideStateAwareBehavior`). Used with the action handler behaviour, as
 * `GuideStateAwareBehavior`.
 * @polymerBehavior
 */
const GuideStateAwareBehaviorImpl = {
  properties: {
    guidePersistentAndVisible: {type: Boolean, reflectToAttribute: true},
    miniGuideVisible: {type: Boolean, reflectToAttribute: true},
    activeEndpoint: Object,
    guideOpened: Boolean,
  },
  observers: ['onActiveEndpointChange(activeEndpoint)'],

  created() {
    this.guideStateActionMap = {
      'ytd-update-guide-state-action': 'handleGuideStateAction',
      'ytd-update-mini-guide-state-action': 'handleMiniGuideStateAction',
      'ytd-update-guide-opened-action': 'handleGuideOpenedAction',
      'ytd-update-active-endpoint-action': 'handleActiveEndpointAction',
    };
  },

  onActiveEndpointChange() {
    this.hostElement.dispatchEvent(new CustomEvent('active-endpoint-changed', {detail: {value: this.activeEndpoint, queueProperty: true}}));
  },

  attached() {
    this.registerActionMap(this.guideStateActionMap);
    const guide = /** @type {?GuideService} */ (rootInjector.resolve(GuideService));
    if (!guide) return;
    this.guidePersistentAndVisible = guide.getGuidePersistentAndVisible();
    this.activeEndpoint = guide.getActiveEndpoint();
    this.guideOpened = guide.getGuideOpened();
    this.miniGuideVisible = guide.getMiniGuideVisible();
  },

  detached() {
    this.unregisterActionMap(this.guideStateActionMap);
  },

  /** @param {boolean} value */
  handleGuideStateAction(value) {
    this.guidePersistentAndVisible = value;
  },

  /** @param {boolean} value */
  handleMiniGuideStateAction(value) {
    this.miniGuideVisible = value;
  },

  /** @param {boolean} value */
  handleGuideOpenedAction(value) {
    this.guideOpened = value;
  },

  /** @param {?Object} value */
  handleActiveEndpointAction(value) {
    this.activeEndpoint = value;
  },
};

/** @polymerBehavior */
export const GuideStateAwareBehavior = [GuideStateAwareBehaviorImpl, ActionHandlerBehavior];
