/**
 * @fileoverview Effects, signals and computeds of the view-model runtime,
 * on Angular's reactive primitives. An effect node is created with
 * `Object.create` from a prototype, attached to the current owner, and
 * carries the component stack it was created in. A render effect runs at
 * creation; its re-runs go to the render queue, which every signal write
 * flushes before the write returns, and the outermost render flushes when
 * it ends. After-render effects go to a second queue, flushed in a
 * microtask after each flush outside a render.
 */
import {REACTIVE_NODE, consumerAfterComputation, consumerBeforeComputation, consumerDestroy, consumerPollProducersForChange,
  SIGNAL, createComputed, createLinkedSignal, createSignal, linkedSignalSetFn, setActiveConsumer, setPostSignalSetFn, untracked} from '../signals.js';
import {noteBreakdown, vmCounters} from './counters.js';
import {Frame, appendDisposable, disposeChildren, getFrame, getOwner, onCleanup, setFrame, setOwner} from './owner.js';

export {Frame, getFrame, setFrame};

/**
 * @param {?Frame} frame
 * @return {string}
 */
function describeStack(frame) {
  const names = [];
  for (let f = frame; f; f = f.parent) names.push(f.name);
  return names.reverse().join(' > ');
}

/**
 * Runs `fn` and reports an error with the component stack instead of
 * letting it escape.
 * @param {function()} fn
 * @param {?Frame} frame
 * @param {string} debugName
 */
export function runReporting(fn, frame, debugName) {
  try {
    fn();
  } catch (e) {
    console.error(`${debugName} failed in ${describeStack(frame)}`, e);
  }
}

/**
 * An effect queue: a reused array with a length counter.
 * @typedef {{queue: !Array<?Object>, length: number, isFlushing: boolean}}
 */
let Queue;

/** @return {!Queue} */
function createQueue() {
  return {queue: [], length: 0, isFlushing: false};
}

const renderQueue = createQueue();
const afterQueue = createQueue();
/** On-init callbacks, flushed before the after-render effects. */
const initQueue = createQueue();

/** Nesting depth of render roots and control-flow renders. */
let renderDepth = 0;

const EFFECT_NODE = Object.assign({}, REACTIVE_NODE, {
  consumerIsAlwaysLive: true,
  consumerAllowSignalWrites: true,
  kind: 'effect',
  dirty: true,
  isEffect: true,
  isAfterRender: false,
  isDisposed: false,
  fn: null,
  debugName: '',
  parent: null,
  componentStack: null,
  childDisposable: null,
  tailDisposable: null,
  nextDisposable: null,
  /** @param {!Object} node */
  consumerMarkedDirty(node) {
    schedule(node);
  },
  /** @this {!Object} */
  dispose() {
    if (this.isDisposed) return;
    this.isDisposed = true;
    consumerDestroy(this);
    disposeChildren(this);
    this.fn = null;
  },
  /** @this {!Object} */
  destroy() {
    this.dispose();
  },
  /** @this {!Object} */
  run() {
    runEffect(this);
  },
});

/**
 * Schedules an effect. A render effect's first run happens at once; only
 * re-runs are queued.
 * @param {!Object} node
 */
function schedule(node) {
  if (node.isDisposed) return;
  if (node.isAfterRender) {
    afterQueue.queue[afterQueue.length++] = node;
  } else if (node.version === 0) {
    runEffect(node);
  } else {
    renderQueue.queue[renderQueue.length++] = node;
  }
}

/**
 * Runs an effect if a producer it read changed, or on its first run. The
 * effect is the current owner while it runs; what it created in its last
 * run is disposed first.
 * @param {!Object} node
 */
function runEffect(node) {
  if (node.isDisposed) return;
  node.dirty = false;
  if (node.version > 0 && !consumerPollProducersForChange(node)) return;
  node.version++;
  const prevOwner = setOwner(node);
  const prevFrame = setFrame(node.componentStack);
  const prevConsumer = consumerBeforeComputation(node);
  try {
    runReporting(() => {
      if (node.childDisposable) disposeChildren(node);
      node.fn();
    }, node.componentStack, node.debugName);
  } finally {
    consumerAfterComputation(node, prevConsumer);
    setFrame(prevFrame);
    setOwner(prevOwner);
  }
}

/**
 * Runs the dirty effects of a queue, each after its dirty effect ancestors,
 * outermost first. Effects queued during the flush run in the same pass.
 * @param {!Queue} q
 */
function flushQueue(q) {
  const wasFlushing = q.isFlushing;
  q.isFlushing = true;
  try {
    for (let i = 0; i < q.length;) {
      const node = q.queue[i];
      q.queue[i] = null;
      i++;
      if (!node || !node.dirty) continue;
      const chain = [node];
      for (let p = node.parent; p; p = p.parent) {
        if (p.isEffect && p.dirty) chain.push(p);
      }
      while (chain.length) chain.pop().run();
    }
    q.length = 0;
  } finally {
    q.isFlushing = wasFlushing;
  }
}

/** @param {!Queue} q */
function clearQueue(q) {
  for (let i = 0; i < q.length; i++) q.queue[i] = null;
  q.length = 0;
}

/**
 * Runs the queued render effects. The page turns on
 * `flushRenderEffectsDuringRender`, so a flush takes the queued effects
 * and starts a new queue; a flush inside another one runs the effects
 * queued since, before the outer flush continues.
 */
export function flushRenderEffects() {
  if (!renderQueue.length) return;
  const batch = {queue: renderQueue.queue, length: renderQueue.length, isFlushing: false};
  renderQueue.queue = [];
  renderQueue.length = 0;
  flushQueue(batch);
}

/** Runs the queued on-init callbacks in order. */
function flushInitCallbacks() {
  for (let i = 0; i < initQueue.length;) {
    const job = initQueue.queue[i];
    initQueue.queue[i] = null;
    i++;
    if (job) job.run();
  }
  initQueue.length = 0;
}

function flushAfterRenderEffects() {
  flushInitCallbacks();
  if (afterQueue.length && !afterQueue.isFlushing) flushQueue(afterQueue);
}

/**
 * After a signal write: flushes the render effects. Outside a render it
 * then flushes the after-render effects in a microtask.
 */
function flushAll() {
  flushRenderEffects();
  if (renderDepth === 0) Promise.resolve().then(flushAfterRenderEffects);
}

/** Enters a render root or a control-flow render. */
export function beginRender() {
  renderDepth++;
}

/**
 * Leaves a render root or a control-flow render. The outermost one flushes.
 * A failed render drops all queued effects.
 * @param {boolean} failed
 */
export function endRender(failed) {
  renderDepth--;
  if (failed) {
    clearQueue(renderQueue);
    clearQueue(initQueue);
    clearQueue(afterQueue);
  } else if (renderDepth === 0) {
    flushAll();
  }
}

/**
 * Runs `fn` as a render, then ends it as `endRender` does.
 * @template T
 * @param {function(): T} fn
 * @return {T}
 */
export function asRender(fn) {
  beginRender();
  let result;
  try {
    result = fn();
  } catch (e) {
    endRender(true);
    throw e;
  }
  endRender(false);
  return result;
}

setPostSignalSetFn(flushAll);

/**
 * @param {function()} fn
 * @param {string} debugName
 * @param {boolean} afterRender
 * @return {!Object}
 */
function createEffectNode(fn, debugName, afterRender) {
  noteBreakdown(`#${debugName}`, getFrame());
  const node = Object.create(EFFECT_NODE);
  node.fn = fn;
  node.debugName = debugName;
  node.isAfterRender = afterRender;
  node.componentStack = getFrame();
  const owner = getOwner();
  node.parent = owner;
  if (owner) appendDisposable(owner, node);
  return node;
}

/**
 * A render effect. Its first run happens at once.
 * @param {function()} fn
 * @param {string=} debugName
 * @return {!Object}
 */
export function renderEffect(fn, debugName = 'o1') {
  vmCounters.effects++;
  noteBreakdown('effects', getFrame());
  const node = createEffectNode(fn, debugName, false);
  schedule(node);
  return node;
}

/**
 * An effect that runs after rendering, in a microtask.
 * @param {function()} fn
 * @param {string=} debugName
 * @return {!Object}
 */
export function afterRenderEffect(fn, debugName = 'Xn') {
  vmCounters.afterEffects++;
  noteBreakdown('effects', getFrame());
  const node = createEffectNode(fn, debugName, true);
  schedule(node);
  return node;
}

/**
 * Queues `fn` to run once after the current render, before the after-render
 * effects, with the current owner and component stack (`_.WA`). It creates
 * no effect node. When `fn` returns a function, that becomes a cleanup of
 * the owner. Nothing runs when the owner was disposed first.
 * @param {function(): (function()|undefined|void)} fn
 */
export function onInit(fn) {
  const owner = getOwner();
  const frame = getFrame();
  initQueue.queue[initQueue.length++] = {run: () => {
    if (!owner || owner.isDisposed) return;
    const prevOwner = setOwner(owner);
    const prevFrame = setFrame(frame);
    try {
      runReporting(() => {
        const cleanup = fn();
        if (typeof cleanup === 'function') onCleanup(cleanup);
      }, frame, 'onInit');
    } finally {
      setFrame(prevFrame);
      setOwner(prevOwner);
    }
  }};
}

/**
 * Queues an untracked `fn` as `onInit` does (`_.UK`).
 * @param {function()} fn
 */
export function onInitUntracked(fn) {
  onInit(() => runUntracked(fn));
}

/**
 * An after-render effect that reads `source` and passes its value to an
 * untracked `fn` (`_.z_`).
 * @template T
 * @param {function(): T} source
 * @param {function(T)} fn
 */
export function watchAfterRender(source, fn) {
  afterRenderEffect(() => {
    const v = source();
    runUntracked(() => void fn(v));
  }, 'cKR9sf');
}

/**
 * An effect of a PolySi signal store or template. It runs at once, then
 * again from the render queue whenever the signals it read change.
 * @param {function()} fn
 * @param {string=} name
 * @return {{run: function(), destroy: function()}}
 */
export function effect(fn, name) {
  vmCounters.polysiEffects++;
  const node = createEffectNode(fn, name || 'k', false);
  runEffect(node);
  return /** @type {?} */ (node);
}

/**
 * `[getter, setter, updater]`, as `_.H` returns.
 * @template T
 * @param {T} value
 * @param {string=} debugName
 * @return {!Array<?>}
 */
export function signal(value, debugName) {
  vmCounters.signals++;
  noteBreakdown('signals', getFrame(), debugName);
  return createSignal(value, undefined);
}

/**
 * @template T
 * @param {function(): T} fn
 * @param {(function(T, T): boolean)=} equal
 * @param {string=} debugName
 * @return {function(): T}
 */
export function computed(fn, equal, debugName) {
  vmCounters.computeds++;
  noteBreakdown('computeds', getFrame(), debugName);
  return createComputed(fn, equal);
}

/**
 * A signal that resets to `fn()` whenever the signals `fn` reads change.
 * @template T
 * @param {function(): T} fn
 * @param {string=} debugName
 * @return {function(): T}
 */
export function linkedSignal(fn, debugName) {
  vmCounters.linked++;
  return createLinkedSignal(fn, (source) => source, undefined);
}

/**
 * A linked signal with a setter, as `[getter, setter]` (`_.nS`).
 * @template T
 * @param {function(): T} fn
 * @param {string=} debugName
 * @return {!Array<?>}
 */
export function linkedState(fn, debugName) {
  vmCounters.linked++;
  noteBreakdown('linked', getFrame(), debugName);
  const get = createLinkedSignal(fn, (source) => source, undefined);
  return [get, (value) => linkedSignalSetFn(/** @type {?} */ (get)[SIGNAL], value)];
}

/**
 * Runs `fn` untracked.
 * @template T
 * @param {function(): T} fn
 * @return {T}
 */
export function runUntracked(fn) {
  const prev = setActiveConsumer(null);
  try {
    return fn();
  } finally {
    setActiveConsumer(prev);
  }
}

export {untracked};

/**
 * Writes a signal; the write flushes the effects that depend on it.
 * @template T
 * @param {function(T)} set
 * @param {T} value
 */
export function writeSignal(set, value) {
  set(value);
}

/**
 * Unwraps a value that may be a signal or thunk (`_.Dx`).
 * @param {*} v
 * @return {*}
 */
export function unwrap(v) {
  return typeof v === 'function' ? v() : v;
}
