/**
 * @fileoverview Behaviours of list items such as video results, shaped
 * like YouTube's: popups, the redux store binding, dismissal, lockup
 * interaction and action handlers.
 */
import {hostDom} from '../framework/host-dom.js';
import {getConfig} from '../framework/flags.js';
import {Priority, afterNextRender, cancel, schedule} from './scheduler.js';
import {appStore} from './store.js';
import {fireAction} from '../framework/actions.js';

/** @polymerBehavior */
export const OpenPopupBehavior = {
  properties: {
    popupPositionTarget: Object,
  },

  listeners: {
    'yt-service-request-completed': 'onOpenPopupServiceRequestCompleted_',
  },

  created() {
    this.openPopupConfig = null;
  },

  /**
   * @param {!Object} action
   * @param {!Object=} options
   */
  openPopup(action, options) {
    fireAction(/** @type {!Element} */ (this.hostElement), 'yt-open-popup-action',
        [Object.assign({}, action, {config: this.openPopupConfig}), options || {}]);
  },

  /**
   * @param {?Object|undefined} endpoint
   * @return {?Object}
   */
  getNavigationEndpointPopupAction(endpoint) {
    const popup = endpoint && endpoint.openPopupAction;
    return popup ? Object.assign({}, popup, {config: this.openPopupConfig}) : null;
  },

  /** @param {!CustomEvent} e */
  onOpenPopupServiceRequestCompleted_(e) {
    const detail = e.detail || {};
    if (detail.openPopupAction) this.openPopup(detail.openPopupAction);
  },
};

/**
 * Takes the popup configuration from the client config.
 * @polymerBehavior
 */
export const PopupConfigBehavior = {
  initFields_() {
    this._noAccessors = true;
  },

  created() {
    this.openPopupConfig = getConfig('OPEN_POPUP_CONFIG', null);
  },
};

/**
 * Binds `selector` properties to the app store: they are recomputed on
 * every store change while the element is attached.
 * @polymerBehavior
 */
export const ReduxBehavior = {
  properties: {
    reduxPropertiesRecomputeTrigger: Object,
  },

  /**
   * Turns the element's own `selector` properties into computed ones,
   * before the element is defined. Selectors declared by behaviours are not
   * wired, as on YouTube.
   * @param {!Object} info
   * @param {!Array<!Object>} behaviors
   * @param {boolean} signal Signal-schema elements turn selectors into
   *     redux schemas themselves.
   */
  registerDeclarations_(info, behaviors, signal) {
    if (signal) return;
    const selectors = {};
    const props = info.properties || {};
    for (const name of Object.keys(props)) {
      const decl = props[name];
      if (decl && decl.selector) selectors[name] = decl;
    }
    for (const name of Object.keys(selectors)) {
      const decl = selectors[name];
      const args = (decl.selectorArgs || []).join(',');
      info.properties[name] = {type: decl.type || Object,
        computed: `recomputeReduxSelector(reduxPropertiesRecomputeTrigger,"${name}"${args ? ',' + args : ''})`};
    }
    info.reduxSelectors_ = selectors;
  },

  beforeRegister() {},

  attached() {
    this.reduxPropertiesRecomputeTrigger = 0;
    if (!this.unsubscribeStore_) this.unsubscribeStore_ = this.store.subscribe(() => this.updateReduxProperties());
  },

  detached() {
    if (this.unsubscribeStore_) {
      this.unsubscribeStore_();
      this.unsubscribeStore_ = null;
    }
  },

  /** @return {!Object} */
  getState() {
    return this.store.getState();
  },

  /**
   * @param {{type: string, payload: *}} action
   * @return {*}
   */
  dispatch(action) {
    return this.store.dispatch(action);
  },

  updateReduxProperties() {
    this.reduxPropertiesRecomputeTrigger = (this.reduxPropertiesRecomputeTrigger || 0) + 1;
  },

  /**
   * @param {*} trigger
   * @param {string} name
   * @param {...*} args
   * @return {*}
   */
  recomputeReduxSelector(trigger, name, ...args) {
    const decl = this.reduxSelectors_ && this.reduxSelectors_[name];
    return decl ? decl.selector(this.getState(), ...args) : undefined;
  },

  /**
   * @param {function(!Object, ...*): *} fn
   * @param {...*} args
   * @return {*}
   */
  select(fn, ...args) {
    return fn(this.getState(), ...args);
  },
};

/** @polymerBehavior */
export const StoreBehavior = {
  /** @return {?} */
  get store() {
    return appStore;
  },
};

const DISMISSED_CONTENT_KEYSPACE = 'DISMISSED_CONTENT_KEYSPACE:';

/** @polymerBehavior */
export const DismissibleItemBehavior = {
  properties: {
    isDismissed: {type: Boolean, reflectToAttribute: true},
    dismissedRenderer: Object,
  },

  observers: ['dismissibleItemDataChanged_(data)'],

  listeners: {
    'yt-service-request-sent': 'dismissibleItemOnYtServiceRequestSent_',
    'yt-service-request-sent-button-renderer': 'dismissibleItemOnRequestSent',
    'yt-dismissible-item-action': 'dismissibleItemOnCommandSent',
    'yt-service-request-completed': 'dismissibleItemOnYtServiceRequestCompleted_',
  },

  created() {
    this._noAccessors = true;
    this.DISMISSED_CONTENT_KEYSPACE = DISMISSED_CONTENT_KEYSPACE;
    this.followUpDialogPromise = null;
    this.followUpDialogPromiseResolve = null;
    this.followUpDialogPromiseReject = null;
  },

  /** @param {!CustomEvent} e */
  dismissibleItemOnRequestSent(e) {
    for (const entry of [].concat(e.detail || [])) {
      const actions = entry && entry.signalServiceEndpoint && entry.signalServiceEndpoint.actions;
      if (actions) this.dismissibleItemProcessActions(actions, e);
    }
  },

  /**
   * @param {!CustomEvent} e
   * @param {!Array<!Object>=} commands
   */
  dismissibleItemOnCommandSent(e, commands) {
    if (commands) this.dismissibleItemProcessActions(commands, e);
  },

  /**
   * @param {string} id
   * @return {string}
   */
  setAndGetDismissedContentId(id) {
    this.dismissedContentId = this.DISMISSED_CONTENT_KEYSPACE + id;
    return this.dismissedContentId;
  },

  /** @param {!Object} action */
  replayDismissAction(action) {
    this.dismissibleItemProcessActions([action]);
  },

  /**
   * @param {!Array<!Object>} actions
   * @param {?Event=} e
   */
  dismissibleItemProcessActions(actions, e) {
    for (const action of actions) {
      if (action.commandExecutorCommand && action.commandExecutorCommand.commands) {
        this.dismissibleItemProcessActions(action.commandExecutorCommand.commands, e);
      }
      if (action.replaceEnclosingAction) {
        const replace = action.replaceEnclosingAction;
        if (!replace.replaceParentSection || this.isSectionComponent()) {
          if (replace.groupDismissal) setGroupDismissal(this, replace.groupDismissal, true);
          this.dismissibleItemHandleReplaceEnclosingAction_(replace);
          if (this.dismissedContentId) dispatchCommandEntity(this, action);
          if (e) e.stopPropagation();
        }
      } else if (action.hideEnclosingAction) {
        this.dismissibleItemHandleHideEnclosingAction_();
        if (e) e.stopPropagation();
      } else if (action.undoFeedbackAction) {
        const undo = action.undoFeedbackAction;
        if (undo && undo.targetGroupId) setGroupDismissal(this, {targetGroupId: undo.targetGroupId}, false);
        this.dismissibleItemHandleUndoFeedbackAction_();
        if (this.dismissedContentId) dispatchCommandEntity(this, undefined);
        if (e) e.stopPropagation();
      } else if (action.signalServiceEndpoint) {
        const actions = action.signalServiceEndpoint.actions;
        if (actions) {
          fireAction(/** @type {!Element} */ (this.hostElement), 'yt-action', [actions]);
          if (e) e.stopPropagation();
        }
      } else if (action.signalAction && action.signalAction.signal === 'TELL_US_WHY' && !action.signalAction.targetId) {
        this.dismissibleItemHandleTellUsWhySignalAction_();
        if (e) e.stopPropagation();
      }
    }
  },

  /** @return {boolean} */
  isSectionComponent() {
    return SECTION_COMPONENTS.has(this.hostElement.nodeName.toLowerCase());
  },

  /** @param {?Object} data */
  dismissibleItemDataChanged_(data) {
    this.dismissedContentId = undefined;
    this.dismissibleItemReset_();
  },

  dismissibleItemReset_() {
    if (this.isDismissed) this.isHideEnclosingAction = this.isDismissed = false;
    if (this.dismissedRenderer) this.dismissedRenderer = undefined;
    if (this.followUpDialogPromiseReject) {
      this.followUpDialogPromise.catch(() => {});
      this.followUpDialogPromiseReject();
    }
    this.followUpDialogPromise = new Promise((resolve, reject) => {
      this.followUpDialogPromiseResolve = resolve;
      this.followUpDialogPromiseReject = reject;
    });
    this.hostElement.dispatchEvent(new CustomEvent('yt-enable-lockup-interaction', {bubbles: true, composed: true}));
  },

  /**
   * @param {!CustomEvent} e
   * @param {?Object} detail
   */
  dismissibleItemOnYtServiceRequestSent_(e, detail) {
    if (detail && detail.actions) this.dismissibleItemProcessActions(detail.actions, e);
  },

  /**
   * @param {!CustomEvent} e
   * @param {?Object} detail
   */
  dismissibleItemOnYtServiceRequestCompleted_(e, detail) {
    const dialog = detail && detail.data && detail.data.feedbackResponses && detail.data.feedbackResponses[0] &&
        detail.data.feedbackResponses[0].followUpDialog;
    if (dialog) this.followUpDialogPromiseResolve(dialog);
    else if (detail && detail.actions && !this.dismissedRenderer) this.dismissibleItemProcessActions(detail.actions, e);
  },

  /** @param {!Object} replace */
  dismissibleItemHandleReplaceEnclosingAction_(replace) {
    this.dismissedRenderer = replace.item;
    this.isDismissed = true;
    const dismissed = hostDom(this.hostElement).querySelector('#dismissed');
    if (dismissed) afterNextRender(this, () => focusFirstFocusable(dismissed));
    this.hostElement.dispatchEvent(new CustomEvent('yt-disable-lockup-interaction', {bubbles: true, composed: true,
      detail: this.dismissedRenderer}));
  },

  dismissibleItemHandleHideEnclosingAction_() {
    this.isHideEnclosingAction = this.isDismissed = true;
  },

  dismissibleItemHandleUndoFeedbackAction_() {
    this.hostElement.dispatchEvent(new CustomEvent('yt-dismissible-item-undo-feedback', {bubbles: true, composed: true}));
    this.dismissibleItemReset_();
  },

  dismissibleItemHandleTellUsWhySignalAction_() {
    this.followUpDialogPromise.then(dialog => this.openPopup({openPopupAction: {popupType: 'DIALOG', popup: dialog}}));
  },
};

/**
 * Tells the section that an item's group is dismissed or restored.
 * @param {!Object} self
 * @param {!Object} group
 * @param {boolean} dismissed
 */
function setGroupDismissal(self, group, dismissed) {
  if (self.rowIndex !== undefined) fireAction(/** @type {!Element} */ (self.hostElement), 'yt-section-reactive-dismissal', [self.rowIndex, group, dismissed]);
}

/**
 * Stores the command that dismissed an item under its dismissed content id.
 * @param {!Object} self
 * @param {?Object|undefined} command
 */
function dispatchCommandEntity(self, command) {
  self.dispatch({type: 'ENTITY_UPDATE', payload: {entityType: 'commandEntity', key: self.dismissedContentId,
    value: {key: self.dismissedContentId, command}}});
}

/**
 * Focuses the first focusable element in `root`, or `root` itself.
 * @param {!Element} root
 */
function focusFirstFocusable(root) {
  const target = /** @type {?HTMLElement} */ (root.querySelector('a[href], button, [tabindex]:not([tabindex="-1"])'));
  if (target && target.offsetParent) {
    target.focus();
    return;
  }
  if (!root.hasAttribute('tabindex')) root.setAttribute('tabindex', '-1');
  /** @type {!HTMLElement} */ (root).focus();
}

const SECTION_COMPONENTS = new Set(['ytl-rich-shelf-renderer']);

/** The tags that don't use the expandable tooltip. */
const NO_EXPANDABLE_TOOLTIP = ['ytl-grid-video-renderer', 'ytl-compact-video-renderer'];

/** @polymerBehavior */
export const LockupBehavior = {
  properties: {
    data: Object,
    lockupIsHovered: Boolean,
    lockupTouchTriggered: Boolean,
    useExpandableTooltip: Boolean,
  },

  listeners: {
    'down': 'lockupOnDown',
    'up': 'lockupOnUp',
    'touchstart': 'onTouchStart',
    'mouseenter': 'lockupOnMouseEnter',
    'mouseleave': 'lockupOnMouseLeave',
    'yt-popup-closed': 'lockupOnPopupClosed',
    'yt-lockup-requested': 'lockupOnLockupRequested',
    'yt-service-request-sent': 'lockupOnYtServiceRequestSent',
    'yt-disable-lockup-interaction': 'lockupOnLockupDisabled',
    'yt-enable-lockup-interaction': 'lockupOnLockupEnabled',
  },

  created() {
    this.hoverJobId = 0;
    this['JSC$18135_touched'] = false;
    this.useExpandableTooltip = !NO_EXPANDABLE_TOOLTIP.includes(this.is);
  },

  attached() {
    const host = this.hostElement;
    if (!host.hasAttribute('lockup')) host.setAttribute('lockup', 'true');
  },

  detached() {
    this.useExpandableTooltip = false;
  },

  /** @return {?Element} */
  get interactionElement() {
    return hostDom(this.hostElement).querySelector('#interaction');
  },

  /**
   * @param {!Event} e
   * @return {boolean}
   */
  lockupHitsButton_(e) {
    const host = this.hostElement;
    for (const n of e.composedPath()) {
      if (n === host) return false;
      if (/** @type {?} */ (n).tagName === 'BUTTON') return true;
    }
    return false;
  },

  /** @param {!Event} e */
  lockupOnDown(e) {
    const interaction = this.interactionElement;
    if (interaction && !this.lockupHitsButton_(e)) /** @type {?} */ (interaction).triggerDown();
  },

  /** @param {!Event} e */
  lockupOnUp(e) {
    const interaction = this.interactionElement;
    if (interaction && !this.lockupHitsButton_(e)) /** @type {?} */ (interaction).triggerUp();
  },

  onTouchStart() {
    this['JSC$18135_touched'] = true;
  },

  lockupOnMouseEnter() {
    const delay = Number(getConfig('EXPERIMENT_FLAGS', {})['kevlar_lockup_hover_delay']) || 0;
    if (this['JSC$18135_touched'] && delay >= 0) {
      this.hoverJobId = schedule(() => {
        this.hoverJobId = 0;
        this.lockupIsHovered = true;
      }, Priority.DEFERRED);
    } else {
      this.lockupIsHovered = true;
    }
  },

  lockupOnMouseLeave() {
    if (this.hoverJobId) cancel(this.hoverJobId);
    this.hoverJobId = 0;
    this.lockupIsHovered = false;
  },

  /** @param {!CustomEvent} e */
  lockupOnPopupClosed(e) {
    const popup = e.detail && e.detail.popup;
    if (popup && popup.localName === 'ytl-menu-popup-renderer') this.logExplicitClick(popup);
  },

  /** @param {!CustomEvent} e */
  lockupOnLockupRequested(e) {
    const ids = e.detail && e.detail.videoIds;
    if (ids && this.data && ids[0] === this.data.videoId) e.detail.returnValue = [this.data];
  },

  /**
   * @param {!CustomEvent} e
   * @param {?Object} detail
   */
  lockupOnYtServiceRequestSent(e, detail) {
    for (const action of (detail && detail.actions) || []) {
      if (action.removeFromPlaylistByVideoIdCommand) this.lockupHandleRemoveFromPlaylistByVideoIdCommand(action.removeFromPlaylistByVideoIdCommand);
      if (action.removeFromPlaylistBySetVideoIdCommand) this.lockupHandleRemoveFromPlaylistBySetVideoIdCommand(action.removeFromPlaylistBySetVideoIdCommand);
    }
  },

  lockupOnLockupDisabled() {
    const interaction = this.interactionElement;
    if (interaction) /** @type {?} */ (interaction).disabled = true;
  },

  lockupOnLockupEnabled() {
    if (!this.$) {
      console.warn('component not ready', this.is, this.getParentRenderer());
      return;
    }
    const interaction = this.interactionElement;
    if (interaction) /** @type {?} */ (interaction).disabled = false;
  },

  /** @param {!Object} command */
  lockupHandleRemoveFromPlaylistByVideoIdCommand(command) {
    fireAction(/** @type {!Element} */ (this.hostElement), 'yt-playlist-remove-video', [command.videoId]);
  },

  /** @param {!Object} command */
  lockupHandleRemoveFromPlaylistBySetVideoIdCommand(command) {
    fireAction(/** @type {!Element} */ (this.hostElement), 'yt-playlist-remove-video', [command.setVideoId]);
  },
};

/** Action name to the components that handle it, with their handlers. */
const actionRoutingMap = new Map();

/** @polymerBehavior */
export const ActionHandlerBehavior = {
  attached() {
    if (this.actionMap) this.registerActionMap(this.actionMap);
  },

  detached() {
    if (this.actionMap) this.unregisterActionMap(this.actionMap);
  },

  /** @param {!Object<string, string>} map */
  registerActionMap(map) {
    for (const action of Object.keys(map)) {
      let handlers = actionRoutingMap.get(action);
      if (!handlers) {
        handlers = new Map();
        actionRoutingMap.set(action, handlers);
      }
      handlers.set(this, this[map[action]].bind(this));
    }
  },

  /** @param {!Object<string, string>} map */
  unregisterActionMap(map) {
    for (const action of Object.keys(map)) {
      const handlers = actionRoutingMap.get(action);
      if (handlers) handlers.delete(this);
    }
  },
};

/**
 * Runs the handlers registered for `action`.
 * @param {string} action
 * @param {!Array<*>} args
 * @return {boolean} Whether any component handled it.
 */
export function routeAction(action, args) {
  const handlers = actionRoutingMap.get(action);
  if (!handlers || !handlers.size) return false;
  for (const handler of handlers.values()) handler(...args);
  return true;
}

/**
 * Forwards events of an element to another target while forwarding is on.
 * @polymerBehavior
 */
export const EventForwardingBehavior = {
  /**
   * @param {!Event} e
   * @return {boolean}
   */
  shouldForward(e) {
    return !!this.forwardingTarget_ && !e.defaultPrevented;
  },

  /**
   * @param {!EventTarget} target
   * @param {!Array<string>} types
   */
  startForwardingEvents(target, types) {
    this.stopForwardingEvents();
    this.forwardingTarget_ = target;
    this.forwardedTypes_ = types;
    this.boundForward_ = this.boundForward_ || ((/** !Event */ e) => {
      if (this.shouldForward(e)) this.forwardingTarget_.dispatchEvent(new CustomEvent(e.type, {detail: /** @type {?} */ (e).detail}));
    });
    for (const type of types) this.hostElement.addEventListener(type, this.boundForward_);
  },

  stopForwardingEvents() {
    for (const type of this.forwardedTypes_ || []) this.hostElement.removeEventListener(type, this.boundForward_);
    this.forwardingTarget_ = null;
    this.forwardedTypes_ = null;
  },
};

