/**
 * @fileoverview The shopping elements of the watch page, from kevlar's
 * classes and templates: the product list of a shopping panel (list, header
 * and item) and the merchandise shelf of the description (shelf and item).
 * Not ported: the sized image view model of a merchandise item (the data
 * never has one), the empty product shelf and details renderers, and the
 * countdown of a hidden product.
 */
import {Polymer, withHandles, withQueries} from '../../framework/polysi/register.js';
import {Debouncer} from '@polymer/polymer/lib/utils/debounce.js';
import {timeOut} from '@polymer/polymer/lib/utils/async.js';
import {IronResizableBehavior} from '@polymer/iron-resizable-behavior/iron-resizable-behavior.js';
import {fireAction} from '../../framework/actions.js';
import {flag} from '../../framework/flags.js';
import {hostDom} from '../../framework/host-dom.js';
import {getText} from '../../framework/text.js';
import {registerRenderer} from '../../framework/registry.js';
import {RendererBehavior} from '../renderer-behavior.js';
import {YtRendererStamperBehavior} from '../renderer-stamper.js';
import {ActionHandlerBehavior, DismissibleItemBehavior, OpenPopupBehavior, PopupConfigBehavior, ReduxBehavior, StoreBehavior} from '../item-behaviors.js';
import {TaskEmitterBehavior} from '../container-behaviors.js';
import {graftServerVe} from '../logging.js';
import {HorizontalListBehavior} from '../horizontal-list.js';
import {template as productListTemplate} from '../../../gen/templates/ytl-product-list-renderer.js';
import {template as productListHeaderTemplate} from '../../../gen/templates/ytl-product-list-header-renderer.js';
import {template as productListItemTemplate} from '../../../gen/templates/ytl-product-list-item-renderer.js';
import {template as merchShelfTemplate} from '../../../gen/templates/ytl-merch-shelf-renderer.js';
import {template as merchItemTemplate} from '../../../gen/templates/ytl-merch-shelf-item-renderer.js';

/** The fixed width at which a shelf with several items switches from small to large items. */
const LARGE_ITEM_MIN_WIDTH = 740;

/**
 * Shows a message in a toast.
 * @param {!Element} source
 * @param {?string|undefined} text
 */
function showSnackbar(source, text) {
  if (text) fireAction(source, 'yt-open-popup-action', [{notificationActionRenderer: {responseText: {simpleText: text}}}]);
}

/**
 * The success message of the toast that a placeholder product's command adds.
 * @param {?Object|undefined} command
 * @return {string}
 */
function placeholderMessage(command) {
  const toast = command && command.addToToastAction;
  return getText(toast && toast.item && toast.item.notificationTextRenderer && toast.item.notificationTextRenderer.successResponseText);
}

Polymer(withHandles({
  _template: productListTemplate,
  is: 'ytl-product-list-renderer',
  behaviors: [RendererBehavior, YtRendererStamperBehavior],
  properties: {
    data: Object,
    panelContentVisible: {type: Boolean, reflectToAttribute: true},
  },
  observers: ['panelContentVisibleChanged(panelContentVisible)'],

  created() {
    this.monitorScroll = true;
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.contents': {id: 'contents', mapping: {
        'productListHeaderRenderer': 'ytl-product-list-header-renderer',
        'productListItemRenderer': 'ytl-product-list-item-renderer',
      }},
    };
  },

  /**
   * Tells the player whether the products of the video are shown, which it
   * marks on its root.
   * @param {boolean} visible
   */
  panelContentVisibleChanged(visible) {
    const player = document.getElementById('movie_player');
    if (player) player.toggleAttribute('products-in-video-visible', !!visible);
  },
}, ['ytRendererBehavior', 'ytRendererstamperBehavior']));
registerRenderer('productListRenderer', 'ytl-product-list-renderer');

Polymer(withHandles({
  _template: productListHeaderTemplate,
  is: 'ytl-product-list-header-renderer',
  behaviors: [RendererBehavior, YtRendererStamperBehavior],
  properties: {
    data: Object,
    suppressPaddingDisclaimer: {type: Boolean, reflectToAttribute: true, computed: '__compute__suppressPaddingDisclaimer(data)'},
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__suppressPaddingDisclaimer(data) {
    return !!(data && data.suppressPaddingDisclaimer);
  },
}, ['ytRendererBehavior', 'componentBehavior', 'ytRendererstamperBehavior']));
registerRenderer('productListHeaderRenderer', 'ytl-product-list-header-renderer');

Polymer(withHandles({
  _template: productListItemTemplate,
  is: 'ytl-product-list-item-renderer',
  behaviors: [RendererBehavior, YtRendererStamperBehavior],
  properties: {
    data: Object,
    useCenterLayoutContainer: {type: Boolean, reflectToAttribute: true, computed: '__compute__useCenterLayoutContainer(isProductPlaceholder)'},
    buttonOverride: {type: Object, computed: 'computeButtonOverride(data)'},
    isProductPlaceholder: {type: Boolean, computed: '__compute__isProductPlaceholder(data)'},
    showDropCountdown: {type: Boolean, computed: '__compute__showDropCountdown(isProductPlaceholder,data)'},
    showBrandName: {type: Boolean, computed: '__compute__showBrandName(isProductPlaceholder,data)'},
    showPriceReplacementText: {type: Boolean, computed: '__compute__showPriceReplacementText(data)'},
    showPrice: {type: Boolean, computed: '__compute__showPrice(data)'},
    showMetadata: {type: Boolean, computed: '__compute__showMetadata(isProductPlaceholder)'},
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.actionButton': {id: 'action-button', mapping: {'buttonRenderer': 'ytl-button-renderer', 'menuRenderer': 'ytl-menu-renderer'}},
      'data.viewButton': {id: 'view-button', mapping: {'buttonRenderer': {component: 'ytl-button-renderer',
        properties: {'overrides': 'buttonOverride'}}}},
    };
  },

  /**
   * @param {?Object} data
   * @return {?Object|undefined}
   */
  computeButtonOverride(data) {
    if (data) return {size: 'S'};
    return undefined;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__isProductPlaceholder(data) {
    return !!(data && data.isProductPlaceholder);
  },

  /**
   * @param {boolean} placeholder
   * @return {boolean}
   */
  __compute__useCenterLayoutContainer(placeholder) {
    return placeholder;
  },

  /**
   * @param {boolean} placeholder
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__showDropCountdown(placeholder, data) {
    return !!(placeholder && data && data.hiddenProductOptions && data.hiddenProductOptions.showDropCountdown && data.hiddenProductOptions.dropTimestamp);
  },

  /**
   * @param {boolean} placeholder
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__showBrandName(placeholder, data) {
    return !placeholder && !(data && data.merchantName);
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__showPriceReplacementText(data) {
    return !!(data && data.priceReplacementText);
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__showPrice(data) {
    return !(data && data.priceReplacementText) && !!(data && data.price);
  },

  /**
   * @param {boolean} placeholder
   * @return {boolean}
   */
  __compute__showMetadata(placeholder) {
    return !placeholder;
  },

  /** Shows the message of a placeholder product's command. */
  showSnackbarIfPlaceholder() {
    if (this.isProductPlaceholder) showSnackbar(this.hostElement, placeholderMessage(this.data && this.data.onClickCommand));
  },
}, ['ytRendererBehavior', 'componentBehavior', 'ytRendererstamperBehavior']));
registerRenderer('productListItemRenderer', 'ytl-product-list-item-renderer');

Polymer(withHandles({
  _template: merchItemTemplate,
  is: 'ytl-merch-shelf-item-renderer',
  behaviors: [RendererBehavior],
  properties: {
    data: Object,
    itemStyle: {type: String, reflectToAttribute: true, value: 'small-item'},
    hasPrice: {type: Boolean, computed: '__compute__hasPrice(data)'},
    hasPriceReplacementText: {type: Boolean, computed: '__compute__hasPriceReplacementText(data)'},
    hasAdditionalFeesText: {type: Boolean, computed: '__compute__hasAdditionalFeesText(data)'},
    hasAffiliateDisclaimer: {type: Boolean, computed: '__compute__hasAffiliateDisclaimer(data)'},
    isProductPlaceholder: {type: Boolean, computed: '__compute__isProductPlaceholder(data)'},
    hideOpenInNewIcon: {type: Boolean, computed: '__compute__hideOpenInNewIcon(data)'},
    ariaLabel: {type: String, computed: '__compute__ariaLabel(data)'},
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__hasPrice(data) {
    return !!data && data.price !== undefined;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__hasPriceReplacementText(data) {
    return !!(data && data.priceReplacementText);
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__hasAdditionalFeesText(data) {
    return !!data && data.additionalFeesText !== undefined;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__hasAffiliateDisclaimer(data) {
    return !!data && data.affiliateDisclaimer !== undefined;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__isProductPlaceholder(data) {
    return !!data && data.isProductPlaceholder !== undefined && !!data.isProductPlaceholder;
  },

  /**
   * @param {?Object} data
   * @return {boolean}
   */
  __compute__hideOpenInNewIcon(data) {
    return !!data && data.showOpenInNewIcon === false;
  },

  /**
   * @param {?Object} data
   * @return {string}
   */
  __compute__ariaLabel(data) {
    if (!data) return '';
    if (data.accessibilityTitle) return data.accessibilityTitle;
    return `${data.title}, ${data.price}, ${data.additionalFeesText}, ${data.vendorName}`;
  },

  /** Shows the message of a placeholder product's command. */
  showSnackbarIfPlaceholder() {
    if (this.isProductPlaceholder) showSnackbar(this.hostElement, placeholderMessage(this.data && this.data.buttonCommand));
  },
}, ['ytRendererBehavior']));

Polymer(withQueries(withHandles({
  _template: merchShelfTemplate,
  is: 'ytl-merch-shelf-renderer',
  behaviors: [RendererBehavior, YtRendererStamperBehavior, ...HorizontalListBehavior, IronResizableBehavior, ActionHandlerBehavior,
    DismissibleItemBehavior, OpenPopupBehavior, PopupConfigBehavior, ReduxBehavior, StoreBehavior, TaskEmitterBehavior],
  properties: {
    data: Object,
    itemsPath: String,
    actionMap: Object,
    updateOnResizeDebouncer: Object,
    itemStyle: {type: String, reflectToAttribute: true, value: 'link-item'},
    watchMetadataRefresh: {type: Object, reflectToAttribute: true},
    skinnyMode: {type: Object, reflectToAttribute: true},
    metaPanel: {type: Object, reflectToAttribute: true},
    inStructuredDescription: {type: Object, reflectToAttribute: true},
    detailedDescriptionOverride: {type: Object, reflectToAttribute: true},
    hasHeader: {type: Object, reflectToAttribute: true},
    noDivider: {type: Boolean, reflectToAttribute: true, value: () => flag('web_watch_no_dividers')},
  },
  observers: ['dataChanged(data)'],
  listeners: {'iron-resize': 'debouncedUpdateOnResize'},

  initFields_() {
    this.itemsPath = 'data.items';
    this.itemStyle = 'link-item';
    this.watchMetadataRefresh = false;
    this.skinnyMode = false;
    this.metaPanel = false;
    this.inStructuredDescription = false;
    this.detailedDescriptionOverride = false;
    this.hasHeader = false;
    this.actionMap = {'yt-update-merchandise-shelf-action': 'handleUpdateMerchShelfAction'};
    this.updateOnResizeDebouncer = null;
  },

  attached() {
    if (!window.IntersectionObserver || !flag('enable_web_side_rail')) return;
    this.intersectionObserver = new IntersectionObserver(entries => {
      if (entries[0] && entries[0].isIntersecting) this.debouncedUpdateOnResize();
    });
    this.intersectionObserver.observe(this.hostElement);
  },

  detached() {
    if (this.intersectionObserver) this.intersectionObserver.disconnect();
    this.intersectionObserver = undefined;
  },

  ready() {
    this.updateOnResize = this.updateOnResize.bind(this);
    this.updateOnResize();
  },

  /** @return {!Object<string, !Object>} */
  configureRendererStamper() {
    return {
      'data.header': {id: 'section-header-container', mapping: {'sectionHeaderViewModel': {component: 'ytl-section-header-view-model',
        params: {'disableHorizontalPadding': true}}}},
      'data.actionButton': {id: 'action-button', mapping: {'buttonRenderer': {component: 'ytl-button-renderer', params: {'iconSize': 16}},
        'menuRenderer': 'ytl-menu-renderer'}},
    };
  },

  /** Scrolls back and sizes the items for the new data. */
  dataChanged() {
    this.reset();
    this.updateOnResize();
    this.hasHeader = !!(this.data && this.data.header);
  },

  /**
   * Replaces the shelf's data with the one an update action carries, after
   * its render delay.
   * @param {{updateMerchandiseShelfAction: {merchandiseShelf: !Object}}} action
   */
  handleUpdateMerchShelfAction(action) {
    const shelf = action.updateMerchandiseShelfAction.merchandiseShelf.merchandiseShelfRenderer;
    if (!shelf) return;
    const apply = () => {
      this.attachVEs(shelf);
      this.data = shelf;
    };
    if (shelf.renderDelayMs) {
      clearTimeout(this.dataSetTimeoutId);
      this.dataSetTimeoutId = setTimeout(apply, Number(shelf.renderDelayMs));
    } else {
      apply();
    }
  },

  /** @param {!Object} shelf */
  attachVEs(shelf) {
    if (shelf.trackingParams) graftServerVe(shelf.trackingParams);
  },

  /** Sizes the items by the shelf type, or the width of the shelf. */
  updateOnResize() {
    const container = /** @type {?HTMLElement} */ (hostDom(this.hostElement).querySelector('#scroll-container'));
    const items = /** @type {?HTMLElement} */ (hostDom(this.hostElement).querySelector('#items'));
    if (!container || container.clientWidth === 0 || !items) return;
    const width = container.clientWidth;
    this.offset = Math.max(0, Math.min(this.offset, items.clientWidth - width));
    this.reposition_();
    switch (this.data && this.data.shelfType) {
      case 'MERCHANDISE_SHELF_TYPE_PRODUCT_LINK':
        this.itemStyle = 'link-item';
        break;
      case 'MERCHANDISE_SHELF_TYPE_LINK_MERCH_SHELF':
        this.itemStyle = 'link-item-merch-shelf';
        break;
      case 'MERCHANDISE_SHELF_TYPE_COMPACT':
        this.itemStyle = 'compact-item';
        break;
      default:
        this.itemStyle = this.data && this.data.items && this.data.items.length === 1 ? 'cta-item' :
          width >= LARGE_ITEM_MIN_WIDTH ? 'large-item' : 'small-item';
    }
  },

  /** Runs `updateOnResize` after the resizing has settled for 100 ms. */
  debouncedUpdateOnResize() {
    this.updateOnResizeDebouncer = Debouncer.debounce(this.updateOnResizeDebouncer, timeOut.after(100), this.updateOnResize);
  },
}, ['ytRendererBehavior', 'ytRendererstamperBehavior', 'ytdHorizontalListBehavior', 'ytComponentBehavior', 'ytActionHandlerBehavior',
  'ytdDismissibleItemBehavior']), {items: 'items', scrollContainer: 'scroll-container'}));
registerRenderer('merchandiseShelfRenderer', 'ytl-merch-shelf-renderer');
