/**
 * @fileoverview The button shape (`_.YB`) and its CoW host
 * (`ytl-button-shape`). Legacy button renderers and the menu renderer pass
 * a shape config through `data`; the button view model builds one from
 * button JSON. The config is read through 30 field thunks, from which 14
 * derived thunks, three computeds, a class list with 16 conditional
 * classes and a custom-colour style are built. The content is a set of
 * named `cond`s: icons, text, touch feedback, middleground asset and light
 * shape.
 */
import {classes, styles} from '../../framework/vm/classes.js';
import {Switch, cond, renderers} from '../../framework/vm/control.js';
import {computed, linkedSignal, signal, unwrap} from '../../framework/vm/effect.js';
import {PropKind, defineCoW} from '../../framework/vm/element.js';
import {h} from '../../framework/vm/jsx.js';
import {onCleanup} from '../../framework/vm/owner.js';
import {defineComponent} from '../../framework/vm/render.js';
import {flag} from '../../framework/flags.js';
import {rootInjector} from '../../framework/injector.js';
import {linkConfig} from '../../framework/link.js';
import {BUTTON_FLAGS, readFlags, shapeSizeClass, shapeStyleClass, shapeTypeClass} from './enums.js';
import {DarkTheme, Icon, LightShape, TouchFeedbackShape, themeColor, useTooltip} from './primitives.js';
import {AttributedString} from './attributed-string.js';
import {cssNumber, useLayoutResolver} from './hooks.js';

/**
 * @param {function(): *} data
 * @param {string} name
 * @param {*} fallback
 * @return {function(): *}
 */
function field(data, name, fallback) {
  return () => {
    const d = data();
    const v = d ? d[name] : undefined;
    return v === undefined ? fallback : v;
  };
}

/**
 * The field thunks of a button-shape config (`yUj`).
 * @param {function(): *} data
 * @return {!Object<string, function(): *>}
 */
export function shapeFields(data) {
  return {
    size: field(data, 'size', 'M'),
    style: field(data, 'style', 'mono'),
    type: field(data, 'type', 'text'),
    focused: field(data, 'focused', false),
    disabled: () => field(data, 'state', 'active')() === 'disabled' || !!field(data, 'disabled', false)(),
    onTap: field(data, 'onTap', null),
    alignByText: field(data, 'alignByText', false),
    aTagConfig: field(data, 'aTagConfig', null),
    customColors: field(data, 'customColors', null),
    segmentedPosition: field(data, 'segmentedPosition', ''),
    toggled: field(data, 'toggled', false),
    toggleable: field(data, 'toggleable', false),
    accessibilityLabel: field(data, 'accessibilityLabel', ''),
    ariaDescribedby: field(data, 'ariaDescribedby', undefined),
    onToggle: field(data, 'onToggle', null),
    iconPosition: field(data, 'iconPosition', undefined),
    iconName: field(data, 'iconName', ''),
    oneOffCustomTextWrap: field(data, 'oneOffCustomTextWrap', false),
    disableTextEllipsis: field(data, 'disableTextEllipsis', false),
    disableBackdropFilter: field(data, 'disableBackdropFilter', false),
    tooltipText: field(data, 'tooltipText', ''),
    tooltipShape: field(data, 'tooltipShape', null),
    ariaHidden: field(data, 'ariaHidden', undefined),
    ariaExpanded: field(data, 'ariaExpanded', undefined),
    ariaHasPopup: field(data, 'ariaHasPopup', undefined),
    tabIndex: field(data, 'tabIndex', undefined),
    buttonText: field(data, 'buttonText', ''),
    formattedButtonText: field(data, 'formattedButtonText', null),
    animatedTextProps: field(data, 'animatedTextProps', null),
    onClickRateLimitMs: field(data, 'onClickRateLimitMs', 0),
    onHover: field(data, 'onHover', null),
    middlegroundAsset: field(data, 'middlegroundAsset', null),
    disableLightShape: field(data, 'disableLightShape', false),
    disableStaticLight: field(data, 'disableStaticLight', false),
  };
}

const ICON_SIZE_CONDENSED = {ytSysMeasurementReference: 'YT_SYS_MEASUREMENT_REFERENCE_ICON_SIZE_CONDENSED'};
const ICON_SIZE_COMFORTABLE = {ytSysMeasurementReference: 'YT_SYS_MEASUREMENT_REFERENCE_ICON_SIZE_COMFORTABLE'};
const ICON_SIZE_MINI = {ytSysMeasurementReference: 'YT_SYS_MEASUREMENT_REFERENCE_ICON_SIZE_MINI'};
const ICON_SIZE_COMPACT = {ytSysMeasurementReference: 'YT_SYS_MEASUREMENT_REFERENCE_ICON_SIZE_COMPACT'};

/**
 * Whether a small button shows its icon at the comfortable size (`rU4`).
 * @param {!Object} config
 * @param {boolean} hasIcon
 * @return {boolean}
 */
function smallIconOnly(config, hasIcon) {
  const iconOnly = (config.iconPosition === 'icon-only' || config.iconPosition === 'icon-only-40' ||
      config.iconPosition === 'icon-with-label') && hasIcon;
  return !config.segmentedPosition && iconOnly && config.size === 'S';
}

/**
 * The icon size in pixels of a button config (`_.lCu`), from the layout
 * resolver's icon-size tokens or their defaults.
 * @param {!Object} config
 * @param {boolean} hasIcon
 * @param {function(): (function(!Object): (string|undefined)|undefined)} resolverSignal
 * @param {boolean=} ignoreOverride
 * @return {number}
 */
export function buttonIconSize(config, hasIcon, resolverSignal, ignoreOverride) {
  const resolver = resolverSignal();
  const token = (t, fallback) => {
    const v = cssNumber(resolver ? resolver(t) : undefined);
    return v !== undefined ? v : fallback;
  };
  if (flag('web_button_icon_size_experiment')) {
    const mini = token(ICON_SIZE_MINI, 12);
    const compact = token(ICON_SIZE_COMPACT, 18);
    const comfortable = token(ICON_SIZE_COMFORTABLE, 24);
    switch (config.size) {
      case 'XS':
        return mini;
      case 'S':
        return !ignoreOverride && smallIconOnly(config, hasIcon) ? comfortable : compact;
      case 'M':
        return flag('web_button_mainstage_v2') ? compact : comfortable;
      default:
        return comfortable;
    }
  }
  const condensed = token(ICON_SIZE_CONDENSED, 16);
  const comfortable = token(ICON_SIZE_COMFORTABLE, 24);
  switch (config.size) {
    case 'XS':
      return condensed;
    case 'S':
      return !ignoreOverride && smallIconOnly(config, hasIcon) ? comfortable : condensed;
    default:
      return comfortable;
  }
}

/**
 * The derived thunks of a button shape (`TPu`).
 * @param {!Object} props
 * @return {!Object<string, function(): *>}
 */
export function derivedFields(props) {
  const f = shapeFields(props.data);
  const iconName = () => f.iconName() || unwrap(props.iconName) || '';
  const secondary = () => unwrap(props.secondaryIconName) || '';
  const hasText = () => !!(f.buttonText() || f.formattedButtonText() || f.animatedTextProps());
  const position = f.iconPosition;
  const customIcon = props.icon;
  const hasIcon = () => !!customIcon || !!iconName();
  const hasIconOnly = () => hasIcon() && (position() === 'icon-only' || !hasText());
  const resolver = useLayoutResolver();
  return {
    customIcon,
    type: () => (f.disabled() && f.type() === 'filled' ? 'tonal' : f.type()),
    shouldFocus: () => !!f.focused() && !f.disabled(),
    hasIconLeading: () => hasIcon() && hasText() && (position() === 'leading' || position() === 'leading-trailing'),
    hasIconTrailing: () => hasIcon() && hasText() && (position() === 'trailing' || position() === 'leading-trailing'),
    hasIconLeadingTrailing: () => hasIcon() && !!secondary() && position() === 'leading-trailing',
    hasIconOnly,
    hasIconOnly40: () => hasIconOnly() && f.size() === 'M' && flag('web_button_mainstage_padding'),
    hasIconWithLabel: () => hasIcon() && position() === 'above',
    iconButton: () => hasIconOnly() && position() === 'icon-only',
    visiblyDisabled: () => f.disabled() && !f.toggleable(),
    overrideSmallSizeIcon: () => f.size() === 'S' && flag('web_button_icon_size_experiment'),
    iconToRender: () => (f.toggled() && secondary() ? secondary() : iconName()),
    secondaryIconToRender: () => (position() === 'leading-trailing' ? secondary() : ''),
    iconSize: () => {
      const data = /** @type {!Object} */ (unwrap(props.data)) || {};
      return buttonIconSize(data, true, resolver, data.ignoreIconSizeOverride);
    },
  };
}

/**
 * @param {*} tap
 * @param {number} ms
 * @return {*}
 */
function rateLimited(tap, ms) {
  if (typeof tap !== 'function') return tap;
  let last = 0;
  return (e) => {
    const now = performance.now();
    if (now - last < ms) return;
    last = now;
    tap(e);
  };
}

/**
 * @param {*} colors
 * @param {string} key
 * @return {string|undefined}
 */
function customColor(colors, key) {
  const c = colors && colors[key === 'textColor' ? 'color' : key];
  if (typeof c === 'string') return c;
  const legacy = colors && colors[key];
  return legacy && typeof legacy === 'object' ? themeColor(legacy.themeToken || null, legacy.raw) : undefined;
}

/** An icon slot of the button: the icon `div` and the icon. */
const IconSlot = defineComponent((props) => {
  const size = props.size;
  return h('div', {
    class: classes('ytlSpecButtonShapeNextIcon', {'ytlSpecButtonShapeNextElevatedContent': () => !props.disableElevation()},
        {'ytlSpecButtonShapeNextSecondaryIcon': props.secondary}),
    'aria-hidden': 'true',
    style: styles({width: () => (size() !== 24 ? `${size()}px` : ''), height: () => (size() !== 24 ? `${size()}px` : '')}),
  },
  props.custom ? props.custom() : cond(() => !!props.icon(), () => cond(props.animate, () => h(Icon, {icon: props.icon, size, animated: true}),
      () => h(Icon, {icon: props.icon, size}))));
}, 'IconSlot');

/**
 * The text of the button (`zZh`): animated, formatted, icon-with-label or
 * plain text.
 * @param {!Object<string, function(): *>} f
 * @param {!Object<string, function(): *>} d
 * @return {!Object}
 */
function buttonText(f, d) {
  return h(Switch, {
    value: () => (f.animatedTextProps() ? 'animated' : f.formattedButtonText() ? 'formatted' : d.hasIconWithLabel() ? 'label' : 'plain'),
    cases: [
      ['animated', () => h('span', {class: 'ytlSpecButtonShapeNextAnimatedText'}, () => (f.animatedTextProps() || {}).text || '')],
      ['formatted', () => h(AttributedString, {text: f.formattedButtonText, className: 'ytlSpecButtonShapeNextButtonTextContent'})],
      ['label', () => h('span', {class: 'ytlSpecButtonShapeNextIconLabel'}, () => f.buttonText())],
      ['plain', () => () => f.buttonText()],
    ],
  });
}

/** A pass-through wrapper (`tFQ`). */
const PassThrough = defineComponent((props) => props.children, 'tFQ');

/**
 * The button content (`HEh`): the six named `cond`s and the middleground
 * asset.
 */
const ButtonContent = defineComponent((props) => {
  const f = props.fields();
  const d = props.derived();
  const hasText = () => !!(f.buttonText() || f.formattedButtonText() || f.animatedTextProps());
  return [
    cond(() => (d.customIcon ? d.hasIconLeading() || d.hasIconLeadingTrailing() || d.iconButton() :
      !!d.iconToRender() && !d.hasIconTrailing()), () => h(IconSlot, {
      data: props.data, icon: d.iconToRender, custom: d.customIcon, size: d.iconSize, animate: props.animateIcon, secondary: false,
      disableElevation: f.disableBackdropFilter,
    }), undefined, 'leadingIcon'),
    cond(hasText, () => h('div', {
      class: classes('ytlSpecButtonShapeNextButtonTextContent', {'ytlSpecButtonShapeNextDisableTextEllipsis': f.disableTextEllipsis},
          {'ytlSpecButtonShapeNextCustomTextWrap': f.oneOffCustomTextWrap}),
    }, buttonText(f, d)), undefined, 'text'),
    cond(d.hasIconTrailing, () => h(IconSlot, {
      data: props.data, icon: d.iconToRender, custom: d.customIcon, size: d.iconSize, animate: props.animateIcon, secondary: false,
      disableElevation: f.disableBackdropFilter,
    }), undefined, 'trailingIcon'),
    cond(() => !!d.secondaryIconToRender(), () => h(IconSlot, {
      data: props.data, icon: d.secondaryIconToRender, size: d.iconSize, animate: false, secondary: true,
      disableElevation: f.disableBackdropFilter,
    }), undefined, 'secondaryIcon'),
    cond(() => !f.disabled() || f.toggleable(), () => h(PassThrough, null,
      cond(() => d.type() === 'filled' || f.style() === 'overlay' || f.style() === 'overlay-dark',
          () => h(TouchFeedbackShape, {response: 'invert'}), () => h(TouchFeedbackShape, {response: 'normal'}))),
    undefined, 'touchFeedback'),
    renderers(() => (f.middlegroundAsset() ? [f.middlegroundAsset()] : []), {}, MiddlegroundFallback),
    cond(() => props.staticLight() && !f.disableLightShape(), () => h(LightShape, {
      variant: () => (d.type() === 'tonal' ? 'Tonal' : 'Outline'),
    }), undefined, 'lightShape'),
  ];
}, 'HEh');

/** An unknown middleground asset renders nothing. */
const MiddlegroundFallback = defineComponent((props) => null, 'Fne');

/** The `button` or `a` element of a button shape. */
const ButtonElement = defineComponent((props) => {
  const f = props.fields();
  const d = props.derived();
  const [hovered, setHovered] = signal(false, 'gR9IIe');
  const tag = unwrap(props.tag);
  const tooltip = props.tooltips() ? useTooltip(f.tooltipText) : null;
  const link = tag === 'a' ? f.aTagConfig() || {} : null;
  const onClick = (/** !Event */ e) => {
    const handler = props.handler();
    if (f.toggleable() && f.onToggle()) f.onToggle()(!f.toggled());
    if (typeof handler === 'function') handler(e);
  };
  const attrs = {
    class: props.className,
    style: props.style,
    title: () => f.tooltipText() || f.accessibilityLabel() || undefined,
    'aria-label': () => f.accessibilityLabel() || undefined,
    'aria-disabled': () => (f.disabled() ? 'true' : 'false'),
    'aria-pressed': () => (f.toggleable() ? String(!!f.toggled()) : undefined),
    'aria-expanded': () => f.ariaExpanded(),
    'aria-haspopup': () => f.ariaHasPopup(),
    'aria-describedby': () => f.ariaDescribedby(),
    'aria-hidden': () => f.ariaHidden(),
    tabindex: () => f.tabIndex(),
    disabled: () => (tag === 'button' && d.visiblyDisabled()) || undefined,
    'on:click': onClick,
  };
  if (f.onHover()) {
    attrs['on:mouseenter'] = () => {
      setHovered(true);
      const hover = f.onHover();
      if (typeof hover === 'function') hover();
    };
    attrs['data-hovered'] = () => (hovered() ? 'true' : undefined);
  }
  if (link) {
    attrs['href'] = link.href;
    attrs['rel'] = link.rel;
    attrs['target'] = link.target;
  }
  if (tooltip) attrs['ref'] = tooltip;
  return h(tag, attrs, h(ButtonContent, {
    data: props.data, fields: f, derived: d, animateIcon: props.animateIcon, staticLight: props.staticLight,
  }));
}, 'ButtonElement');

/**
 * The button shape (`_.YB`).
 */
export const ButtonShape = defineComponent((props) => {
  const experiments = readFlags(BUTTON_FLAGS);
  const f = shapeFields(props.data);
  const d = derivedFields(props);
  /** @type {!DarkTheme} */ (rootInjector.resolve(DarkTheme));
  const rateLimit = computed(() => Number(f.onClickRateLimitMs()) || 0, undefined, 'YOhY7d');
  const handler = computed(() => rateLimited(f.onTap(), rateLimit()), undefined, 'PBBZUc');
  const staticLight = computed(() => !f.disableStaticLight() && (d.type() === 'outline' || d.type() === 'tonal') &&
      flag('web_modern_buttons_static_light', true), undefined, 'VcYSsb');
  const className = classes('ytlSpecButtonShapeNextHost', () => shapeTypeClass(d.type()), () => shapeStyleClass(f.style()),
      () => shapeSizeClass(f.size()), {
        'ytlSpecButtonShapeNextIconOnlyDefault': () => d.hasIconOnly() && !d.iconButton(),
        'ytlSpecButtonShapeNextIconButton': d.iconButton,
        'ytlSpecButtonShapeNextIconLeading': d.hasIconLeading,
        'ytlSpecButtonShapeNextIconTrailing': d.hasIconTrailing,
        'ytlSpecButtonShapeNextIconLeadingTrailing': d.hasIconLeadingTrailing,
        'ytlSpecButtonShapeNextIconWithLabel': d.hasIconWithLabel,
        'ytlSpecButtonShapeNextFocused': d.shouldFocus,
        'ytlSpecButtonShapeNextDisabled': d.visiblyDisabled,
        'ytlSpecButtonShapeNextAlignByText': f.alignByText,
        'ytlSpecButtonShapeNextSegmentedStart': () => f.segmentedPosition() === 'start',
        'ytlSpecButtonShapeNextSegmentedEnd': () => f.segmentedPosition() === 'end',
        'ytlSpecButtonShapeNextToggled': () => f.toggleable() && f.toggled() && !experiments['web_animated_like'],
        'ytlSpecButtonShapeNextOverrideSmallSizeIcon': d.overrideSmallSizeIcon,
        'ytlSpecButtonShapeNextEnableBackdropFilterExperiment': () => !f.disableBackdropFilter() && !flag('web_disable_backdrop_filter'),
        'ytlSpecButtonShapeNextMainstageIconSize': () => flag('web_button_icon_size_experiment'),
        'ytlSpecButtonShapeNextMainstagePadding': () => flag('web_button_mainstage_padding'),
      });
  const style = styles({
    'color': () => customColor(f.customColors(), 'textColor'),
    'background-color': () => customColor(f.customColors(), 'backgroundColor'),
    'border-color': () => customColor(f.customColors(), 'borderColor'),
  });
  const inner = (tag) => h(ButtonElement, {
    data: props.data, fields: f, derived: d, tag, handler, className, style, staticLight,
    animateIcon: () => !!unwrap(props.animateIcon), tooltips: () => !!unwrap(props.clientOnlyWizTooltipsEnabled),
  });
  const element = () => cond(() => !!f.aTagConfig(), () => inner('a'), () => inner('button'));
  return cond(f.alignByText, () => h('div', {class: 'ytlSpecButtonShapeNextAlignByTextWrapper'}, element()), element);
}, 'YB');

/**
 * The button-shape CoW host: a focus signal, focus listeners on the host,
 * and a `cond` on `data`.
 */
const ButtonShapeHost = defineComponent((props) => {
  const [focused, setFocused] = signal(false, 'xPqod');
  const ref = {
    onRender: (/** !Element */ el) => {
      const onIn = () => setFocused(true);
      const onOut = () => setFocused(false);
      el.addEventListener('focusin', onIn);
      el.addEventListener('focusout', onOut);
      onCleanup(() => {
        el.removeEventListener('focusin', onIn);
        el.removeEventListener('focusout', onOut);
      });
    },
  };
  const data = () => {
    const d = props.data();
    return d && focused() !== !!d.focused ? Object.assign({}, d, {focused: focused()}) : d;
  };
  return h('ytl-button-shape', {id: props.id, class: props.className, ref},
    cond(() => !!props.data(), () => h(ButtonShape, {
      data, iconName: props.iconName, animateIcon: props.animateIcon, secondaryIconName: props.secondaryIconName,
      clientOnlyWizTooltipsEnabled: props.clientOnlyWizTooltipsEnabled,
    })));
}, 'ytl-button-shape (CoW)');

defineCoW('ytl-button-shape', ButtonShapeHost, {props: {
  data: PropKind.SIGNAL, id: PropKind.SIGNAL, className: PropKind.SIGNAL, iconName: PropKind.SIGNAL,
  animateIcon: PropKind.SIGNAL, secondaryIconName: PropKind.SIGNAL, clientOnlyWizTooltipsEnabled: PropKind.SIGNAL,
}});

/**
 * An `<a>` config for a tap command (`AUY`), when it has a URL.
 * @param {*} command
 * @return {?Object}
 */
export function anchorConfig(command) {
  if (!command) return null;
  const link = linkConfig(command);
  return link.href ? link : null;
}
