/**
 * @fileoverview The disposal tree of the view-model runtime. An owner is a
 * plain object whose disposables (child owners, effects and cleanup
 * records) form a singly linked list. Owners come from render roots, from
 * each `cond`/`switch` evaluation and from each `each` item (not linked
 * into the parent's list); components and elements have none of their own. Effects are owners of what they create while
 * they run.
 */
import {setActiveConsumer} from '../signals.js';
import {noteBreakdown, vmCounters} from './counters.js';

/**
 * @typedef {{
 *   parent: ?Object,
 *   isDisposed: boolean,
 *   childDisposable: ?Object,
 *   tailDisposable: ?Object,
 *   nextDisposable: ?Object,
 * }}
 */
export let Owner;

/** @type {?Object} */
let currentOwner = null;

/**
 * A component-stack frame.
 * @typedef {{name: string, isReactive: boolean, parent: ?Object}}
 */
export let Frame;

/** @type {?Frame} */
let currentFrame = null;

/** @return {?Frame} */
export function getFrame() {
  return currentFrame;
}

/**
 * @param {?Frame} frame
 * @return {?Frame} The previous frame.
 */
export function setFrame(frame) {
  const prev = currentFrame;
  currentFrame = frame;
  return prev;
}

/**
 * @param {?Object} parent
 * @return {!Owner}
 */
export function createOwner(parent) {
  const owner = {parent, isDisposed: false, childDisposable: null, tailDisposable: null, nextDisposable: null};
  vmCounters.owners++;
  noteBreakdown('owners', currentFrame);
  if (parent) appendDisposable(parent, owner);
  return owner;
}

/**
 * An owner whose parent is set but which is not in the parent's list
 * (`sC` with `false`), as each `each` item has. Its creator disposes it.
 * @param {?Object} parent
 * @return {!Owner}
 */
export function createDetachedOwner(parent) {
  vmCounters.owners++;
  noteBreakdown('owners', currentFrame);
  return {parent, isDisposed: false, childDisposable: null, tailDisposable: null, nextDisposable: null};
}

/**
 * A root owner of a PolySi signal proxy or host render, counted apart from
 * the view-model owners.
 * @return {!Owner}
 */
export function createPolySiOwner() {
  vmCounters.polysiOwners++;
  return {parent: null, isDisposed: false, childDisposable: null, tailDisposable: null, nextDisposable: null};
}

/**
 * @param {!Object} owner
 * @param {!Object} disposable
 */
export function appendDisposable(owner, disposable) {
  const tail = owner.tailDisposable;
  if (tail) tail.nextDisposable = disposable;
  else owner.childDisposable = disposable;
  owner.tailDisposable = disposable;
}

/** @param {!Object} owner */
export function disposeChildren(owner) {
  let d = owner.childDisposable;
  owner.childDisposable = null;
  owner.tailDisposable = null;
  while (d) {
    const next = d.nextDisposable;
    d.nextDisposable = null;
    if (d.dispose) d.dispose();
    else disposeOwner(d);
    d = next;
  }
}

/** @param {!Object} owner */
export function disposeOwner(owner) {
  if (owner.isDisposed) return;
  owner.isDisposed = true;
  disposeChildren(owner);
}

/** @return {?Object} */
export function getOwner() {
  return currentOwner;
}

/**
 * @param {?Object} owner
 * @return {?Object} The previous owner.
 */
export function setOwner(owner) {
  const prev = currentOwner;
  currentOwner = owner;
  return prev;
}

/**
 * @template T
 * @param {?Object} owner
 * @param {function(): T} fn
 * @return {T}
 */
export function runWithOwner(owner, fn) {
  const prev = currentOwner;
  currentOwner = owner;
  try {
    return fn();
  } finally {
    currentOwner = prev;
  }
}

/**
 * Appends a cleanup record to the current owner. The cleanup runs with
 * signal writes allowed and reports its errors.
 * @param {function()} fn
 */
export function onCleanup(fn) {
  const owner = currentOwner;
  if (!owner) return;
  vmCounters.cleanups++;
  noteBreakdown('cleanups', currentFrame);
  appendDisposable(owner, {dispose: () => runCleanup(fn), nextDisposable: null});
}

/** @param {function()} fn */
function runCleanup(fn) {
  const prev = setActiveConsumer(null);
  try {
    fn();
  } catch (e) {
    console.error('cleanup failed', e);
  } finally {
    setActiveConsumer(prev);
  }
}
