/**
 * @fileoverview Stamps renderer elements for InnerTube item lists. Each
 * item `{someRenderer: data}` becomes the element registered for
 * `someRenderer`, with `data` assigned. Existing children whose `is` is
 * the tag are reused in place, as when a list is re-rendered with new data;
 * view-model hosts have no `is`, so they are always recreated. The
 * container's children are managed through Polymer's DOM API; new
 * elements get their data after they are inserted.
 */
import {dom} from '@polymer/polymer/lib/legacy/polymer.dom.js';
import {rendererKeyOf, tagFor} from './registry.js';

/**
 * @param {!Element} container
 * @param {!Array<!Object>} items
 * @param {number=} start Index of the first child to (re)use; children
 *     before it are kept as they are, so appended pages keep earlier items.
 * @return {!Array<!Element>} The elements for `items`.
 */
export function stampRenderers(container, items, start = 0) {
  const parent = dom(container);
  const existing = Array.from(parent.children);
  const out = [];
  const deferred = [];
  let i = start;
  for (const item of items) {
    const key = rendererKeyOf(item);
    if (!key) continue;
    const tag = /** @type {string} */ (tagFor(key));
    let el = existing[i];
    if (!el || /** @type {?} */ (el).is !== tag) {
      const created = document.createElement(tag);
      parent.insertBefore(created, el || null);
      if (el) existing.splice(i, 0, created);
      el = created;
      deferred.push([el, item[key]]);
    } else {
      /** @type {?} */ (el).data = item[key];
    }
    out.push(el);
    i++;
  }
  for (let j = existing.length - 1; j >= i; j--) parent.removeChild(existing[j]);
  for (const [el, data] of deferred) /** @type {?} */ (el).data = data;
  return out;
}

/**
 * Removes all renderer children of `container`.
 * @param {!Element} container
 */
export function clearRenderers(container) {
  const parent = dom(container);
  let n;
  while ((n = parent.lastElementChild)) parent.removeChild(n);
}
