/**
 * @fileoverview The button view model (`_.Kp`) and the toggle, like and
 * dislike buttons built on it. The config thunk merges the button JSON and
 * the overrides into a button-shape config through the enum switches, the
 * theme-token colours, the accessibility label, the tap and hover
 * closures and the anchor config.
 */
import {classes} from '../../framework/vm/classes.js';
import {cond} from '../../framework/vm/control.js';
import {afterRenderEffect, runUntracked, signal, unwrap} from '../../framework/vm/effect.js';
import {h} from '../../framework/vm/jsx.js';
import {defineComponent} from '../../framework/vm/render.js';
import {flag} from '../../framework/flags.js';
import {fireCommand} from '../commands.js';
import {logClick} from '../logging.js';
import {buttonSizeOf, buttonStateOf, buttonStyleOf, buttonTypeOf, iconPositionOf, tooltipPlacementOf} from './enums.js';
import {ButtonShape, anchorConfig, buttonIconSize} from './button-shape.js';
import {DarkTheme, argbToCss, keyboardInUse} from './primitives.js';
import {rootInjector} from '../../framework/injector.js';
import {selectEntity} from '../store.js';
import {registerTarget, unregisterTarget} from '../targets.js';
import {INNERTUBE_COMMAND, SAMPLED_COLOR, TOOLTIP_VIEW_MODEL, innertubeOf, rendererField, useLayoutResolver, useSelector} from './hooks.js';
import {Image} from './image.js';

/** Button target ids that become classes of the host (`mRh`). */
const TARGET_ID_CLASSES = ['you-chat-entrypoint-button', 'ask-studio-conversation-more-history-button'];

/**
 * The entity state of a button with an entity selector: hidden or
 * disabled.
 * @param {!Object} state The store state.
 * @param {string|undefined} key
 * @param {string|undefined} selector
 * @return {?{isHidden: boolean, isDisabled: (boolean|undefined)}}
 */
function buttonEntityState(state, key, selector) {
  if (!key || !selector) return null;
  switch (selector) {
    case 'BUTTON_ENTITY_SELECTOR_TYPE_REMOVE_ADS_AD_STATE': {
      const ads = selectEntity(state.entities, 'adsStateEntity', key);
      return ads ? {isHidden: ads.adsState === 'ADS_STATE_NONE' || ads.adsState === 'ADS_STATE_UNKNOWN'} : {isHidden: true};
    }
    case 'BUTTON_ENTITY_SELECTOR_TYPE_CHATBOT_PENDING_RESPONSE': {
      const pending = selectEntity(state.entities, 'youchatPendingResponseEntity', key);
      return {isHidden: false, isDisabled: !!(pending && pending.isPendingResponse)};
    }
    case 'BUTTON_ENTITY_SELECTOR_TYPE_BOOLEAN_DISABLED': {
      const b = selectEntity(state.entities, 'booleanEntity', key);
      return {isHidden: false, isDisabled: !!(b && b.value)};
    }
    default:
      return null;
  }
}

/**
 * A theme colour of a button (`R_x`): the sampled colour token for the
 * theme, else the raw colour for the theme, as CSS.
 * @param {*} token
 * @param {boolean} dark
 * @param {number|undefined} raw
 * @param {number|undefined=} rawDark
 * @return {string|undefined}
 */
function buttonThemeColor(token, dark, raw, rawDark) {
  const sampled = /** @type {?Object} */ (rendererField(token, SAMPLED_COLOR));
  const value = dark ? (sampled && sampled.darkTheme != null ? sampled.darkTheme : sampled && sampled.lightTheme) : sampled && sampled.lightTheme;
  const chosen = value != null ? value : dark ? (rawDark != null ? rawDark : raw) : raw;
  return chosen ? argbToCss(chosen) : undefined;
}

/**
 * The tooltip shape of a tooltip view model.
 * @param {!Object} tooltip
 * @return {!Object}
 */
function tooltipShapeOf(tooltip) {
  return {text: tooltip.tooltipText || '', location: tooltipPlacementOf(tooltip.placement), style: tooltip.style, hotkey: tooltip.hotkey};
}

/**
 * The visual element a click is logged against when the button has a
 * client VE spec but no tracking params of its own.
 * @param {!Object} vm
 * @param {?Object} command
 * @param {*} ve
 * @return {*}
 */
function clickedVisualElement(vm, command, ve) {
  const params = command && command.clickTrackingParams;
  const uiType = vm.loggingDirectives && vm.loggingDirectives.clientVeSpec && vm.loggingDirectives.clientVeSpec.uiType;
  if (ve && uiType && !params) return ve;
  return undefined;
}

/**
 * Runs a button command with the click's form data.
 * @param {!Object} command
 * @param {?Element} element
 * @param {!Event} event
 * @param {!Object=} extra
 */
function runButtonCommand(command, element, event, extra) {
  logClick(command.clickTrackingParams || '');
  fireCommand(element || /** @type {!Element} */ (event.currentTarget), command);
  if (extra && extra.clickedVisualElement) logClick(String(extra.clickedVisualElement));
}

/**
 * The tap handler of a button (`Xaj`).
 * @param {!Object} vm
 * @param {{value: ?Element}} host
 * @param {boolean} disabled
 * @param {*} onClick
 * @param {?Element} target
 * @return {function(!Event)}
 */
function tapHandler(vm, host, disabled, onClick, target) {
  let el;
  return (e) => {
    const command = innertubeOf(disabled ? vm.onDisabledTap : vm.onTap);
    if (command) {
      el = el || host.value;
      if (flag('web_button_vm_click_client_ve_killswitch')) {
        runButtonCommand(command, el, e);
      } else {
        const ve = clickedVisualElement(vm, command, el);
        runButtonCommand(command, target || el, e, {clickedVisualElement: ve});
      }
    }
    if (typeof onClick === 'function') onClick(e);
  };
}

/**
 * The hover handler of a button (`DVy`).
 * @param {!Object} vm
 * @param {{value: ?Element}} host
 * @param {?Element} target
 * @return {function(!Event)}
 */
function hoverHandler(vm, host, target) {
  return (e) => {
    const command = innertubeOf(vm.onHover);
    if (command) runButtonCommand(command, target || host.value, e);
  };
}

/**
 * The `<a>` config of a button whose tap command has a URL (`AUY`).
 * @param {!Object} vm
 * @param {{value: ?Element}} host
 * @param {*} onClick
 * @return {?Object}
 */
function buttonAnchorConfig(vm, host, onClick) {
  const command = innertubeOf(vm.onTap);
  const link = anchorConfig(command);
  if (!link) return null;
  return Object.assign({}, link, {forceNewState: true,
    getClickedVisualElement: () => clickedVisualElement(vm, command, host.value), onclick: onClick || undefined});
}

/**
 * The button-shape config of a button view model (`P`).
 * @param {?Object} vm
 * @param {!Object} c Overrides, entity state and handlers.
 * @return {!Object}
 */
export function buttonViewModelConfig(vm, c) {
  const overrides = c.overrides || null;
  const entity = c.entity;
  const entityOverrides = c.entityOverrides;
  let merged = overrides;
  if (vm && vm.buttonEntitySelectorType) merged = Object.assign({}, overrides, {disabled: !!(entity && entity.isDisabled) || !!(overrides && overrides.disabled)});
  const animated = c.animatedTextProps;
  const blocked = (entityOverrides && entityOverrides.ariaDisabled) || (entity && entity.isDisabled) ||
      (entityOverrides && entityOverrides.ariaBusy) || (merged && merged.disabled);
  const onClick = blocked ? undefined : c.onClick;
  let config;
  if (vm) {
    let type = buttonTypeOf(vm.type);
    const position = iconPositionOf(vm);
    if (position === 'icon-only-40') type = 'text';
    const state = merged && merged.state !== undefined ? merged.state : buttonStateOf(vm.state);
    let disabled = merged && merged.disabled !== undefined ? merged.disabled :
      vm.state === 'BUTTON_VIEW_MODEL_STATE_DISABLED' || vm.state === 'BUTTON_VIEW_MODEL_STATE_INACTIVE';
    if (flag('web_button_vm_refactor_disabled')) disabled = merged && merged.disabled !== undefined ? merged.disabled : state === 'disabled';
    const tooltip = /** @type {?Object} */ (rendererField(vm.tooltipData, TOOLTIP_VIEW_MODEL));
    const disabledTooltip = /** @type {?Object} */ (rendererField(vm.disabledTooltipData, TOOLTIP_VIEW_MODEL));
    config = Object.assign({}, {
      buttonText: vm.title,
      formattedButtonText: vm.titleFormatted,
      animatedTextProps: animated && animated.numberText && !isNaN(Number(animated.numberValue)) ? animated : undefined,
      accessibilityLabel: disabled && vm.disabledAccessibilityText ? vm.disabledAccessibilityText : vm.accessibilityText,
      style: buttonStyleOf(vm.style),
      type,
      state,
      size: buttonSizeOf(vm.buttonSize),
      iconPosition: position,
      onTap: tapHandler(vm, c.host, disabled, onClick, c.target),
      disabled: disabled && !vm.onDisabledTap,
      aTagConfig: buttonAnchorConfig(vm, c.host, onClick),
      customColors: {
        color: buttonThemeColor(vm.customFontColorToken, c.dark, vm.customFontColor, vm.customDarkThemeFontColor),
        backgroundColor: buttonThemeColor(vm.customBackgroundColorToken, c.dark, vm.customBackgroundColor, vm.customDarkThemeBackgroundColor),
        borderColor: buttonThemeColor(vm.customBorderColorToken, c.dark, vm.customBorderColor, vm.customDarkThemeBorderColor),
        washLightColor: buttonThemeColor(vm.customWashColor, c.dark),
        rimLightColor: buttonThemeColor(vm.customRimColor, c.dark),
      },
      tooltipText: vm.tooltip,
      tooltipShape: disabled && disabledTooltip ? tooltipShapeOf(disabledTooltip) : tooltip ? tooltipShapeOf(tooltip) : undefined,
      onHover: hoverHandler(vm, c.host, c.target),
      middlegroundAsset: vm.middlegroundAsset,
      iconAsset: vm.leadingAsset,
    }, merged);
  } else {
    config = {style: 'mono', type: 'text', state: 'active', size: 'M'};
  }
  config.focused = c.focused;
  if (entityOverrides && entityOverrides.accessibilityLabel !== undefined) config.accessibilityLabel = entityOverrides.accessibilityLabel;
  if (entityOverrides && entityOverrides.customColors !== undefined) config.customColors = entityOverrides.customColors;
  if (entityOverrides && entityOverrides.iconAsset !== undefined) {
    config.iconAsset = entityOverrides.iconAsset;
    config.iconPosition = 'icon-only';
  } else if (entityOverrides && entityOverrides.iconName !== undefined) {
    config.iconAsset = undefined;
    config.iconPosition = 'icon-only';
  }
  if (entity && entity.formattedButtonText) {
    config.formattedButtonText = entity.formattedButtonText;
    if (config.iconPosition === 'icon-only') config.iconPosition = 'leading';
  }
  return config;
}

/** The button view model (`_.Kp`). */
export const ButtonViewModel = defineComponent((props) => {
  const vm = () => /** @type {?Object} */ (unwrap(props.data)) || null;
  const host = {value: null};
  const ref = {
    onRender: (/** !Element */ el) => {
      host.value = el;
      el.dispatchEvent(new CustomEvent('yt-renderidom-finished', {bubbles: true, cancelable: false, composed: true}));
      const target = vm() && vm().targetId;
      if (target) registerTarget(target, el);
    },
    onUnmount: (/** !Element */ el) => {
      const target = vm() && vm().targetId;
      if (target) unregisterTarget(target, el);
    },
  };
  const selected = useSelector((state) => {
    const v = vm();
    return buttonEntityState(state, v ? v.entityKey : undefined, v ? v.buttonEntitySelectorType : undefined);
  });
  const entity = () => {
    const v = vm();
    return v && v.entityKey && v.buttonEntitySelectorType ? selected() : null;
  };
  const entityOverrides = () => (flag('WebFEAllStudioByChannel__web_button_view_model_entity_overrides') ? entity() : null);
  const iconName = () => {
    const o = /** @type {?Object} */ (entityOverrides());
    if (o && o.iconName !== undefined) return o.iconName;
    if (o && o.iconAsset !== undefined) return undefined;
    const e = /** @type {?Object} */ (entity());
    const v = vm();
    return (e && e.iconName) || (v && v.iconName) || (v && v.ytIcon);
  };
  const theme = /** @type {!DarkTheme} */ (rootInjector.resolve(DarkTheme));
  const dark = theme.isDark();
  const [focused, setFocused] = signal(false, 'eZotDb');
  const config = () => buttonViewModelConfig(vm(), {
    overrides: unwrap(props.buttonOverrides || props.overrides) || null,
    entity: entity(),
    entityOverrides: entityOverrides(),
    animatedTextProps: unwrap(props.animatedTextProps),
    onClick: props.onClick || props.onTap,
    target: unwrap(props.target) || null,
    host,
    dark,
    focused: focused(),
  });
  const resolver = useLayoutResolver();
  const iconSize = () => {
    const c = config();
    return buttonIconSize(c, !!iconName() || !!c.iconAsset, resolver);
  };
  afterRenderEffect(() => {
    const command = vm() && rendererField(vm().onVisible, INNERTUBE_COMMAND);
    runUntracked(() => {
      if (command) fireCommand(document.body, /** @type {!Object} */ (command));
    });
  }, 'meIDRc');
  const iconImage = () => {
    const image = vm() && vm().iconImage;
    return image ? {sources: [image]} : undefined;
  };
  const secondaryIcon = () => h(Image, {data: () => (vm() && vm().secondaryIconImage) || {}, alt: '', targetWidth: iconSize,
    targetHeight: iconSize, preserveWidth: true, preserveHeight: true});
  const popover = HTMLElement.prototype.hasOwnProperty('popover');
  return h('ytl-button-view-model', {
    ref,
    class: classes('ytlSpecButtonViewModelHost', () => unwrap(props.className || props.extraClass) || '', () => {
      const target = vm() && vm().targetId;
      return target && TARGET_ID_CLASSES.includes(target) ? target : undefined;
    }),
    'on:focusin': () => setFocused(keyboardInUse()),
    'on:focusout': () => setFocused(false),
    'aria-disabled': () => {
      const o = /** @type {?Object} */ (entityOverrides());
      return o && o.ariaDisabled ? 'true' : undefined;
    },
    'aria-busy': () => {
      const o = /** @type {?Object} */ (entityOverrides());
      return o && o.ariaBusy ? 'true' : undefined;
    },
  },
  cond(() => !(entity() && entity().isHidden), () => cond(iconImage,
    () => h(ButtonShape, {data: config, icon: () => h(Image, {data: iconImage, alt: '', targetWidth: iconSize, targetHeight: iconSize,
      preserveWidth: true, preserveHeight: true}), secondaryIcon, clientOnlyWizTooltipsEnabled: popover}),
    () => h(ButtonShape, {data: config, iconName, animateIcon: () => {
      const o = unwrap(props.buttonOverrides || props.overrides);
      return !!(o && o.animateIcon);
    }, secondaryIcon, clientOnlyWizTooltipsEnabled: popover}))));
}, 'button-view-model');

/** A toggle button: a toggled signal that switches between two buttons. */
export const ToggleButtonViewModel = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const [isToggled, setToggled] = signal(!!(unwrap(props.toggled) || vm().isToggled), 'toggled');
  const def = () => vm().defaultButtonViewModel && vm().defaultButtonViewModel.buttonViewModel;
  const toggled = () => vm().toggledButtonViewModel && vm().toggledButtonViewModel.buttonViewModel;
  const onTap = () => {
    const next = !isToggled();
    setToggled(next);
    if (props.onToggle) props.onToggle(next);
  };
  return h('ytl-toggle-button-view-model', null,
    cond(isToggled, () => h(ButtonViewModel, {data: () => toggled() || def(), onTap}),
      () => h(ButtonViewModel, {data: () => def() || toggled(), onTap})));
}, 'toggle-button-view-model');

/** The like or dislike button of a video summary. */
export const LikeButtonViewModel = defineComponent((props) => {
  const vm = () => unwrap(props.data) || {};
  const kind = unwrap(props.kind);
  const inner = () => vm().toggleButtonViewModel && vm().toggleButtonViewModel.toggleButtonViewModel;
  const status = () => (vm().likeStatusEntity ? vm().likeStatusEntity.likeStatus : 'INDIFFERENT');
  const toggledInit = kind === 'dislike' ? status() === 'DISLIKE' : status() === 'LIKE';
  const host = kind === 'dislike' ? 'ytl-dislike-button-view-model' : 'ytl-like-button-view-model';
  return h(host, {class: kind === 'dislike' ? 'ytlDislikeButtonViewModelHost' : 'ytlLikeButtonViewModelHost',
    'data-state': () => `${kind}-${toggledInit ? 'on' : 'off'}`},
  h(ToggleButtonViewModel, {data: inner, toggled: toggledInit, onToggle: props.onToggle}));
}, 'like-button-view-model');
