/**
 * @fileoverview The lazy list of renderer containers. It keeps
 * `shownItems` in sync with the items at `getItemsPath()` (by default
 * `data.items`): it shows the first `initialCount` items at once, then
 * adds chunks in scheduler jobs, sizing each chunk so that it takes about
 * 1000 / `targetFramerate` ms. The renderer stamper (`renderer-stamper.js`)
 * turns `shownItems` into elements.
 *
 * The list observes `<itemsPath>.*`: through a reactive schema added in
 * `beforeRegister` on signal-schema elements, and through an observer
 * declaration otherwise.
 */
import {Priority, cancel, schedule} from './scheduler.js';

/** @polymerBehavior */
export const LazyListBehavior = {
  properties: {
    initialCount: {type: Number, value: 4},
    targetFramerate: {type: Number, value: 20},
    minChunkSize: {type: Number, value: 1},
    autoFill: {type: Boolean, value: false},
    disableAutoFill: {type: Boolean, value: false},
    shownItems: Array,
    shownCount: {type: Number, value: 0},
    canShowMore: {type: Boolean, reflectToAttribute: true, notify: true, observer: 'onCanShowMoreUpdated_'},
    renderDelay: Number,
    targetFrameTime_: {type: Number, computed: 'computeFrameTime_(targetFramerate)'},
    canScheduleJobs: {type: Boolean, value: true, observer: 'canScheduleJobsChanged_'},
  },

  /**
   * Adds the items observer to a legacy element's declarations.
   * @param {!Object} info
   * @param {!Array<!Object>} behaviors
   * @param {boolean} signal
   */
  registerDeclarations_(info, behaviors, signal) {
    if (signal) return;
    const path = info.getItemsPath ? info.getItemsPath() : itemsPathOf(behaviors);
    info.observers.push(`deepLazyListObserver_(${path}.*)`);
  },

  beforeRegister() {
    if (!this.useSignals) return;
    this.addReactiveSchema({type: 'observe', propertyKey: '', method: {methodName: 'deepLazyListObserver_',
      args: [{type: 'wildcard', path: itemsPathOfElement(this), value: undefined}]}});
  },

  created() {
    this.boundRenderChunk_ = this.renderChunk_.bind(this);
    this.items_ = null;
    this.lazyListRenderJobId_ = this.chunkCount_ = this.lastChunkTime_ = this.length_ = 0;
    this.nonDeferredItemCount = -1;
    this.renderElementsOutsideVisibleArea_ = null;
    this.partiallyRenderedItems_ = new WeakSet();
  },

  /** Shows all remaining items at once. */
  fillRemainingListItems() {
    this.fillRange_(this.shownCount, this.length_);
  },

  /** Runs the deferred rendering of items outside the visible area. */
  renderDeferredElements() {
    const deferred = this.renderElementsOutsideVisibleArea_;
    if (deferred) {
      this.renderElementsOutsideVisibleArea_ = null;
      deferred();
    }
  },

  /**
   * @param {number} framerate
   * @return {number}
   */
  computeFrameTime_(framerate) {
    return Math.ceil(1000 / framerate);
  },

  /** @param {boolean} canShowMore */
  onCanShowMoreUpdated_(canShowMore) {
    if (!this.data || !this.items_) return;
    if (canShowMore) this.partiallyRenderedItems_.add(this.items_);
    else this.partiallyRenderedItems_.delete(this.items_);
  },

  /** @param {boolean} canScheduleJobs */
  canScheduleJobsChanged_(canScheduleJobs) {
    if (this.shouldUseTaskManager && this.shouldUseTaskManager()) return;
    if (canScheduleJobs && this.lazyListRenderJobId_ === -1) this.requestRenderChunk_();
  },

  /** @param {{path: string, value: *}} change */
  deepLazyListObserver_(change) {
    const itemsPath = itemsPathOfElement(this);
    if (change.path === itemsPath) {
      this.setInitialItemsOnDataChanged();
    } else if (change.path === `${itemsPath}.splices`) {
      this.onItemsUpdated_(/** @type {{indexSplices: !Array<!Object>}} */ (change.value).indexSplices);
    } else if (change.path === `${itemsPath}.length`) {
      // Covered by the splices record.
    } else {
      this.updateChangeRecord_(change.path.slice(itemsPath.length + 1), change.value);
    }
  },

  setInitialItemsOnDataChanged() {
    this.cancelPendingTasks_();
    const items = itemsOf(this);
    this.items_ = items;
    this.length_ = items.length;
    const first = items.slice(0, this.initialCount);
    this.shownItems = first;
    this.shownCount = first.length;
    this.canShowMore = items.length > first.length;
    this.chunkCount_ = this.minChunkSize;
    if (this.autoFill && !this.disableAutoFill) this.tryRenderChunk_();
  },

  /** @param {!Array<!Object>} splices */
  onItemsUpdated_(splices) {
    const items = itemsOf(this);
    this.items_ = items;
    this.length_ = items.length;
    for (const splice of splices) {
      const index = /** @type {number} */ (splice.index);
      if (index > shownOf(this).length) continue;
      const removed = /** @type {!Array} */ (splice.removed).length;
      const added = /** @type {number} */ (splice.addedCount);
      const visibleAdded = Math.min(added, Math.max(0, this.initialCount - (index - shownOf(this).length)));
      const toAdd = items.slice(index, index + visibleAdded);
      this.splice('shownItems', index, removed, ...toAdd);
    }
    this.shownCount = shownOf(this).length;
    this.canShowMore = this.shownCount < this.length_;
    if (this.autoFill && !this.disableAutoFill) this.tryRenderChunk_();
  },

  /**
   * Forwards a change inside the items to `shownItems`.
   * @param {string} rest The path below the items.
   * @param {*} value
   */
  updateChangeRecord_(rest, value) {
    if (this.useSignals && rest === 'length') return;
    const m = /^(\d+)(\..*)?$/.exec(rest);
    if (!m) return;
    const i = Number(m[1]);
    if (i < shownOf(this).length) this.notifyPath(`shownItems.${i}${m[2] || ''}`, value);
  },

  /**
   * @param {number} start
   * @param {number} end
   */
  fillRange_(start, end) {
    if (end <= start || !this.items_) return;
    this.push('shownItems', ...itemsOf(this).slice(start, end));
    this.shownCount = shownOf(this).length;
    this.canShowMore = this.shownCount < this.length_;
  },

  tryRenderChunk_() {
    if (this.canShowMore) this.requestRenderChunk_();
  },

  /** @return {boolean} Whether a chunk is scheduled. */
  requestRenderChunk_() {
    if (this.lazyListRenderJobId_ > 0) return true;
    if (!this.canScheduleJobs) {
      this.lazyListRenderJobId_ = -1;
      return false;
    }
    this.lastChunkTime_ = performance.now();
    this.lazyListRenderJobId_ = schedule(this.boundRenderChunk_, Priority.RENDER);
    return true;
  },

  cancelPendingTasks_() {
    if (this.lazyListRenderJobId_ > 0) cancel(this.lazyListRenderJobId_);
    this.lazyListRenderJobId_ = 0;
    this.renderElementsOutsideVisibleArea_ = null;
  },

  renderChunk_() {
    this.lazyListRenderJobId_ = 0;
    const now = performance.now();
    const elapsed = now - this.lastChunkTime_;
    const target = this.targetFrameTime_;
    if (elapsed > 0) this.chunkCount_ = Math.round(target / elapsed * this.chunkCount_) || 1;
    this.chunkCount_ = Math.max(this.minChunkSize, this.chunkCount_);
    const start = shownOf(this).length;
    this.fillRange_(start, Math.min(this.length_, start + this.chunkCount_));
    if (!this.canShowMore) this.fire('yt-lazy-list-rendered', {count: this.shownCount}, {bubbles: false});
    else if (this.autoFill && !this.disableAutoFill) this.tryRenderChunk_();
  },
};

/**
 * The path of the items: the element's `getItemsPath()`, its `itemsPath`
 * field, or `data.items`.
 * @param {!Object} self
 * @return {string}
 */
export function itemsPathOfElement(self) {
  if (typeof self.getItemsPath === 'function') return self.getItemsPath();
  return self.itemsPath || 'data.items';
}

/**
 * @param {!Object} self
 * @return {!Array<!Object>}
 */
function itemsOf(self) {
  return /** @type {?Array<!Object>} */ (self.get(itemsPathOfElement(self))) || [];
}

/**
 * @param {!Object} self
 * @return {!Array<!Object>}
 */
function shownOf(self) {
  return /** @type {?Array<!Object>} */ (self.shownItems) || [];
}

/**
 * The items path that a behaviour of the element declares.
 * @param {!Array<!Object>} behaviors
 * @return {string}
 */
function itemsPathOf(behaviors) {
  for (let i = behaviors.length - 1; i >= 0; i--) {
    if (behaviors[i].getItemsPath && behaviors[i] !== LazyListBehavior) return behaviors[i].getItemsPath();
  }
  return 'data.items';
}
