/**
 * @fileoverview The app element: routes `yt-action` events to handlers,
 * runs navigations (`yt-navigate` → fetch → `yt-page-data-fetched`), and
 * hosts the page manager.
 */
import {Polymer} from '../../framework/polysi/register.js';
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {endpointKind, endpointUrl, webPageType} from '../../framework/endpoints.js';
import {innertubeContext, innertubeFetch} from '../network.js';
import {handleResponse, handleWatchResponse, resolveCommand} from '../response.js';
import {newScreen} from '../logging.js';
import {markScreenCreated, markWarmLoad, navigationFinished, navigationStarted, networkRequestFinished, networkRequestStarted, startLatencyAction} from '../telemetry.js';
import {routeAction} from '../item-behaviors.js';
import {makeGuideData} from './shell.js';
import {Priority, cancel, schedule} from '../scheduler.js';
import {appStore} from '../store.js';
import {styleSubtree} from './browse.js';
import {template as appTemplate} from '../../../gen/templates/ytl-app.js';

/**
 * Maps action names to handler lists. Handlers get the app element, the
 * element that fired the action, and the action's arguments.
 */
class ActionRouter {
  constructor() {
    /** @private @const {!Map<string, !Array<function(!Element, !Element, !Array<*>)>>} */
    this.handlers_ = new Map();
    /** @type {number} */
    this.handled = 0;
  }

  /**
   * @param {string} name
   * @param {function(!Element, !Element, !Array<*>)} handler
   */
  register(name, handler) {
    let list = this.handlers_.get(name);
    if (!list) {
      list = [];
      this.handlers_.set(name, list);
    }
    list.push(handler);
  }

  /**
   * @param {!Element} app
   * @param {!Element} source
   * @param {{actionName: string, args: !Array<*>}} action
   * @return {boolean}
   */
  handleAction(app, source, action) {
    const list = this.handlers_.get(action.actionName);
    if (!list) return false;
    for (const handler of list) handler(app, source, action.args || []);
    this.handled++;
    return true;
  }
}

const router = new ActionRouter();

/**
 * Counts page dispose jobs for `tools/verify.mjs`: queued, run by their
 * frame, run by the flush that starts the response handling.
 * @param {string} key
 */
function countDisposeJob(key) {
  const counts = window['ytlDispose'] || (window['ytlDispose'] = {queued: 0, frame: 0, flushed: 0});
  counts[key]++;
}

router.register('yt-command', (app, source, [command]) => {
  resolveCommand(source, /** @type {?Object} */ (command));
});

router.register('yt-append-continuation-items-action', (app, source, [action, command]) => {
  routeAction('yt-append-continuation-items-action', [command]);
  window.dispatchEvent(new CustomEvent('ytl-continuation-applied', {detail: {targetId: /** @type {!Object} */ (action).targetId}}));
});

router.register('yt-reload-continuation-items-command', (app, source, [reload, command]) => {
  const c = /** @type {!Object} */ (reload);
  if (c.targetId === 'search-page') {
    const page = /** @type {?} */ (app).pageManager_().activePage();
    if (page && page.reloadResults) page.reloadResults(c.continuationItems || []);
  } else {
    routeAction('yt-reload-continuation-items-command', [command]);
  }
  if (c.slot !== 'RELOAD_CONTINUATION_SLOT_HEADER') window.dispatchEvent(new CustomEvent('ytl-reload-applied', {detail: {targetId: c.targetId}}));
});

router.register('yt-open-popup-action', (app, source, [popup]) => {
  /** @type {?} */ (app).$['popups'].openPopup(popup);
});

router.register('yt-close-popup-action', (app, source, [types]) => {
  /** @type {?} */ (app).$['popups'].closePopups(/** @type {!Array<string>} */ (types || []));
});

router.register('yt-guide-toggle', (app) => {
  /** @type {?} */ (app).guideOpened = !/** @type {?} */ (app).guideOpened;
});

/**
 * The simulated response kind and API path of a continuation request. The
 * generated tokens don't link responses to each other, so for watch-next
 * continuations the simulated server answers by the section that asks: the
 * comment section's first request gets the reload response with the header
 * and the first threads, later ones get thread batches, and the related
 * list gets its continuation.
 * @param {!Object} command
 * @param {!Element} source
 * @return {?{kind: string, api: string, page: string}}
 */
function continuationRequest(command, source) {
  if (command.request === 'CONTINUATION_REQUEST_TYPE_SEARCH') return {kind: 'search-append', api: '/youtubei/v1/search', page: 'search'};
  if (command.request !== 'CONTINUATION_REQUEST_TYPE_WATCH_NEXT') return null;
  if (source.closest('ytl-comment-replies-renderer')) return null;
  const section = /** @type {?} */ (source.closest('ytl-item-section-renderer'));
  const data = section && section.data;
  if (!data) return null;
  if (data.targetId === 'comments-section') {
    const loaded = (data.contents || []).some(item => item.commentThreadRenderer);
    return {kind: loaded ? 'comments-append' : 'comments-reload', api: '/youtubei/v1/next', page: 'watch'};
  }
  if (data.targetId === 'watch-next-feed') return {kind: 'related-append', api: '/youtubei/v1/next', page: 'watch'};
  return null;
}

/**
 * The simulated response kind of a browse continuation: the rich grid's
 * next items.
 * @param {!Element} source
 * @return {?{kind: string, api: string, page: string}}
 */
function browseContinuationRequest(source) {
  return source.closest('ytl-rich-grid-renderer') ? {kind: 'grid-append', api: '/youtubei/v1/browse', page: 'browse'} : null;
}

router.register('yt-continuation-command', async (app, source, [command, endpoint]) => {
  const c = /** @type {!Object} */ (command);
  const request = c.request === 'CONTINUATION_REQUEST_TYPE_BROWSE' || source.closest('ytl-rich-grid-renderer') ?
    browseContinuationRequest(source) : continuationRequest(c, source);
  if (!request) return;
  networkRequestStarted(request.page, 'continuation');
  const text = await innertubeFetch(request.kind, request.api, {
    context: innertubeContext(),
    continuation: c.token,
  });
  networkRequestFinished(true);
  handleResponse(text, source, request.kind);
});

for (const name of ['yt-signal-action', 'yt-playlist-edit-action', 'yt-share-action', 'yt-show-reload-ui-command', 'yt-feedback-action']) {
  router.register(name, () => {});
}

/** Response kinds per page type, for the simulated network. */
const PAGE_KINDS = {
  'searchEndpoint': {kind: 'search-init', api: '/youtubei/v1/search', page: 'search', tag: 'ytl-search', latency: 'results'},
  'watchEndpoint': {kind: 'watch', api: '/youtubei/v1/get_watch', page: 'watch', tag: 'ytl-watch-flexy', latency: 'watch'},
  'browseEndpoint': {kind: 'browse', api: '/youtubei/v1/browse', page: 'browse', tag: 'ytl-browse', latency: 'browse'},
};

/**
 * The request payload of a navigation.
 * @param {!Object} endpoint
 * @return {!Object}
 */
function navigationPayload(endpoint) {
  const payload = {context: innertubeContext(endpoint.watchEndpoint ? endpoint.clickTrackingParams : undefined)};
  if (endpoint.searchEndpoint) payload.query = endpoint.searchEndpoint.query;
  if (endpoint.browseEndpoint) {
    payload.browseId = endpoint.browseEndpoint.browseId;
    if (endpoint.browseEndpoint.params) payload.params = endpoint.browseEndpoint.params;
  }
  if (endpoint.watchEndpoint) {
    const w = endpoint.watchEndpoint;
    payload.videoId = w.videoId;
    if (w.playerParams) payload.params = w.playerParams;
    payload.racyCheckOk = false;
    payload.contentCheckOk = false;
    payload.playbackContext = {contentPlaybackContext: {html5Preference: 'HTML5_PREF_WANTS', lactMilliseconds: '-1',
      signatureTimestamp: 20367, autoCaptionsDefaultOn: false, autonavState: 'STATE_ON'}};
  }
  return payload;
}

Polymer({
  _template: appTemplate,
  is: 'ytl-app',
  properties: {
    guideOpened: {type: Boolean, value: true, reflectToAttribute: true},
    guideData: {type: Object, value: () => makeGuideData()},
    navigating: {type: Boolean, value: false, reflectToAttribute: true},
    pageSubtype: {type: String, reflectToAttribute: true},
    isWatchPage: {type: Boolean, observer: 'isWatchPageChanged_'},
    mastheadHeight: {type: Number, value: 56},
    fullscreen: {type: Boolean, value: false},
  },
  listeners: {
    'yt-action': 'onYtAction_',
    'yt-navigate': 'onYtNavigate_',
    'yt-page-type-changed': 'onYtPageTypeChanged_',
    'yt-navigate-set-page-offset': 'onYtNavigateSetPageOffset_',
  },

  attached() {
    if (this.onPopState_) return;
    this.onPopState_ = (/** !Event */ e) => {
      const state = /** @type {?Object} */ (/** @type {!PopStateEvent} */ (e).state);
      if (state && state.endpoint) this.navigate(/** @type {!Object} */ (state.endpoint), true);
    };
    window.addEventListener('popstate', this.onPopState_);
  },

  detached() {
    if (!this.onPopState_) return;
    window.removeEventListener('popstate', this.onPopState_);
    this.onPopState_ = null;
  },

  /** @param {!CustomEvent} e */
  onYtPageTypeChanged_(e) {
    this.isWatchPage = e.detail.newPageType === 'ytl-watch-flexy';
  },

  /**
   * Restyles the app when the page type changes between watch and not
   * watch (kevlar's `isWatchPageChanged`); it does not run for other
   * changes.
   */
  isWatchPageChanged_() {
    this.updateScrollAndMasthead_();
  },

  /** @param {!CustomEvent} e */
  onYtNavigateSetPageOffset_(e) {
    window.scrollTo(0, e.detail.offset);
  },

  /**
   * Leaves the full-window scroll mode and writes the masthead and banner
   * variables (kevlar's `updateScrollAndMasthead`), one `styleSubtree` call
   * each.
   * @private
   */
  updateScrollAndMasthead_() {
    document.body.classList.remove('no-scroll');
    this.updateMastheadCssHeight_();
    this.updateNetworkStatusBannerDisplayStatus_();
  },

  /** @private */
  updateMastheadCssHeight_() {
    styleSubtree(this.hostElement, {'--ytl-masthead-height': `${this.fullscreen ? 0 : this.mastheadHeight}px`,
      '--ytl-masthead-height-absolute': `${this.mastheadHeight}px`});
  },

  /** @private */
  updateNetworkStatusBannerDisplayStatus_() {
    styleSubtree(this.hostElement, {'--ytl-network-status-banner-display': this.fullscreen ? 'none' : 'unset'});
  },

  /** @return {?} */
  pageManager_() {
    return this.$['page-manager'];
  },

  /** @param {!CustomEvent} e */
  onYtAction_(e) {
    const source = /** @type {!Element} */ (e.composedPath()[0] || e.target);
    router.handleAction(this, source, /** @type {{actionName: string, args: !Array<*>}} */ (e.detail));
  },

  /** @param {!CustomEvent} e */
  onYtNavigate_(e) {
    e.stopPropagation();
    this.navigate(/** @type {!Object} */ (e.detail.endpoint));
  },

  /**
   * @param {!Object} endpoint
   * @param {boolean=} fromHistory The navigation restores a history entry,
   *     so no entry is pushed.
   * @return {!Promise<void>}
   */
  async navigate(endpoint, fromHistory = false) {
    const kind = endpointKind(endpoint);
    const page = kind ? PAGE_KINDS[kind] : null;
    if (!page) return;
    this.navigating = true;
    this.pageManager_().prepareForNavigation(page.tag);
    this.$['progress'].start();
    startLatencyAction(page.latency);
    markWarmLoad();
    navigationStarted(page.page);
    newScreen();
    markScreenCreated();
    const url = endpointUrl(endpoint);
    networkRequestStarted(page.page, 'navigation');
    const text = await innertubeFetch(page.kind, page.api, navigationPayload(endpoint));
    networkRequestFinished(true);
    let response;
    let playerResponse = null;
    if (endpoint.watchEndpoint) {
      ({response, playerResponse} = handleWatchResponse(text, this.hostElement));
    } else {
      response = handleResponse(text, this.hostElement, page.kind);
    }
    this.handleNavigateSuccess_({page: page.page, tag: page.tag, response, playerResponse, url, endpoint, fromHistory});
  },

  /** @param {{page: string, tag: string, response: !Object, playerResponse: ?Object, url: string, endpoint: !Object, fromHistory: boolean}} pageData */
  handleNavigateSuccess_(pageData) {
    if (!pageData.fromHistory) {
      // The workload is served from a directory, so a channel's path goes
      // into the query; relative asset URLs keep working.
      let query = new URL(pageData.url, location.href).search;
      if (pageData.endpoint.watchEndpoint) query = `?v=${pageData.endpoint.watchEndpoint.videoId}`;
      else if (pageData.endpoint.browseEndpoint) query = `?c=${encodeURIComponent(pageData.url)}`;
      history.pushState({page: pageData.page, endpoint: pageData.endpoint}, '', location.pathname + query);
    }
    this.pageSubtype = pageData.page;
    pageData.onLoaded = () => this.finishNavigation_(pageData);
    this.publishPageData_(pageData);
  },

  /**
   * Runs once the page has rendered the new page data.
   * @param {!Object} pageData
   * @private
   */
  finishNavigation_(pageData) {
    this.navigating = false;
    this.$['progress'].finish();
    this.fire('yt-navigate-finish', {page: pageData.page});
    navigationFinished();
    window.dispatchEvent(new CustomEvent('ytl-navigate-finish'));
  },

  /** @param {!Object} pageData */
  publishPageData_(pageData) {
    this.hostElement.dispatchEvent(new CustomEvent('yt-page-data-fetched', {bubbles: false, composed: true, detail: {pageData}}));
  },
});

Polymer({
  is: 'ytl-page-manager',

  attached() {
    const app = this.closestApp_();
    if (app && !this.listening_) {
      this.listening_ = true;
      app.addEventListener('yt-page-data-fetched', (e) => this.onPageDataFetched_(/** @type {!CustomEvent} */ (e)));
    }
  },

  /** @return {?Element} */
  closestApp_() {
    for (let n = wrap(this.hostElement).parentNode; n; n = wrap(n).parentNode || /** @type {?} */ (n).host) {
      if (/** @type {!Element} */ (n).localName === 'ytl-app') return /** @type {!Element} */ (n);
    }
    return null;
  },

  /** @param {!CustomEvent} e */
  onPageDataFetched_(e) {
    this.flushJobs_();
    const pageData = e.detail.pageData;
    const page = this.ensurePage_(pageData.tag, webPageType(pageData.endpoint));
    const load = () => {
      page.onYtPageDataFetched(pageData);
      if (!pageData.onLoaded) return;
      if (page.whenRendered) page.whenRendered().then(pageData.onLoaded);
      else pageData.onLoaded();
    };
    load();
  },

  /**
   * Makes the page element `tag` the active one, as kevlar's
   * `setActivePage`: the old page is hidden and deactivated, the type change
   * is announced and stored, the new page is shown (created on first use;
   * hidden pages stay in the document, as on YouTube), and a page switch
   * resets the scroll offset.
   * @param {string} tag
   * @param {string} subtype
   * @return {?}
   */
  ensurePage_(tag, subtype) {
    const el = wrap(this.hostElement);
    let page = null;
    for (let n = el.firstElementChild; n; n = wrap(n).nextElementSibling) if (n.localName === tag) page = n;
    if (!page) {
      page = document.createElement(tag);
      el.appendChild(page);
    }
    const old = this.active_;
    if (old !== page) {
      if (old) {
        old.toggleAttribute('hidden', true);
        /** @type {?} */ (old).active = false;
        old.removeAttribute('role');
      }
      this.active_ = page;
      if (old) {
        this.hostElement.dispatchEvent(new CustomEvent('yt-page-type-changed', {bubbles: true, composed: true,
          detail: {oldPageType: old.localName, newPageType: tag, newPageSubtype: subtype}}));
      }
      appStore.dispatch({type: 'SET_SHARED_CURRENT_PAGE_TYPE', payload: tag});
      appStore.dispatch({type: 'SET_SHARED_CURRENT_PAGE_SUB_TYPE', payload: subtype});
      page.toggleAttribute('hidden', false);
      /** @type {?} */ (page).active = true;
      page.setAttribute('role', 'main');
      if (old) {
        this.hostElement.dispatchEvent(new CustomEvent('yt-navigate-set-page-offset', {bubbles: true, composed: true,
          detail: {page, offset: 0}}));
      }
    }
    return page;
  },

  /**
   * Starts a navigation's page work, as kevlar's `onYtNavigateStart` does:
   * the destination page is prepared (created and attached hidden, as
   * `preparePage` does) and the active page's dispose jobs are queued, both
   * as priority 1 scheduler jobs that run in the next frame. The simulated
   * network answers in the next task, usually before that frame, so the jobs
   * that have not run when the page data arrives run first in
   * `onPageDataFetched_`, ahead of the response handling as they are on
   * YouTube, for any destination page.
   * @param {string} tag The destination page's tag.
   */
  prepareForNavigation(tag) {
    this.flushJobs_();
    const page = this.activePage();
    const jobs = [() => this.preparePage_(tag)].concat((page && page.pageDisposeJobs) || []);
    this.disposeJobs_ = jobs.map((job, i) => {
      const entry = {job, id: 0, dispose: i > 0};
      if (entry.dispose) countDisposeJob('queued');
      entry.id = schedule(() => {
        entry.id = 0;
        if (entry.dispose) countDisposeJob('frame');
        job();
      }, Priority.HIGH);
      return entry;
    });
  },

  /**
   * Creates the page element of `tag` and attaches it, hidden unless it is
   * the active page.
   * @param {string} tag
   * @private
   */
  preparePage_(tag) {
    const el = wrap(this.hostElement);
    for (let n = el.firstElementChild; n; n = wrap(n).nextElementSibling) if (n.localName === tag) return;
    const page = document.createElement(tag);
    page.toggleAttribute('hidden', true);
    el.appendChild(page);
  },

  /** @private */
  flushJobs_() {
    const pending = this.disposeJobs_ || [];
    this.disposeJobs_ = [];
    for (const entry of pending) {
      if (!entry.id) continue;
      cancel(entry.id);
      if (entry.dispose) countDisposeJob('flushed');
      entry.job();
    }
  },

  /** @return {?} */
  activePage() {
    return this.active_ || null;
  },
});
