/**
 * @fileoverview DOM access to an element's own content, for element code
 * that renders into its host. Insertions go into the host's shadow root,
 * or into the host itself if it has none, and the inserted subtree is
 * rescoped to the host's `style-scope` class; removals strip it again.
 * Element hosts are scoped by their tag name, other nodes keep the scope
 * they already have.
 */
import {wrap} from '@polymer/polymer/lib/utils/wrap.js';
import {flag} from './flags.js';

/**
 * The scope class of `el`: the class after `style-scope`.
 * @param {*} el
 * @return {?string}
 */
export function scopeOf(el) {
  if (!(el instanceof Element)) return null;
  const classes = Array.from(el.classList);
  const i = classes.indexOf('style-scope');
  return i > -1 && i + 1 < classes.length ? classes[i + 1] : null;
}

/**
 * The scope that content inserted into `host` gets.
 * @param {!Node} host
 * @return {?string}
 */
function scopeForContentOf(host) {
  if (!(host instanceof HTMLElement)) return null;
  const tag = host.$$ || host.polymerController ? host.tagName.toLowerCase() : null;
  return tag || scopeOf(host);
}

/**
 * @param {!Node} node
 * @return {!Set<!Node>}
 */
function childrenOf(node) {
  return new Set([...(node.children || []), ...(node.__shady_native_children || []), ...(node.__shady_children || [])]);
}

/**
 * Gives `node` and its descendants whose scope is `oldScope` the scope
 * `scope`.
 * @param {!Node} node
 * @param {string} scope
 * @param {?string} oldScope
 * @return {!Node}
 */
function rescope(node, scope, oldScope) {
  if (node instanceof HTMLElement && scopeOf(node) === oldScope) {
    const classes = Array.from(node.classList);
    const i = classes.indexOf('style-scope');
    if (i === -1) {
      node.classList.add('style-scope');
      node.classList.add(scope);
    } else if (i + 1 < node.classList.length) {
      node.classList.replace(node.classList[i + 1], scope);
    }
  }
  if (node instanceof HTMLElement || node instanceof DocumentFragment) {
    for (const child of childrenOf(node)) rescope(child, scope, oldScope);
  }
  return node;
}

/**
 * Removes the scope `scope` from `node` and its descendants.
 * @param {!Node} node
 * @param {string} scope
 * @return {!Node}
 */
function unscope(node, scope) {
  if (node instanceof HTMLElement && scopeOf(node) === scope) {
    const classes = Array.from(node.classList);
    const i = classes.indexOf('style-scope');
    if (i !== -1 && i + 1 < node.classList.length) node.classList.remove('style-scope', node.classList[i + 1]);
  }
  if (node instanceof HTMLElement || node instanceof DocumentFragment) {
    for (const child of Array.from(node.children)) unscope(child, scope);
  }
  return node;
}

/**
 * Restricts each compound selector in `selector` to the scope `scope`.
 * @param {string} selector
 * @param {?string} scope
 * @return {string}
 */
function scopeSelector(selector, scope) {
  if (!scope) return selector;
  return selector.split(',').map(part => part.trim().replace(/[^a-z]*[^\s]+/g, m => m + '.style-scope.' + scope)).join(', ');
}

/**
 * The node that insertions and queries on `host`'s content run on: its
 * root (a stock element's shady root), its shadow root (a ShadyDOM shadow
 * root on PolySi hosts) or the host itself.
 * @param {!Node} host
 * @return {!Node}
 */
function contentNodeOf(host) {
  const h = /** @type {?} */ (host);
  return h.root || h.shadowRoot || h.__shady_native_shadowRoot || h.__shady_shadowRoot || host;
}

/**
 * The class whose node methods apply to `node`. ShadyDOM replaces
 * `window.ShadowRoot` with its own class, so they run ShadyDOM's logical
 * tree operations on a shady root.
 * @param {!Node} node
 * @return {!Object}
 */
function protoOf(node) {
  if (node instanceof ShadowRoot) return ShadowRoot.prototype;
  if (node instanceof DocumentFragment) return DocumentFragment.prototype;
  if (node instanceof Document) return Document.prototype;
  return HTMLElement.prototype;
}

/**
 * DOM access to the content of one host. `host` is the host's ShadyDOM
 * wrapper, and `root` the node its read-only properties and `textContent`
 * use: the host's ShadyDOM shadow root, a stock element's `root`, or the
 * wrapper.
 */
export class HostDom {
  /** @param {!Node} node A host, or a shadow root. */
  constructor(node) {
    const n = /** @type {?} */ (node);
    if (node instanceof ShadowRoot) {
      /** @type {!Node} */
      this.host = /** @type {!Node} */ (wrap(n.host));
      /** @type {!Node} */
      this.root = node;
    } else if (n.$$) {
      this.host = /** @type {!Node} */ (wrap(node));
      this.root = n.root != null ? n.root : this.host;
    } else if (n.polymerController) {
      this.host = /** @type {!Node} */ (wrap(node));
      const shadow = /** @type {?} */ (this.host).shadowRoot;
      this.root = shadow != null ? shadow : this.host;
    } else {
      this.host = this.root = /** @type {!Node} */ (wrap(node));
    }
  }

  /**
   * @return {!Node}
   * @private
   */
  element_() {
    const h = /** @type {?} */ (this.host);
    return h.node || h;
  }

  /**
   * @param {!Node} node
   * @return {!Node}
   */
  appendChild(node) {
    if (!flag('enable_shadydom_free_scoped_node_methods')) return this.root.appendChild(node);
    const el = this.element_();
    const scope = scopeForContentOf(el);
    const oldScope = scopeOf(node);
    const target = contentNodeOf(el);
    return protoOf(target).appendChild.call(target, scope ? rescope(node, scope, oldScope) : node);
  }

  /**
   * @param {!Node} node
   * @param {?Node} ref
   * @return {!Node}
   */
  insertBefore(node, ref) {
    if (!flag('enable_shadydom_free_scoped_node_methods')) return this.root.insertBefore(node, ref);
    const el = this.element_();
    const scope = scopeForContentOf(el);
    const oldScope = scopeOf(node);
    const target = contentNodeOf(el);
    return protoOf(target).insertBefore.call(target, scope ? rescope(node, scope, oldScope) : node, ref);
  }

  /**
   * @param {!Node} node
   * @return {!Node}
   */
  removeChild(node) {
    if (!flag('enable_shadydom_free_scoped_node_methods')) return this.root.removeChild(node);
    const el = this.element_();
    const scope = scopeForContentOf(el);
    const target = contentNodeOf(el);
    return protoOf(target).removeChild.call(target, scope ? unscope(node, scope) : node);
  }

  /**
   * @param {string} name
   * @param {string} value
   */
  setAttribute(name, value) {
    /** @type {?} */ (this.host).setAttribute(name, value);
  }

  /** @param {string} name */
  removeAttribute(name) {
    /** @type {?} */ (this.host).removeAttribute(name);
  }

  /** @return {string} */
  get textContent() {
    return /** @type {string} */ (this.root.textContent);
  }

  /** @param {string} text */
  set textContent(text) {
    this.root.textContent = text;
  }

  /** @return {!NodeList<!Node>} */
  get childNodes() {
    return this.root.childNodes;
  }

  /**
   * The first element of the host's content that matches `selector`, with
   * the selector restricted to the host's scope.
   * @param {string} selector
   * @return {?Element}
   */
  querySelector(selector) {
    if (!flag('enable_shadydom_free_scoped_query_methods')) return /** @type {?} */ (this.root).querySelector(selector);
    const el = this.element_();
    const scoped = scopeSelector(selector, scopeForContentOf(el));
    if (flag('sunnydom_native_scoped_query_selectors')) return el.querySelector(scoped);
    const root = contentNodeOf(el);
    return protoOf(root).querySelector.call(root, scoped);
  }

  /**
   * @param {string} selector
   * @return {!Array<!Element>}
   */
  querySelectorAll(selector) {
    if (!flag('enable_shadydom_free_scoped_query_methods')) return Array.from(/** @type {?} */ (this.root).querySelectorAll(selector));
    const el = this.element_();
    const scoped = scopeSelector(selector, scopeForContentOf(el));
    if (flag('sunnydom_native_scoped_query_selectors')) return Array.from(el.querySelectorAll(scoped));
    const root = contentNodeOf(el);
    return Array.from(protoOf(root).querySelectorAll.call(root, scoped));
  }

  /** @return {?Node} */
  get firstChild() {
    return this.root.firstChild;
  }

  /** @return {?Node} */
  get lastChild() {
    return this.root.lastChild;
  }

  /** @return {?Element} */
  get firstElementChild() {
    return /** @type {?} */ (this.root).firstElementChild;
  }

  /** @return {?Element} */
  get lastElementChild() {
    return /** @type {?} */ (this.root).lastElementChild;
  }
}

/**
 * A new `HostDom` for `node`, as kevlar's `_.ME` allocates one per call.
 * `options.ignoreOwnerDocument` gives `node` an `ownerDocument` getter that
 * returns the main document.
 * @param {!Node|!HostDom} node
 * @param {{ignoreOwnerDocument: (boolean|undefined)}=} options
 * @return {!HostDom}
 */
export function hostDom(node, options = undefined) {
  if (node instanceof HostDom) return node;
  if (options && options.ignoreOwnerDocument && !Object.getOwnPropertyDescriptor(node, 'ownerDocument')) {
    Object.defineProperty(node, 'ownerDocument', {get: () => window.document});
  }
  return new HostDom(/** @type {!Node} */ (node));
}

/**
 * Sets custom properties on `host` through ShadyCSS, which also restyles
 * the subtree (`_.jd` in kevlar).
 * @param {!Element} host
 * @param {!Object<string, string>} props
 */
export function styleSubtree(host, props) {
  if (window.ShadyCSS) window.ShadyCSS.styleSubtree(host, props);
}
