/**
 * @fileoverview PolySi hosts: the custom elements that stand for PolySi
 * elements in the DOM.
 *
 * A host's constructor creates its controller and makes the host look like
 * the Polymer element: for every instance it computes the list of
 * properties to forward, defines an own accessor for each that checks the
 * access logging and forwards to the controller, defines an own wrapper
 * closure for each public method of the element and its behaviors, and
 * converts the observed attribute names to property names. The Polymer
 * API is not forwarded, apart from a few property-effects methods. This
 * host class (registration mode 2) defines no lifecycle callbacks; the
 * patched DOM methods in lifecycle.js call the controller's
 * `connectedCallback` and `disconnectedCallback`.
 *
 * Mode 0 hosts are custom element classes with their own lifecycle
 * callbacks. Their property accessors are defined once, on the class
 * prototype; methods are forwarded per instance, and the controller's
 * public fields at `ready`.
 */
import {renderPolySiHost} from '../vm/render.js';
import {LegacyElementMixin} from '@polymer/polymer/lib/legacy/legacy-element-mixin.js';
import {camelToDash, dashToCamel} from '../case.js';
import {ControllerBase, EXTRA_METHODS, createControllerClass, setConstructingHost} from './controller.js';
import {createSignalControllerClass} from './signal-controller.js';
import {instrumentField, instrumentMethod, isAccessLoggingEnabled, isIgnoredName, logPropertyAccess} from './logging.js';

/**
 * @typedef {{
 *   tag: string,
 *   ctor: function(new:Object),
 *   info: !Object,
 *   methods: ?Array<string>,
 *   signal: boolean,
 *   protoForwarded: boolean,
 *   observedAttributes: !Array<string>,
 *   loggedHostProps: boolean,
 * }}
 */
let TypeInfo;

/** @type {!Map<string, !TypeInfo>} */
const types = new Map();

/**
 * Names that are never forwarded as methods: the legacy element API, and
 * the names PolySi itself manages.
 */
const NOT_FORWARDED = new Set(['is', 'hostElement', 'root', 'rootPath', 'importPath', 'inject', 'behaviors', 'properties', 'provide',
  'hostAttributes', 'stampDom', 'allowedPropsFromBehaviors']
    .concat(Object.getOwnPropertyNames(LegacyElementMixin(ControllerBase).prototype)));

/** Polymer state that every host exposes read-only. */
const READ_ONLY_STATE = new Set(['__dataEnabled', '__dataHasAccessor', '__dataPending', '__isPropertyEffectsClient', '__readOnly']);

/** State of signal-schema controllers that every host exposes read-only. */
const SIGNAL_READ_ONLY_STATE = new Set(['__dataHasAccessor', '__isPropertyEffectsClient', '$', 'hostElement', 'isAttached', 'observers', 'properties', 'useSignals']);

/**
 * Info keys that signal-schema hosts do not forward as properties. Their
 * hosts forward the controller's other fields without a name filter.
 */
const SIGNAL_NOT_FORWARDED = new Set(['is', 'root', 'rootPath', 'importPath', 'inject', 'hostAttributes', 'stampDom', '_template',
  'didCallReady', 'signalProxy']);

/**
 * Functions of the controller base class that every signal-schema host
 * forwards, with `constructor` (every behaviour set has a class-based
 * behaviour). Build-time declaration hooks of ours are not forwarded.
 */
const SIGNAL_BASE_METHODS = ['_enableProperties', '_setPendingProperty', '_setPendingPropertyOrPath', 'fire', 'get', 'linkPaths', 'listen',
  'notifyPath', 'notifySplices', 'pop', 'push', 'set', 'setProperties', 'splice', 'unlinkPaths', 'unlisten', 'unshift', 'constructor'];
const SIGNAL_SKIPPED_METHODS = new Set(['addReactiveSchema', 'registerDeclarations_', 'initFields_', '_template']);

/** Attributes that legacy hosts observe besides their declared properties. */
const OBSERVED_EXTRA = ['disabled', 'disable-upgrade'];

/**
 * @param {string} name
 * @return {boolean}
 */
function isExcluded(name) {
  return NOT_FORWARDED.has(name) || name.startsWith('__compute__');
}

/**
 * Whether `name` is public: no leading or trailing underscore.
 * @param {string} name
 * @return {boolean}
 */
function isPublicName(name) {
  return name[0] !== '_' && name[name.length - 1] !== '_';
}

/**
 * Defines an accessor on `host` that forwards `name` to the controller,
 * unless the host already has an own property of that name. `host` is a
 * host element, or the prototype of mode 0 hosts.
 * @param {!Object} host
 * @param {string} name
 * @param {boolean} declared Whether Polymer manages the property.
 * @param {boolean} readOnly
 * @param {boolean=} signal Whether the controller is a signal-schema one,
 *     whose properties are assigned directly.
 */
function forwardProperty(host, name, declared, readOnly, signal = false) {
  if (host.hasOwnProperty(name)) return;
  Object.defineProperty(host, name, {
    configurable: true,
    enumerable: true,
    get() {
      const tag = (this.is != null ? this.is : this.tagName).toLowerCase();
      const ctrl = this.polymerController;
      if (!ctrl) return undefined;
      const status = this.loggingStatus;
      if (!status.isDeclarativeExternal) logPropertyAccess(tag, name, 'PROPERTY_ACCESS_GET_EXTERNAL');
      status.isExternalGet = true;
      status.bypassProxyController = true;
      const value = ctrl[name];
      status.isExternalGet = false;
      status.bypassProxyController = false;
      return value;
    },
    set(value) {
      if (readOnly) return;
      const tag = (this.is != null ? this.is : this.tagName).toLowerCase();
      const ctrl = this.polymerController;
      if (!ctrl) return;
      const status = this.loggingStatus;
      if (!status.isDeclarativeExternal) logPropertyAccess(tag, name, 'PROPERTY_ACCESS_SET_EXTERNAL_IMPERATIVE');
      status.currentExternalSet = name;
      status.bypassProxyController = true;
      if (signal) ctrl[name] = value;
      else if (ctrl[name] !== value) {
        if (declared) ctrl.setProperties({[name]: value});
        else ctrl[name] = value;
      }
      status.currentExternalSet = undefined;
      status.bypassProxyController = false;
    },
  });
}

/**
 * Defines a wrapper on `host` that forwards calls of `name` to the
 * controller.
 * @param {!HTMLElement} host
 * @param {string} name
 * @param {?Function=} method The method to call; by default the
 *     controller's method of that name, looked up per call.
 */
function forwardMethod(host, name, method) {
  const ctrl = host.polymerController;
  host[name] = function(...args) {
    const status = host.loggingStatus;
    status.currentExternalCall = name;
    status.bypassProxyController = true;
    const tag = (host.is != null ? host.is : host.tagName).toLowerCase();
    logPropertyAccess(tag, name, 'PROPERTY_ACCESS_CALL_EXTERNAL');
    const fn = method != null ? method : ctrl[name];
    const result = fn == null ? undefined : fn.call.apply(fn, [ctrl].concat(args));
    status.currentExternalCall = undefined;
    status.bypassProxyController = false;
    return result;
  };
}

/**
 * The element's own method names to forward: the public methods of its
 * behaviors and of its info object, except declared properties and the
 * legacy element API. Computed once per type.
 * @param {!TypeInfo} type
 * @return {!Array<string>}
 */
function getInitialMethods(type) {
  if (type.methods) return type.methods;
  const declared = type.ctor.psSchema.properties;
  const names = [];
  const seen = new Set();
  if (type.signal) for (const name of SIGNAL_BASE_METHODS) seen.add(name), names.push(name);
  for (const source of type.ctor.psBehaviors.concat([type.info])) {
    for (const name of Object.getOwnPropertyNames(source)) {
      if (seen.has(name) || name in declared) continue;
      if (type.signal ? SIGNAL_SKIPPED_METHODS.has(name) : isExcluded(name)) continue;
      const desc = Object.getOwnPropertyDescriptor(source, name);
      if (!desc || typeof desc.value !== 'function') continue;
      seen.add(name);
      if (type.signal || isPublicName(name)) names.push(name);
    }
  }
  type.methods = names;
  return names;
}

/**
 * The property names to forward when the host is constructed: every
 * declared property, the info object's other public values, and Polymer's
 * read-only state. Built for each instance.
 * @param {!TypeInfo} type
 * @return {!Array<!Array<*>>} [name, declared, readOnly] triples.
 */
function getPropsToForwardBeforeRegister(type) {
  const declared = type.ctor.psSchema.properties;
  const out = [];
  const seen = new Set();
  for (const name of Object.keys(declared)) {
    seen.add(name);
    out.push([name, true, !!declared[name].readOnly]);
  }
  for (const name of Object.getOwnPropertyNames(type.info)) {
    if (seen.has(name) || !isPublicName(name) || (type.signal ? SIGNAL_NOT_FORWARDED.has(name) : isExcluded(name))) continue;
    const desc = Object.getOwnPropertyDescriptor(type.info, name);
    if (desc && typeof desc.value === 'function') continue;
    seen.add(name);
    out.push([name, false, false]);
  }
  for (const name of type.signal ? SIGNAL_READ_ONLY_STATE : READ_ONLY_STATE) {
    if (!seen.has(name)) out.push([name, false, true]);
  }
  return out;
}

/**
 * Forwards the controller's public instance fields that the host doesn't
 * have yet. Runs once, when the controller is about to become ready.
 * @param {!HTMLElement} host
 * @param {!Object} ctrl
 * @param {boolean} signal
 */
function forwardDynamicProps(host, ctrl, signal) {
  const tag = host.localName;
  const names = [];
  for (const [name, value] of Object.entries(ctrl)) {
    if (host.hasOwnProperty(name)) continue;
    if (signal) {
      if (SIGNAL_NOT_FORWARDED.has(name)) continue;
    } else if (typeof value === 'function' || !isPublicName(name) || isExcluded(name)) {
      continue;
    }
    names.push(name);
    if (isAccessLoggingEnabled(tag)) instrumentField(ctrl, name);
  }
  for (const name of names) {
    forwardProperty(host, name, false, false, signal);
    if (isAccessLoggingEnabled(tag) && !isIgnoredName(name)) instrumentField(ctrl, name);
  }
}

/**
 * `attr` to property name, for each observed attribute; built per instance.
 * @param {!Array<string>} observed
 * @return {!Object<string, string>}
 */
function attributeMap(observed) {
  const map = {};
  for (const attr of observed) map[attr] = dashToCamel(attr);
  return map;
}

/**
 * Constructs a legacy controller for `host`. The class prototype's
 * `hostElement` is set to each new host, as kevlar does.
 * @param {!HTMLElement} host
 * @param {!TypeInfo} type
 * @return {!Object}
 */
function constructLegacyController(host, type) {
  setConstructingHost(host);
  type.ctor.prototype.hostElement = host;
  let ctrl;
  try {
    ctrl = new type.ctor();
  } finally {
    setConstructingHost(null);
  }
  ctrl.__dataAttributes = attributeMap(type.observedAttributes);
  return ctrl;
}

/**
 * Runs `beforeReady` before the controller's `ready`, and the access
 * logging check after it. With logging on, the first `ready` of a type
 * records the template's host properties.
 * @param {!Object} ctrl
 * @param {!TypeInfo} type
 * @param {function()} beforeReady
 */
function wrapReady(ctrl, type, beforeReady) {
  const ready = ctrl.ready;
  ctrl.ready = () => {
    beforeReady();
    ready.call(ctrl);
    if (isAccessLoggingEnabled(type.tag) && !type.loggedHostProps) {
      const hostProps = ctrl.__templateInfo && ctrl.__templateInfo.hostProps;
      if (hostProps) {
        for (const name of Object.keys(hostProps)) logPropertyAccess(type.tag, name, 'PROPERTY_ACCESS_GET_INTERNAL');
      }
      type.loggedHostProps = true;
    }
  };
}

/**
 * Creates the controller for `host` and installs the forwarding.
 * @param {!HTMLElement} host
 * @return {!Object}
 */
export function createController(host) {
  const type = /** @type {!TypeInfo} */ (types.get(host.localName));
  host.is = type.tag;
  host.usePatchedLifecycles = true;
  host.lifecycleIsConnected = false;
  host.loggingStatus = {};
  const ctrl = type.signal ? new type.ctor(host) : constructLegacyController(host, type);
  host.polymerController = ctrl;
  const observed = type.observedAttributes;
  ctrl.observedAttributes = observed;
  const attributeNames = type.signal ? attributeMap(observed) : ctrl.__dataAttributes;
  let didForward = false;
  const forwardBeforeReady = () => {
    if (!didForward) {
      forwardDynamicProps(host, ctrl, type.signal);
      didForward = true;
    }
  };
  if (type.signal) {
    ctrl.beforeReady = () => {
      if (host.hasAttributes()) {
        for (const attr of Array.from(host.attributes)) {
          if (attr.name in attributeNames) ctrl.attributeChangedCallback(attr.name, null, attr.value);
        }
      }
      forwardBeforeReady();
    };
  } else {
    wrapReady(ctrl, type, forwardBeforeReady);
    for (const [name, method] of ctrl.getExtraMethodsToForward()) forwardMethod(host, name, method);
  }
  const tag = host.localName;
  for (const name of getInitialMethods(type)) {
    forwardMethod(host, name);
    if (isAccessLoggingEnabled(tag) && !isIgnoredName(name)) instrumentMethod(ctrl, name);
  }
  for (const [name, declared, readOnly] of getPropsToForwardBeforeRegister(type)) {
    forwardProperty(host, /** @type {string} */ (name), /** @type {boolean} */ (declared), /** @type {boolean} */ (readOnly), type.signal);
    if (isAccessLoggingEnabled(tag) && !isIgnoredName(/** @type {string} */ (name))) instrumentField(ctrl, /** @type {string} */ (name));
  }
  // Kevlar wraps the controller in a logging proxy when logging is on.
  if (isAccessLoggingEnabled(tag)) host.polymerController = new Proxy(ctrl, {});
  if (!type.signal && host.hasAttributes()) {
    for (const attr of Array.from(host.attributes)) {
      if (attr.name in attributeNames) ctrl._attributeToProperty(attr.name, attr.value);
    }
  }
  return ctrl;
}

/** The base class of mode 2 PolySi hosts. */
class PolySiHost extends HTMLElement {
  constructor() {
    super();
    renderPolySiHost(this, () => createController(this));
  }
}

/**
 * Creates the controller of a mode 0 host and forwards its methods. The
 * property accessors live on the host class's prototype; they are defined
 * when the first instance is constructed.
 * @param {!HTMLElement} host
 * @param {!TypeInfo} type
 * @param {!Object} proto The host class's prototype.
 */
function createModeZeroController(host, type, proto) {
  const tag = host.localName;
  host.didForwardDynamicProps = false;
  host.loggingStatus = {};
  if (!type.protoForwarded) {
    for (const [name, declared, readOnly] of getPropsToForwardBeforeRegister(type)) {
      forwardProperty(proto, /** @type {string} */ (name), /** @type {boolean} */ (declared), /** @type {boolean} */ (readOnly));
    }
    type.protoForwarded = true;
  }
  const ctrl = constructLegacyController(host, type);
  host.inst = ctrl;
  wrapReady(ctrl, type, () => {
    if (!host.didForwardDynamicProps) {
      /** @type {?} */ (host).forwardDynamicProps();
      host.didForwardDynamicProps = true;
    }
  });
  // Kevlar wraps the controller in a logging proxy when logging is on.
  host.controllerProxy = isAccessLoggingEnabled(tag) ? new Proxy(ctrl, {}) : ctrl;
  /** @type {?} */ (host).forwardMethods();
}

/**
 * Defines the host class of a mode 0 element: a custom element whose
 * lifecycle callbacks are its own, with the forwarded accessors on its
 * prototype.
 * @param {!TypeInfo} type
 * @return {function(new:HTMLElement)}
 */
function defineModeZeroHost(type) {
  /** @suppress {checkTypes} */
  class ModeZeroHost extends HTMLElement {
    constructor() {
      super();
      createModeZeroController(this, type, ModeZeroHost.prototype);
    }

    /** @return {!Array<string>} */
    static get observedAttributes() {
      return type.observedAttributes;
    }

    forwardMethods() {
      const ctrl = this.inst;
      const tag = this.localName;
      for (const [name, method] of ctrl.getExtraMethodsToForward()) {
        this[name] = (...args) => method.call.apply(method, [ctrl].concat(args));
      }
      for (const name of getInitialMethods(type)) {
        forwardMethod(this, name);
        if (isAccessLoggingEnabled(tag) && !isIgnoredName(name)) instrumentMethod(ctrl, name);
      }
    }

    forwardDynamicProps() {
      forwardDynamicProps(this, this.inst, false);
    }

    connectedCallback() {
      this.inst.connectedCallback();
      this.inst.isConnected = true;
    }

    disconnectedCallback() {
      this.inst.disconnectedCallback();
      this.inst.isConnected = false;
    }

    /**
     * @param {string} name
     * @param {?string} oldValue
     * @param {?string} newValue
     */
    attributeChangedCallback(name, oldValue, newValue) {
      this.inst.attributeChangedCallbackWrapper(name, oldValue, newValue);
    }

    /** @return {!Object} */
    get polymerController() {
      return this.controllerProxy;
    }
  }
  Object.defineProperty(ModeZeroHost.prototype, 'is', {configurable: true, enumerable: true, get: () => type.tag});
  return ModeZeroHost;
}

/**
 * Defines a PolySi element from a Polymer info object.
 * @param {!Object} info
 * @param {boolean} signal Whether the element gets a signal-schema
 *     controller instead of a legacy one.
 * @param {number=} mode The registration mode of a legacy element: 2 (the
 *     default) builds the host per instance; 0 makes it a custom element
 *     class with prototype accessors and its own lifecycle callbacks.
 * @param {!Array<string>|undefined=} allowedProps The registration option.
 * @return {function(new:Object, ...?)} The controller class.
 */
export function definePolySiElement(info, signal, mode = 2, allowedProps = undefined) {
  const ctor = signal ? createSignalControllerClass(info) : createControllerClass(info, allowedProps);
  const observedAttributes = signal ? /** @type {!Array<string>} */ (ctor.observedAttributes)
      : OBSERVED_EXTRA.concat(Object.keys(ctor.psSchema.properties).map(camelToDash));
  const type = /** @type {!TypeInfo} */ ({tag: info.is, ctor, info, methods: null, signal, protoForwarded: false, observedAttributes,
    loggedHostProps: false});
  types.set(info.is, type);
  customElements.define(info.is, !signal && mode === 0 ? defineModeZeroHost(type) : class extends PolySiHost {});
  return ctor;
}

/**
 * @param {?Element} el
 * @return {boolean}
 */
export function isPolySiHost(el) {
  return !!el && !!el.usePatchedLifecycles;
}
