/**
 * @fileoverview The signal proxy of a signal-schema controller or of a
 * repeat or if instance. It resolves any key of its model to a path store
 * on first use: the store is seeded with the model's current value (a
 * field, or a method from the prototype), and an own accessor on the model
 * then reads and writes through it. Effects created through the proxy are
 * owned by it.
 */
import {createPolySiOwner, disposeOwner, runWithOwner} from '../vm/owner.js';
import {effect, runUntracked} from '../vm/effect.js';
import {PathStore} from './store.js';
import {logPropertyAccess} from './logging.js';

/**
 * Splits a Polymer-style path into components.
 * @param {string|!Array<string|number>} path
 * @return {!Array<string>}
 */
export function toPath(path) {
  return Array.isArray(path) ? path.map(String) : String(path).split('.');
}

export class SignalProxy {
  /**
   * @param {!Object} model
   * @param {?function(string, !SignalProxy): ?PathStore} resolver Supplies
   *     stores for keys the model doesn't own, as repeat instances do.
   * @param {?SignalProxy=} parent
   */
  constructor(model, resolver, parent) {
    /** @const {!Object} */
    this.model = model;
    /** @const {?function(string, !SignalProxy): ?PathStore} */
    this.resolver = resolver;
    /** @const {!Map<string, !PathStore>} */
    this.signalCache = new Map();
    /** @const {!Array<!SignalProxy>} */
    this.childSignalProxies = [];
    /** @const {!Object} */
    this.owner = createPolySiOwner();
    /** @type {boolean} */
    this.isDisposed = false;
    if (parent) parent.childSignalProxies.push(this);
  }

  /**
   * The store for `key`, created on first use.
   * @param {string} key
   * @return {!PathStore}
   */
  resolve(key) {
    let store = this.signalCache.get(key);
    if (store) return store;
    if (this.resolver) store = this.resolver(key, this);
    if (!store) store = new PathStore(key, runUntracked(() => this.model[key]));
    this.signalCache.set(key, store);
    const proxy = this;
    const tag = this.model.is || 'model';
    const tagOf = () => tag;
    Object.defineProperty(this.model, key, {
      configurable: true,
      enumerable: true,
      get() {
        if (proxy.model.hostElement && proxy.model.hostElement.loggingStatus) logPropertyAccess(tagOf(), key, 'PROPERTY_ACCESS_GET_INTERNAL');
        return store.getWithPath([]);
      },
      set(value) {
        if (proxy.model.hostElement && proxy.model.hostElement.loggingStatus) logPropertyAccess(tagOf(), key, 'PROPERTY_ACCESS_SET_INTERNAL');
        proxy.setWithPath([key], value);
      },
    });
    return store;
  }

  /**
   * @param {!Array<string>} path
   * @param {*} value
   */
  setWithPath(path, value) {
    this.resolve(path[0]).setWithPath(path.slice(1), value);
  }

  /**
   * @param {!Array<string>} path
   * @return {*}
   */
  getWithPath(path) {
    return this.resolve(path[0]).getWithPath(path.slice(1));
  }

  /**
   * @param {!Array<string>} path
   * @param {{value: *}=} options
   */
  notifyPath(path, options) {
    this.resolve(path[0]).notifyPath(path.slice(1), options);
  }

  /**
   * Creates an effect owned by this proxy.
   * @param {function()} fn
   * @param {string=} name
   * @return {{run: function(), destroy: function()}}
   */
  effect(fn, name) {
    return runWithOwner(this.owner, () => effect(fn, name));
  }

  /**
   * Runs `fn` untracked, with this proxy as the owner.
   * @template T
   * @param {function(): T} fn
   * @return {T}
   */
  runUntracked(fn) {
    return runWithOwner(this.owner, () => runUntracked(fn));
  }

  dispose() {
    if (this.isDisposed) return;
    this.isDisposed = true;
    for (const child of this.childSignalProxies) child.dispose();
    disposeOwner(this.owner);
  }
}
